window.__RF_DATA=window.__RF_DATA||{};window.__RF_DATA["khalwaYear"]="{\"v\":2,\"weeks\":[[\"نبدأ السنة بالشكر ونصل إلى المذود\",\"شكرٌ وصلاةٌ وإصغاءٌ وتوبةٌ ومحبةٌ، تقودنا كلها إلى ميلاد المسيح.\"],[\"فضائل التلميذ في أول الطريق\",\"الصبر والاتضاع والرجاء والفرح: ملامح حياةٍ قريبة من الله.\"],[\"من الخلوة إلى الأردن\",\"غفرانٌ وطاعةٌ واستعدادٌ، ثم نقف مع المسيح في معموديته.\"],[\"إيمانٌ يعمل\",\"لسانٌ محفوظ، وصلاةٌ بلا ملل، ورحمةٌ وخدمةٌ وثباتٌ في التجارب.\"],[\"طمأنينة تحت عناية الله\",\"راحةٌ في الرب، ووداعةٌ، وبيتٌ مبنيٌّ عليه، وشجاعةٌ تنمو.\"],[\"قلبٌ نقيٌّ يخدم ويسبّح\",\"رجاءٌ في الضعف، وإصغاءٌ للآخرين، وذبيحةُ تسبيحٍ وجهادٌ روحي.\"],[\"عطش القلب ولقاء الهيكل\",\"عطشٌ إلى الله، وحريةٌ ومحبةٌ عملية، ولقاءٌ مع السيد في الهيكل.\"],[\"جماعةٌ مصالَحة تخاف الرب\",\"جسدٌ واحد، وميراثٌ سماوي، ومصالحةٌ وسهرٌ وعطاءٌ بفرح.\"],[\"نهضةٌ وتوبة\",\"نقوم بعد السقوط، ونقتني القناعة، ونفتدي الوقت، ونقترب بقلبٍ منسحق.\"],[\"كلمةٌ تغذّي وصليبٌ ينتصر\",\"الكلمة غذاءٌ، والشهادة والإيمان والمحبة تتوّجها قوةُ الصليب.\"],[\"الراعي الذي يعطي الحياة\",\"رجاءٌ في الألم، ولصُّ اليمين، وصوتُ الراعي، وخبزُ الحياة، والقيامة.\"],[\"نورٌ وبيتٌ ودعوة\",\"نورُ المسيح في الخفاء وفي البيت، وصلاةٌ ربانيةٌ ودعوةٌ مختارة.\"],[\"سلامٌ يبدأ بالتوبة\",\"سلامٌ داخلي، ونقاءٌ، وسرُّ الاعتراف، ووحدةُ الكنيسة، وصدقٌ في الكلمة.\"],[\"من الخوف إلى الثقة\",\"نُلحّ في الصلاة، ونلقي همَّنا، ونتحرر من الخوف، ونطيع كما أطاعت العذراء.\"],[\"فرح القيامة ومعزّي الطريق\",\"رحمةٌ جديدة، وحياةٌ أبدية، ومسيحٌ رفيقُ الطريق، وروحٌ يعزّي ويهب.\"],[\"تربيةُ القلب بالكلمة\",\"محبةٌ تُربّي، وقبولُ الآخر، وخضوعٌ لله، وكتابٌ مقدسٌ يفحص الخفايا.\"],[\"مرسَلون بثمر الحياة\",\"شهادةٌ أمينة، وجوابُ «هأنذا»، وعدلٌ ورحمة، وإنسانٌ جديدٌ يعبد في الجماعة.\"],[\"العمل والخدمة بروح الفقر\",\"أمانةُ الله، وكرامةُ العمل، وفرحُ الخدمة، والكنزُ الحقيقي، وفقرُ الروح.\"],[\"التطويبات في الحياة اليومية\",\"تعزيةٌ وسلامٌ وملحٌ وكمالُ محبة، وصدقُ كلمةٍ بلا قلق.\"],[\"الطريق الضيق وعبادة الروح\",\"لا نَدين، ندخل الباب الضيق، ونعبد بالروح والحق، ونحب الله والإخوة.\"],[\"كرازةٌ تبدأ بالشكر والشفاعة\",\"حكمةٌ وشكرٌ وقوةُ الاسم، وكرازةٌ وبحثٌ عن الضال وشفاعة.\"],[\"الحصاد وحلول الروح\",\"خميرةٌ وحصادٌ وأيدٍ مرفوعة، ثم حلولُ الروح القدس واستنارتُه.\"],[\"المحبة الأولى وغنى المسيح\",\"زيارةُ المتألمين، ومحبةٌ أولى، وكلمةٌ تثمر، ومعرفةُ الله وأمانُه.\"],[\"فرحٌ لا تهزّه الظروف\",\"ثمرٌ مطلوب، وفرحُ الرب قوتنا، وهدوءُ القلب، وتسبيحٌ وسط الخسارة.\"],[\"ثباتٌ ورحمة\",\"خيرُ الله وثباتُنا فيه، وتواضعٌ ونعمة، ومحبةٌ بلا رياء وغفران.\"],[\"كلمةٌ ورجاءٌ ونداء\",\"أمانةٌ في القليل، وكلمةٌ في وقتها، ومرساةُ الرجاء، ونداء «اتبعني».\"],[\"اتبعني… وأرسلكم\",\"اتباعٌ أمين، وحملُ الصليب، وخدمةٌ كمثال، وحصادٌ كثير وإرسالية.\"],[\"شهودٌ وجماعةٌ مصلية\",\"شجاعةُ الشهادة، واعترافُ الإيمان، وبطرس وبولس، وكنيسةٌ تصلي.\"],[\"السلوك في النور\",\"محبةٌ كاملة، ووحدةٌ وحرية، وصوتٌ منخفضٌ خفيف، ونعمةٌ فوق نعمة.\"],[\"ثقةُ المؤمن\",\"نورُ العالم، وإيمانٌ عظيم، ورجاءٌ وثقة، وملجأٌ وشبعُ النفس.\"],[\"العودة إلى الرب\",\"ظلٌّ ونور، وشكرُ الغروب، وقلبٌ جديد، وصومٌ وصلاةٌ في الخفاء.\"],[\"العذراء وسرّ التجسد\",\"عطاءٌ مبارك، واتضاعُ العذراء، ونبواتُ التجسد ورموزه.\"],[\"رموزُ العذراء وجبلُ التجلي\",\"الباب المغلق وعصا هارون ونشيدُ العروس، ثم جبلُ الرب والتجلي.\"],[\"رجاءُ ما بعد الجبل\",\"نزولٌ من الجبل، ونياحةُ العذراء، ومنازلُ الآب، وسحابةُ الشهود.\"],[\"سكونٌ وشكر\",\"انتظارُ النفس، وكفطيمٍ نحو أمه، وعهدُ سلامٍ، وشكرُ ختام السنة.\"],[\"كلمةٌ تروي القلب\",\"أبوابُ الحمد، وجودُ الرب، وكلمةٌ تثبت، ومياهٌ للعطشان.\"],[\"رأس السنة والشهداء\",\"استعدادٌ للعام الجديد، وعيدُ النيروز، وصبرٌ واتكالٌ وسهر.\"],[\"ثمرُ الروح ومحبةُ المصلوب\",\"غلبةُ المسيح، ووداعةٌ وتأنٍّ، ومحبةُ المصلوب وحملُ الله.\"],[\"الصليبُ في الكتب\",\"جراحُه شفاؤنا، ونبواتُ الصليب، والحيةُ النحاسية، وعيدُ الصليب.\"],[\"الكنيسةُ جسدٌ واحد\",\"أعضاءٌ بعضُنا لبعض، بيتُ الله، وقطيعٌ واحدٌ ووحدةُ الروح.\"],[\"أسرارُ الكنيسة وطريقُ الاتضاع\",\"خبزُ الحياة، والمعمودية والمسحة، ومخافةُ الرب وانتظارُ رحمته.\"],[\"رحمةٌ وحكمةٌ وبيت\",\"رحمةٌ بالفقير، وصديقٌ أمين، وغفرانٌ وحكمةٌ، وأسرةٌ في قصد الله.\"],[\"البيتُ المبارك\",\"اثنان خيرٌ من واحد، ومحبةٌ واحترام، وبنونٌ ميراثٌ من الرب.\"],[\"من البيت إلى الرجوع\",\"وفاءٌ وأمانةُ الأجيال، ثم صرخةٌ من الهاوية ورجوعٌ إلى الرب.\"],[\"تذكرةُ الأنبياء الأخيرة\",\"اذكر الرحمة، واجعلوا قلبكم على طرقكم، وشمسُ البرّ تشرق.\"],[\"الحكمةُ واختيارُ الحياة\",\"تأديبٌ وزمانٌ لكل شيء، وختامُ الأمر، واختَر الحياة.\"],[\"الملائكةُ وبدءُ الصوم\",\"تواضعٌ وصلاة، وعيدُ ميخائيل، وفرحُ الملائكة، وبدءُ صوم الميلاد.\"],[\"مِلءُ الزمان\",\"موعدٌ منذ القديم، ورحمةٌ وحقٌّ التقيا، وزكريا والسابق.\"],[\"البشارةُ والاستعداد\",\"صمتٌ وإيمان، وبشارةٌ للعذراء، وزيارةٌ وفرح، ويوسفُ البارُّ وعمانوئيل.\"],[\"الطريقُ إلى المذود\",\"نورٌ حقيقي، وطريقٌ إلى بيت لحم، ورعاةٌ ومجوس، وحفظُ الله.\"],[\"سهرُ كيهك وانتظارُ المشرق\",\"لماذا تجسّد؟ ظهورُ النعمة، وسهرٌ وصلاة، والمشرقُ من العلاء.\"],[\"شكرٌ وختامٌ وبداية\",\"رجاءٌ مبارك، «إلى هنا أعاننا الرب»، وعطيةٌ لا يُعبَّر عنها، وكلُّ شيءٍ جديد.\"]],\"days\":{\"1-1\":{\"th\":\"سنةٌ جديدة بين يدي الله\",\"m\":[{\"t\":\"بركةٌ ووجهٌ مضيء\",\"ref\":\"المزمور السادس والستون — باكر\",\"v\":\"ليتراءف الله علينا ويباركنا، وليظهر وجهه علينا ويرحمنا. لتعرف في الأرض طريقك، وفى جميع الأمم خلاصك.\",\"r\":\"نبدأ السنة بطلب البركة قبل أي خطة: أن يُظهر الله وجهه علينا. من يبدأ يومه ووجهه نحو الله لا يخاف مما لم يعرفه بعد، ومن تعلّم أن يرى طريق الله يهتدي في كل طريق. اجعل أولى خطواتك في هذه السنة صلاةً قصيرة تطلب فيها وجه الله لا نتائجه.\",\"p\":\"يا رب، تراءف علينا وباركنا، وأظهر وجهك علينا في هذه السنة. عرّفني طريقك في كل يوم، وليكن خلاصك حاضرًا في بيتي وعملي وقلبي. آمين.\"},{\"t\":\"سنةٌ تُكلَّل بالصلاح\",\"ref\":\"المزامير ٦٥: ١١\",\"bk\":\"المزامير\",\"v\":\"كللت السنة بجودك، وآثارك تقطر دسما.\",\"r\":\"في أول يوم من السنة تميل النفس إلى الحساب: ماذا أنجزت، وماذا أريد، وماذا أخاف؟ لكن المزمور يبدأ من اتجاه آخر؛ فالسنة نفسها تاجٌ يضعه الله على رأسك. قبل أن تضع خططك، ارفع عينيك واشكر على ما سبق، فالقلب الشاكر يدخل المستقبل بطمأنينة لا بقلق.\",\"p\":\"يا رب، أنت إله الأزمنة وصاحب السنين. أشكرك على كل ما أعطيتني فيما مضى، المعلَن منه والخفي. كلّل هذه السنة الجديدة بصلاحك، واجعلني أرى يدك في كل يوم من أيامها. آمين.\"},{\"t\":\"كأنني لم أبدأ بعد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يختم الأب بمفو عمره الطويل بكلمات من لم يبدأ بعد، وليست هذه قلة تقدير لما مضى بل تواضع من يعرف أن الطريق إلى الله لا ينتهي. افتتح سنتك بروح البداية: لا تفتخر بما أنجزت ولا تيأس مما فات، بل ابدأ اليوم كأنه أول يوم تعرف فيه الله.\",\"p\":\"أيها الرب يسوع، علّمني أن أبدأ كل يوم بقلب المبتدئ، متواضعًا أمامك، شاكرًا على الماضي، ومشتاقًا أن أتعلم منك من جديد. آمين.\",\"fq\":461}]},\"1-2\":{\"th\":\"الشكر أولًا\",\"m\":[{\"t\":\"أبارك الرب في كل حين\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"أبارك الرب في كل وقت؛ وفى كل حين تسبحته في فمي، بالرب تفتخر نفسي، يسمع الودعاء فيفرحون. عظموا الرب معي، لنرفع اسمه جميعا.\",\"r\":\"المرنم لا يخصّص للشكر مناسبة، فهو في كل وقت وكل حين. الشكر عادةٌ تُبنى كما تُبنى الصلاة، تبدأ بإرادة وتنتهي بطبع. وكلما سبّحتَ في لحظة بسيطة من يومك، صار قلبك أقدر على أن يلمس يد الله في الأمور العادية.\",\"p\":\"يا رب، أبارك اسمك في كل وقت، وليكن تسبيحك دائمًا في فمي. علّمني أن أعظّمك مع إخوتي، وأن أجد في كل يوم سببًا جديدًا للشكر. آمين.\"},{\"t\":\"رسالة شكر من القلب\",\"ref\":\"لوقا ١٧: ١٥–١٦\",\"bk\":\"لوقا\",\"v\":\"فواحد منهم لما رأى أنه شفي، رجع يمجد الله بصوت عظيم، وخر على وجهه عند رجليه شاكرا له، وكان سامريا.\",\"r\":\"عشرة برصٍ شُفوا، وواحد فقط عاد. الفرق لم يكن في الشفاء، بل في العودة. التسعة أخذوا الهدية، والواحد وجد الواهب. اليوم لا تكتفِ بأن تستمتع بعطايا الله، بل ارجع وقل له: يا رب، أنت أغلى من العطية.\",\"p\":\"يا رب يسوع، كثيرًا ما أخذت عطاياك ومضيت. اليوم أرجع إليك وأخرّ عند قدميك شاكرًا. اشفِ قلبي من الجحود، وعلّمني أن أرى فيك الواهب قبل الهبة. آمين.\"},{\"t\":\"يذوق ويشكر\",\"ref\":\"\",\"v\":\"\",\"r\":\"القديس أرسانيوس يذوق قليلًا من كل نوع من الثمار ويشكر الله، فالشكر عنده يمرّ من الفم إلى القلب. لا ينتظر كثرة العطايا ليشكر، بل يشكر على قليلها. تعلّم منه أن تقف اليوم عند نعمةٍ بسيطة وتقول: شكرًا يا رب.\",\"p\":\"يا إله كل عطية صالحة، علّمني أن أقبل القليل بشكر كبير، وأن أتذوق خيراتك بقلب ممتن لا يعتاد على نعمك. لك المجد دائمًا. آمين.\",\"fq\":36}]},\"1-3\":{\"th\":\"أن نبدأ بالصلاة\",\"m\":[{\"t\":\"عطشت إليك نفسي\",\"ref\":\"المزمور ٦٣ — باكر\",\"v\":\"يا الله إلهي إليك أبكر، عطشت إليك نفسي. يشتاق إليك جسدي، في أرض مقفرة وموضع غير مسلوك ومكان بلا ماء.\",\"r\":\"يبكّر المرنم إلى الله لأن عطشه أكبر من انشغاله. ليست البداية بالصلاة واجبًا ثقيلًا بل جوابًا لعطش داخلي، فكل نفس تعرف أنها لا تشبع بغير الله. ابدأ يومك اليوم بدقائق تسمّي فيها عطشك أمام الله دون ألفاظ كثيرة.\",\"p\":\"يا الله إلهي، إليك أبكّر، وإليك عطشت نفسي. اروِ قلبي بحضورك في أرض الانشغال القاحلة، واجعل صلاتي أول خطواتي كل صباح. آمين.\"},{\"t\":\"اطلبوا تجدوا\",\"ref\":\"متى ٧: ٧–٨\",\"bk\":\"متى\",\"v\":\"«اسألوا تعطوا. اطلبوا تجدوا. اقرعوا يفتح لكم. لأن كل من يسأل يأخذ، ومن يطلب يجد، ومن يقرع يفتح له.\",\"r\":\"قد نصلّي ونشعر أن السماء صامتة. لكن المسيح يشجعنا ثلاث مرات في عدد واحد: اسأل، اطلب، اقرع. الإلحاح لا يغيّر قلب الله، لكنه يغيّر قلبي أنا ويُظهر ما أطلبه حقًا. الله لا يتأخر ليعاقب، بل ليعلّم الثقة.\",\"p\":\"يا أبانا الذي في السموات، أسألك فأعطني، أطلبك فاجعلني أجدك، أقرع بابك فافتح لي. علّمني أن أثق بحكمتك حين لا أفهم تأخيرك، وأن أطلبك أنت أكثر من عطاياك. آمين.\"},{\"t\":\"ابدأ في هذه الساعة\",\"ref\":\"\",\"v\":\"\",\"r\":\"سُئل الأب سلوان: هل يمكن أن يبتدئ المرء من جديد؟ فأجاب أن النشيط يبتدئ كل ساعة. لا ينتظر الإنسان رأس السنة أو بداية الأسبوع ليعود إلى الصلاة، فالله يقبله في هذه اللحظة. وإن فاتك صباحك، فابدأ بصلاة قصيرة الآن.\",\"p\":\"يا رب، اجعلني نشيطًا في البدء كل ساعة، ولا تدعني أؤجل لقاءك. أعطني نعمة العودة إليك مرارًا بقلب جديد. آمين.\",\"fq\":515}]},\"1-4\":{\"th\":\"الإصغاء لكلمة الله\",\"m\":[{\"t\":\"ناموس الرب يردّ النفوس\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"ناموس الرب بلا عيب يرد النفوس. شهادة الرب صادقة. تعلم الأطفال.\",\"r\":\"كلمة الله لا تعلّمنا فقط، بل تردّ النفس إذا ضلّت وتفرح القلب إذا حزن. قد نسمعها كثيرًا دون أن نُصغي إليها، فالإصغاء أن نترك لها أن تعمل فينا. اقرأ اليوم فقرة قصيرة ببطء، ثم اسأل: ماذا تريد هذه الكلمة أن تفعل فيّ؟\",\"p\":\"يا رب، ناموسك بلا عيب يردّ النفوس، فردّ نفسي إليك. افتح أذني لأصغي وقلبي لأقبل، وعلّمني بكلمتك كما يتعلم الطفل من أبيه. آمين.\"},{\"t\":\"الأرض الجيدة\",\"ref\":\"لوقا ٨: ١٥\",\"bk\":\"لوقا\",\"v\":\"والذي في الأرض الجيدة، هو الذين يسمعون الكلمة فيحفظونها في قلب جيد صالح، ويثمرون بالصبر.\",\"r\":\"لا نستطيع أن نتحكم في مقدار ما يزرعه الله في قلوبنا، لكننا نتحكم في نوع الأرض. هل قلبي طريق مداس، أم صخرة بلا عمق، أم أرض فيها شوك؟ والأرض الجيدة ليست بلا مشاكل، بل هي التي تسمع وتحفظ وتصبر حتى يأتي الثمر.\",\"p\":\"يا رب، أنت الزارع وأنا الأرض. اقلع شوك الاهتمامات من قلبي، وليّن قسوتي، واجعلني أسمع كلمتك وأحفظها وأثمر بالصبر. آمين.\"},{\"t\":\"ضمانة للهرب من الخطيئة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يرى القديس إبيفانيوس في قراءة الكتب المقدسة ضمانة كبيرة للهرب من الخطيئة، لأن الكلمة تملأ الذهن بما هو أنقى من أفكاره. ما نحتفظ به في داخلنا يظهر في اختياراتنا. اجعل لك وقتًا ثابتًا في اليوم للكلمة، ولو صفحة واحدة.\",\"p\":\"يا رب، احفظني بكلمتك من كل سقوط. ثبّت فيّ الشوق إلى قراءتها وتأملها، وليكن الكتاب نورًا لخطواتي وحصنًا لقلبي. آمين.\",\"fq\":100}]},\"1-5\":{\"th\":\"التوبة بابٌ مفتوح\",\"m\":[{\"t\":\"اذكرني كرحمتك\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"خطايا شبابي وجهالاتي لا تذكر. كرحمتك اذكرني أنت من أجل صلاحك يا رب.\",\"r\":\"يطلب المرنم أن يُنسى ما كان من الخطأ، وأن يُذكر بحسب الرحمة. هذا الباب لا يُغلق، لا لأنني أستحق بل لأن رحمة الله أقدم من خطيتي. لا تنتظر أن تصير أفضل لتعود، بل عُد فتصير أفضل في حضنه.\",\"p\":\"اذكرني يا رب كرحمتك لا كخطاياي. لا تذكر جهالات شبابي وسقطاتي، وردّني إليك بقلب منكسر يرجو صلاحك. آمين.\"},{\"t\":\"الابن الضال والآب المنتظر\",\"ref\":\"لوقا ١٥: ٢٠\",\"bk\":\"لوقا\",\"v\":\"فقام وجاء إلى أبيه. وإذ كان لم يزل بعيدا رآه أبوه، فتحنن وركض ووقع على عنقه وقبله.\",\"r\":\"توقف عند هذا المشهد: «وإذ كان لم يزل بعيدًا رآه أبوه فتحنن وركض». الأب لم يكن ينتظر في البيت، بل كان يراقب الطريق. وقبل أن يسمع كلمات الاعتذار كان قد احتضنه. هذه هي صورة الله لمن يفكر في العودة إليه.\",\"p\":\"يا أبي السماوي، أخطأت إليك وإلى السماء. ها أنا راجع إليك، فاستقبلني كما استقبلت الابن الراجع. ألبسني ثوب البنوة، وأقمني من جديد في بيتك. آمين.\"},{\"t\":\"أن أضع خطيتي أمام الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يسمّي القديس أنطونيوس العمل العظيم أن يحمل الإنسان خطيته ويضعها أمام الله. لا إنكار ولا تبرير ولا هروب، بل وقوف صادق. من يقف هكذا لا يبقى طويلًا تحت ثقل الذنب، فسمِّ خطيتك اليوم أمام الله باسمها.\",\"p\":\"يا رب، أضع أمامك خطيتي بلا تبرير ولا خوف. اقبل اعترافي، وارفع عني ثقلها، وعلّمني أن أنتظر رحمتك طوال أيام حياتي. آمين.\",\"fq\":2}]},\"1-6\":{\"th\":\"المحبة أعظم\",\"m\":[{\"t\":\"ما أحسن وما أحلى\",\"ref\":\"المزمور ١٣٢ — النوم\",\"v\":\"هوذا ما أحسن وما أحلي أن يسكن الاخوة معا. كالطيب الكائن على الرأس الذي ينزل على اللحية، لحية هارون النازلة على جيب قميصه.\",\"r\":\"المحبة التي تبقى هي التي تُرى في بيتٍ واحد ومائدةٍ واحدة. يشبّه المرنم وحدة الإخوة بالطيب الذي ينزل على الرأس، فيشمّ الجميع رائحته. حيث يُسكب الحب لا يبقى لأحد وحده. فمن أقرب الناس إليك ويحتاج اليوم إلى كلمة طيبة؟\",\"p\":\"يا رب، ما أحسن أن نسكن معًا بمحبة. انزع من بيتي وكنيستي كل جفاء، واسكب فينا طيب وحدتك وبركتك. آمين.\"},{\"t\":\"أحبّ بالفعل\",\"ref\":\"يوحنا الأولى ٣: ١٨\",\"bk\":\"يوحنا الأولى\",\"v\":\"يا أولادي، لا نحب بالكلام ولا باللسان، بل بالعمل والحق!\",\"r\":\"من السهل أن أقول «أحبك» لكل أحد، ولكن المحبة تُختبر حين أحتاج إلى أن أترك راحتي لأجل غيري. يطلب منا الرسول أن تكون محبتنا «بالعمل والحق». فلنفتش اليوم عن حاجة بين أيدينا نستطيع أن نسدّها دون أن نُعلن عنها.\",\"p\":\"يا رب، لا تجعل محبتي كلامًا فقط. علّمني أن أرى حاجة من حولي وأتحرك، وأن أبذل بفرح دون أن أنتظر شكرًا. اجعلني أداة لمحبتك. آمين.\"},{\"t\":\"ربح الأخ ربحٌ لله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّمنا القديس أنطونيوس أن الحياة والموت متعلقان بالقريب: إن ربحنا أخانا ربحنا الله، وإن أعثرناه أخطأنا إلى المسيح. هذا يعطي لكل علاقة ثقلها الروحي. قبل أن تكلّم أحدًا اليوم، تذكّر أنك تتعامل مع من يحبه المسيح.\",\"p\":\"أيها المسيح إلهي، علّمني أن أرى فيك كل أخ. احفظني من أن أعثر أحدًا، وأعطني أن أكسب القلوب بمحبتك. آمين.\",\"fq\":7}]},\"1-7\":{\"th\":\"عيد الميلاد المجيد\",\"m\":[{\"t\":\"الكلمة صار جسدًا\",\"ref\":\"إنجيل باكر\",\"v\":\"والكلمة صار جسدا وحل بيننا ورأينا مجده مثل مجد ابن وحيد لأبيه مملوءا نعمة وحقا.\",\"r\":\"في الميلاد لا نحتفل بفكرة بل بشخص: الكلمة نفسه صار جسدًا وسكن بيننا. الله لم يرسل رسالة بل جاء بنفسه. هذا هو معنى عيدنا، أن الله ليس بعيدًا عن بيتك وتعبك وفرحك. اقترب اليوم من المذود بقلب يفتح له مكانًا.\",\"p\":\"أيها الكلمة المتجسد، شكرًا لأنك سكنت بيننا ورأينا مجدك. افتح قلبي لك كما فتحت العذراء حضنها، واملأني نعمةً وحقًا. آمين.\"},{\"t\":\"وُلد لكم اليوم مخلّص\",\"ref\":\"لوقا ٢: ١٠–١١\",\"bk\":\"لوقا\",\"v\":\"فقال لهم الملاك: «لا تخافوا! فها أنا أبشركم بفرح عظيم يكون لجميع الشعب: أنه ولد لكم اليوم في مدينة داود مخلص هو المسيح الرب.\",\"r\":\"الملاك لم يقل للرعاة: ستحتاجون إلى مجهود كبير. قال: «أبشركم بفرح عظيم». الميلاد ليس إنجازًا بشريًا بل هبة. والله جاء إلى أبسط الناس: رعاة يسهرون على قطيعهم. وهو يأتي اليوم إلى قلبي أيضًا، لا لأني أستحق بل لأن محبته سبقت استحقاقي.\",\"p\":\"يا رب يسوع، أشكرك لأنك ولدت لأجلي. افتح قلبي مذودًا لك، وامنحني فرح الرعاة وإيمانهم. ثبّتني في البشارة التي تجعل الحياة جديدة. آمين.\"},{\"t\":\"أعظم نعمة: تجسّد ابن الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"حين طلب الإخوة من الأب إيسيذورس أن يرتاح لأنه شاخ، أجاب أنه حتى لو أُحرق ونُثر رماده في الهواء فلا نعمة أكبر من أن ابن الله جاء إلى هنا من أجلنا. التجسد هو الذي يهوّن كل تعب. تأمّل اليوم: ماذا يعني أن الله أحبني حتى نزل إلى عالمي؟\",\"p\":\"يا رب يسوع، ابن الله الذي جاء من أجلنا، لك الشكر على تجسدك وفدائك. اجعل هذه النعمة أعظم ما في قلبي، وهوّن عليّ كل تعب بسببك. آمين.\",\"fq\":170}]},\"1-8\":{\"th\":\"الصبر والانتظار\",\"m\":[{\"t\":\"انتظر الرب فتقوى\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"وأنا أؤمن أنى أعاين خيرات الرب في أرض الأحياء. انتظر الرب، تقو وليتشدد قلبك وانتظر الرب.\",\"r\":\"يعلّمنا المرنم أن الانتظار ليس ضعفًا بل مدرسة قوة: «انتظر الرب، تقوَّ وليتشدد قلبك». ننتظر وقلوبنا تُبنى بالإيمان بأن الله يرى ما لا نرى. في أمرٍ معلّق في حياتك اليوم، قل لله: أنا أنتظرك، وأثق أنك أعددتَ لي خيرًا.\",\"p\":\"يا رب، أؤمن أني سأعاين خيراتك في أرض الأحياء. قوِّ قلبي في الانتظار، وأعطني صبرًا لا يتعجّل ولا ييأس مما تؤخّره. آمين.\"},{\"t\":\"الصبر يصنع الخبرة\",\"ref\":\"رومية ٥: ٣–٥\",\"bk\":\"رومية\",\"v\":\"وليس ذلك فقط، بل نفتخر أيضا في الضيقات، عالمين أن الضيق ينشئ صبرا، والصبر تزكية، والتزكية رجاء، والرجاء لا يخزي، لأن محبة الله قد انسكبت في قلوبنا بالروح القدس المعطى لنا.\",\"r\":\"يبدو غريبًا أن نفتخر بالضيقات. لكن الرسول يشرح السلسلة: الضيق ينتج صبرًا، والصبر خبرة، والخبرة رجاء. فالألم لا يُحتمل وحده، بل يحمله الروح القدس الذي سُكبت فيه محبة الله. وهكذا تتحول المحنة من عائق إلى مدرسة.\",\"p\":\"يا رب، أشكرك لأنك لا تترك المتألم وحده. حوّل ضيقاتي إلى صبر وخبرة ورجاء. املأ قلبي بمحبتك لأقف ثابتًا في المحنة. آمين.\"},{\"t\":\"أعطني الصبر في الحروب\",\"ref\":\"\",\"v\":\"\",\"r\":\"لم يطلب الأب يوحنا الكولوفي أن تُرفع الحرب عنه، بل صلّى: «يا رب أعطني الصبر في الحروب». كثيرًا ما نطلب رفع الضيق، وقليلًا ما نطلب القوة على الصبر فيه. هذه كلمات قليلة نردّدها اليوم عند أول ضيق.\",\"p\":\"يا رب، أعطني الصبر في حروبي، ولا تدعني أتعجّل مخرجًا خارج مشيئتك. كن معي حتى ينتهي الامتحان. آمين.\",\"fq\":155}]},\"1-9\":{\"th\":\"الاتضاع طريق الرفعة\",\"m\":[{\"t\":\"قلبٌ لم يرتفع\",\"ref\":\"المزمور ١٣٠ — النوم\",\"v\":\"يا رب لم يرتفع قلبي، ولم تستعل عيناي؛ ولم أسلك في العظائم ولا في العجائب التي هي أعلى مني.\",\"r\":\"لا يدّعي المرنم العظمة ولا يطلب ما فوق طاقته، فقلبه مطمئن كطفل فُطم على صدر أمه. الاتضاع ليس إنكار القدرة، بل قبول حجمي أمام الله. إن تعبتَ من المقارنة والسباق، فاجلس اليوم لحظة وقل: لا أطلب يا رب أكثر مما تعطيني.\",\"p\":\"يا رب، لم يرتفع قلبي ولم تستعلِ عيناي. علّمني أن أطمئن في حضنك كطفل، ولا أسعى إلى عظائم تفوق ما أعطيتني. آمين.\"},{\"t\":\"الله يقاوم المستكبرين\",\"ref\":\"بطرس الأولى ٥: ٥–٦\",\"bk\":\"بطرس الأولى\",\"v\":\"كذلك أيها الأحداث، اخضعوا للشيوخ، وكونوا جميعا خاضعين بعضكم لبعض، وتسربلوا بالتواضع، لأن: «الله يقاوم المستكبرين، وأما المتواضعون فيعطيهم نعمة». فتواضعوا تحت يد الله القوية لكي يرفعكم في حينه،\",\"r\":\"قد نظن أن الكبرياء يدفعنا إلى القمة، لكن الكتاب يقول إن الله يقاوم المستكبرين. وهذه مقاومة محبة، لأنه لا يريد أن نسقط في الوهم. بينما المتواضعون يأخذون نعمة، أي قوة ومعونة. فلنتواضع تحت يد الله القوية.\",\"p\":\"يا رب، احفظني من الكبرياء الخفي. أعطني نعمة الاتضاع لأقبل مكاني ومحدوديتي، وارفعني أنت في الوقت الذي تراه. آمين.\"},{\"t\":\"فخاخ العدو والتواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"رأى القديس أنطونيوس فخاخ العدو منتشرة على الأرض فتنهّد: من ينجو منها؟ فجاءه الجواب: التواضع. جوابٌ بسيط لكنه يحتاج حياةً كاملة. جرّب اليوم أن تتنازل في موقف صغير قبل أن تثبت أنك على صواب.\",\"p\":\"يا رب، احفظني من فخاخ العدو بالتواضع. انزع الكبرياء من قلبي، وعلّمني أن أنحني كما انحنيتَ أنت لتغسل أقدام تلاميذك. آمين.\",\"fq\":5}]},\"1-10\":{\"th\":\"أنا مع الله\",\"m\":[{\"t\":\"معه أنا في الشدة\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"لأنه على أتكل فأنجيه: أرفعه (أستره) لأنه عرف اسمي. يدعوني فأستجيب له. معه أنا في الشدة، أنقذه وأمجده.\",\"r\":\"الله لا يعد بغياب الشدة، بل بحضوره فيها: «معه أنا في الشدة». هذا الوعد يغيّر نظرتنا إلى الصعوبة، فهي ليست دليل غياب بل مكان لقاء. تذكّر اليوم موقفًا ثقيلًا في حياتك وقل: أنت معي هنا.\",\"p\":\"يا رب، أنت تُجيب من يدعوك وتكون معه في الشدة. أنقذني ومجّدني بنعمتك، وعلّمني أن أراك قريبًا في ضيقاتي. آمين.\"},{\"t\":\"لا أتركك ولا أهملك\",\"ref\":\"العبرانيين ١٣: ٥–٦\",\"bk\":\"العبرانيين\",\"v\":\"لتكن سيرتكم خالية من محبة المال. كونوا مكتفين بما عندكم، لأنه قال: «لا أهملك ولا أتركك» حتى إننا نقول واثقين: «الرب معين لي فلا أخاف. ماذا يصنع بي إنسان؟»\",\"r\":\"في زمن يعتمد فيه الإنسان على المال والمكانة والعلاقات، يعدنا الله بما هو أعظم: حضوره الدائم. هذا الوعد لا يلغي الصعوبات، لكنه يغيّر طريقة مواجهتها. فنقول بثقة: «الرب معين لي فلا أخاف».\",\"p\":\"يا رب، أشكرك لأنك وعدت ألا تتركني. حين أخاف ذكّرني بحضورك، وحين أطمع علّمني القناعة. أنت معيني فلا أخاف. آمين.\"},{\"t\":\"الله في القلاية وخارجها\",\"ref\":\"\",\"v\":\"\",\"r\":\"يتساءل الأب دانيال: من ينزع الله منا؟ ثم يعلن أن الله في القلاية وخارجها. حضوره لا يتوقف على مكان نحبه أو ظرف نختاره. فلنعش اليوم بإحساس أن الله يرافقنا في العمل والطريق والبيت.\",\"p\":\"يا رب، أنت في كل مكان، فلا تدعني أنسى حضورك. أعطني سلامًا يثبّتني في كل ظرف وتغيير. آمين.\",\"fq\":95}]},\"1-11\":{\"th\":\"الرجاء الذي لا يخزي\",\"m\":[{\"t\":\"خلاص وجهي هو إلهي\",\"ref\":\"المزمور ٤٢ (٤٣) — الثالثة\",\"v\":\"لماذا أنت حزينة يا نفسي، ولماذا تزعجينني؟ توكلي على الله فإني أعترف له. خلاص وجهي هو إلهي.\",\"r\":\"يحاور المرنم نفسه الحزينة بدل أن يتركها للحزن: لماذا أنت حزينة؟ توكلي على الله. الرجاء قرارٌ يُتخذ حين تثقل النفس، وليس شعورًا ينتظر الظروف. حاور قلبك اليوم بالطريقة نفسها، وذكّره بأن خلاصك من الله لا من الأحوال.\",\"p\":\"يا رب، أنت خلاص وجهي وإلهي. حين تحزن نفسي ذكّرني أن أتوكل عليك، واجعل الرجاء فيك مرساةً لقلبي. آمين.\"},{\"t\":\"رجاء يحيا في الانتظار\",\"ref\":\"رومية ٨: ٢٤–٢٥\",\"bk\":\"رومية\",\"v\":\"لأننا بالرجاء خلصنا. ولكن الرجاء المنظور ليس رجاء، لأن ما ينظره أحد كيف يرجوه أيضا؟ ولكن إن كنا نرجو ما لسنا ننظره فإننا نتوقعه بالصبر.\",\"r\":\"أصعب أنواع الانتظار هو انتظار ما لا نراه. بولس يقول إن الرجاء المنظور ليس رجاءً، فالذي أراه بعيني لا أحتاج أن أرجوه. إذن الرجاء مدرسة الإيمان: يعلّمني أن أمشي بثقة قبل أن أرى، وأن أصبر وأنا أعلم أن الله لا يتأخر ولا ينسى.\",\"p\":\"يا رب، علّمني أن أرجو ما لا أراه وأن أنتظر دون تذمر. اجعل ضيقي مدرسة تصنع فيّ صبرًا ورجاءً. املأ قلبي بمحبتك المسكوبة بروحك القدوس. آمين.\"},{\"t\":\"لماذا الشك إذن؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"تعب الإخوة فسأل أحدهم الأب يوحنا الفارسي، فأجابهم بإيمان من يثق في وعد ربه: سأرث أورشليم العلوية لأن من وعدنا أمين. لا ينفي التعبَ، لكنه يضع الوعد فوقه. حين تثقل عليك مشقة اليوم، فكّر في من وعدك.\",\"p\":\"يا رب، أنت أمين في كل وعودك. ثبّتني في رجاء أورشليم العلوية، وامنحني ألا أشك فيك عند التعب. آمين.\",\"fq\":204}]},\"1-12\":{\"th\":\"الفرح بالرب\",\"m\":[{\"t\":\"فرحٌ للمستقيمي القلوب\",\"ref\":\"المزمور ٩٦ (٩٧) — التاسعة\",\"v\":\"نور أشرق للصديقين وفرح للمستقيمي القلوب. افرحوا أيها الصديقون بالرب. واعترفوا لذكر قدسه.\",\"r\":\"الفرح الذي يتحدث عنه المرنم نور يُشرق للصديقين، فليس هو تهريجًا ولا هروبًا. إنه ثمرة قلب مستقيم أمام الله. افرح اليوم بشيء صغير تعرف أنه من الله، واشكره باسمه، وسترى أن الفرح يكبر حين نعترف بمصدره.\",\"p\":\"يا رب، أشرق بنورك على قلبي واملأه فرحًا مستقيمًا. علّمني أن أفرح بك وأعترف لذكر قدسك في كل يوم. آمين.\"},{\"t\":\"فرح لا ينتزعه أحد\",\"ref\":\"فيلبي ٤: ٤\",\"bk\":\"فيلبي\",\"v\":\"افرحوا في الرب كل حين، وأقول أيضا: افرحوا.\",\"r\":\"بولس كتب هذه الآية وهو في السجن. هذا وحده كافٍ ليعلّمنا أن الفرح الذي يتكلم عنه ليس راحة ظرفية. إنه فرحٌ في الرب، أي أن مصدره خارج الظروف. إن كان فرحي مرهونًا بيوم هادئ، فهو ضيف. أما إن كان مرتبطًا بشخص المسيح، فهو ساكن لا يغادر.\",\"p\":\"يا رب، علّمني أن أفرح بك لا بما يعطيه الزمان. حوّل شكواي إلى تسبيح وثقل يومي إلى شكر. ثبّت فيّ فرحك الذي لا ينتزعه أحد. آمين.\"},{\"t\":\"افرحوا دائمًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب بنيامين أبناءه في ساعته الأخيرة بثلاث: افرحوا دائمًا، صلوا بلا انقطاع، واشكروا على كل شيء. وصية رجل قرر أن يترك لهم ما هو أثمن من المال. أيٌّ من الثلاث أحوج إليه قلبك اليوم؟\",\"p\":\"يا رب، علّمني الفرح الدائم والصلاة بلا انقطاع والشكر على كل شيء. احفظ هذه الوصية حيةً في داخلي. آمين.\",\"fq\":84}]},\"1-13\":{\"th\":\"الأمانة في القليل\",\"m\":[{\"t\":\"الوكيل الأمين الحكيم\",\"ref\":\"إنجيل الخدمة الثالثة — نصف الليل — الخدمة الثالثة\",\"v\":\"من هو الوكيل الأمين الحكيم الذي يقيمه سيده على عبيده ليعطيهم طعامهم في حينه؟ طوبى لذلك العبد الذي إذا جاء سيده يجده يفعل هكذا. حقا أقول لكم إنه يقيمه على جميع أمواله.\",\"r\":\"سؤال الرب عن الوكيل الأمين لا يبحث عن المشاهير، بل عمّن يعطي الآخرين طعامهم في حينه. الأمانة هي الاستمرار في الواجب الصغير دون مراقب. ما المهمة الصغيرة المنسية في يومك، وهل تؤديها كأن السيد حاضر؟\",\"p\":\"يا رب، اجعلني وكيلًا أمينًا حكيمًا على ما استأمنتني عليه. علّمني أن أؤدي الصغير بفرح، فتقيمني على الكثير بنعمتك. آمين.\"},{\"t\":\"من كان أمينًا في القليل\",\"ref\":\"لوقا ١٦: ١٠\",\"bk\":\"لوقا\",\"v\":\"الأمين في القليل أمين أيضا في الكثير، والظالم في القليل ظالم أيضا في الكثير.\",\"r\":\"نحب أن نتصور أننا سنكون أمناء متى جاءت المهمة الكبرى. لكن الرب يقول إن الحياة تُقاس بالتفاصيل: مواعيدي الصغيرة، وكلمتي التي لم يسمعها أحد، وعملي حين لا يراقبني أحد. الأمانة عادة تتكون يومًا بعد يوم في الأمور التي نحسبها لا شيء.\",\"p\":\"يا رب، علّمني أن أكون أمينًا في الصغير كما في الكبير. نقِّ قلبي من الإهمال والتسويف، واجعل عملي كله لمجدك. اذكرني كعبدك الأمين. آمين.\"},{\"t\":\"عمل خفيف ودائم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يفضّل الأب ماتوى عملًا خفيفًا دائمًا على عمل متعب لا يدوم. الأمانة ليست حماسة البدء بل ثبات الاستمرار. اختر اليوم عادة روحية صغيرة يمكنك أن تمارسها كل يوم دون أن تنقطع.\",\"p\":\"يا رب، أعطني أمانةً هادئة لا تتعب، وثباتًا في العمل الصغير. وكلّل جهدي المتواضع بنعمتك. آمين.\",\"fq\":268}]},\"1-14\":{\"th\":\"الصداقة مع الله\",\"m\":[{\"t\":\"الرب أمامي في كل حين\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"تقدمت فرأيت الرب أمامي في كل حين، لأنه عن يميني لكي لا أتزعزع. من أجل هذا فرح قلبي وتهلل لساني. وأيضا جسدي يسكن على الرجاء.\",\"r\":\"الصداقة مع الله تبدأ حين أراه أمامي في كل حين لا في المناسبات فقط. وجوده عن يميني يعطيني ثباتًا، وفرح القلب نتيجة طبيعية لهذه الصحبة. اجعل لنفسك اليوم عادة قصيرة: كلما بدأت عملًا جديدًا، قل في سرّك: أنت هنا يا رب.\",\"p\":\"يا رب، أنت أمامي في كل حين وعن يميني فلا أتزعزع. ليفرح قلبي بصحبتك، وليسكن جسدي على الرجاء. آمين.\"},{\"t\":\"موسى وإبراهيم: أصدقاء الله\",\"ref\":\"الخروج ٣٣: ١١\",\"bk\":\"الخروج\",\"v\":\"ويكلم الرب موسى وجها لوجه، كما يكلم الرجل صاحبه. وإذا رجع موسى إلى المحلة كان خادمه يشوع بن نون الغلام، لا يبرح من داخل الخيمة.\",\"r\":\"موسى كان يكلّم الله «كما يكلم الرجل صاحبه». هذا يعني أنه قال كل ما في قلبه: شكواه وخوفه وأسئلته وحتى اعتراضه. والله لم يغضب، بل قرّبه أكثر. الصداقة مع الله لا تعني أن أخفي ضعفي، بل أن أحمله إليه بصدق.\",\"p\":\"يا رب، علّمني أن أكلمك كصديق وأسمعك كابن. اجعل صلاتي صادقة لا زخرفة فيها. كشف لي قلبك كما كشفته لأحبائك، وأعطني أن أحيا حسب مشيئتك. آمين.\"},{\"t\":\"إذا طلبنا الله يظهر لنا\",\"ref\":\"\",\"v\":\"\",\"r\":\"الكلمات قليلة عند القديس أرسانيوس لكنها وعد: إذا طلبنا الله يظهر لنا، وإذا تمسكنا به يقيم فينا. الصداقة مع الله تتطلب طلبًا ثم تمسكًا. اطلب وجهه اليوم، ولا تتركه عند أول ازدحام للانشغال.\",\"p\":\"يا رب، أطلبك فاظهر لي، وأتمسك بك فأقم فيّ. لا تدعني أبتعد عنك مهما شغلتني الأيام. آمين.\",\"fq\":30}]},\"1-15\":{\"th\":\"الصوم والخلوة\",\"m\":[{\"t\":\"تذكرتُ الأيام الأولى\",\"ref\":\"المزمور المئة والثاني والأربعون — باكر\",\"v\":\"تذكرت الأيام الأولى ولهجت في كل أعمالك، وفى صنائع يديك كنت أتأمل. بسطت إليك يدي. صارت نفسي لك مثل أرض بلا ماء.\",\"r\":\"في خلوة المرنم يتذكر أعمال الله ويتأمل صنائع يديه، ثم يبسط يديه إليه كأرض عطشى. الخلوة ليست انسحابًا بل استعادة لذاكرة النعمة. خصّص اليوم دقائق بلا هاتف، واذكر ثلاثة مواقف عمل الله فيها معك.\",\"p\":\"يا رب، أتذكر أعمالك وأتأمل صنائع يديك. أبسط يدي إليك، فتصير نفسي أرضًا عطشى ترتوي من حضورك. آمين.\"},{\"t\":\"صلِّ إلى أبيك في الخفاء\",\"ref\":\"متى ٦: ٦\",\"bk\":\"متى\",\"v\":\"وأما أنت فمتى صليت فادخل إلى مخدعك وأغلق بابك، وصل إلى أبيك الذي في الخفاء. فأبوك الذي يرى في الخفاء يجازيك علانية.\",\"r\":\"في عالم يُعرض فيه كل شيء، يدعوك المسيح إلى باب مغلق. ليست الدعوة هروبًا بل لقاء بلا جمهور، لا أحتاج فيه أن أبدو صالحًا بل أكون على حقيقتي. ومن يتعلم الخلوة يصير ثابتًا حين يخرج، لأن جذوره في الخفاء.\",\"p\":\"أبانا الذي في السموات، أريد أن ألقاك في الخفاء بلا قناع. اجذبني إلى خلوتي، وأغلق عني ضجيج العالم. علّمني أن أصلي لأجلك لا لأجل أحد. آمين.\"},{\"t\":\"اجلس في قلايتك\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل أخٌ الأب موسى كلمة منفعة، فلم يعطه محاضرة بل قال: اجلس في قلايتك وهي تعلّمك كل شيء. الخلوة مدرسة لمن يسكن فيها بصدق. اختر لنفسك مكانًا هادئًا في بيتك، واجلس فيه خمس دقائق صامتًا.\",\"p\":\"يا رب، علّمني أن أحب الخلوة معك. وفي صمتها علّمني ما لا يُقال، ودعني أسمع فيها همس نعمتك. آمين.\",\"fq\":255}]},\"1-16\":{\"th\":\"الغفران يحرر\",\"m\":[{\"t\":\"غفرتَ وسترتَ\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"رضيت يا رب عن أرضك، رددت سبى يعقوب. غفرت آثام شعبك. سترت جميع خطاياهم.\",\"r\":\"يرى المرنم الغفران مثل نهرٍ يرد الأسير إلى بيته: غفرت آثام، وسترت الخطايا، ورجعت عن غضبك. من نال هذا الغفران صار أقدر على أن يغفر. فكّر في إنسان لم تغفر له بعد، واطلب اليوم من الله أن يعطيك أن تبدأ.\",\"p\":\"يا رب، شكرًا لأنك غفرت آثام شعبك وسترت خطاياهم. علّمني أن أغفر كما غفرت لي، وحرّر قلبي من كل مرارة. آمين.\"},{\"t\":\"سبعون مرة سبع مرات\",\"ref\":\"متى ١٨: ٢١–٢٢\",\"bk\":\"متى\",\"v\":\"حينئذ تقدم إليه بطرس وقال: «يارب، كم مرة يخطئ إلي أخي وأنا أغفر له؟ هل إلى سبع مرات؟» قال له يسوع: «لا أقول لك إلى سبع مرات، بل إلى سبعين مرة سبع مرات.\",\"r\":\"بطرس ظن أن سبع مرات سخاء كبير. لكن الرب أجاب بما يتجاوز الحساب. الغفران الحقيقي لا يعدّ. وهو لا يعني تجاهل الأذى بل رفض العيش به. إن كنت تغفر ثم تتذكر الألم وتضيق، فلا تيأس: الغفران عملية تحتاج تكرارًا لا مرة واحدة.\",\"p\":\"يا رب، علّمني أن أغفر دون عدّ، كما تغفر أنت لي كل يوم. اشفِ ذاكرتي من المرارة. وأعطني أن أكون سفير مصالحتك. آمين.\"},{\"t\":\"لم أنم وفي قلبي شيء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشهد القديس أغاثون أنه لم ينم يومًا وفي قلبه شيء على أحد، ولم يترك أحدًا ينام وفي قلبه عليه شيء. يعمل هكذا على قدر طاقته. هذا هو الغفران العملي: مصالحة قبل الغروب. إن كان بينك وبين أحد خلاف، فابدأ اليوم بخطوة صغيرة.\",\"p\":\"يا رب، اجعلني صانع سلام لا أنام وفي قلبي ضغينة. وأعطني شجاعة أن أبدأ بالاعتذار والمصالحة. آمين.\",\"fq\":48}]},\"1-17\":{\"th\":\"الطاعة طريق البركة\",\"m\":[{\"t\":\"علّمني أن أصنع مشيئتك\",\"ref\":\"المزمور المئة والثاني والأربعون — باكر\",\"v\":\"علمني أن أصنع مشيئتك. لأنك أنت هو إلهي. روحك القدوس فليهدني إلى الاستقامة.\",\"r\":\"الطاعة في كلمات المرنم ليست آلية بل طلب: علّمني. نحن لا نعرف المشيئة تلقائيًا، والروح القدس هو الذي يهدينا إلى الاستقامة. اسأل الله اليوم عن مشيئته في أمرٍ يشغلك، واترك الجواب يأتي بهدوء، ولو تأخر.\",\"p\":\"يا رب، علّمني أن أصنع مشيئتك فأنت إلهي. وليهدني روحك القدوس إلى الاستقامة من أجل اسمك. آمين.\"},{\"t\":\"نوح ومسيرة الطاعة\",\"ref\":\"التكوين ٦: ٢٢\",\"bk\":\"التكوين\",\"v\":\"ففعل نوح حسب كل ما أمره به الله. هكذا فعل.\",\"r\":\"بنى نوح الفلك سنين طويلة والسماء صافية. ربما سخر منه الناس. لكنه فعل «حسب كل ما أمره الله». لم يطلب دليلًا ولم يؤجل. طاعته كانت تصديقًا بالفعل. وربما يطلب منا الله اليوم أمرًا يبدو غير منطقي، لكنه خلاص لنا ولمن حولنا.\",\"p\":\"يا رب، امنحني إيمان نوح الذي يطيع قبل أن يرى. ثبّتني على الطريق الطويل. اجعل طاعتي سببًا لخلاص بيتي وكل من حولي. آمين.\"},{\"t\":\"الطاعة تخضع الوحوش\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أنطونيوس إن الطاعة مع الإمساك تخضع الوحوش. أي أن الذي يتعلم أن يطيع ويضبط نفسه يصير أقوى من كل ما يخيفه. جرّب اليوم أن تطيع بسرعة في أمر لا تحبه، وراقب كيف يتقوّى قلبك.\",\"p\":\"يا رب، علّمني الطاعة والإمساك، واخضع بهما وحوش أهوائي. أعطني قلبًا ينقاد لوصاياك بفرح. آمين.\",\"fq\":20}]},\"1-18\":{\"th\":\"الاستعداد لعيد الغطاس\",\"m\":[{\"t\":\"يقظةٌ تسبق النور\",\"ref\":\"قوموا يا بني النور — نصف الليل — الخدمة الأولى\",\"v\":\"قوموا يا بني النور لنسبح رب القوات، لكي ينعم علينا بخلاص نفوسنا، عندما نقف أمامك جسديا انزع من عقولنا نوم الغفلة. أعطنا يا رب يقظة لكي نفهم كيف نقف أمامك وقت الصلاة.\",\"r\":\"قبل عيد الغطاس تدعونا الكنيسة أن نقوم كبني النور وننزع من عقولنا نوم الغفلة. الاستعداد للعيد أن نصحو لما هو أثمن: حضور الله. اطلب اليوم يقظة ذهنية واحدة، كأن تنتبه لكلماتك وأفكارك في الصلاة.\",\"p\":\"يا رب، أنعم عليّ بيقظةٍ أقف بها أمامك وقت الصلاة. انزع من عقلي نوم الغفلة، واجعلني أحد بني النور. آمين.\"},{\"t\":\"توبة تسبق المعمودية\",\"ref\":\"متى ٣: ٨\",\"bk\":\"متى\",\"v\":\"فاصنعوا أثمارا تليق بالتوبة.\",\"r\":\"يوحنا لم يعتمد كل من جاء، بل صرخ في الفريسيين: «اصنعوا ثمرًا يليق بالتوبة». فالتوبة ليست شعورًا بالندم فقط بل تغيير يُرى. وقبل العيد، هذا السؤال موجه لي: ما هو الثمر الذي يشهد على أنني رجعت إلى الله؟ هل في علاقاتي وكلامي وقراراتي علامة جديدة؟\",\"p\":\"يا رب، لا أريد توبة بالكلام بل بالحياة. أعطني ثمرًا يليق بالتوبة. اشفِ ضعفي وقوِّ إرادتي، واقبلني إليك كل يوم من جديد. آمين.\"},{\"t\":\"الصحو أصل التقدم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أغاثون إنه بدون صحو كثير لا يستطيع الإنسان أن يتقدم ولا في فضيلة واحدة. الصحو هو أن أنتبه لما يحدث في داخلي. استعدادك للغطاس هذا الأسبوع يبدأ بأن تلاحظ أفكارك اليوم قبل أن تتصرف.\",\"p\":\"يا رب، امنحني صحوًا ويقظة. علّمني أن أراقب قلبي وأفكاري، وأتقدم في الفضيلة بنعمتك. آمين.\",\"fq\":59}]},\"1-19\":{\"th\":\"عيد الغطاس: معمودية ربنا\",\"m\":[{\"t\":\"تقدموا واستنيروا\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"تقدموا إليه واستنيروا، ووجوهكم لا تخزى.\",\"r\":\"في الغطاس يستنير الإنسان بالمسيح، وكل من يتقدم إليه لا يخزى. ليس المعمودية حدثًا مضى بل نور ما زال يضيء. تذكّر اليوم أنك ابن لله بالمعمودية، وأن هذه الهوية لا تتغير بتغير ظروفك.\",\"p\":\"يا رب، أتقدم إليك لأستنير، فلا تُخزِ وجهي. اجعلني أحيا بنور معموديتي، وأثبت في بنوّتي لك كل أيام حياتي. آمين.\"},{\"t\":\"ماء يقدّس الحياة\",\"ref\":\"رومية ٦: ٤\",\"bk\":\"رومية\",\"v\":\"فدفنا معه بالمعمودية للموت، حتى كما أقيم المسيح من الأموات، بمجد الآب، هكذا نسلك نحن أيضا في جدة الحياة؟\",\"r\":\"بولس يقول إننا دُفنا مع المسيح بالمعمودية لنسلك في جدّة الحياة. هذا ليس تشبيهًا فقط بل حقيقة سرائرية: شيء مات فيّ وشيء قام. ولكني أحتاج أن أعيش حسب هذه الحقيقة كل يوم، فأرفض ما دُفن وأتمسك بما قام.\",\"p\":\"يا رب، أشكرك على نعمة المعمودية. ميّت معك أنا عن الخطية، وقائم معك للحياة. ساعدني أن أسلك في جدّة الحياة كل يوم، وأن أعيش ما صرت إليه بنعمتك. آمين.\"},{\"t\":\"ثلاثة أمور يطلبها الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس غريغوريوس اللاهوتي إن الله يطلب ممن اقتبل المعمودية ثلاثة أمور: الإيمان القويم من كل النفس، والحقيقة من الفم، والتعقل من الجسد. اختر اليوم أمرًا واحدًا من الثلاثة لتتدرب عليه، وسيصير عيدك أثمر.\",\"p\":\"يا رب، أثبّتني في إيماني المستقيم، وافتح فمي للصدق، وعلّمني تعقّل الجسد. أنت الذي اقتبلتني بالمعمودية، أكمل عمل نعمتك. آمين.\",\"fq\":87}]},\"1-20\":{\"th\":\"حياة جديدة بالروح\",\"m\":[{\"t\":\"روحك لا تنزعه منا\",\"ref\":\"قطعة الثالثة (١)\",\"v\":\"روحك القدوس يا رب الذي أرسلته على تلاميذك القديسين ورسلك المكرمين، هذا لا تنزعه منا أيها الصالح، لكن جدده في أحشائنا. قلبا نقيا اخلق في يا الله، وروحا مستقيما جدد في أحشائي.\",\"r\":\"تصلي الكنيسة في الساعة الثالثة أن لا ينزع الله روحه القدوس بل يجدده في الأحشاء. الحياة الجديدة تتجدد كل يوم بتسليم القلب. اطلب اليوم قلبًا نقيًا في لحظة صلاة، واترك لله أن يخلقه كما يشاء.\",\"p\":\"يا رب، لا تنزع منا روحك القدوس بل جدده في أحشائنا. اخلق فيّ قلبًا نقيًا وروحًا مستقيمًا. آمين.\"},{\"t\":\"السير بالروح\",\"ref\":\"غلاطية ٥: ٢٥\",\"bk\":\"غلاطية\",\"v\":\"إن كنا نعيش بالروح، فلنسلك أيضا بحسب الروح.\",\"r\":\"الحياة بالروح ليست حالة ثابتة بل سير: خطوة بعد خطوة. وفي كل يوم أقف عند مفترقات صغيرة: أن أرد أو أصمت، أن أغفر أو أحتفظ، أن أصلي أو أؤجل. والسير بالروح هو أن أسأل في كل مفترق: ماذا تريدني أن أفعل يا رب؟\",\"p\":\"أيها الروح القدس، أريد أن أسير بك لا أن أكتفي بأنني أملكك. قدني في كل خطوة. أعطني أن أسمع صوتك الهادئ وأطيعه. آمين.\"},{\"t\":\"الروح كالمطر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب يوحنا الكولوفي نزول الروح القدس بالمطر: عندما ينزل في القلوب تتجدد وتخرج براعم بمخافة الله. التجديد عمل الله، وعلينا أن نكون أرضًا مفتوحة. افتح قلبك اليوم لصلاة قصيرة تطلب فيها حلول الروح.\",\"p\":\"أيها الروح القدس، انزل في قلبي كالمطر، وأنبت فيّ براعم مخافة الله. جدّد حياتي، وأعد لي نضارة البدء. آمين.\",\"fq\":153}]},\"1-21\":{\"th\":\"مريم: حفظت كل هذه الأمور\",\"m\":[{\"t\":\"أم النور المكرّمة\",\"ref\":\"قطعة باكر (٣)\",\"v\":\"أنت هي أم النور المكرمة، يا والدة الإله... لأن الآب اختارك، والروح القدس ظللك. والابن تنازل وتجسد منك.\",\"r\":\"تذكر الكنيسة العذراء بالتمجيد لأن الآب اختارها والروح القدس ظللها والابن تجسد منها. قبلت دعوة الله بصمت وتأمل. تأمّل اليوم كيف يمكن أن تقبل أنت دعوة الله في أمرٍ صغير، بقلب مصغٍ كقلبها.\",\"p\":\"أيتها العذراء والدة الإله، اسألي المسيح من أجلنا. علّمينا أن نحفظ كلمة الله في القلب، ونقبل مشيئته بإيمان وصمت. آمين.\"},{\"t\":\"مريم في عرس قانا\",\"ref\":\"يوحنا ٢: ٥\",\"bk\":\"يوحنا\",\"v\":\"قالت أمه للخدام: «مهما قال لكم فافعلوه».\",\"r\":\"في قانا رأت مريم حاجة العروسين قبل أن يطلب أحد. رفعتها إلى ابنها بلا ضغط ولا تفاصيل، ثم قالت للخدام كلمة واحدة: افعلوا ما يقوله. هكذا تعلّمنا أن نصلي: نعرض الحاجة ثم نسلّم الطريقة. والطاعة بعد ذلك تفتح باب المعجزة.\",\"p\":\"يا رب يسوع، بشفاعة أمك العذراء أعرض عليك حاجتي. علّمني أن أطيعك دون أن أفهم، وأن أنتظر عملك بثقة. حوّل ماء حياتي إلى خمر فرحك. آمين.\"},{\"t\":\"أن يكون إصغاؤك أكثر من كلامك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب نيسثروس أن الإصغاء أولى من الكلام في المناقشة، وأن من لا يشعر بالراحة في كلامه فالصمت أفضل. العذراء كانت تحفظ الأمور في قلبها. في حوارٍ ما اليوم، انتظر لحظة قبل أن تجيب.\",\"p\":\"يا رب، علّمني الإصغاء قبل الكلام. وبشفاعة العذراء اجعلني أحفظ كلمتك في قلبي وأتكلم بما ينفع. آمين.\",\"fq\":299}]},\"1-22\":{\"th\":\"حفظ اللسان\",\"m\":[{\"t\":\"صُن لسانك عن الشر\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"صن لسانك عن الشر، وشفتيك عن النطق بالغش. حد عن الشر واصنع الخير. اطلب السلامة واتبعها.\",\"r\":\"يربط المرنم الحياة الصالحة بحفظ اللسان: صن لسانك، حد عن الشر، اطلب السلامة. الكلمة تصنع حياة أو تهدمها. تدرّب اليوم على أن تتأنى قبل كل جملة جارحة، وتستبدلها بصمت أو بكلمة طيبة.\",\"p\":\"يا رب، صن لساني عن الشر وشفتيّ عن الغش. علّمني أن أحيد عن الشر وأصنع الخير، وأطلب السلامة وأتبعها. آمين.\"},{\"t\":\"كلام يُصلح\",\"ref\":\"أفسس ٤: ٢٩\",\"bk\":\"أفسس\",\"v\":\"لا تخرج كلمة ردية من أفواهكم، بل كل ما كان صالحا للبنيان، حسب الحاجة، كي يعطي نعمة للسامعين.\",\"r\":\"الكلمة الطيبة صدقة كما يقول الآباء. وقد لا ندرك كم يحتاج الناس إلى كلمة تشجيع. زميل متعب، أو أم في البيت، أو صديق وحيد. بكلمة واحدة صادقة قد أعطي أحدهم قوة ليوم كامل. فهل أقول اليوم كلمة تبني؟\",\"p\":\"يا رب، علّمني أن أستخدم كلامي لأبني لا لأهدم. أعطني عينًا ترى حاجة الآخرين وفمًا يقول الكلمة الصالحة في وقتها. اجعل شفتيّ ينبوع نعمة. آمين.\"},{\"t\":\"استرني من لساني\",\"ref\":\"\",\"v\":\"\",\"r\":\"صلاة الأب سيسوى بسيطة وصادقة: «استرني من لساني لأني بسببه أسقط كل يوم». لا يدّعي القوة بل يطلب الستر. اجعل هذه الصلاة بداية يومك، وأعطها لنفسك كلما همّت بالكلام الجارح.\",\"p\":\"يا ربي يسوع المسيح، استرني من لساني، لأني بسببه أسقط وأخطئ. ضع حافظًا لفمي وبابًا حصينًا لشفتيّ. آمين.\",\"fq\":486}]},\"1-23\":{\"th\":\"الصلاة بلا ملل\",\"m\":[{\"t\":\"إذ دعوت استجبتَ لي\",\"ref\":\"المزمور الرابع — باكر\",\"v\":\"إذ دعوت استجبت لي يا إله بري. في الشدة فرجت عنى. تراءف على يا رب واسمع صلاتي.\",\"r\":\"يقول المرنم إن الله استجاب حين دعاه، وفرّج عنه في الشدة. الذي يذكر استجابات الأمس يواصل الصلاة اليوم. اكتب في ذهنك ثلاث مرات استجاب الله لك فيها، وارفع بعدها طلبك الحالي بثقة.\",\"p\":\"يا إله برّي، إذ دعوتُك استجبتَ لي، وفي الشدة فرّجت عني. تراءف عليّ واسمع صلاتي، وعلّمني ألا أمل من الدعاء. آمين.\"},{\"t\":\"القاضي الظالم والأرملة\",\"ref\":\"لوقا ١٨: ١\",\"bk\":\"لوقا\",\"v\":\"وقال لهم أيضا مثلا في أنه ينبغي أن يصلى كل حين ولا يمل،\",\"r\":\"الأرملة لم تملك مالًا ولا نفوذًا، بل إصرارًا. وكلما أغلق القاضي بابه كانت تعود. المسيح يريد أن نصلي بالإصرار نفسه، لا لأن الله قاسٍ أو يحتاج إلى إقناع، بل لأن الإصرار يربي إيماننا ويعلّمنا أن نطلب ما يستحق أن نطلبه حقًا.\",\"p\":\"يا رب، علّمني ألا أملّ من الصلاة. قوِّ إيماني حين يتأخر الجواب. أشكرك لأنك تسمع وتنصف، وأنك أعدل وأرحم من كل قاضٍ. آمين.\"},{\"t\":\"أصلّي وأنا أعمل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يردّ الأب لوكيوس على من يظنون أن الصلاة تعطّل العمل بأنه يصلّي بدون انقطاع وهو يحوك الخوص، مردّدًا: «ارحمني يا الله كعظيم رحمتك». يمكنك أن تحول عملك كله إلى صلاة بكلمة قصيرة تكررها.\",\"p\":\"يا الله، ارحمني كعظيم رحمتك وكمثل كثرة رأفتك. اجعل عملي كله صلاةً ترتفع إليك بلا انقطاع. آمين.\",\"fq\":226}]},\"1-24\":{\"th\":\"إيمان مثل حبة الخردل\",\"m\":[{\"t\":\"آمنتُ لذلك تكلمت\",\"ref\":\"المزمور ١١٥ — التاسعة\",\"v\":\"آمنت لذلك تكلمت. وأنا اتضعت جدا.\",\"r\":\"ينطق المرنم بإيمان لا يخلو من اعتراف بالضعف: آمنت، وأنا اتضعت جدًا. الإيمان لا يعني غياب الشك، بل أن نتكلم مع الله وسط الشك. قل اليوم لله بصراحة ما يخيفك، وأضف إليه: لكني أؤمن بك.\",\"p\":\"يا رب، آمنت لذلك تكلمت. أنا اتضعت جدًا أمامك، فاقبل إيماني القليل وزده، وأعن عدم إيماني. آمين.\"},{\"t\":\"أؤمن يا رب فأعن عدم إيماني\",\"ref\":\"مرقس ٩: ٢٤\",\"bk\":\"مرقس\",\"v\":\"فللوقت صرخ أبو الولد بدموع وقال: «أومن يا سيد، فأعن عدم إيماني».\",\"r\":\"هذا الأب لم يقل: أؤمن بالكامل. بل قال: «أؤمن فأعن عدم إيماني». كانت صلاته صادقة بشكل مؤثر. اعترف بالإيمان والشك معًا. والمسيح لم يوبخه بل شفى ابنه. فلا تخجل أن تصلي بقلب فيه أسئلة وشكوك. الله يقبل الإيمان الناقص ويكمله.\",\"p\":\"يا رب، أؤمن، فأعن عدم إيماني. أنا أحمل إليك شكوكي وأسئلتي بدل أن أهرب منك. قوِّ ثقتي بك، وأعطني أن أراك في كل موقف. آمين.\"},{\"t\":\"الإيمان ثمر التواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعرّف الأب بيمن الإيمان بأن يسلك الإنسان بتواضع ويفعل الصدقة، لأن الإيمان والإحسان يمحوان الخطايا. هكذا يبدو الإيمان عملًا بسيطًا. اختر اليوم عملًا صغيرًا من الإحسان تقوم به بتواضع.\",\"p\":\"يا رب، أعطني إيمانًا يعمل بالمحبة، وتواضعًا يخدم بلا ضجيج. وليكن إحساني اليوم شهادةً لك. آمين.\",\"fq\":365}]},\"1-25\":{\"th\":\"الرحمة تنتصر\",\"m\":[{\"t\":\"رؤوفٌ ورحيم\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"وأنت أيها الرب الإله أنت رؤوف ورحيم. أنت طويل الروح؛ وكثير الرحمة وصادق.\",\"r\":\"يصف المرنم الله بأنه رؤوف رحيم طويل الروح كثير الرحمة. الرحمة التي نأخذها منه هي التي نتعلم أن نعطيها. فكّر في إنسان تأخرتَ في رحمته، وأعطه اليوم فرصة أخرى كما أعطاك الله فرصًا كثيرة.\",\"p\":\"يا رب، أنت رؤوف ورحيم طويل الروح كثير الرحمة. اجعلني رحيمًا بالآخرين كما رحمتني، وطويل الأناة على من أساء إليّ. آمين.\"},{\"t\":\"السامري الصالح\",\"ref\":\"لوقا ١٠: ٣٣\",\"bk\":\"لوقا\",\"v\":\"ولكن سامريا مسافرا جاء إليه، ولما رآه تحنن،\",\"r\":\"الكاهن واللاوي رأيا الجريح وعبرا. أما السامري فـ«رآه فتحنن». الفرق بين الثلاثة لم يكن المعرفة الدينية بل القلب. الرحمة تبدأ بأن أسمح لعيني أن ترى وتتأثر. وأحيانًا أمر على حاجة قريبة مني لأني مشغول، فيسألني المسيح: ومن هو قريبك؟\",\"p\":\"يا رب يسوع، يا سامري نفوسنا، أشكرك لأنك تحننت عليّ. اجعل عيني ترى المحتاجين وقلبي يتحرك نحوهم. لا تدعني أمرّ بجانب أحد دون أن أرحمه. آمين.\"},{\"t\":\"كن رحيمًا نحو الجميع\",\"ref\":\"\",\"v\":\"\",\"r\":\"وصية الأب بمفو للأب ثيوذورس واضحة: «اذهب وكن رحيمًا نحو الجميع، لأن الرحمة قد وجدت حظوة في عيني الرب». ما أبسط الوصية وما أعمق أثرها! اجعل رحمتك اليوم تتجاوز من تحبهم إلى من يصعب عليك حبهم.\",\"p\":\"يا رب، اجعلني رحيمًا نحو الجميع، وأعطني أن أجد حظوة في عينيك برحمتي. وارحمني أنا أيضًا كعظيم رحمتك. آمين.\",\"fq\":465}]},\"1-26\":{\"th\":\"الخدمة بمحبة\",\"m\":[{\"t\":\"اعبدوا الرب بالفرح\",\"ref\":\"المزمور ٩٩ (١٠٠) — التاسعة\",\"v\":\"اعبدوا الرب بالفرح، ادخلوا أمامه بالتهليل. اعلموا أن الرب هو إلهنا، هو صنعنا وليس نحن، ونحن شعبه وغنم رعيته.\",\"r\":\"الخدمة في كلمات المرنم عبادة بفرح ودخول بتهليل، فنحن شعبه وغنم رعيته. الخادم الذي ينسى أنه من الغنم يتعب، والذي يتذكر يخدم بسرور. خدمتك اليوم، مهما صغرت، يمكن أن تكون عبادة إن قمت بها بقلب فرح.\",\"p\":\"يا رب، أعبدك بالفرح وأدخل أمامك بالتهليل. أعلم أنك إلهي وأنني من غنم رعيتك، فاجعل خدمتي ثمرة فرحي بك. آمين.\"},{\"t\":\"كل واحد بحسب الموهبة\",\"ref\":\"بطرس الأولى ٤: ١٠\",\"bk\":\"بطرس الأولى\",\"v\":\"ليكن كل واحد بحسب ما أخذ موهبة، يخدم بها بعضكم بعضا، كوكلاء صالحين على نعمة الله المتنوعة.\",\"r\":\"ليس هناك مؤمن بلا موهبة. قد لا أراها لأنها بسيطة: قدرة على الاستماع، أو ترتيب، أو ابتسامة، أو صبر على الصغار. وبطرس يقول إنها نعمة الله المتنوعة، وأنا وكيل عليها. فالسؤال ليس هل لدي موهبة، بل هل أستخدمها لأخدم به غيري؟\",\"p\":\"يا رب، أشكرك على المواهب التي أعطيتني. اغفر لي إخفاءها وتقليلي منها. علّمني أن أخدم بها بأمانة وتواضع، لمجد اسمك ولبنيان كنيستك. آمين.\"},{\"t\":\"ننحني لله في أخينا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّمنا الأب أبو للوس أن ننحني للإخوة الذين يأتون إلينا لأننا لا ننحني لهم إنما لله، فإذا رأيت أخاك رأيت الرب إلهك. هذه نظرة خدمة جديدة. استقبل اليوم من يطرق بابك أو يطلب منك شيئًا كأنه ضيف المسيح.\",\"p\":\"يا رب، علّمني أن أرى وجهك في وجه أخي، وأخدمه بتواضع كمن يخدمك. آمين.\",\"fq\":77}]},\"1-27\":{\"th\":\"الحكمة من فوق\",\"m\":[{\"t\":\"رأس الحكمة\",\"ref\":\"المزمور ١١٠ (١١١) — التاسعة\",\"v\":\"رأس الحكمة مخافة الرب. والفهم صالح لكل من يعمل به؛ وتسبحته دائمة إلى الأبد هلليلويا.\",\"r\":\"يضع المرنم نقطة البداية: مخافة الرب، ثم الفهم الصالح لمن يعمل به. الحكمة ليست معلومات بل عمل. اسأل نفسك اليوم عن أمرٍ تعرف الصواب فيه ولا تعمل به، وابدأ في تنفيذه بخطوة واحدة.\",\"p\":\"يا رب، ضع في قلبي مخافتك رأسًا للحكمة. وأعطني فهمًا صالحًا أعمل به، فتكون تسبحتك دائمة في فمي. آمين.\"},{\"t\":\"سليمان يطلب قلبًا فهيمًا\",\"ref\":\"الملوك الأول ٣: ٩\",\"bk\":\"الملوك الأول\",\"v\":\"فأعط عبدك قلبا فهيما لأحكم على شعبك وأميز بين الخير والشر، لأنه من يقدر أن يحكم على شعبك العظيم هذا؟»\",\"r\":\"لو أتاك الله وقال: اطلب ماذا أعطيك؟ فما الذي ستقوله؟ سليمان كان شابًا وملكًا وأمامه كل الخيارات. لكنه طلب قلبًا فاهمًا. وهذا يكشف تواضعه: اعترف أنه صغير وأن المسؤولية أكبر منه. والله أعطاه ما طلب وزاده ما لم يطلب.\",\"p\":\"يا رب، أنا فتى صغير لا أعرف كيف أخرج وأدخل. أعطني قلبًا فهيمًا يميز بين الخير والشر. وليكن كل ما أطلبه لمجدك وخير شعبك. آمين.\"},{\"t\":\"فضيلة التمييز\",\"ref\":\"\",\"v\":\"\",\"r\":\"يلفت القديس أنطونيوس النظر إلى أناس أفنوا أجسادهم بالنسك وبقوا بعيدين عن الله لأنهم لم يقتنوا فضيلة التمييز. الحماس بغير حكمة قد يضر. قبل أن تقرر في أمر مهم اليوم، اسأل مرشدك أو صلِّ طالبًا التمييز.\",\"p\":\"يا رب، هب لي روح التمييز. احفظني من الحماس الأعمى، واجعل أعمالي كلها بحكمة تقودني إليك. آمين.\",\"fq\":6}]},\"1-28\":{\"th\":\"الثبات في التجارب\",\"m\":[{\"t\":\"اضطجعتُ ونمتُ فاستيقظت\",\"ref\":\"المزمور الثالث — باكر\",\"v\":\"أنا اضطجعت ونمت، ثم استيقظت لأن الرب ناصري. فلا أخاف من ربوات الجموع المحيطين بي القائمين على.\",\"r\":\"ينام المرنم وسط جموع محيطة به ثم يستيقظ آمنًا لأن الرب ناصره. الثبات في التجارب لا يعني غياب الأعداء بل حضور الناصر. في موقفٍ يحاصرك اليوم، قل: الرب ناصري، وانتبه كيف يتغير ثقل الجموع في قلبك.\",\"p\":\"يا رب، أنت ناصري فلا أخاف من ربوات الجموع المحيطين بي. ثبّتني في التجارب، وأيقظني دائمًا في حفظك. آمين.\"},{\"t\":\"لا تجربة إلا بشرية\",\"ref\":\"كورنثوس الأولى ١٠: ١٣\",\"bk\":\"كورنثوس الأولى\",\"v\":\"لم تصبكم تجربة إلا بشرية. ولكن الله أمين، الذي لا يدعكم تجربون فوق ما تستطيعون، بل سيجعل مع التجربة أيضا المنفذ، لتستطيعوا أن تحتملوا.\",\"r\":\"حين أتألم أشعر أن أحدًا لا يفهمني وأن الحمل فوق طاقتي. لكن الكتاب يقول إن كل من مرّوا بمثل ما أمر به، والله أمين: لا يسمح بتجربة تفوق احتمالي، ويفتح مخرجًا. هذه ليست كلمات سهلة، لكنها وعد من الله الذي لا يكذب.\",\"p\":\"يا رب، أنت أمين ولا تسمح بتجربة فوق طاقتي. افتح لي المنفذ، وقوِّ قلبي. اجعلني أسهر وأقاوم بإيمان، وأعبر كل شدة بنعمتك. آمين.\"},{\"t\":\"يوسف وأيوب\",\"ref\":\"\",\"v\":\"\",\"r\":\"حين تعب أخ قلبه، ذكّره الأب بيمن بيوسف الشاب الذي قاوم التجربة حتى النهاية وبأيوب الذي تمسك بالصبر ولم يتزعزع رجاؤه. الثبات يُتعلّم من الذين سبقونا. اذكر اليوم قصة قديس ثبت في تجربة تشبه تجربتك.\",\"p\":\"يا رب، كما ثبّت يوسف وأيوب ثبّتني في تجاربي، وامنحني رجاءً لا يتزعزع بك. آمين.\",\"fq\":387}]},\"1-29\":{\"th\":\"الراحة في الرب\",\"m\":[{\"t\":\"ارجعي يا نفسي إلى راحتك\",\"ref\":\"المزمور ١١٤ — التاسعة\",\"v\":\"ارجعي يا نفسي إلى موضع راحتك، لأن الرب قد أحسن إلى، وأنقذ نفسي من الموت وعيني من الدموع ورجلي من الزلل، أرضي الرب أمامه في كورة الأحياء.\",\"r\":\"يدعو المرنم نفسه أن ترجع إلى موضع راحتها، لأن الرب أحسن إليه وأنقذه. راحة النفس ليست في زيادة الإنجاز بل في الرجوع إلى المحسن. خصّص اليوم عشر دقائق راحة بلا شاشات لتشكر الله على إنقاذه لك.\",\"p\":\"ارجعي يا نفسي إلى موضع راحتك لأن الرب قد أحسن إليّ. أنقذ نفسي وعيني ورجلي، وأعطني أن أسير أمامك في كورة الأحياء. آمين.\"},{\"t\":\"سلامًا أترك لكم\",\"ref\":\"يوحنا ١٤: ٢٧\",\"bk\":\"يوحنا\",\"v\":\"«سلاما أترك لكم. سلامي أعطيكم. ليس كما يعطي العالم أعطيكم أنا. لا تضطرب قلوبكم ولا ترهب.\",\"r\":\"العالم يعطي سلامًا مشروطًا: إذا سارت الأمور بخير. أما المسيح فيعطي سلامه وسط الضيق. هو سلام إنسان يعرف أن الله يمسك به. ولهذا يقول: لا تضطرب قلوبكم ولا ترهب. هذه وصية ووعد معًا، تُمارَس بالإيمان.\",\"p\":\"يا رب، أشكرك على سلامك الذي لا يشبه سلام العالم. احرس قلبي من الاضطراب. أعطني أن أحمل سلامك إلى بيتي وعملي وكل من ألقاه. آمين.\"},{\"t\":\"اطرح ضعفك أمام الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"جواب القديس أغاثون لأخ ضعيف: «اذهب واطرح ضعفك أمام الله تجد راحة». لا يطلب منه أن يصير قويًا أولًا. الراحة تأتي حين نعترف بالضعف بلا خجل. ضع اليوم أمام الله أكثر شيء يتعبك.\",\"p\":\"يا رب، أطرح أمامك ضعفي، وأطلب منك الراحة. خذ ما يتعبني وأعطني سلامك. آمين.\",\"fq\":55}]},\"1-30\":{\"th\":\"عناية الله بنا\",\"m\":[{\"t\":\"الرب يحفظك\",\"ref\":\"المزمور ١٢٠ (١٢١) — الغروب\",\"v\":\"الرب يحفظك. الرب يظلل على يدك اليمنى، فلا تحرقك الشمس بالنهار ولا القمر بالليل. الرب يحفظك من كل سوء.\",\"r\":\"كرّر المرنم عبارة «الرب يحفظك» كما يردد الأب كلمة طمأنينة لابنه. عناية الله تظلّل اليد اليمنى بالنهار والليل. ما الذي يقلقك على الغد؟ اجلس اليوم وقل مرة بعد مرة: الرب يحفظني من كل سوء.\",\"p\":\"يا رب، أنت حافظي وظلي على يدي اليمنى. احفظني من كل سوء، واحفظ دخولي وخروجي من الآن وإلى الأبد. آمين.\"},{\"t\":\"أعرف الخطط\",\"ref\":\"إرميا ٢٩: ١١\",\"bk\":\"إرميا\",\"v\":\"لأني عرفت الأفكار التي أنا مفتكر بها عنكم، يقول الرب، أفكار سلام لا شر، لأعطيكم آخرة ورجاء.\",\"r\":\"هذه الآية قيلت للمسبيّين في بابل، أي لشعب يعاني ويعيش بعيدًا عن بيته. لم يقل لهم الله إن الأمر سينتهي غدًا، بل إنه يعرف خططه لهم. أحيانًا أعيش في «بابل» خاصة بي، فأحتاج أن أتذكر أن لله خطة هناك أيضًا.\",\"p\":\"يا رب، أنت تعرف الأفكار التي تفكرها نحوي، أفكار سلام لا شر. ثبّتني في رجائك حتى حين أكون في الغربة. علّمني أن أزرع وأبني حيث وضعتني. آمين.\"},{\"t\":\"إن لم يهتم الله بي\",\"ref\":\"\",\"v\":\"\",\"r\":\"سؤال الأب دانيال صادم: «إذا كان الله لا يهتم بي، لماذا أحيا؟». وهو في الحقيقة اعتراف بأن حياتنا كلها قائمة على اهتمام الله. تأمّل في الأمور التي تتوالى كل يوم دون أن تلاحظها، فهي دليل رعايته.\",\"p\":\"يا رب، شكرًا لأن عنايتك تحمل حياتي كل يوم حتى حين لا أراها. ثبّتني في الثقة بأنك تهتم بي. آمين.\",\"fq\":93}]},\"1-31\":{\"th\":\"ختام الشهر: شكر وتسليم\",\"m\":[{\"t\":\"نشكرك على هذا اليوم\",\"ref\":\"تحليل الغروب\",\"v\":\"نشكرك يا ملكنا المتحنن لأنك منحتنا أن نعبر هذا اليوم بسلام وأتيت بنا إلى المساء شاكرين: وجعلتنا مستحقين أن ننظر النور إلى المساء.\",\"r\":\"في ختام الشهر نقف مع الكنيسة وقت الغروب لنشكر أن عبرنا اليوم بسلام ووصلنا إلى المساء. الشكر عند نهاية اليوم يغلق صفحته بسلام. اكتب الليلة بضع كلمات عن شهر يناير تشكر الله فيها، ثم سلّم ما بقي له.\",\"p\":\"نشكرك يا ملكنا المتحنن لأنك منحتنا أن نعبر هذا اليوم بسلام. تقبّل شكرنا وسلامنا، واجعل الشهر القادم أقرب إليك. آمين.\"},{\"t\":\"لتكن مشيئتك\",\"ref\":\"متى ٢٦: ٣٩\",\"bk\":\"متى\",\"v\":\"ثم تقدم قليلا وخر على وجهه، وكان يصلي قائلا: «يا أبتاه، إن أمكن فلتعبر عني هذه الكأس، ولكن ليس كما أريد أنا بل كما تريد أنت».\",\"r\":\"في ليلة آلامه، لم يخفِ المسيح خوفه. قال: «إن أمكن فلتعبر عني هذه الكأس». ثم أكمل: «ولكن ليس كما أريد أنا بل كما تريد أنت». الصلاة الحقيقية لا تلغي رغباتي بل تعرضها بصدق ثم تسلّمها. هذا التسليم لا يعني ضعفًا بل أعلى درجات الثقة.\",\"p\":\"يا أبتاه، إن شئت فاجعل ما أتألم منه يعبر. ولكن ليكن لا كما أريد أنا بل كما تريد أنت. قوّني بروحك لأقبل مشيئتك بسلام وأمضي فيها بثقة. آمين.\"},{\"t\":\"أن يرمي الإنسان نفسه أمام الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعرّف الأب بيمن أدوات النفس بأن يرمي الإنسان نفسه أمام الله ولا يعتبر نفسه شيئًا وأن يهمل مشيئته. هذا هو التسليم الذي يليق بختام شهر: أن نضع كل ما أنجزنا أو فشلنا فيه عند قدمي الله ونمضي بسلام.\",\"p\":\"يا رب، أرمي نفسي أمامك بلا تردد. خذ ما مضى وما سيأتي، وليكن لي مشيئتك وسلامك. آمين.\",\"fq\":334}]},\"2-1\":{\"th\":\"الوداعة قوة\",\"m\":[{\"t\":\"يهدي الودعاء في الحكم\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"الرب صالح ومستقيم، لذلك يرشد الذين يخطئون في الطريق. يهدى الودعاء في الحكم؛ يعلم الودعاء طرقه.\",\"r\":\"الوداعة في كلمات المرنم ليست ضعفًا، فالله نفسه يهدي الودعاء ويعلّمهم طرقه. من يملك نفسه أقوى ممن يملك الكلمة الأخيرة. جرّب اليوم أن تجيب بهدوء على كلمة تستفزك، وراقب كيف يهدئ الله ما بداخلك.\",\"p\":\"يا رب، أنت صالح ومستقيم، فأرشدني وأنا أخطئ الطريق. اهدني بوداعتك، وعلّمني طرقك التي تنتهي كلها برحمة وحق. آمين.\"},{\"t\":\"روح وديعة هادئة\",\"ref\":\"بطرس الأولى ٣: ٤\",\"bk\":\"بطرس الأولى\",\"v\":\"بل إنسان القلب الخفي في العديمة الفساد، زينة الروح الوديع الهادئ، الذي هو قدام الله كثير الثمن.\",\"r\":\"نهتم كثيرًا بما يراه الناس: المظهر والصورة والانطباع. لكن الله ينظر إلى القلب. وجمال الروح الوديعة الهادئة لا يذبل بالزمن ولا يحتاج إلى تحديث. فما الذي أستثمر فيه أكثر: زينتي الخارجية أم قلبي المخفي؟\",\"p\":\"يا رب، علّمني أن أهتم بجمال قلبي أكثر من ظاهري. أعطني روحًا وديعة هادئة ثمينة أمامك. جمّل نفسي بنعمتك. آمين.\"},{\"t\":\"الصلاة برعم الوداعة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يربط الأب نيلوس بين الصلاة والوداعة: الصلاة برعم الوداعة وعدم الغضب. من يصلي بصدق يلين قلبه تدريجيًا. اجعل صلاتك اليوم قبل لقاء يوترك، وانظر كيف تخفّ حدّتك.\",\"p\":\"يا رب، اجعل صلاتي تُثمر في قلبي وداعةً وسلامًا. انزع غضبي، وأعطني لسانًا هادئًا في مواجهة كل ضغط. آمين.\",\"fq\":289}]},\"2-2\":{\"th\":\"بيت مبني على الرب\",\"m\":[{\"t\":\"إن لم يبنِ الرب البيت\",\"ref\":\"المزمور ١٢٦ (١٢٧) — الغروب\",\"v\":\"إن لم يبن الرب البيت فباطلا تعب البناءون، وإن لم يحرس الرب المدينة فباطلا سهر الحراس. باطل هو لكم التبكير. انهضوا من بعد جلوسكم يا آكلي الخبز بالهموم، فإنه يمنح أحباءه نوما.\",\"r\":\"كل بيت يُبنى على التعب وحده، مهما كثر السهر والتبكير، يظل ناقصًا من غير الرب. المرنم يذكّرنا أن نوم الطمأنينة هبة يمنحها الله لأحبائه. قبل أن تبدأ مشاغل بيتك اليوم، ضعها كلها في يد الرب صراحةً بصلاة قصيرة.\",\"p\":\"يا رب، ابنِ بيتي ولا تتركني أتعب باطلًا. احرس أسرتي، وامنحنا نومًا هادئًا وقلبًا مطمئنًا في رعايتك. آمين.\"},{\"t\":\"أنا وبيتي نعبد الرب\",\"ref\":\"يشوع ٢٤: ١٥\",\"bk\":\"يشوع\",\"v\":\"وإن ساء في أعينكم أن تعبدوا الرب، فاختاروا لأنفسكم اليوم من تعبدون: إن كان الآلهة الذين عبدهم آباؤكم الذين في عبر النهر، وإن كان آلهة الأموريين الذين أنتم ساكنون في أرضهم. وأما أنا وبيتي فنعبد الرب».\",\"r\":\"قال يشوع للشعب: «اختاروا لأنفسكم اليوم من تعبدون». ثم أعلن موقفه بلا تردد. لا يمكن أن نعبد الله بنصف قلب ونطلب أن يكون بيتنا كله له. القرار يبدأ منّي، وأولادي وأسرتي يرون كيف أعيشه قبل أن يسمعوا ما أقوله.\",\"p\":\"يا رب، أنا أختارك إلهًا لي ولبيتي. انزع من حياتي كل ما ينافسك. اجعل بيتي مكانًا يُعبد فيه اسمك ويُشهد لك. آمين.\"},{\"t\":\"الأساس هو القريب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّمنا الأب يوحنا الكولوفي أن البيت لا يُبنى من أعلى إلى أسفل، بل من الأساس، والأساس هو القريب الذي ينبغي أن نربحه. فبيتك الروحي لا يقوم على أعمال عظيمة فقط، بل على علاقة طيبة بمن حولك. ابدأ اليوم من أقرب شخص إليك.\",\"p\":\"يا رب، ثبّت بيتي على أساس المحبة. علّمني أن أربح قريبي أولًا، فيقوم ما أبنيه على وصاياك. آمين.\",\"fq\":165}]},\"2-3\":{\"th\":\"التلمذة والنمو\",\"m\":[{\"t\":\"وباسم إلهنا ننمو\",\"ref\":\"المزمور ١٩ (٢٠) — الثالثة\",\"v\":\"وباسم إلهنا ننمو. يكمل الرب كل سؤالك. الآن علمت أن الرب قد خلص مسيحه؛ واستجاب له من سماء قدسه بجبروت خلاص يمينه.\",\"r\":\"النمو في الحياة الروحية ليس عملية سريعة، لكنه يحدث «باسم إلهنا»، أي بقوته وحضوره. المرنم يعلن أن الرب يكمل كل سؤال. اسأل نفسك: في أي جانب من حياتي أريد أن أنمو هذا الشهر؟ وارفعه إلى الله بصلاة محددة.\",\"p\":\"يا رب، باسمك ننمو، فأكمل كل سؤال قلبي. استجب لي من سماء قدسك، وانمِ فيّ ما غرسته بنعمتك. آمين.\"},{\"t\":\"قدّام قدمي المعلم\",\"ref\":\"لوقا ١٠: ٣٩\",\"bk\":\"لوقا\",\"v\":\"وكانت لهذه أخت تدعى مريم، التي جلست عند قدمي يسوع وكانت تسمع كلامه.\",\"r\":\"كانت مرثا مشغولة بالخدمة، ومريم جالسة عند قدمي يسوع. ومرثا اشتكت، فأجابها المسيح بلطف: «أنتِ تهتمين بأمور كثيرة، ولكن الحاجة إلى واحد». لا يلوم الخدمة، لكنه يضع الأولويات: أن أجلس أولًا، ثم أخدم من الامتلاء.\",\"p\":\"يا رب، علّمني أن أجلس عند قدميك قبل أن أخدم. اغفر لي انشغالي بالكثير. أعطني النصيب الصالح الذي لا ينزع مني. آمين.\"},{\"t\":\"من الصباح حتى المساء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ألونيوس إن الإنسان إذا أراد يستطيع أن يصل إلى القامة الإلهية من الصباح حتى المساء. هذه الجملة تحمل تحديًا ورجاءً: ليس النمو حكرًا على الزمن الطويل، فاليوم الواحد قد يغيّرنا حين نقرر. ما قرارك الواحد اليوم؟\",\"p\":\"يا رب، أعطني إرادةً جادة وقوة في يومي هذا. ليكن لي نمو حقيقي من الصباح حتى المساء بنعمتك. آمين.\",\"fq\":74}]},\"2-4\":{\"th\":\"الشجاعة بالرب\",\"m\":[{\"t\":\"إن يحاربني جيش\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"إن يحاربني جيش فلن يخاف قلبي. وإن قام على قتال ففي هذا أنا أطمئن.\",\"r\":\"الشجاعة عند المرنم ليست أن تغيب الحرب، بل ألا يخاف القلب وسطها لأن الرب نوره وحصنه. اكتب الآن أكثر ما يقلقك، وقل أمام الله: إن حاربني هذا فلن يخاف قلبي، لأنك معي. ثم ابدأ يومك.\",\"p\":\"يا رب، أنت نوري وخلاصي وحصن حياتي، فممن أخاف؟ إن حاربني جيش فلن يخاف قلبي، ففي هذا أنا مطمئن بك. آمين.\"},{\"t\":\"داود وجليات\",\"ref\":\"صموئيل الأول ١٧: ٤٥\",\"bk\":\"صموئيل الأول\",\"v\":\"فقال داود للفلسطيني: «أنت تأتي إلي بسيف وبرمح وبترس، وأنا آتي إليك باسم رب الجنود إله صفوف إسرائيل الذين عيرتهم.\",\"r\":\"أمام جليات، لم يكن لداود سيف ولا درع. كان معه اسم الرب وخبرة سابقة مع الله في مواجهة الأسد والدب. وهذا درس: الإيمان يتغذى بالذكريات. من تذكّر كيف أنقذه الله سابقًا واجه التحدي الحالي بثقة.\",\"p\":\"يا رب القوات، أنا أواجه جبابرة لا أقوى عليهم. أذكّرني بما فعلته معي في الماضي. اجعل المعركة لك، وأنا أسير باسمك. آمين.\"},{\"t\":\"أحبه فلا أخافه\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أنطونيوس: «أنا لا أخاف الله أبدًا إنما أحبه، لأن المحبة تطرد الخوف خارجًا». حين نحب الله، يتحول الخوف من العقاب إلى شوق للقاء. اسأل نفسك هل تقف أمام الله اليوم بخوف المذنب أم بمحبة الابن؟\",\"p\":\"يا رب، علّمني أن أحبك فيطرد حبك الخوف من قلبي. وكن شجاعتي في كل يوم أواجه فيه ما يخيفني. آمين.\",\"fq\":17}]},\"2-5\":{\"th\":\"الرجاء في الضعف\",\"m\":[{\"t\":\"ارحمني فإني ضعيف\",\"ref\":\"المزمور السادس — باكر\",\"v\":\"ارحمني يا رب فإني ضعيف. اشفني يا رب فإن عظامي قد اضطربت ونفسي قد انزعجت جدا.\",\"r\":\"يعترف المرنم بضعفه بلا مواربة: ارحمني فإني ضعيف، اشفني فعظامي اضطربت. هذه ليست نهاية الرجاء بل بدايته، فالضعف المعترف به هو الباب الذي تدخل منه القوة الإلهية. لا تخفِ ضعفك اليوم عن الله، فهو يعرفه ويحب أن تقوله له.\",\"p\":\"ارحمني يا رب فإني ضعيف، واشفني فإن عظامي قد اضطربت ونفسي انزعجت جدًا. أعنّي بقوتك التي تكمل في الضعف. آمين.\"},{\"t\":\"القصبة المرضوضة\",\"ref\":\"إشعياء ٤٢: ٣\",\"bk\":\"إشعياء\",\"v\":\"قصبة مرضوضة لا يقصف، وفتيلة خامدة لا يطفئ. إلى الأمان يخرج الحق.\",\"r\":\"القصبة المرضوضة كادت تنكسر، والفتيلة المدخنة كادت تنطفئ. وأحيانًا أكون كذلك: مجروحًا ومتعبًا وطاقتي الروحية خافتة. والخبر السار أن المسيح لا يكسر ولا يطفئ، بل يصبر ويعالج. فلا أخجل من حالتي أمامه.\",\"p\":\"يا رب يسوع، أشكرك لأنك لا تكسر القصبة المرضوضة. أعطني أن أثق برفقك حين أضعف. واجعلني رفيقًا بالضعفاء من حولي. آمين.\"},{\"t\":\"ابدأ من جديد\",\"ref\":\"\",\"v\":\"\",\"r\":\"صلّى القديس أرسانيوس حين اقتربت الشياطين من صومعته: «لا تتركني لوحدي لأني لم أعمل الصلاح أمامك، لكن بصلاحك أعطني أن أبدأ من جديد». الرجاء في الضعف أن أبدأ من جديد بنعمته كل مرة. فابدأ من حيث أنت.\",\"p\":\"يا إلهي، لا تتركني وحدي، فأنا لم أعمل الصلاح أمامك. بصلاحك ومحبتك أعطني أن أبدأ من جديد. آمين.\",\"fq\":25}]},\"2-6\":{\"th\":\"القلب النقي\",\"m\":[{\"t\":\"نقِّ قلبي وكليتي\",\"ref\":\"المزمور ٢٥ (٢٦) — الثالثة\",\"v\":\"اختبرني يا رب وجربنى، نق قلبي وكليتي. لأن رحمتك أمام عيني، وقد ارتضيت بحقك.\",\"r\":\"يطلب المرنم أن يختبره الله وينقي قلبه، لأنه واثق أن رحمة الله أمام عينيه. النقاء ليس نتيجة جهدنا وحده، بل نعمة نطلبها ثم نتعاون معها. اطلب اليوم من الله أن يكشف لك فكرة واحدة تلوّث قلبك، وسلّمها له.\",\"p\":\"اختبرني يا رب وجرّبني، ونقِّ قلبي وكليتي. لتكن رحمتك أمام عيني، وليكن حقك طريقي في كل خطوة. آمين.\"},{\"t\":\"احفظ قلبك\",\"ref\":\"الأمثال ٤: ٢٣\",\"bk\":\"الأمثال\",\"v\":\"فوق كل تحفظ احفظ قلبك، لأن منه مخارج الحياة.\",\"r\":\"كل ما أفعله يبدأ من فكرة، وكل فكرة تبدأ من قلب. ولهذا يقول الحكيم: احفظ قلبك أكثر من كل تحفظ. فمن يحرس الحدود الخارجية ويترك المنبع مفتوحًا، سيتلوث ماؤه. والحراسة تبدأ بالانتباه لما أسمح بدخوله من أفكار وصور وأحاديث.\",\"p\":\"يا رب، احرس قلبي لأن منه مخارج الحياة. ساعدني أن أنتبه لأفكاري وأن أطردها بصلاتك. ملّأ ذهني بما هو حق وطاهر وجميل. آمين.\"},{\"t\":\"الصحو يمنع الدنس\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب بيمن أنه إذا تجاوزنا ما هو عملي وثابرنا على الصحو بنشاط لن يكون في داخلنا دنس. القلب النقي لا يُصنع بالتمنّي، بل بالانتباه المستمر. اختر ساعة اليوم لتراقب فيها أفكارك دون أن تحكم عليها، ثم صلِّ.\",\"p\":\"يا رب، اجعلني صاحيًا في ذهني وقلبي، ونقّني من كل دنس بنعمتك. علّمني أن أثابر على اليقظة بنشاط. آمين.\",\"fq\":437}]},\"2-7\":{\"th\":\"شريك الله في العمل\",\"m\":[{\"t\":\"هوذا الله عوني\",\"ref\":\"المزمور ٥٣ (٥٤) — السادسة\",\"v\":\"هوذا الله عوني، والرب ناصر نفسي، يرد الشرور على أعدائي، بحقك استأصلهم. فأذبح لك طائعا، وأعترف لاسمك يا رب فإنه صالح.\",\"r\":\"الشراكة مع الله تبدأ من إقرار بسيط: هوذا الله عوني. لا أعمل وحدي، ولا أخدم لحساب نفسي. وحين أذبح له طائعًا، أقدّم عملي تقدمة. قبل أن تبدأ عمل اليوم، قل: هذا العمل لك يا رب، وبمعونتك أنجزه.\",\"p\":\"هوذا الله عوني والرب ناصر نفسي. أقدّم لك عملي طائعًا، وأعترف لاسمك لأنه صالح، فقد نجيتني من الشدائد. آمين.\"},{\"t\":\"الكرمة والأغصان\",\"ref\":\"يوحنا ١٥: ٥\",\"bk\":\"يوحنا\",\"v\":\"أنا الكرمة وأنتم الأغصان. الذي يثبت في وأنا فيه هذا يأتي بثمر كثير، لأنكم بدوني لا تقدرون أن تفعلوا شيئا.\",\"r\":\"الغصن لا يجهد ليثمر، بل يثبت في الكرمة فتمر فيه الحياة. وهذا درس عميق: أن ثمر حياتي ليس نتيجة إجهاد بل نتيجة اتصال. وإن كنت أشعر بجفاف روحي، ربما أحتاج أن أراجع اتصالي بالكرمة: كيف صلاتي وأسراري وكلمة الله؟\",\"p\":\"يا رب يسوع، أنت الكرمة وأنا الغصن. ثبتني فيك فأثمر ثمرًا يبقى. قلّم ما يعطّلني، وأعطني حياتك تجري فيّ. آمين.\"},{\"t\":\"أشتغل مع المسيح\",\"ref\":\"\",\"v\":\"\",\"r\":\"كان الأب أبو للوس يقول بفرح كلما قصده الناس في طلب خدمة: «اليوم سأشتغل مع المسيح من أجل نفسي، لأن هذا هو أجرها». الخدمة تتحول إلى شراكة حين أراه شريكي. حين يطلب منك أحد خدمة اليوم، تذكّر هذه العبارة.\",\"p\":\"أيها المسيح، اجعلني أشتغل معك في كل خدمة. علّمني أن أرى طلبات الناس فرصًا للقاء بك وللنمو في المحبة. آمين.\",\"fq\":75}]},\"2-8\":{\"th\":\"الإصغاء إلى الآخرين\",\"m\":[{\"t\":\"هلمّ أيها البنون استمعوا\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"هلم أيها البنون استمعوا لي. فأعلمكم مخافة الرب.\",\"r\":\"الدعوة إلى الاستماع تسبق التعليم: «هلم استمعوا لي فأعلمكم». كثيرًا ما نكون متحدثين في محضر من يحتاج أن يُصغى إليه. اطلب اليوم أن تستمع كاملًا لشخص واحد دون أن تقاطعه أو تجهّز ردك.\",\"p\":\"يا رب، علّمني أن أُصغي كما تُصغي إليّ. أعطني أذنًا مفتوحة، وقلبًا هادئًا، وحكمة أن أسمع قبل أن أجيب. آمين.\"},{\"t\":\"سريعًا في الاستماع\",\"ref\":\"يعقوب ١: ١٩\",\"bk\":\"يعقوب\",\"v\":\"إذا يا إخوتي الأحباء، ليكن كل إنسان مسرعا في الاستماع، مبطئا في التكلم، مبطئا في الغضب،\",\"r\":\"نحب أن نتكلم لنُسمَع، لكن يعقوب يقلب الترتيب: سريعًا في الاستماع، بطيئًا في التكلم، بطيئًا في الغضب. الاستماع الحقيقي أن أسمع لأفهم لا لأرد. وحين أعطي إنسانًا انتباهي الكامل، أقول له بدون كلمات: أنت مهم عندي.\",\"p\":\"يا رب، اجعلني سريعًا في الاستماع بطيئًا في الكلام. أعطني صبرًا أسمع به إخوتي. وعلّمني أن أسمع صوتك أيضًا. آمين.\"},{\"t\":\"لا تجب قبل أن تسمع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب بيمن أن من يجيب بكلمة قبل أن يسمع يعمل بجهل، وأن علينا أن نجيب إذا سُئلنا وإلا نصمت. الإصغاء احترام لصورة الله في الآخر. راقب اليوم رغبتك في المقاطعة وامتنع عنها مرة واحدة على الأقل.\",\"p\":\"يا رب، أبعد عني الجهل الذي يتسرع. علّمني الصمت المحب والكلمة في وقتها، لأحترم كل إنسان تجعله في طريقي. آمين.\",\"fq\":344}]},\"2-9\":{\"th\":\"قدوس هو الرب\",\"m\":[{\"t\":\"الجلال والبهاء قدامه\",\"ref\":\"المزمور ٩٥ (٩٦) — التاسعة\",\"v\":\"الجلال والبهاء قدامه؛ الطهر والجمال العظيم في قدسه. قدموا للرب يا جميع قبائل الأمم؛ قدموا للرب مجدا وكرامة؛ قدموا للرب مجدا لاسمه.\",\"r\":\"القداسة في الكتاب ليست كمالًا بشريًا بل حضور الله الذي يملأ المكان جلالًا وطهرًا. وحين ندخل إلى هذا الحضور نتغير. قبل أن تبدأ صلاتك اليوم، قف لحظة صامتًا كمن يدخل مكانًا مقدسًا، ثم ابدأ.\",\"p\":\"يا رب، الجلال والبهاء قدامك والطهر في قدسك. أقدّم لك مجدًا وكرامة، واجعل قلبي موضعًا لحضورك. آمين.\"},{\"t\":\"قدوس قدوس قدوس\",\"ref\":\"إشعياء ٦: ٣\",\"bk\":\"إشعياء\",\"v\":\"وهذا نادى ذاك وقال: «قدوس، قدوس، قدوس رب الجنود. مجده ملء كل الأرض».\",\"r\":\"رأى إشعياء الرب جالسًا على كرسي عالٍ، فلم يتفاخر بل صرخ: «ويل لي، إني هلكت». اللقاء مع القداسة يكشف الحقيقة. لكن الله لم يتركه في اليأس: أرسل سيرافًا بجمرة تطهّر شفتيه. ثم سمع النداء: من أرسل؟ فقال: هأنذا.\",\"p\":\"قدوس قدوس قدوس رب الجنود، السماوات والأرض مملوءتان من مجدك. طهّر شفتيّ وقلبي، وأرسلني حيثما تشاء. هأنذا فأرسلني. آمين.\"},{\"t\":\"خوف الله كالمصباح\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب يعقوب خوف الله بمصباح يضيء غرفة النوم المظلمة، فينير القلب ويعلّمه كل الفضائل. القداسة تبدأ إذًا من إضاءة داخلية. أي ركن مظلم في داخلك تحتاج أن يضيئه هذا المصباح اليوم؟\",\"p\":\"يا رب، أدخل خوفك الطاهر قلبي، كالمصباح الذي ينير. علّمني بنوره الفضائل والوصايا التي تقدّسني. آمين.\",\"fq\":189}]},\"2-10\":{\"th\":\"ذبيحة التسبيح\",\"m\":[{\"t\":\"ذبيحة التسبيح\",\"ref\":\"المزمور ١١٥ — التاسعة\",\"v\":\"فلك أذبح ذبيحة التسبيح، وباسم الرب أدعو.\",\"r\":\"يعد المرنم بذبيحة لا ثمن مادي لها: ذبيحة التسبيح. وما أبسطها وما أعمقها! تسبيح في وقت الضيق أثمن من تسبيح في وقت الراحة. اختر اليوم لحظة صعبة وسبّح فيها بكلمة واحدة، مثل: المجد لك يا رب.\",\"p\":\"لك أذبح ذبيحة التسبيح وباسم الرب أدعو. اقبل شفتيّ تقدمة، وارفع بها قلبي إليك في كل ظرف. آمين.\"},{\"t\":\"بولس وسيلا في السجن\",\"ref\":\"أعمال الرسل ١٦: ٢٥\",\"bk\":\"أعمال الرسل\",\"v\":\"ونحو نصف الليل كان بولس وسيلا يصليان ويسبحان الله، والمسجونون يسمعونهما.\",\"r\":\"جُلدا وقيّدت أرجلهما في المقطرة، ومع ذلك سبّحا الله في منتصف الليل. والمساجين كانوا يسمعونهما. لم يكن التسبيح حيلة لتغيير الظروف، بل تعبيرًا عن إيمانهما. وحين حدث الزلزال لم يهربا، فكانت شهادتهما أقوى، وخلص السجان وبيته.\",\"p\":\"يا رب، علّمني أن أسبحك في منتصف ليلي. اجعل ضيقي شهادة لمن يراقبني. افتح أبواب القلوب كما فتحت أبواب السجن. آمين.\"},{\"t\":\"ترتيل بلا تشتت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إفاغريوس إن عظيم أن يصلّي المرء بدون شرود، لكن الأعظم أن يرتل بدون تشتت. التسبيح يحتاج انتباهًا أكثر لأنه يمرّ بالفم والقلب معًا. رتل اليوم مزمورًا أو ترنيمة واحدة بتمهل وانتباه.\",\"p\":\"يا رب، علّمني أن أرتل بقلب مجتمع غير مشتت. اجعل تسبيحي ذبيحة مقبولة أمامك وقوةً لي في كل يوم. آمين.\",\"fq\":110}]},\"2-11\":{\"th\":\"الجهاد الروحي\",\"m\":[{\"t\":\"قمنا وانتصبنا\",\"ref\":\"المزمور ١٩ (٢٠) — الثالثة\",\"v\":\"ونحن باسم الرب إلهنا ننمو. هم عثروا وسقطوا، ونحن قمنا وانتصبنا. يا رب خلص ملكك واستجب لنا يوم ندعوك.\",\"r\":\"يرى المرنم الفرق بين من يتكلون على مركبات وخيل ومن يتكلون على الله: أولئك عثروا وسقطوا ونحن قمنا وانتصبنا. الجهاد الروحي ليس بقدراتنا بل بالاعتماد على اسمه. حدّد اليوم معركة صغيرة، وادخلها وأنت تقول: باسم الرب إلهنا.\",\"p\":\"يا رب، خلّص ملكك واستجب لنا يوم ندعوك. باسمك ننمو وبك نقوم وننتصب، فكن قوتنا في الجهاد. آمين.\"},{\"t\":\"الجري في الميدان\",\"ref\":\"كورنثوس الأولى ٩: ٢٤\",\"bk\":\"كورنثوس الأولى\",\"v\":\"ألستم تعلمون أن الذين يركضون في الميدان جميعهم يركضون، ولكن واحدا يأخذ الجعالة؟ هكذا اركضوا لكي تنالوا.\",\"r\":\"صاحب السباق يخفف حمله ويثبت نظره على خط النهاية. والرسول يطلب منا أن نطرح «كل ثقل والخطية المحيطة بنا بسهولة». أحيانًا ما يعطلني ليس خطية كبيرة بل أثقال لا لزوم لها: التزامات، أو مقارنات، أو أحقاد. وقبل أن أجري، أحتاج أن أخلع.\",\"p\":\"يا رب يسوع، مبدئ إيماني ومكمله، أنظر إليك فلا أفتر. أطرح عني كل ثقل وكل خطية تعثرني. اجعلني أجري بصبر في الميدان الذي وضعتني فيه. آمين.\"},{\"t\":\"أن يغصب نفسه في كل شيء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يسأل الأب مكاريوس عن عمل الراهب، فيجيب الأب زخريا: من غصب نفسه في كل شيء. ليس الجهاد حدثًا كبيرًا بل هو غصب النفس في أمور كثيرة صغيرة. اختر اليوم أمرًا واحدًا تغصب فيه نفسك على الخير.\",\"p\":\"يا رب، أعطني أن أغصب نفسي على الخير في الصغير والكبير. وقوّني بنعمتك حتى أنتصر في جهادي اليومي. آمين.\",\"fq\":117}]},\"2-12\":{\"th\":\"العطش إلى الله\",\"m\":[{\"t\":\"رحمتك أفضل من الحياة\",\"ref\":\"المزمور ٦٣ — باكر\",\"v\":\"هكذا ظهرت لك في القدس. لأرى قوتك ومجدك. لان رحمتك أفضل من الحياة. شفتاي تسبحانك.\",\"r\":\"يتجه عطش المرنم إلى رؤية قوة الله ومجده في القدس، ويقرّ أن رحمته أفضل من الحياة نفسها. حين أضع الله في المقام الأول يصير العطش دليل حياة لا نقصًا. اسأل نفسك اليوم: ما الذي أعطشه أكثر من الله؟\",\"p\":\"يا رب، لأرى قوتك ومجدك في قدسك. رحمتك أفضل عندي من الحياة، فلتسبّحك شفتاي كل أيامي. آمين.\"},{\"t\":\"طوبى للجياع\",\"ref\":\"متى ٥: ٦\",\"bk\":\"متى\",\"v\":\"طوبى للجياع والعطاش إلى البر، لأنهم يشبعون.\",\"r\":\"قد نجوع إلى أشياء كثيرة: نجاح، أو تقدير، أو راحة. لكن المسيح يمدح من يجوع إلى البر، أي إلى أن يكون على الاستقامة أمام الله. وحين يكون هذا هو جوعي الأكبر، يعدني الله بالشبع. لا يعد بإشباع الأشياء الأخرى، لكنه يعد بما هو أهم.\",\"p\":\"يا رب، اجعلني أجوع وأعطش إلى البر. أشبعني من كلمتك وروحك، ولا تدعني أكتفي بما هو أدنى. أعطني شهية روحية صحيحة. آمين.\"},{\"t\":\"أطلب الله ولا تسأل عن مكانه\",\"ref\":\"\",\"v\":\"\",\"r\":\"وصية الأب سيسوى مختصرة: «أطلب الله ولا تسأل عن مكان سكناه». أي لا تشغل نفسك بتفاصيل الوسائل وابدأ بالطلب نفسه. العطش الحقيقي لا ينتظر المكان المثالي. ابدأ بالطلب الآن حيث أنت.\",\"p\":\"يا رب، أطلبك في مكاني هذا وزماني. علّمني ألا أؤجل لقاءك حتى تكتمل الظروف، وأن أعطش إليك أكثر كل يوم. آمين.\",\"fq\":503}]},\"2-13\":{\"th\":\"الحرية في المسيح\",\"m\":[{\"t\":\"أخرجني إلى الرحب\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"فاستجاب لي وأخرجني إلى الرحب. الرب عوني فلا أخشى ماذا يصنع بي الإنسان.\",\"r\":\"الحرية عند المرنم خروج من الضيق إلى الرحب، وهي ثمرة صراخ إلى الرب واستجابته. وهي تأتي بثقة: الرب عوني فلا أخشى. ما الذي يضيّق صدرك اليوم؟ اطرحه أمام الله بصراحة واطلب رحبًا جديدًا.\",\"p\":\"في ضيقتي صرخت إليك يا رب، فاستجبتَ لي وأخرجتني إلى الرحب. أنت عوني فلا أخشى ماذا يصنع بي الإنسان. آمين.\"},{\"t\":\"تعرفون الحق والحق يحرركم\",\"ref\":\"يوحنا ٨: ٣١–٣٢\",\"bk\":\"يوحنا\",\"v\":\"فقال يسوع لليهود الذين آمنوا به: «إنكم إن ثبتم في كلامي فبالحقيقة تكونون تلاميذي، وتعرفون الحق، والحق يحرركم».\",\"r\":\"الحرية هنا تأتي من معرفة الحق، وليس أي حق بل الحق الذي هو المسيح نفسه. وهذا يبدأ بالثبات في كلمته. فمن لا يثبت في الكلمة لا يعرف الحق، ومن لا يعرف الحق لا يتحرر. والعبودية ليست بالضرورة جسدية، فقد أكون عبدًا لعادة أو فكرة.\",\"p\":\"يا رب، أعترف أني كنت عبدًا لـ(ما أخفيه). يا من يحرر الأسرى، أعتقني بحقك. ثبتني في كلمتك لأعرف الحق فيحررني. آمين.\"},{\"t\":\"تحرر من الاهتمامات\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أفربيوس إننا إذا فقدنا شيئًا، فعلينا أن نقبل هذا بفرح وحمد لأننا انعتقنا من بعض الاهتمامات. هذه نظرة للحرية مختلفة: أن أرى في الخسارة مساحة جديدة. فكّر في شيء فقدته، وجرّب أن تشكر الله على الحرية التي أعطاك إياها.\",\"p\":\"يا رب، حرّرني من تعلق قلبي بما يزول. علّمني أن أقبل الفقد بحمد، وأن أجد حريتي الحقيقية فيك وحدك. آمين.\",\"fq\":104}]},\"2-14\":{\"th\":\"المحبة العملية\",\"m\":[{\"t\":\"طوبى لمن يتعطف\",\"ref\":\"المزمور ٤٠ (٤١) — الثالثة\",\"v\":\"طوبى لمن يتعطف على المسكين، في يوم الشر ينجيه الرب. الرب يحفظه ويحييه. ويجعله في الأرض مغبوطا، ولا يسلمه لأيدي أعدائه.\",\"r\":\"يمدح المرنم من يتعطف على المسكين، فيكون الرب حافظه ومحييه في يوم الشر. المحبة العملية لا تنتظر الشعور، بل تبدأ بخطوة صغيرة نحو المحتاج. من في دائرتك يحتاج اليوم مكالمة أو زيارة أو مساعدة بسيطة؟\",\"p\":\"يا رب، اجعلني أتعطف على كل مسكين. علّمني أن أحب بالفعل لا بالكلام، وكن أنت حافظي ومحييّ في يوم الشر. آمين.\"},{\"t\":\"المحبة تغطي كثرة من الخطايا\",\"ref\":\"بطرس الأولى ٤: ٨\",\"bk\":\"بطرس الأولى\",\"v\":\"ولكن قبل كل شيء، لتكن محبتكم بعضكم لبعض شديدة، لأن المحبة تستر كثرة من الخطايا.\",\"r\":\"في العلاقات القريبة نرى العيوب بوضوح. والمحبة تختار ألا تنشر هذه العيوب ولا تضخمها. «تغطي» لا تعني أن أنكر الخطأ، بل أن أتعامل معه في الخفاء بحكمة ومحبة. وحين يسقط أحد أحبائي، أكون أول من يستره لا من يفضحه.\",\"p\":\"يا رب، علّمني محبة حارة تغطي كثرة من الخطايا. امنع لساني من الإذاعة بعيوب إخوتي. اجعلني أستر وأصلح كما فعلت معي. آمين.\"},{\"t\":\"أعظم المحبة بذل النفس\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشرح الأب بيمن أن أعظم محبة هي بذل النفس عن القريب، وأن من يجاهد ألا ينطق بما يجرح أو يحتمل الظلم والطمع قادر أن يبذل حياته. المحبة تبدأ من الصغائر. ابدأ اليوم بكلمة لا تقولها أو أمر تحتمله من أجل أخيك.\",\"p\":\"يا رب، علّمني أن أبذل نفسي من أجل قريبي في الصغير قبل الكبير. اجعل محبتي عملية تشبه محبتك. آمين.\",\"fq\":394}]},\"2-15\":{\"th\":\"تقدمة السيد إلى الهيكل\",\"m\":[{\"t\":\"عيناي أبصرتا خلاصك\",\"ref\":\"إنجيل النوم\",\"v\":\"الآن يا سيدي تطلق عبدك بسلام حسب قولك، لأن عيني قد أبصرتا خلاصك الذي أعددته قدام جميع الشعوب. نورا تجلى للأمم، ومجدا لشعبك إسرائيل.\",\"r\":\"في عيد دخول السيد إلى الهيكل يحمل سمعان الشيخ الطفل على ذراعيه ويرى في هذا الطفل الخلاص كله. بعد سنين طويلة من الانتظار صار وداعه سلامًا. وما ينتظره قلبك اليوم قد يأتي في صورة بسيطة، فكن مستعدًا لتعرفه.\",\"p\":\"الآن يا سيدي أطلق عبدك بسلام، فقد أبصرت عيناي خلاصك. اجعلني دائمًا منتظرًا لك بقلب مستعد وروح تتعرف عليك. آمين.\"},{\"t\":\"تقدمة الذات\",\"ref\":\"رومية ١٢: ١\",\"bk\":\"رومية\",\"v\":\"فأطلب إليكم أيها الإخوة برأفة الله أن تقدموا أجسادكم ذبيحة حية مقدسة مرضية عند الله، عبادتكم العقلية.\",\"r\":\"في هذا العيد قدّمت العذراء ابنها لله حسب الناموس. وفي كل يوم أنا مدعو أن أقدم حياتي له: وقتي وجسدي وقراري. والتقدمة ليست حدثًا واحدًا بل حياة. وهي «عبادة عقلية»، أي واعية، ولا تأتي من الجبر بل من الاقتناع بمراحم الله.\",\"p\":\"يا رب، أقدّم لك نفسي ذبيحة حية. أقدم جسدي وفكري ووقتي. اقبلني كما قبلت تقدمة ابنك في الهيكل، وجدد ذهني لأعرف مشيئتك. آمين.\"},{\"t\":\"لنحترم الواحد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا الكولوفي لتلميذه: لنحترم الواحد فيحترمنا الجميع، ويقصد بالواحد الله. تقدمة السيد إلى الهيكل تذكّرنا أن الله هو الأول، وأن كل علاقة تنتظم حين يكون هو المركز. ضع الله اليوم أول اهتماماتك.\",\"p\":\"يا رب، أنت الواحد الذي أحترمه وأخافه. ضعني في مكاني أمامك، ورتّب علاقاتي كلها بمحبتك. آمين.\",\"fq\":160}]},\"2-16\":{\"th\":\"البصيرة الروحية\",\"m\":[{\"t\":\"أنر عيني\",\"ref\":\"المزمور ١٢ (١٣) — باكر\",\"v\":\"انظر واستجب لي يا ربي وإلهي. أنر عيني لئلا أنام نوم الموت، لئلا يقول عدوي: إني قد قويت عليه.\",\"r\":\"يصلي المرنم: «أنر عيني لئلا أنام نوم الموت». البصيرة الروحية تبدأ بالاعتراف أننا لا نرى بذواتنا. وحين تنفتح العيون نرى الله في الأحداث التي كنا نعدها عادية. اطلب اليوم عينًا ترى حضوره في موقف واحد.\",\"p\":\"انظر واستجب لي يا ربي وإلهي، وأنر عيني لئلا أنام نوم الموت. افتح بصيرتي لأرى عملك، وأبتهج بخلاصك. آمين.\"},{\"t\":\"شفاء الأعمى\",\"ref\":\"يوحنا ٩: ٢٥\",\"bk\":\"يوحنا\",\"v\":\"فأجاب ذاك وقال: «أخاطئ هو؟ لست أعلم. إنما أعلم شيئا واحدا: أني كنت أعمى والآن أبصر».\",\"r\":\"أُلقيت على الأعمى أسئلة وتشكيكات كثيرة، لكنه لم يدخل في جدال لاهوتي. قال ببساطة: «أنا أعلم شيئًا واحدًا: أني كنت أعمى والآن أبصر». شهادتك لا تحتاج أن تكون معقدة. يكفي أن تحكي ما فعله المسيح فيك.\",\"p\":\"يا رب يسوع، كنت أعمى والآن أبصر بنعمتك. اشفِ عمى قلبي وأفهمني ما لا أراه. اجعلني شاهدًا بسيطًا صادقًا لعملك فيّ. آمين.\"},{\"t\":\"ثلاث فضائل ترفع النفس\",\"ref\":\"\",\"v\":\"\",\"r\":\"يلخّص الأب بيمن ما ترتفع به النفس في ثلاث: الانتباه والصحو والتمييز. هذه هي عيون القلب. وحين تضعف إحداها يضعف النظر. فأي واحدة منها تحتاج إلى تدريب اليوم؟ اختر واحدة وعالجها.\",\"p\":\"يا رب، امنحني انتباهًا وصحوًا وتمييزًا. افتح بصيرتي بنعمتك لأرى كل شيء كما تراه أنت. آمين.\",\"fq\":333}]},\"2-17\":{\"th\":\"الصبر على الناس\",\"m\":[{\"t\":\"إلى جيلٍ فجيل حقه\",\"ref\":\"المزمور ٩٩ (١٠٠) — التاسعة\",\"v\":\"فإن الرب صالح هو، والى الأبد رحمته. وإلى جيل فجيل حقه.\",\"r\":\"يذكّرنا المرنم أن الرب صالح ورحمته إلى الأبد وحقه إلى جيل فجيل. من يتأمل صبر الله على الأجيال يتعلم الصبر على من أمامه. فكّر في شخص يتعبك اليوم، وتذكّر كم صبر الله عليك.\",\"p\":\"يا رب، أنت صالح ورحمتك إلى الأبد وحقك إلى جيل فجيل. علّمني أن أصبر على الناس كما صبرت أنت عليّ. آمين.\"},{\"t\":\"طول الأناة\",\"ref\":\"غلاطية ٥: ٢٢\",\"bk\":\"غلاطية\",\"v\":\"وأما ثمر الروح فهو: محبة فرح سلام، طول أناة لطف صلاح، إيمان\",\"r\":\"طول الأناة تعني أن «روحي طويلة» لا تنفد بسرعة. وأنا أعلم أنني أنفد سريعًا حين أكون متعبًا أو مضغوطًا. لكن الصبر من ثمار الروح، أي أنه ينمو حين أتغذى من الروح. وكلما اقتربت من الله اتسعت صدري للآخرين.\",\"p\":\"أيها الروح القدس، اغرس فيّ ثمر طول الأناة. اجعل صدري واسعًا وروحي هادئة. ذكّرني بصبرك عليّ حين أضيق بغيري. آمين.\"},{\"t\":\"القوس إذا شُدّ فوق القياس\",\"ref\":\"\",\"v\":\"\",\"r\":\"أراه القديس أنطونيوس لصياد أن القوس إذا شُدّ فوق قياسه انكسر، وكذلك الإخوة إذا ضُغط عليهم فوق طاقتهم. الصبر على الناس يعني أن أراعي قدرتهم. وأنت اليوم، أي شخص تضغط عليه أكثر مما يحتمل؟ خفّف عنه.\",\"p\":\"يا رب، علّمني الرفق بمن حولي، وألا أطلب من أحد ما لا يطيق. اجعلني صبورًا ومتنازلًا بمحبة. آمين.\",\"fq\":9}]},\"2-18\":{\"th\":\"الاعتراف بالخطية\",\"m\":[{\"t\":\"انظر إلى ذلي وتعبي\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"انظر إلى ذلي وتعبي. واغفر لي جميع خطاياي.\",\"r\":\"الاعتراف يبدأ بنظرة الله إلى ذلّنا وتعبنا قبل أن يطلب منا شيئًا: «انظر إلى ذلي وتعبي واغفر لي جميع خطاياي». يجتمع هنا الألم والتوبة. فلا تخف أن تعرض على الله حقيقتك كما هي، ففي نظرته شفاء.\",\"p\":\"انظر يا رب إلى ذلي وتعبي، واغفر لي جميع خطاياي. اقبل اعترافي الصادق، وأعد إليّ فرحك. آمين.\"},{\"t\":\"الجابي في الهيكل\",\"ref\":\"لوقا ١٨: ١٣\",\"bk\":\"لوقا\",\"v\":\"وأما العشار فوقف من بعيد، لا يشاء أن يرفع عينيه نحو السماء، بل قرع على صدره قائلا: اللهم ارحمني، أنا الخاطئ.\",\"r\":\"الفريسي صلّى عن نفسه ومقارنًا نفسه بغيره. أما الجابي فوقف من بعيد ولم يرفع عينيه. صلاة الجابي بسيطة وقصيرة: «ارحمني». ولهذا خرج مبررًا. فالمهم ليس طول الصلاة ولا جمالها بل صدق القلب.\",\"p\":\"اللهم ارحمني أنا الخاطئ. لا أرفع عينيّ إليك بل أقرع صدري. اغفر لي كبريائي وقسوتي، واقبلني كما قبلت الجابي. آمين.\"},{\"t\":\"«خطئت» لا يعود مذنبًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعطينا الأب بيمن رجاءً عظيمًا: عندما يخطئ الإنسان ويقول «خطئت» لا يعود مذنبًا. فالاعتراف الصادق ينهي سطوة الخطيئة. إن كان على ضميرك شيء اليوم فقله لله كاملًا ولا تؤجله.\",\"p\":\"يا رب، أقول لك خطئت، فاغفر لي. لا تتركني أحمل خطيتي في الظلام، وألبسني ثوب التوبة والفرح. آمين.\",\"fq\":384}]},\"2-19\":{\"th\":\"الجسد الواحد\",\"m\":[{\"t\":\"ندى حرمون\",\"ref\":\"المزمور ١٣٢ — النوم\",\"v\":\"ومثل ندى حرمون المنحدر على جبل صهيون. لأن هناك أمر الرب بالبركة والحياة إلى الأبد هلليلويا.\",\"r\":\"يشبّه المرنم الوحدة بندى حرمون الذي ينحدر على جبل صهيون فيحيي أرضًا. هكذا الجسد الواحد: كل عضو ينفع الآخر، وحيث الوحدة تأتي البركة. اسأل نفسك اليوم من هو العضو الذي أهملته في جسدك الروحي؟\",\"p\":\"يا رب، حيث تكون الوحدة هناك تأمر بالبركة والحياة. اجعلنا جسدًا واحدًا بمحبتك، وأنزل ندى بركتك على بيوتنا وكنيستنا. آمين.\"},{\"t\":\"فرحًا مع الفرحين\",\"ref\":\"رومية ١٢: ١٥\",\"bk\":\"رومية\",\"v\":\"فرحا مع الفرحين وبكاء مع الباكين.\",\"r\":\"من السهل أن أبكي مع الباكين وأنا أراهم يتألمون، لكن الأصعب أحيانًا أن أفرح مع الفرحين حين يكون عندهم ما ليس عندي. هنا تُختبر المحبة: هل أستطيع أن أفرح بنجاح غيري دون شعور بالنقص؟ فرحي بنجاحهم علامة صحة قلبي.\",\"p\":\"يا رب، أعطني قلبًا يفرح مع الفرحين ويبكي مع الباكين. طهّرني من الحسد والأنانية. علّمني أن أشارك إخوتي في كل ظروفهم بمحبة. آمين.\"},{\"t\":\"لم أؤثر مصلحتي على أخي\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينقل الأب يوحنا الخصي عن القديس أنطونيوس: «لم أؤثر مرة مصلحتي على مصلحة أخي». جملة قصيرة لكنها منهج حياة كاملة. هل يمكنك اليوم أن تقدّم مصلحة أخيك في أمر ولو بسيط؟\",\"p\":\"يا رب، علّمني أن أضع أخي قبل نفسي. وحّد قلوبنا ونفوسنا لنكون جسدًا واحدًا لك. آمين.\",\"fq\":193}]},\"2-20\":{\"th\":\"الميراث السماوي\",\"m\":[{\"t\":\"الرب نصيب ميراثي\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"الرب هو نصيب ميراثي وكأسي. أنت الذي ترد إلى ميراثي. حبال المساحة وقعت لي في أرض خصبة، وإن ميراثي لثابت لي.\",\"r\":\"يرى المرنم أن ميراثه الحقيقي هو الرب نفسه، وأن حبال المساحة وقعت له في أرض خصبة. من ينظر إلى ميراثه هكذا لا يحسد أحدًا. فتأمّل اليوم: ما الذي أعدّه ميراثي، وهل هو الله أم ما يعطيه؟\",\"p\":\"يا رب، أنت نصيب ميراثي وكأسي، وأنت الذي ترد إلي ميراثي. اجعل قلبي يطمئن لأن ميراثي ثابت في يدك. آمين.\"},{\"t\":\"كنز في السماء\",\"ref\":\"متى ٦: ١٩–٢٠\",\"bk\":\"متى\",\"v\":\"«لا تكنزوا لكم كنوزا على الأرض حيث يفسد السوس والصدأ، وحيث ينقب السارقون ويسرقون. بل اكنزوا لكم كنوزا في السماء، حيث لا يفسد سوس ولا صدأ، وحيث لا ينقب سارقون ولا يسرقون،\",\"r\":\"السؤال الأهم ليس كم أملك بل أين قلبي. المسيح يربط الكنز بالقلب: «حيث يكون كنزك هناك يكون قلبك أيضًا». فإذا كان كنزي في الأرض يكون قلبي هناك يتأرجح مع الأسعار والأخبار. أما إن كان في السماء فيستقر. والاستثمار هناك يبدأ بالعطاء.\",\"p\":\"يا رب، حيث يكون كنزي هناك يكون قلبي. علّمني أن أكنز في السماء بالعطاء والصلاة. حرر قلبي من محبة المال، واجعلك أنت كنزي. آمين.\"},{\"t\":\"ذكر الملكوت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصينا الأب إيبريخيوس: «فليكن ذكر ملكوت السماوات أمامك كل حين، فترثه سريعًا». من يذكر وجهته لا يضل في الطريق. اجعل لك اليوم لحظة تذكّر فيها أنك غريب في هذا العالم وأن لك ميراثًا.\",\"p\":\"يا رب، ليكن ملكوتك أمام عيني كل حين. أعطني أن أعيش كابن لك ينتظر ميراثه بصبر ورجاء. آمين.\",\"fq\":554}]},\"2-21\":{\"th\":\"المصالحة قبل التقدمة\",\"m\":[{\"t\":\"اغضبوا ولا تخطئوا\",\"ref\":\"المزمور الرابع — باكر\",\"v\":\"اغضبوا ولا تخطئوا، الذي تقولونه في قلوبكم اندموا عليه في مضاجعكم. اذبحوا ذبيحة البر، وتوكلوا على الرب.\",\"r\":\"ليس الغضب نفسه خطيئة، لكن ما نفعله به قد يكون. ينصحنا المرنم أن نراجع في مضاجعنا ما قلناه في قلوبنا وأن نذبح ذبيحة البر. اليوم قبل أن تنام راجع أي كلمة غاضبة قلتها، وصالح.\",\"p\":\"يا رب، علّمني أن أغضب دون أن أخطئ، وأن أندم على ما يقوله قلبي في غضبه. أقدّم لك ذبيحة البر، وأتكل عليك. آمين.\"},{\"t\":\"سالموا جميع الناس\",\"ref\":\"رومية ١٢: ١٨\",\"bk\":\"رومية\",\"v\":\"إن كان ممكنا فحسب طاقتكم سالموا جميع الناس.\",\"r\":\"«إن كان ممكنًا فحسب طاقتكم سالموا جميع الناس». عبارة صادقة وواقعية: لا يطلب مني ما لا أقدر، لكنه يطلب كل ما أقدر. قد لا يتصالح الآخر معي، لكن عليّ أن أكون قد فعلت نصيبي: كلمة لينة، أو صمت حكيم، أو صلاة من أجله. السلام عملي قبل أن يكون شعورًا.\",\"p\":\"يا ملك السلام، اجعلني أداة لسلامك في بيتي وعملي. أعطني لسانًا هادئًا وقلبًا متواضعًا، وعلّمني أن أفعل نصيبي في المصالحة دون كبرياء. آمين.\"},{\"t\":\"أخ ظلمك يدخل صلاتك\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينبهنا الأب نيلوس أن الأخ الذي نقاومه سيدخل إلى قلبنا ساعة الصلاة. أي أن الخصومة تعيق اللقاء مع الله. قبل أن تقف لتصلي اليوم، تخلص من مقاومة أحد، أو على الأقل ضعه في صلاتك.\",\"p\":\"يا رب، لا تدع خصومة تقف بيني وبينك. اغفر لي ولمن ظلمني، وصالحنا بسلامك قبل أن نقف في حضرتك. آمين.\",\"fq\":288}]},\"2-22\":{\"th\":\"مخافة الرب\",\"m\":[{\"t\":\"خشية الرب زكية\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"خشية الرب زكية:، دائمة إلى أبد الأبد. أحكام الرب أحكام حق وعادلة معا.\",\"r\":\"«خشية الرب زكية دائمة»: كلمة تصف رائحة طيبة تدوم. مخافة الرب ليست رعبًا بل احترام يحفظنا من الاستهانة. وأحكامه حق وعادلة معًا. اقترب اليوم من الله بخشوع يحفظ قلبك من الاعتياد.\",\"p\":\"يا رب، ضع في قلبي خشيتك الزكية الدائمة. علّمني أن أسير بأحكامك الحق العادلة، وأقف أمامك بخشوع محب. آمين.\"},{\"t\":\"بدء المعرفة\",\"ref\":\"الأمثال ١: ٧\",\"bk\":\"الأمثال\",\"v\":\"مخافة الرب رأس المعرفة، أما الجاهلون فيحتقرون الحكمة والأدب.\",\"r\":\"«مخافة الرب رأس المعرفة». لا أفهم المخافة هنا رعبًا من إله قاسٍ، بل توقيرًا لمن أحبني. كما يخشى الابن أن يجرح قلب أبيه. هذه المخافة لا تقيّدني، بل تحميني، وتجعلني أفكر قبل أن أتكلم وأتصرف: هل هذا يفرح الله؟\",\"p\":\"يا رب، ازرع في قلبي مخافة بنوية ومحبة صادقة. علّمني أن أعتبرك في كل قراراتي، وأن لا أحزن روحك القدوس بتصرف أو كلمة. آمين.\"},{\"t\":\"ضع مخافة الله نصب عينيك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي القديس أنطونيوس: «ضع مخافة الله نصب عينيك دائمًا. وتذكّر هذا الذي يميت ويحيي». هذه الوصية لا تقصد إرهابنا بل إيقاظ وعينا. فاجعل مخافة الله اليوم مرجعًا لقرار واحد على الأقل تتخذه.\",\"p\":\"يا رب، اجعل مخافتك رفيقة لي في كل قرار. أعطني قلبًا يراك دائمًا، ويحيا بوعده وعهده معك. آمين.\",\"fq\":18}]},\"2-23\":{\"th\":\"السهر والاستعداد\",\"m\":[{\"t\":\"طوبى للعبد المستيقظ\",\"ref\":\"قطعة الخدمة الأولى (١) — نصف الليل — الخدمة الأولى\",\"v\":\"هاهوذا العريس يأتي في نصف الليل. طوبى للعبد الذي يجده مستيقظا. أما الذي يجده متغافلا، فإنه غير مستحق المضي معه. فانظري يا نفسي لئلا تثقلي نوما، فتلقي خارج الملكوت. بل اسهري.\",\"r\":\"تذكّرنا الكنيسة بالعريس الذي يأتي في ساعة لا نعرفها. السهر ليس قلقًا من الوقت، بل حياة تعيش كل لحظة كأنها لقاء محتمل. اسأل نفسك الليلة: لو جاء الآن، هل يجدني مشغولًا بما يليق به؟\",\"p\":\"أيها العريس السماوي، لا تدعني أثقل نومًا فألقى خارجًا. أيقظ نفسي لأسهر وأصرخ إليك، وكن أنت رجائي عند مجيئك. آمين.\"},{\"t\":\"اصحوا واسهروا\",\"ref\":\"بطرس الأولى ٥: ٨\",\"bk\":\"بطرس الأولى\",\"v\":\"اصحوا واسهروا. لأن إبليس خصمكم كأسد زائر، يجول ملتمسا من يبتلعه هو.\",\"r\":\"«اصحوا واسهروا لأن إبليس خصمكم كأسد زائر يجول ملتمسًا من يبتلعه هو». يخبرني الرسول بالحقيقة ليحميني لا ليخيفني. العدو حقيقي، لكن المسيح انتصر عليه. وسلاحي هو الانتباه والصلاة والتمسك بكلمة الله، وأن لا أتهاون في الصغائر.\",\"p\":\"يا رب، احرسني من كل هجمة للعدو. علّمني أن أصحو وأقاوم بصلاة يسوع، وثبّتني في إيمانك. أنت قوتي وحصني. آمين.\"},{\"t\":\"افحص أفكارك\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح القديس أمون الأخ بأن يفحص أفكاره كما يفعل فاعلو الشر في السجن، يسألون عن الرئيس ومتى يأتي. أي أن ننتظر لقاء مع الله بمحاسبة يومية. خصص الليلة خمس دقائق لمراجعة يومك أمام الله.\",\"p\":\"يا رب، علّمني أن أحاسب نفسي كل يوم وأتيقظ للقائك. ليكن ذهني مستعدًا وقلبي ساهرًا. آمين.\",\"fq\":60}]},\"2-24\":{\"th\":\"العطاء بفرح\",\"m\":[{\"t\":\"فرّق وأعطى المساكين\",\"ref\":\"المزمور ١١١ (١١٢) — التاسعة\",\"v\":\"قلبه مستعد متكل على الرب. قلبه ثابت لا يتزعزع حتى يرى بأعدائه. فرق وأعطى المساكين.\",\"r\":\"يصف المرنم الرجل المتقي الرب بأن قلبه مستعد وثابت، ومن ثمرة هذا الثبات أنه يفرّق ويعطي المساكين. العطاء ليس تبذيرًا بل علامة قلب متكل على الرب. اعطِ اليوم شيئًا، ولو صغيرًا، بفرح ودون إعلان.\",\"p\":\"يا رب، اجعل قلبي مستعدًا متكلًا عليك. علّمني أن أعطي المساكين بفرح، وثبّت قلبي فلا يتزعزع. آمين.\"},{\"t\":\"فلسا الأرملة\",\"ref\":\"لوقا ٢١: ١–٤\",\"bk\":\"لوقا\",\"v\":\"وتطلع فرأى الأغنياء يلقون قرابينهم في الخزانة، ورأى أيضا أرملة مسكينة ألقت هناك فلسين. فقال: «بالحق أقول لكم: إن هذه الأرملة الفقيرة ألقت أكثر من الجميع، لأن هؤلاء من فضلتهم ألقوا في قرابين الله، وأما هذه فمن إعوازها، ألقت كل المعيشة التي لها».\",\"r\":\"رأى المسيح الأغنياء يلقون من فضلتهم، وأرملة تلقي فلسين، فقال: «هذه الأرملة الفقيرة ألقت أكثر من الجميع». لأن القيمة عند الله ليست في الرقم بل في التضحية. هي لم تحتفظ لنفسها بشيء، فكانت تثق أن الله يعولها. فما أجمل ثقتها!\",\"p\":\"يا رب، علّمني ثقة الأرملة في عنايتك. اقبل مني ما أقدمه ولو قليلًا، واجعلني أعطي من قلبي دون حساب. آمين.\"},{\"t\":\"أيديكم للعطاء\",\"ref\":\"\",\"v\":\"\",\"r\":\"أوصى الأب خومة أبناءه قبل رحيله ألا يمدوا أيديهم للأخذ بل للعطاء. وصية تعبّر عن روح المسيح الذي قال إن العطاء أفضل من الأخذ. فكّر اليوم: ماذا تستطيع أن تعطي، من وقتك أو مالك أو انتباهك؟\",\"p\":\"يا رب، علّمني أن أمد يدي للعطاء لا للأخذ. اجعل عطائي فرحًا يحمل بركتك للآخرين. آمين.\",\"fq\":558}]},\"2-25\":{\"th\":\"الاستقامة والنزاهة\",\"m\":[{\"t\":\"السالك بلا عيب\",\"ref\":\"المزمور الرابع عشر — باكر\",\"v\":\"السالك بلا عيب والفاعل البر، والمتكلم بالحق في قلبه، الذي لا يغش بلسانه، ولا يصنع بقريبه سوءا، ولا يقبل عارا على جيرانه. فاعل الشر مرذول أمامه؛ ويمجد الذين يتقون الرب.\",\"r\":\"يصف المرنم الساكن في بيت الرب بأنه سالك بلا عيب، متكلم بالحق، لا يغش ولا يسيء إلى قريبه. هذه هي النزاهة اليومية: كلمة صادقة وفعل عادل. اختبر اليوم صدقك في أمر صغير لا يراه أحد.\",\"p\":\"يا رب، من يسكن في مسكنك؟ اجعلني سالكًا بلا عيب، فاعلًا للبر، ومتكلمًا بالحق في قلبي. آمين.\"},{\"t\":\"زكا يرد المال\",\"ref\":\"لوقا ١٩: ٨\",\"bk\":\"لوقا\",\"v\":\"فوقف زكا وقال للرب: «ها أنا يارب أعطي نصف أموالي للمساكين، وإن كنت قد وشيت بأحد أرد أربعة أضعاف».\",\"r\":\"لم يطلب المسيح من زكا أن يرد شيئًا، لكن اللقاء به غيّر قلبه فقال: «ها أنا يا رب أعطي نصف أموالي للمساكين وإن كنت قد وشيت بأحد أرد أربعة أضعاف». التوبة الحقيقية تلمس الجيب والعلاقات، وليست كلامًا فقط. والنعمة تغيّر ما لم يستطع الناموس أن يغيّره.\",\"p\":\"يا رب، كما زرت زكا زر قلبي. أعطني توبة صادقة ترد الحقوق وتصلح العلاقات، وأنعم عليّ بفرح الخلاص. آمين.\"},{\"t\":\"ضمير نقي تجاه القريب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بمفو للأخوين اللذين يصومان ويتعبّدان: حسنة هي الأعمال، لكن إن حفظتما ضميركما نقيًا تجاه القريب تخلصان. فالنزاهة أن لا يكون في قلبي حيلة أو أذى نحو أحد. هل ضميرك اليوم نقي نحو الجميع؟\",\"p\":\"يا رب، احفظ ضميري نقيًا تجاه كل قريب. لتكن أعمالي كلها بصدق ونزاهة أمامك. آمين.\",\"fq\":456}]},\"2-26\":{\"th\":\"النهوض بعد السقوط\",\"m\":[{\"t\":\"الرب يقيم الساقطين\",\"ref\":\"المزمور ١٤٥ — النوم\",\"v\":\"الرب يحل المربوطين الرب يقيم الساقطين. الرب يحكم العميان. الرب يحب الصديقين.\",\"r\":\"كل سقوط قابل للقيام لأن الرب هو الذي يقيم الساقطين ويحل المربوطين. لا يبقى الساقط طويلًا على الأرض إن مدّ يده. مهما كان سقوطك الأخير، قل اليوم لله: أقمني، ثم قم وامشِ.\",\"p\":\"أيها الرب الذي يحل المربوطين ويقيم الساقطين، أقمني من سقوطي. أنت تحب الصديقين، فاجعلني منهم بنعمتك. آمين.\"},{\"t\":\"أتحبني أكثر من هؤلاء\",\"ref\":\"يوحنا ٢١: ١٥\",\"bk\":\"يوحنا\",\"v\":\"فبعد ما تغدوا قال يسوع لسمعان بطرس: «يا سمعان بن يونا، أتحبني أكثر من هؤلاء؟» قال له: «نعم يارب أنت تعلم أني أحبك». قال له: «ارع خرافي».\",\"r\":\"أنكر بطرس سيده ثلاث مرات، ولم يوبخه المسيح بعد القيامة بل سأله ثلاث مرات: «أتحبني؟». السؤال لم يكن عن الماضي بل عن الحب. والمسيح لا يعيّر ساقطًا بل يعيده إلى مكانه ويكلفه برعاية خرافه. هكذا يتعامل معي: يسألني عن قلبي ثم يعطيني رسالة.\",\"p\":\"يا رب، أنت تعلم كل شيء، أنت تعلم أني أحبك. اغفر لي إنكاري وضعفي، وأعد إليّ ثقتك، واستخدمني في خدمة خرافك. آمين.\"},{\"t\":\"انهض أيضًا من جديد\",\"ref\":\"\",\"v\":\"\",\"r\":\"حين سأل أخ الأب سيسوى ماذا يعمل بعد أن سقط، قال: انهض. وحين عاد وسقط قال: انهض أيضًا من جديد، إلى أن تنتهي إما إلى الخير أو إلى السقطة. معنى هذا أن النهوض هو الشيء الوحيد المطلوب. انهض الآن.\",\"p\":\"يا رب، أنهض مرة بعد مرة بنعمتك. لا تدعني أيأس مهما سقطت، وأعطني أن أنتهي إليك في كل مرة. آمين.\",\"fq\":501}]},\"2-27\":{\"th\":\"الإيمان العامل\",\"m\":[{\"t\":\"بماذا أكافئ الرب؟\",\"ref\":\"المزمور ١١٥ — التاسعة\",\"v\":\"بماذا أكافئ الرب عن كل ما أعطانيه؟ كأس الخلاص آخذ وباسم الرب أدعو. أوفي نذوري للرب قدام كل شعبه.\",\"r\":\"يسأل المرنم: بماذا أكافئ الرب عن كل ما أعطانيه؟ وجوابه عمل: آخذ كأس الخلاص، وأوفي نذوري. الإيمان الحي يتحول إلى وفاء. ما الوعد الذي وعدت الله به ولم تنفذه؟ نفّذ جزءًا منه اليوم.\",\"p\":\"بماذا أكافئك يا رب عن كل ما أعطيتني؟ آخذ كأس الخلاص وباسمك أدعو، وأوفي نذوري لك أمام شعبك. آمين.\"},{\"t\":\"الإيمان العامل بالمحبة\",\"ref\":\"غلاطية ٥: ٦\",\"bk\":\"غلاطية\",\"v\":\"لأنه في المسيح يسوع لا الختان ينفع شيئا ولا الغرلة، بل الإيمان العامل بالمحبة.\",\"r\":\"«في المسيح يسوع لا الختان ينفع شيئًا ولا الغرلة بل الإيمان العامل بالمحبة». كل مظاهري الدينية بدون محبة لا قيمة لها. والإيمان الذي يقبله الله هو الذي يعمل بالمحبة: يخدم ويسامح ويصبر. وأحتاج أن أراجع ما إذا كان تديّني مظهرًا أو حياة.\",\"p\":\"يا رب، علّمني أن تكون كل عبادتي محبة. حوّل ممارساتي الروحية إلى ثمر في حياتي، وازرع في قلبي إيمانًا يعمل بالمحبة. آمين.\"},{\"t\":\"العمل بما نسمع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب فيلكس إن الإخوة كانوا يسألون الشيوخ ويعملون بما يسمعونه فيمنحهم الله القدرة على الكلام، أما الآن فيسألون ولا يعملون. الإيمان العامل هو الطاعة الفورية لما نعرفه. اختر كلمة سمعتها هذا الأسبوع وطبّقها اليوم.\",\"p\":\"يا رب، اجعلني عاملًا بما أسمع لا سامعًا فقط. أعطني قوة لتنفيذ ما تعلّمه كلمتك. آمين.\",\"fq\":556}]},\"2-28\":{\"th\":\"القناعة\",\"m\":[{\"t\":\"لا يعوزهم شيء\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"فإن الذين يتقونه لا يعوزهم شيء. الأغنياء افتقروا وجاعوا، أما الذين يبتغون الرب فلا يعوزهم أي خير.\",\"r\":\"يقول المرنم إن الذين يتقون الرب لا يعوزهم شيء، بينما الأغنياء افتقروا وجاعوا. القناعة ليست قلة طموح بل ثقة في أن الله يعطي الخير. أحصِ اليوم ثلاثة أشياء عندك ولا تلتفت لما ينقصك.\",\"p\":\"يا رب، من يتقيك لا يعوزه شيء. علّمني القناعة بما أعطيتني، وأن أبتغيك قبل كل خير. آمين.\"},{\"t\":\"احترزوا من الطمع\",\"ref\":\"لوقا ١٢: ١٥\",\"bk\":\"لوقا\",\"v\":\"وقال لهم: «انظروا وتحفظوا من الطمع، فإنه متى كان لأحد كثير فليست حياته من أمواله».\",\"r\":\"«انظروا وتحفظوا من الطمع، فإنه ليس في كثرة الأموال حياة». هذا التحذير جاء ردًّا على من طلب عدلًا في ميراث. فالمسيح يكشف أن المشكلة أعمق من المال: هي الطمع الذي يجعلني أظن أن الأمان في الأشياء. لكن الحياة هبة من الله لا من المخزون.\",\"p\":\"يا رب، احفظني من الطمع. علّمني أن أكون غنيًا لك، وأن أستخدم ما أعطيتني لمجدك وخير إخوتي، ولا أعتمد على المخزون بل عليك. آمين.\"},{\"t\":\"لا نقتني شيئًا بسبب مخافة الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقارن الأم سينكليتيكي بين الذين يجمعون الغنى ولا يكتفون وبين الذين يتركون الأمور المرغوب فيها بسبب مخافة الله. القناعة هنا اختيار حر. هل في حياتك شيء تستطيع أن تتخلى عنه بفرح اليوم؟\",\"p\":\"يا رب، علّمني أن أقنع بما عندي، وألا ألهث وراء المزيد. اجعل مخافتك كنزي الحقيقي. آمين.\",\"fq\":538}]},\"2-29\":{\"th\":\"افتداء الوقت\",\"m\":[{\"t\":\"احسبني مع أصحاب الساعة الحادية عشرة\",\"ref\":\"قطعة الغروب (١)\",\"v\":\"إذا كان الصديق بالجهد يخلص فأين أظهر أنا الخاطئ. ثقل النهار وحره لم أحتمل لضعف بشريتي. لكن أنت يا الله الرحوم احسبني مع أصحاب الساعة الحادية عشر.\",\"r\":\"في نهاية شهر قصير نتذكر أن الوقت ثمين ومحدود، وأن الله يقبل من جاء في آخر النهار. لا ننتظر الوقت المثالي ليقترب الإنسان، ولا نيأس لأن الوقت مضى. استخدم اليوم ما بقي منه لتبدأ شيئًا طال تأجيله.\",\"p\":\"اللهم الرحوم، احسبني مع أصحاب الساعة الحادية عشرة. اقبل ما بقي من عمري، واجعل أيامي القادمة لك. آمين.\"},{\"t\":\"فرصة للصلاح\",\"ref\":\"غلاطية ٦: ١٠\",\"bk\":\"غلاطية\",\"v\":\"فإذا حسبما لنا فرصة فلنعمل الخير للجميع، ولا سيما لأهل الإيمان.\",\"r\":\"«فإذًا حسبما لنا فرصة فلنعمل الخير للجميع». كلمة «فرصة» تذكّرني أن الخير له وقت. أمامي اليوم من يحتاج كلمة أو مساعدة أو سؤالًا. إن أجّلت قد تفوت الفرصة. وأعمال المحبة الصغيرة، إذا أُجلّت، تتحول إلى ندم كبير. فليكن شعاري: اليوم لا غدًا.\",\"p\":\"يا رب، افتح عينيّ لفرص الخير التي تضعها أمامي. اجعلني سريعًا في المحبة، ولا تدعني أؤجل رحمة يمكن أن أقدمها اليوم. آمين.\"},{\"t\":\"حياتنا يوم واحد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس غريغوريوس اللاهوتي إن حياة الإنسان كلها يوم واحد بالنسبة للذين يتعبون بشوق. من يرى العمر يومًا واحدًا لا يضيعه في تأجيل. اجعل اليوم الذي لك أمانة أمام الله وقدّمه كله له.\",\"p\":\"يا رب، علّمني أن أحصي أيامي وأفتدي الوقت. اجعل اليوم الذي أنا فيه يومًا لك، فأتعب فيه بشوق وفرح. آمين.\",\"fq\":88}]},\"3-1\":{\"th\":\"جمال الخليقة\",\"m\":[{\"t\":\"أعمال أصابعك\",\"ref\":\"المزمور الثامن — باكر\",\"v\":\"لأني أرى السموات أعمال أصابعك. القمر والنجوم أنت أسستها.\",\"r\":\"يقف المرنم أمام السماء والقمر والنجوم فلا يرى مجرد مشهد، بل أعمال أصابع الله. الجمال حولنا دعوة إلى الشكر. اخرج اليوم إلى شرفة أو شباك أو شارع، وانظر دقيقة واحدة إلى السماء دون أن تنشغل بشيء، ثم قل: ما أعظم أعمالك.\",\"p\":\"يا رب، أرى السماوات أعمال أصابعك، والقمر والنجوم التي أسستها. افتح عيني على جمال خليقتك، وعلّمني أن أشكرك عليها ولا أمر بها غافلًا. آمين.\"},{\"t\":\"السماوات تحدّث بمجد الله\",\"ref\":\"المزامير ١٩: ١\",\"bk\":\"المزامير\",\"v\":\"السماوات تحدث بمجد الله، والفلك يخبر بعمل يديه.\",\"r\":\"«السماوات تحدث بمجد الله والفلك يخبر بعمل يديه». لا تحتاج السماء إلى كلمات لتعلن عظمة الله، فهي تتكلم بنظامها وجمالها. وأنا أحتاج أحيانًا أن أرفع نظري من شاشتي ومشاغلي إلى السماء لأتذكر أن لي أبًا عظيمًا يهتم بالتفاصيل.\",\"p\":\"يا خالق السماء والأرض، افتح عينيّ لأرى جمال أعمالك وأسبّحك بها. علّمني أن أتأمل في خليقتك فأزداد معرفة بمحبتك وحكمتك. آمين.\"},{\"t\":\"ما ندمت على الصمت\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال القديس أرسانيوس لتلاميذه قبيل رحيله: «مرارًا كثيرة ندمت لأني تكلمت، ولكن عن الصمت لم أندم». الصمت يفتح الأذن لسماع الخليقة وهي تسبّح. اجعل لك اليوم دقائق تصمت فيها وتتأمل ما حولك.\",\"p\":\"يا رب، علّمني أن أصمت لأسمع تسبيح خليقتك. وأعطني قلبًا هادئًا يرى فيها يدك ويشكر. آمين.\",\"fq\":42}]},\"3-2\":{\"th\":\"القلب المنسحق\",\"m\":[{\"t\":\"قريب من منسحقي القلب\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"قريب هو الرب من منسحقي القلب، ويخلص المتواضعين بالروح. كثيرة هي أحزان الصديقين، ومن جميعها ينجيهم الرب. يحفظ الرب جميع عظامهم. وواحدة منها لا تنكسر.\",\"r\":\"كسر القلب في عين الله ليس عيبًا، فهو «قريب من منسحقي القلب ويخلص المتواضعين بالروح». كثيرة أحزان الصديقين، لكن الرب ينجيهم منها كلها. إن كان في داخلك كسر لا تبوح به، فاعرضه اليوم على الله بكلمات قليلة.\",\"p\":\"قريب أنت يا رب من منسحقي القلب. خلّصني متواضعًا بالروح، وانجني من أحزاني، واحفظ كياني فلا ينكسر. آمين.\"},{\"t\":\"اتضعوا قدام الرب\",\"ref\":\"يعقوب ٤: ١٠\",\"bk\":\"يعقوب\",\"v\":\"اتضعوا قدام الرب فيرفعكم.\",\"r\":\"«اتضعوا قدام الرب فيرفعكم». المعادلة بسيطة وصعبة: أنزل أنا فيرفعني هو. لست مضطرًا أن أدافع عن نفسي أو أثبت قيمتي بالمنافسة. أضع نفسي في يده وهو يتولى الباقي، في الوقت الذي يراه. وهذا يعطيني سلامًا.\",\"p\":\"يا رب، علّمني أن أتضع أمامك فترفعني في الوقت الذي تراه. احفظني من الكبرياء والدفاع عن نفسي، واملأني بنعمتك. آمين.\"},{\"t\":\"اجلس وابكِ خطاياك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يجيب الأب مكاريوس عن معنى الهرب من الناس بأنه أن يجلس الإنسان في قلايته ويبكي خطاياه. ليس البكاء ضعفًا بل صدق. خصّص دقائق الليلة تجلس فيها أمام الله وتقول له ما يثقل ضميرك.\",\"p\":\"يا رب، امنحني دموع التوبة الصادقة. علّمني أن أجلس أمامك بصدق، وأعترف بخطاياي فتغسلها نعمتك. آمين.\",\"fq\":244}]},\"3-3\":{\"th\":\"الصوم المقبول\",\"m\":[{\"t\":\"تعبتُ في تنهدي\",\"ref\":\"المزمور السادس — باكر\",\"v\":\"تعبت في تنهدي. أعوم كل ليلة سريري، وبدموعي أبل فراشي. تعكرت من الغضب عيناي.\",\"r\":\"يبوح المرنم بتعبه وتنهده ودموعه. الصوم الحقيقي ينفتح على هذا الصدق: لا مظهر ولا استعراض بل رجوع إلى الله بكل القلب. ليكن صومك اليوم، بأي صورة تلتزم بها، فرصة أن تقول لله ما في داخلك كاملًا.\",\"p\":\"يا رب، تعبت في تنهدي، وأبلّ فراشي بدموعي. اسمع بكائي وتضرعي، واجعل صومي رجوعًا إليك بكل قلبي. آمين.\"},{\"t\":\"ارجعوا إليّ بكل قلوبكم\",\"ref\":\"يوئيل ٢: ١٢–١٣\",\"bk\":\"يوئيل\",\"v\":\"« ولكن الآن، يقول الرب، ارجعوا إلي بكل قلوبكم، وبالصوم والبكاء والنوح. ومزقوا قلوبكم لا ثيابكم». وارجعوا إلى الرب إلهكم لأنه رؤوف رحيم، بطيء الغضب وكثير الرأفة ويندم على الشر.\",\"r\":\"«ارجعوا إليّ بكل قلوبكم وبالصوم والبكاء والنوح، ومزقوا قلوبكم لا ثيابكم». الله لا يريد مظهرًا بل قلبًا. والرجوع إليه ليس رحلة مخيفة، فهو رحوم ورؤوف بطيء الغضب وكثير الرأفة. والباب مفتوح، وأنا أحتاج فقط أن أرجع بصدق.\",\"p\":\"يا رب، أنت حنان ورحيم. أرجع إليك بكل قلبي، فاقبلني ومزّق كل ما يحجبني عنك، وامنحني فرح الرجوع إلى بيت أبي. آمين.\"},{\"t\":\"الصلاة مع الصوم\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي: كما تبعد الأدوية القوية الوحوش السامة، هكذا تبعد الصلاة مع الصوم الفكر الشرير. الصوم وحده قد يصير مجرد حرمان، لكن اقترانه بالصلاة يجعله جهادًا. اجعل لكل امتناع اليوم صلاة قصيرة.\",\"p\":\"يا رب، اجعل صومي مقترنًا بالصلاة، وأبعد عني بهما كل فكر شرير. علّمني أن أصوم لك لا لنفسي. آمين.\",\"fq\":532}]},\"3-4\":{\"th\":\"الغلبة بالمسيح\",\"m\":[{\"t\":\"قوتي وتسبحتي\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"قوتي وتسبحتي هو الرب وقد صار لي خلاصا.\",\"r\":\"الغلبة في المسيح تبدأ بالاعتراف: «قوتي وتسبحتي هو الرب وقد صار لي خلاصًا». لا أنتصر بخبرتي ولا بقوتي، بل بمن صار لي خلاصًا. اذكر اليوم صراعًا تعبت منه، وقل لله إنك تسلّمه له لأنك ضعيف ولأنه أقوى.\",\"p\":\"أنت قوتي وتسبحتي يا رب، وقد صرت لي خلاصًا. اغلب عني وفيّ، واجعل انتصاري دائمًا باسمك. آمين.\"},{\"t\":\"أكثر من غالبين\",\"ref\":\"رومية ٨: ٣٧\",\"bk\":\"رومية\",\"v\":\"ولكننا في هذه جميعها يعظم انتصارنا بالذي أحبنا.\",\"r\":\"«ولكننا في هذه جميعها يعظم انتصارنا بالذي أحبنا». ليس انتصارنا بقوتنا بل بمحبته. حتى الشدة والضيق والاضطهاد لا تفصلني عنه. ما دام هو يحبني فأنا في أمان. وهذه المحبة هي الحصن الذي أختبئ فيه حين يعصف بي الألم.\",\"p\":\"يا رب، أشكرك لأن محبتك أقوى من كل شيء. ثبّتني فيها، ولا تدع الضيق أو الخوف يفصلني عنك، وامنحني أن أنتصر بك. آمين.\"},{\"t\":\"المسيح هو الذي غلبك\",\"ref\":\"\",\"v\":\"\",\"r\":\"قالت الأم سارة للشيطان الذي حاربها: «سيدي المسيح هو الذي غلبك لا أنا». ما أجمل التواضع الذي ينسب الانتصار لصاحبه! نحن لا ننتصر لنفتخر بل لنشكر. بعد أي نجاح روحي اليوم، لا تنسَ أن تعيده له.\",\"p\":\"يا ربي يسوع، أنت الذي تغلب في ضعفي. اجعلني أنسب إليك كل نصرة، وأتكل عليك في كل معركة. آمين.\",\"fq\":526}]},\"3-5\":{\"th\":\"كلمة الله غذاء\",\"m\":[{\"t\":\"أحلى من العسل\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"أفضل من الذهب والحجر الكثير الثمن، وأحلى من العسل والشهد.\",\"r\":\"يقارن المرنم كلمة الله بالذهب وبالعسل: أغلى من الذهب وأحلى من العسل. فهي غذاء يُتذوق وليست معلومة تُحفظ. اقرأ اليوم آية واحدة ببطء، وكأنك تتذوق كل كلمة فيها، وانظر هل تعطيك شبعًا أم تشتهي المزيد.\",\"p\":\"كلمتك يا رب أفضل من الذهب والحجر الكثير الثمن، وأحلى من العسل والشهد. اجعلني أشتهيها وأتغذى بها كل يوم. آمين.\"},{\"t\":\"ليس بالخبز وحده\",\"ref\":\"متى ٤: ٤\",\"bk\":\"متى\",\"v\":\"فأجاب وقال: «مكتوب: ليس بالخبز وحده يحيا الإنسان، بل بكل كلمة تخرج من فم الله».\",\"r\":\"«مكتوب: ليس بالخبز وحده يحيا الإنسان بل بكل كلمة تخرج من فم الله». المسيح كان جائعًا بعد أربعين يومًا، ومع ذلك قدّم كلمة الله على الخبز. وأنا كثيرًا ما أُطعم جسدي ثلاث مرات وأنسى أن أُطعم روحي مرة واحدة.\",\"p\":\"يا رب، أنت خبز الحياة. أشبع روحي بكلمتك كل يوم، وعلّمني أن أشتاق إليها أكثر من الطعام، وأعمل بها في حياتي. آمين.\"},{\"t\":\"حياة بكلمة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس: «حياة بدون كلام خير من كلام بدون حياة». كلمة الله تغذّينا حين نعيشها. لا يكفي أن نقرأها، بل يجب أن تتحول إلى سلوك. اختر اليوم كلمة قرأتها أخيرًا واجعلها حياة في موقف واحد.\",\"p\":\"يا رب، اجعل كلمتك حياة فيّ لا مجرد معرفة. أعطني أن أعيش ما أقرأ، فتكون حياتي كلمة مقروءة من الناس. آمين.\",\"fq\":172}]},\"3-6\":{\"th\":\"الشهادة للمسيح\",\"m\":[{\"t\":\"بشروا من يوم إلى يوم\",\"ref\":\"المزمور ٩٥ (٩٦) — التاسعة\",\"v\":\"بشروا من يوم إلى يوم بخلاصه. حدثوا في الأمم بمجده وبين جميع الشعوب بعجائبه، لأن الرب عظيم هو ومسبح جدا.\",\"r\":\"يدعو المرنم إلى التبشير اليومي: يومًا بعد يوم، وبخلاص الله لا بأفكارنا. الشهادة ليست حدثًا استثنائيًا بل عادة أن نحدّث بعجائب الله. فاليوم، أخبر شخصًا واحدًا بفضل إلهي عليك، بكلمات صادقة وبسيطة.\",\"p\":\"يا رب، أبشر بخلاصك من يوم إلى يوم، وأحدّث بمجدك وعجائبك بين الناس. اجعل شهادتي صادقة وحياتي مرآة لمحبتك. آمين.\"},{\"t\":\"فليضئ نوركم\",\"ref\":\"متى ٥: ١٦\",\"bk\":\"متى\",\"v\":\"فليضئ نوركم هكذا قدام الناس، لكي يروا أعمالكم الحسنة، ويمجدوا أباكم الذي في السماوات.\",\"r\":\"«فليضئ نوركم هكذا قدام الناس لكي يروا أعمالكم الحسنة ويمجدوا أباكم الذي في السماوات». الغاية ليست أن يمدحوني بل أن يمجدوا الله. والنور لا يتكلف، يضيء فقط. وكل عمل صالح أعمله بروح محبة يصير إضاءة صغيرة لمن حولي.\",\"p\":\"يا نور العالم، اجعلني أضيء بنورك وحدك. أعطني أعمالًا حسنة تمجّد أباك، وبعّد عني حب الظهور، وألهمني أن أعكس محبتك. آمين.\"},{\"t\":\"يتكلمون كثيرًا ويعملون قليلًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"ملاحظة الأب بيمن قصيرة: الناس في أغلب الأحوال يتكلمون وفي القليل يعملون. وأقوى شهادة هي العمل الذي يسبق الكلام. اسأل نفسك اليوم: ماذا قلتُ عن المسيح ولم أعشه؟ وابدأ بالفعل لا بالقول.\",\"p\":\"يا رب، علّمني أن أشهد بأعمالي قبل أقوالي. اجعل حياتي موافقة لما أقول عنك. آمين.\",\"fq\":354}]},\"3-7\":{\"th\":\"المسيح الشافي\",\"m\":[{\"t\":\"يشفي المنكسري القلوب\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"الرب يشفي المنكسري القلوب. ويجبر جميع كسرهم.\",\"r\":\"يعلن المرنم أن الرب يشفي المنكسري القلوب ويجبر جميع كسرهم. الشفاء الأعمق هو شفاء الداخل. فقل له اليوم من أعماقك: ما انكسر فيّ أنت تعرفه، فاجبره أنت. ثم صلِّ لمن تعرف أنه مريض في جسده أو نفسه.\",\"p\":\"يا رب، أنت تشفي المنكسري القلوب وتجبر جميع كسرهم. اشفِ كل ما انكسر فيّ وفي أحبائي، وكن طبيب نفوسنا وأجسادنا. آمين.\"},{\"t\":\"إن أردت تقدر\",\"ref\":\"لوقا ٥: ١٢–١٣\",\"bk\":\"لوقا\",\"v\":\"وكان في إحدى المدن، فإذا رجل مملوء برصا. فلما رأى يسوع خر على وجهه وطلب إليه قائلا: «يا سيد، إن أردت تقدر أن تطهرني». فمد يده ولمسه قائلا: «أريد، فاطهر!». وللوقت ذهب عنه البرص.\",\"r\":\"«يا سيد إن أردت تقدر أن تطهرني». ما أجمل هذا الإيمان المتواضع! لم يطالب بل رجا. والمسيح لمس الأبرص، وكان اللمس ممنوعًا، فكسر حاجز النجاسة والعزلة. جاوب الرب بكلمتين: «أريد فاطهر». وهكذا أتعلم أن إرادته نحوي هي الشفاء.\",\"p\":\"يا رب، إن أردت تقدر أن تطهرني وتشفيني. المس جراحي الخفية، واكسر عزلتي، وأعدني إلى الشركة معك ومع إخوتي. آمين.\"},{\"t\":\"مرض بلا شكوى\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي: إذا أزعجنا المرض فلا نحزن إن لم نقدر أن نسبّح الرب بصوتنا، لأن هذا لتنقية الأهواء. المرض تعب، لكنه قد يصير مدرسة صبر وشكر. صلِّ اليوم من أجل مريض واشكر على صحتك.\",\"p\":\"يا رب، اشفِ المرضى واعطِهم صبرًا وسلامًا. وعلّمني أن أشكرك في المرض وفي الصحة، وأجد فيهما محبتك. آمين.\",\"fq\":536}]},\"3-8\":{\"th\":\"الإيمان الواثق\",\"m\":[{\"t\":\"عليك توكلت\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"يا إلهي عليك توكلت. فلا تخزني إلى الأبد.\",\"r\":\"عبارة المرنم قصيرة وصادقة: «يا إلهي عليك توكلت، فلا تخزني إلى الأبد». الإيمان الواثق ليس أن أضمن النتيجة بل أن أسلّمها. في أمر لا تعرف كيف سينتهي اليوم، كرّر هذه الجملة بهدوء كلما عاد القلق.\",\"p\":\"يا إلهي، عليك توكلت، فلا تخزني إلى الأبد. ثبّت إيماني حين تغيب النتائج، واجعلني واثقًا بأنك أمين. آمين.\"},{\"t\":\"لا تخف آمن فقط\",\"ref\":\"مرقس ٥: ٣٦\",\"bk\":\"مرقس\",\"v\":\"فسمع يسوع لوقته الكلمة التي قيلت، فقال لرئيس المجمع: «لا تخف! آمن فقط».\",\"r\":\"«لا تخف، آمن فقط». قيلت هذه الكلمات لرجل سمع أسوأ خبر في حياته. وسط اليأس يأتيه صوت المسيح الهادئ. الإيمان لا ينكر الواقع، لكنه يضع المسيح فوقه. وأنا أحتاج أن أسمع هذه الكلمة في كل مرة تأتيني فيها أخبار مخيفة.\",\"p\":\"يا رب، اسمع صراخي في ضيقي. قل لقلبي: لا تخف. ثبّت إيماني في كل خوف، وأقم ما مات من رجاء وفرح في حياتي. آمين.\"},{\"t\":\"الله محب\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل ثلاثة شيوخ الأب سيسوى عن أمور مخيفة، فأجاب أنه لا يذكر شيئًا منها لأنه يعرف أن الله محب ويرجو أن يرحمه. هذا هو الإيمان الواثق: أن أثق بمحبته أكثر من خوفي. هذه الجملة تكفي لنهارك.\",\"p\":\"يا رب، أعرف أنك محب، وأرجو رحمتك. ثبّتني على هذا الإيمان البسيط في كل ظرف. آمين.\",\"fq\":493}]},\"3-9\":{\"th\":\"محبة الأعداء\",\"m\":[{\"t\":\"باركناكم باسم الرب\",\"ref\":\"المزمور ١٢٨ (١٢٩) — الغروب\",\"v\":\"ولم يقل المجتازون إن بركة الرب عليكم. باركناكم باسم الرب هلليلويا.\",\"r\":\"بعد ذكر الأعداء الذين حاربوا شعب الله، يختم المزمور بكلمة بركة: «باركناكم باسم الرب». هذه محبة تتحدى المنطق. وهي ثمرة قلب لا يحمل مرارة. من أساء إليك مؤخرًا؟ ابدأ اليوم بأن تذكره في صلاتك بالخير.\",\"p\":\"يا رب، علّمني أن أبارك من حاربني. انزع من قلبي المرارة والحقد، واملأه بمحبتك التي تغفر وتبارك. آمين.\"},{\"t\":\"يا أبتاه اغفر لهم\",\"ref\":\"لوقا ٢٣: ٣٤\",\"bk\":\"لوقا\",\"v\":\"فقال يسوع: «ياأبتاه، اغفر لهم، لأنهم لا يعلمون ماذا يفعلون». وإذ اقتسموا ثيابه اقترعوا عليها.\",\"r\":\"«يا أبتاه اغفر لهم لأنهم لا يعلمون ماذا يفعلون». هذه كلمات المسيح بين المسامير. لم يهدد ولم يلعن، بل صلّى. وإن كان هذا فعل المسيح بمن صلبه، فما حجة من لا يغفر لأخيه؟ أحتاج أن أنظر إلى الصليب حين أصعب عليّ المسامحة.\",\"p\":\"يا رب يسوع، يا من غفرت لصالبيك، علّمني أن أغفر. حرر قلبي من المرارة، وأعطني أن أصلي لأعدائي كما صليت أنت. آمين.\"},{\"t\":\"صلِّ أولًا من أجل أعدائك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب زينون أن من يريد الله أن يستجيب صلاته عليه، حين ينهض للصلاة، أن يصلّي أولًا من أجل أعدائه. تبدأ استجابة الله من داخلنا بالتطهر من الحقد. قبل أن تطلب لنفسك اليوم، اطلب لمن يعاديك.\",\"p\":\"يا رب، أصلي من أجل أعدائي وأطلب لهم الخير. طهّر قلبي من كل حقد، واستجب صلاتي كما استجبت لمن غفر. آمين.\",\"fq\":116}]},\"3-10\":{\"th\":\"الحضور الإلهي\",\"m\":[{\"t\":\"عيناي إلى الرب في كل حين\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"عيناي تنظران إلى الرب في كل حين. لأنه يجتذب من الفخ رجلي.\",\"r\":\"يعلّمنا المرنم أن نبقي عيوننا على الرب في كل حين، لأنه يجتذب من الفخ رجلنا. الحضور الإلهي ليس شعورًا يومًا ويغيب يومًا، بل التفات مستمر. اجعل ساعة هاتفك مذكّرًا: عند كل ساعة تامة ارفع عينيك إلى الرب لحظة.\",\"p\":\"عيناي تنظران إليك يا رب في كل حين، فاجتذب من الفخ رجلي. اجعلني واعيًا لحضورك في عملي وطريقي وبيتي. آمين.\"},{\"t\":\"حقًا إن الرب في هذا المكان\",\"ref\":\"التكوين ٢٨: ١٦\",\"bk\":\"التكوين\",\"v\":\"فاستيقظ يعقوب من نومه وقال: «حقا إن الرب في هذا المكان وأنا لم أعلم!».\",\"r\":\"«حقًا إن الرب في هذا المكان وأنا لم أعلم». كان يعقوب هاربًا خائفًا وحيدًا، ومع ذلك كان الله هناك. وكم مرة كان الله في مكاني وأنا لم أنتبه! ربما أحتاج أن أقول في كل مكان: «حقًا إن الرب هنا».\",\"p\":\"يا رب، افتح عينيّ لأعرف أنك حاضر في كل مكان. اجعل بيتي وعملي بيوتًا لك، وعلّمني أن أبني مذبح صلاة حيثما أكون. آمين.\"},{\"t\":\"كجندي في حضرة الملك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب سيرابيون الإنسان القائم في حضرة الله بجنود الملك الذين لا يلتفتون يمنة ويسرة، فلا تخيفه أعمال العدو. من يركّز على الله لا تشغله التفاصيل المخيفة. حدّد اليوم ما يشتتك وأعد عينك إلى الله.\",\"p\":\"يا رب، ثبّت نظري عليك فلا يخيفني العدو ولا تشغلني الأمور. كن أمامي في كل حين. آمين.\",\"fq\":520}]},\"3-11\":{\"th\":\"الصليب قوة الله\",\"m\":[{\"t\":\"بسطتَ يديك على الصليب\",\"ref\":\"قطعة السادسة (٤)\",\"v\":\"صنعت خلاصا في وسط الأرض كلها أيها المسيح إلهنا، عندما بسطت يديك الطاهرتين على عود الصليب.\",\"r\":\"في وسط الأرض بسط المسيح يديه ليحتضن العالم كله. الصليب في أعيننا ليس رمز ضعف بل مكان انتصار المحبة. اصنع اليوم علامة الصليب ببطء وتأمل أن هذه اليد التي بُسطت لك لا تزال مفتوحة.\",\"p\":\"أيها المسيح إلهنا، صنعت خلاصًا في وسط الأرض عندما بسطت يديك على الصليب. أنا أيضًا أتمسك بصليبك قوةً وفخرًا لي. آمين.\"},{\"t\":\"أجذب إليّ الجميع\",\"ref\":\"يوحنا ١٢: ٣٢\",\"bk\":\"يوحنا\",\"v\":\"وأنا إن ارتفعت عن الأرض أجذب إلي الجميع».\",\"r\":\"«وأنا إن ارتفعت عن الأرض أجذب إليّ الجميع». ارتفاع المسيح على الصليب ليس إذلالًا بل جاذبية. كل من نظر إليه بإيمان وجد فيه حبًا لا يُقاوم. وأنا أيضًا قد انجذبت إليه بمحبته الكبيرة لي.\",\"p\":\"يا رب يسوع المرفوع على الصليب، اجذبني إليك وأجذب كل من أحب. اجمع المتفرقين، واشفِ كل انقسام بمحبتك التي لا تنتهي. آمين.\"},{\"t\":\"احمل صليبك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يرشد الأب نيلوس من أراد أن يصلي دون ارتباك أن يذهب ويبيع ما له ويعطيه للمساكين، ثم يحمل صليبه وينكر نفسه. قوة الصليب تظهر في تخلينا عما يعطلنا. ما الذي تحتاج أن تتخلى عنه اليوم لتصلي بحرية؟\",\"p\":\"يا رب، أعطني أن أحمل صليبي وأنكر نفسي. حرّرني مما يربطني بالأرض حتى أصلي إليك بقلب حر. آمين.\",\"fq\":291}]},\"3-12\":{\"th\":\"الرجاء في الألم\",\"m\":[{\"t\":\"في العشاء بكاء وفي الصباح سرور\",\"ref\":\"المزمور ٢٩ (٣٠) — الثالثة\",\"v\":\"في العشاء يحل البكاء. وفى الصباح السرور.\",\"r\":\"كلمات المرنم القليلة تحمل منطق الرجاء: البكاء لا يبقى، والسرور يأتي في الصباح. الألم مرحلة وليس هوية. إن كنت في ليلة ثقيلة اليوم، ضع الصباح في قلبك كوعد من الله، حتى لو لم تره بعد.\",\"p\":\"يا رب، إن حلّ البكاء في العشاء فاجعل السرور في الصباح. ارفعني من حزني، وأعطني أن أرجو فيك مهما طالت ليلتي. آمين.\"},{\"t\":\"أحسب أن آلام هذا الزمان\",\"ref\":\"رومية ٨: ١٨\",\"bk\":\"رومية\",\"v\":\"فإني أحسب أن آلام الزمان الحاضر لا تقاس بالمجد العتيد أن يستعلن فينا.\",\"r\":\"«فإني أحسب أن آلام الزمان الحاضر لا تقاس بالمجد العتيد أن يستعلن فينا». لا ينكر بولس الألم، لكنه يضعه في الميزان. وحين أرى الصورة الكاملة أجد أن الضيق مؤقت والمجد دائم. وهذا الرجاء لا يلغي دموعي، لكنه يمنعها من أن تصير يأسًا.\",\"p\":\"يا رب، علّمني أن أحتمل الألم بالرجاء. أرني المجد الذي تعدّه، وامنحني قوة وصبرًا، وكن معي في كل ضيق. آمين.\"},{\"t\":\"بصبركم تقتنون نفوسكم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس إن الخلاص يُقتنى في وقت الضيقات، وإن الأردأ أن يتبع الإنسان قلبه بدل شريعة الله. فالضيق فرصة لا عقوبة. فكّر في ضيق تمرّ به: ما الخير الذي يمكن أن يخرج من الصبر عليه؟\",\"p\":\"يا رب، علّمني أن أقتني نفسي بالصبر في الضيقات. وفي ألمي أرني خيرًا ينمو بنعمتك. آمين.\",\"fq\":171}]},\"3-13\":{\"th\":\"لص اليمين\",\"m\":[{\"t\":\"اذكرني يا رب\",\"ref\":\"قطعة التاسعة (٤)\",\"v\":\"لما أبصر اللص رئيس الحياة على الصليب معلقا، قال: ... اذكرني يا رب متى جئت في ملكوتك.\",\"r\":\"في الصلب يرى اللص ما لم يره المتعلمون: أن المصلوب إله. وبكلمة واحدة تحوّل من مجرم إلى شريك في الفردوس. ليس التبرير في كثرة الأعمال بل في صدق الطلب. قلها اليوم لله من قلبك: اذكرني يا رب.\",\"p\":\"اذكرني يا رب متى جئت في ملكوتك. أنا الخاطئ، أعترف أنك الإله المتجسد. اقبل بساطة اعترافي، وأدخلني فردوسك برحمتك. آمين.\"},{\"t\":\"اطلبوا الرب\",\"ref\":\"إشعياء ٥٥: ٦–٧\",\"bk\":\"إشعياء\",\"v\":\"اطلبوا الرب ما دام يوجد. ادعوه وهو قريب. ليترك الشرير طريقه، ورجل الإثم أفكاره، وليتب إلى الرب فيرحمه، وإلى إلهنا لأنه يكثر الغفران.\",\"r\":\"«اطلبوا الرب ما دام يوجد، ادعوه وهو قريب». الدعوة ليست مجرد فرصة، بل هي نعمة. فالله قريب الآن. وربما لا أشعر بقربه دائمًا لكنه يقول إنه قريب. وعندما أرجع إليه يرحمني ويكثر الغفران. لا شروط معقدة، فقط رجوع.\",\"p\":\"يا رب، أنت قريب مني. أطلبك الآن وأعود إليك، فارحمني واغفر لي كثيرًا، وأعطني قوة أن أتوب كل يوم. آمين.\"},{\"t\":\"برّر بكلمة واحدة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كسنثيا إن اللص على الصليب تبرر بكلمة واحدة، بينما خسر يهوذا في ليلة واحدة كل ما كان له. لا يفتخر أحد بسيرته ولا ييأس أحد من سقوطه. صلِّ اليوم بتواضع: لا أعتمد على ما أنا فيه بل على رحمتك.\",\"p\":\"يا رب، لا أعتمد على برّي ولا ييأس قلبي من خطاياي. اقبلني كما قبلت اللص التائب وأعطني فردوسك. آمين.\",\"fq\":307}]},\"3-14\":{\"th\":\"الراعي الصالح\",\"m\":[{\"t\":\"الرب يرعاني\",\"ref\":\"المزمور ٢٢ (٢٣) — الثالثة\",\"v\":\"الرب يرعاني فلا يعوزني شئ. في مراع خضر يسكنني، إلى ماء الراحة يوردني. يرد نفسي. يهدني إلى سبل البر من أجل اسمه.\",\"r\":\"أول ما يقوله المرنم عن الراعي أنه لا ينقص شيئًا: الرعي والماء والراحة والهداية. المسيح هو الراعي الصالح الذي بذل نفسه عن الخراف. فتأمّل اليوم في ما يعوزك فعلًا، وهل هو ما تظن أم ما يعرفه الراعي؟\",\"p\":\"الرب راعيّ فلا يعوزني شيء. أسكنني في مراع خضر، وأوردني إلى ماء الراحة، وردّ نفسي، واهدني إلى سبل البر من أجل اسمك. آمين.\"},{\"t\":\"يبذل نفسه عن الخراف\",\"ref\":\"يوحنا ١٠: ١١\",\"bk\":\"يوحنا\",\"v\":\"أنا هو الراعي الصالح، والراعي الصالح يبذل نفسه عن الخراف.\",\"r\":\"«أنا هو الراعي الصالح، والراعي الصالح يبذل نفسه عن الخراف». لست مجرد عضو في قطيع كبير، بل أنا خروفه الذي يعرفه بالاسم ويبذل نفسه عنه. وكل ما أمر به، يمر به راعيّ الذي لا يهرب. وهذا يعطيني أمانًا عميقًا لا تعطيه أي مؤسسة.\",\"p\":\"يا راعي الخراف العظيم، أشكرك لأنك بذلت نفسك عني. احفظني في قطيعك، ولا تدعني أضل، وبارك رعاتنا وكل من يخدم ويتعب. آمين.\"},{\"t\":\"التصق بمن يعرف طريق الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوجّه الأب بيمن من تعب من نفسه: اذهب والتصق بإنسان يخاف الله، وبملازمتك إياه يعلمك كيف تخاف الله. هكذا تُعرف الخراف: تتبع راعيًا وتتعلم من رعاته. من تتبع اليوم في حياتك الروحية؟ ومن هو الأب الذي تسأله؟\",\"p\":\"يا راعي نفسي، ضع في طريقي من يعلّمني مخافتك. وثبّتني في اتباعك أنت الراعي الصالح. آمين.\",\"fq\":362}]},\"3-15\":{\"th\":\"سماع الصوت\",\"m\":[{\"t\":\"إني أسمع ما يتكلم به الرب\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"إني أسمع ما يتكلم به الرب الإله، لأنه يتكلم بالسلام لشعبه ولقديسيه؛ وللذين رجعوا إليه بكل قلوبهم.\",\"r\":\"يعلن المرنم أنه مستعد لأن يسمع ما يتكلم به الرب، لأنه يتكلم بالسلام لشعبه وللذين رجعوا إليه بكل قلوبهم. السمع يسبق السلام. فاجلس اليوم خمس دقائق دون طلب ولا شكوى، وقل: تكلم يا رب فعبدك سامع.\",\"p\":\"يا رب، إني أسمع ما تتكلم به، فتكلّم بالسلام لشعبك ولقديسيك. اجعلني من الراجعين إليك بكل قلوبهم. آمين.\"},{\"t\":\"يدعو خرافه بأسمائها\",\"ref\":\"يوحنا ١٠: ٣\",\"bk\":\"يوحنا\",\"v\":\"لهذا يفتح البواب، والخراف تسمع صوته، فيدعو خرافه الخاصة بأسماء ويخرجها.\",\"r\":\"«ويدعو خرافه الخاصة بأسماء ويخرجها». المسيح يعرفني باسمي، لست رقمًا في كنيسة. ويخرجني من حظيرة الخوف والتعود إلى مرعى جديد. وكل مرة يناديني فيها باسمي أشعر بقيمتي، وأطمئن أنني معروف ومحبوب كما أنا.\",\"p\":\"يا رب، أنت تعرفني باسمي. ناد قلبي ولا تدعني أتجاهل صوتك، وأخرجني من كل ما يعيقني، لأتبعك بفرح وثقة. آمين.\"},{\"t\":\"الغني الذي لا نسمعه\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب مكاريوس: ربنا هو الغني ويحبنا ولكننا لا نريد أن نسمع له، أما عدونا فهو فقير ويكرهنا إلا أننا نحبه ونحب نتانته. نسمع أصواتًا كثيرة تبدو جذابة وتفرغنا. اختر اليوم أن تنصت لصوت الله قبل كل صوت آخر.\",\"p\":\"يا رب، أنت الغني الذي يحبنا، فاجعلني أسمع صوتك وأعرضه على ضجيج العالم. آمين.\",\"fq\":243}]},\"3-16\":{\"th\":\"الكنيسة بيت الله\",\"m\":[{\"t\":\"ما أحلى مساكنك\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"مساكنك محبوبة يا رب إله القوات. تشتاق وتذوب نفسي للدخول إلى ديار الرب. قلبي وجسمي قد ابتهجا بالإله الحي.\",\"r\":\"يعبّر المرنم عن شوق إلى بيت الله: مساكنك محبوبة، ونفسي تشتاق وتذوب للدخول إلى ديار الرب. الكنيسة بيت يبتهج فيه القلب والجسد. فكّر في آخر مرة اشتقت فيها إلى الكنيسة، وجدد هذا الشوق اليوم بصلاة.\",\"p\":\"ما أحلى مساكنك يا رب الجنود. تشتاق نفسي للدخول إلى ديارك، فيبتهج قلبي وجسمي بالإله الحي. آمين.\"},{\"t\":\"كانوا يواظبون\",\"ref\":\"أعمال الرسل ٢: ٤٢\",\"bk\":\"أعمال الرسل\",\"v\":\"وكانوا يواظبون على تعليم الرسل، والشركة، وكسر الخبز، والصلوات.\",\"r\":\"«وكانوا يواظبون على تعليم الرسل والشركة وكسر الخبز والصلوات». أربعة أعمدة: التعليم والشركة والإفخارستيا والصلاة. ومن واظب عليها ثبت. والمواظبة ليست سهلة، لكنها سر النمو. وحين أنتظم فيها أجد قوة تحملني في الأيام الثقيلة.\",\"p\":\"يا رب، علّمني المواظبة على تعليمك وصلواتك وأسرارك. اجعلني عضوًا في جسدك أحب إخوتي وأخدمهم، وأشارك في فرح كنيستك. آمين.\"},{\"t\":\"ساعات الاجتماع وساعات الخلوة\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينبّه الأب بيمن إلى النمو الخفي: ألا نهمل ساعات الاجتماع وساعات الاختلاء. أي نعيش الكنيسة جماعة وفردًا معًا. هل تنتظم في اجتماعك الكنسي كما تنتظم في خلوتك؟ اختر ما تحتاج أن تقوّيه.\",\"p\":\"يا رب، علّمني أن أحب الاجتماع في بيتك كما أحب الخلوة معك. اجعلني عضوًا حيًا في كنيستك. آمين.\",\"fq\":439}]},\"3-17\":{\"th\":\"خبز الحياة\",\"m\":[{\"t\":\"أعطوهم أنتم ليأكلوا\",\"ref\":\"إنجيل التاسعة\",\"v\":\"فأخذ الخمس خبزات والسمكتين، ونظر إلى السماء، وباركها وقسمها، وأعطى التلاميذ ليضعوا أمام الجموع. فأكلوا جميعهم وشبعوا.\",\"r\":\"أمام جموع جائعة لم يكن عند التلاميذ إلا خمس خبزات وسمكتان، لكن في يد المسيح صارت كافية. الخبز المبارك يشبع الجميع. ما القليل الذي في يدك اليوم؟ سلّمه للمسيح ليباركه، ولا تقل إنه لا يكفي.\",\"p\":\"يا رب، خذ القليل الذي عندي وباركه. أشبع به جوعي وجوع من حولي، وعلّمني أن أسلّم لك ما عندي بثقة. آمين.\"},{\"t\":\"الخبز الحي\",\"ref\":\"يوحنا ٦: ٥١\",\"bk\":\"يوحنا\",\"v\":\"أنا هو الخبز الحي الذي نزل من السماء. إن أكل أحد من هذا الخبز يحيا إلى الأبد. والخبز الذي أنا أعطي هو جسدي الذي أبذله من أجل حياة العالم».\",\"r\":\"«أنا هو الخبز الحي الذي نزل من السماء، إن أكل أحد من هذا الخبز يحيا إلى الأبد». المسيح لا يعطيني تعليمًا فقط بل يعطيني نفسه. وفي سر الإفخارستيا أتناول جسده ودمه لأثبت فيه ويثبت فيّ. فما أعظم نعمة القداس!\",\"p\":\"يا رب يسوع، أنت الخبز الحي. أشكرك لأنك تعطيني نفسك. اجعلني أستعد للمناولة بقلب نقي، وأثبت فيك وتثبت فيّ. آمين.\"},{\"t\":\"يد الله التي تشبع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيرينيوس إنه أمضى السنة يجني ويخيط ويحوك، لكن لولا يد الله التي كانت تشبعه ما أمكن أن يشبع. العمل وسيلة والشبع من الله. تأمّل اليوم في خبزك اليومي كيف جاءك، واشكر الذي يعطي.\",\"p\":\"يا رب، أنت الذي تشبعنا بعمل أيدينا وبنعمتك. أشكرك على خبزي اليومي، ولا تحرم أحدًا من هذا الشبع. آمين.\",\"fq\":524}]},\"3-18\":{\"th\":\"القيامة والحياة\",\"m\":[{\"t\":\"فلن أموت بل أحيا\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"فلن أموت بعد، بل أحيا وأحدث بأعمال الرب. تأديبا أدبني الرب وإلى الموت لم يسلمني.\",\"r\":\"بعد التأديب والألم يعلن المرنم أنه لن يموت بل يحيا ويحدّث بأعمال الرب. هذه لغة الرجاء الذي بلغ القيامة. المسيح يهب الحياة التي لا تنتهي، فالموت لم يعد آخر الكلام. اذكر اليوم عزيزًا فارقك، وقل: الذي أحيا المسيح سيحيينا.\",\"p\":\"يا رب، أنا لن أموت بعد بل أحيا وأحدّث بأعمالك. أدبتني، لكنك إلى الموت لم تسلمني. أشكرك على رجاء القيامة. آمين.\"},{\"t\":\"باكورة الراقدين\",\"ref\":\"كورنثوس الأولى ١٥: ٢٠\",\"bk\":\"كورنثوس الأولى\",\"v\":\"ولكن الآن قد قام المسيح من الأموات وصار باكورة الراقدين.\",\"r\":\"«ولكن الآن قد قام المسيح من الأموات وصار باكورة الراقدين». الباكورة هي أول الثمر الذي يضمن أن الحصاد قادم. وقيامة المسيح هي ضمان قيامتي. ما يحدث له سيحدث لي. وهذا يغير نظرتي إلى الموت: إنه عبور لا فناء.\",\"p\":\"يا رب المسيح القائم، أشكرك لأنك باكورة الراقدين. ثبّت يقيني بقيامتك، واجعلني أعمل بلا يأس، وأحيا كمن ينتظر لقاءك. آمين.\"},{\"t\":\"الموت نصب العينين\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سارة: «أضع رجلي على السلّم، وقبل أن أصعد عليه أجعل الموت نصب عيني». ذكر الموت عند المؤمن ليس تشاؤمًا بل يقظة، لأن وراءه القيامة. أي قرار اليوم يتغير إذا تذكرت أن عمرك محدود؟\",\"p\":\"يا رب، علّمني أن أذكر الموت بيقظة لا بخوف، وأن أحيا اليوم لك في رجاء قيامتك. آمين.\",\"fq\":529}]},\"3-19\":{\"th\":\"نور المسيح\",\"m\":[{\"t\":\"أرسل نورك وحقك\",\"ref\":\"المزمور ٤٢ (٤٣) — الثالثة\",\"v\":\"أرسل نورك وحقك. فإنهما يهديانني ويصعدانني إلى جبلك المقدس وإلى مسكنك. فأدخل إلى مذبح الله تجاه وجه الله الذي يفرح شبابي.\",\"r\":\"يطلب المرنم نور الله وحقه ليهدياه إلى جبله المقدس. المسيح هو النور الذي يضيء كل إنسان. والنور لا يفرض نفسه بل يُطلب. اطلب اليوم نورًا لقرار محيّر، ثم تقدّم خطوة صغيرة بما يظهر لك.\",\"p\":\"أرسل نورك وحقك يا رب، فيهدياني ويصعداني إلى جبلك المقدس. أدخلني مذبحك، فيفرح شبابي بوجهك. آمين.\"},{\"t\":\"كأولاد نور\",\"ref\":\"أفسس ٥: ٨\",\"bk\":\"أفسس\",\"v\":\"لأنكم كنتم قبلا ظلمة، وأما الآن فنور في الرب. اسلكوا كأولاد نور.\",\"r\":\"«لأنكم كنتم قبلًا ظلمة وأما الآن فنور في الرب، اسلكوا كأولاد نور». لاحظ: لم يقل «تحت النور» بل «نور»! النعمة غيّرت هويتي. وحياتي اليومية هي ترجمة هذه الهوية: صدق وطيبة وعدل. فلا أعيش كما كنت قبلًا.\",\"p\":\"يا رب، أشكرك لأنك جعلتني نورًا فيك. علّمني أن أسلك في الصلاح والبر والحق، وأمتحن ما يرضيك، وأبتعد عن أعمال الظلمة. آمين.\"},{\"t\":\"روح الله يستقر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كرونيوس: النفس إذا سهرت وجمعت ذاتها من التشتت وهجرت إرادتها، يستقر عليها روح الله. هذا هو النور الداخلي: سكنى الروح. ما الذي يشتتك اليوم؟ حدده، واجمع نفسك حول كلمة واحدة من الله.\",\"p\":\"يا رب، اجمع شتات فكري، ودعني أهجر إرادتي من أجلك. فيستقر عليّ روحك وينير داخلي. آمين.\",\"fq\":217}]},\"3-20\":{\"th\":\"العمل في الخفاء\",\"m\":[{\"t\":\"أسلك بدعة قلبي في بيتي\",\"ref\":\"المزمور ١٠٠ (١٠١) — التاسعة\",\"v\":\"لقد كنت أسلك بدعة قلبي في وسط بيتي. لم أضع أمام عيني أمرا يخالف الناموس.\",\"r\":\"يتعهد المرنم أن يسلك بدعة القلب في وسط بيته، حيث لا أحد يراه إلا الله. العمل في الخفاء هو الامتحان الحقيقي للحياة. اختر اليوم عملًا صغيرًا للخير لا يعرفه أحد، واجعله سرًا بينك وبين الله.\",\"p\":\"يا رب، أسلك بدعة قلبي في وسط بيتي، ولا أضع أمام عيني أمرًا يخالف ناموسك. اجعل خفايا حياتي مرضية لك. آمين.\"},{\"t\":\"عبيد بطّالون\",\"ref\":\"لوقا ١٧: ١٠\",\"bk\":\"لوقا\",\"v\":\"كذلك أنتم أيضا، متى فعلتم كل ما أمرتم به فقولوا: إننا عبيد بطالون، لأننا إنما عملنا ما كان يجب علينا».\",\"r\":\"«هكذا أنتم أيضًا متى فعلتم كل ما أمرتم به فقولوا إننا عبيد بطالون، لأننا إنما عملنا ما كان يجب علينا». ليست دعوة لتحقير الذات، بل لحماية الخدمة من الكبرياء. فكل ما أقوم به هو بنعمته، فلا أطالب بمكافأة بل أشكره أنه أشركني.\",\"p\":\"يا رب، أنت صاحب الفضل في كل ما أعمل. اجعلني عبدًا أمينًا فرحًا، يخدم بتواضع ويشكر دائمًا، ولا يطلب مجدًا لنفسه. آمين.\"},{\"t\":\"أعمال بلا عين بشرية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعدّد الأب يوسف الطيبي ثلاثة أمور مكرمة في عين الرب، منها أن يُتمّ الإنسان أعماله أمام الرب بدون أي أمر بشري. تتحول أعمالنا بهذا إلى صلاة. اختر أمرًا تفعله اليوم دون أن تنتظر شكرًا أو تقديرًا.\",\"p\":\"يا رب، علّمني أن أعمل لك وحدك، لا لأجل مديح الناس. اقبل خفي عملي واجعله بركة. آمين.\",\"fq\":205}]},\"3-21\":{\"th\":\"إكرام الوالدين\",\"m\":[{\"t\":\"البنون ميراث من الرب\",\"ref\":\"المزمور ١٢٦ (١٢٧) — الغروب\",\"v\":\"البنون ميراث من الرب أجرة ثمرة البطن. كالسهام بيد القوي كذلك أبناء المتيقظين.\",\"r\":\"ينظر المزمور إلى الأبناء كعطية من الله وميراث. من يقبل هذه النظرة يكرّم والديه ويكرّم أبناءه. الإكرام رباط يمتد في الاتجاهين. اتصل اليوم بأحد والديك أو من ربّاك، وقل له كلمة شكر صادقة.\",\"p\":\"يا رب، أشكرك على نعمة الأسرة التي أعطيتني. باركها واحفظها، وعلّمني أن أكرم والدي كما تريد، وأن أرى في الأبناء ميراثًا منك. آمين.\"},{\"t\":\"تنهض بنوها ويطوبونها\",\"ref\":\"الأمثال ٣١: ٢٨\",\"bk\":\"الأمثال\",\"v\":\"يقوم أولادها ويطوبونها. زوجها أيضا فيمدحها:\",\"r\":\"«تقوم بنوها ويطوبونها، زوجها أيضًا فيمدحها». في اليوم الذي نكرّم فيه الأمهات أتأمل في ثمرة التعب الصامت: سنوات سهر وصلاة وعطاء. وأفكّر: كم مرة قلت لأمي «شكرًا» دون مناسبة؟ المديح الصادق هو أجمل هدية.\",\"p\":\"يا رب، أشكرك على كل أم ومن قامت مقامها. بارك تعبهن وعوّضهن، وامنحنا أن نكرمهن بالمحبة والشكر والصلاة. آمين.\"},{\"t\":\"الطاعة بالطاعة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ميّوس: «الطاعة تكون من أجل الطاعة، فالإنسان إذا أطاع الله فإن الله يطيعه». ليس هذا إذلالًا، بل ثقة بالله الذي يستجيب لمن يسمع له. أطع اليوم بفرح في أمر صغير يطلبه منك والداك أو من هو مسؤول عنك.\",\"p\":\"يا رب، علّمني الطاعة التي تكرّم، والسمع الذي يبني. بارك بيوتنا بوصيتك الأولى. آمين.\",\"fq\":284}]},\"3-22\":{\"th\":\"حنان الله\",\"m\":[{\"t\":\"يا أم الرحمة والخلاص\",\"ref\":\"قطعة الخدمة الثانية (٣) — نصف الليل — الخدمة الثانية\",\"v\":\"السموات تطوبك أيتها الممتلئة نعمة. العروس التي بلا زواج. ونحن أيضا نمجد ميلادك غير المدرك. يا والدة الإله يا أم الرحمة والخلاص؛ تشفعي من أجل خلاص نفوسنا.\",\"r\":\"نرى حنان الله في صورة الأم التي تحتضن، وتذكّرنا الكنيسة بالعذراء أم الرحمة. فكل عطف تعرفه في الأسرة ظل ضعيف لحنان أعظم. تأمل اليوم في أمٍّ أو امرأةٍ حملتك بحنانها، واشكر الله من أجلها.\",\"p\":\"يا رب، أشكرك لأنك تحنو علينا كما تحنو الأم على أبنائها. بشفاعة والدة الإله، ارحمني واحمني تحت ظلال حنانك. آمين.\"},{\"t\":\"كإنسان تعزيه أمه\",\"ref\":\"إشعياء ٦٦: ١٣\",\"bk\":\"إشعياء\",\"v\":\"كإنسان تعزيه أمه هكذا أعزيكم أنا، وفي أورشليم تعزون.\",\"r\":\"«كإنسان تعزيه أمه هكذا أنا أعزيكم». يستخدم الله صورة حنان الأم ليصف عنايته. ليس في الله ضعف، لكنه يعرف كيف يضمّ ويمسح الدموع. وعندما أتألم لا أحتاج إلى خطب طويلة، بل إلى حضن، والله يقدّمه لي.\",\"p\":\"يا رب، أنت المعزي الحنون. عزّ قلبي في ضيقي، وامسح دموعي، وعلّمني أن أعزي غيري بالحنان الذي تلقيته منك. آمين.\"},{\"t\":\"بشريتي وإلهيتك\",\"ref\":\"\",\"v\":\"\",\"r\":\"كان الأب أبو للوس يردد دائمًا: «لقد خطئت كإنسان، ولكن أنت كإله ارحمني». هذه الصلاة تلخص حنان الله: خطيتي بحجم بشريتي، ورحمته بحجم ألوهيته. رددها اليوم مراتٍ كلما شعرت بثقل.\",\"p\":\"لقد خطئت كإنسان، ولكن أنت كإله ارحمني. أعطني ثقة في حنانك الذي لا ينفد. آمين.\",\"fq\":76}]},\"3-23\":{\"th\":\"المحبة في البيت\",\"m\":[{\"t\":\"امرأتك مثل كرمة مخصبة\",\"ref\":\"المزمور ١٢٧ (١٢٨) — الغروب\",\"v\":\"امرأتك تصير مثل كرمة مخصبة في جوانب بيتك. بنوك مثل غروس الزيتون الجدد حول مائدتك. هكذا يبارك الإنسان المتقي الرب.\",\"r\":\"يرسم المرنم صورة بيت مبارك: كرمة مخصبة وغروس زيتون حول المائدة. الحب في البيت يظهر على مائدة تجمع. اجعل وجبة اليوم أو الليلة وقتًا بلا شاشات، تجلس فيه مع أسرتك وتنصت إلى كل واحد.\",\"p\":\"يا رب، بارك بيتي واجعله مثل كرمة مخصبة وغروس زيتون حول مائدتك. أعطنا محبة تغفر وتبني وتجمع. آمين.\"},{\"t\":\"فوق كل هذا المحبة\",\"ref\":\"كولوسي ٣: ١٤\",\"bk\":\"كولوسي\",\"v\":\"وعلى جميع هذه البسوا المحبة التي هي رباط الكمال.\",\"r\":\"«وعلى جميع هذه البسوا المحبة التي هي رباط الكمال». المحبة تلبس كما نلبس الثوب، وتربط كل الفضائل معًا. فبدونها يصير اللطف مجاملة، والتواضع ضعفًا. وفي البيت يتجلى هذا اللباس في أصغر التفاصيل: نبرة الصوت، ونظرة العين، وطريقة الاعتذار.\",\"p\":\"يا رب، ألبسني محبتك فوق كل شيء. اجعلني ليّنًا صبورًا غافرًا، وأجمع شمل أسرتي برباط الكمال والسلام. آمين.\"},{\"t\":\"أن أحب من يحبني كنفسي\",\"ref\":\"\",\"v\":\"\",\"r\":\"جواب الأب ماتوى صادق وبسيط: «حتى الآن أنا أحب من يحبني كنفسي». يعترف بحدود محبته، فيطلب الأكثر. في البيت، المحبة الحقيقية تتجاوز المقابل. اختر اليوم أن تحب أحد أهل بيتك دون أن تنتظر رد الفعل.\",\"p\":\"يا رب، وسّع محبتي لتشمل من لا يحبني بسهولة. علّمني أن أحب في بيتي كما أحببتني أنت. آمين.\",\"fq\":271}]},\"3-24\":{\"th\":\"الصلاة الربانية\",\"m\":[{\"t\":\"أصغِ إلى صوت طلبتي\",\"ref\":\"المزمور الخامس — باكر\",\"v\":\"أنصت يا رب لكلماتي. واسمع صراخي. أصغ إلى صوت طلبتي يا ملكي وإلهي، لأني إليك أصلى. يا رب بالغداة تسمع صوتي، بالغداة أقف أمامك وتراني.\",\"r\":\"قبل أن يقدّم المرنم طلبه يقول: أصغ إلى صوت طلبتي يا ملكي وإلهي، لأني إليك أصلي. الصلاة الربانية تبدأ بالمخاطبة قبل الطلب. افتتح صلاتك اليوم بهذا الوعي: أنت تخاطب ملكًا هو أب، وتقول له: أبانا.\",\"p\":\"أنصت يا رب لكلماتي واسمع صراخي. أصغِ إلى صوت طلبتي يا ملكي وإلهي، فبالغداة تسمع صوتي وبالغداة أقف أمامك. آمين.\"},{\"t\":\"أبانا الذي في السماوات\",\"ref\":\"متى ٦: ٩–١٠\",\"bk\":\"متى\",\"v\":\"«فصلوا أنتم هكذا: أبانا الذي في السماوات، ليتقدس اسمك. ليأت ملكوتك. لتكن مشيئتك كما في السماء كذلك على الأرض.\",\"r\":\"«فصلوا أنتم هكذا: أبانا الذي في السماوات ليتقدس اسمك، ليأتِ ملكوتك، لتكن مشيئتك». تبدأ الصلاة بـ«أبانا» لا بـ«أبي»، لأنني لا أصلي وحدي بل مع كل الكنيسة. وتبدأ بالله لا بحاجاتي، فأتعلم أن أضع مشيئته قبل رغباتي.\",\"p\":\"أبانا الذي في السماوات، ليتقدس اسمك. ليأتِ ملكوتك. لتكن مشيئتك. علّمني أن أضع إرادتك فوق رغباتي، وأن أصلي بقلب ابن. آمين.\"},{\"t\":\"الصلاة ليلًا ونهارًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يحكي الأب إيسيذورس أنه في صغره لم يكن له مقياس للصلاة، لأن الصلاة كانت له في الليل والنهار. هكذا تنمو الصلاة الربانية فينا: من كلمات نحفظها إلى حياة نعيشها. رددها اليوم ببطء، كلمة كلمة.\",\"p\":\"يا أبانا الذي في السماوات، علّمني أن أصلي ليلًا ونهارًا. ليكن اسمك مقدسًا في فمي وقلبي. آمين.\",\"fq\":169}]},\"3-25\":{\"th\":\"الدعوة والاختيار\",\"m\":[{\"t\":\"اهدني إلى طريقك\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"اهدني يا رب إلى طريقك فأسلك في حقك. ليفرح قلبي عند خوفه من اسمك. أعترف لك أيها الرب إلهي من كل قلبي.\",\"r\":\"الدعوة تبدأ بسؤال: ما طريقك يا رب؟ يصلي المرنم: اهدني إلى طريقك فأسلك في حقك. ثم يعترف بقلبه كله. من لا يعرف دعوته لا ييأس، فالمهم أن يطلب الاهتداء بقلب صادق. اسأل الله اليوم عن خطوة واحدة.\",\"p\":\"اهدني يا رب إلى طريقك فأسلك في حقك، وليفرح قلبي عند خوفه من اسمك. أعترف لك من كل قلبي، فأرشدني. آمين.\"},{\"t\":\"أنا اخترتكم\",\"ref\":\"يوحنا ١٥: ١٦\",\"bk\":\"يوحنا\",\"v\":\"ليس أنتم اخترتموني بل أنا اخترتكم، وأقمتكم لتذهبوا وتأتوا بثمر، ويدوم ثمركم، لكي يعطيكم الآب كل ما طلبتم باسمي.\",\"r\":\"«لستم أنتم اخترتموني بل أنا اخترتكم وأقمتكم لتذهبوا وتأتوا بثمر». يا لهذه النعمة: لست مضطرًا أن أبحث عن قيمتي لأنني مختار. وقد اخترني ليس لأنني مستحق بل لأنه أحبني. والثمر هو أن أحيا في محبته وأخدم.\",\"p\":\"يا رب يسوع، أشكرك لأنك اخترتني. اجعلني أثمر ثمرًا يدوم، ودعني أحب إخوتي كما أحببتني، وأخدمك بقلب شاكر. آمين.\"},{\"t\":\"اسأل أباك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يلاحظ القديس أنطونيوس رهبانًا سقطوا بعد أتعاب كثيرة لأنهم اتكلوا على أعمالهم واحتقروا وصية: «اسأل أباك فيقول لك». من يطلب الدعوة يحتاج إلى مرشد. إن كنت متحيرًا في اختيارك، فاسأل أب اعترافك أو معلمًا حكيمًا.\",\"p\":\"يا رب، أعطني قلبًا يطلب المشورة، ولا يتكل على فهمه. ضع في طريقي أبًا روحيًا يقودني إلى ما تدعوني إليه. آمين.\",\"fq\":21}]},\"3-26\":{\"th\":\"السلام الداخلي\",\"m\":[{\"t\":\"بالسلامة أضطجع وأنام\",\"ref\":\"المزمور الرابع — باكر\",\"v\":\"كثيرون يقولون: من يرينا الخيرات؟ قد أضاء علينا نور وجهك يا رب. أعطيت سرورا لقلبي أوفر من الذين كثرت حنطتهم وخمرهم وزيتهم. فبالسلامة أضطجع أيضا وأنام، لأنك أنت وحدك يا رب أسكنتني على الرجاء هلليلويا.\",\"r\":\"السلام الداخلي عند المرنم ليس نتيجة غياب الأسئلة، بل نور وجه الرب الذي يعطي سرورًا أوفر من الحنطة والخمر. وهو ينام مطمئنًا لأن الله أسكنه على الرجاء. الليلة اترك هواجسك لله قبل أن تنام.\",\"p\":\"قد أضاء علينا نور وجهك يا رب، وأعطيت سرورًا لقلبي. بالسلامة أضطجع وأنام لأنك أنت وحدك أسكنتني على الرجاء. آمين.\"},{\"t\":\"ليملك في قلوبكم سلام الله\",\"ref\":\"كولوسي ٣: ١٥\",\"bk\":\"كولوسي\",\"v\":\"وليملك في قلوبكم سلام الله الذي إليه دعيتم في جسد واحد، وكونوا شاكرين.\",\"r\":\"«وليملك في قلوبكم سلام الله الذي إليه دُعيتم في جسد واحد وكونوا شاكرين». كلمة «يملك» تعني أنه الحكم في قراراتي. فإن فقدت السلام في أمر فهذا مؤشر لأعيد النظر. وهو ليس لي وحدي بل للجسد الواحد، فلا سلام مع خصام الإخوة.\",\"p\":\"يا رب، املك على قلبي بسلامك. اجعله حكمًا في قراراتي، ووحّدنا في جسدك الواحد، وعلّمني أن أكون شاكرًا في كل شيء. آمين.\"},{\"t\":\"محبّ السكينة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب نيلوس إن الذي يحب السكينة لا يمكن لسهام العدو أن تجرحه، أما من يتدخل في كل شيء فيحتمل جراحات مستمرة. السلام الداخلي يحتاج حدودًا. ما الأمر الذي ليس من شأنك وتتوقف عن التدخل فيه اليوم؟\",\"p\":\"يا رب، علّمني أن أحب السكينة، وأترك ما ليس لي. احفظ قلبي هادئًا في كل ما يحدث حولي. آمين.\",\"fq\":296}]},\"3-27\":{\"th\":\"الشباب والنقاء\",\"m\":[{\"t\":\"الطاهر اليدين النقي القلب\",\"ref\":\"المزمور ٢٣ (٢٤) — الثالثة\",\"v\":\"من يصعد إلى جبل الرب، أو من يقوم في موضع قدسه \\\"؟ الطاهر اليدين: النقي القلب. الذي لم يحمل نفسه إلى الباطل ولم يحلف بالغش. هذا ينال بركة من الرب، ورحمة من الله مخلصه. هذا هو جيل الذين يطلبون الرب ويبتغون وجه إله يعقوب.\",\"r\":\"السؤال القديم لا يزال حيًا: من يصعد إلى جبل الرب؟ والجواب عن الطهارة واضح: الطاهر اليدين، النقي القلب، الذي لم يحمل نفسه إلى الباطل. ليست الطهارة مجرد امتناع، بل اتجاه نحو الله. ما الذي يحتاج قلبك إلى التنقية منه اليوم؟\",\"p\":\"يا رب، أريد أن أصعد إلى جبلك. اجعلني طاهر اليدين نقي القلب، وأعطني بركتك ورحمتك يا إلهي ومخلصي. آمين.\"},{\"t\":\"لم يتنجس بطعام الملك\",\"ref\":\"دانيال ١: ٨\",\"bk\":\"دانيال\",\"v\":\"أما دانيآل فجعل في قلبه أنه لا يتنجس بأطايب الملك ولا بخمر مشروبه، فطلب من رئيس الخصيان أن لا يتنجس.\",\"r\":\"«وأما دانيال فجعل في قلبه أنه لا يتنجس بأطايب الملك». كان بعيدًا عن أهله في بلد غريب، ومع ذلك قرر أن يحفظ نفسه. والقرار «في القلب» أولًا. وكانت بداية رحلة طويلة من الأمانة. وكل أمانة كبيرة تبدأ بقرار صغير سري.\",\"p\":\"يا رب، أعطني قرارًا في قلبي أن أحفظ نفسي لك. ثبّتني في الغربة والضغط، وامنحني حكمة ومحبة وأمانة كدانيال. آمين.\"},{\"t\":\"آنية للاستعمال الشريف\",\"ref\":\"\",\"v\":\"\",\"r\":\"يذكّر الأب بيمن في جوابه لأخ بأنه في البيت الكبير آنية من ذهب وفضة وأخرى من خشب وخزف، وبعضها لاستعمال شريف. الشاب الذي ينقي نفسه يصير إناءً شريفًا للرب. ما العادة التي تحتاج أن تنظفها اليوم؟\",\"p\":\"يا رب، طهّرني لأكون إناءً شريفًا في بيتك. انزع عني ما يدنس، وتمم فيّ عمل نعمتك. آمين.\",\"fq\":385}]},\"3-28\":{\"th\":\"سر الاعتراف\",\"m\":[{\"t\":\"من يثبت لأن من عندك المغفرة\",\"ref\":\"المزمور ١٢٩ (١٣٠) — النوم\",\"v\":\"إن كنت للآثام راصدا يا رب. يا رب من يثبت لأن من عندك المغفرة. من أجل اسمك صبرت لك يا رب.\",\"r\":\"يقف المرنم أمام الله بحقيقة بسيطة: إن حسبت الآثام فمن يثبت؟ لكن عندك المغفرة. الاعتراف ليس محاكمة بل لقاء مع غفران سابق. ابدأ اليوم بتسمية خطية واحدة تثقلك، وحضّر نفسك للاعتراف بها أمام أب اعترافك.\",\"p\":\"إن كنت للآثام راصدًا يا رب فمن يثبت؟ لكن عندك المغفرة، ومن أجل اسمك صبرت لك. اغفر لي واقبل اعترافي. آمين.\"},{\"t\":\"من غفرتم خطاياه\",\"ref\":\"يوحنا ٢٠: ٢٢–٢٣\",\"bk\":\"يوحنا\",\"v\":\"ولما قال هذا نفخ وقال لهم: «اقبلوا الروح القدس. من غفرتم خطاياه تغفر له، ومن أمسكتم خطاياه أمسكت».\",\"r\":\"«اقبلوا الروح القدس. من غفرتم خطاياه تُغفر له ومن أمسكتم خطاياه أمسكت». في مساء القيامة أعطى المسيح تلاميذه هذا السلطان. وهذا أساس سر التوبة والاعتراف في الكنيسة. فالغفران ليس فكرة بل عطية تُمنح عبر الكنيسة.\",\"p\":\"يا رب يسوع، أشكرك على سلطان الغفران الذي أعطيته لكنيستك. اغسلني بدمك، وأعطني سلامك، وثبّتني في توبة مستمرة. آمين.\"},{\"t\":\"العدو يحب الأفكار المخفية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا الكولوفي: إن العدو لا يفرح كثيرًا إلا من الذين لا يظهرون أفكارهم. فالاعتراف يفضح خطة العدو ويجعلنا أحرارًا. ما الفكرة التي تخفيها ولا تقولها لأحد؟ قلها اليوم لله، وفي الاعتراف المقبل لأب اعترافك.\",\"p\":\"يا رب، لا أريد أن أخفي شيئًا عنك. أظهر لك أفكاري، وحرّرني من سلطان العدو بسر الاعتراف. آمين.\",\"fq\":386}]},\"3-29\":{\"th\":\"الكنيسة الواحدة\",\"m\":[{\"t\":\"القائمون في بيت الرب\",\"ref\":\"المزمور ١٣٣ — النوم\",\"v\":\"ها باركوا الرب يا عبيد الرب، القائمين في بيت الرب في ديار إلهنا. في الليالي ارفعوا أيديكم إلى القدس وباركوا الرب. يبارككم الرب من صهيون الذي خلق السماء والأرض هلليلويا.\",\"r\":\"تتحد الكنيسة في الصلاة، حتى في الليل يرفع المؤمنون أيديهم إلى القدس. نبارك الرب معًا لا منفردين. فالصلاة الجماعية تحمل من لا يقدر على الصلاة. صلِّ اليوم من أجل كنيستك ومن أجل أسماء تعرفها من أعضائها.\",\"p\":\"يا رب، يبارك عبيدك القائمون في بيتك ويرفعون أيديهم إلى القدس. بارك كنيستك، وبارك كل واحد فيها، يا خالق السماء والأرض. آمين.\"},{\"t\":\"يحمل بعضكم أثقال بعض\",\"ref\":\"غلاطية ٦: ٢\",\"bk\":\"غلاطية\",\"v\":\"احملوا بعضكم أثقال بعض، وهكذا تمموا ناموس المسيح.\",\"r\":\"«احملوا بعضكم أثقال بعض وهكذا تمموا ناموس المسيح». لا أحد يقدر أن يحمل ثقله وحده. والكنيسة ليست مكانًا للمتفرجين بل لحاملي الأثقال. وأن أحمل أثقال غيري يعني أن أشاركه بكلمة ووقت وصلاة وربما بمال. وهكذا أتمم محبة المسيح.\",\"p\":\"يا رب، علّمني أن أحمل أثقال إخوتي وأن أسمح لهم بأن يحملوا أثقالي. اجعل كنيستنا جماعة محبة ومشاركة تتمم ناموسك. آمين.\"},{\"t\":\"التصق بمن يسلك حسنًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"وصية الأب بيمن: «لا تعتدّ بنفسك إنما التصق بمن يسلك حسنًا». الكنيسة الواحدة تنمو بالصحبة الصالحة. فمن هم الذين يسلكون حسنًا في كنيستك؟ ابحث عن فرصة تقترب فيها منهم وتتعلم.\",\"p\":\"يا رب، اجعلني أتعلم من الصالحين في كنيستك، ولا أتكل على فهمي. ضعني في صحبة تقودني إليك. آمين.\",\"fq\":367}]},\"3-30\":{\"th\":\"السلام مع الله\",\"m\":[{\"t\":\"اسألوا السلام\",\"ref\":\"المزمور ١٢١ (١٢٢) — الغروب\",\"v\":\"اسألوا السلام لأورشليم والخصب لمحبيك. ليكن السلام في حصنك والخصب في أبراجك الرصينة. من أجل اخوتي وأقربائي تكلمت من أجلك بالسلام، ومن أجل بيت الرب إلهنا التمست لك الخيرات هلليلويا.\",\"r\":\"يدعو المرنم إلى السؤال من أجل سلام المدينة، لأجل الإخوة والأقرباء وبيت الرب. السلام مع الله يظهر في أن نطلب السلام للآخرين. من هو الشخص أو المكان الذي يحتاج إلى سلام اليوم؟ صلِّ له بالاسم.\",\"p\":\"اسألك يا رب السلام لأورشليم وللكنيسة ولبيوتنا. ليكن السلام في حصنك والخصب في أبراجك، من أجل إخوتي وأقربائي. آمين.\"},{\"t\":\"السلام لكم\",\"ref\":\"يوحنا ٢٠: ١٩\",\"bk\":\"يوحنا\",\"v\":\"ولما كانت عشية ذلك اليوم، وهو أول الأسبوع، وكانت الأبواب مغلقة حيث كان التلاميذ مجتمعين لسبب الخوف من اليهود، جاء يسوع ووقف في الوسط، وقال لهم: «سلام لكم!»\",\"r\":\"«ولما كانت عشية ذلك اليوم والأبواب مغلقة حيث كان التلاميذ مجتمعين لسبب الخوف جاء يسوع ووقف في الوسط وقال لهم سلام لكم». المسيح لا ينتظر أن يفتح التلاميذ الأبواب، بل يدخل إليهم وهي مغلقة. وأنا أيضًا قد أغلق قلبي خوفًا، لكنه يدخل ويقف في وسطي.\",\"p\":\"يا رب يسوع القائم، ادخل إلى قلبي المغلق خوفًا، وقف في وسطي وقل لي: سلام لك. حوّل خوفي فرحًا، وارسلني بسلامك. آمين.\"},{\"t\":\"هذا هو السلام\",\"ref\":\"\",\"v\":\"\",\"r\":\"يرسم الأب موسى الحبشي سلامًا عمليًا: لا تثلب أحدًا، لا توافق المتكلم بالسوء، لا تحقد على أحد، لا يكن لك عداوة. ثم يقول: هذا هو السلام. السلام مع الله يبدأ بأمور صغيرة نتجنبها. أيّها تحتاج إليه اليوم؟\",\"p\":\"يا رب، اجعلني صانع سلام لا أثلب ولا أحقد. وأعطني قلبًا يعيش بسلامك في كل علاقاتي. آمين.\",\"fq\":267}]},\"3-31\":{\"th\":\"أنسى ما هو وراء\",\"m\":[{\"t\":\"هذا هو اليوم الذي صنعه الرب\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"هذا هو اليوم الذي صنعه الرب. فلنبتهج ونفرح فيه.\",\"r\":\"ننهي مارس بفرح اللحظة: «هذا هو اليوم الذي صنعه الرب، فلنبتهج ونفرح فيه». ننسى ما وراء ونمتد إلى ما أمام، وتبقى عطية اليوم أمامنا. ابدأ هذا اليوم بتهليل قصير حتى لو كانت الأخبار ثقيلة.\",\"p\":\"هذا هو اليوم الذي صنعته يا رب، فلنبتهج ونفرح فيه. أنسني ما وراء وامتد بي إلى ما قدام. آمين.\"},{\"t\":\"أسعى نحو الغرض\",\"ref\":\"فيلبي ٣: ١٣–١٤\",\"bk\":\"فيلبي\",\"v\":\"أيها الإخوة، أنا لست أحسب نفسي أني قد أدركت. ولكني أفعل شيئا واحدا: إذ أنا أنسى ما هو وراء وأمتد إلى ما هو قدام، أسعى نحو الغرض لأجل جعالة دعوة الله العليا في المسيح يسوع.\",\"r\":\"«ولكني أفعل شيئًا واحدًا: إذ أنا أنسى ما هو وراء وأمتد إلى ما هو قدام أسعى نحو الغرض». في نهاية شهر قد أجمع خسائر وإخفاقات، لكن الرسول يعلّمني ألا أبقى في الماضي. أتعلم ثم أتحرك. والغرض هو المسيح نفسه. فأمدّ يدي إلى الغد بثقة.\",\"p\":\"يا رب، علّمني أن أنسى ما هو وراء وأمتد إلى ما هو قدام. حرّرني من ندم الماضي، وقدني نحو غايتي فيك، وأعطني مثابرة. آمين.\"},{\"t\":\"ابدأ من جديد كل صباح\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب يوحنا الكولوفي: عندما تستيقظ كل صباح ابدأ من جديد في كل فضيلة ووصية، بصبر عظيم وخوف وطول أناة ومحبة لله. أنسى ما وراء يعني أن كل صباح بدء جديد. ابدأ اليوم كأنه أول يوم.\",\"p\":\"يا رب، أبدأ من جديد معك. أعطني صبرًا وخوفًا ومحبة لك، وساعدني أن أترك ما مضى. آمين.\",\"fq\":163}]},\"4-1\":{\"th\":\"الصدق في القول والعمل\",\"m\":[{\"t\":\"شفاه غاشة\",\"ref\":\"المزمور الحادي عشر — باكر\",\"v\":\"تكلم كل واحد مع قريبه بالأباطيل. شفاه غاشة في قلوبهم وبقلوبهم تخاطبوا.\",\"r\":\"يشكو المرنم من زمن قلّت فيه الأمانة وتكلم الناس بالأباطيل بشفاه غاشة وقلوب منقسمة. الصدق أن يتفق ما في القلب مع ما على اللسان. قبل أن تتكلم اليوم في موضوع حساس، اسأل: هل ما سأقوله هو ما أعتقده فعلًا؟\",\"p\":\"خلصني يا رب من الغش، وقوّم لساني ليوافق قلبي. أعطني أن أتكلم مع قريبي بالحق، وأن أسير أمامك بنزاهة. آمين.\"},{\"t\":\"تكلموا بالصدق\",\"ref\":\"أفسس ٤: ٢٥\",\"bk\":\"أفسس\",\"v\":\"لذلك اطرحوا عنكم الكذب، وتكلموا بالصدق كل واحد مع قريبه، لأننا بعضنا أعضاء البعض.\",\"r\":\"«لذلك اطرحوا عنكم الكذب وتكلموا بالصدق كل واحد مع قريبه لأننا بعضنا أعضاء البعض». الكذب يمزق الجسد الواحد كما يمزق العضو المصاب بقية الأعضاء. والصدق ليس قسوة بل محبة تحترم الآخر. وأحتاج اليوم أن أراجع: هل أقول الحق بمحبة، أم أجامل على حساب الحقيقة؟\",\"p\":\"يا رب، أنت الحق. طهّر لساني من كل كذب ومبالغة، وعلّمني أن أتكلم بالصدق في المحبة، فأبني الثقة بيني وبين إخوتي. آمين.\"},{\"t\":\"عين ماء لا تنظف نفسها\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن من يعلّم ولا يعمل بعين ماء تسقي وتروي وتغسل كل شيء لكنها لا تقدر أن تنظف نفسها. الصدق ليس في الكلام الجميل، بل في أن أعيش ما أقوله. اختر اليوم كلمة نصحت بها غيرك وطبّقها أنت أولًا.\",\"p\":\"يا رب، اجعل أقوالي وأعمالي واحدة. لا تدعني أعلّم بما لا أعيشه، وأعطني نعمة الصدق الكامل أمامك وأمام الناس. آمين.\",\"fq\":343}]},\"4-2\":{\"th\":\"الإلحاح في الصلاة\",\"m\":[{\"t\":\"إلى متى يا رب؟\",\"ref\":\"المزمور ١٢ (١٣) — باكر\",\"v\":\"إلى متى يا رب تنساني؟ إلى الانقضاء؟ حتى متى تصرف وجهك عنى؟\",\"r\":\"الإلحاح في الصلاة يبدأ أحيانًا بسؤال يخرج من التعب: إلى متى؟ والمرنم لا يخاف أن يسأل الله هكذا، وهذا هو صدق العلاقة. اسأل الله اليوم بصراحة عما تأخر، وخذ قراري ألا تصمت حتى تسمع جوابه، ولو بعد حين.\",\"p\":\"إلى متى يا رب تنساني؟ حتى متى تصرف وجهك عني؟ أنا لا أمل من الصلاة، فانظر إليّ واستجب في وقتك الحسن. آمين.\"},{\"t\":\"صلاة من أجله\",\"ref\":\"أعمال الرسل ١٢: ٥\",\"bk\":\"أعمال الرسل\",\"v\":\"فكان بطرس محروسا في السجن، وأما الكنيسة فكانت تصير منها صلاة بلجاجة إلى الله من أجله.\",\"r\":\"«فكان بطرس محروسًا في السجن، وأما الكنيسة فكانت تصلي إلى الله بلجاجة من أجله». سجن وحراس وسلاسل، وفي مقابلها كنيسة تصلي. وانتهى الأمر بتحرير بطرس. والصلاة الجماعية ليست رمزًا بل قوة. وكل واحد منا يمكنه أن يحمل إنسانًا في سجنه بالصلاة.\",\"p\":\"يا رب، أشكرك على قوة الصلاة الجماعية. حرّر المسجونين بالمرض والخطية واليأس، وعلّمنا أن نصلي بإيمان ولجاجة معًا. آمين.\"},{\"t\":\"أسرع واطلب\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال القديس أنطونيوس لأخ طلب منه الصلاة: «لا أنا أرحمك ولا الله، إذا كنت أنت نفسك لا تسرع لتطلب هذا منه». الإلحاح مسؤوليتنا، والله ينتظر أن نطلب. ما الطلب الذي تؤجل رفعه إلى الله؟ ارفعه اليوم.\",\"p\":\"يا رب، علّمني أن أطلب بنفسي وألحّ ولا أتكل على صلاة الآخرين وحدها. افتح لي بابك في كل مرة أقرع فيها. آمين.\",\"fq\":11}]},\"4-3\":{\"th\":\"الإيمان والشك\",\"m\":[{\"t\":\"على رحمتك توكلت\",\"ref\":\"المزمور ١٢ (١٣) — باكر\",\"v\":\"أما أنا فعلى رحمتك توكلت. يبتهج قلبي بخلاصك.\",\"r\":\"لا يخلو الإيمان من لحظات تساؤل، لكن المرنم يقفز فوق الشك بإعلان بسيط: أما أنا فعلى رحمتك توكلت. التوكل قرار يواجه الشك ولا ينكره. إذا مرّ بك سؤال بلا جواب اليوم، لا تهرب منه، ضعه في حضن رحمة الله.\",\"p\":\"أما أنا فعلى رحمتك توكلت، ويبتهج قلبي بخلاصك. يا رب، حين يأتي الشك ثبّتني، وأرني وجهك فيما لا أفهمه. آمين.\"},{\"t\":\"طوبى للذين آمنوا ولم يروا\",\"ref\":\"يوحنا ٢٠: ٢٧–٢٩\",\"bk\":\"يوحنا\",\"v\":\"ثم قال لتوما: «هات إصبعك إلى هنا وأبصر يدي، وهات يدك وضعها في جنبي، ولا تكن غير مؤمن بل مؤمنا». أجاب توما وقال له: «ربي وإلهي!». قال له يسوع: «لأنك رأيتني يا توما آمنت! طوبى للذين آمنوا ولم يروا».\",\"r\":\"«هات إصبعك إلى هنا وأبصر يديّ، وهات يدك وضعها في جنبي، ولا تكن غير مؤمن بل مؤمنًا». لم يوبخ المسيح توما على شكه، بل قدّم له ما يحتاجه. وهذا ما يفعله معي: يقابل أسئلتي بحنان. وانتهى شك توما باعتراف عظيم: «ربي وإلهي».\",\"p\":\"يا رب، لا تؤنبني على أسئلتي بل قدني بها إليك. زد إيماني، وأعطني أن أقول من قلبي: ربي وإلهي، وأن أثق بك وإن لم أرَ. آمين.\"},{\"t\":\"نبكي أمام الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"نصح الأب بيمن من أزعجته الاضطرابات بأن نبكي أمام الله في كل أتعابنا إلى أن يعلن لنا رحمته. لا يطلب منا أن نفهم كل شيء بل أن نبقى أمامه. قل له اليوم كل ما يربكك دون ترتيب، وانتظر.\",\"p\":\"يا رب، أبكي أمامك أتعابي واضطراباتي، وأنتظر رحمتك. ثبّت إيماني فلا يتزعزع في ضعفي وأسئلتي. آمين.\",\"fq\":400}]},\"4-4\":{\"th\":\"إلقاء الهم على الله\",\"m\":[{\"t\":\"سترني بستر مظلته\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"لأنه أخفاني في خيمته. في يوم شدتي؛ سترني بستر مظلته. وعلى صخرة رفعني.\",\"r\":\"في يوم الشدة يجد المرنم مكانًا: خيمة الله وستر مظلته وصخرة ترفعه. إلقاء الهم على الله هو أن أترك الحمل عند من هو أقوى مني. ما الهمّ الذي تحمله اليوم وحدك؟ سمِّه بصوت مسموع، ثم قل: هذا لك يا رب.\",\"p\":\"أخفني يا رب في خيمتك في يوم شدتي، واسترني بستر مظلتك، وارفعني على صخرة. ألقي عليك همومي لأنك تعتني بي. آمين.\"},{\"t\":\"ألقوا كل همكم عليه\",\"ref\":\"بطرس الأولى ٥: ٧\",\"bk\":\"بطرس الأولى\",\"v\":\"ملقين كل همكم عليه، لأنه هو يعتني بكم.\",\"r\":\"«ملقين كل همكم عليه لأنه هو يعتني بكم». كلمة «كل» تعني الصغير والكبير. لا أحتاج أن أنتقي مما أعرضه عليه. وهو يعتني بي كما يعتني الأب بطفله. وإلقاء الهم فعل إرادي: أن أضع الحمل عند قدميه وأرفع يدي فارغة.\",\"p\":\"يا رب، ألقي عليك كل همّي لأنك تعتني بي. أعطني أن أتوكل عليك وأترك ما لا أستطيع، فأعيش بسلام وثقة في رعايتك. آمين.\"},{\"t\":\"على قدر مشيئة الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب نيلوس ألا نرغب أن تأتي الأمور كما نتمنى بل كما يشاء الله، فنكون بلا اضطراب ولا همّ ومسرورين في صلاتنا. هذه خلاصة إلقاء الهم: قبول المشيئة. ما الأمر الذي تريده بطريقتك وتتعب بسببه اليوم؟\",\"p\":\"يا رب، لتكن مشيئتك لا مشيئتي. علّمني أن أرضى بما ترتبه، وأن أصلي بلا اضطراب أو همّ. آمين.\",\"fq\":294}]},\"4-5\":{\"th\":\"التحرر من الخوف\",\"m\":[{\"t\":\"أنا هو، لا تخافوا\",\"ref\":\"إنجيل الستار\",\"v\":\"نظروا يسوع ماشيا على البحر، مقتربا إلى السفينة فخافوا. فقال لهم: أنا هو، لا تخافوا. فقبلوا أن يحملوه معهم في السفينة، وللوقت جاءت السفينة إلى شاطئ الأرض التي كانوا ذاهبين إليها.\",\"r\":\"كان البحر هائجًا والظلام قد حل ولم يكن يسوع معهم، فلما اقترب خافوا أيضًا. ثم قال لهم: أنا هو، لا تخافوا. حين قبلوه في السفينة وصلوا في الحال. الخوف يتحرر حين نقبل حضور المسيح في قاربنا. ادعه اليوم إلى قارب يومك.\",\"p\":\"يا يسوع، أنت تقترب وسط الأمواج وتقول لي: أنا هو لا تخافوا. أقبلك في سفينة حياتي، فتوصلني بسلام إلى حيث ترسلني. آمين.\"},{\"t\":\"لا تخف لأني معك\",\"ref\":\"إشعياء ٤١: ١٠\",\"bk\":\"إشعياء\",\"v\":\"لا تخف لأني معك. لا تتلفت لأني إلهك. قد أيدتك وأعنتك وعضدتك بيمين بري.\",\"r\":\"«لا تخف لأني معك، لا تتلفت لأني إلهك. قد أيدتك وأعنتك وعضدتك بيمين برّي». خمسة أفعال إلهية تواجه خوفي: معية، إلوهية، تأييد، معونة، عضد. ولا أحتاج أن أنظر حولي بقلق فهو كل ما أحتاجه. والخوف يفقد قوته حين أضع عيني على الله.\",\"p\":\"يا رب، أنت معي فلا أخاف. شددني وأعني وعضدني بيمين بِرّك، وأبعد عني كل تلفت وقلق، وثبّت نظري عليك. آمين.\"},{\"t\":\"لا تخف من الأموات\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب كيرس لأخ تزعجه ذكريات الأفكار القديمة: لا تكن من الأموات خائفًا، بل تحاش الأحياء وأطل صلاتك. أي لا تدع الماضي يرعبك، بل اجعل الصلاة ملجأ. ما الذي يخيفك من الماضي؟ ضعه في صلاتك اليوم.\",\"p\":\"يا رب، حرّرني من خوف الماضي ومن أفكاره القديمة. أطل صلاتي وأقوّ إيماني، وكن أنت سلامي. آمين.\",\"fq\":225}]},\"4-6\":{\"th\":\"الثبات في المسيح\",\"m\":[{\"t\":\"اثبتوا فيّ وأنا فيكم\",\"ref\":\"إنجيل الثالثة\",\"v\":\"أنا هو الكرمة الحقيقية وأبى الكرام. كل غصن في لا يأتي بثمر يقطعه. وكل ما يأتي بثمر ينقيه ليأتي بثمر أكثر. وأنتم من قبل أنقياء من أجل الكلام الذي كلمتكم به. اثبتوا في وأنا أيضا فيكم.\",\"r\":\"يشبّه المسيح علاقتنا به بالكرمة والأغصان: غصن بلا كرمة لا يثمر، وغصن في الكرمة ينقّيه الآب ليأتي بثمر أكثر. الثبات ليس مجهودًا بل بقاء في المصدر. أبقِ قلبك اليوم متصلًا بالمسيح بصلاة قصيرة بين كل عمل وآخر.\",\"p\":\"يا رب يسوع، أنت الكرمة الحقيقية وأنا الغصن. ثبّتني فيك وثبّت كلامك فيّ، ونقِّني لأثمر ثمرًا أكثر. آمين.\"},{\"t\":\"سيروا فيه\",\"ref\":\"كولوسي ٢: ٦–٧\",\"bk\":\"كولوسي\",\"v\":\"فكما قبلتم المسيح يسوع الرب اسلكوا فيه، متأصلين ومبنيين فيه، وموطدين في الإيمان، كما علمتم، متفاضلين فيه بالشكر.\",\"r\":\"«فكما قبلتم المسيح يسوع الرب اسلكوا فيه، متأصلين ومبنيين فيه وموطدين في الإيمان». كما بدأت العلاقة بقبول المسيح، تستمر بالسلوك فيه. ثلاث صور: شجرة متأصلة، وبناء، وإيمان موطد. وكل صورة تذكرني أن الإيمان ينمو بالعمق والاستقرار.\",\"p\":\"يا رب، كما قبلتك أسلك فيك. أصّلني فيك وابنِني عليك ووطّدني في الإيمان، واملأني شكرًا يفيض على كل من حولي. آمين.\"},{\"t\":\"النار تحت المرجل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن الإنسان الثابت بالمرجل الذي تشتعل تحته النار، فلا تقدر الذبابة أن تدنو منه، أما إذا برد فتقترب منه الحشرات. الحرارة الروحية هي الحماية. ما الذي يحفظ حرارتك الروحية اليوم؟ لا تتركه.\",\"p\":\"يا رب، أشعل فيّ نار محبتك لتحميني من كل فتور. أبقني ثابتًا فيك وملتهبًا بالروح. آمين.\",\"fq\":391}]},\"4-7\":{\"th\":\"عيد البشارة\",\"m\":[{\"t\":\"اسمعي يا ابنتي وانظري\",\"ref\":\"المزمور ٤٤ (٤٥) — الثالثة\",\"v\":\"اسمعي يا ابنتي وانظري وأميلي أذنك، وانسي شعبك وبيت أبيك. فإن الملك قد اشتهى حسنك.\",\"r\":\"في عيد البشارة تسمع الكنيسة صدى هذا المزمور مع كلام الملاك للعذراء. «اسمعي وأميلي أذنك»: بداية الدعوة أن نصغي. قبلت مريم الرسالة بتواضع قائلة: هوذا أنا أمة الرب. ما رسالة الله إليك اليوم؟ أصغِ إليها بقلب مفتوح.\",\"p\":\"افتح يا رب أذني لأسمعك كما سمعت العذراء، وقلبي لأقبل ما تقوله لي. ليكن لي حسب قولك، وأنت تظلل على حياتي. آمين.\"},{\"t\":\"لا تخافي يا مريم\",\"ref\":\"لوقا ١: ٣٠–٣١\",\"bk\":\"لوقا\",\"v\":\"فقال لها الملاك: «لا تخافي يا مريم، لأنك قد وجدت نعمة عند الله. وها أنت ستحبلين وتلدين ابنا وتسمينه يسوع.\",\"r\":\"«لا تخافي يا مريم لأنك قد وجدت نعمة عند الله». أول ما يقوله الله لمن يدعوه هو «لا تخف». لأن الدعوة الكبرى تحمل خوفًا طبيعيًا. وما يطمئن ليس غياب الصعوبة بل «نعمة عند الله». وهكذا أتعلم أن أقابل دعوات الله بإيمان لا بقلق.\",\"p\":\"يا رب، علّمني ألا أخاف من دعوتك. كما وجدت مريم نعمة عندك، أنعم عليّ بقلب مؤمن مطيع، يسأل بصدق ويقبل بفرح. آمين.\"},{\"t\":\"الطاعة أمّ الفضائل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يهتف الأب روفو بالطاعة: يا خلاص جميع المؤمنين، يا أمّ جميع الفضائل، يا محقّقة الملكوت. وتعلمنا العذراء أن الطاعة لا تعني ضعفًا بل قبولًا حرًا لمشيئة الله. اجعل «ليكن لي» عبارة تقولها اليوم أمام أول أمر لا تفهمه.\",\"p\":\"يا رب، علّمني طاعة العذراء. اجعل «ليكن لي» تتردد في قلبي كل يوم، فتتم مشيئتك فيّ. آمين.\",\"fq\":482}]},\"4-8\":{\"th\":\"الطاعة الكاملة\",\"m\":[{\"t\":\"علّمني يا رب طريقك\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"علمني يا رب طريقك. واهدني في سبيل مستقيم من أجل أعدائي.\",\"r\":\"الطاعة الكاملة تبدأ بتعلّم الطريق: «علّمني يا رب طريقك واهدني في سبيل مستقيم». لا نطيع في الظلام بل بإرشاد. ومن يسأل بتواضع يُهدَ. اطلب اليوم من الله أن يريك الخطوة التالية في أمر لم تحسمه.\",\"p\":\"علّمني يا رب طريقك، واهدني في سبيل مستقيم. أعطني قلبًا يطيع وأذنًا تسمع، فأسير بسلام في مشيئتك. آمين.\"},{\"t\":\"الله العامل فيكم\",\"ref\":\"فيلبي ٢: ١٢–١٣\",\"bk\":\"فيلبي\",\"v\":\"إذا يا أحبائي، كما أطعتم كل حين، ليس كما في حضوري فقط، بل الآن بالأولى جدا في غيابي، تمموا خلاصكم بخوف ورعدة، لأن الله هو العامل فيكم أن تريدوا وأن تعملوا من أجل المسرة.\",\"r\":\"«تمموا خلاصكم بخوف ورعدة، لأن الله هو العامل فيكم أن تريدوا وأن تعملوا من أجل المسرة». الطاعة ليست نتيجة جهدي وحده، فالله يعمل في إرادتي وفعلي. وأنا مدعو أن أتعاون معه. وهذا يحميني من اليأس والكبرياء معًا.\",\"p\":\"يا رب، أنت العامل فيّ أن أريد وأن أعمل. قوِّ إرادتي وأعنّي على الطاعة، وتمم فيّ خلاصك بنعمتك وجهادي. آمين.\"},{\"t\":\"أطاع حتى الموت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيبريخيوس إن الطاعة جوهرة موروثة، ومن يمتلكها يحفظه المصلوب، لأن الرب الذي صُلب من أجلنا أطاع حتى الموت. الطاعة الحقيقية تشبه طاعة المسيح: محبة وليست خوفًا. اطع اليوم فيما لا تحب، متذكرًا طاعته.\",\"p\":\"أيها الرب المصلوب، علّمني الطاعة التي أطعتها لأبيك. ألبسني هذه الجوهرة، وثبّتني في مشيئتك. آمين.\",\"fq\":555}]},\"4-9\":{\"th\":\"رحمة الله الجديدة\",\"m\":[{\"t\":\"أسمعني رحمتك بالغداة\",\"ref\":\"المزمور المئة والثاني والأربعون — باكر\",\"v\":\"فلأسمع في الغدوات رحمتك، فإني عليك توكلت. عرفني يا رب الطريق التي أسلك فيها، لأني إليك رفعت نفسي.\",\"r\":\"يبدأ المرنم يومه بطلب رحمة الله في الصباح، كأن الرحمة تتجدد مع كل غداة. لا يعيش الله على رصيد الأمس فينا، بل يجدد رحمته. ابدأ يومك اليوم بكلمة: يا رب لا أستحق، لكنك رحوم. وقم بثقة جديدة.\",\"p\":\"أسمعني رحمتك بالغداة يا رب لأني عليك توكلت. عرّفني الطريق التي أسلك فيها، فإني إليك رفعت نفسي. آمين.\"},{\"t\":\"هي جديدة كل صباح\",\"ref\":\"مراثي إرميا ٣: ٢٢–٢٣\",\"bk\":\"مراثي إرميا\",\"v\":\"إنه من إحسانات الرب أننا لم نفن، لأن مراحمه لا تزول. هي جديدة في كل صباح. كثيرة أمانتك.\",\"r\":\"«إحسانات الرب إنها لا تفنى، لأن مراحمه لا تزول. هي جديدة في كل صباح، كثيرة أمانتك». كتبها إرميا وسط خراب أورشليم. وفي أحلك الأوقات وجد رجاءه في أمانة الله. وكل صباح يبدأ برحمة جديدة، فلا أبدأ بحمل أخطاء الأمس، بل بمراحم اليوم.\",\"p\":\"يا رب، أشكرك لأن مراحمك جديدة كل صباح. اغفر لي أخطاء الأمس، وامنحني بداية جديدة اليوم، وعلّمني أن أثق في أمانتك الكثيرة. آمين.\"},{\"t\":\"انتبه للمستقبل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّمنا الأب بيمن كيف نتعامل مع من أخطأ: لا نبكته فنثبّط عزيمته، بل نقول له: لا تحزن يا أخي، انتبه للمستقبل. هكذا يعاملنا الله برحمته الجديدة. فتعامل اليوم مع نفسك ومع غيرك بهذه اللغة.\",\"p\":\"يا رب، ارحمني برحمتك الجديدة كل صباح. وعلّمني أن أكون رحيمًا بمن أخطأ، وأن أشجعه على البدء من جديد. آمين.\",\"fq\":324}]},\"4-10\":{\"th\":\"الحياة الأبدية\",\"m\":[{\"t\":\"البهجة في يمينك\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"تملأني فرحا مع وجهك. البهجة في يمينك إلى الانقضاء.\",\"r\":\"الحياة الأبدية في كلمات المرنم ليست بعيدة: فرح مع وجه الله وبهجة في يمينه إلى الانقضاء. تبدأ الأبدية حين نعرف الله. اسأل نفسك اليوم: هل ما أطلبه من الحياة يوصلني إلى هذه البهجة أم يبعدني عنها؟\",\"p\":\"تملأني فرحًا مع وجهك يا رب، والبهجة في يمينك إلى الانقضاء. اجعل شوقي إلى حياتك الأبدية أقوى من كل رغبة. آمين.\"},{\"t\":\"هذه هي الحياة الأبدية\",\"ref\":\"يوحنا ١٧: ٣\",\"bk\":\"يوحنا\",\"v\":\"وهذه هي الحياة الأبدية: أن يعرفوك أنت الإله الحقيقي وحدك ويسوع المسيح الذي أرسلته.\",\"r\":\"«وهذه هي الحياة الأبدية: أن يعرفوك أنت الإله الحقيقي وحدك ويسوع المسيح الذي أرسلته». الحياة الأبدية تبدأ الآن بمعرفة الله، وليست مجرد حياة بعد الموت. والمعرفة هنا ليست معلومات بل علاقة حية. وكلما تعمقت علاقتي به عشت أبديتي الآن.\",\"p\":\"يا رب، أشتاق أن أعرفك أكثر. علّمني أن أعيش الحياة الأبدية الآن بالشركة معك، وافتح قلبي لتعرف الآب والابن بروحك القدوس. آمين.\"},{\"t\":\"اعمل ما يقودك إلى الخلاص\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس: «إذا كنت تشتاق إلى الخلاص، اعمل كل ما من شأنه أن يقودك إليه». الشوق وحده لا يكفي، بل الخطوة العملية. ماذا يمكن أن تفعله اليوم لتقترب من الله: صلاة أو اعتراف أو صدقة؟\",\"p\":\"يا رب، أنا أشتاق إلى خلاصك، فأعطني قوة أن أعمل ما يقودني إليك. آمين.\",\"fq\":202}]},\"4-11\":{\"th\":\"الوكالة الأمينة\",\"m\":[{\"t\":\"الذي يتراءف ويقرض\",\"ref\":\"المزمور ١١١ (١١٢) — التاسعة\",\"v\":\"صالح هو الرجل الذي يتراءف ويقرض ويدبر أقواله بالحق، لأنه لا يتزعزع إلى الدهر. ذكر الصديق يدوم إلى الأبد، ولا يخشى من خبر السوء.\",\"r\":\"يصف المرنم الصالح بأنه يتراءف ويقرض ويدبر أقواله بالحق، فلا يخشى خبر السوء. هذه هي الوكالة الأمينة: أن أعتبر ما عندي أمانة أتصرف فيها بحكمة ورحمة. أي أمانة تحتاج إلى تدبير أفضل في وقتك أو مالك اليوم؟\",\"p\":\"يا رب، علّمني أن أدبّر أقوالي وأموالي بالحق والرحمة. اجعلني وكيلًا أمينًا لما استودعتني، فلا أخشى خبر السوء. آمين.\"},{\"t\":\"أعطى كل واحد حسب طاقته\",\"ref\":\"متى ٢٥: ١٥\",\"bk\":\"متى\",\"v\":\"فأعطى واحدا خمس وزنات، وآخر وزنتين، وآخر وزنة. كل واحد على قدر طاقته. وسافر للوقت.\",\"r\":\"«فأعطى واحدًا خمس وزنات وآخر وزنتين وآخر وزنة، كل واحد على قدر طاقته». الله لا يظلمني بمقارنة غيري، ولا يطلب مني ما لم يعطني. وأنا مسؤول عن وزنتي أنا لا وزنات الآخرين. وهذا يحميني من الحسد والاستهانة بنفسي.\",\"p\":\"يا رب، أشكرك على ما أعطيتني على قدر طاقتي. علّمني ألا أحسد غيري ولا أحتقر وزنتي، بل أستخدمها بفرح وأمانة. آمين.\"},{\"t\":\"أتمم عملي وأنا أعولك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سلوان: أنا عبد وسيدي قال لي: أتمم عملي وأنا أعولك. الوكيل الأمين يقوم بما عليه ويترك الباقي للسيد. لا تتوقف اليوم عن العمل خوفًا من النتائج، بل أتمّ ما كُلفت به وسلّم الباقي.\",\"p\":\"يا رب، أنا عبدك، فأتمم عملي بأمانة وأنت تعولني. أعطني ثقة في تدبيرك لما لا أستطيعه. آمين.\",\"fq\":513}]},\"4-12\":{\"th\":\"فرح القيامة\",\"m\":[{\"t\":\"حولتَ نوحي إلى فرح\",\"ref\":\"المزمور ٢٩ (٣٠) — الثالثة\",\"v\":\"سمع الرب فرحمني، الرب صار لي عونا. حولت نوحي إلى فرح لي؛ مزقت مسحي ومنطقتني سرورا. لكي ترتل لك نفسي ولا يحزن قلبي.\",\"r\":\"يشهد المرنم لفرح ما بعد الحزن: حولت نوحي إلى فرح، ومزقت مسحي ومنطقتني سرورًا. هذه صورة القيامة: الحزن لا يُمحى بل يتحول. تذكّر اليوم موقفًا حزينًا حوّله الله فرحًا، وسبّحه عليه بصوت عالٍ.\",\"p\":\"سمعت يا رب فرحمتني، وصرت لي عونًا. حولت نوحي إلى فرح، لترتل لك نفسي ولا يحزن قلبي. لك المجد. آمين.\"},{\"t\":\"فرح التلاميذ\",\"ref\":\"يوحنا ٢٠: ٢٠\",\"bk\":\"يوحنا\",\"v\":\"ولما قال هذا أراهم يديه وجنبه، ففرح التلاميذ إذ رأوا الرب.\",\"r\":\"«فلما قال هذا أراهم يديه وجنبه، ففرح التلاميذ إذ رأوا الرب». الفرح لم يأتِ من تغيير الظروف بل من رؤية الرب. والجراح التي يحملها تؤكد أنه هو، وأنه انتصر. وأنا أيضًا أجد فرحي الأول في لقائه، قبل أن تتغير ظروفي.\",\"p\":\"يا رب القائم، أرني يديك وجنبك فأفرح. حوّل حزني فرحًا بلقائك، وامنحني فرحًا لا ينزعه أحد منّي. المسيح قام، بالحقيقة قام. آمين.\"},{\"t\":\"فرح لا يوصف\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي إن التعب والجهاد يكثران في البداية عند الذين يتقدمون نحو الله، لكن بعد ذلك يغمرهم فرح لا يوصف، كمن يشعل النار فيلفحه الدخان ثم يفرح بالنور. لا تيأس من دخان الجهاد، فوراءه فرح.\",\"p\":\"يا رب، قوّني في الجهاد، ولا تدعني أتوقف عند دخان البداية. أذقني فرحك الذي لا يوصف. آمين.\",\"fq\":531}]},\"4-13\":{\"th\":\"المسيح رفيق الطريق\",\"m\":[{\"t\":\"لأنك أنت معي\",\"ref\":\"المزمور ٢٢ (٢٣) — الثالثة\",\"v\":\"إن سلكت في وسط ظلال الموت فلا أخاف شرا، لأنك أنت معي. عصاك وعكازك هما يعزيانني.\",\"r\":\"لا يعد الراعي بغياب ظلال الموت، بل بأن يكون معنا فيها: «لا أخاف شرًا لأنك أنت معي». ورفيق الطريق يظهر في أضيق الأماكن. هل في طريقك اليوم ظل ثقيل؟ تذكّر أنك لا تسير فيه وحدك.\",\"p\":\"إن سلكت في وسط ظلال الموت فلا أخاف شرًا لأنك أنت معي، وعصاك وعكازك يعزيانني. كن معي في طريقي كله. آمين.\"},{\"t\":\"أمكث معنا\",\"ref\":\"لوقا ٢٤: ٢٩\",\"bk\":\"لوقا\",\"v\":\"فألزماه قائلين: «امكث معنا، لأنه نحو المساء وقد مال النهار». فدخل ليمكث معهما.\",\"r\":\"«أمكث معنا لأنه نحو المساء وقد مال النهار». كانت دعوة بسيطة من قلب محتاج. والمسيح «تظاهر أنه منطلق»، لكنه ينتظر الدعوة. وكم مرة يتيح لي الله الاختيار أن أدعوه! والدعوة تفتح باب الشركة. وفي المساء تزداد حاجتي إليه.\",\"p\":\"يا رب، أمكث معنا لأنه نحو المساء. ادخل بيتي وقلبي، وكن ضيفي ثم مضيفي، وافتح عينيّ لأعرفك في كل ما أمرّ به. آمين.\"},{\"t\":\"ليكن الله نصب عينيك\",\"ref\":\"\",\"v\":\"\",\"r\":\"أجاب القديس أنطونيوس من سأله ماذا يحفظ لكي يرضي الله: حيثما تذهب ليكن الله نصب عينيك. هذه هي الصحبة: أن يرافقنا في كل خطوة. فاسأل نفسك وأنت في الطريق اليوم: أين أنت من حضور الله؟\",\"p\":\"يا رب، ليكن حضورك أمام عيني حيثما ذهبت. ارافقني كما رافقت تلميذي عمواس، وافتح عيني لأعرفك. آمين.\",\"fq\":1}]},\"4-14\":{\"th\":\"الروح القدس المعزي\",\"m\":[{\"t\":\"هلمّ تفضل وحل فينا\",\"ref\":\"قطعة مشتركة — نصف الليل — الخدمة الثالثة\",\"v\":\"أيها الملك السمائي المعزي، روح الحق، الحاضر في كل مكان والمالئ الكل، كنز الصالحات ومعطي الحياة، هلم تفضل وحل فينا، وطهرنا من كل دنس أيها الصالح، وخلص نفوسنا.\",\"r\":\"هذه صلاة الكنيسة للروح القدس المعزي: حاضر في كل مكان ومالئ الكل، لكننا نطلب أن يحل فينا. وجوده معنا ليس إلغاء لسؤالنا، فالروح يحل حيث يُدعى. اطلبه اليوم بهذه الكلمات قبل أول عمل مهم.\",\"p\":\"أيها الملك السمائي المعزي، روح الحق، هلم تفضل وحل فينا. طهرنا من كل دنس، وخلص نفوسنا، واعزِّني في كل ضيق. آمين.\"},{\"t\":\"أبناء الله\",\"ref\":\"رومية ٨: ١٤\",\"bk\":\"رومية\",\"v\":\"لأن كل الذين ينقادون بروح الله، فأولئك هم أبناء الله.\",\"r\":\"«لأن كل الذين ينقادون بروح الله فأولئك هم أبناء الله». أن أكون ابنًا ليس مجرد لقب بل حياة تنقاد. والروح ينقاد بها من يصغي. وهو يقودني إلى الحق والسلام والمحبة. وكلما استسلمت لقيادته تعمّقت بنوتي.\",\"p\":\"يا روح الله، قُدني كما يُقاد الأبناء. أعطني روح التبني لأصرخ: يا أبا الآب، وحرّرني من الخوف، وثبّتني في بنوّتي لك. آمين.\"},{\"t\":\"أهرع إلى الشجرة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يصف الأب يوحنا الكولوفي نفسه بإنسان تحت شجرة كبيرة يرى وحوشًا تقترب، فيهرع إلى الشجرة فينجو. هكذا نلجأ إلى الله. الروح القدس هو العزاء في الخطر. اللجوء الفوري في أول خوف أفضل من محاولة المواجهة وحدنا.\",\"p\":\"يا رب، أهرع إليك عندما تقترب الوحوش. كن أنت ملجئي وعزائي، وأنا آمن في ظلك. آمين.\",\"fq\":154}]},\"4-15\":{\"th\":\"مواهب الروح\",\"m\":[{\"t\":\"رتلوا بفهم\",\"ref\":\"المزمور ٤٦ (٤٧) — الثالثة\",\"v\":\"رتلوا لإلهنا رتلوا، رتلوا لمليكنا رتلوا، لأن الرب هو ملك الأرض كلها. رتلوا بفهم لأن الرب قد ملك على جميع الأمم.\",\"r\":\"التسبيح بفهم يعني أن نغني ونعرف لمن نغني. والروح القدس يعطي كل واحد موهبة للنفع المشترك، وكل موهبة تصلح أن تتحول إلى تسبيح في الكنيسة. ما الذي أعطاك الله إياه ولا تستخدمه؟ قدمه اليوم ولو في خدمة صغيرة.\",\"p\":\"رتلوا لإلهنا رتلوا، رتلوا بفهم. يا رب، أنت ملك الأرض كلها، فاستخدم مواهبي لمجدك ولبنيان إخوتي. آمين.\"},{\"t\":\"لبنيان جسد المسيح\",\"ref\":\"أفسس ٤: ١١–١٢\",\"bk\":\"أفسس\",\"v\":\"وهو أعطى البعض أن يكونوا رسلا، والبعض أنبياء، والبعض مبشرين، والبعض رعاة ومعلمين، لأجل تكميل القديسين لعمل الخدمة، لبنيان جسد المسيح،\",\"r\":\"«وهو أعطى البعض أن يكونوا رسلًا والبعض أنبياء والبعض مبشرين والبعض رعاة ومعلمين، لأجل تكميل القديسين لعمل الخدمة لبنيان جسد المسيح». غاية الخدمة ليست أن يفعل الخادم كل شيء، بل أن يعد كل المؤمنين للخدمة. فكل واحد في الكنيسة خادم بنوع ما.\",\"p\":\"يا رب، أشكرك على من أعطيتهم لكنيستك رعاة ومعلمين. أهّلنا جميعًا لعمل الخدمة، واجعلنا نبني بعضنا في الوحدة والمحبة. آمين.\"},{\"t\":\"الكلام كثير والعمل قليل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يعقوب إن حاجتنا ليست إلى الكلام لأنه في هذا الزمان كثير، إنما إلى العمل. المواهب تتحول إلى خدمة بالعمل لا بالكلام. اسأل: ما عمل اليوم الذي أعدّه الروح لي؟ ابدأ به ولا تؤجله.\",\"p\":\"يا رب، أعطني أن أعمل بما أعطيتني. لا يكفي الكلام، فاجعل مواهبي ثمرًا ينفع كنيستك. آمين.\",\"fq\":190}]},\"4-16\":{\"th\":\"التربية بمحبة\",\"m\":[{\"t\":\"طوبى للسالكين في طرقه\",\"ref\":\"المزمور ١٢٧ (١٢٨) — الغروب\",\"v\":\"طوبى لجميع الذين يتقون الرب السالكين في طرقه. تأكل من ثمرة أتعابك تصير مغبوطا ويكون لك الخير.\",\"r\":\"يربط المزمور بين تقوى الأب وسلام البيت. التربية بمحبة تبدأ من سلوك الوالدين أنفسهم في طرق الرب، فالأبناء يتعلمون بالنظر أكثر من الاستماع. ما الذي يراه أبناؤك أو أخوتك الصغار منك اليوم؟ اجعله يستحق التقليد.\",\"p\":\"طوبى لجميع الذين يتقون الرب السالكين في طرقه. اجعلني قدوة صالحة لمن أربيهم، وبارك تعبي في بيتي ليأتي بخير. آمين.\"},{\"t\":\"نخبر الجيل الآتي\",\"ref\":\"المزامير ٧٨: ٤\",\"bk\":\"المزامير\",\"v\":\"لا نخفي عن بنيهم إلى الجيل الآخر، مخبرين بتسابيح الرب وقوته وعجائبه التي صنع.\",\"r\":\"«لا نخفي عن بنيهم إلى الجيل الأخير مخبرين بتسابيح الرب وقوته وعجائبه التي صنع». قصص الله في حياتنا ليست لنا وحدنا، إنها ميراث للجيل التالي. وأن أحكي لأولادي كيف نصرني الله هو أعمق أشكال التعليم. والتسبيح ينتقل بالحكي.\",\"p\":\"يا رب، علّمنا أن نخبر الجيل الآتي بعجائبك. ولا تدعنا ننسى أعمالك معنا، وأعطنا أن نرويها بفرح لتثبّت إيمان أبنائنا فيك. آمين.\"},{\"t\":\"ثلاثة أمور نافعة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يلخّص الأب بيمن ما ينفع في ثلاث كلمات: مخافة الرب والصلاة والإحسان إلى القريب. وهي أيضًا أساس التربية الناجحة: أن يرى الصغير الصلاة والإحسان ويتعلم المخافة. أي واحدة منها تحتاج إلى مزيد من حضور في بيتك؟\",\"p\":\"يا رب، اجعل في بيتي مخافتك والصلاة والإحسان. ربِّ أبناءنا بمحبتك، وأعطنا حكمة أن نعلمهم بأعمالنا. آمين.\",\"fq\":433}]},\"4-17\":{\"th\":\"قبول الآخر\",\"m\":[{\"t\":\"الرب يحفظ الغرباء\",\"ref\":\"المزمور ١٤٥ — النوم\",\"v\":\"الرب يحفظ الغرباء. ويعضد اليتيم والأرملة.\",\"r\":\"يمدح المرنم الله الذي يحفظ الغرباء ويعضد اليتيم والأرملة. قبول الآخر يبدأ حين أنظر إليه بنظرة الله. من هو الغريب في محيطك: زميل جديد، جار، أو شخص مختلف عنك؟ اقترب منه اليوم بكلمة ترحيب.\",\"p\":\"أيها الرب الذي تحفظ الغرباء وتعضد اليتيم والأرملة، علّمني أن أقبل كل إنسان كما قبلتني. وسّع قلبي بمحبتك. آمين.\"},{\"t\":\"اقبلوا بعضكم بعضًا\",\"ref\":\"رومية ١٥: ٧\",\"bk\":\"رومية\",\"v\":\"لذلك اقبلوا بعضكم بعضا كما أن المسيح أيضا قبلنا، لمجد الله.\",\"r\":\"«لذلك اقبلوا بعضكم بعضًا كما أن المسيح أيضًا قبلنا لمجد الله». المسيح قبلني بضعفي وخطاياي. فكيف لا أقبل أخي؟ وقبوله ليس عاطفة بل قرار: أن أرحب به وأفتح له مكانًا. وهذا يمجد الله لأنه يظهر محبته في الجماعة.\",\"p\":\"يا رب، قبلتني كما أنا لمجدك. أعطني أن أقبل إخوتي بنفس المحبة، وأن نمجدك معًا بقلب واحد وفم واحد. آمين.\"},{\"t\":\"مددتُ المائدة ست مرات\",\"ref\":\"\",\"v\":\"\",\"r\":\"يحكي الشيخ لكسيانوس أنه من أجل الإخوة الزوار مدّ المائدة ست مرات وهو يتوسل إلى كل واحد أن يأكل ويأكل معه. القبول فعل ضيافة، لا مجرد تسامح. استقبل اليوم أحدًا في بيتك أو في وقتك بسخاء حقيقي.\",\"p\":\"يا رب، علّمني الضيافة والترحيب بالجميع. اجعل بيتي وقلبي مفتوحين لكل من ترسله إليّ. آمين.\",\"fq\":210}]},\"4-18\":{\"th\":\"بيت الله\",\"m\":[{\"t\":\"طوبى للساكنين في بيتك\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"طوبى لكل الساكنين في بيتك. يباركونك إلى الأبد.\",\"r\":\"بيت الله ليس مبنى فقط بل مكان يسكن فيه المؤمنون ويباركون الله إلى الأبد. السكنى فيه علاقة وليست زيارة. هل علاقتك بالكنيسة حضور شكلي أم سكنى؟ شارك اليوم بكلمة أو خدمة تجعلك أقرب.\",\"p\":\"طوبى للساكنين في بيتك، يباركونك إلى الأبد. اجعلني ساكنًا في كنيستك بقلبي، وأجد فيها بيتي الروحي. آمين.\"},{\"t\":\"يوم في ديارك\",\"ref\":\"المزامير ٨٤: ١٠\",\"bk\":\"المزامير\",\"v\":\"لأن يوما واحدا في ديارك خير من ألف. اخترت الوقوف على العتبة في بيت إلهي على السكن في خيام الأشرار.\",\"r\":\"«لأن يومًا واحدًا في ديارك خير من ألف. اخترت الوقوف على العتبة في بيت إلهي على السكنى في خيام الأشرار». هذا ليس ترفًا لفظيًا بل اشتياق حقيقي. ما قيمة ألف يوم بعيدًا عن الله؟ ويوم واحد معه يملأ العمر. فأين أضع أولوية زمني؟\",\"p\":\"يا رب، ما أحلى مساكنك. اجعلني أشتاق إلى بيتك أكثر من أي مكان، وأحب الوقوف على عتبته بتواضع، وأعيش فيه بقلبي حتى حين أكون بعيدًا عنه بجسدي. آمين.\"},{\"t\":\"ما نحفظه عندما نخرج\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيرينيوس إن حفظ القانون في القلاية ليس فضيلة كبيرة، إنما المهم أن نحفظه عندما نخرج. ما نتعلمه في بيت الله يمتحن في الطريق والعمل. فاحمل اليوم شيئًا من الكنيسة إلى أول موقف صعب.\",\"p\":\"يا رب، ما أسمعه في بيتك أحفظه حين أخرج. اجعل حياتي كلها امتدادًا لعبادتي لك. آمين.\",\"fq\":523}]},\"4-19\":{\"th\":\"الخضوع لله\",\"m\":[{\"t\":\"كعيون العبيد إلى أيدي مواليهم\",\"ref\":\"المزمور ١٢٢ (١٢٣) — الغروب\",\"v\":\"إليك رفعت عيني يا ساكن السماء. فها هما مثل عيون العبيد إلى أيدي مواليهم. ومثل عيني الأمة إلى يدي سيدتها. كذلك أعيننا نحو الرب إلهنا حتى يتراءف علينا.\",\"r\":\"الخضوع لله ينظر إلى يد السيد في كل حاجة ولا يتكل على نفسه. هو يرفع عينيه إلى ساكن السماء ينتظر أن يتراءف. الخضوع ليس إذلالًا بل ثقة. هل ترفع عينيك اليوم إلى الله أم إلى حيلك؟ اجعل نظرك إليه.\",\"p\":\"إليك رفعت عيني يا ساكن السماء، كعيون العبيد إلى أيدي مواليهم. أعيننا نحوك حتى تتراءف علينا. آمين.\"},{\"t\":\"الرب أعطى والرب أخذ\",\"ref\":\"أيوب ١: ٢١\",\"bk\":\"أيوب\",\"v\":\"وقال: «عريانا خرجت من بطن أمي، وعريانا أعود إلى هناك. الرب أعطى والرب أخذ، فليكن اسم الرب مباركا».\",\"r\":\"«عريانًا خرجت من بطن أمي وعريانًا أعود إلى هناك. الرب أعطى والرب أخذ فليكن اسم الرب مباركًا». لم يتجاهل أيوب الألم، فقد مزّق ثوبه وجز شعره، لكنه سجد وبارك. والخضوع ليس إنكارًا للجرح بل ثقة في سيادة الله.\",\"p\":\"يا رب، أنت أعطيت وأنت أخذت، فليكن اسمك مباركًا. أسلم لك ما أملك وما فقدت، وأعطني قلبًا يسجد ويثق في كل حال. آمين.\"},{\"t\":\"السور النحاسي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن إرادة الإنسان سور نحاسي بينه وبين الله. الخضوع يهدم هذا السور. ما الذي تصرّ عليه بإرادتك رغم أنك تعلم أنه يبعدك عن الله؟ اترك قرارك اليوم لمشيئته.\",\"p\":\"يا رب، أهدم سور إرادتي الذي يفصلني عنك. علّمني الخضوع لمشيئتك الصالحة المرضية. آمين.\",\"fq\":352}]},\"4-20\":{\"th\":\"الكتاب المقدس\",\"m\":[{\"t\":\"فرائض الرب تفرح القلب\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"فرائض الرب مستقيمة، تفرح القلب. وصية الرب مضيئة؛ تنير العينين عن بعد.\",\"r\":\"تحدّث المرنم عن فرائض الرب كأنها فرحة: تفرح القلب وتنير العينين. الكتاب المقدس ليس عبئًا بل نور. قبل أن تشغل بالك بأخبار اليوم، افتح الإنجيل وخصص له نفس الوقت الذي تعطيه لهاتفك.\",\"p\":\"فرائض الرب مستقيمة تفرح القلب، ووصية الرب مضيئة تنير العينين. يا رب، نوّر عيني بكلمتك كل يوم. آمين.\"},{\"t\":\"كلمة الله حية وفعالة\",\"ref\":\"العبرانيين ٤: ١٢\",\"bk\":\"العبرانيين\",\"v\":\"لأن كلمة الله حية وفعالة وأمضى من كل سيف ذي حدين، وخارقة إلى مفرق النفس والروح والمفاصل والمخاخ، ومميزة أفكار القلب ونياته.\",\"r\":\"«لأن كلمة الله حية وفعالة وأمضى من كل سيف ذي حدين». الكلمة ليست حبرًا على ورق، إنها حية تعمل فيّ. تخترق وتكشف وتشفي. وقد تؤلمني أحيانًا، لكنها كالمشرط الذي يعالج. وكلما قرأتها بتواضع كشفت لي نفسي بحنان.\",\"p\":\"يا رب، كلمتك حية وفعالة. اخترق قلبي بنورها واكشف ما يحتاج إلى شفاء، وقوّني لأطيعها وأعيش بها كل يوم. آمين.\"},{\"t\":\"جهل الكتب هاوية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس إبيفانيوس إن جهل الكتب المقدسة هاوية عميقة ومنخفض سحيق. من لا يعرف الكتاب يضل في طرق كثيرة. فاسأل نفسك: ما أقل ما أعرفه من الكتاب وما أحتاج إليه؟ ابدأ به.\",\"p\":\"يا رب، احفظني من هاوية الجهل. افتح ذهني لفهم كتبك، واجعلني أنمو في معرفتك كل يوم. آمين.\",\"fq\":101}]},\"4-21\":{\"th\":\"الصبر على النفس\",\"m\":[{\"t\":\"إلى متى أردد هذه المشورات؟\",\"ref\":\"المزمور ١٢ (١٣) — باكر\",\"v\":\"إلى متى أردد هذه المشورات في نفسي، وهذه الأوجاع في قلبي النهار كله؟\",\"r\":\"يعبّر المرنم عن تعب النفس من أفكارها: إلى متى أردد هذه المشورات في نفسي وهذه الأوجاع في قلبي؟ الصبر على النفس يبدأ بالاعتراف بالتعب بلا جلد للذات. ارفق بنفسك اليوم، فالله يرفق بك، وضع أمامه ما يدور في ذهنك.\",\"p\":\"إلى متى أردد هذه المشورات في نفسي وهذه الأوجاع في قلبي النهار كله؟ يا رب، أنت صبور على نفسي، فعلّمني الصبر عليها. آمين.\"},{\"t\":\"الكتب مكتوبة لتعليمنا\",\"ref\":\"رومية ١٥: ٤\",\"bk\":\"رومية\",\"v\":\"لأن كل ما سبق فكتب كتب لأجل تعليمنا، حتى بالصبر والتعزية بما في الكتب يكون لنا رجاء.\",\"r\":\"«لأن كل ما سبق فكتب كتب لأجل تعليمنا حتى بالصبر والتعزية بما في الكتب يكون لنا رجاء». الكتاب يعلّمني ويعزيني ويعطيني صبرًا ورجاء. وقصص الأنبياء والأبرار فيه ليست تاريخًا فقط بل مرايا لحياتي. وكلما قرأت شعرت أنني لست وحدي في الصراع.\",\"p\":\"يا رب، أشكرك على قصص الأبرار التي تعلّمني. اجعل كلمتك تعزيتي وصبري ورجائي، وقوّني بها في أوقات الانتظار الطويلة. آمين.\"},{\"t\":\"الأفكار تموت مع الوقت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن الأفكار الشريرة بثعبان أو عقرب في وعاء، يموتان مع الوقت إذا لم نغذِّهما. الصبر على النفس أن أنتظر موت فكر دون أن أتبعه. ما الفكرة التي تغذيها ولا تحتاج إليها؟ توقف عن تغذيتها اليوم.\",\"p\":\"يا رب، أعطني صبرًا على أفكاري لأتركها تموت ولا أغذيها. نقِّ ذهني بنعمتك. آمين.\",\"fq\":323}]},\"4-22\":{\"th\":\"الخطايا الخفية\",\"m\":[{\"t\":\"من الخطايا المستترة طهرني\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"الهفوات من يشعر بها؟ من الخطايا المستترة يا رب طهرني.\",\"r\":\"يسأل المرنم: الهفوات من يشعر بها؟ ثم يطلب: من الخطايا المستترة يا رب طهرني. نحن لا نرى كل ما فينا، فنحتاج أن يكشفه الله. أنهِ يومك اليوم بخمس دقائق تسأل فيها الله أن يريك ما خفي عنك.\",\"p\":\"الهفوات من يشعر بها؟ من الخطايا المستترة يا رب طهرني. افحص قلبي وأرني ما أخفيه عن نفسي. آمين.\"},{\"t\":\"اختبرني يا الله\",\"ref\":\"المزامير ١٣٩: ٢٣–٢٤\",\"bk\":\"المزامير\",\"v\":\"اختبرني يا الله واعرف قلبي. امتحني واعرف أفكاري. وانظر إن كان في طريق باطل، واهدني طريقا أبديا.\",\"r\":\"«اختبرني يا الله واعرف قلبي، امتحني واعرف أفكاري، وانظر إن كان فيّ طريق باطل واهدني طريقًا أبديًا». هذه شجاعة روحية: أن أدعو الله ليفحصني. وهو لا يفحص ليدين بل ليهدي. فالفحص مدخل للهداية.\",\"p\":\"اختبرني يا الله واعرف قلبي، امتحنني واعرف أفكاري. وانظر إن كان فيّ طريق باطل، واهدني طريقًا أبديًا بنعمتك. آمين.\"},{\"t\":\"أن يشعر بأنه خاطئ\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى الحبشي إن الإنسان إذا لم يشعر في أعماقه أنه خاطئ لا يصغي إليه الله. الإحساس بالخطية بداية الاستجابة، وهو نعمة. اطلب اليوم هذا الإحساس بلا قلق مرضي ولا يأس.\",\"p\":\"يا رب، أعطني أن أشعر بخطيتي وأقف أمامك بتواضع. اسمع صلاتي واغفر لي. آمين.\",\"fq\":262}]},\"4-23\":{\"th\":\"الشهادة بالأمانة\",\"m\":[{\"t\":\"أمام الملائكة أرتل لك\",\"ref\":\"المزمور ١٣٧ — النوم\",\"v\":\"أعترف لك يا رب من كل قلبي لأنك استمعت كل كلمات فمي. أمام الملائكة أرتل لك وأسجد قدام هيكلك المقدس، وأعترف لاسمك على رحمتك وحقك.\",\"r\":\"يعلن المرنم اعترافه أمام الملائكة وفي الهيكل. الشهادة بالأمانة تبدأ باعتراف علني بالإيمان في الأمور الصغيرة قبل الكبيرة. هل تخجل من إعلان إيمانك في مكان عملك أو دراستك؟ تقدم اليوم بخطوة اعتراف بسيطة.\",\"p\":\"أعترف لك يا رب من كل قلبي، وأرتل لك أمام الملائكة، وأسجد قدام هيكلك المقدس. اجعلني شاهدًا أمينًا لاسمك. آمين.\"},{\"t\":\"من اعترف بي قدام الناس\",\"ref\":\"متى ١٠: ٣٢\",\"bk\":\"متى\",\"v\":\"فكل من يعترف بي قدام الناس أعترف أنا أيضا به قدام أبي الذي في السماوات،\",\"r\":\"«فكل من يعترف بي قدام الناس أعترف أنا أيضًا به قدام أبي الذي في السماوات». وعد جميل: المسيح لا ينسى من يشهد له. والاعتراف لا يعني صراخًا بل صدقًا في إعلان الانتماء. وأنا مدعو أن أعيش علنًا كمسيحي: في كلامي وسلوكي وأخلاقي.\",\"p\":\"يا رب يسوع، أعترف بك أمام الناس بفرح. لا تدعني أخجل منك، واعترف بي أمام أبيك في السماء، وقوّني لأحمل صليبي وأتبعك. آمين.\"},{\"t\":\"لا خلاص بدون تجارب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أنطونيوس: «لا أحد يقدر أن يدخل ملكوت السموات بدون تجارب، ارفع التجارب فلا يخلص أحد». الشاهد الأمين لا يفرّ من التجربة بل يجتازها بالله. ما التجربة التي تواجهها وتظن أنها تعطلك؟ قد تكون هي طريقك.\",\"p\":\"يا رب، قوّني في التجارب لأثبت شاهدًا لك. علّمني أن أرى فيها طريقًا إلى ملكوتك. آمين.\",\"fq\":3}]},\"4-24\":{\"th\":\"هأنذا أرسلني\",\"m\":[{\"t\":\"مستعد قلبي يا الله\",\"ref\":\"المزمور ٥٦ (٥٧) — السادسة\",\"v\":\"مستعد قلبي يا الله مستعد قلبي. أسبح وأرتل في تمجيدي.\",\"r\":\"«هأنذا أرسلني» تبدأ بقلب مستعد: مستعد قلبي يا الله مستعد قلبي. الاستعداد يعني أن أقف على باب العمل قبل أن أعرف ما هو. فكّر اليوم: لو ناداك الله الآن لمهمة محددة، هل قلبك مستعد؟\",\"p\":\"مستعد قلبي يا الله، مستعد قلبي. أسبح وأرتل في تمجيدي. أرسلني يا رب إلى حيث تشاء، وقوّني لأحمل رسالتك. آمين.\"},{\"t\":\"إناء مختار\",\"ref\":\"أعمال الرسل ٩: ١٥–١٦\",\"bk\":\"أعمال الرسل\",\"v\":\"فقال له الرب: «اذهب! لأن هذا لي إناء مختار ليحمل اسمي أمام أمم وملوك وبني إسرائيل. لأني سأريه كم ينبغي أن يتألم من أجل اسمي».\",\"r\":\"«اذهب لأن هذا لي إناء مختار ليحمل اسمي أمام أمم وملوك وبني إسرائيل». كان شاول مضطهِدًا، لكن الله رأى فيه ما لا يراه الناس. وهذا يعطيني رجاء: ربما يرى الله فيّ إناءً مختارًا رغم ماضيّ. وفي الوقت نفسه يذكر الألم: فالدعوة ليست رخاءً.\",\"p\":\"يا رب، اجعلني إناءً مختارًا لاسمك. أعطني طاعة حنانيا وشجاعة بولس، واستخدمني لتبلغ محبتك إلى من لا أتوقعهم، واحتمل معي الألم. آمين.\"},{\"t\":\"ذلّل نفسك لأخيك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب بيمن: «لا تشبع مشيئتك، لكن بالأحرى ذلِّل نفسك لأخيك». الإرسالية خدمة للآخر قبل أن تكون إنجازًا. ما الذي يمكنك اليوم أن تتنازل عنه لأجل راحة أخ؟ ابدأ بهذه الخطوة.\",\"p\":\"يا رب، علّمني أن أذلل نفسي لأخي وأضع مشيئتك فوق مشيئتي. أرسلني لأخدم من أجلك. آمين.\",\"fq\":431}]},\"4-25\":{\"th\":\"ثمر الحياة\",\"m\":[{\"t\":\"كالشجرة المغروسة\",\"ref\":\"المزمور الأول — باكر\",\"v\":\"لكن في ناموس الرب إرادته، وفى ناموسه يلهج نهارا وليلا. فيكون كالشجرة المغروسة على مجارى المياه التي تعطى ثمرها في حينه. وورقها لا ينتثر، وكل ما يصنع ينجح فيه.\",\"r\":\"يصور المرنم المؤمن شجرة مغروسة على مجاري المياه، تعطي ثمرها في حينه ولا ينتثر ورقها. الثمر نتيجة جذور وصبر، وليس شيئًا يُصنع بالقوة. ما الذي تغذي به جذورك اليوم: وقتًا مع كلمة الله أم مجرد انشغال؟\",\"p\":\"يا رب، اجعل إرادتي في ناموسك، وأمل بي كشجرة على مجاري المياه تعطي ثمرها في حينه. بارك كل ما أصنع بنعمتك. آمين.\"},{\"t\":\"اتركها هذه السنة أيضًا\",\"ref\":\"لوقا ١٣: ٦–٩\",\"bk\":\"لوقا\",\"v\":\"وقال هذا المثل: «كانت لواحد شجرة تين مغروسة في كرمه، فأتى يطلب فيها ثمرا ولم يجد. فقال للكرام: هوذا ثلاث سنين آتي أطلب ثمرا في هذه التينة ولم أجد. اقطعها! لماذا تبطل الأرض أيضا؟ فأجاب وقال له: يا سيد، اتركها هذه السنة أيضا، حتى أنقب حولها وأضع زبلا. فإن صنعت ثمرا، وإلا ففيما بعد تقطعها».\",\"r\":\"«يا سيد اتركها هذه السنة أيضًا حتى أنقب حولها وأضع زبلًا، فإن صنعت ثمرًا وإلا ففيما بعد تقطعها». الكرام يشفع في الشجرة. والمسيح يشفع فينا. ويعطينا مهلة، لا للتهاون بل للعمل. والله يعتني بنا بالتنقيب والسماد، أي بالتأديب والنعمة.\",\"p\":\"يا رب، أشكرك لأنك تشفع فيّ وتمهلني. افلح حول قلبي، وضع فيه سمادك، وأعطني أن أثمر ثمرًا يرضيك قبل أن تنتهي مهلتي. آمين.\"},{\"t\":\"الورق والثمر\",\"ref\":\"\",\"v\":\"\",\"r\":\"سُئل القديس أغاثون: أيهما أعظم، التعب الجسدي أم ضبط ما في الداخل؟ فشبّه الإنسان بشجرة: التعب الجسدي هو الورق وضبط الداخل هو الثمر. الله يطلب الثمر. ما الثمر الداخلي الذي تعمل عليه اليوم؟\",\"p\":\"يا رب، لا تدعني أكتفي بورق مظهر خارجي. اجعلني أحمل ثمر قلب نقي ومتضع ينفع الآخرين. آمين.\",\"fq\":49}]},\"4-26\":{\"th\":\"العدل والرحمة\",\"m\":[{\"t\":\"رحمة وحكمًا أسبحك\",\"ref\":\"المزمور ١٠٠ (١٠١) — التاسعة\",\"v\":\"رحمة وحكما أسبحك يا رب. أترنم لك. وأتفهم في طريق بلا عيب.\",\"r\":\"يربط المرنم بين الرحمة والحكم، كأنهما جناحا العدل. والعدل بدون رحمة قسوة، والرحمة بدون حق ضعف. وهو يتعهد أن يتفهم في طريق بلا عيب. في قرار تتخذه اليوم، اسأل: هل فيه رحمة وعدل معًا؟\",\"p\":\"رحمة وحكمًا أسبحك يا رب، وأترنم لك. اجعلني أتفهم في طريق بلا عيب، وأقضي بالعدل والرحمة. آمين.\"},{\"t\":\"ما يطلبه الرب منك\",\"ref\":\"ميخا ٦: ٨\",\"bk\":\"ميخا\",\"v\":\"قد أخبرك أيها الإنسان ما هو صالح، وماذا يطلبه منك الرب، إلا أن تصنع الحق وتحب الرحمة، وتسلك متواضعا مع إلهك.\",\"r\":\"«قد أخبرك أيها الإنسان ما هو صالح وماذا يطلبه منك الرب: إلا أن تصنع الحق وتحب الرحمة وتسلك متواضعًا مع إلهك». ثلاثة أشياء بسيطة وصعبة معًا: عدل في التعامل، ورحمة في القلب، وتواضع في السير مع الله. وهذا هو جوهر الدين.\",\"p\":\"يا رب، علّمني أن أصنع الحق وأحب الرحمة وأسلك متواضعًا معك. اجعل حياتي تعكس ما تطلبه منّي، لا مظاهر خارجية فقط. آمين.\"},{\"t\":\"الشر لا يبطل الشر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: «الشر لا يبطل الشر أبدًا. إنما إذا أساء إليك أحد، أحسن إليه، لأنك بذلك تضحد الشر». هذا هو العدل المسيحي: لا مقابلة بالمثل بل إحسان يهزم الإساءة. من أساء إليك مؤخرًا؟ أحسن إليه بشيء بسيط.\",\"p\":\"يا رب، علّمني أن أغلب الشر بالخير. أعطني قلبًا يحسن لمن أساء إليّ، ولا يردّ الشر بشر. آمين.\",\"fq\":446}]},\"4-27\":{\"th\":\"الإنسان الجديد\",\"m\":[{\"t\":\"أنت تعود فتحيينا\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"أنت يا الله تعود فتحيينا، وشعبك يفرح بك. أرنا يا رب رحمتك. وأعطنا خلاصك.\",\"r\":\"الإنسان الجديد ليس صناعة ذاتية بل عودة الله إلينا وإحياؤه لنا: «أنت يا الله تعود فتحيينا وشعبك يفرح بك». نحن نطلب رحمته وخلاصه. ما الجزء من حياتك الذي تحتاج أن يعيد الله إحياءه؟ ارفعه اليوم بصلاة محددة.\",\"p\":\"أنت يا الله تعود فتحيينا، وشعبك يفرح بك. أرنا يا رب رحمتك وأعطنا خلاصك، وجدد فيّ إنساني الجديد. آمين.\"},{\"t\":\"لا تشاكلوا هذا الدهر\",\"ref\":\"رومية ١٢: ٢\",\"bk\":\"رومية\",\"v\":\"ولا تشاكلوا هذا الدهر، بل تغيروا عن شكلكم بتجديد أذهانكم، لتختبروا ما هي إرادة الله: الصالحة المرضية الكاملة.\",\"r\":\"«ولا تشاكلوا هذا الدهر بل تغيروا عن شكلكم بتجديد أذهانكم لتختبروا ما هي إرادة الله الصالحة المرضية الكاملة». هناك ضغط خفي لأتشبه بالعالم في تفكيره. لكن الله يدعوني لأتغير من الداخل. وبهذا التغيير أعرف إرادته: «صالحة مرضية كاملة».\",\"p\":\"يا رب، لا تدعني أشاكل هذا الدهر. غيّر أفكاري وقلبي بروحك، وأعطني أن أميّز إرادتك الصالحة المرضية الكاملة وأعمل بها. آمين.\"},{\"t\":\"التثاقل في كل بداية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن التثاقل موجود في كل بداءة وليس هوى أردأ منه، لكن إذا عرف الإنسان ماهيته يرتاح. أي أن الإنسان الجديد يبدأ بمعرفة أن الفتور طبيعي في البدايات. لا تيأس من ثقل أول الطريق.\",\"p\":\"يا رب، أعطني نشاطًا في كل بداية، وصبرًا على ثقل أول الطريق. جدّد فيّ الحماس والمثابرة. آمين.\",\"fq\":424}]},\"4-28\":{\"th\":\"العبادة الجماعية\",\"m\":[{\"t\":\"فرحت بالقائلين لي إلى بيت الرب نذهب\",\"ref\":\"المزمور ١٢١ (١٢٢) — الغروب\",\"v\":\"فرحت بالقائلين لي إلى بيت الرب نذهب. وقفت أرجلنا في ديار أورشليم: أورشليم المبنية مثل مدينة متصلة بعضها ببعض. لأن هناك صعدت القبائل؛ قبائل الرب، شهادة لإسرائيل؛ يعترفون لاسم الرب.\",\"r\":\"فرح المرنم حين دعاه الآخرون إلى بيت الرب، فالعبادة الجماعية تزرع الفرح حين نذهب معًا. وقفت الأرجل في ديار أورشليم المتصلة بعضها ببعض. من يمكنك أن تدعوه اليوم أو هذا الأسبوع ليذهب معك إلى الكنيسة؟\",\"p\":\"فرحت بالقائلين لي إلى بيت الرب نذهب. اجعل عبادتي مع إخوتي فرحًا وشركة، وبارك اجتماعنا باسمك. آمين.\"},{\"t\":\"ادخلوا أبوابه بحمد\",\"ref\":\"المزامير ١٠٠: ٤\",\"bk\":\"المزامير\",\"v\":\"ادخلوا أبوابه بحمد، دياره بالتسبيح. احمدوه، باركوا اسمه.\",\"r\":\"«ادخلوا أبوابه بحمد، دياره بالتسبيح، احمدوه باركوا اسمه». هذا هو أسلوب الدخول إلى الكنيسة والصلاة: بحمد لا بشكوى. وإن جئت متعبًا فأبدأ بالشكر، فهو يرفع القلب. والتسبيح يغيّر الجو الداخلي ويفتح للحضور الإلهي.\",\"p\":\"يا رب، أدخل أبوابك بحمد ودارك بتسبيح. أشكرك وأبارك اسمك، فأنت صالح وإلى الأبد رحمتك، وأعطني أن أعبدك بفرح مع الجماعة. آمين.\"},{\"t\":\"ماذا كان في فكرك؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب بيمن من لم ينتفع بزيارة أخ أن يفتش في فكره عما كان فيه قبل دخوله، فيدرك سبب عدم انتفاعه. في اجتماع الكنيسة اليوم، افحص قلبك قبل أن تدخل: أي فكر تحمله معك؟\",\"p\":\"يا رب، طهّر فكري قبل أن أدخل بيتك. وأعطني أن أنتفع بكل اجتماع وأحتمل عيوب إخوتي بتواضع. آمين.\",\"fq\":444}]},\"4-29\":{\"th\":\"السكون والهدوء\",\"m\":[{\"t\":\"ثابروا واعلموا أني أنا الله\",\"ref\":\"المزمور ٤٥ (٤٦) — الثالثة\",\"v\":\"ثابروا واعلموا أنى أنا هو الله، أرتفع بين الأمم وأتعالى في الأرض.\",\"r\":\"في وسط الحروب والضجيج يقول الله: ثابروا واعلموا أني أنا هو الله. السكون ليس غياب النشاط بل معرفة من هو الله. اجلس اليوم دقيقتين في صمت واحد بلا طلب، وقل فقط: أنت الله.\",\"p\":\"يا رب، أنت الله، ترتفع بين الأمم وتتعالى في الأرض. علّمني أن أسكن في حضرتك وأعلم أنك أنت الله. آمين.\"},{\"t\":\"بالرجوع والسكون تخلصون\",\"ref\":\"إشعياء ٣٠: ١٥\",\"bk\":\"إشعياء\",\"v\":\"لأنه هكذا قال السيد الرب قدوس إسرائيل: «بالرجوع والسكون تخلصون. بالهدوء والطمأنينة تكون قوتكم». فلم تشاءوا.\",\"r\":\"«بالرجوع والسكون تخلصون، بالهدو والطمأنينة تكون قوتكم». معادلة غريبة على العالم: القوة في السكون. لكنها حقيقة روحية: من يرجع إلى الله ويهدأ يجد قوة. لكن الشعب «لم يشاءوا» وأرادوا الاعتماد على الخيل والسرعة. وأنا أتأمل: على ماذا أتكل؟\",\"p\":\"يا رب، أرجع إليك وأسكن في حضورك. علّمني أن قوتي في الهدوء والاتكال عليك، لا في السرعة والحلول البشرية. ورأف بي في انتظارك. آمين.\"},{\"t\":\"ما هي السكينة؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعرّف الأب روفو السكينة بأنها أن يقيم المرء بمعرفة الله وخوفه، مبتعدًا عن الإساءة والعجب، وتولد منها كل الفضائل. ليس السكون غياب الضجة بل حضور الله. ابحث اليوم عن مكان هادئ ولو قليلًا.\",\"p\":\"يا رب، علّمني السكينة التي بمعرفتك وخوفك. أبعد عني الإساءة والعجب، وأنبت فيّ فضائلك. آمين.\",\"fq\":481}]},\"4-30\":{\"th\":\"أمانة الله\",\"m\":[{\"t\":\"كلام الرب كلام نقي\",\"ref\":\"المزمور الحادي عشر — باكر\",\"v\":\"كلام الرب كلام نقي، فضة محماة مجربة في الأرض، قد صفيت سبعة أضعاف. وأنت يا رب تنجينا وتحفظنا من هذا الجيل وإلى الدهر.\",\"r\":\"بعد زمن قلّ فيه الأمين، يشهد المرنم أن كلام الرب كلام نقي، فضة محماة مصفاة سبعة أضعاف. الله أمين في كلامه ووعده. وأنت يا رب تنجينا وتحفظنا. تأمل اليوم أي وعد من الله مرّت عليه تجربة ثم ثبت.\",\"p\":\"كلامك يا رب نقي كالفضة المصفاة سبع مرات، وأنت أمين. أنت تنجينا وتحفظنا من هذا الجيل وإلى الدهر. آمين.\"},{\"t\":\"الإله الأمين\",\"ref\":\"التثنية ٧: ٩\",\"bk\":\"التثنية\",\"v\":\"فاعلم أن الرب إلهك هو الله، الإله الأمين، الحافظ العهد والإحسان للذين يحبونه ويحفظون وصاياه إلى ألف جيل،\",\"r\":\"«فاعلم أن الرب إلهك هو الله، الإله الأمين الحافظ العهد والإحسان للذين يحبونه ويحفظون وصاياه إلى ألف جيل». الله يحفظ عهده عبر ألف جيل. وأنا ثمرة أمانته لأجدادي. وقد أكون أنا أيضًا سببًا في بركة لأجيال بعدي بأمانتي له.\",\"p\":\"يا رب، أنت الإله الأمين الحافظ العهد والإحسان. أشكرك على أمانتك عبر الأجيال، واجعلني حلقة أمينة في سلسلة الإيمان لمن بعدي. آمين.\"},{\"t\":\"يدبّرني الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب فورتا: إذا أرادني الله أن أعيش هو يعرف تمامًا كيف يدبّرني، وإذا لم يرد ذلك فما حاجتي إلى هذه الحياة؟ كلمات أمانة وتسليم. اختم الشهر بهذا اليقين: الله الذي يدبّرني أمين.\",\"p\":\"يا رب، أنت أمين في تدبيرك لحياتي. أسلّم لك أيامي كلها، وأعرف أنك لن تتركني. آمين.\",\"fq\":557}]},\"5-1\":{\"th\":\"كرامة العمل\",\"m\":[{\"t\":\"من قوة إلى قوة\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"لأن البركات يعطيها واضع الناموس. يسيرون من قوة إلى قوة، يتجلى إله الآلهة في صهيون.\",\"r\":\"يرى المرنم الحياة مع الله سيرًا من قوة إلى قوة، وكل خطوة فيها بركة من واضع الناموس. العمل جزء من هذا الطريق وليس عائقًا له. اعمل اليوم أول مهمة بتركيز كامل كأنك تؤديها لله نفسه، وستجد أنها تصير صلاة.\",\"p\":\"يا رب، أعطني أن أسير في عملي من قوة إلى قوة. بارك جهدي، واجعل كرامة العمل تذكّرني أنك خلقتني للعمل معك. آمين.\"},{\"t\":\"من لا يعمل لا يأكل\",\"ref\":\"تسالونيكي الثانية ٣: ١٠–١٢\",\"bk\":\"تسالونيكي الثانية\",\"v\":\"فإننا أيضا حين كنا عندكم، أوصيناكم بهذا: «أنه إن كان أحد لا يريد أن يشتغل فلا يأكل أيضا». لأننا نسمع أن قوما يسلكون بينكم بلا ترتيب، لا يشتغلون شيئا بل هم فضوليون. فمثل هؤلاء نوصيهم ونعظهم بربنا يسوع المسيح أن يشتغلوا بهدوء، ويأكلوا خبز أنفسهم.\",\"r\":\"«إن كان أحد لا يريد أن يشتغل فلا يأكل أيضًا». عبارة حازمة موجهة للمتكاسلين المتطفلين على غيرهم. وبولس نفسه عمل بيديه ليكون قدوة. والعمل يحفظ كرامتي ويجعلني قادرًا على العطاء. وفيه انضباط يحميني من التسيب والثرثرة.\",\"p\":\"يا رب، أعطني نشاطًا وأمانة في عملي. احفظني من الكسل والتطفل، وعلّمني أن أعمل بهدوء وأكسب خبزي وأعطي من تعبي لمن يحتاج. آمين.\"},{\"t\":\"لا تتخلَّ عن عمل اليد\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب بيستامون لأخ مؤمّنة حاجاته: مهما كان لديك لا تتخلَّ عن عمل اليد، اعمل ما في وسعك دونما اضطراب. العمل كرامة حتى عندما لا نحتاج إليه للمعيشة. اعمل اليوم بيديك شيئًا ملموسًا ولو صغيرًا.\",\"p\":\"يا رب، علّمني كرامة العمل وبهجة اليد التي تعمل. وأعطني أن أعمل بما في وسعي دون اضطراب. آمين.\",\"fq\":471}]},\"5-2\":{\"th\":\"طاعة الرعاة\",\"m\":[{\"t\":\"كانوا يدعون الرب فيستجيب\",\"ref\":\"المزمور ٩٨ (٩٩) — التاسعة\",\"v\":\"موسى وهرون بين كهنته وصموئيل بين الذين يدعون باسمه. كانوا يدعون الرب فيستجيب لهم، بعمود الغمام كان يكلمهم.\",\"r\":\"يذكر المرنم موسى وهرون وصموئيل، كهنة وأنبياء كان الله يكلمهم ويستجيب لهم. الرعاة ليسوا فوق الجماعة بل في خدمتها ويحملون صلاتها. صلِّ اليوم بالاسم من أجل راعيك أو أب اعترافك، واطلب له قوة وحكمة.\",\"p\":\"يا رب، احفظ رعاة كنيستك وأعطهم حكمة وقوة. استجب لهم كما استجبت لموسى وهرون وصموئيل، وعلّمنا أن نصلي من أجلهم ونطيعهم بمحبة. آمين.\"},{\"t\":\"اعرفوا الذين يتعبون\",\"ref\":\"تسالونيكي الأولى ٥: ١٢–١٣\",\"bk\":\"تسالونيكي الأولى\",\"v\":\"ثم نسألكم أيها الإخوة أن تعرفوا الذين يتعبون بينكم ويدبرونكم في الرب وينذرونكم، وأن تعتبروهم كثيرا جدا في المحبة من أجل عملهم. سالموا بعضكم بعضا.\",\"r\":\"«ثم نسألكم أيها الإخوة أن تعرفوا الذين يتعبون بينكم ويدبرونكم في الرب وينذرونكم». كلمة «يتعبون» تذكّرني بأن الخدمة تعب. وقد لا أرى ما وراء الكواليس. وكل خادم يحتاج أن أُعرّفه وأشجعه، وأن أعتبره «كثيرًا جدًا في المحبة».\",\"p\":\"يا رب، بارك الذين يتعبون في خدمتنا. علّمني أن أقدّرهم بالمحبة، وأن أشاركهم في رعاية إخوتي بالتشجيع والإسناد والصبر. آمين.\"},{\"t\":\"ألا نستعبد لرأينا\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي إن علينا في الشركة أن نسوس أنفسنا بالتمييز، فلا نطلب ما هو لنا ولا نستعبد لرأينا. طاعة الرعاة حرية من أنانية الرأي. في قرار واحد اليوم، اسمع للمشورة قبل أن تتمسك برأيك.\",\"p\":\"يا رب، أعطني روح التمييز والطاعة. حرّرني من التمسك الأعمى برأيي، واجعلني أنصت إلى من وضعتهم رعاة لي. آمين.\",\"fq\":543}]},\"5-3\":{\"th\":\"فرح الخدمة\",\"m\":[{\"t\":\"يعودون بالفرح\",\"ref\":\"المزمور ١٢٥ (١٢٦) — الغروب\",\"v\":\"الذين يزرعون بالدموع يحصدون بالابتهاج. سيرا كانوا يسيرون وهم باكون حاملين بذارهم: ويعودون بالفرح حاملين أغمارهم هلليلويا.\",\"r\":\"صورة الزارع الباكي الذي يعود حاملًا أغماره بفرح هي صورة الخدمة: تعب البذار ثم فرح الحصاد. الخدمة بذار لا يرى ثمره دائمًا في يوم زرعه. اخدم اليوم في أمر صغير دون أن تنتظر نتيجة فورية، وثق في موسم الحصاد.\",\"p\":\"يا رب، الذين يزرعون بالدموع يحصدون بالابتهاج. قوّني في بذار الخدمة، وأعطني أن أعود بالفرح حاملًا أغمارًا لك. آمين.\"},{\"t\":\"طعامي أن أعمل مشيئة الذي أرسلني\",\"ref\":\"يوحنا ٤: ٣٤\",\"bk\":\"يوحنا\",\"v\":\"قال لهم يسوع: «طعامي أن أعمل مشيئة الذي أرسلني وأتمم عمله.\",\"r\":\"«طعامي أن أعمل مشيئة الذي أرسلني وأتمم عمله». كان المسيح متعبًا وجائعًا، لكنه شبع بلقاء السامرية. فالخدمة حين تتم بحسب مشيئة الآب تعطي شبعًا داخليًا. وأنا أحتاج أن أتعلم هذا: أن أجد الشبع في طاعة الله لا في إنجازاتي.\",\"p\":\"يا رب يسوع، علّمني أن يكون طعامي مشيئة الآب. أشبعني بطاعتك وخدمتك، وافتح عيني على الحقول المبيضة، واجعلني عاملًا فرحًا في حصادك. آمين.\"},{\"t\":\"خدمة بفكر طاهر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يصف الأب بيمن ثلاثة معًا: أحدهم يحيا السكينة، والثاني يمرض ويشكر، والثالث يخدم بفكر طاهر، والثلاثة يقومون بالعمل نفسه. فرح الخدمة أن أراها عملًا مقدسًا. اخدم اليوم بفكر نقي بعيدًا عن المقارنة.\",\"p\":\"يا رب، اجعل خدمتي بفكر طاهر وقلب فرح. علّمني أن أقدر عمل كل أخ، وأن أراك في كل خدمة. آمين.\",\"fq\":329}]},\"5-4\":{\"th\":\"طلب المشورة\",\"m\":[{\"t\":\"أظهر لي طرقك\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"أظهر لي يا رب طرقك؛ وعلمني سبلك. اهدني إلى عدلك وعلمني.\",\"r\":\"يطلب المرنم تعليمًا واهتداءً: أظهر لي طرقك، علّمني سبلك، اهدني إلى عدلك. وهو يعلم أن الطريق لا يُعرف بالتخمين. فلا تتردد في سؤال من هو أخبر منك، ولكن ابدأ بالسؤال الأول: ما مشيئتك يا رب في هذا الأمر؟\",\"p\":\"أظهر لي يا رب طرقك وعلّمني سبلك. اهدني إلى عدلك وعلّمني، وضع في طريقي من ينصحني بحكمة. آمين.\"},{\"t\":\"اسمع المشورة\",\"ref\":\"الأمثال ١٩: ٢٠\",\"bk\":\"الأمثال\",\"v\":\"اسمع المشورة واقبل التأديب، لكي تكون حكيما في آخرتك.\",\"r\":\"«اسمع المشورة واقبل التأديب لكي تكون حكيمًا في آخرتك». الحكمة تنمو بالاستماع. والتأديب جزء من تعليمي. وكثيرًا ما ننفر منه لأنه يؤلم الكبرياء، لكنه يحمي مستقبلنا. فالسماع الحكيم استثمار في المستقبل.\",\"p\":\"يا رب، علّمني أن أسمع المشورة وأقبل التأديب بتواضع. اجعلني أنمو في الحكمة كل يوم، وأشكر كل من أرشدني بمحبة. آمين.\"},{\"t\":\"أن أبني بيتي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن تعليم الإنسان لقريبه من شأن الصُّم والعديمي الأهواء، وإلا فما قيمته إذا بنى بيت قريبه وهدم بيته؟ طلب المشورة يحميني من التسرع في إرشاد غيري قبل نفسي. اسأل اليوم من يكبرك خبرة عن أمر يهمّك.\",\"p\":\"يا رب، علّمني أن أبني بيتي أولًا وأطلب المشورة بتواضع. احفظني من التسرع في تعليم غيري قبل أن أتعلم. آمين.\",\"fq\":405}]},\"5-5\":{\"th\":\"الكنز الحقيقي\",\"m\":[{\"t\":\"ميراث لخائفي اسمك\",\"ref\":\"المزمور ٦٠ (٦١) — السادسة\",\"v\":\"أعطيت ميراثا لخائفي اسمك.\",\"r\":\"الكنز الحقيقي في كلمات المرنم عطية من الله لمن يخافونه: «أعطيت ميراثًا لخائفي اسمك». هذا ما لا يسرقه سارق ولا يفسده سوس. اسأل قلبك اليوم عن الكنز الذي تنشغل به أكثر: هل هو الباقي أم الزائل؟\",\"p\":\"أعطيتَ يا رب ميراثًا لخائفي اسمك. اجعل مخافتك كنزي الأعظم، وعلّمني أن أدخر في السماء ما لا يفنى. آمين.\"},{\"t\":\"اكنزوا لأنفسكم كنزًا\",\"ref\":\"لوقا ١٢: ٣٣\",\"bk\":\"لوقا\",\"v\":\"بيعوا ما لكم وأعطوا صدقة. اعملوا لكم أكياسا لا تفنى وكنزا لا ينفد في السماوات، حيث لا يقرب سارق ولا يبلي سوس،\",\"r\":\"«بيعوا ما لكم وأعطوا صدقة. اعملوا لكم أكياسًا لا تفنى وكنزًا لا ينفد في السماوات». المسيح يعلمني أن ما أعطيه يبقى، وما أحتفظ به يزول. والأكياس التي لا تبلى هي أعمال الرحمة. وهذه رؤية مختلفة للغنى: غنى العطاء.\",\"p\":\"يا رب، علّمني أن أكنز في السماء. حرر قلبي من التعلق بما يبلى، وأعطني أن أعطي بسخاء وفرح من واقع ثقتي بأنك تعطيني الملكوت. آمين.\"},{\"t\":\"فاكنز في السماء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب إيبريخيوس بأن كنز الراهب هو عدم القنية الطوعي، ويقول: فاكنز يا أخي في السماء لأن أزمنة الراحة لا تنتهي. الكنز الحقيقي يُدّخر بالتخلي لا بالجمع. ما الذي يمكنك أن تعطيه اليوم فتدخره عند الله؟\",\"p\":\"يا رب، أنا أريد كنزي عندك. حرّرني من التعلق بما يزول، وأعطني فرح من لا يملك شيئًا وهو يملك كل شيء بك. آمين.\",\"fq\":553}]},\"5-6\":{\"th\":\"فقر الروح\",\"m\":[{\"t\":\"لأني ابن وحيد وفقير\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"انظر إلى وارحمني، لأني ابن وحيد وفقير أنا. أحزان قلبي قد كثرت، أخرجني من شدائدي.\",\"r\":\"يقدم المرنم نفسه إلى الله مسكينًا: فقيرًا وحيدًا كثرت أحزان قلبه. فقر الروح ليس ضعف الشخصية بل صدق الوقوف أمام الله بلا ادعاء. اجلس اليوم أمامه في صلاة قصيرة وقل: يا رب أنا فقير إليك.\",\"p\":\"انظر إليّ وارحمني يا رب لأني وحيد وفقير. أخرجني من شدائدي، واملأ فقري من غناك. آمين.\"},{\"t\":\"يرفع المتواضع\",\"ref\":\"لوقا ١٨: ١٤\",\"bk\":\"لوقا\",\"v\":\"أقول لكم: إن هذا نزل إلى بيته مبررا دون ذاك، لأن كل من يرفع نفسه يتضع، ومن يضع نفسه يرتفع».\",\"r\":\"«كل من يرفع نفسه يتضع ومن يضع نفسه يرتفع». الفريسي صلّى بغرور فخرج غير مبرر، والعشار صلّى بانسحاق فخرج مبررًا. وهذا يعلمني أن شكل الصلاة لا يكفي، بل قلبها. والاتضاع يفتح باب النعمة.\",\"p\":\"يا رب، ارحمني أنا الخاطئ. احفظني من غرور الفريسي، وعلّمني اتضاع العشار، وأعطني أن أنزل لأرتفع بنعمتك. آمين.\"},{\"t\":\"«هنيئًا للمساكين بالروح»\",\"ref\":\"\",\"v\":\"\",\"r\":\"يرى الأب يوحنا رجل القلالي أن الراهب يجب قبل كل شيء أن يكون متواضعًا، لأن هذه هي وصية السيد الأولى: هنيئًا للمساكين بالروح لأن لهم ملكوت السماوات. فقر الروح باب الملكوت. بأي أمر تحتاج أن تتواضع اليوم؟\",\"p\":\"يا رب، اجعلني مسكينًا بالروح لأرث ملكوتك. انزع الكبرياء من قلبي، وأعطني تواضع المحتاج إليك. آمين.\",\"fq\":196}]},\"5-7\":{\"th\":\"تعزية الحزانى\",\"m\":[{\"t\":\"أعنتني وعزيتني\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"اصنع معي آية صالحة؛: ليرى ذلك مبغضي فيخزوا. لأنك أنت يا رب أعنتني وعزيتني.\",\"r\":\"يختم المرنم طلبه بشهادة: «أنت يا رب أعنتني وعزيتني». التعزية في الحزن ليست نسيانًا بل حضور. من يحزن يجد الله قريبًا، ومن يعزّي يشاركه في عمل الله. اتصل اليوم بشخص حزين وكن معه بلا كثرة كلام.\",\"p\":\"أنت يا رب أعنتني وعزيتني. اصنع معي آية صالحة، وعزِّ الحزانى الذين أعرفهم، وكن أنت سلامهم وتعزيتهم. آمين.\"},{\"t\":\"الحزن حسب مشيئة الله\",\"ref\":\"كورنثوس الثانية ٧: ١٠\",\"bk\":\"كورنثوس الثانية\",\"v\":\"لأن الحزن الذي بحسب مشيئة الله ينشئ توبة لخلاص بلا ندامة، وأما حزن العالم فينشئ موتا.\",\"r\":\"«لأن الحزن الذي بحسب مشيئة الله ينشئ توبة لخلاص بلا ندامة، وأما حزن العالم فينشئ موتًا». هناك حزن يكسرني وهناك حزن يرفعني. الأول يقودني إلى الله، والثاني إلى اليأس. وأنا أحتاج أن أفحص حزني: هل يدفعني إلى التوبة والأمل أم إلى الاستسلام؟\",\"p\":\"يا رب، حوّل حزني إلى توبة وخلاص. احفظني من حزن العالم الذي يميت، وأعطني الحزن الذي بحسب مشيئتك فيثمر حياة وفرحًا. آمين.\"},{\"t\":\"كن دون الجميع\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب ماتوى أخًا طلب كلمة: اذهب وتضرع إلى الرب أن يجعل في قلبك الحزن والتواضع، وانتبه لخطاياك دائمًا ولا تدن أحدًا. هذا الحزن الصحي يقود إلى تعزية. لا تهرب اليوم من حزن يعلّمك التواضع.\",\"p\":\"يا رب، اجعل فيّ حزنًا بحسب مشيئتك يقودني إلى التوبة والتعزية. وكن أنت عزائي في كل حزن. آمين.\",\"fq\":276}]},\"5-8\":{\"th\":\"صانعو السلام\",\"m\":[{\"t\":\"الرحمة والحق تلاقيا\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"الرحمة والحق تلاقيا، البر والسلام تلاثما. الحق من الأرض أشرق.\",\"r\":\"يصف المرنم لقاء ما لا يلتقي عادة: الرحمة مع الحق، والبر مع السلام. صانع السلام هو من يجمع الاثنين، فلا يتنازل عن الحق ولا يترك الرحمة. في خلاف يخصّك اليوم، فكّر كيف تجمع الصدق واللطف معًا.\",\"p\":\"يا رب، لتتلاقَ الرحمة والحق في قلبي، وليتعانق البر والسلام. اجعلني صانع سلام في بيتي وكنيستي وعملي. آمين.\"},{\"t\":\"ثمر البر يُزرع في السلام\",\"ref\":\"يعقوب ٣: ١٧–١٨\",\"bk\":\"يعقوب\",\"v\":\"وأما الحكمة التي من فوق فهي أولا طاهرة، ثم مسالمة، مترفقة، مذعنة، مملوة رحمة وأثمارا صالحة، عديمة الريب والرياء. وثمر البر يزرع في السلام من الذين يفعلون السلام.\",\"r\":\"«أما الحكمة التي من فوق فهي أولًا طاهرة ثم مسالمة مترفقة مذعنة مملوءة رحمة وأثمارًا صالحة». هذه قائمة صفات الحكمة السماوية، وأولها الطهارة. فلا سلام حقيقي بدون نقاء. وعندما أعيش بهذه الصفات، ثمر البر ينمو في بيئتي.\",\"p\":\"يا رب، أعطني الحكمة التي من فوق: طاهرة مسالمة مترفقة مملوءة رحمة. ازرع في حياتي وبيتي ثمر البر بالسلام الذي تصنعه بنا. آمين.\"},{\"t\":\"أظهر توبتك أمام أخيك\",\"ref\":\"\",\"v\":\"\",\"r\":\"عندما سأل أحدهم الأب بيمن عمن حزن بسببه، أرشده أن يأخذ معه اثنين ثم خمسة ثم كاهنًا ليُظهر توبته، فإذا لم يقتنع صلّى إلى الله بلا انزعاج. صنع السلام يتطلب تواضعًا وسعيًا. من لك عنده شيء؟ ابدأ بالسعي.\",\"p\":\"يا رب، اجعلني أسعى إلى المصالحة بتواضع وصبر. وإن لم يقتنع الآخر، علّمني أن أصلي وأتركه لك بلا همّ. آمين.\",\"fq\":429}]},\"5-9\":{\"th\":\"الاضطهاد من أجل البر\",\"m\":[{\"t\":\"لم يقدروا عليّ\",\"ref\":\"المزمور ١٢٨ (١٢٩) — الغروب\",\"v\":\"مرارا كثيرة حاربوني منذ صباي - ليقل إسرائيل مرارا كثيرة قاتلوني منذ شبابي، وإنهم لم يقدروا علي. على ظهري جلدني الخطاة وأطالوا إثمهم.\",\"r\":\"يتذكر المرنم محاربة الأعداء منذ الصبا وجلدهم ظهره، ومع ذلك يعلن: لم يقدروا عليّ. الاضطهاد من أجل البر يجرح لكنه لا يهزم. إن عانيت اليوم من سخرية أو ضغط بسبب إيمانك، فتذكّر أن الله لا ينسى وأن ثباتك شهادة.\",\"p\":\"مرارًا كثيرة حاربوني منذ صباي، لكنهم لم يقدروا عليّ لأنك معي. قوّني في الاضطهاد، واحفظ فرحي وسلامي. آمين.\"},{\"t\":\"إن تألمتم من أجل البر\",\"ref\":\"بطرس الأولى ٣: ١٤\",\"bk\":\"بطرس الأولى\",\"v\":\"ولكن وإن تألمتم من أجل البر، فطوباكم. وأما خوفهم فلا تخافوه ولا تضطربوا،\",\"r\":\"«ولكن وإن تألمتم من أجل البر فطوباكم، وأما خوفهم فلا تخافوه ولا تضطربوا». الخوف هو أول سلاح المضطهد. وبطرس يقول: لا تخف من خوفهم. فالثبات يبدأ بالقلب. ثم يوصي: «قدسوا الرب الإله في قلوبكم». أي اجعلوا الله هو الأول.\",\"p\":\"يا رب، قدّسك في قلبي. اجعلني مستعدًا أن أجاوب عن رجائي بوداعة وخوف، وأثبت بضمير صالح، ولا أخاف من خوف أحد. آمين.\"},{\"t\":\"الشتم يروي الشجرة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أشعيا إنه لا شيء ينفع المبتدئ كالشتم والإهانة، فكما أن الشجرة ترتوي كل يوم هكذا المبتدئ الذي يُشتم فيحتمل. الاضطهاد قد يصير ماءً يرويني. كيف تقابل إهانة اليوم؟ جرّب الاحتمال بسلام.\",\"p\":\"يا رب، علّمني أن أحتمل الإهانة بفرح كمن يشرب ماءً يرويه. ولا تدعني أرد الشر بشر. آمين.\",\"fq\":120}]},\"5-10\":{\"th\":\"ملح الأرض\",\"m\":[{\"t\":\"أنتم ملح الأرض\",\"ref\":\"إنجيل السادسة\",\"v\":\"أنتم ملح الأرض، فإذا فسد الملح فبماذا يملح؟ ... أنتم نور العالم. ... هكذا فليضئ نوركم قدام الناس لكي يروا أعمالكم الصالحة فيمجدوا أباكم الذي في السموات.\",\"r\":\"الملح لا يُرى لكنه يعطي الطعم، ولا يظهر في الوجبة لكن غيابه يُلاحَظ فورًا. هذا هو تأثير المؤمن في بيته وعمله. لا يحتاج أن يتكلم كثيرًا، بل أن يحافظ على طعمه. ما الذي يعطي حياتك طعم المسيح اليوم؟\",\"p\":\"يا رب، اجعلني ملحًا يحفظ ولا يفسد، ونورًا يضيء لمن حولي. ليرى الناس أعمالي الصالحة فيمجدوك أبانا الذي في السماوات. آمين.\"},{\"t\":\"كلامكم كل حين بنعمة\",\"ref\":\"كولوسي ٤: ٦\",\"bk\":\"كولوسي\",\"v\":\"ليكن كلامكم كل حين بنعمة، مصلحا بملح، لتعلموا كيف يجب أن تجاوبوا كل واحد.\",\"r\":\"«ليكن كلامكم كل حين بنعمة مصلحًا بملح لتعلموا كيف يجب أن تجاوبوا كل واحد». كلام النعمة لطيف ومملوء بالقبول. والملح هو الحكمة التي تحفظ من الفساد. فأتعلم أن أتكلم بلطف دون مجاملة كاذبة، وبصدق دون جرح.\",\"p\":\"يا رب، ليكن كلامي كل حين بنعمة مصلحًا بملح. علّمني متى أتكلم ومتى أصمت، وكيف أجاوب كل واحد بحكمة ولطف وصدق. آمين.\"},{\"t\":\"الملح والمحبة بلا رياء\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينبه الأب أور ألا نقول في قلوبنا نحو أخينا: أنا أكثر نسكًا منه، بل نطيع نعمة المسيح بروح الفقر والمحبة التي لا رياء فيها. الملح الذي يحفظ هو الاتضاع الصادق. اختبر اليوم نيتك قبل كل عمل مفيد.\",\"p\":\"يا رب، احفظ فيّ ملح التواضع. لا تدعني أفتخر بنسكي، بل أطع نعمتك بمحبة بلا رياء. آمين.\",\"fq\":564}]},\"5-11\":{\"th\":\"كمال المحبة\",\"m\":[{\"t\":\"رحمة ونقاء وسلام\",\"ref\":\"إنجيل السادسة\",\"v\":\"طوبى للرحماء لأنهم يرحمون. طوبى لأنقياء القلب لأنهم يعاينون الله. طوبى لصانعي السلام، لأنهم يدعون أبناء الله.\",\"r\":\"يضع الرب أمامنا ثلاث علامات للمحبة الكاملة: رحمة تعطي، وقلب نقي يرى الله، وسلام يصالح. كمال المحبة أن تتكامل هذه الثلاث فيّ. أي واحدة منها أحتاج أن أنمّيها اليوم؟ اختر واحدة وصلِّ لأجل نموها.\",\"p\":\"يا رب، اجعلني رحيمًا ونقي القلب وصانع سلام. وأتمم فيّ محبتك الكاملة لأكون ابنًا لك في كل شيء. آمين.\"},{\"t\":\"كونوا كاملين\",\"ref\":\"متى ٥: ٤٨\",\"bk\":\"متى\",\"v\":\"فكونوا أنتم كاملين كما أن أباكم الذي في السماوات هو كامل.\",\"r\":\"«فكونوا أنتم كاملين كما أن أباكم الذي في السماوات هو كامل». الكمال هنا في سياق المحبة: أن أحب الجميع كما يحب الله، فهو يشرق شمسه على الأشرار والصالحين. وليس مطلوبًا ألا أخطئ أبدًا، بل أن أنمو باستمرار في هذه المحبة.\",\"p\":\"أبانا السماوي، أنت كامل في محبتك. علّمني أن أنمو في الكمال بنعمتك، وأحب كما تحب، وأسامح كما تسامح، حتى أشبهك. آمين.\"},{\"t\":\"المحبة الكاملة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال القديس أغاثون: «لو كان ممكنًا أن أجد أبرص أعطيه جسدي وآخذ جسده لكنت سعيدًا، لأن هذه هي المحبة الكاملة». عبارة تهز القلب: المحبة التي تقبل أن تحمل ثقل الآخر. ما الثقل الذي يمكنك أن تحمله عن أحد اليوم؟\",\"p\":\"يا رب، اجعل محبتي كاملة تقبل أن تتحمل عن الآخر. علّمني أن أحب كما أحببتني، حتى الصليب. آمين.\",\"fq\":58}]},\"5-12\":{\"th\":\"نعم نعم لا لا\",\"m\":[{\"t\":\"نجِّ نفسي من اللسان الغاش\",\"ref\":\"المزمور ١١٩ (١٢٠) — الغروب\",\"v\":\"يا رب نج نفسي من الشفاه الظالمة ومن اللسان الغاش. ماذا تعطى وماذا تزاد من اللسان الغاش.\",\"r\":\"يصلي المرنم أن ينجيه الله من الشفاه الظالمة ومن اللسان الغاش، ويسأل ماذا ينتفع صاحبه منه. الصدق في القول يبدأ من طلب النجاة من غش الكلمة. قبل أن تعد بشيء اليوم، تأكد أنك ستفي، وإلا فقل بصراحة: لا.\",\"p\":\"يا رب، نجِّ نفسي من الشفاه الظالمة ومن اللسان الغاش. علّمني أن يكون كلامي نعم نعم ولا لا، وأن أفي بوعودي. آمين.\"},{\"t\":\"ليكن كلامكم نعم نعم\",\"ref\":\"متى ٥: ٣٧\",\"bk\":\"متى\",\"v\":\"بل ليكن كلامكم: نعم نعم، لا لا. وما زاد على ذلك فهو من الشرير.\",\"r\":\"«ليكن كلامكم نعم نعم لا لا، وما زاد على ذلك فهو من الشرير». يريد المسيح لسانًا موثوقًا: إذا قلت نعم فهي نعم، وإذا قلت لا فهي لا. فلا أحتاج إلى حلف أو إقناع. والمصداقية تُبنى بالأمانة اليومية في الصغائر.\",\"p\":\"يا رب، اجعل كلامي صادقًا موثوقًا. علّمني ألا أعد بما لا أقدر، وأن أحفظ كلمتي في الصغير والكبير، ولتكن نعم نعم ولا لا. آمين.\"},{\"t\":\"باب اللسان\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل أخ الأب بيمن عن خوفه ألا يفتح له الباب، فقال: نحن لا نعرف أن نغلق الباب الخشبي لكن باب اللسان. لا نتعب في حفظ أبواب البيت وننسى فمنا. ما الكلمة التي تحتاج أن تغلق بابها اليوم؟\",\"p\":\"يا رب، أغلق باب لساني عن كل كلمة لا تنفع. وأعطني حكمة أن أتكلم بالحق وفي وقته. آمين.\",\"fq\":356}]},\"5-13\":{\"th\":\"لا تقلقوا\",\"m\":[{\"t\":\"يعطي فراخ الغربان طعامها\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"الذي يجلل السماء بالغمام، الذي يهيئ للأرض المطر، الذي ينبت العشب على الجبال والخضرة لخدمة البشر، ويعطي البهائم طعامها، ولفراخ الغربان التي تدعوه.\",\"r\":\"يذكّرنا المرنم بإله يدبر المطر والعشب وطعام فراخ الغربان. من يعتني بكل هذا لا ينسى أبناءه. لهذا قال الرب: لا تقلقوا. اكتب اليوم ثلاثة أشياء تقلق منها وضعها أمام الله، ثم اعمل ما عليك واترك الباقي.\",\"p\":\"أيها الرب الذي يعطي البهائم طعامها ولفراخ الغربان التي تدعوه، اعتن بي. خذ قلقي واعطني ثقة بتدبيرك. آمين.\"},{\"t\":\"لا تهتموا للغد\",\"ref\":\"متى ٦: ٣٤\",\"bk\":\"متى\",\"v\":\"فلا تهتموا للغد، لأن الغد يهتم بما لنفسه. يكفي اليوم شره.\",\"r\":\"«فلا تهتموا للغد لأن الغد يهتم بما لنفسه. يكفي اليوم شره». لا أحمل غدًا بجانب اليوم، فهو حمل زائد. والله يعطيني نعمة لليوم، وسيعطيني نعمة للغد حين يأتي. وهذا يحررني من الاحتراق بالتفكير في ما لم يحدث.\",\"p\":\"يا رب، أعطني نعمة اليوم. حرّرني من حمل الغد قبل أوانه، وعلّمني أن أعيش لحظتي بأمانة، وأثق بك في كل ما هو آتٍ. آمين.\"},{\"t\":\"إذا قام الإنسان بواجباته\",\"ref\":\"\",\"v\":\"\",\"r\":\"عبارة الأب بيمن قصيرة وحاسمة: «إذا قام الإنسان بواجباته لا يضطرب». القلق كثيرًا ما يأتي من تأجيل ما علينا، والسلام يأتي مع الأمانة في الواجب. ما الواجب الذي تؤجله وهو سبب جزء من قلقك؟ ابدأ به اليوم.\",\"p\":\"يا رب، أعطني أن أقوم بواجباتي بأمانة فأرتاح من القلق. وليكن اهتمامي الأول ملكوتك وبرك. آمين.\",\"fq\":438}]},\"5-14\":{\"th\":\"لا تدينوا\",\"m\":[{\"t\":\"ليس رحمة في الدينونة\",\"ref\":\"قطعة الخدمة الثالثة (٢) — نصف الليل — الخدمة الثالثة\",\"v\":\"بما أن الديان حاضر، اهتمي يا نفسي وتيقظي وتفهمي تلك الساعة المخوفة. فإنه ليس رحمة في الدينونة لمن لم يستعمل الرحمة. فلهذا أشفق علي أيها المخلص.\",\"r\":\"تذكّرنا الكنيسة بالديان الحاضر وبقاعدة الرحمة: الدينونة بلا رحمة لمن لم يستعمل الرحمة. حين أدين غيري أحكم على نفسي بالمعيار نفسه. اترك اليوم حكمًا كنت ستصدره على أحد، واستبدله بطلب رحمة لك وله.\",\"p\":\"بما أن الديان حاضر، اهتمي يا نفسي وتيقظي. فلهذا أشفق عليّ أيها المخلص، فإنك محب البشر وحدك. آمين.\"},{\"t\":\"لماذا تدين أخاك\",\"ref\":\"رومية ١٤: ١٠\",\"bk\":\"رومية\",\"v\":\"وأما أنت، فلماذا تدين أخاك؟ أو أنت أيضا، لماذا تزدري بأخيك؟ لأننا جميعا سوف نقف أمام كرسي المسيح،\",\"r\":\"«وأما أنت فلماذا تدين أخاك؟ أو أنت أيضًا لماذا تزدري بأخيك؟ لأننا جميعًا سوف نقف أمام كرسي المسيح». الحكم ليس لي، فسأقف أنا أيضًا أمام المسيح. وهذا يضعني في مكاني الصحيح: مخلوق يحتاج رحمة. وتحويل نظري من الآخر إلى نفسي هو بداية الحكمة.\",\"p\":\"يا رب، ذكّرني أني سأقف أمام كرسيك. احفظني من الدينونة والازدراء، وعلّمني أن أسعى لما يبني أخي ولا أضع له عثرة. آمين.\"},{\"t\":\"من أنا؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب يوسف الذي في بنفو أخًا يطلب الراحة: إذا أردت أن تجد راحة هنا وهناك، قل في كل شيء: «من أنا؟» ولا تدن أحدًا. هذا السؤال يوقف الدينونة. جرّبه اليوم قبل أن تحكم على أحد.\",\"p\":\"يا رب، علّمني أن أسأل نفسي: من أنا؟ وأن أتوقف عن الدينونة. ارحمني ولا تدنّي كما أدين غيري. آمين.\",\"fq\":182}]},\"5-15\":{\"th\":\"الباب الضيق\",\"m\":[{\"t\":\"ارفعوا أيها الرؤساء أبوابكم\",\"ref\":\"المزمور ٢٣ (٢٤) — الثالثة\",\"v\":\"ارفعوا أيها الرؤساء أبواكم، وارتفعي أيتها الأبواب الدهرية، فيدخل ملك المجد. من هو هذا ملك المجد؟\",\"r\":\"الأبواب الدهرية تُرفع ليدخل ملك المجد. الباب الضيق ليس ضيقًا على المسيح، بل على من يحمل أمتعة كثيرة. وهو الذي قال: أنا هو الباب. أين الأبواب المغلقة في قلبك؟ افتح اليوم بابًا واحدًا لمن يطرقه.\",\"p\":\"يا رب، ارفع أبواب قلبي الدهرية، فيدخل ملك المجد. اجعلني أدخل من بابك الضيق، وتحمل عني ما يعطلني. آمين.\"},{\"t\":\"أنا هو الباب\",\"ref\":\"يوحنا ١٠: ٩\",\"bk\":\"يوحنا\",\"v\":\"أنا هو الباب. إن دخل بي أحد فيخلص ويدخل ويخرج ويجد مرعى.\",\"r\":\"«أنا هو الباب. إن دخل بي أحد فيخلص ويدخل ويخرج ويجد مرعى». الباب الضيق هو المسيح نفسه. فلا أدخل بمجهودي بل به. وهو يعدني بالخلاص والحرية والغذاء. فالباب ليس سجنًا بل مدخل لحياة غنية: أدخل وأخرج وأجد مرعى.\",\"p\":\"يا رب يسوع، أنت الباب. أدخلني بك إلى الخلاص والحرية والمرعى، واحمني من كل ذئب، وأعطني حياة وفيرة في شركتك. آمين.\"},{\"t\":\"الطريق الضيقة\",\"ref\":\"\",\"v\":\"\",\"r\":\"سُئل القديس أمون عن الطريق الضيقة المحزنة فقال إنها أن يمسك الإنسان أفكاره ويقطع مشيئته حبًا بالله. الضيق في القرارات الصغيرة التي أتخلى فيها عن رغبتي. ما الرغبة التي تقطعها اليوم من أجل المسيح؟\",\"p\":\"يا رب، علّمني أن أمسك أفكاري وأقطع مشيئتي حبًا بك. أدخلني من الباب الضيق إلى حياتك. آمين.\",\"fq\":64}]},\"5-16\":{\"th\":\"الابتعاد عن محبة العالم\",\"m\":[{\"t\":\"ويل لي فإن غربتي طالت\",\"ref\":\"المزمور ١١٩ (١٢٠) — الغروب\",\"v\":\"ويل لي فإن غربتي قد طالت علي، وسكنت في مساكن قيدار. طويلا سكنت نفسي في الغربة: ومع مبغضي السلام كنت صاحب سلام، وحين كنت أكلمهم كانوا يقاتلونني باطلا هلليلويا.\",\"r\":\"يصف المرنم نفسه غريبًا يسكن مع من يكرهون السلام، وهو كلما كلمهم قاتلوه. من يحب الله يشعر في هذا العالم بالغربة بقدر ما يتعلق قلبه بالسماء. اسأل اليوم: هل أنا ضيف في هذا العالم أم ساكن؟\",\"p\":\"يا رب، غربتي قد طالت، فاجعل قلبي متعلقًا بوطنك. علّمني أن أكون صاحب سلام وسط من لا يحبون السلام. آمين.\"},{\"t\":\"اهتمام الروح حياة وسلام\",\"ref\":\"رومية ٨: ٥–٦\",\"bk\":\"رومية\",\"v\":\"فإن الذين هم حسب الجسد فبما للجسد يهتمون، ولكن الذين حسب الروح فبما للروح. لأن اهتمام الجسد هو موت، ولكن اهتمام الروح هو حياة وسلام.\",\"r\":\"«لأن اهتمام الجسد هو موت ولكن اهتمام الروح هو حياة وسلام». الفكر الذي أغذّيه يقودني. إن غذّيت الفكر بما للجسد والعالم وجدت قلقًا وفراغًا. وإن غذّيته بما للروح وجدت سلامًا وحياة. فأنا أختار كل يوم بماذا أهتم.\",\"p\":\"يا رب، علّمني أن أهتم بما للروح. نقِّ فكري وغذّه بكلمتك وحضورك، وأعطني حياة وسلامًا من روحك الساكن فيّ. آمين.\"},{\"t\":\"المال واللذة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس: «يستحيل عليك أن تعيش وفقًا لإرادة الله إذا كنت محبًا للمال واللذة». محبة العالم تزاحم محبة الله. ما الذي في العالم يشغل قلبك أكثر من اللازم؟ سمِّه، وخفّف تعلقك به اليوم.\",\"p\":\"يا رب، حرّر قلبي من محبة المال واللذة. اجعل محبتك تملأ كياني فلا يبقى مكان لغيرك. آمين.\",\"fq\":199}]},\"5-17\":{\"th\":\"الصلاة معًا\",\"m\":[{\"t\":\"أنصت يا رب إلى صلاتي\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"أنصت يا رب إلي صلاتي. وأصغ إلى صوت تضرعي. في يوم شدتي إليك صرخت فأجبتني.\",\"r\":\"يطلب المرنم أن ينصت الرب لصلاته ويصغي لتضرعه، ويشهد أنه في يوم شدته صرخ فأجابه. الصلاة معًا تضاعف هذه الثقة، فنصلّي ونحن نعلم أن الجماعة تحمل ضعفنا. اطلب اليوم من أحد أن يصلي معك لأجل أمر واحد.\",\"p\":\"أنصت يا رب إلى صلاتنا، وأصغِ إلى صوت تضرعنا. في يوم شدتنا إليك نصرخ فتجيبنا. اجمعنا في الصلاة وكن في وسطنا. آمين.\"},{\"t\":\"بقلب واحد\",\"ref\":\"أعمال الرسل ١: ١٤\",\"bk\":\"أعمال الرسل\",\"v\":\"هؤلاء كلهم كانوا يواظبون بنفس واحدة على الصلاة والطلبة، مع النساء، ومريم أم يسوع، ومع إخوته.\",\"r\":\"«هؤلاء كلهم كانوا يواظبون بنفس واحدة على الصلاة والطلبة مع النساء ومريم أم يسوع ومع إخوته». كانوا ينتظرون وعد الآب. ولم يملؤوا الانتظار بالقلق بل بالصلاة معًا. وجاء الروح القدس على جماعة متحدة. فالوحدة تهيّئ لاستقبال النعمة.\",\"p\":\"يا رب، علّمنا أن نواظب بنفس واحدة على الصلاة. حوّل أوقات انتظارنا إلى لقاء معك ومع بعضنا، واملأنا بروحك القدوس. آمين.\"},{\"t\":\"كيف ينبغي أن نصلي؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلم الأب مكاريوس أننا لا نحتاج إلى كثرة الكلام، بل أن نمد أيدينا إلى العلاء ونقول: يا رب ارحمنا كما تريد وكما تعلم. هكذا نصلي معًا بكلمة بسيطة. رددوا هذه الجملة اليوم في البيت أو الكنيسة.\",\"p\":\"يا رب، ارحمنا كما تريد وكما تعلم. علّمنا أن نصلي معًا ببساطة، وأن تجمعنا صلاتنا في اسمك. آمين.\",\"fq\":239}]},\"5-18\":{\"th\":\"العبادة بالروح والحق\",\"m\":[{\"t\":\"أنا أستيقظ مبكرًا\",\"ref\":\"المزمور ٥٦ (٥٧) — السادسة\",\"v\":\"استيقظ يا مجدي، استيقظ أيها المزمار والقيثارة. أنا أستيقظ مبكرا.\",\"r\":\"يوقظ المرنم مجده: «استيقظ يا مجدي، استيقظ أيها المزمار والقيثارة. أنا أستيقظ مبكرًا». العبادة بالروح والحق تبدأ من اليقظة الداخلية قبل الصوت الخارجي. حاول اليوم أن تصلي بكلمات قليلة ولكن بانتباه كامل.\",\"p\":\"استيقظ يا مجدي، استيقظ أيها المزمار والقيثارة. يا رب، أنا أستيقظ لأعبدك بالروح والحق، وأسبحك من كل قلبي. آمين.\"},{\"t\":\"امتلئوا بالروح\",\"ref\":\"أفسس ٥: ١٨–١٩\",\"bk\":\"أفسس\",\"v\":\"ولا تسكروا بالخمر الذي فيه الخلاعة، بل امتلئوا بالروح، مكلمين بعضكم بعضا بمزامير وتسابيح وأغاني روحية، مترنمين ومرتلين في قلوبكم للرب.\",\"r\":\"«ولا تسكروا بالخمر الذي فيه الخلاعة بل امتلئوا بالروح». كلنا نبحث عن ما يملأنا. فهناك امتلاء بالأشياء يؤدي إلى فراغ، وامتلاء بالروح يؤدي إلى فرح وترنيم. والامتلاء بالروح ليس حدثًا واحدًا بل حالة مستمرة تتغذى بالصلاة والكلمة.\",\"p\":\"يا روح الله، املأني بك. اجعلني أرتل وأسبح في قلبي كل حين، وأشكر الآب بكل شيء، وأخضع لإخوتي بمحبة المسيح. آمين.\"},{\"t\":\"الصلاة في القلب دائمًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال القديس إبيفانيوس لرئيس دير أهمل صلوات النهار: الراهب الحقيقي ينبغي أن يحوي الصلاة في قلبه على الدوام. العبادة بالروح لا تتوقف عند ساعة الكنيسة. خذ اليوم جملة قصيرة من صلاة تحملها في قلبك طوال النهار.\",\"p\":\"يا رب، اجعل الصلاة في قلبي على الدوام. علّمني أن أعبدك بالروح والحق في كل ساعة وكل مكان. آمين.\",\"fq\":99}]},\"5-19\":{\"th\":\"الروح والجسد\",\"m\":[{\"t\":\"ولتنطفئ حرارة الجسد\",\"ref\":\"تحليل الستار\",\"v\":\"أيها السيد الرب يسوع المسيح إلهنا اعطنا راحة في نومنا ونياحا في أجسادنا وطهارة في أنفسنا. واحفظنا من ظلمة الخطية المدلهمة. ولتسكن حركات الآلام ولتنطفئ حرارة الجسد.\",\"r\":\"تطلب الكنيسة راحة الجسد وطهارة النفس وسكون الآلام. الصراع بين الروح والجسد ليس عداوة مع الجسد نفسه، بل ترتيب: الروح تقود والجسد يتبع. قبل أن تنام الليلة، سلّم جسدك وأفكارك لله وقل: سكّن حركاتي.\",\"p\":\"أيها السيد الرب يسوع، أعطنا راحة في نومنا وطهارة في أنفسنا. احفظنا من ظلمة الخطية، واجعل الروح تقود حياتنا. آمين.\"},{\"t\":\"إن أمتم أعمال الجسد\",\"ref\":\"رومية ٨: ١٣\",\"bk\":\"رومية\",\"v\":\"لأنه إن عشتم حسب الجسد فستموتون، ولكن إن كنتم بالروح تميتون أعمال الجسد فستحيون.\",\"r\":\"«لأنه إن عشتم حسب الجسد فستموتون ولكن إن كنتم بالروح تميتون أعمال الجسد فستحيون». الإماتة ليست كراهية للجسد بل رفضًا لأعمال تقتل الروح. وهي تتم بالروح لا بإرادتي وحدي. فأنا أتعاون مع نعمة تميت العادات السيئة.\",\"p\":\"يا رب، روح قيامتك ساكن فيّ. أمِت بروحك أعمال الجسد فيّ، وأعطني حياة وسلامًا، وقوِّ إرادتي لأقول لا لما يقتل روحي. آمين.\"},{\"t\":\"الصوم يسمو فوق اللذة\",\"ref\":\"\",\"v\":\"\",\"r\":\"تشجع الأم سينكليتيكي على ألا يغرينا تنعّم الأغنياء بلذتهم الجوفاء، فالصائم يسمو فوق طيّبات أطعمتهم. تدريب الجسد على الامتناع يحرر الروح. اختر اليوم امتناعًا صغيرًا عن شيء مباح، وقدّمه صلاة.\",\"p\":\"يا رب، علّمني أن أضبط جسدي ليخدم الروح. أعطني نعمة الامتناع بفرح، فأتحرر من عبودية اللذة. آمين.\",\"fq\":533}]},\"5-20\":{\"th\":\"محبة الله والإخوة\",\"m\":[{\"t\":\"الرب يجمع المتفرقين\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"الرب يبني أورشليم. الرب يجمع متفرقي إسرائيل.\",\"r\":\"يعلن المرنم أن الرب يبني أورشليم ويجمع متفرقي إسرائيل. محبة الله ليست شعورًا عابرًا بل عمل بناء وجمع. ومن أحب الله أحب أن يجمع هو أيضًا لا أن يفرّق. من هو الأخ الذي ابتعد عنك؟ ابدأ اليوم بخطوة جمع صغيرة نحوه.\",\"p\":\"الرب يبني أورشليم ويجمع متفرقي إسرائيل. يا رب، اجمعني بمحبتك إليك وإلى إخوتي، واجعلني أداة بنيان لا هدم. آمين.\"},{\"t\":\"إن أحب بعضنا بعضًا\",\"ref\":\"يوحنا الأولى ٤: ١١–١٢\",\"bk\":\"يوحنا الأولى\",\"v\":\"أيها الأحباء، إن كان الله قد أحبنا هكذا، ينبغي لنا أيضا أن يحب بعضنا بعضا. الله لم ينظره أحد قط. إن أحب بعضنا بعضا، فالله يثبت فينا، ومحبته قد تكملت فينا.\",\"r\":\"«إن كان الله قد أحبنا هكذا ينبغي لنا أيضًا أن يحب بعضنا بعضًا. الله لم ينظره أحد قط. إن أحب بعضنا بعضًا فالله يثبت فينا ومحبته قد تكملت فينا». محبة الإخوة هي الطريقة التي يراه بها العالم. وهي تكمل محبته فيّ.\",\"p\":\"يا رب، أنت أحببتنا فعلّمنا أن نحب. اجعل محبتك تكمل فينا، واظهر من خلالنا للعالم الذي لا يراك، وثبّتنا في المحبة. آمين.\"},{\"t\":\"الحث على المحبة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: «كثيرون صاروا أقوياء، لكن القليلين يحثّون على المحبة». أي أن القوة سهلة والمحبة نادرة. لا تكتفِ اليوم بأن تحب، بل شجّع أخًا على محبة، بكلمة أو بمثال حي.\",\"p\":\"يا رب، علّمني أن أحث على المحبة بأعمالي. اجعلني بين القلة الذين يرفعون الآخرين ويشجعونهم على أن يحبوا. آمين.\",\"fq\":410}]},\"5-21\":{\"th\":\"حكمة الله\",\"m\":[{\"t\":\"عظيم هو الرب\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"المحصي كثرة الكواكب، ولكافتها يعطي أسماء. عظيم هو الرب وعظيمة هي قوته؛ ولا إحصاء لفهمه.\",\"r\":\"يتأمل المرنم أن الرب يحصي كثرة الكواكب ويدعو كل واحد باسمه، وأن فهمه لا إحصاء له. حكمة الله لا تُقاس بحجم معرفتنا. اسجد اليوم في صلاتك أمام لغز لا تفهمه، وقل: عظيم أنت يا رب، وأنا أثق بحكمتك.\",\"p\":\"عظيم أنت يا رب وعظيمة قوتك، ولا إحصاء لفهمك. أنت تحصي الكواكب وتعرف أسماءها، فاعرف قلبي وقده بحكمتك. آمين.\"},{\"t\":\"ما لم تر عين\",\"ref\":\"كورنثوس الأولى ٢: ٩\",\"bk\":\"كورنثوس الأولى\",\"v\":\"بل كما هو مكتوب: «ما لم تر عين، ولم تسمع أذن، ولم يخطر على بال إنسان: ما أعده الله للذين يحبونه».\",\"r\":\"«ما لم تر عين ولم تسمع أذن ولم يخطر على بال إنسان ما أعده الله للذين يحبونه». أفكاري صغيرة أمام عطايا الله. وهذا يعطيني رجاء لا حدود له. فلا أحكم على مستقبلي بما أتخيله، ولا أستسلم لتوقعات ضيقة.\",\"p\":\"يا رب، ما أعددته لمن يحبونك يفوق كل تصوري. افتح قلبي لروحك ليعلن لي ما لم تره عيني، وأعطني رجاءً لا حدود له. آمين.\"},{\"t\":\"حكماء كالحيات\",\"ref\":\"\",\"v\":\"\",\"r\":\"تفسر الأم سينكليتيكي قول الرب «كونوا حكماء كالحيّات ودعاء كالحمام» بأننا لا ينبغي أن تنطلي علينا ألاعيب الشيطان. الحكمة الإلهية تجمع الانتباه والوداعة. اطلب اليوم حكمة تميّز دون أن تتصلب.\",\"p\":\"يا رب، أعطني حكمة الحيات ووداعة الحمام. احفظني من خداع العدو، وقوِّ قلبي بحكمتك. آمين.\",\"fq\":544}]},\"5-22\":{\"th\":\"الشكر في كل شيء\",\"m\":[{\"t\":\"أنت إلهي فأشكرك\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"أنت هو إلهي فأشكرك، إلهي أنت فأرفعك. أعترف لك يا رب، لأنك استجبت لي وصرت لي مخلصا.\",\"r\":\"يسبح المرنم إلهه معترفًا: لأنك استجبت لي وصرت لي مخلصًا. الشكر هنا ليس مجاملة بل شهادة. أمسك ورقة وسجّل ثلاث استجابات حدثت لك هذا العام، وقدّمها لله اليوم شكرًا صريحًا.\",\"p\":\"أنت هو إلهي فأشكرك، إلهي أنت فأرفعك. أعترف لك يا رب لأنك استجبت لي وصرت لي مخلصًا. آمين.\"},{\"t\":\"أشكر إلهي\",\"ref\":\"فيلبي ١: ٣\",\"bk\":\"فيلبي\",\"v\":\"أشكر إلهي عند كل ذكري إياكم\",\"r\":\"«أشكر إلهي كلما ذكرتكم». بولس في السجن لكنه يشكر على أصدقائه. وهذا يدفعني أن أتذكر من أثروا في حياتي، وأشكر الله عليهم. فمن عرفتهم كانوا عطايا. وذكرهم بالشكر يغذي قلبي بمحبة.\",\"p\":\"يا رب، أشكرك على كل من وضعتهم في حياتي. بارك كل واحد منهم، وأكمل فيهم العمل الصالح الذي بدأته، واجعلني أصلي لأجلهم بفرح. آمين.\"},{\"t\":\"هنيئًا لمن يحتمل التعب بشكر\",\"ref\":\"\",\"v\":\"\",\"r\":\"عبارة الأب كوبريس في سطر: «هنيئًا لمن يحتمل التعب بشكر». أي أن الشكر لا ينتظر الراحة. إن كان تعب اليوم ثقيلًا، فاشكر فيه حتى قبل أن ينتهي، وانظر كيف يخف.\",\"p\":\"يا رب، علّمني أن أشكر في التعب. أعطني قلبًا يرى في كل جهد نعمة وفي كل تعب خيرًا. آمين.\",\"fq\":222}]},\"5-23\":{\"th\":\"قوة الاسم\",\"m\":[{\"t\":\"ما أعجب اسمك\",\"ref\":\"المزمور الثامن — باكر\",\"v\":\"أيها الرب ربنا، ما أعجب اسمك في الأرض كلها! لأنه قد ارتفع عظم جلالك فوق السموات.\",\"r\":\"يفتتح المرنم صلاته بالتعجب من اسم الرب في الأرض كلها، وارتفاع جلاله فوق السماوات. الاسم ليس لفظًا بل حضور الله نفسه. حين تنطق «يا رب يسوع ارحمني» اليوم، تذكّر أنك تستدعي ملك الأرض.\",\"p\":\"أيها الرب ربنا، ما أعجب اسمك في الأرض كلها. ارتفع جلالك فوق السماوات، فاسمك قوتي وملجئي في كل ضيق. آمين.\"},{\"t\":\"مهما سألتم باسمي\",\"ref\":\"يوحنا ١٤: ١٣–١٤\",\"bk\":\"يوحنا\",\"v\":\"ومهما سألتم باسمي فذلك أفعله ليتمجد الآب بالابن. إن سألتم شيئا باسمي فإني أفعله.\",\"r\":\"«ومهما سألتم باسمي فذلك أفعله ليتمجد الآب بالابن». الصلاة باسم المسيح ليست إضافة عبارة بل مطابقة لقلبه ومشيئته. وغاية الاستجابة أن يتمجد الآب. وهذا يهذب طلباتي: هل ما أطلبه يمجد الله؟ ويعطيني ثقة بقبول الطلب.\",\"p\":\"يا رب يسوع، أطلب باسمك فاستجب لي بحسب مشيئتك ليتمجد الآب بك. هذّب طلباتي، وأعطني ثقة بمحبتك وحكمتك في كل استجابة. آمين.\"},{\"t\":\"اسم أكبر من العمل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يتحسر الأب سلوان على من كان اسمه أكبر من عمله. قوة الاسم المسيحي تكمن في أن يطابقه السلوك. حين يسمّيك الناس مسيحيًا، هل يجدون حياة تشهد لهذا الاسم؟ اجعل عملك اليوم يشرّف الاسم.\",\"p\":\"يا رب، لا تدعني أحمل اسمك باطلًا. اجعل أعمالي توافق اسم المسيحي الذي دعيت به. آمين.\",\"fq\":514}]},\"5-24\":{\"th\":\"الكرازة\",\"m\":[{\"t\":\"بشروا بخلاصه\",\"ref\":\"المزمور ٩٧ (٩٨) — التاسعة\",\"v\":\"سبحوا الرب تسبيحا جديدا لأن الرب قد صنع أعمالا عجيبة. خلصت له يمينه وذراعه القدوس، أعلن الرب خلاصه وكشف قدام الأمم عدله.\",\"r\":\"تعلن الكرازة ما صنعه الله: أعمال عجيبة وخلاص يمين الله وعدله. ليس المبشر صاحب الرسالة بل ناقلها. في حديث اليوم مع من يهمّك أمره، اذكر شيئًا واحدًا صنعه الله معك، وقله بصدق دون ضغط.\",\"p\":\"سبحوا الرب تسبيحًا جديدًا لأنه صنع أعمالًا عجيبة. يا رب، أعطني فمًا يعلن خلاصك، وحياة تشهد لعدلك أمام الأمم. آمين.\"},{\"t\":\"اذهبوا إلى العالم\",\"ref\":\"مرقس ١٦: ١٥\",\"bk\":\"مرقس\",\"v\":\"وقال لهم: «اذهبوا إلى العالم أجمع واكرزوا بالإنجيل للخليقة كلها.\",\"r\":\"«اذهبوا إلى العالم أجمع واكرزوا بالإنجيل للخليقة كلها». الإنجيل ليس سرًا بل بشرى لكل أحد. وهذه ليست مهمة المتخصصين فقط، بل دعوة لكل مؤمن بحسب موقعه. والبشارة تبدأ بحياة تشهد وكلمة محبة في وقتها.\",\"p\":\"يا رب، أرسلني إلى من تريد لأحمل بشارتك. أعطني محبة وحكمة وجرأة، وافتح قلوب من حولي لسماع كلمتك. آمين.\"},{\"t\":\"الكلمة الطيبة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب مكاريوس: «الكلمة الشريرة تجعل الصالحين أشرارًا، أما الكلمة الطيبة فمن شأنها أن تجعل الأشرار صالحين». الكرازة الأولى كلمة طيبة. قل اليوم كلمة تشجيع صادقة لشخص لا يتوقعها.\",\"p\":\"يا رب، ضع في فمي كلمة طيبة تبني. اجعل كلامي مبشرًا بك، وتغيّر قلوب من يسمعه. آمين.\",\"fq\":250}]},\"5-25\":{\"th\":\"الأمور الصغيرة\",\"m\":[{\"t\":\"من هو الإنسان حتى تذكره؟\",\"ref\":\"المزمور الثامن — باكر\",\"v\":\"من هو الإنسان حتى تذكره. أو ابن الإنسان حتى تفتقده؟!\",\"r\":\"يتعجب المرنم من أن الله يذكر الإنسان ويفتقده، رغم عظمة السماوات. الله لا يزدري الصغير. إن شعرت أن ما تفعله اليوم صغير لا قيمة له، فتذكّر أن من يحصي الكواكب يهتم بكأس ماء بارد.\",\"p\":\"من هو الإنسان حتى تذكره، وابن الإنسان حتى تفتقده؟ يا رب، أشكرك على اهتمامك بالصغير. بارك الأمور الصغيرة في يدي. آمين.\"},{\"t\":\"كأس ماء بارد\",\"ref\":\"متى ١٠: ٤٢\",\"bk\":\"متى\",\"v\":\"ومن سقى أحد هؤلاء الصغار كأس ماء بارد فقط باسم تلميذ، فالحق أقول لكم إنه لا يضيع أجره».\",\"r\":\"«ومن سقى أحد هؤلاء الصغار كأس ماء بارد فقط باسم تلميذ فالحق أقول لكم إنه لا يضيع أجره». كأس ماء! لا مال ولا مجهود كبير، لكن المسيح يحسبه. فالمحبة الصغيرة عند الله عظيمة. وكل لفتة طيبة تحمل أجرًا.\",\"p\":\"يا رب، أشكرك لأنك تحسب أصغر عطية. علّمني أن أخدم بالصغائر بمحبة، وأن أرى فيها خدمتك، فلا يضيع أجر ما أقدمه باسمك. آمين.\"},{\"t\":\"ما تراه فافعله\",\"ref\":\"\",\"v\":\"\",\"r\":\"ألحّ أخ على الأب سيسوى أن يعطيه كلمة واحدة، فقال له: «لماذا ترغمني على الكلام؟ ما تراه إياه إفعل». أي لا تنتظر العظائم، بل افعل الخير الذي تراه أمامك. ما الخير الصغير الذي تراه ولا تفعله؟ افعله الآن.\",\"p\":\"يا رب، علّمني أن أفعل الخير الذي أراه ولو كان صغيرًا. اجعلني أمينًا في القليل وأعمل بما ترشدني إليه. آمين.\",\"fq\":508}]},\"5-26\":{\"th\":\"البحث عن الضال\",\"m\":[{\"t\":\"ضللت مثل الخروف الضال\",\"ref\":\"المزمور ١١٨ — الجزء الثاني والعشرون («كُونوا مُستَعِدّينَ، لأنَّهُ في ساعَةٍ لا تَظُنّونَ يَأتي ابنُ الإنسان.») — الستار\",\"v\":\"وأحكامك تعينيني. ضللت مثل الخروف الضال، فاطلب عبدك، فإني لوصاياك لم أنس هلليلويا.\",\"r\":\"يعترف المرنم بأنه ضلّ مثل الخروف الضال ويطلب من الله أن يطلب عبده. المسيح هو الراعي الذي يخرج للبحث. من ضلّ لا يفقد قيمته، بل يُطلب. فكّر اليوم في إنسان ابتعد عن الكنيسة أو عنك، وصلّ من أجله بالاسم.\",\"p\":\"ضللت مثل الخروف الضال، فاطلب عبدك لأني لوصاياك لم أنس. يا راعي الخراف، ابحث عني وعن كل ضال، وردنا إلى حظيرتك. آمين.\"},{\"t\":\"لا أسر بموت الشرير\",\"ref\":\"حزقيال ١٨: ٢٣\",\"bk\":\"حزقيال\",\"v\":\"هل مسرة أسر بموت الشرير؟ يقول السيد الرب. ألا برجوعه عن طرقه فيحيا؟\",\"r\":\"«هل مسرة أسر بموت الشرير؟ يقول السيد الرب. ألا برجوعه عن طرقه فيحيا؟». الله لا يتلذذ بمعاقبة أحد. فهو يشتاق إلى عودتي. وهذا يغيّر نظرتي إليه: ليس قاضيًا متربصًا بل أبًا ينتظر. ويغير نظرتي للخاطئين: فهم أحباء ينتظرهم.\",\"p\":\"يا رب، أشكرك لأنك لا تسر بموت الخاطئ بل برجوعه. أرجع إليك اليوم، فاقبلني، وعلّمني أن أنظر إلى الخطاة بنظرة محبتك وانتظارك. آمين.\"},{\"t\":\"خاطئ يتوب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سارمتا: «أفضل إنسانًا خاطئًا لكنه يعرف خطيته ويتوب عليها، على إنسان لا يخطئ بل يرى نفسه بارًا». الله يبحث عن التائب ويفرح به. لا تحكم على أحد ضال، بل تذكّر أنك كنت مطلوبًا أنت أيضًا.\",\"p\":\"يا رب، اجعلني أعرف خطيتي وأتوب عنها. ولا تدعني أرى نفسي بارًا فأبتعد عن رحمتك. آمين.\",\"fq\":517}]},\"5-27\":{\"th\":\"الشفاعة\",\"m\":[{\"t\":\"أنت استجبت لهم\",\"ref\":\"المزمور ٩٨ (٩٩) — التاسعة\",\"v\":\"لأنهم حفظوا شهاداته. والأوامر التي أعطاهم. أيها الرب إلهنا، أنت استجبت لهم.\",\"r\":\"يمدح المرنم موسى وهرون وصموئيل لأنهم حفظوا شهادات الله وأوامره، وأن الله استجاب لهم. الشفاعة تقوى بالأمانة. من هو الشخص الذي تحمله في صلاتك؟ اذكره اليوم بالاسم، واطلب له خيرًا كما تطلب لنفسك.\",\"p\":\"أيها الرب إلهنا، أنت استجبت لهم لأنهم حفظوا شهاداتك. علّمني أن أشفع في الآخرين بإيمان، وأحمل أحبائي أمامك في صلاتي. آمين.\"},{\"t\":\"كنت أود أن أكون أنا محرومًا\",\"ref\":\"رومية ٩: ٣\",\"bk\":\"رومية\",\"v\":\"فإني كنت أود لو أكون أنا نفسي محروما من المسيح لأجل إخوتي أنسبائي حسب الجسد،\",\"r\":\"«فإني كنت أود لو أكون أنا نفسي محرومًا من المسيح لأجل إخوتي أنسبائي حسب الجسد». هذا كان قلب بولس: حزن مستمر لأجل الذين لم يؤمنوا. وهذا يعلمني ألا أكون بارد القلب نحو من لا يعرف المسيح. بل أحزن وأصلي.\",\"p\":\"يا رب، أعطني قلبًا يتألم لخلاص الآخرين. ازرع فيّ محبة تصلي وتعمل من أجل البعيدين، وأعد إليك أقاربي وأحبائي. آمين.\"},{\"t\":\"صلّوا من أجل بعضكم\",\"ref\":\"\",\"v\":\"\",\"r\":\"عندما جاء أخ يشكو كاهنًا، قال له الأب مرقس: «الكل يطرحون الفساد خارجًا، أما أنت فقد أحضرته إلي»، وذكّره بقول الكتاب: لا تدينوا. الشفاعة بدل الشكوى. صلِّ اليوم لمن يضايقك بدل أن تشكوه.\",\"p\":\"يا رب، علّمني أن أشفع في من يضايقني بدل أن أتكلم عنه. اجعل صلاتي رحمة تغطي ولا تفضح. آمين.\",\"fq\":286}]},\"5-28\":{\"th\":\"الخميرة\",\"m\":[{\"t\":\"يرسل كلمته فيسرع قوله\",\"ref\":\"المزمور ١٤٧ — النوم\",\"v\":\"الذي يرسل كلمته إلى الأرض فيسرع قوله عاجلا جدا. المعطي الثلج كالصوف.\",\"r\":\"يقول المرنم إن الله يرسل كلمته إلى الأرض فيسرع قوله عاجلًا جدًا. الخميرة الصغيرة في العجين تعمل بصمت حتى يختمر الكل. كلمة صادقة تقولها أو عمل خير تفعله قد يحمل أثرًا لا تراه. اترك اليوم في مكانك خميرة خير.\",\"p\":\"الذي يرسل كلمته إلى الأرض فيسرع قوله عاجلًا جدًا، أرسل كلمتك إلى قلبي وإلى بيتي. واجعلني خميرة صالحة في كل مكان. آمين.\"},{\"t\":\"قليل من الخميرة\",\"ref\":\"كورنثوس الأولى ٥: ٦\",\"bk\":\"كورنثوس الأولى\",\"v\":\"ليس افتخاركم حسنا. ألستم تعلمون أن خميرة صغيرة تخمر العجين كله؟\",\"r\":\"«أما تعلمون أن خميرة صغيرة تخمّر العجين كله؟». خطية صغيرة مخفية قد تنتشر وتفسد الجماعة. وهذا يعلّمني الجدية في معالجة الأخطاء الصغيرة قبل انتشارها. وقد تكون الخميرة نميمة أو كبرياء أو حسدًا. وعلاجها التنقية بالتوبة.\",\"p\":\"يا رب، نقِّ قلبي من خميرة الشر والخبث. اجعلني عجينًا جديدًا لأن فصحنا المسيح قد ذبح لأجلنا، وساعدني أن أحفظ نقاء جماعتك. آمين.\"},{\"t\":\"الماء يثقب الصخرة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن كلمة الله بالماء الناعم الذي ينزل على الصخرة قطرة قطرة فيثقبها. هكذا تعمل الكلمة تدريجيًا في قلب قاسٍ. لا تيأس من بطء التغيير، وواظب اليوم على قطرة: آية تقرؤها وتتأملها.\",\"p\":\"يا رب، ليتنقط في قلبي ماء كلمتك فيثقب قسوته. واظب بي على قراءتها حتى تتغير حياتي. آمين.\",\"fq\":451}]},\"5-29\":{\"th\":\"الحصاد\",\"m\":[{\"t\":\"الأرض أعطت ثمرتها\",\"ref\":\"المزمور السادس والستون — باكر\",\"v\":\"الأرض أعطت ثمرتها، فليباركنا الله إلهنا. ليباركنا الله.\",\"r\":\"يعلن المرنم أن الأرض أعطت ثمرتها، ثم يطلب: فليباركنا الله إلهنا. الحصاد عطية قبل أن يكون إنجازًا. لا تشكر على الحصاد وحده، بل على الزارعين الذين سبقوك. تذكّر اليوم من زرع في حياتك الروحية.\",\"p\":\"الأرض أعطت ثمرتها، فليباركنا الله إلهنا. أشكرك على كل من زرع فيّ الإيمان. اجعلني حصادًا نافعًا وأرسلني لأحصد ما زرعته أنت. آمين.\"},{\"t\":\"الحصاد كثير\",\"ref\":\"متى ٩: ٣٧–٣٨\",\"bk\":\"متى\",\"v\":\"حينئذ قال لتلاميذه: «الحصاد كثير ولكن الفعلة قليلون. فاطلبوا من رب الحصاد أن يرسل فعلة إلى حصاده».\",\"r\":\"«الحصاد كثير ولكن الفعلة قليلون. فاطلبوا من رب الحصاد أن يرسل فعلة إلى حصاده». بدأ المسيح بالنظر بحنان إلى الجموع، ثم دعا إلى الصلاة. وأول الخدمة هي الصلاة: أن نطلب فعلة. وربما أكون أنا أحد الفعلة الذين يرسلهم الله استجابة لصلاة.\",\"p\":\"يا رب الحصاد، أرسل فعلة إلى حصادك. اجعلني مستعدًا أن أكون واحدًا منهم، وأعطني حنانك على الجموع المتعبة وجرأة على الخدمة. آمين.\"},{\"t\":\"رجاء وعمل\",\"ref\":\"\",\"v\":\"\",\"r\":\"الكلمة التي ينقلها الأب كيرس عن الرجاء والعمل تذكّرنا أن الرجاء بلا عمل لا يثمر. الحصاد الكثير يحتاج فعلة قليلين. فاسأل: ما العمل الذي يتطلبه رجائي اليوم؟ ابدأه ولو بخطوة.\",\"p\":\"يا سيد الحصاد، لا تدعني متفرجًا على حقلك. اجعلني واحدًا من فعلتك بالرجاء والعمل. آمين.\",\"fq\":224}]},\"5-30\":{\"th\":\"الأيدي المرفوعة\",\"m\":[{\"t\":\"لتستقم صلاتي كالبخور\",\"ref\":\"المزمور ١٤٠ (١٤١) — النوم\",\"v\":\"لتسقم صلاتي كالبخور قدامك. وليكن رفع يدي كذبيحة مسائية.\",\"r\":\"يشبّه المرنم صلاته بالبخور ورفع يديه بذبيحة مسائية. الأيدي المرفوعة صورة التوسل والاتكال على الله وحده، وهي تحمل المحتاجين. ارفع يديك الليلة في صلاتك، ولو في سرك، وضع بين يديك كل من تحمله في قلبك.\",\"p\":\"لتستقم صلاتي كالبخور قدامك، وليكن رفع يدي كذبيحة مسائية. تقبّل يا رب صلاتي وشفاعاتي كما تقبّلت بخور هارون. آمين.\"},{\"t\":\"يدا موسى ثقيلتان\",\"ref\":\"الخروج ١٧: ١١–١٢\",\"bk\":\"الخروج\",\"v\":\"وكان إذا رفع موسى يده أن إسرائيل يغلب، وإذا خفض يده أن عماليق يغلب. فلما صارت يدا موسى ثقيلتين، أخذا حجرا ووضعاه تحته فجلس عليه. ودعم هارون وحور يديه، الواحد من هنا والآخر من هناك. فكانت يداه ثابتتين إلى غروب الشمس.\",\"r\":\"«وكان إذا رفع موسى يده أن إسرائيل يغلب وإذا خفض يده أن عماليق يغلب». الصلاة لها أثر حقيقي في المعركة. وعندما ثقلت يدا موسى سنده أخواه. وهذا يعلمني أنني أحتاج إلى من يسندني في الصلاة، وأن أكون أنا أيضًا سندًا لغيري.\",\"p\":\"يا رب، أشكرك على قوة الصلاة. أعطني من يسند يديّ عند التعب، وأعطني أن أسند الآخرين، وأن نغلب بصلواتنا المشتركة. آمين.\"},{\"t\":\"النار والماء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن الإنسان الذي يشعل نارًا بيسراه ويحمل وعاء ماء بيمناه ليخمدها. هكذا الصلاة: الأيدي ترتفع لتطفئ نار الأفكار. عند أول فكر ملتهب اليوم، ارفع يدك في سرك واطلب الإخماد.\",\"p\":\"يا رب، أطفئ بصلاتي نار الأفكار التي تشتعل في قلبي. وارفع يدي إليك لتحفظني من الاضطراب. آمين.\",\"fq\":421}]},\"5-31\":{\"th\":\"كل الأشياء للخير\",\"m\":[{\"t\":\"إن سلكت في وسط الشدة\",\"ref\":\"المزمور ١٣٧ — النوم\",\"v\":\"إن سلكت في وسط الشدة فإنك تحييني. على رجز الأعداء مددت يدك وخلصتني يمينك.\",\"r\":\"يشهد المرنم أنه إن سلك في وسط الشدة فالله يحييه، وأن يده امتدت على رجز الأعداء. يختم الشهر بحقيقة: كل الأشياء تعمل معًا للخير. قد لا ترى الخير الآن، لكن يد الله ممدودة. اذكر شدة مضت وصارت خيرًا.\",\"p\":\"إن سلكت في وسط الشدة فإنك تحييني، وعلى رجز الأعداء تمد يدك وتخلصني يمينك. أشكرك لأن كل الأشياء تعمل معًا للخير. آمين.\"},{\"t\":\"أنتم قصدتم لي شرًا\",\"ref\":\"التكوين ٥٠: ٢٠\",\"bk\":\"التكوين\",\"v\":\"أنتم قصدتم لي شرا، أما الله فقصد به خيرا، لكي يفعل كما اليوم، ليحيي شعبا كثيرا.\",\"r\":\"«أنتم قصدتم لي شرًا. أما الله فقصد به خيرًا لكي يفعل كما اليوم ليحيي شعبًا كثيرًا». بعد سنين من السجن والظلم، رأى يوسف يد الله. لم ينكر الشر الذي وقع عليه، لكنه رأى أن الله حوّله لخير. وهذا يحررني من المرارة.\",\"p\":\"يا رب، علّمني أن أرى يدك وراء كل أذى. حوّل قصدهم الشر خيرًا في حياتي، وأعطني قلبًا يغفر كيوسف ويطمئن من أساء إليّ. آمين.\"},{\"t\":\"سلّمه إلى الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب سيسوى أن من حلّت به تجربة يقول: «إن هذا حدث من أجل خطيئتي» ويسلّم الأمر إلى الله. هكذا يتحول الحدث إلى مدرسة. اختم الشهر بتسليم تجربة ما بين يدي الله بثقة أنه يرتب خيرًا.\",\"p\":\"يا رب، أسلّم لك كل تجربة. حوّل ما أراه شرًا إلى خير، وعلّمني أن أرى يدك في كل حدث. آمين.\",\"fq\":498}]},\"6-1\":{\"th\":\"حلول الروح القدس\",\"m\":[{\"t\":\"جدّده في أحشائنا\",\"ref\":\"قطعة الثالثة (٢)\",\"v\":\"أيها الرب الذي أرسلت روح قدسك على تلاميذك القديسين ورسلك المكرمين في الساعة الثالثة، لا تنزعه منا، بل نسألك أن تجدده في أحشائنا روحًا مستقيمًا ومحييًا، روح القداسة والعدالة والسلطة.\",\"r\":\"صلاة الساعة الثالثة تذكّرنا بيوم حلول الروح على التلاميذ، وتطلب ألا يُنزع منا. الروح القدس يسكن في قلب مفتوح له، ويجدد ما فينا من الداخل. افتح قلبك الآن دقيقة صمت، وقل له: تفضل وجدد.\",\"p\":\"أيها الروح القدس، لا تنزعك مني، وجدد فيّ روحًا مستقيمًا. اجعل صلاتي اليوم منك لا مني، وخلّص نفسي بنعمتك. آمين.\"},{\"t\":\"امتلأ الجميع من الروح\",\"ref\":\"أعمال الرسل ٢: ١–٤\",\"bk\":\"أعمال الرسل\",\"v\":\"ولما حضر يوم الخمسين كان الجميع معا بنفس واحدة، وصار بغتة من السماء صوت كما من هبوب ريح عاصفة وملأ كل البيت حيث كانوا جالسين، وظهرت لهم ألسنة منقسمة كأنها من نار واستقرت على كل واحد منهم. وامتلأ الجميع من الروح القدس، وابتدأوا يتكلمون بألسنة أخرى كما أعطاهم الروح أن ينطقوا.\",\"r\":\"«وكان الجميع معًا بنفس واحدة… وامتلأ الجميع من الروح القدس». لم يكونوا يعملون شيئًا استثنائيًا، كانوا مجتمعين ومنتظرين. والروح القدس نزل على الجماعة كلها لا على فرد واحد. وهذا يعلمني أن الامتلاء يأتي في الشركة والانتظار والطاعة.\",\"p\":\"تعالَ يا روح الله واملأني. أحرق فيّ كل ما يعيق محبتك، وأعطني دفئًا وشجاعة لأشهد لك، واجمعنا معًا في وحدة الكنيسة. آمين.\"},{\"t\":\"العمل الداخلي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصينا الأب أرسانيوس أن نجاهد ليكون عملنا الداخلي موافقًا لإرادة الله، فتنهزم الأهواء الخارجية. والروح القدس هو الذي يعمل في الداخل. اسأل نفسك اليوم: ما الذي يريده الله في قلبي أكثر مما في مظهري؟\",\"p\":\"يا رب، أرني ما في داخلي، واعمل أنت فيه بروحك القدوس. أعطني جهادًا هادئًا يوافق مشيئتك. آمين.\",\"fq\":29}]},\"6-2\":{\"th\":\"الاستنارة بالروح\",\"m\":[{\"t\":\"الرب نوري\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"الرب نوري وخلاصي ممن أخاف؟! الرب حصن حياتي ممن أجزع؟!\",\"r\":\"حين يكون الرب نورنا لا يبقى للخوف سلطان، فالنور يكشف الطريق قبل أن يطرد الظلمة. الاستنارة عطية تُطلب كل صباح. قبل أن تقرأ أو تقرر شيئًا اليوم، اطلب نورًا للخطوة التالية فقط.\",\"p\":\"يا رب، أنت نوري وخلاصي. أنر عقلي وقلبي في كل قرار، ولا تدع الخوف يحجب عني طريقك. آمين.\"},{\"t\":\"الروح القدس يعلمكم كل شيء\",\"ref\":\"يوحنا ١٤: ٢٦\",\"bk\":\"يوحنا\",\"v\":\"وأما المعزي، الروح القدس، الذي سيرسله الآب باسمي، فهو يعلمكم كل شيء، ويذكركم بكل ما قلته لكم.\",\"r\":\"«وأما المعزي الروح القدس الذي سيرسله الآب باسمي فهو يعلمكم كل شيء ويذكركم بكل ما قلته لكم». يعدني المسيح أن كلماته لن تضيع. فالروح القدس يذكّرني بها في الوقت المناسب. وكم مرة جاءتني آية في لحظة احتياج! هذا هو عمل الروح.\",\"p\":\"يا روح الله المعزي، علّمني كل شيء وذكّرني بكلمات المسيح. اجعل قلبي مخزنًا لكلمتك، وذكّرني بها في كل احتياج، وأرشدني بها. آمين.\"},{\"t\":\"زيت السراج\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب أورسيسيوس القلب بسراج إن أهملنا الزيت انطفأ شيئًا فشيئًا وقويت عليه الظلمة. زيت النور هو الصلاة وحفظ القلب كل يوم. اكتب لنفسك اليوم عادة صغيرة تحفظ بها قلبك.\",\"p\":\"يا رب، املأ سراج قلبي بزيت نعمتك. علّمني أن أحفظ قلبي، فلا ينطفئ فيّ نورك. آمين.\",\"fq\":311}]},\"6-3\":{\"th\":\"الجسد المقدس\",\"m\":[{\"t\":\"من يسكن في مسكنك؟\",\"ref\":\"المزمور الرابع عشر — باكر\",\"v\":\"يا رب من يسكن في مسكنك. ومن يحل في جبل قدسك؟\",\"r\":\"يسأل المرنم من يستحق السكنى في بيت الله، فيجيب بالسلوك الذي لا عيب فيه والبر والحق في القلب. القداسة تشمل الجسد واللسان والقلب معًا. اختر اليوم عضوًا من جسدك تقدّسه لله، كعينك أو لسانك.\",\"p\":\"يا رب، قدّس جسدي وحواسي. اجعلني أسلك بلا عيب وأتكلم بالحق من قلبي، وأسكن في بيتك. آمين.\"},{\"t\":\"هذه هي إرادة الله قداستكم\",\"ref\":\"تسالونيكي الأولى ٤: ٣–٤\",\"bk\":\"تسالونيكي الأولى\",\"v\":\"لأن هذه هي إرادة الله: قداستكم. أن تمتنعوا عن الزنا، أن يعرف كل واحد منكم أن يقتني إناءه بقداسة وكرامة،\",\"r\":\"«لأن هذه هي إرادة الله قداستكم: أن تمتنعوا عن الزنا. أن يعرف كل واحد منكم أن يقتني إناءه بقداسة وكرامة». القداسة ليست نظرية بل تشمل الجسد والعلاقات. والله يريد لي كرامة، لا يحرمني. فالقيم التي يطلبها تحفظني وتحفظ من أحب.\",\"p\":\"يا رب، قدّسني. احفظ جسدي وعيني وفكري في طهارة وكرامة، وأعطني أن أقتني إنائي بقداسة، لأعيش إرادتك في كل شيء. آمين.\"},{\"t\":\"ضمير نقي تجاه القريب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوسف إن من لا يقدر على كل الجهادات يكفيه أن يحفظ ضميره نقيًا تجاه قريبه. القداسة تظهر في تعاملنا مع الناس. راجع ضميرك اليوم تجاه شخص واحد، وصحح ما يحتاج تصحيحًا.\",\"p\":\"يا رب، طهّر ضميري من كل ما يؤذي أخًا لي. أعطني أن أرى قريبي بعينك، وأعامله بطهارة. آمين.\",\"fq\":183}]},\"6-4\":{\"th\":\"زيارة المتألمين\",\"m\":[{\"t\":\"الرب سمع صوت بكائي\",\"ref\":\"المزمور السادس — باكر\",\"v\":\"لأن الرب قد سمع صوت بكائي. الرب سمع تضرعي، الرب لصلاتي قبل؛ فليخر وليضطرب جدا جميع أعدائي، وليرتدوا إلى ورائهم بالخزي سريعا جدا.\",\"r\":\"يعلن المرنم أن الرب سمع صوت بكائه وقبل صلاته. الله لا يهمل دمعة متألم، ونحن مدعوون أن نسمع معه. المتألمون حولنا يحتاجون من يجلس إلى جوارهم. اتصل اليوم بمريض أو حزين وأنصت إليه.\",\"p\":\"يا رب، اسمع صراخ كل متألم وعزّه. وأعطني قلبًا يرى المتألمين، ويدين تمتدان لراحتهم. آمين.\"},{\"t\":\"كنت مريضًا فزرتموني\",\"ref\":\"متى ٢٥: ٣٦\",\"bk\":\"متى\",\"v\":\"عريانا فكسوتموني. مريضا فزرتموني. محبوسا فأتيتم إلي.\",\"r\":\"«كنت عريانًا فكسوتموني. مريضًا فزرتموني. محبوسًا فأتيتم إليّ». لم يقل المسيح «كنتم تعبدون في الهيكل» بل ركّز على الرحمة العملية. وعندما أزور مريضًا أو أخدم محتاجًا، أخدمه هو. وهذا يعطي قيمة لكل لفتة صغيرة.\",\"p\":\"يا رب، علّمني أن أراك في وجه كل مريض ومحتاج. افتح قلبي لزيارة المتألمين، وأعطني حنانًا وانتباهًا، لأخدمك فيهم بفرح. آمين.\"},{\"t\":\"رأسه على ركبتي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إنه إذا رأى أخًا ينعس أسند رأسه على ركبته ليريحه. هكذا تكون الخدمة: لمسة صغيرة تحمل راحة حقيقية. ابحث اليوم عن تعب قريب منك، وقدّم له راحة بسيطة.\",\"p\":\"يا رب، علّمني الرحمة العملية. أعطني أن أريح أخًا متعبًا، وأخدمك فيه. آمين.\",\"fq\":379}]},\"6-5\":{\"th\":\"المحبة الأولى\",\"m\":[{\"t\":\"واحدة سألت\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"واحدة سألت من الرب وإياها التمس. أن أسكن في بيت الرب كل أيام حياتي. لكي أنظر نعيم الرب، وأتفرس في هيكله المقدس.\",\"r\":\"أراد المرنم شيئًا واحدًا: أن يسكن في بيت الرب وينظر نعيمه. هذه هي المحبة الأولى، شوق يسبق كل طلب. عُد اليوم إلى لحظة أول فرح لك بالمسيح، وسله أن يجدد ذلك الاشتياق.\",\"p\":\"يا رب، أعد إليّ محبتي الأولى. اجعل أعظم شوق في قلبي أن أكون في بيتك وأنظر نعيمك. آمين.\"},{\"t\":\"غيرة خطوبتك\",\"ref\":\"إرميا ٢: ٢\",\"bk\":\"إرميا\",\"v\":\"«اذهب وناد في أذني أورشليم قائلا: هكذا قال الرب: قد ذكرت لك غيرة صباك، محبة خطبتك، ذهابك ورائي في البرية في أرض غير مزروعة.\",\"r\":\"«قد ذكرت لك غيرة صباك، محبة خطبتك، ذهابك ورائي في البرية». الله يتذكر بدايتي معه بحنين. كانت لي حرارة في البداية، فهل حافظت عليها؟ وهو لا يعاتب فقط بل يشتاق. وهذه دعوة للرجوع: أن أستعيد حب البدايات.\",\"p\":\"يا رب، أذكر محبتي الأولى لك. أعد إليّ حرارة البدايات وشوق الخطبة، ولا تدع محبتي تفتر. أنت تتذكر غيرة صباي فأرجع إليك. آمين.\"},{\"t\":\"محبة تخفف الجهاد\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينقل إفاغريوس عن أحد الآباء أن أشد أنواع الحياة هو الذي يقترن بالمحبة، فيصل صاحبه سريعًا إلى ميناء السلام. المحبة تجعل الجهاد خفيفًا. قدّم اليوم عملًا صغيرًا بدافع الحب لا الواجب.\",\"p\":\"يا رب، اجعل جهادي كله محبة. علّمني أن أعمل بدافع الحب لك وللناس. آمين.\",\"fq\":113}]},\"6-6\":{\"th\":\"كلمة تثمر\",\"m\":[{\"t\":\"في حفظها ثواب عظيم\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"عبدك يحفظها. وفى حفظها ثواب عظيم.\",\"r\":\"كلمة الله لا تُحفظ في الذاكرة فقط، بل في الحياة. وعد الرب أنها لا ترجع فارغة بل تثمر. اقرأ اليوم آية واحدة وكرر قراءتها ثلاث مرات، ثم اسأل: ما الخطوة التي تطلبها مني؟\",\"p\":\"يا رب، ازرع كلمتك في قلبي فتثمر. أعطني أن أحفظها بالعمل، فأنال ثوابها الذي وعدت به. آمين.\"},{\"t\":\"لا ترجع إليّ فارغة\",\"ref\":\"إشعياء ٥٥: ١٠–١١\",\"bk\":\"إشعياء\",\"v\":\"لأنه كما ينزل المطر والثلج من السماء ولا يرجعان إلى هناك، بل يرويان الأرض ويجعلانها تلد وتنبت وتعطي زرعا للزارع وخبزا للآكل، هكذا تكون كلمتي التي تخرج من فمي. لا ترجع إلي فارغة، بل تعمل ما سررت به وتنجح في ما أرسلتها له.\",\"r\":\"«هكذا تكون كلمتي التي تخرج من فمي: لا ترجع إليّ فارغة، بل تعمل ما سررت به وتنجح في ما أرسلتها له». ثقة جميلة: كلمة الله تعمل حتى لو لم أر. فأنا أزرع الكلمة في قلبي وفي قلوب غيري، وأثق أنها لا تضيع.\",\"p\":\"يا رب، أشكرك على كلمتك التي لا ترجع فارغة. ازرعها في قلبي وقلوب إخوتي، وأعطني صبرًا لانتظار ثمرها، وثقة بأنها تعمل ما سررت به. آمين.\"},{\"t\":\"تأمل يثمر في الصلاة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب نيلوس إن كل ما تتأمل فيه صابرًا ستجني ثمره ساعة الصلاة. فالتأمل بذار، والصلاة موسم الحصاد. خصص اليوم عشر دقائق تتأمل فيها آية دون عجلة.\",\"p\":\"يا رب، علّمني الصبر في التأمل. اجعل كلمتك تتحول في قلبي صلاة ومحبة. آمين.\",\"fq\":292}]},\"6-7\":{\"th\":\"معرفة الله\",\"m\":[{\"t\":\"عرّفتني سبل الحياة\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"قد عرفتني سبل الحياة.\",\"r\":\"معرفة الله ليست معلومات بل طريق نسير فيه، وهو الذي يعرّفنا إياه. الاهتداء بنور وجهه يعطينا فرحًا لا تعطيه الأرض. اسأل الرب اليوم أن يكشف لك خطوة واحدة في سبيل الحياة.\",\"p\":\"يا رب، عرّفني سبل الحياة. اجعلني أعرفك أكثر كل يوم، وأسير معك بفرح. آمين.\"},{\"t\":\"لنعرف لنتتبع لنعرف الرب\",\"ref\":\"هوشع ٦: ٣\",\"bk\":\"هوشع\",\"v\":\"لنعرف فلنتتبع لنعرف الرب. خروجه يقين كالفجر. يأتي إلينا كالمطر. كمطر متأخر يسقي الأرض.\",\"r\":\"«فلنعرف ولنتتبع لنعرف الرب. خروجه يقين كالفجر ويأتي إلينا كالمطر». معرفة الله ليست حدثًا بل مسيرة: نتتبع لنعرف. وهو يأتي كالفجر والمطر: بيقين ونعمة. وأنا أستطيع أن أعتمد على هذا اليقين، فهو آتٍ كل يوم كالفجر.\",\"p\":\"يا رب، دعني أعرف وأتتبع لأعرفك. خروجك يقين كالفجر، فأتّكل على مجيئك كالمطر. زد معرفتي بك كل يوم، وثبّتني في تتبعك. آمين.\"},{\"t\":\"كلما اقتربنا رأينا ضعفنا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ماتوى إن الإنسان كلما دنا من الله رأى نفسه خاطئًا، وإشعياء لما رأى الله قال إنه دنس. المعرفة الحقيقية تقود إلى تواضع. قل لله اليوم بصدق: أنا أحتاجك.\",\"p\":\"يا رب، قرّبني إليك. وإذا رأيت ضعفي فاجعلني أرتمي في رحمتك لا في يأسي. آمين.\",\"fq\":269}]},\"6-8\":{\"th\":\"الأمان في الله\",\"m\":[{\"t\":\"الساكن في عون العلي\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"الساكن في عون العلي، يستريح في ظل إله السماء. يقول للرب أنت هو ناصري وملجأي، إلهي فأتكل عليه.\",\"r\":\"الأمان لا يقوم على قوتنا بل على من نسكن في ظله. يقول المرنم: أنت ناصري وملجأي. حين يشتد القلق اليوم، توقف وقل هذه العبارة بصوت منخفض ثلاث مرات.\",\"p\":\"يا رب، أنت ناصري وملجأي. أسكن في ظلك فلا أخاف، وأتكل عليك في كل أمر. آمين.\"},{\"t\":\"أضطجع بسلام\",\"ref\":\"المزامير ٤: ٨\",\"bk\":\"المزامير\",\"v\":\"بسلامة أضطجع بل أيضا أنام، لأنك أنت يا رب منفردا في طمأنينة تسكنني.\",\"r\":\"«بسلام أضطجع وأيضًا أنام، لأنك أنت يا رب منفردًا في طمأنينة تسكنني». قالها داود ضمن مرحلة ضيق. لم تتغير الظروف، لكن تغير قلبه. فالنوم بسلام ثمرة الثقة. وأنا أحتاج أن أنهي يومي بتسليمه، فأنام بطمأنينة.\",\"p\":\"يا رب، بسلام أضطجع وأنام لأنك تسكنني في طمأنينة. أسلّم لك يومي بكل ما فيه، واحفظني في الليل، وأيقظني بنشاط وشكر. آمين.\"},{\"t\":\"أنا والله فقط\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ألونيوس إن الإنسان إن لم يقل في قلبه: أنا والله فقط في العالم، لن يجد راحة. الراحة تبدأ حين أضع نفسي أمام الله وحده. خصص اليوم لحظة خلوة بلا مقارنات ولا انشغال بآراء الناس.\",\"p\":\"يا رب، أنت وحدك تكفيني. اجعلني أجد راحتي في حضورك، لا في رضا الناس. آمين.\",\"fq\":72}]},\"6-9\":{\"th\":\"غنى المسيح\",\"m\":[{\"t\":\"يرفع المسكين\",\"ref\":\"المزمور ١١٢ (١١٣) — باكر\",\"v\":\"المقيم المسكين من التراب، الرافع البائس من المزبلة لكي يجلسه مع رؤساء شعبه.\",\"r\":\"غنى المسيح أنه افتقر لأجلنا، فلا نحتاج أن نكون أغنياء لنكون مقبولين عنده. هو يرفع البائس ويجلسه مع الرؤساء. اشكره اليوم على غنى لا يُشترى بمال، وفكّر فيما تملكه فعلًا.\",\"p\":\"يا رب، أشكرك لأنك رفعتني من التراب. علّمني أن أعيش غنى نعمتك وأشارك الآخرين. آمين.\"},{\"t\":\"افتقر لأجلكم\",\"ref\":\"كورنثوس الثانية ٨: ٩\",\"bk\":\"كورنثوس الثانية\",\"v\":\"فإنكم تعرفون نعمة ربنا يسوع المسيح، أنه من أجلكم افتقر وهو غني، لكي تستغنوا أنتم بفقره.\",\"r\":\"«فإنكم تعرفون نعمة ربنا يسوع المسيح أنه من أجلكم افتقر وهو غني لكي تستغنوا أنتم بفقره». افتقر ليغنيني. هذه هي النعمة. وهي دافع لي أن أعطي بسخاء. فمن أخذ منه كل شيء يعطي بفرح.\",\"p\":\"يا رب يسوع، أنت افتقرت لأجلي لأستغني. أشكرك على نعمتك، واجعلني أعطي بسخاء وفرح، وأتشبه بك في بذل نفسي. آمين.\"},{\"t\":\"ثمن البر الرخيص\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس إبيفانيوس إن الله يبيع البر رخيصًا لمن يبادرون إلى شرائه: بقطعة خبز، أو كأس ماء بارد، أو فلس واحد. الله يقبل القليل بقلب كبير. أعطِ اليوم شيئًا بسيطًا لمحتاج.\",\"p\":\"يا رب، علّمني أن أشتري البر بعطية صغيرة. اجعل قلبي سخيًا كما أنت سخي. آمين.\",\"fq\":102}]},\"6-10\":{\"th\":\"صورة الله في الإنسان\",\"m\":[{\"t\":\"بالمجد والكرامة توجته\",\"ref\":\"المزمور الثامن — باكر\",\"v\":\"أنقصته قليلا عن الملائكة. بالمجد والكرامة توجته، وعلى أعمال يديك أقمته.\",\"r\":\"خلق الله الإنسان على صورته وكلّله بالمجد والكرامة. قيمتك ليست فيما تملك بل فيمن خلقك. تعامل اليوم مع نفسك ومع كل إنسان تقابله كصورة لله.\",\"p\":\"يا رب، توّجتني بالمجد والكرامة بنعمتك. اجعلني أحترم نفسي وإخوتي، وأرى فيهم مجدك. آمين.\"},{\"t\":\"على صورة الله خلقه\",\"ref\":\"التكوين ١: ٢٧\",\"bk\":\"التكوين\",\"v\":\"فخلق الله الإنسان على صورته. على صورة الله خلقه. ذكرا وأنثى خلقهم.\",\"r\":\"«فخلق الله الإنسان على صورته، على صورة الله خلقه، ذكرًا وأنثى خلقهم». كل إنسان أقابله يحمل صورة الله. وهذا يغير نظرتي: لا أحتقر ولا أستخف بأحد. وأنا أيضًا حامل لهذه الصورة، وأحتاج أن أحفظها نقية.\",\"p\":\"يا خالقي، أشكرك لأنك خلقتني على صورتك. علّمني أن أحترم كل إنسان كحامل صورتك، وأحفظ صورتي نقية، وأتجدد بالمسيح الصورة الكاملة. آمين.\"},{\"t\":\"صورتان\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: نحن وإخوتنا صورتان، فإذا انتبه الإنسان لنفسه ولامها وجد أخاه مكرّمًا في عينيه. احترام صورة الله في الغير يبدأ بتواضعنا. اختر اليوم شخصًا صعبًا وابحث عن شيء مكرَّم فيه.\",\"p\":\"يا رب، أعطني عينًا تكرّم إخوتي. حرّرني من النظر إلى نفسي صالحًا وإلى غيري شريرًا. آمين.\",\"fq\":423}]},\"6-11\":{\"th\":\"الثمر المطلوب\",\"m\":[{\"t\":\"طوبى للرجل\",\"ref\":\"المزمور الأول — باكر\",\"v\":\"طوبى للرجل الذي لم يسلك في مشورة المنافقين. وفى طريق الخطاة لم يقف. وفى مجلس المستهزئين لم يجلس.\",\"r\":\"يبدأ المزمور برفض ثلاث خطوات: مشورة المنافقين وطريق الخطاة ومجلس المستهزئين. الثمر يبدأ من اختيار الصحبة والطريق. افحص اليوم من يؤثر في أفكارك، وتخلَّ عن مشورة واحدة لا تبني.\",\"p\":\"يا رب، احفظني من مشورة الأشرار وطريقهم. اجعل لذتي في ناموسك، فأثمر في أوانه. آمين.\"},{\"t\":\"مثمرين في كل عمل صالح\",\"ref\":\"كولوسي ١: ١٠\",\"bk\":\"كولوسي\",\"v\":\"لتسلكوا كما يحق للرب، في كل رضى، مثمرين في كل عمل صالح، ونامين في معرفة الله،\",\"r\":\"«لتسلكوا كما يحق للرب، في كل رضى، مثمرين في كل عمل صالح، ونامين في معرفة الله». الثمر ليس مجهودًا لإثبات نفسي، بل نتيجة معرفة تنمو. كلما عرفت الله أكثر، صار عملي الصالح أصدق وأهدأ.\",\"p\":\"يا رب، علّمني أن أسلك كما يحق لك، وأثمر في كل عمل صالح، وأنمو في معرفتك كل يوم. آمين.\"},{\"t\":\"الشجرة والرياح\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم ثيوذورا إن الشجرة إذا لم تتعرض للرياح والعواصف لا تأتي بثمر، وكذلك نحن. الضيقات تعمق جذورنا. انظر اليوم إلى ضيق صغير كفرصة لإثمار صبر ومحبة.\",\"p\":\"يا رب، ثبّت جذوري فيك وسط الرياح. حوّل ضيقاتي إلى ثمر يمجدك. آمين.\",\"fq\":148}]},\"6-12\":{\"th\":\"فرح الرب قوتنا\",\"m\":[{\"t\":\"ليفرح جميع المتكلين\",\"ref\":\"المزمور الخامس — باكر\",\"v\":\"وليفرح جميع المتكلين عليك، إلى الأبد يسرون وتحل فيهم. ويفتخر بك كل الذين يحبون اسمك.\",\"r\":\"الفرح الحقيقي وعد للمتكلين على الرب، لا يتوقف على الظروف. فرح الرب قوتنا لأنه لا يُسلب. سجّل اليوم ثلاثة أسباب للفرح ولو كانت صغيرة، وقدّمها شكرًا لله.\",\"p\":\"يا رب، املأ قلبي فرحًا بك. اجعلني أفتخر باسمك وأتكل عليك في كل حال. آمين.\"},{\"t\":\"لا تحزنوا\",\"ref\":\"نحميا ٨: ١٠\",\"bk\":\"نحميا\",\"v\":\"فقال لهم: «اذهبوا كلوا السمين، واشربوا الحلو، وابعثوا أنصبة لمن لم يعد له، لأن اليوم إنما هو مقدس لسيدنا. ولا تحزنوا، لأن فرح الرب هو قوتكم».\",\"r\":\"«لا تحزنوا، لأن فرح الرب هو قوتكم». بكى الشعب حين سمعوا الشريعة، لكن القادة ردّوهم إلى الفرح. فالتوبة الحقيقية لا تتركني في الحزن، بل تفتح لي باب فرح الرب فيصير قوتي.\",\"p\":\"يا رب، حوّل حزني على خطاياي إلى فرح بغفرانك، واجعل فرحك قوتي في كل عمل. آمين.\"},{\"t\":\"شكر بدل الكبرياء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بطرس إنه لا ينبغي أن نتكبر حين يجري الرب أمرًا على أيدينا، بل نشكره لأنه أهّلنا. الفرح بالخدمة يكتمل بالشكر. إن نجح لك أمر اليوم فقل: يا رب هذا منك.\",\"p\":\"يا رب، أنت صاحب كل عمل صالح. حفظني من الكبرياء، وأعطني أن أنسب الفضل لك. آمين.\",\"fq\":472}]},\"6-13\":{\"th\":\"سلام لمحبي الشريعة\",\"m\":[{\"t\":\"الرب يبارك شعبه بالسلام\",\"ref\":\"المزمور ٢٨ (٢٩) — الثالثة\",\"v\":\"الرب يعطى شعبه قوة، الرب يبارك شعبه بالسلام.\",\"r\":\"السلام هبة يعطيها الرب لشعبه مع القوة. سلام بلا قوة هش، وقوة بلا سلام قاسية. اطلب اليوم من الرب سلامًا لموقف يضايقك، وأسلمه له.\",\"p\":\"يا رب، أعطني قوتك وسلامك. بارك بيتي وكنيستك بالسلام الذي لا يُنزع. آمين.\"},{\"t\":\"سلامة جزيلة\",\"ref\":\"المزامير ١١٩: ١٦٥\",\"bk\":\"المزامير\",\"v\":\"سلامة جزيلة لمحبي شريعتك، وليس لهم معثرة.\",\"r\":\"«سلامة جزيلة لمحبي شريعتك، وليس لهم معثرة». عندما أحب الوصية، لا أعود أراها قيدًا. وتصير مثل سياج يحميني من السقوط ويمنحني راحة. فأطلب اليوم أن أزداد حبًا لكلمته وصبرًا على العمل بها.\",\"p\":\"يا رب، علّمني أن أحب وصاياك. امنحني سلامة جزيلة، واحفظني من كل معثرة في طريقي. آمين.\"},{\"t\":\"هدوء الليل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بولس إن هدوء الليل يكفينا إذا كان ذهننا صاحيًا. فسلام الليل يحتاج ذهنًا هادئًا. قبل أن تنام الليلة، سلّم لله مخاوف يومك واحدة واحدة.\",\"p\":\"يا رب، اجعل ذهني صاحيًا وقلبي مطمئنًا. أعطني ليلة هادئة في حضورك. آمين.\",\"fq\":476}]},\"6-14\":{\"th\":\"هدوء القلب\",\"m\":[{\"t\":\"اشخصوا وانظروا\",\"ref\":\"المزمور ٤٥ (٤٦) — الثالثة\",\"v\":\"هلم فانظروا أعمال الرب، التي جعلها ايات على الأرض. الذي ينزع الحروب من أقاصي الأرض.\",\"r\":\"يدعونا المرنم أن ننظر أعمال الرب: ينزع الحروب من أقاصي الأرض. الهدوء ليس غياب الأحداث بل الثقة بمن يضبطها. اجلس اليوم خمس دقائق صامتًا، وتذكر ما صنعه الله معك.\",\"p\":\"يا رب، انزع الاضطراب من قلبي كما تنزع الحروب. علّمني أن أسكن وأعرف أنك أنت الله. آمين.\"},{\"t\":\"السكوت والانتظار\",\"ref\":\"مراثي إرميا ٣: ٢٦\",\"bk\":\"مراثي إرميا\",\"v\":\"جيد أن ينتظر الإنسان ويتوقع بسكوت خلاص الرب.\",\"r\":\"«جيد أن ينتظر الإنسان ويتوقع بسكوت خلاص الرب». لا أحتاج أن أشرح لله ألف مرة أو أضغط عليه بسرعة. بل أنتظر هادئًا لأنني أثق أن خلاصه آتٍ في وقته.\",\"p\":\"يا رب، علّمني أن أنتظرك بسكوت وثقة، وأن أرى خلاصك في وقتك. ثبّت قلبي في رجائك. آمين.\"},{\"t\":\"محبة الصمت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إنك إذا كنت محبًا للصمت تجد راحة أينما حللت. الصمت مكان لقاء، لا هروب. اجعل في يومك دقائق قليلة صمت كامل قبل النوم أو بعد الصلاة.\",\"p\":\"يا رب، علّمني أن أحب السكوت معك. أعطني قلبًا هادئًا في كل مكان. آمين.\",\"fq\":374}]},\"6-15\":{\"th\":\"انتظار الرب\",\"m\":[{\"t\":\"وأنت يا رب فإلى متى؟\",\"ref\":\"المزمور السادس — باكر\",\"v\":\"وأنت يا رب فإلي متى؟ عد ونج نفسي. وأحيني من أجل رحمتك.\",\"r\":\"يتساءل المرنم عن طول الانتظار، لكنه يطلب النجاة والإحياء من أجل الرحمة. الانتظار بيت الإيمان حين لا نرى الحل. اكتب الأمر الذي تنتظر فيه الله اليوم، وسلّمه له.\",\"p\":\"يا رب، عد ونجّ نفسي. أحيني من أجل رحمتك، وأعطني صبرًا أنتظرك به. آمين.\"},{\"t\":\"الذين ينتظرون\",\"ref\":\"المزامير ٣٧: ٩\",\"bk\":\"المزامير\",\"v\":\"لأن عاملي الشر يقطعون، والذين ينتظرون الرب هم يرثون الأرض.\",\"r\":\"«الذين ينتظرون الرب هم يرثون الأرض». قد أرى الشر يتقدم أحيانًا فأتعب. لكن الله يعدني أن من ينتظره يرث، فأثبت في الانتظار وأعمل الخير. فأهدأ وأترك الأمور في يد الله العادل وأثبت في الخير.\",\"p\":\"يا رب، أنتظرك بثقة. احفظني من الغيرة والقلق، وثبّتني في عمل الخير حتى ترثني ملكوتك. آمين.\"},{\"t\":\"اليوم فقط\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب بيمن من تأتيه التجربة ألا يسأل كم ستدوم، بل أن يقول: اليوم. الصبر يعيش يومًا بيوم. قل لنفسك الآن: اليوم فقط أحتمل بنعمة الله.\",\"p\":\"يا رب، علّمني أن أعيش يومي. أعطني نعمة أحتمل بها اليوم، وتُبقي الغد في يدك. آمين.\",\"fq\":404}]},\"6-16\":{\"th\":\"فرح القلب المستقر\",\"m\":[{\"t\":\"أسبح الرب المحسن إلي\",\"ref\":\"المزمور ١٢ (١٣) — باكر\",\"v\":\"أسبح الرب المحسن إلي، وأرتل لاسم الرب العلي.\",\"r\":\"يختم المرنم ضيقته بالتسبيح لأنه تذكر إحسان الله. القلب المستقر يتغذى بتذكر النعم. اختر اليوم نعمة صنعها الله معك ورتّل لها ترنيمة أو مزمورًا.\",\"p\":\"يا رب، أسبحك لأنك محسن إليّ. اجعل قلبي مستقرًا في ذكر نعمك، وفمي ممتلئًا بتسبيحك. آمين.\"},{\"t\":\"بظل جناحيك\",\"ref\":\"المزامير ٦٣: ٧\",\"bk\":\"المزامير\",\"v\":\"لأنك كنت عونا لي، وبظل جناحيك أبتهج.\",\"r\":\"«لأنك كنت عونًا لي، وبظل جناحيك أبتهج». حتى في البرية الجافة يجد داود فرحًا. وأنا أيضًا حين أقف في ظل الله أجد راحة لا تعطيها الظروف. فأعود إلى هذه الصورة كلما شعرت بالتعب أو الوحدة اليوم.\",\"p\":\"يا رب، كنت عونًا لي دائمًا. أحميني بظل جناحيك، وأعطني أن أبتهج بك في كل برية أمر بها. آمين.\"},{\"t\":\"ملك على أهوائه\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوسف إنه ملك اليوم لأنه ملك على أهوائه. الفرح الحقيقي في سلطان النفس على نفسها بنعمة الله. اجعل لك اليوم هدفًا صغيرًا: ضبط هوى واحد.\",\"p\":\"يا رب، أعطني أن أملك على أهوائي بنعمتك. فيمتلئ قلبي فرحًا في طاعتك. آمين.\",\"fq\":186}]},\"6-17\":{\"th\":\"التسبيح وسط الخسارة\",\"m\":[{\"t\":\"عظم الرب الصنيع معنا\",\"ref\":\"المزمور ١٢٥ (١٢٦) — الغروب\",\"v\":\"إذا ما رد الرب سبي صهيون صرنا فرحين. حينئذ امتلأ فمنا فرحا ولساننا تهليلا. حينئذ يقال في الأمم إن الرب قد عظم الصنيع معهم. عظم الرب الصنيع معنا فصرنا فرحين.\",\"r\":\"يتذكر المرنم رد السبي فيمتلئ فمه فرحًا. التسبيح يبدأ بالذاكرة حين لا نجد في الحاضر ما نشكر عليه. حين يخسر الإنسان شيئًا يتذكر ما صنعه الله قبلاً. اكتب اليوم ثلاث مرات أنقذك فيها الله.\",\"p\":\"يا رب، عظّمت الصنيع معنا فصرنا فرحين. ذكّرني بإحساناتك السابقة وسط كل خسارة. آمين.\"},{\"t\":\"مع ذلك أبتهج\",\"ref\":\"حبقوق ٣: ١٧\",\"bk\":\"حبقوق\",\"v\":\"فمع أنه لا يزهر التين، ولا يكون حمل في الكروم. يكذب عمل الزيتونة، والحقول لا تصنع طعاما. ينقطع الغنم من الحظيرة، ولا بقر في المذاود،\",\"r\":\"«فمع أنه لا يزهر التين، ولا يكون حمل في الكروم... فإني أبتهج بالرب». تخيّل أن تخسر كل مصدر رزق ثم تسبّح! هذا إيمان لا يتعلق بالعطايا بل بالمعطي نفسه.\",\"p\":\"يا رب، حتى لو نقصت كل الأشياء، أنت قوتي وخلاصي. علّمني أن أبتهج بك في كل حال. آمين.\"},{\"t\":\"لوم النفس يحمّل الشدائد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن الإنسان إذا لام نفسه صبر على الشدائد أينما كان. لوم النفس يخفف حدة الخسارة لأنه يرفع الاتهام عن الآخرين. بدلًا من لوم الظروف، قل: يا رب ماذا تريد أن أتعلم؟\",\"p\":\"يا رب، علّمني أن أقبل الشدة بروح التواضع. حوّل كل خسارة إلى درس يقربني إليك. آمين.\",\"fq\":382}]},\"6-18\":{\"th\":\"خير الله وثباتنا\",\"m\":[{\"t\":\"ذوقوا وانظروا\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"ذوقوا وانظروا ما أطيب الرب! طوبى للإنسان المتكل عليه.\",\"r\":\"يدعونا المرنم إلى اختبار صلاح الله لا الاكتفاء بالسماع. وطوبى لمن يتكل عليه. اختبر صلاح الله اليوم: اطلب منه شيئًا وانتبه لكيفية استجابته.\",\"p\":\"يا رب، ما أطيبك! أعطني أن أتذوق صلاحك كل يوم، وأتكل عليك في كل أمر. آمين.\"},{\"t\":\"بضيقات كثيرة\",\"ref\":\"أعمال الرسل ١٤: ٢٢\",\"bk\":\"أعمال الرسل\",\"v\":\"يشددان أنفس التلاميذ ويعظانهم أن يثبتوا في الإيمان، وأنه بضيقات كثيرة ينبغي أن ندخل ملكوت الله.\",\"r\":\"«بضيقات كثيرة ينبغي أن ندخل ملكوت الله». الإنجيل لا يعدني بحياة بلا ألم، بل بحضور الله في الألم. والتشجيع الحقيقي هو أن أعرف الطريق وأثبت. فأقبل الضيق بصبر لأنه جزء من الطريق الذي مشاه المسيح قبلي.\",\"p\":\"يا رب، ثبّتني في الإيمان في كل ضيق، وشدد نفوس إخوتي. وأدخلنا بنعمتك إلى ملكوتك. آمين.\"},{\"t\":\"علامة الراهب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن علامة الراهب تظهر في التجارب. وكلنا نُعرف في ساعة الضيق لا الرخاء. حين تأتيك مشكلة اليوم اجعلها فرصة لتظهر ثبات إيمانك.\",\"p\":\"يا رب، ثبتني في التجارب. اجعل ضيقاتي تظهر إيماني لا ضعفي. آمين.\",\"fq\":317}]},\"6-19\":{\"th\":\"الثبات في الرب\",\"m\":[{\"t\":\"إلهنا ملجأنا وقوتنا\",\"ref\":\"المزمور ٤٥ (٤٦) — الثالثة\",\"v\":\"إلهنا ملجأنا وقوتنا، ومعيننا في شدائدنا التي أصابتنا جدا. لذلك لا نخشى إذا تزعزعت الأرض، وانقلبت الجبال إلى قلب البحار.\",\"r\":\"يقول المرنم لا نخشى حتى لو تزعزعت الأرض. الثبات ليس غياب الاهتزاز بل وجود الملجأ. حين تضطرب اليوم أمام خبر أو موقف، كرر: إلهنا ملجأنا وقوتنا.\",\"p\":\"يا رب، أنت ملجأي وقوتي. ثبتني حين تهتز الأرض، ولا تدعني أخاف. آمين.\"},{\"t\":\"اسهروا واثبتوا\",\"ref\":\"كورنثوس الأولى ١٦: ١٣\",\"bk\":\"كورنثوس الأولى\",\"v\":\"اسهروا. اثبتوا في الإيمان. كونوا رجالا. تقووا.\",\"r\":\"«اسهروا. اثبتوا في الإيمان. كونوا رجالًا. تقووا». وصايا مختصرة كجنود على الحراسة. أحتاج أن أكون يقظًا في أفكاري، وثابتًا في إيماني، وشجاعًا في الشهادة. فأختار اليوم أن أكون واعيًا في كلماتي وقراراتي وصلواتي.\",\"p\":\"يا رب، علّمني أن أسهر وأثبت في الإيمان، وأكون شجاعًا وقويًا بنعمتك، وفي كل شيء بمحبة. آمين.\"},{\"t\":\"الطوب المطبوخ\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب أورسيسيوس الإنسان غير المنصهر بمخافة الله بطوب غير مطبوخ يتداعى سريعًا، أما المطبوخ فيصمد كالحجر. الثبات ينمو بالمخافة والاختبار. اطلب اليوم أن يطبخ الله فيك فضيلة واحدة بنار الصبر.\",\"p\":\"يا رب، اجعلني ثابتًا كالحجر في مخافتك. لا تدع أول ريح تهدمني. آمين.\",\"fq\":310}]},\"6-20\":{\"th\":\"تسبيح الفرح\",\"m\":[{\"t\":\"سبحوا الرب\",\"ref\":\"المزمور ١١٢ (١١٣) — باكر\",\"v\":\"سبحوا الرب أيها الفتيان، سبحوا اسم الرب. ليكن اسم الرب مباركا من الآن وإلى الأبد. من مشارق الشمس إلى مغاربها باركوا اسم الرب.\",\"r\":\"تبدأ التسبحة بدعوة الفتيان أن يسبحوا اسم الرب من مشارق الشمس إلى مغاربها. فرح التسبيح لا يعرف عمرًا ولا ساعة. رتّل اليوم ترنيمة بفرح، ولو في مكان بعيد عن الناس.\",\"p\":\"يا رب، ليكن اسمك مباركًا من الآن وإلى الأبد. اجعل التسبيح فرح قلبي في كل حين. آمين.\"},{\"t\":\"أفرح وأبتهج بك\",\"ref\":\"المزامير ٩: ٢\",\"bk\":\"المزامير\",\"v\":\"أفرح وأبتهج بك. أرنم لاسمك أيها العلي.\",\"r\":\"«أفرح وأبتهج بك. أرنم لاسمك أيها العلي». الفرح هنا موجّه إلى الله نفسه. وحين أركز على من هو، لا على ما عندي، تتسع نفسي وتنفتح للترنيم. فأشاركه الآن بكل قلبي، وأتذكر ما صنعه معي أمس.\",\"p\":\"يا رب، أحمدك بكل قلبي وأحدث بعجائبك. أفرح وأبتهج بك، وأرنم لاسمك العلي كل أيام حياتي. آمين.\"},{\"t\":\"ألا نفتر في التراتيل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ثيوذورس إننا إذا حوسبنا على كسلنا في الصلاة وفتورنا في التراتيل لا نخلص. الله يريد حرارة لا مجرد شكل. صلِّ اليوم صلاة قصيرة بكامل انتباهك.\",\"p\":\"يا رب، أبعد عني الفتور. أعطني حرارة الروح في صلاتي وتسبيحي. آمين.\",\"fq\":141}]},\"6-21\":{\"th\":\"التواضع والنعمة\",\"m\":[{\"t\":\"الناظر إلى المتواضعين\",\"ref\":\"المزمور ١١٢ (١١٣) — باكر\",\"v\":\"الساكن في الأعالي، الناظر إلى المتواضعين في السماء وعلى الأرض.\",\"r\":\"الرب عالٍ ومع ذلك ينظر إلى المتواضعين. التواضع ليس إنكار المواهب بل معرفة أن كل شيء نعمة. اعمل اليوم خدمة صغيرة دون أن يراك أحد، ودع الله وحده ينظر إليك.\",\"p\":\"يا رب، انظر إلى اتضاعي وارفعني في وقتك. أعطني نعمة التواضع كل يوم. آمين.\"},{\"t\":\"يعطي نعمة أعظم\",\"ref\":\"يعقوب ٤: ٦\",\"bk\":\"يعقوب\",\"v\":\"ولكنه يعطي نعمة أعظم. لذلك يقول: «يقاوم الله المستكبرين، وأما المتواضعون فيعطيهم نعمة».\",\"r\":\"«يقاوم الله المستكبرين، وأما المتواضعون فيعطيهم نعمة». أحيانًا أتعب لأنني أحاول أن أثبت نفسي، بينما النعمة تنتظر قلبًا فارغًا من الكبرياء. حين أنحني أمام الله أجد يده ممدودة لتسندني.\",\"p\":\"يا رب، أنزع من قلبي كل كبرياء، وعلّمني أن أقف أمامك متواضعًا لأنال نعمتك التي تسند ضعفي وتقودني. آمين.\"},{\"t\":\"التواضع الأصيل\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم ثيوذورا إنه لا النسك ولا السهر ولا أي وجع يخلّص الإنسان سوى التواضع الأصيل. التواضع هو الباب الذي تدخل منه النعمة. اطلب اليوم أن يعلّمك الله التواضع في موقف محدد.\",\"p\":\"يا رب، علّمني التواضع الأصيل. لا تدع جهادي يتحول إلى كبرياء. آمين.\",\"fq\":149}]},\"6-22\":{\"th\":\"رحمة الآب\",\"m\":[{\"t\":\"اذكر رأفاتك\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"اذكر يا رب رأفاتك ومراحمك. لأنها ثابتة منذ الأزل.\",\"r\":\"يطلب المرنم أن يذكر الله رأفاته ومراحمه الثابتة منذ الأزل. رحمة الله قديمة قدم الدهور ولا تتغير بتغيّر حالنا. ارفع اليوم صلاة طلب رحمة لنفسك ولمن أخطأوا إليك.\",\"p\":\"يا رب، اذكر رأفاتك ومراحمك. كن رحيمًا كما أنت رحيم، وعلّمني أن أرحم غيري. آمين.\"},{\"t\":\"كونوا رحماء\",\"ref\":\"لوقا ٦: ٣٦\",\"bk\":\"لوقا\",\"v\":\"فكونوا رحماء كما أن أباكم أيضا رحيم.\",\"r\":\"«كونوا رحماء كما أن أباكم أيضًا رحيم». الرحمة ليست عاطفة عابرة بل تشبّه بالله. وكلما رأيت كم احتملني، صار الصفح عن غيري أسهل على قلبي. وهكذا أصير صورة صغيرة لأبي السماوي في بيتي وعملي.\",\"p\":\"يا أبانا الرحيم، اجعلني رحيمًا كما أنت رحيم. علّمني الإحسان بلا انتظار، ونقِّ قلبي من الانتقام. آمين.\"},{\"t\":\"الرحيم يسكب مخافته\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أورسيسيوس إن الله الرحيم يسكب مخافته في من يغلبه الكسل قليلًا، فيقوّيه ليصحو. الرحمة تقيمنا لا تتركنا. إن تعثرت اليوم فلا تيأس، بل قم بسرعة.\",\"p\":\"يا رب، أيقظني من كسلي برحمتك. قوّني لأسهر وأحفظ نفسي حتى مجيئك. آمين.\",\"fq\":312}]},\"6-23\":{\"th\":\"محبة بلا رياء\",\"m\":[{\"t\":\"الشفاه الغاشة\",\"ref\":\"المزمور الحادي عشر — باكر\",\"v\":\"يستأصل الرب جميع الشفاه الغاشة، واللسان الناطق بالعظائم.\",\"r\":\"يعلن المرنم أن الرب يستأصل الشفاه الغاشة واللسان الناطق بالعظائم. المحبة بلا رياء كلام يطابق القلب. اختر اليوم أن تقول لشخص كلمة صادقة ومشجعة، لا مجاملة.\",\"p\":\"يا رب، احفظ لساني من الغش. اجعل كلامي صادقًا ومحبتي بلا رياء. آمين.\"},{\"t\":\"وادين بالمحبة\",\"ref\":\"رومية ١٢: ١٠\",\"bk\":\"رومية\",\"v\":\"وادين بعضكم بعضا بالمحبة الأخوية، مقدمين بعضكم بعضا في الكرامة.\",\"r\":\"«وادّين بعضكم بعضًا بالمحبة الأخوية، مقدمين بعضكم بعضًا في الكرامة». التكريم يعني أن أعطي لأخي مكانًا قبل نفسي. وهذا يتطلب قلبًا هادئًا لا يخاف على صورته. فأتدرب اليوم على أن أسبق غيري بالتحية والتقدير.\",\"p\":\"يا رب، علّمني محبة بلا رياء، وأن أقدم إخوتي في الكرامة، وأجد فرحي في خدمتهم. آمين.\"},{\"t\":\"أعطي القريب ما يحتاجه\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إننا سنعطي القريب ما هو بحاجة إليه، حتى لو كان ذلك لإرضاء الناس. المحبة العملية تقدم الحاجة قبل الحسابات. اسأل اليوم أحد المقربين: ماذا تحتاج؟\",\"p\":\"يا رب، علّمني المحبة التي تعطي. حرّرني من الحسابات الصغيرة التي تعطل رحمتي. آمين.\",\"fq\":349}]},\"6-24\":{\"th\":\"الغفران\",\"m\":[{\"t\":\"غفرت ذنب شعبك\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"حللت كل رجزك. رجعت عن سخط غضبك.\",\"r\":\"يتذكر المرنم أن الله أزال غضبه وسكن سخطه. الغفران الإلهي أساس غفراننا لبعضنا. فكر اليوم في شخص أخطأ إليك، وصلِّ من أجله بالاسم.\",\"p\":\"يا رب، كما غفرت لي أعطني أن أغفر. انزع المرارة من قلبي واملأه سلامك. آمين.\"},{\"t\":\"متسامحين كما سامحكم الله\",\"ref\":\"أفسس ٤: ٣٢\",\"bk\":\"أفسس\",\"v\":\"وكونوا لطفاء بعضكم نحو بعض، شفوقين متسامحين كما سامحكم الله أيضا في المسيح.\",\"r\":\"«كونوا لطفاء بعضكم نحو بعض، شفوقين، متسامحين كما سامحكم الله أيضًا في المسيح». عندما يصعب عليّ أن أسامح أتذكر كم سامحني الله. فمن غُفر له كثيرًا يقدر أن يغفر.\",\"p\":\"يا رب، سامحني كما أسامح، وانزع من قلبي كل مرارة، واجعلني لطيفًا شفوقًا متسامحًا كما سامحتني في المسيح. آمين.\"},{\"t\":\"سبعين مرة سبع مرات\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إنه إذا كان الله قد طلب من الإنسان أن يغفر لأخيه، فهو بالأحرى يفعل ذلك. فغفراننا صدى لغفرانه. اكتب اليوم اسم من تريد أن تسامحه وصلِّ له.\",\"p\":\"يا رب، أعطني قلبًا غافرًا. علّمني أن أغفر مهما تكرر الإساءة. آمين.\",\"fq\":375}]},\"6-25\":{\"th\":\"الأمانة في القليل\",\"m\":[{\"t\":\"لا يتزعزع إلى الأبد\",\"ref\":\"المزمور الرابع عشر — باكر\",\"v\":\"الذي يحلف لقريبه ولا يغدر به. ولا يعطى فضته بالربا، ولا يقبل الرشوة على الأبرياء. الذي يصنع هذا لا يتزعزع إلى الأبد.\",\"r\":\"يصف المرنم الأمين: الذي يحلف لقريبه ولا يغدر، ولا يأخذ الرشوة. الأمانة في القليل تُظهر من نحن. حافظ اليوم على موعد أو وعد صغير مهما كلّفك.\",\"p\":\"يا رب، اجعلني أمينًا في الصغير. احفظ كلمتي ووعودي، ولا تدعني أتزعزع. آمين.\"},{\"t\":\"أمينًا في القليل\",\"ref\":\"لوقا ١٩: ١٧\",\"bk\":\"لوقا\",\"v\":\"فقال له: نعما أيها العبد الصالح! لأنك كنت أمينا في القليل، فليكن لك سلطان على عشر مدن.\",\"r\":\"«نعمًا أيها العبد الصالح! لأنك كنت أمينًا في القليل، فليكن لك سلطان على عشر مدن». الأمانة في الأمور الصغيرة هي التي تُعدّني لما هو أكبر. فلا أحتقر عملًا صغيرًا ما دام لله.\",\"p\":\"يا رب، اجعلني أمينًا في القليل حتى تستأمنني على الكثير. لا أطلب سلطانًا بل أن أخدمك بإخلاص. آمين.\"},{\"t\":\"ضعف الخير\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إنك إذا صنعت قليلًا من الخير مع أخيك الصالح، فاجعل ضعفه للآخر لأنه المريض. الأمانة تهتم بالأضعف. أحسن اليوم إلى من يصعب الإحسان إليه.\",\"p\":\"يا رب، علّمني الأمانة في المحبة. اجعلني أسبق لمن يحتاج. آمين.\",\"fq\":366}]},\"6-26\":{\"th\":\"محبة تستر\",\"m\":[{\"t\":\"اغفر لي خطيتي\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"من أجل اسمك يا رب اغفر لي خطيتي لأنها كثيرة.\",\"r\":\"يصلي المرنم: من أجل اسمك اغفر لي خطيتي لأنها كثيرة. من يعرف مقدار ما غُفر له يستر على غيره. حين تسمع اليوم عن عثرة أخ، لا تنشرها بل صلِّ له.\",\"p\":\"يا رب، اغفر لي خطيتي واستر عليّ. علّمني أن أستر على إخوتي بمحبة. آمين.\"},{\"t\":\"طالب المحبة\",\"ref\":\"الأمثال ١٧: ٩\",\"bk\":\"الأمثال\",\"v\":\"من يستر معصية يطلب المحبة، ومن يكرر أمرا يفرق بين الأصدقاء.\",\"r\":\"«من يستر معصية يطلب المحبة، ومن يكرر أمرًا يفرق بين الأصدقاء». كل كلمة أعيدها عن عيب أحد قد تهدم علاقة. وبصمتي المحب أبني ما يهدمه الكلام. فأحفظ سر أخي وأطلب له الخير في صلاتي أمام الله.\",\"p\":\"يا رب، احفظ لساني من تكرار الأخطاء وتفريق الأصدقاء. علّمني أن أطلب المحبة وأستر بدل أن أنشر. آمين.\"},{\"t\":\"الله يكتم سقطاتنا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إننا في اللحظة التي نكتم فيها سقطة أخينا يكتم الله سقطاتنا. الستر استثمار في رحمة الله. قاوم اليوم رغبة الحديث عن خطأ آخر.\",\"p\":\"يا رب، استر علينا وعلى إخوتنا. احفظ لساني من كشف عيوب الآخرين. آمين.\",\"fq\":361}]},\"6-27\":{\"th\":\"كلمة في وقتها\",\"m\":[{\"t\":\"فاض قلبي بكلام صالح\",\"ref\":\"المزمور ٤٤ (٤٥) — الثالثة\",\"v\":\"فاض قلبي بكلام صالح. إني أخبر الملك بأفعالي، لساني قلم كاتب ماهر.\",\"r\":\"من فيض القلب يتكلم اللسان، وهو قلم كاتب ماهر في يد الله. الكلمة المناسبة في وقتها ثمر الصلاة. قبل أن تتكلم اليوم في موقف حساس، اطلب من الله أن يعطيك الكلمة.\",\"p\":\"يا رب، املأ قلبي بكلام صالح. واجعل لساني قلم كاتب ماهر يشهد لك. آمين.\"},{\"t\":\"فرح بجواب الفم\",\"ref\":\"الأمثال ١٥: ٢٣\",\"bk\":\"الأمثال\",\"v\":\"للإنسان فرح بجواب فمه، والكلمة في وقتها ما أحسنها!\",\"r\":\"«للإنسان فرح بجواب فمه، والكلمة في وقتها ما أحسنها!». ليست كل كلمة صحيحة تُقال في أي وقت. فحين أنتظر اللحظة المناسبة وأصلي قبل أن أتكلم، تصير كلماتي بلسمًا.\",\"p\":\"يا رب، ضع على فمي حارسًا، وعلّمني الكلمة في وقتها لأكون بركة لكل من يسمعني اليوم. آمين.\"},{\"t\":\"الصمت والكلام\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن هناك من يتكلم من الصباح للمساء لكنه صامت لأنه لا يتكلم إلا بنفع، وهناك من يصمت وقلبه يدين كثيرين. الكلام المفيد صمت حقيقي. اختر اليوم أن تتكلم بكلمة نافعة واحدة.\",\"p\":\"يا رب، علّمني متى أتكلم ومتى أصمت. ولتكن كلماتي نافعة وقلبي نقيًا. آمين.\",\"fq\":327}]},\"6-28\":{\"th\":\"مرساة الرجاء\",\"m\":[{\"t\":\"رجاء حصين\",\"ref\":\"المزمور ٦٠ (٦١) — السادسة\",\"v\":\"وبرجا حصينا في وجه العدو. فأسكن في مسكنك إلى الدهر، وأستظل بستر جناحيك.\",\"r\":\"يرى المرنم في الله رجاءه وبرجه الحصين في وجه العدو، ويسكن في مسكنه ويستظل بجناحيه. الرجاء مرساة للنفس وسط العواصف. اكتب اليوم عبارة رجاء تحملها في قلبك.\",\"p\":\"يا رب، أنت رجائي وبرجي الحصين. ثبّتني تحت ستر جناحيك، ولا تدعني أيأس. آمين.\"},{\"t\":\"إله الرجاء\",\"ref\":\"رومية ١٥: ١٣\",\"bk\":\"رومية\",\"v\":\"وليملأكم إله الرجاء كل سرور وسلام في الإيمان، لتزدادوا في الرجاء بقوة الروح القدس.\",\"r\":\"«وليملأكم إله الرجاء كل سرور وسلام في الإيمان، لتزدادوا في الرجاء بقوة الروح القدس». الرجاء ليس تفاؤلًا بل عطية. وحين أمتلئ من الروح القدس يصير الأمل في داخلي حيًا وإن ضاقت الظروف.\",\"p\":\"يا إله الرجاء، املأني سرورًا وسلامًا في الإيمان، وأفِض فيَّ الرجاء بقوة روحك القدوس كل يوم. آمين.\"},{\"t\":\"إن كان لك قلب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بمفو: إذا كان لك قلب يمكنك أن تخلص. القلب الحي هو أول الخلاص. اطلب اليوم قلبًا يحس ويصلي ويرجو.\",\"p\":\"يا رب، أعطني قلبًا حيًا. لا تدع اليأس يقسّيه، واجعل رجائي فيك ثابتًا. آمين.\",\"fq\":462}]},\"6-29\":{\"th\":\"تعزية الله\",\"m\":[{\"t\":\"يستجيب لك الرب\",\"ref\":\"المزمور ١٩ (٢٠) — الثالثة\",\"v\":\"يستجيب لك الرب في يوم شدتك. ينصرك اسم إله يعقوب. يرسل لك عونا من قدسه.\",\"r\":\"يعد المزمور بالاستجابة في يوم الضيق وبعون من القدس. التعزية ليست غياب الضيق بل حضور المعين. اذكر اليوم ضيقة تمر بها، وقل: يا رب أرسل لي عونًا.\",\"p\":\"يا رب، استجب لي في يوم شدتي. أرسل لي عونًا من قدسك وعزّني بروحك. آمين.\"},{\"t\":\"تكثر تعزيتنا\",\"ref\":\"كورنثوس الثانية ١: ٥\",\"bk\":\"كورنثوس الثانية\",\"v\":\"لأنه كما تكثر آلام المسيح فينا، كذلك بالمسيح تكثر تعزيتنا أيضا.\",\"r\":\"«كما تكثر آلام المسيح فينا، كذلك بالمسيح تكثر تعزيتنا أيضًا». لا يعدني الله بغياب الألم، بل بتعزية تفوقه. وكلما اشتد الحمل، اشتد حضوره بجواري. فأقبل عزاءه اليوم وأشارك به من يحتاج إليه حولي.\",\"p\":\"يا إله كل تعزية، عزّني في ضيقي، واجعلني أعزي غيري بنفس التعزية التي تعزيت بها منك. آمين.\"},{\"t\":\"الصلاة دواء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب نيلوس إن الصلاة دواء للفتور والأحزان. حين يثقل الحزن لا نصمت بل نصلي. صلِّ اليوم صلاة قصيرة حين يغلبك الحزن.\",\"p\":\"يا رب، اجعل صلاتي دوائي في الحزن والفتور. أعطني تعزيتك في كل ضيق. آمين.\",\"fq\":290}]},\"6-30\":{\"th\":\"الصبر من أجل الآخرين\",\"m\":[{\"t\":\"اللهم التفت إلى معونتي\",\"ref\":\"المزمور التاسع والستون — باكر\",\"v\":\"اللهم التفت إلى معونتي. يا رب أسرع وأعنى.\",\"r\":\"صلاة قصيرة تصلح للطريق كله: التفت إلى معونتي، أسرع وأعنّي. الصبر على الآخرين يحتاج معونة من فوق. حين يضايقك أحد اليوم، قل هذه الصلاة قبل أي رد فعل.\",\"p\":\"اللهم التفت إلى معونتي، يا رب أسرع وأعنّي. اجعلني صبورًا على إخوتي، رحيمًا في الرد. آمين.\"},{\"t\":\"مثال الأنبياء في الصبر\",\"ref\":\"يعقوب ٥: ١٠\",\"bk\":\"يعقوب\",\"v\":\"خذوا يا إخوتي مثالا لاحتمال المشقات والأناة: الأنبياء الذين تكلموا باسم الرب.\",\"r\":\"«خذوا يا إخوتي مثالًا لاحتمال المشقات والأناة الأنبياء الذين تكلموا باسم الرب». الصبر ليس ضعفًا بل طريق سار فيه الأنبياء قبلي. وإذا نظرت إلى عاقبة أيوب رأيت أن الرب رحيم ورؤوف، فأتشجع.\",\"p\":\"يا رب، اجعلني صابرًا كأيوب، واكشف لي عاقبتك الصالحة. فأنت رحيم ورؤوف في كل طرقك. آمين.\"},{\"t\":\"ألا تحزن أخاك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: اترك فكرك يجري، ألا يكفي ألا تحزن أخاك؟ أقل الواجب ألا نجرح أحدًا. اختر اليوم أن تتجنب كلمة جارحة واحدة.\",\"p\":\"يا رب، أعطني حكمة الصبر. احفظني من إحزان أي أخ، وعلّمني المحبة الطويلة. آمين.\",\"fq\":440}]},\"7-1\":{\"th\":\"نداء اتبعني\",\"m\":[{\"t\":\"سهّل طريقنا يا رب\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"يا رب سهل طريقنا. مبارك الآتي باسم الرب.\",\"r\":\"دعوة «اتبعني» تبدأ بخطوة صغيرة وتحتاج إلى طريق يسهّله الله. نتبع المسيح لأنه الآتي باسم الرب وهو الذي يسبقنا. اسأله اليوم أن يريك خطوة واحدة تتبعه فيها.\",\"p\":\"يا رب، سهّل طريقنا. أعطني أن أسمع ندائك وأتبعك بقلب مستعد، فأنت مبارك الآتي باسم الرب. آمين.\"},{\"t\":\"اتبعني\",\"ref\":\"يوحنا ١: ٤٣\",\"bk\":\"يوحنا\",\"v\":\"في الغد أراد يسوع أن يخرج إلى الجليل، فوجد فيلبس فقال له: «اتبعني».\",\"r\":\"«وجد فيلبس فقال له: اتبعني». لاحظ أن المسيح هو الذي وجد، لا فيلبس. الله يبحث عني قبل أن أبحث عنه، وكلمته لي بسيطة وواضحة: اتبعني. وعلي أن أجيب بخطوة عملية اليوم لا بمجرد شعور.\",\"p\":\"يا رب يسوع، أشكرك لأنك وجدتني ودعوتني. أعطني قلبًا يسمع صوتك ويجيبك بخطوة طاعة صادقة اليوم. آمين.\"},{\"t\":\"المكان الذي يقيم فيه الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"طلب أحد الآباء أن يرى القديسين فلم يجد الأب أنطونيوس بينهم، فقيل له إنه في المكان الذي يقيم فيه الله. من يتبع المسيح يقيم حيث يقيم. اجعل اليوم قلبك مكانًا يقيم فيه الله بالصلاة.\",\"p\":\"يا رب، اجعلني أقيم حيث تقيم أنت. وأعطني أن أتبعك بصدق، وأمكث في حضورك. آمين.\",\"fq\":15}]},\"7-2\":{\"th\":\"الاتباع الأمين\",\"m\":[{\"t\":\"لا يمنع الخيرات\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"الرب لا يمنع الخيرات عن السالكين بالدعة. يا رب إله القوات، طوبى للإنسان المتكل عليك.\",\"r\":\"الرب لا يمنع الخيرات عن السالكين بالدعة، وطوبى للمتكل عليه. الاتباع الأمين سير يومي دون التفات إلى الوراء. التزم اليوم بقرار واحد أجّلته، وتابع السير دون تردد.\",\"p\":\"يا رب إله القوات، طوبى للمتكل عليك. اجعلني أسلك بالدعة وأتبعك بأمانة، ولا ألتفت إلى الوراء. آمين.\"},{\"t\":\"لا ينظر إلى الوراء\",\"ref\":\"لوقا ٩: ٦٢\",\"bk\":\"لوقا\",\"v\":\"فقال له يسوع: «ليس أحد يضع يده على المحراث وينظر إلى الوراء يصلح لملكوت الله».\",\"r\":\"«ليس أحد يضع يده على المحراث وينظر إلى الوراء يصلح لملكوت الله». الحارث الذي يلتفت يعوّج خطّه. وأنا إذا ظللت أتأمل في أخطاء الماضي أو أمجاده، تعطلت خطواتي الجديدة مع الله.\",\"p\":\"يا رب، ثبّت عيني إلى الأمام نحوك. حررني من ثقل الماضي، وأعطني أن أتبعك بلا ارتداد ولا تأخير. آمين.\"},{\"t\":\"يكفيني أن أراك\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال أحد الآباء للأب أنطونيوس: يكفيني أن أراك يا أبت. الاتباع يبدأ بالوجود قرب من نحبه. اختر اليوم لحظة تجلس فيها في حضرة الله دون أن تطلب شيئًا.\",\"p\":\"يا رب، يكفيني أن أكون في حضرتك. علّمني أن أتبعك لأجل حبك لا لأجل عطاياك. آمين.\",\"fq\":14}]},\"7-3\":{\"th\":\"حمل الصليب\",\"m\":[{\"t\":\"الرب قد ملك على خشبة\",\"ref\":\"المزمور ٩٥ (٩٦) — التاسعة\",\"v\":\"قولوا بين الأمم إن الرب قد ملك على خشبة؛ وأيضا ثبت المسكونة فلن تتزعزع.\",\"r\":\"تقول الكنيسة بين الأمم إن الرب ملك على خشبة، فالصليب عرشه. حمل الصليب يعني أن نقبل الألم بروح المسيح. اسأل نفسك اليوم: ما الصليب الصغير الذي أهرب منه؟ احمله بصلاة.\",\"p\":\"يا رب، يا من ملكت على خشبة، علّمني أن أحمل صليبي كل يوم بفرح، وأتبعك حتى النهاية. آمين.\"},{\"t\":\"فلينكر نفسه\",\"ref\":\"مرقس ٨: ٣٤\",\"bk\":\"مرقس\",\"v\":\"ودعا الجمع مع تلاميذه وقال لهم: «من أراد أن يأتي ورائي فلينكر نفسه ويحمل صليبه ويتبعني.\",\"r\":\"«من أراد أن يأتي ورائي فلينكر نفسه ويحمل صليبه ويتبعني». الدعوة مفتوحة لمن يريد. ولا يجبرني أحد، لكن الطريق يمر بإنكار الأنا وبحمل صليب يومي أحبه لأنه يقودني إليه.\",\"p\":\"يا رب، علّمني أن أنكر ذاتي وأحمل صليبي كل يوم، وأتبعك بفرح الذي يعرف أن الصليب طريق القيامة. آمين.\"},{\"t\":\"الخطيئة أمام العينين\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أنطونيوس إن قوة الإنسان الكبرى أن يضع خطيئته نصب عينيه أمام الله وينتظر التجربة حتى النسمة الأخيرة. حمل الصليب يبدأ بصدق مع النفس. اعترف اليوم بضعف واحد أمام الله.\",\"p\":\"يا رب، اكشف لي ضعفي بلطف، وقوّني أن أحمل صليبي بتواضع حتى آخر نسمة. آمين.\",\"fq\":403}]},\"7-4\":{\"th\":\"الخدمة كمثال\",\"m\":[{\"t\":\"انظر إلي وارحمني\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"انظر إلي وارحمني. أعط عزة لعبدك. وخلص ابن أمتك.\",\"r\":\"يصلي المرنم: انظر إلي وارحمني، أعط عزة لعبدك. الخادم الحقيقي يطلب قوة من الله قبل أن يعطي غيره. قبل أن تخدم اليوم، قل له: أعطني ما أقدمه لهم.\",\"p\":\"يا رب، انظر إلي وارحمني. أعطني عزة لأخدم إخوتي، وعلّمني أن أكون خادمًا كما فعلت أنت. آمين.\"},{\"t\":\"أعطيتكم مثالًا\",\"ref\":\"يوحنا ١٣: ١٥\",\"bk\":\"يوحنا\",\"v\":\"لأني أعطيتكم مثالا، حتى كما صنعت أنا بكم تصنعون أنتم أيضا.\",\"r\":\"«أعطيتكم مثالًا، حتى كما صنعت أنا بكم تصنعون أنتم أيضًا». المسيح لا يكتفي بالتعليم، بل يفعل أمامنا. غسل أرجل تلاميذه، ومنهم من سينكره ومن سيسلمه. وأنا أُدعى أن أخدم بلا تمييز.\",\"p\":\"يا رب، علّمني أن أخدم كما خدمت أنت. اجعلني متواضعًا أنحني لإخوتي بلا تمييز ولا انتظار شكر. آمين.\"},{\"t\":\"الإحسان ولو لإرضاء الناس\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سارة إنه يحسن بالبشر أن يتصدقوا ولو كان السبب إرضاء الناس، لأن الإحسان يحقق إرضاء الله. الخدمة تعلّمنا حتى حين تكون النية ناقصة. قدّم اليوم عطاءً بسيطًا لمحتاج.\",\"p\":\"يا رب، طهّر نيّتي في العطاء والخدمة. وارحمني حين أعطي بغير محبة كاملة، وعلّمني أن أعطي لك. آمين.\",\"fq\":530}]},\"7-5\":{\"th\":\"مواهب الروح\",\"m\":[{\"t\":\"عظيمة هي أعمال الرب\",\"ref\":\"المزمور ١١٠ (١١١) — التاسعة\",\"v\":\"عظيمة هي أعمال الرب، ومشيئاته كلها مفحوصة: جلال وبهاء عمله؛ وعدله دائم إلى أبد الأبد. صنع ذكرا لجميع عجائبه.\",\"r\":\"يتأمل المرنم في أعمال الرب وعجائبه فيعترف بجلالها. المواهب التي فينا من أعماله هو، وهي لخدمة الجميع. اذكر اليوم موهبة وهبك الله إياها، واستخدمها في عمل صغير لإخوتك.\",\"p\":\"يا رب، عظيمة هي أعمالك. شكرًا على مواهبي، وعلّمني أن أستخدمها لمجدك ولخدمة إخوتي. آمين.\"},{\"t\":\"ليتمجد الله في كل شيء\",\"ref\":\"بطرس الأولى ٤: ١١\",\"bk\":\"بطرس الأولى\",\"v\":\"إن كان يتكلم أحد فكأقوال الله. وإن كان يخدم أحد فكأنه من قوة يمنحها الله، لكي يتمجد الله في كل شيء بيسوع المسيح، الذي له المجد والسلطان إلى أبد الآبدين. آمين.\",\"r\":\"«إن كان يتكلم أحد فكأقوال الله. وإن كان يخدم أحد فكأنه من قوة يمنحها الله، لكي يتمجد الله في كل شيء». موهبتي ليست ملكي، بل أمانة. والقوة التي أخدم بها هي من الله، فلا أفتخر بل أشكر.\",\"p\":\"يا رب، اجعل كل كلمة وكل خدمة مني لمجد اسمك. أعطني قوتك، ولا تدعني أنسب شيئًا لنفسي. آمين.\"},{\"t\":\"قليل من كل الفضائل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن الإنسان الذي يبني بيتًا بمن يجمع طاقات كثيرة، فنحن علينا أن نأخذ قليلًا من كل الفضائل. المواهب تنمو بالتكامل. اختر اليوم فضيلة لم تمارسها واعمل فيها خطوة صغيرة.\",\"p\":\"يا رب، ابنِ فيّ بنيانًا كاملًا. أعطني من كل فضيلة نصيبًا، وبارك مواهبي. آمين.\",\"fq\":407}]},\"7-6\":{\"th\":\"الحصاد الكثير\",\"m\":[{\"t\":\"أرضنا تعطي ثمرها\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"والبر من السماء تطلع. لأن الرب يعطى الخيرات، وأرضنا تعطى ثمرها.\",\"r\":\"الرب يعطي الخيرات والأرض تعطي ثمرها. الحصاد وعد من الله لا أمر نصنعه وحدنا. افحص اليوم ما زرعته من صلاة أو خدمة، وابتهج بالثمر الذي يعدك الله به.\",\"p\":\"يا رب، أنت تعطي الخيرات وأرضنا تعطي ثمرها. ابعث فعلة إلى حصادك وأعطني أن أكون واحدًا منهم. آمين.\"},{\"t\":\"تحنن عليهم\",\"ref\":\"متى ٩: ٣٦\",\"bk\":\"متى\",\"v\":\"ولما رأى الجموع تحنن عليهم، إذ كانوا منزعجين ومنطرحين كغنم لا راعي لها.\",\"r\":\"«ولما رأى الجموع تحنن عليهم». النظر ينتج الحنان، والحنان ينتج الخدمة. أحيانًا لا أخدم لأنني لا أنظر حقًا إلى من حولي. فأطلب من المسيح أن يعطيني عينيه وقلبه.\",\"p\":\"يا رب، افتح عيني لأرى كما ترى، وحرك قلبي بحنانك لأخدم المتعبين والمشتتين حولي بمحبة صادقة. آمين.\"},{\"t\":\"أي فضيلة ننشد؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أنطونيوس إن من يضرب الحديد يفكر أولًا ماذا يصنع منه، منجلًا أم فأسًا. الحصاد يحتاج هدفًا واضحًا. حدد اليوم فضيلة واحدة تجاهد فيها كي لا تتعب عبثًا.\",\"p\":\"يا رب، علّمني أن أعرف هدف جهادي. اجعل تعبي مثمرًا لا عبثًا. آمين.\",\"fq\":19}]},\"7-7\":{\"th\":\"الثبات والثمر\",\"m\":[{\"t\":\"كجبل صهيون\",\"ref\":\"المزمور ١٢٤ (١٢٥) — الغروب\",\"v\":\"المتوكلون على الرب مثل جبل صهيون لا يتزعزع إلى الأبد.\",\"r\":\"المتكلون على الرب مثل جبل صهيون لا يتزعزع إلى الأبد. من يثبت في الكرمة يثمر. اختر اليوم أن تثبت في الصلاة عشر دقائق قبل كل عمل.\",\"p\":\"يا رب، ثبّتني فيك كالكرمة. اجعلني متكلًا عليك فلا أتزعزع، وأثمر لك ثمرًا يدوم. آمين.\"},{\"t\":\"إن ثبتم فيّ\",\"ref\":\"يوحنا ١٥: ٧\",\"bk\":\"يوحنا\",\"v\":\"إن ثبتم في وثبت كلامي فيكم تطلبون ما تريدون فيكون لكم.\",\"r\":\"«إن ثبتم فيّ وثبت كلامي فيكم، تطلبون ما تريدون فيكون لكم». الثبات يغيّر ما أريده. وكلما ثبتُّ فيه صارت رغباتي أقرب إلى رغباته، فتصير صلاتي مستجابة. فأقرأ كلمته اليوم لأنها غذاء ثباتي.\",\"p\":\"يا رب يسوع، ثبّتني فيك وثبّت كلمتك فيّ. اجعل رغباتي موافقة لرغباتك، واستجب صلاتي بحسب إرادتك. آمين.\"},{\"t\":\"لم أترك فكرًا يغضب الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"سُئل الأب سلوان عن نسكه فأجاب أنه لم يترك في قلبه فكرًا يغضب الله. الثبات في المسيح يبدأ من الأفكار. راقب اليوم فكرًا واحدًا يتكرر عليك، وأسلمه لله.\",\"p\":\"يا رب، احفظ أفكاري. طهّر ذهني، واجعل قلبي مسكنًا لك. آمين.\",\"fq\":512}]},\"7-8\":{\"th\":\"أرسلكم أنا\",\"m\":[{\"t\":\"الرب يحفظ دخولك وخروجك\",\"ref\":\"المزمور ١٢٠ (١٢١) — الغروب\",\"v\":\"الرب يحفظ نفسك. الرب يحفظ دخولك وخروجك.\",\"r\":\"الإرسال لا يعني أن نذهب وحدنا، فالرب يحفظ دخولنا وخروجنا. ثق بأنه معك حيث يرسلك. حين تخرج اليوم من بيتك قل: أنا مرسل منه.\",\"p\":\"يا رب، احفظ نفسي ودخولي وخروجي. أرسلني حيث تريد، وكن معي في كل خطوة. آمين.\"},{\"t\":\"حكماء كالحيات\",\"ref\":\"متى ١٠: ١٦\",\"bk\":\"متى\",\"v\":\"«ها أنا أرسلكم كغنم في وسط ذئاب، فكونوا حكماء كالحيات وبسطاء كالحمام.\",\"r\":\"«ها أنا أرسلكم كغنم في وسط ذئاب، فكونوا حكماء كالحيات وبسطاء كالحمام». الحكمة بلا بساطة تصير مكرًا، والبساطة بلا حكمة تصير سذاجة. وأنا أحتاج الاثنين معًا في تعاملي.\",\"p\":\"يا رب، امنحني حكمة الفطنة وبساطة الحمام. احفظني من الخبث ومن السذاجة، وقدني بروحك في كل خطوة. آمين.\"},{\"t\":\"أن تبقى\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول أحد الآباء: إذا ذهبت يقولون لك أنطونيوس، أما إذا بقيت فيقولون الأب أنطونيوس. الإرسال يحتاج إلى ثبات في المكان. التزم اليوم بما أوكل إليك دون أن تنتقل من عمل إلى آخر.\",\"p\":\"يا رب، علّمني أن أثبت في إرساليتي. أعطني صبرًا في مكاني حتى أثمر. آمين.\",\"fq\":16}]},\"7-9\":{\"th\":\"شجاعة الشهادة\",\"m\":[{\"t\":\"لا تخشى من خوف الليل\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"فلا تخشى من خوف الليل، ولا من سهم يطير في النهار. ولا من أمر يسلك في الظلمة. ولا من سقطة وشيطان الظهيرة.\",\"r\":\"يعد المزمور بحفظ من خوف الليل وسهم النهار وسقطة الظهيرة. الشهادة تحتاج شجاعة من لا يخاف. اكتب اليوم الخوف الذي يمنعك من الشهادة، وسلّمه للرب.\",\"p\":\"يا رب، احفظني من كل خوف. أعطني جرأة أن أشهد لك بحياتي وبكلامي. آمين.\"},{\"t\":\"عرفوهما أنهما كانا مع يسوع\",\"ref\":\"أعمال الرسل ٤: ١٣\",\"bk\":\"أعمال الرسل\",\"v\":\"فلما رأوا مجاهرة بطرس ويوحنا، ووجدوا أنهما إنسانان عديما العلم وعاميان، تعجبوا. فعرفوهما أنهما كانا مع يسوع.\",\"r\":\"«فعرفوهما أنهما كانا مع يسوع». أعظم شهادة ليست علمي أو فصاحتي، بل أن يرى الناس فيّ أثر لقائي بالمسيح. فأنا مدعو أن أقضي وقتًا معه ليظهر فيّ. ولهذا أطلب الجلوس معه كل يوم قبل أن أنطلق.\",\"p\":\"يا رب، اجعلني قريبًا منك حتى يعرف الناس أنني معك. املأني من روحك لأشهد بجرأة وتواضع. آمين.\"},{\"t\":\"أنت مجنون\",\"ref\":\"\",\"v\":\"\",\"r\":\"يتنبأ القديس أنطونيوس أن الناس سيصيرون مجانين، وإن رأوا إنسانًا عاقلًا قالوا له أنت مجنون لأنه يختلف عنهم. الشهادة تعني أحيانًا أن نكون مختلفين. اثبت اليوم على قيمة مسيحية واحدة رغم ضغط الجماعة.\",\"p\":\"يا رب، ثبتني على الحق ولو خالفت الناس. اجعلني شاهدًا بهدوء ومحبة. آمين.\",\"fq\":13}]},\"7-10\":{\"th\":\"انتظار القوة\",\"m\":[{\"t\":\"رتب مصاعد في قلبه\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"طوبى للرجل الذي نصرته من عندك يا رب، رتب مصاعد في قلبه. في وادي البكاء، في المكان الذي قرره.\",\"r\":\"الإنسان الذي نصرته من عند الله يرتب مصاعد في قلبه حتى في وادي البكاء. انتظار القوة صعود خطوة خطوة. اطلب اليوم قوة لمهمة بعينها، ثم ابدأ بها واثقًا.\",\"p\":\"يا رب، رتّب في قلبي مصاعد نحوك. قوّني في وادي البكاء، وانتظرني حتى أنال قوتك. آمين.\"},{\"t\":\"موعد الآب\",\"ref\":\"أعمال الرسل ١: ٤\",\"bk\":\"أعمال الرسل\",\"v\":\"وفيما هو مجتمع معهم أوصاهم أن لا يبرحوا من أورشليم، بل ينتظروا «موعد الآب الذي سمعتموه مني،\",\"r\":\"«أوصاهم أن لا يبرحوا من أورشليم، بل ينتظروا موعد الآب». الانتظار لا يعني الفراغ بل الاستعداد. والرب لا يريدني أن أعمل بقوتي، بل أن أنتظر قوته. فالله يعد ولا يخلف.\",\"p\":\"يا رب، علّمني أن أنتظرك بصبر، وأن أطلب قوة روحك القدوس قبل أن أنطلق في أي عمل. آمين.\"},{\"t\":\"أعطني القوة\",\"ref\":\"\",\"v\":\"\",\"r\":\"صلاة الأم سارة قصيرة جدًا: يا الله أعطني القوة. القوة تأتي حين نعترف بضعفنا. كرر هذه الصلاة اليوم كلما شعرت بالتعب.\",\"p\":\"يا الله، أعطني القوة. لا تتركني لضعفي، بل اسكب روحك عليّ. آمين.\",\"fq\":525}]},\"7-11\":{\"th\":\"اعتراف الإيمان\",\"m\":[{\"t\":\"في مجلس المستقيمين\",\"ref\":\"المزمور ١١٠ (١١١) — التاسعة\",\"v\":\"في مجلس المستقيمين وفي مجمعهم.\",\"r\":\"الاعتراف بالإيمان يعلن بالفم ويصدّق بالقلب، في مجلس المستقيمين وفي مجمعهم. قل اليوم بصوت منخفض ما تؤمن به عن المسيح، وكن صادقًا في كل كلمة.\",\"p\":\"يا رب، أعترف لك من كل قلبي أنك ابن الله. ثبّت إيماني ولا تدعني أخجل باسمك. آمين.\"},{\"t\":\"اعتراف الفم وإيمان القلب\",\"ref\":\"رومية ١٠: ٩\",\"bk\":\"رومية\",\"v\":\"لأنك إن اعترفت بفمك بالرب يسوع، وآمنت بقلبك أن الله أقامه من الأموات، خلصت.\",\"r\":\"«إن اعترفت بفمك بالرب يسوع، وآمنت بقلبك أن الله أقامه من الأموات، خلصت». الإيمان ليس شعورًا مخبأ في القلب فقط، ولا كلمات بلا قلب. أحتاج أن يتوافق ما في داخلي مع ما أقوله وأعيشه أمام الناس.\",\"p\":\"يا رب يسوع، أؤمن بقلبي أنك قمت من الأموات، وأعترف بفمي أنك ربي ومخلصي. اجعل حياتي كلها شهادة لهذا الإيمان. آمين.\"},{\"t\":\"أمام الله الذي يفحص القلوب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أفرام: إذا كنا نستحي من الناس فكم بالحري ينبغي أن نخجل من الله الذي يفحص خفايا القلوب. الاعتراف الحقيقي أمام الله. راجع اليوم فكرًا تخجل أن يراه الناس، وقدمه لله بصدق.\",\"p\":\"يا رب، يا فاحص القلوب، طهّر ما في داخلي. أعطني مخافتك وصدق الاعتراف. آمين.\",\"fq\":103}]},\"7-12\":{\"th\":\"الرسولان بطرس وبولس\",\"m\":[{\"t\":\"رأس الزاوية\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"الحجر الذي رذله البناءون هذا صار رأسا للزاوية. من قبل الرب كان هذا وهو عجيب في أعيننا.\",\"r\":\"الحجر الذي رذله البناءون صار رأس الزاوية، وهذا عجيب في أعيننا. على هذا الأساس بُنيت الكنيسة بشهادة بطرس وبولس. فكر اليوم في ثبات إيمانك على المسيح الحجر الحي.\",\"p\":\"يا رب، أنت الحجر رأس الزاوية. ابنِ حياتي عليك كما بنيت كنيستك على إيمان رسلك. آمين.\"},{\"t\":\"جاهدت الجهاد الحسن\",\"ref\":\"تيموثاوس الثانية ٤: ٧\",\"bk\":\"تيموثاوس الثانية\",\"v\":\"قد جاهدت الجهاد الحسن، أكملت السعي، حفظت الإيمان،\",\"r\":\"«قد جاهدت الجهاد الحسن، أكملت السعي، حفظت الإيمان». لم يقل بولس أنه انتصر بقوته، بل أنه جاهد وحفظ. وأنا أيضًا أُدعى للأمانة حتى النهاية، فالأمانة هي مقياس الجهاد الحسن.\",\"p\":\"يا رب، أعطني أن أجاهد الجهاد الحسن وأحفظ الإيمان، وأكمل السعي بنعمتك حتى أنال إكليل البر مع جميع محبي ظهورك. آمين.\"},{\"t\":\"احصوا الأميال\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بنيامين: اسلكوا الطريق الملوكي واحصوا الأميال ولا تكونوا غير مبالين. أكمل بولس السعي وحفظ الإيمان بمثل هذا الانتباه. حدد اليوم ميلًا روحيًا تقطعه: صلاة أو قراءة أو خدمة.\",\"p\":\"يا رب، علّمني أن أسعى بانتباه. أعطني أن أكمل السعي وأحفظ الإيمان كرسلك. آمين.\",\"fq\":85}]},\"7-13\":{\"th\":\"الكنيسة بيت روحي\",\"m\":[{\"t\":\"يوم في ديارك\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"لأن يوما صالحا في ديارك خير من آلاف. اخترت لنفسي أن أطرح على باب بيت الله، أفضل من أن أسكن في مظال الخطاة.\",\"r\":\"يوم واحد في بيت الله خير من آلاف، والمرنم يفضل أن يطرح على بابه. الكنيسة بيت روحي نبنى فيه حجارة حية. اذهب اليوم إلى الكنيسة أو صلِّ فيها قليلًا إن استطعت.\",\"p\":\"يا رب، ما أحلى بيتك. اجعلني حجرًا حيًا في كنيستك، وأعطني حب الاجتماع فيها. آمين.\"},{\"t\":\"أساس الرسل\",\"ref\":\"أفسس ٢: ٢٠\",\"bk\":\"أفسس\",\"v\":\"مبنيين على أساس الرسل والأنبياء، ويسوع المسيح نفسه حجر الزاوية،\",\"r\":\"«مبنيين على أساس الرسل والأنبياء، ويسوع المسيح نفسه حجر الزاوية». لست وحدي في إيماني، بل أنا جزء من بناء بدأ منذ قرون. وكل حجر يستمد ثباته من حجر الزاوية الذي يحمل البناء كله.\",\"p\":\"يا رب، أشكرك على الكنيسة التي بنيتها على أساس الرسل. ثبّتني حجرًا حيًا فيها، وليكن المسيح حجر زاويتي. آمين.\"},{\"t\":\"عمل الحياة المشتركة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن الحياة المشتركة تحتاج إلى عمل التواضع وعمل الطاعة وعمل الحياة المشتركة نفسه. الكنيسة جماعة تحتاج أعضاء متضعين. ساهم اليوم بعمل في كنيستك أو أسرتك دون أن تطلب شكرًا.\",\"p\":\"يا رب، علّمني التواضع والطاعة في الجماعة. اجعلني عضوًا نافعًا في جسدك. آمين.\",\"fq\":388}]},\"7-14\":{\"th\":\"كلمة الله\",\"m\":[{\"t\":\"أعطى طعامه لأتقيائه\",\"ref\":\"المزمور ١١٠ (١١١) — التاسعة\",\"v\":\"رحيم هو الرب ورؤوف. أعطى طعامه لأتقيائه: يذكر إلى الدهر ميثاقه.\",\"r\":\"الرب رحيم ورؤوف، وأعطى طعامه لأتقيائه ويذكر ميثاقه. كلمة الله طعام للنفس مثل الخبز للجسد. اقرأ اليوم فصلًا من الإنجيل قبل أي شيء آخر.\",\"p\":\"يا رب، أطعمني من كلمتك. أعطني أن أسمعها بإيمان، فتصير حياة في قلبي. آمين.\"},{\"t\":\"الإيمان بالخبر\",\"ref\":\"رومية ١٠: ١٧\",\"bk\":\"رومية\",\"v\":\"إذا الإيمان بالخبر، والخبر بكلمة الله.\",\"r\":\"«إذًا الإيمان بالخبر، والخبر بكلمة الله». كيف أنمو في إيماني؟ بأن أسمع كلمة الله وأقرأها وأتأملها باستمرار. فالإيمان يتغذى من الكلمة كما يتغذى الجسد من الطعام، ولا يعيش بالحماس العابر وحده.\",\"p\":\"يا رب، افتح أذني وقلبي لكلمتك، واجعل إيماني ينمو بسماعها ليصير حياة وثمرًا في كل أيامي. آمين.\"},{\"t\":\"احفظ الإنجيل\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب مكاريوس أخًا تحاربه الأفكار أن يحفظ الإنجيل والأسفار عن ظهر قلب، وأن يوجه أبصاره إلى العلاء. الكلمة المحفوظة سلاح وقت الضيق. احفظ اليوم آية واحدة تلجأ إليها.\",\"p\":\"يا رب، اكتب كلمتك على قلبي. أعطني أن أرددها في التجربة فتنتصر فيّ. آمين.\",\"fq\":234}]},\"7-15\":{\"th\":\"جماعة تصلي\",\"m\":[{\"t\":\"ادخلوا دياره\",\"ref\":\"المزمور ٩٥ (٩٦) — التاسعة\",\"v\":\"احملوا الذبائح وادخلوا دياره، اسجدوا للرب في دياره المقدسة.\",\"r\":\"يدعونا المرنم أن نحمل الذبائح وندخل دياره المقدسة ونسجد للرب. الجماعة التي تصلي معًا تجد قوة لا يجدها المنفرد. صلِّ اليوم مع أحد أفراد أسرتك ولو بصلاة قصيرة.\",\"p\":\"يا رب، اجمعنا في اسمك. علّمنا أن نصلي معًا بقلب واحد وروح واحدة. آمين.\"},{\"t\":\"مصلين بكل صلاة\",\"ref\":\"أفسس ٦: ١٨\",\"bk\":\"أفسس\",\"v\":\"مصلين بكل صلاة وطلبة كل وقت في الروح، وساهرين لهذا بعينه بكل مواظبة وطلبة، لأجل جميع القديسين،\",\"r\":\"«مصلين بكل صلاة وطلبة كل وقت في الروح، وساهرين لهذا بعينه بكل مواظبة وطلبة لأجل جميع القديسين». الصلاة ليست قسمًا من يومي بل هواء حياتي. وهي أيضًا مسؤولية تجاه الجميع.\",\"p\":\"يا رب، علّمني أن أصلي في كل وقت وبكل صلاة. وأعطني أن أشفع في إخوتي القديسين وخدام كنيستك. آمين.\"},{\"t\":\"كنا نرتفع إلى السماوات\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب مياثيوس إننا في البدء كنا نجتمع ونتباحث في أمور نافعة بانين بعضنا بعضًا فنرتفع إلى السماوات، أما الآن فنجتمع ليدين أحدنا أخاه. اجعل لقاءك اليوم بنيانًا لا إدانة.\",\"p\":\"يا رب، اجعل اجتماعاتنا بنيانًا. احفظ ألسنتنا من الإدانة وعلّمنا أن نصعد معًا إليك. آمين.\",\"fq\":283}]},\"7-16\":{\"th\":\"المحبة الكاملة\",\"m\":[{\"t\":\"الرب يحب الرحمة والحق\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"لأن الرب الإله يحب الرحمة والحق، ويعطى مجدا ونعمة.\",\"r\":\"الرب الإله يحب الرحمة والحق ويعطي مجدًا ونعمة. المحبة الكاملة هي التي تجمع الرحمة والحق معًا. اختر اليوم موقفًا تجمع فيه الحق بالرحمة دون تجريح.\",\"p\":\"يا رب، علّمني أن أحب كما تحب. اجعل رحمتي وحقي معًا في كل تعامل. آمين.\"},{\"t\":\"هو أحبنا أولًا\",\"ref\":\"يوحنا الأولى ٤: ١٩\",\"bk\":\"يوحنا الأولى\",\"v\":\"نحن نحبه لأنه هو أحبنا أولا.\",\"r\":\"«نحن نحبه لأنه هو أحبنا أولًا». لا أحتاج أن أتصنع محبة الله، بل أن أتأمل في محبته لي حتى تشتعل محبتي له. فمن عرف كم هو محبوب يصير قادرًا على أن يحب.\",\"p\":\"يا رب، أنت أحببتني أولًا. افتح قلبي لمحبتك، واملأني بها حتى أحب إخوتي كما أحببتني. آمين.\"},{\"t\":\"محبة بلا دينونة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كسنثيا إن الكلب أفضل منه لأن عنده محبة ولا يأتي إلى دينونة أحد. المحبة تخفض الأنا وتبعد الدينونة. أحب اليوم بلا حكم على أحد.\",\"p\":\"يا رب، هب لي محبة بسيطة لا تدين. وطهّر قلبي من كل كبرياء يمنعني أن أحب. آمين.\",\"fq\":308}]},\"7-17\":{\"th\":\"الوحدة\",\"m\":[{\"t\":\"سبحوه يا جميع الأمم\",\"ref\":\"المزمور ١١٦ (١١٧) — الغروب\",\"v\":\"سبحوا الرب يا جميع الأمم ولتباركه كافة الشعوب. لأن رحمته قد ثبتت علينا وحق الرب يدوم إلى الأبد هلليلويا.\",\"r\":\"يدعو المرنم كل الأمم والشعوب إلى تسبيح واحد لأن رحمة الرب ثبتت علينا. الوحدة تبدأ بتسبيح مشترك. صلِّ اليوم من أجل وحدة كنيستك وبيتك.\",\"p\":\"يا رب، اجمع شعبك في تسبيح واحد. ثبّت رحمتك علينا، واجعلنا واحدًا كما أنت والآب واحد. آمين.\"},{\"t\":\"ما أحسن وما أجمل\",\"ref\":\"المزامير ١٣٣: ١\",\"bk\":\"المزامير\",\"v\":\"هوذا ما أحسن وما أجمل أن يسكن الإخوة معا!\",\"r\":\"«هوذا ما أحسن وما أجمل أن يسكن الإخوة معًا!». الوحدة ليست فرضًا بل جمال وعطر وندى. وحيث يجتمع الإخوة بمحبة، يأمر الرب بالبركة، فتنمو الحياة وتنتعش الأرواح. وأنا أبدأ بنفسي: أن أكون سبب جمال لا سبب خصام.\",\"p\":\"يا رب، ما أحسن وما أجمل أن نسكن معًا بالمحبة! اجعل بيوتنا وكنائسنا مكانًا تأمر فيه بالبركة. آمين.\"},{\"t\":\"أن تموت عن قريبك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى الحبشي إن أن تموت عن قريبك يعني أن تحمل خطاياك ولا تسيء إلى أحد ولا تحتقر من أخطأ. الوحدة تحتاج هذا الموت عن الذات. تصالح اليوم مع شخص ما، أو صلِّ من أجله.\",\"p\":\"يا رب، أمتّ فيّ كل ما يفرّقني عن إخوتي. اجعلني صانع سلام ومصالحة. آمين.\",\"fq\":266}]},\"7-18\":{\"th\":\"الحرية في المسيح\",\"m\":[{\"t\":\"نجت أنفسنا\",\"ref\":\"المزمور ١٢٣ (١٢٤) — الغروب\",\"v\":\"نجت أنفسنا مثل العصفور من فخ الصيادين، الفخ انكسر ونحن نجونا، عوننا باسم الرب الذي صنع السماء والأرض هلليلويا.\",\"r\":\"نجت أنفسنا مثل العصفور من فخ الصيادين، الفخ انكسر ونحن نجونا. الحرية في المسيح فك لكل فخ. اكتب اليوم عادة تقيدك، وقدمها للمسيح طالبًا الحرية.\",\"p\":\"يا رب، حررني من كل فخ. أنت كسرت قيودي فأعطني أن أسلك في حريتك. آمين.\"},{\"t\":\"أحرارًا بالحقيقة\",\"ref\":\"يوحنا ٨: ٣٦\",\"bk\":\"يوحنا\",\"v\":\"فإن حرركم الابن فبالحقيقة تكونون أحرارا.\",\"r\":\"«فإن حرركم الابن فبالحقيقة تكونون أحرارًا». أحيانًا أظن الحرية أن أفعل ما أشاء، لكن المسيح يعلمني أنها التحرر من عبودية لا أراها. هو وحده يفك القيود ويعطيني قدرة على عمل الخير.\",\"p\":\"يا رب يسوع، حرّرني من كل قيد داخلي وخطية متسلطة، وأعطني حرية أبناء الله في بيتك. آمين.\"},{\"t\":\"احتقر الأموال\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس: إذا اشتهيت ملكوت السماوات فاحتقر الأموال واسع نحو المكافأة الإلهية. المال أول قيد للقلب. تخلَّ اليوم عن شراء شيء غير ضروري، وأعطِ ثمنه لمحتاج.\",\"p\":\"يا رب، فكّ قلبي من أسر الغنى. اجعل كنزي عندك في السماء. آمين.\",\"fq\":198}]},\"7-19\":{\"th\":\"السلوك في النور\",\"m\":[{\"t\":\"نور أشرق في الظلمة\",\"ref\":\"المزمور ١١١ (١١٢) — التاسعة\",\"v\":\"نور أشرق في الظلمة للمستقيمين.\",\"r\":\"النور أشرق في الظلمة للمستقيمين. السلوك في النور اختيار يومي للصدق والشفافية. حدد اليوم أمرًا تخفيه، وأخرجه إلى النور بالاعتراف أو التصحيح.\",\"p\":\"يا رب، أنر طريقي. أعطني أن أسلك في النور، فلا أخفي شيئًا منك ولا من الناس. آمين.\"},{\"t\":\"شركة ودم يطهر\",\"ref\":\"يوحنا الأولى ١: ٧\",\"bk\":\"يوحنا الأولى\",\"v\":\"ولكن إن سلكنا في النور كما هو في النور، فلنا شركة بعضنا مع بعض، ودم يسوع المسيح ابنه يطهرنا من كل خطية.\",\"r\":\"«إن سلكنا في النور كما هو في النور، فلنا شركة بعضنا مع بعض، ودم يسوع المسيح ابنه يطهرنا من كل خطية». السير في النور يعني الصدق مع الله ومع الناس، ولا أخفي شيئًا عن عينيه الرحيمتين.\",\"p\":\"يا رب، علّمني أن أسلك في نورك بلا خوف ولا أقنعة، وطهّرني بدمك الكريم من كل خطية. آمين.\"},{\"t\":\"نقاوة الذهن\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب سيسوى بأن نقتني نقاوة الذهن وعدم الهم والكلام. النور الداخلي يحتاج ذهنًا صافيًا. خصص اليوم عشر دقائق بلا هاتف، واجلس مع الله.\",\"p\":\"يا رب، نقِّ ذهني من كل همّ زائد. اجعل فكري صافيًا لتشرق فيه. آمين.\",\"fq\":492}]},\"7-20\":{\"th\":\"الصوت المنخفض الخفيف\",\"m\":[{\"t\":\"صالح ووديع\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"لأني إليك يا رب رفعت نفسي. لأنك أنت يا رب صالح ووديع. ورحمتك كثيرة لكافة المستغيثين بك.\",\"r\":\"يقول المرنم: أنت يا رب صالح ووديع، ورحمتك كثيرة لكافة المستغيثين بك. الله يتكلم بالصوت المنخفض، ونحتاج هدوءًا لنسمعه. اجلس اليوم دقائق في صمت، وقل: تكلم يا رب.\",\"p\":\"يا رب، أنت صالح ووديع. رفعت إليك نفسي، فتكلم إلى قلبي بصوتك الخفيف. آمين.\"},{\"t\":\"صوت منخفض خفيف\",\"ref\":\"الملوك الأول ١٩: ١٢\",\"bk\":\"الملوك الأول\",\"v\":\"وبعد الزلزلة نار، ولم يكن الرب في النار. وبعد النار صوت منخفض خفيف.\",\"r\":\"«وبعد النار صوت منخفض خفيف». كثيرًا ما أبحث عن الله في الأحداث الكبيرة والمشاعر القوية، لكنه يخاطبني في الهدوء. أحتاج إلى سكون أصغي فيه إلى صوته الرقيق داخل قلبي.\",\"p\":\"يا رب، أصغِ إلى صوتك المنخفض الخفيف. اهدئ ضجيج قلبي لأسمعك، وأرسلني بما تريد وأنا مطمئن. آمين.\"},{\"t\":\"صوت عصفور\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أرسانيوس إن الإنسان إذا أقام في السكينة وسمع صوت عصفور لا يكون في قلبه الهدوء نفسه. الهدوء الداخلي هش، يحتاج حراسة. أغلق اليوم أحد مصادر الضوضاء عمدًا.\",\"p\":\"يا رب، علّمني حراسة الهدوء. اجعلني أسمع صوتك في كل صمت. آمين.\",\"fq\":38}]},\"7-21\":{\"th\":\"نعمة فوق نعمة\",\"m\":[{\"t\":\"ذكر رحمته\",\"ref\":\"المزمور ٩٧ (٩٨) — التاسعة\",\"v\":\"ذكر رحمته ليعقوب وحقه لبيت إسرائيل. نظرت أقاصي الأرض جميعا خلاص إلهنا.\",\"r\":\"ذكر الله رحمته ليعقوب وحقه لبيت إسرائيل، ونظرت أقاصي الأرض خلاص إلهنا. نعمة فوق نعمة تتدفق من غنى المسيح. اكتب اليوم نعمة تلقيتها هذا الأسبوع، واشكره عليها.\",\"p\":\"يا رب، ذكرت رحمتك لنا. أعطني أن أرى نعمك الكثيرة وأشكرك عليها. آمين.\"},{\"t\":\"من ملئه أخذنا\",\"ref\":\"يوحنا ١: ١٦\",\"bk\":\"يوحنا\",\"v\":\"ومن ملئه نحن جميعا أخذنا، ونعمة فوق نعمة.\",\"r\":\"«ومن ملئه نحن جميعًا أخذنا، ونعمة فوق نعمة». لا أحيا من رصيد قديم من النعمة، بل من تدفق جديد كل يوم. كل صباح تأتي نعمة فوق التي أخذتها أمس، فلا أخاف من نفاد أو من جفاف.\",\"p\":\"يا رب، من ملئك أخذت نعمة فوق نعمة. أشكرك على عطاياك المتجددة، واجعل قلبي مستعدًا دائمًا لقبولها. آمين.\"},{\"t\":\"التواضع ومخافة الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا الكولوفي إن التواضع ومخافة الله أسمى من كل الفضائل. من تواضع قبل النعمة ونمت فيه. تواضع اليوم في موقف واحد، واترك الدفاع عن نفسك.\",\"p\":\"يا رب، علّمني التواضع ومخافتك. املأني من نعمتك، وأنقذني من كبريائي. آمين.\",\"fq\":159}]},\"7-22\":{\"th\":\"توبوا قد اقترب الملكوت\",\"m\":[{\"t\":\"لأني مسكين وبائس\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"أمل يا رب أذنك واستمعني، لأني مسكين وبائس أنا. احفظ نفسي لأني بار، يا إلهي خلص عبدك المتكل عليك. ارحمني يا رب، لأني إليك أصرخ اليوم كله.\",\"r\":\"يطلب المرنم أن يميل الرب أذنه لأنه مسكين وبائس، ويصرخ إليه اليوم كله. التوبة أن نأتي إلى الله فقراء. ملكوت السماوات يقترب من القلب المنكسر. قل لله اليوم: ارحمني.\",\"p\":\"يا رب، أنا مسكين وبائس، فاسمعني وارحمني. أعطني توبة صادقة وصراخًا إليك كل اليوم. آمين.\"},{\"t\":\"قد اقترب ملكوت السماوات\",\"ref\":\"متى ٤: ١٧\",\"bk\":\"متى\",\"v\":\"من ذلك الزمان ابتدأ يسوع يكرز ويقول: «توبوا لأنه قد اقترب ملكوت السماوات».\",\"r\":\"«توبوا لأنه قد اقترب ملكوت السماوات». السبب الأول للتوبة ليس الخوف من العقاب بل قرب الله. والملكوت ليس بعيدًا في السماء فقط، بل اقترب إليّ في المسيح. فأتحول إليه لأنه قريب.\",\"p\":\"يا رب، أتوب إليك لأنك قريب مني. اغفر لي، وأدخلني إلى ملكوتك بنعمتك واجعلني أسير في طريقك. آمين.\"},{\"t\":\"كلام العشار\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب أمون أخًا أن يبقى في قلايته وأن يكون في قلبه كلام العشار، فيخلص. التوبة صلاة قصيرة يومية. كرر اليوم: ارحمني يا الله أنا الخاطئ.\",\"p\":\"يا رب، علّمني توبة العشار. ارحمني أنا الخاطئ، وأدخلني إلى ملكوتك. آمين.\",\"fq\":62}]},\"7-23\":{\"th\":\"أنتم نور العالم\",\"m\":[{\"t\":\"مثل العريس الخارج من خدره\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"جعل في الشمس مظلته. وهى مثل العريس الخارج من خدره. تتهلل مثل الجبار الذي يسرع في طريقه.\",\"r\":\"جعل الله في الشمس مظلته وهي مثل العريس الخارج من خدره، تتهلل كالجبار. هكذا يُشرق المؤمن نورًا للعالم. اجعل اليوم عملًا واحدًا يُرى فيه نور المسيح فيك.\",\"p\":\"يا رب، اجعلني نورًا في العالم. أشرق فيّ بنورك، فيرى الناس أعمالي ويمجدون أباك. آمين.\"},{\"t\":\"مدينة على جبل\",\"ref\":\"متى ٥: ١٤\",\"bk\":\"متى\",\"v\":\"أنتم نور العالم. لا يمكن أن تخفى مدينة موضوعة على جبل،\",\"r\":\"«أنتم نور العالم. لا يمكن أن تخفى مدينة موضوعة على جبل». المسيح لا يقول: اجتهدوا لتصيروا نورًا، بل يعلن أنكم نور. لأنه نور فيّ، وعلي أن أترك هذا النور يظهر دون خجل ودون استعراض.\",\"p\":\"يا رب، أنت نور العالم، وقد جعلتني نورًا بك. اجعل أعمالي تضيء أمام الناس فيمجدوا أبي الذي في السماوات. آمين.\"},{\"t\":\"قرية مزينة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أنطونيوس لقرية تبدو جميلة مزينة من الأمام لكن اللصوص يسلبونها من الخلف. النور الحقيقي ليس مظهرًا، بل حياة كاملة. اسأل نفسك اليوم: أي باب خلفي مفتوح في حياتي؟\",\"p\":\"يا رب، احرس كل أبواب قلبي، لا ظاهري فقط بل باطني. اجعلني نورًا حقيقيًا. آمين.\",\"fq\":10}]},\"7-24\":{\"th\":\"عظيم إيمانك\",\"m\":[{\"t\":\"وباسم الرب دعوت\",\"ref\":\"المزمور ١١٤ — التاسعة\",\"v\":\"ضيقا وحزنا وجدت، وباسم الرب دعوت: يا رب نج نفسي. الرب رحيم وصديق وإلهنا يرحم.\",\"r\":\"يجد المرنم ضيقًا وحزنًا فيدعو باسم الرب ويعلن أنه رحيم. الإيمان العظيم يلجأ إلى الله في الضيق ويتواضع. اطلب اليوم من الله شيئًا بإلحاح ولا تتراجع كالمرأة الكنعانية.\",\"p\":\"يا رب، أنا أؤمن فأعن عدم إيماني. علّمني أن أتواضع وأصرخ إليك حتى تستجيب. آمين.\"},{\"t\":\"عظيم إيمانك\",\"ref\":\"متى ١٥: ٢٨\",\"bk\":\"متى\",\"v\":\"حينئذ أجاب يسوع وقال لها: «يا امرأة، عظيم إيمانك! ليكن لك كما تريدين». فشفيت ابنتها من تلك الساعة.\",\"r\":\"«يا امرأة، عظيم إيمانك! ليكن لك كما تريدين». لم تغضب من الاختبار ولم تنسحب، بل قبلت المكان الأخير بتواضع، فنالت الأول. وهذا إيمان يجمع الثقة بمحبة المسيح مع الاعتراف بعدم الاستحقاق.\",\"p\":\"يا رب، لست مستحقًا لكن أثق في غنى رحمتك. اشفِ ضعفي وضعف أحبائي، وأعطني إيمانًا عظيمًا متواضعًا. آمين.\"},{\"t\":\"يا إله القوات\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب أمون النطروني من تأتيه التجربة أن يقول: يا إله القوات، بصلوات أبي أعتقني. الإيمان يلجأ إلى الله في ساعة التجربة. اختر اليوم صلاة قصيرة تقولها عند الضيق.\",\"p\":\"يا إله القوات، أعتقني من كل تجربة. ثبّت إيماني وعلّمني أن ألجأ إليك سريعًا. آمين.\",\"fq\":69}]},\"7-25\":{\"th\":\"ارحمنا\",\"m\":[{\"t\":\"ارحمنا يا رب ارحمنا\",\"ref\":\"المزمور ١٢٢ (١٢٣) — الغروب\",\"v\":\"ارحمنا يا رب ارحمنا، فإننا كثيرا ما امتلأنا هوانا، وكثيرا ما امتلأت نفوسنا العار اردده على المخصبين والهوان على المتعظمين هلليلويا.\",\"r\":\"تتكرر صرخة ارحمنا لأن النفس شبعت هوانًا. هذه هي صلاة الأعمى وصلاة الكنيسة كلها. صلِّ اليوم «يا رب ارحم» بلا انقطاع في ساعة واحدة.\",\"p\":\"يا رب، ارحمنا ارحمنا. اسمع صراخ ضعفنا، ولا تحجب وجهك عنا. آمين.\"},{\"t\":\"يا ابن داود ارحمني\",\"ref\":\"مرقس ١٠: ٤٧\",\"bk\":\"مرقس\",\"v\":\"فلما سمع أنه يسوع الناصري، ابتدأ يصرخ ويقول: «يا يسوع ابن داود، ارحمني!»\",\"r\":\"«فانتهره كثيرون ليسكت، فصرخ أكثر كثيرًا: يا ابن داود، ارحمني!». أحيانًا تحاول الظروف أو الناس أو حتى أفكاري أن تسكتني عن الصلاة. لكن الحاجة الحقيقية تجعلني أصرخ أكثر.\",\"p\":\"يا ابن داود، ارحمني. لا تدعني أسكت عن الصلاة مهما انتهرني الناس، وافتح عيني لأبصر نورك. آمين.\"},{\"t\":\"ثلاثة أيام\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إنه إذا تاب الإنسان من كل قلبه وتوقف عن الخطيئة فإن الله يقبله حتى في ثلاثة أيام. الرحمة أقرب مما نظن. ابدأ اليوم بتوبة صغيرة صادقة.\",\"p\":\"يا رب، اقبل توبتي مهما تأخرت. ارحمني وأعدني إلى حضنك. آمين.\",\"fq\":316}]},\"7-26\":{\"th\":\"ثقة الرجاء\",\"m\":[{\"t\":\"الاتكال على الرب خير\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"الاتكال على الرب خير من الاتكال على البشر، الرجاء بالرب خير من الرجاء بالرؤساء.\",\"r\":\"الاتكال على الرب خير من الاتكال على البشر، والرجاء به خير من الرجاء بالرؤساء. ثقة الرجاء ثابتة لأن الله أمين. ضع اليوم أمرًا يقلقك في يد الله، ولا تحمله وحدك.\",\"p\":\"يا رب، أنت رجائي وثقتي. علّمني أن أتكل عليك وحدك، فلا أخزى أبدًا. آمين.\"},{\"t\":\"إن تمسكنا بثقة الرجاء\",\"ref\":\"العبرانيين ٣: ٦\",\"bk\":\"العبرانيين\",\"v\":\"وأما المسيح فكابن على بيته. وبيته نحن إن تمسكنا بثقة الرجاء وافتخاره ثابتة إلى النهاية.\",\"r\":\"«وبيته نحن إن تمسكنا بثقة الرجاء وافتخاره ثابتة إلى النهاية». أنا جزء من بيت الله. والتمسك بالرجاء ليس عنادًا بل ثقة في المسيح الذي لا يخذل. فأمسك به حين تتغير الظروف.\",\"p\":\"يا رب، ثبّتني في بيتك بثقة الرجاء. أعطني أن أتمسك بك إلى النهاية مهما تغيرت الأيام. آمين.\"},{\"t\":\"لا نيأس من خلاصنا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يؤكد الأب بولس البسيط صلاح الله لمن يهرعون إليه بصدق، فلا نيأس من خلاصنا لأن خطايانا تُطهَّر وتصير بيضاء كالثلج. الرجاء يبدأ حين نعود. عد اليوم إلى الله، مهما كان ماضيك.\",\"p\":\"يا رب، لا أيأس من خلاصي. طهّرني وبيّضني، وأهّلني لخيرات أورشليم السماوية. آمين.\",\"fq\":479}]},\"7-27\":{\"th\":\"الحكمة من الرب\",\"m\":[{\"t\":\"جيل المستقيمين يبارك\",\"ref\":\"المزمور ١١١ (١١٢) — التاسعة\",\"v\":\"جيل المستقيمين يبارك. مجد وغنى في بيته؛ وبره يدوم إلى الأبد.\",\"r\":\"جيل المستقيمين يبارك، ومجد وغنى في بيته وبره يدوم. الحكمة ثمرة الاستقامة ومخافة الرب. اطلب اليوم حكمة لقرار ينتظرك، واسأل مشورة أمينة.\",\"p\":\"يا رب، اهدني بحكمتك. اجعلني مستقيمًا فيبارك الله نسلي، ويدوم برّك في بيتي. آمين.\"},{\"t\":\"الرب يعطي حكمة\",\"ref\":\"الأمثال ٢: ٦\",\"bk\":\"الأمثال\",\"v\":\"لأن الرب يعطي حكمة. من فمه المعرفة والفهم.\",\"r\":\"«لأن الرب يعطي حكمة. من فمه المعرفة والفهم». أحيانًا أحتار في قرار أو علاقة أو أولوية، وأظن أنني أحتاج ذكاءً أكبر. لكن الحكمة تأتي من فم الرب، وتُطلب بالسؤال والإصغاء.\",\"p\":\"يا رب، أنت تعطي حكمة. امنحني حكمة من فمك في قراراتي، وعلّمني أن أطلبها بتواضع وأسمعها بانتباه. آمين.\"},{\"t\":\"الفضائل الثلاث\",\"ref\":\"\",\"v\":\"\",\"r\":\"يتأسف الأب إيليا أن فضائل آبائنا كانت اللاقنية والإمساك والوداعة، أما الآن فيسود الطمع والشراهة والوقاحة. الحكمة أن نعود إلى البسيط. ابدأ اليوم بفضيلة منها: الوداعة.\",\"p\":\"يا رب، أعد إلينا بساطة الآباء. اغرس فينا الوداعة والاكتفاء. آمين.\",\"fq\":130}]},\"7-28\":{\"th\":\"ملجأنا\",\"m\":[{\"t\":\"رب القوات معنا\",\"ref\":\"المزمور ٤٥ (٤٦) — الثالثة\",\"v\":\"الرب إله القوات معنا، ناصرنا هو إله يعقوب.\",\"r\":\"رب القوات معنا، إله يعقوب ناصر لنا. هو ملجأنا لأنه حاضر معنا. حين تخاف اليوم من أمر قل بصوت مسموع: رب القوات معنا.\",\"p\":\"يا رب القوات، كن معنا وملجأنا. احفظنا في ظلك، ولا تدع الخوف يغلبنا. آمين.\"},{\"t\":\"ملجأ في أزمنة الضيق\",\"ref\":\"المزامير ٩: ٩\",\"bk\":\"المزامير\",\"v\":\"ويكون الرب ملجأ للمنسحق. ملجأ في أزمنة الضيق.\",\"r\":\"«ويكون الرب ملجأ للمنسحق. ملجأ في أزمنة الضيق». حين ينكسر قلبي أو تضيق بي الأمور، لا أبحث عن ملجأ بعيد، فالرب نفسه هو المأوى. وهو يستقبل المنسحقين ولا يرفض أحدًا.\",\"p\":\"يا رب، أنت ملجأي في أزمنة الضيق. احتضن قلبي المنسحق، وعلّمني أن آوي إليك في كل حين. آمين.\"},{\"t\":\"ثلاث حروب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أنطونيوس إن من يقيم في السكينة يتحرر من حروب السمع والكلام والنظر. الملجأ الحقيقي هو الله والسكينة معه. أغلق اليوم عينيك لحظات عن شيء يشتتك.\",\"p\":\"يا رب، احفظ حواسي. اجعل سمعي ونظري ولساني لك وحدك. آمين.\",\"fq\":8}]},\"7-29\":{\"th\":\"شبع النفس\",\"m\":[{\"t\":\"وتبصر خيرات أورشليم\",\"ref\":\"المزمور ١٢٧ (١٢٨) — الغروب\",\"v\":\"يباركك الرب من صهيون، وتبصر خيرات أورشليم جميع أيام حياتك: وترى بني بنيك، والسلام على إسرائيل.\",\"r\":\"يعد المزمور بالبركة والخير والسلام لمن يتقي الرب. النفس تشبع حين تعود إلى الله. قبل أن تشتهي شيئًا اليوم، اسأل: هل هذا ما تحتاجه روحي فعلًا؟\",\"p\":\"يا رب، أشبع نفسي من صلاحك. باركني وأعطني أن أبصر خيراتك وسلامك. آمين.\"},{\"t\":\"أشبع نفسًا مشتهية\",\"ref\":\"المزامير ١٠٧: ٩\",\"bk\":\"المزامير\",\"v\":\"لأنه أشبع نفسا مشتهية وملأ نفسا جائعة خبزا،\",\"r\":\"«لأنه أشبع نفسًا مشتهية، وملأ نفسًا جائعة خبزًا». في داخلي جوع أحاول إشباعه بأشياء كثيرة لا تكفي. والله وحده يملأ النفس المشتهية، فأقبل إليه بجوعي ولا أخجل. فهو الذي يعطي الشبع الحقيقي لنفسي الجائعة كل يوم.\",\"p\":\"يا رب، أشبعني من خيراتك ومن رحمتك. املأ جوع نفسي الحقيقي بك أنت، يا خبز الحياة. آمين.\"},{\"t\":\"الشبع الممقوت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن الشبع الجسدي ممقوت أمام الرب. وشبع النفس يأتي من الله لا من الطعام. قلل اليوم من طعامك قليلًا، وارفع الفارق صلاة.\",\"p\":\"يا رب، أشبع روحي بك. ساعدني أن أضبط جسدي، فلا يعيق صلاتي. آمين.\",\"fq\":336}]},\"7-30\":{\"th\":\"الظل والنور\",\"m\":[{\"t\":\"من حيث يأتي عوني\",\"ref\":\"المزمور ١٢٠ (١٢١) — الغروب\",\"v\":\"رفعت عيني إلى الجبال، من حيث يأتي عوني. معونتي من عند الرب الذي صنع السماء والأرض.\",\"r\":\"أرفع عيني إلى الجبال من حيث يأتي عوني، ومعونتي من عند الرب الذي صنع السماء والأرض. ظل الله وراحتنا فيه نور لطريقنا. ارفع عينيك الآن إلى السماء لحظة، ثم عد إلى عملك.\",\"p\":\"يا رب، معونتي منك. استرني في ظل جناحيك، وأنر طريقي. آمين.\"},{\"t\":\"مثل حدقة العين\",\"ref\":\"المزامير ١٧: ٨\",\"bk\":\"المزامير\",\"v\":\"احفظني مثل حدقة العين. بظل جناحيك استرني\",\"r\":\"«احفظني مثل حدقة العين. بظل جناحيك استرني». حدقة العين أرق ما في الجسد وأشد ما نحميه. هكذا يحفظني الله. فلا أخاف من أني صغير أو ضعيف، فأنا في حماية حنانه.\",\"p\":\"يا رب، احفظني مثل حدقة العين، واسترني بظل جناحيك من كل شر، فأنا في حضنك آمن. آمين.\"},{\"t\":\"اهرب واصمت واهدأ\",\"ref\":\"\",\"v\":\"\",\"r\":\"سمع الأب أرسانيوس صوتًا يقول له: اهرب واصمت واهدأ، لأن هذه جذور عدم الخطيئة. الظل الذي نحتمي به هو الهدوء مع الله. اهرب اليوم من ضجيج واحد، واصمت قليلًا.\",\"p\":\"يا رب، قدني إلى هدوء لا يزعجه شيء. علّمني أن أصمت لأسمعك. آمين.\",\"fq\":24}]},\"7-31\":{\"th\":\"شكر الغروب\",\"m\":[{\"t\":\"اقبل تمجيدنا\",\"ref\":\"تحليل الغروب\",\"v\":\"اللهم اقبل تمجيدنا هذا الذي صار الآن. هب لنا في هذه الليلة المقبلة سلامة بغير ألم ولا قلق ولا تعب.\",\"r\":\"نختم الشهر بتمجيد الغروب وشكر على يوم مضى. اجلس الليلة دقائق وراجع أسبوعك وقدم شكرك على كل ما أعطاك. ثم اطلب ليلة بسلام.\",\"p\":\"يا رب، اقبل شكري. هب لي ليلة هادئة بلا قلق، وأيقظني إلى يوم جديد في نعمتك. آمين.\"},{\"t\":\"أشبعنا بالغداة\",\"ref\":\"المزامير ٩٠: ١٤\",\"bk\":\"المزامير\",\"v\":\"أشبعنا بالغداة من رحمتك، فنبتهج ونفرح كل أيامنا.\",\"r\":\"«أشبعنا بالغداة من رحمتك، فنبتهج ونفرح كل أيامنا». أبدأ الصباح بالقلق أو بالتفكير في المهام، لكن موسى يعلمني أن أبدأه بالشبع من رحمة الله. وعندئذ يخرج الفرح عفويًا لأيامي كلها.\",\"p\":\"يا رب، أشبعنا بالغداة من رحمتك فنبتهج ونفرح كل أيامنا. وثبّت عمل أيدينا لمجد اسمك. آمين.\"},{\"t\":\"أشكرك ربي\",\"ref\":\"\",\"v\":\"\",\"r\":\"في مرض الأب أرسانيوس قال: أشكرك ربي لأنك أهلتني أن آخذ حسنة من أجل اسمك. هكذا يشكر القلب في الضعف. اشكر الله الليلة على ما لم تفهمه من يومك.\",\"p\":\"يا رب، أشكرك على كل ما كان. علّمني أن أشكر في الضعف كما في القوة. آمين.\",\"fq\":37}]},\"8-1\":{\"th\":\"هلم نرجع إلى الرب\",\"m\":[{\"t\":\"فلتدخل طلبتي إلى حضرتك\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء الثاني والعشرون · صلاة الستار\",\"v\":\"فلتدن وسيلتي قدامك يا رب، كقولك فهمني. فلتدخل طلبتي إلى حضرتك يا رب، ككلمتك أحيني.\",\"r\":\"يطلب المرنم أن تدنو وسيلته من الله وأن تدخل طلبته إلى حضرته. الرجوع إلى الرب يبدأ بطلب فهم وحياة منه. ابدأ اليوم بالجملة البسيطة: هلم نرجع إلى الرب، وحدد شيئًا واحدًا تعود عنه.\",\"p\":\"يا رب، لتدن وسيلتي قدامك ولتدخل طلبتي إلى حضرتك. أرجعني إليك وأحيني ككلمتك. آمين.\"},{\"t\":\"هو افترس فيشفينا\",\"ref\":\"هوشع ٦: ١\",\"bk\":\"هوشع\",\"v\":\"هلم نرجع إلى الرب لأنه هو افترس فيشفينا، ضرب فيجبرنا.\",\"r\":\"«هلم نرجع إلى الرب، لأنه هو افترس فيشفينا، ضرب فيجبرنا». حتى حين أتألم من نتائج خطاياي، لا أبتعد عن الله بل أرجع إليه، لأن الذي سمح بالجرح هو الذي يضمده. فالتأديب عنده بداية الشفاء لا نهاية الرجاء.\",\"p\":\"يا رب، هلم نرجع إليك لأنك أنت الذي تشفي وتجبر. اقبلني في توبتي، وضمد جراحي بحنانك الأبوي. آمين.\"},{\"t\":\"التوبة أمامك\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب لوط لأخ سقط: تشجع يا أخي فالتوبة أمامك، اجلس في الكهف وأنا أحتمل معك نصف الخطية. الرجوع إلى الله يحتاج رفيقًا يشجع. شجّع اليوم أخًا تعثر بدلًا من أن تحكم عليه.\",\"p\":\"يا رب، افتح أمامي باب التوبة. وأعطني أن أشجع من سقط حتى يقوم، كما شجعتني أنت. آمين.\",\"fq\":229}]},\"8-2\":{\"th\":\"قلب جديد\",\"m\":[{\"t\":\"تحيا نفسي وتسبحك\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء الثاني والعشرون · صلاة الستار\",\"v\":\"اشتقت إلى خلاصك يا رب. وناموسك هو تلاوتي. تحيا نفسي وتسبحك.\",\"r\":\"يشتاق المرنم إلى خلاص الرب ويجعل ناموسه تلاوته، فتحيا نفسه وتسبح. القلب الجديد عطية يعطيها الله لمن يشتاق إليها. اقرأ اليوم آية واحدة بشوق وقل: أعطني قلبًا جديدًا.\",\"p\":\"يا رب، اشتقت إلى خلاصك. اخلق فيّ قلبًا جديدًا، واجعل ناموسك تلاوتي، فتحيا نفسي وتسبحك. آمين.\"},{\"t\":\"قلبًا جديدًا\",\"ref\":\"حزقيال ٣٦: ٢٦\",\"bk\":\"حزقيال\",\"v\":\"وأعطيكم قلبا جديدا، وأجعل روحا جديدة في داخلكم، وأنزع قلب الحجر من لحمكم وأعطيكم قلب لحم.\",\"r\":\"«وأعطيكم قلبًا جديدًا، وأجعل روحًا جديدة في داخلكم، وأنزع قلب الحجر من لحمكم وأعطيكم قلب لحم». لا يطلب الله تجميل القلب بل استبداله. وأنا أحتاج أن أسمح له بأن ينزع قساوتي ويعطيني حساسية جديدة.\",\"p\":\"يا رب، أعطني قلبًا جديدًا وروحًا جديدة. انزع قساوة قلبي وأعطني قلبًا حيًا يستجيب لمحبتك وكلمتك. آمين.\"},{\"t\":\"ينابيع مياه\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي: مثّل العشار لئلا تدان مع الفريسي، وآثر وداعة موسى لتحول قلبك الصلد إلى ينابيع مياه. القلب القاسي يلين بالوداعة. اختر اليوم رد فعل لين في موقف يضايقك.\",\"p\":\"يا رب، حوّل قلبي الصلد إلى ينابيع مياه. امنحني وداعة موسى وتوبة العشار. آمين.\",\"fq\":539}]},\"8-3\":{\"th\":\"ارجع إلى الرب\",\"m\":[{\"t\":\"انظر إلى مذلتي ونجني\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء العشرون · صلاة الستار\",\"v\":\"انظر إلى مذلتي وأنقذني، فإني لم أنس ناموسك. احكم لي في دعواي ونجني.\",\"r\":\"يطلب المرنم من الله أن ينظر إلى مذلته وينجيه، لأنه لم ينس ناموسه. الرجوع إلى الله يكون من مكان الضعف لا من مكان القوة. ارجع اليوم إلى الرب بصلاة صادقة واذكر له ما يوجع قلبك.\",\"p\":\"يا رب، انظر إلى مذلتي وأنقذني، واحكم لي في دعواي ونجني. أرجع إليك فاقبلني. آمين.\"},{\"t\":\"قد تعثرت بإثمك\",\"ref\":\"هوشع ١٤: ١\",\"bk\":\"هوشع\",\"v\":\"ارجع يا إسرائيل إلى الرب إلهك، لأنك قد تعثرت بإثمك.\",\"r\":\"«ارجع يا إسرائيل إلى الرب إلهك، لأنك قد تعثرت بإثمك». كلمة «تعثرت» رقيقة، فهي لا تقول سقطت ولا هلكت. الله يرى ضعفي كعثرة تحتاج إلى قيام، ويقول لي: ارجع، فلا تيأس من نفسك.\",\"p\":\"يا رب، ها أنا أرجع إليك وقد تعثرت بإثمي. ارفع عني كل إثم، وأقمني بنعمتك لأسير في طريقك. آمين.\"},{\"t\":\"الطريق الذي سلّمه الآباء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن من أراد التحرر من خطاياه يتخلص منها بالبكاء، وهو الطريق الذي سلمه الكتاب المقدس والآباء. الدموع تغسل ما لا يغسله الكلام. اجلس اليوم دقائق وابك أمام الله على خطية واحدة.\",\"p\":\"يا رب، أعطني دموع التوبة. اغسلني بها، واقبلني ابنًا راجعًا إليك. آمين.\",\"fq\":397}]},\"8-4\":{\"th\":\"الصوم المقبول\",\"m\":[{\"t\":\"برحمتك أحيني\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء العشرون · صلاة الستار\",\"v\":\"انظر يا رب، فإني أحببت وصاياك. برحمتك يا رب أحيني.\",\"r\":\"يعلن المرنم محبته لوصايا الله ويطلب الحياة برحمته. الصوم الذي يريده الله يبدأ بالمحبة للوصية ثم يمتد إلى العطاء. قدّم اليوم صومًا صغيرًا وأعطِ ما وفرته لمحتاج.\",\"p\":\"انظر يا رب فإني أحببت وصاياك، وبرحمتك أحيني. اجعل صومي مقبولًا، وعلّمني أن أفتح يدي للفقراء. آمين.\"},{\"t\":\"أن تكسر للجائع خبزك\",\"ref\":\"إشعياء ٥٨: ٧\",\"bk\":\"إشعياء\",\"v\":\"أليس أن تكسر للجائع خبزك، وأن تدخل المساكين التائهين إلى بيتك؟ إذا رأيت عريانا أن تكسوه، وأن لا تتغاضى عن لحمك.\",\"r\":\"«أن تكسر للجائع خبزك، وأن تدخل المساكين التائهين إلى بيتك». الصوم الذي يرضي الله لا ينتهي بالامتناع عن الطعام بل يمتد إلى العطاء. وما أوفره بصيامي يجب أن يصل إلى يد محتاج.\",\"p\":\"يا رب، علّمني الصوم الذي ترضى به. اجعل صومي رحمة وعطاءً، وافتح قلبي وبيتي للمحتاجين. آمين.\"},{\"t\":\"ضبط الأفكار\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينقل الأب لوكيوس قول إشعياء إن إحناء العنق ليس هو الصوم المقبول، بل الأفضل ضبط الأفكار الشريرة. الصوم الحقيقي صراع مع الفكر قبل الجسد. اختر اليوم فكرًا شريرًا يتكرر عليك وقاومه بصلاة.\",\"p\":\"يا رب، علّمني صومًا يضبط أفكاري. نقِّ ذهني، واجعل صومي ثمرة محبة لا مظهرًا. آمين.\",\"fq\":231}]},\"8-5\":{\"th\":\"الصلاة في الخفاء\",\"m\":[{\"t\":\"اهدني إلى طريقك\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"وأمجد اسمك إلى الأبد.\",\"r\":\"يطلب المرنم الهداية ويعترف من كل قلبه ويمجد اسم الرب. الصلاة في الخفاء تبدأ بالاعتراف أمام من يرى في الخفاء. أغلق اليوم بابك ودقائق قليلة، واسكب قلبك أمام أبيك.\",\"p\":\"يا رب، اهدني إلى طريقك، وأعترف لك من كل قلبي. أمجد اسمك إلى الأبد وأنا في خلوتي معك. آمين.\"},{\"t\":\"يعتزل ويصلي\",\"ref\":\"لوقا ٥: ١٦\",\"bk\":\"لوقا\",\"v\":\"وأما هو فكان يعتزل في البراري ويصلي.\",\"r\":\"«وأما هو فكان يعتزل في البراري ويصلي». المسيح كان مشغولًا بالجموع والمرضى، ومع ذلك كان يخلو بالآب. وإن كان هو يحتاج إلى هذه الخلوة فكم بالحري أنا. فلا أسمح للانشغال أن يسرق وقت صلاتي.\",\"p\":\"يا رب يسوع، علّمني أن أعتزل وأصلي كما فعلت. اجعل الخلوة معك أحب أوقات يومي. آمين.\"},{\"t\":\"فلندخل إلى مخادعنا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: فلندخل إلى مخادعنا ونتذكر خطايانا، والرب يعيننا في كل شيء. الخلوة موضع الصدق مع النفس ومع الله. اجعل لك اليوم موعدًا ثابتًا مع الله لا تعطيه لأي أمر آخر.\",\"p\":\"يا رب، علّمني حب الخلوة معك. أعنّي في مخدعي، واكشف لي ما يحتاج إلى توبة. آمين.\",\"fq\":435}]},\"8-6\":{\"th\":\"العطاء المبارك\",\"m\":[{\"t\":\"أذبح لك طائعًا\",\"ref\":\"المزمور ٥٣ (٥٤) — السادسة\",\"v\":\"لأنك من جميع الشدائد نجيتني.\",\"r\":\"يقول المرنم: الله عوني، أذبح لك طائعًا وأعترف لاسمك. العطاء الحقيقي ذبيحة طوعية يقدمها القلب المحب. أعط اليوم من وقتك أو مالك شيئًا بفرح، دون أن يطلب منك أحد.\",\"p\":\"يا رب، أنت عوني. علّمني أن أعطي طائعًا فرحًا، وبارك ما أقدمه لك ولإخوتي. آمين.\"},{\"t\":\"الصالح العين يبارك\",\"ref\":\"الأمثال ٢٢: ٩\",\"bk\":\"الأمثال\",\"v\":\"الصالح العين هو يبارك، لأنه يعطي من خبزه للفقير.\",\"r\":\"«الصالح العين هو يبارك، لأنه يعطي من خبزه للفقير». العين الصالحة ترى حاجة الآخر ولا تحسدهم. وحين أعطي من خبزي لا من فائضي فقط، أتحول إلى بركة وأنال بركة.\",\"p\":\"يا رب، اجعل عيني صالحة ترى حاجة إخوتي، وقلبي سخيًا يعطي من خبزه بفرح وسلام دائم. آمين.\"},{\"t\":\"العطاء أكثر من الأخذ\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب بفنوتيوس: أحبوا الضيق أكثر من الراحة، والاحتقار أكثر من المجد، والعطاء أكثر من الأخذ. العطاء يحرر القلب. اختر اليوم أن تعطي في موضع كنت تأخذ فيه.\",\"p\":\"يا رب، حرر قلبي من حب الأخذ. اجعلني أحب العطاء كما أنت المعطي الكريم. آمين.\",\"fq\":275}]},\"8-7\":{\"th\":\"العذراء مريم: نظر إلى اتضاعها\",\"m\":[{\"t\":\"يا باب الحياة\",\"ref\":\"قطعة الخدمة الثالثة (٣) — نصف الليل — الخدمة الثالثة\",\"v\":\"يا باب الحياة العقلي، يا والدة الإله المكرمة، خلصي الذين التجأوا إليك بإيمان من الشدائد، لكي نمجد ميلادك الطاهر في كل شيء من أجل خلاص نفوسنا.\",\"r\":\"تدعو الكنيسة العذراء باب الحياة لأن من خلالها جاء الحياة إلينا. نظر الله إلى اتضاعها فصارت أم الرب. تعلّم منها اتضاعها في طلب شفاعتها، وأن تقول لله اليوم: لتكن مشيئتك.\",\"p\":\"يا رب، بشفاعة والدة الإله القديسة مريم خلص الملتجئين إليها بإيمان. علّمني اتضاعها وطاعتها. آمين.\"},{\"t\":\"نظر إلى اتضاع أمته\",\"ref\":\"لوقا ١: ٤٨\",\"bk\":\"لوقا\",\"v\":\"لأنه نظر إلى اتضاع أمته. فهوذا منذ الآن جميع الأجيال تطوبني،\",\"r\":\"«لأنه نظر إلى اتضاع أمته. فهوذا منذ الآن جميع الأجيال تطوبني». لم تفتخر مريم بنفسها بل بنظر الله إليها. والتطويب الذي تناله هو من الله وليس من جهدها. وهكذا نتعلم أن نطلب نظرة الله لا مديح الناس.\",\"p\":\"يا رب، كما نظرت إلى اتضاع أمتك مريم، انظر إلى اتضاعي. وبشفاعتها ساعدني أن أصوم وأصلي بقلب متواضع. آمين.\"},{\"t\":\"اتضاع بلا كلام كثير\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب نيلوس: هنيئًا للراهب الذي يعتبر نفسه نفاية الكل. الاتضاع الحقيقي لا يطلب مديحًا. اختر اليوم عملًا صغيرًا تقوم به بلا ضجيج، كما فعلت العذراء مريم في صمت.\",\"p\":\"يا رب، علّمني اتضاع العذراء. اجعلني أعمل عملي في الخفاء، وأفرح بنظرتك. آمين.\",\"fq\":295}]},\"8-8\":{\"th\":\"الرافع المتضعين\",\"m\":[{\"t\":\"من مثل الرب إلهنا؟\",\"ref\":\"المزمور ١١٢ (١١٣) — باكر\",\"v\":\"الرب عال على كل الأمم؛ فوق السموات مجده. من مثل الرب إلهنا؟!\",\"r\":\"الرب عال على كل الأمم، ومع ذلك ينظر إلى المتواضعين ويرفعهم. وعد مريم أن الله يرفع المتضعين ويشبع الجياع. اعترف اليوم بمكان ضعفك أمام الله وارفع إليه عينيك.\",\"p\":\"يا رب، من مثلك؟ ارفعني من تراب ضعفي، وعلّمني أن أتضع أمامك. آمين.\"},{\"t\":\"أنزل الأعزاء\",\"ref\":\"لوقا ١: ٥٢\",\"bk\":\"لوقا\",\"v\":\"أنزل الأعزاء عن الكراسي ورفع المتضعين.\",\"r\":\"«أنزل الأعزاء عن الكراسي، ورفع المتضعين». ميزان الله يختلف عن ميزان العالم. فمن يتكبر ينزل، ومن يتضع يُرفع. وهذا يريحني من سباق المراكز، لأن رفعي في يد الله وحده.\",\"p\":\"يا رب، ارفع المتضعين وانزع الكبرياء من قلبي. وعلّمني أن أرفع من هم أصغر مني بمحبة. آمين.\"},{\"t\":\"علو التواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس إن علو التواضع عظيم، وكذلك السقوط في الكبرياء. من اتضع ارتفع ومن تكبر سقط. إن مدحك أحد اليوم فاشكر الله ولا تتكبر.\",\"p\":\"يا رب، احفظني من كبرياء القلب. ارفعني بتواضعك ولا تدعني أسقط. آمين.\",\"fq\":174}]},\"8-9\":{\"th\":\"قلب مريم الحافظ\",\"m\":[{\"t\":\"حفظت وصاياك وشهاداتك\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء الحادي والعشرون · صلاة الستار\",\"v\":\"حفظت نفسي شهاداتك وأحببتها جدا. حفظت وصاياك وشهاداتك.\",\"r\":\"يحفظ المرنم شهادات الله ويحبها جدًا. هكذا حفظت العذراء كل الأمور متفكرة بها في قلبها. القلب الحافظ يتأمل بصمت. اكتب اليوم كلمة سمعتها في الكنيسة أو الكتاب وتأمل فيها.\",\"p\":\"يا رب، احفظ في قلبي كلمتك كما حفظتها العذراء. أعطني قلبًا يتأمل ويحفظ ويعمل بها. آمين.\"},{\"t\":\"خاضعًا لهما\",\"ref\":\"لوقا ٢: ٥١\",\"bk\":\"لوقا\",\"v\":\"ثم نزل معهما وجاء إلى الناصرة وكان خاضعا لهما. وكانت أمه تحفظ جميع هذه الأمور في قلبها.\",\"r\":\"«ثم نزل معهما وجاء إلى الناصرة وكان خاضعًا لهما». ابن الله الأزلي قبل أن يخضع لوالدين بشريين. فلا أستخف بقيمة الطاعة في بيتي، فهي تعليم المسيح العملي لنا. وهناك في الناصرة صنع حياة هادئة وعادية.\",\"p\":\"يا رب يسوع، يا من خضعت لوالديك في الناصرة، علّمني الطاعة والتواضع في بيتي وعملي. آمين.\"},{\"t\":\"ماذا فعلت مما يريده الله؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب نيسثروس إن على الراهب أن يحاسب نفسه كل مساء وصباح: ماذا فعلت مما يريده الله وماذا فعلت مما لا يريده؟ حفظ القلب يحتاج مراجعة. اجعل الليلة محاسبة من ثلاث دقائق.\",\"p\":\"يا رب، أرني ما يرضيك وما لا يرضيك. أعطني قلبًا يحفظ ويراجع ويتوب. آمين.\",\"fq\":300}]},\"8-10\":{\"th\":\"أم ربي\",\"m\":[{\"t\":\"صهيون الأم\",\"ref\":\"المزمور ٨٦ (٨٧) — السادسة\",\"v\":\"صهيون الأم تقول إن إنسانا وإنسانا ولد فيها، وهو العلي الذي أسسها إلى الأبد.\",\"r\":\"تُقال عن صهيون إن إنسانًا وإنسانًا وُلد فيها، وهو العلي الذي أسسها. وتراها الكنيسة صورة للعذراء أم الرب. أكرم اليوم أمك الروحية والجسدية بكلمة شكر.\",\"p\":\"يا رب، أشكرك على العذراء مريم أم مخلصي. علّمني أن أكرم أمي وأمهات الكنيسة. آمين.\"},{\"t\":\"من أين لي هذا\",\"ref\":\"لوقا ١: ٤٣\",\"bk\":\"لوقا\",\"v\":\"فمن أين لي هذا أن تأتي أم ربي إلي؟\",\"r\":\"«فمن أين لي هذا أن تأتي أم ربي إليّ؟». أليصابات الأكبر سنًا والأعلى مكانة تظهر تواضعًا كبيرًا أمام العذراء. وتعلمني أن أحترم من اختاره الله وأن أقول: من أنا حتى يزورني الله وقديسوه؟\",\"p\":\"يا رب، أشكرك على أمك العذراء التي كرمتها. علّمني أن أحترم قديسيك وأطلب شفاعتهم بتواضع. آمين.\"},{\"t\":\"أن تمجد قريبك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا رجل القلالي: إذا سمعت شيخًا يمتدح قريبه أكثر من نفسه، فاعلم أنه بلغ كمالًا رفيعًا. المكرِّم هو المحب. اذكر اليوم اسم شخص وأثنِ عليه أمام غيره.\",\"p\":\"يا رب، اجعلني أمجد إخوتي أكثر من نفسي. وأنزع من قلبي حب المدح. آمين.\",\"fq\":273}]},\"8-11\":{\"th\":\"نبوات التجسد\",\"m\":[{\"t\":\"ما الإنسان حتى تذكره؟\",\"ref\":\"المزمور الثامن (من صلاة باكر) — الستار\",\"v\":\"إذا أرى سَمواتِكَ عَمَلَ أصابِعِكَ، القَمَرَ والنُّجومَ التي كَوَّنْتَها، فمَا الإنسانُ حتَّى تَذكُرَه؟ وابنُ آدَمَ حتَّى تَفتَقِدَه؟\",\"r\":\"يتعجب المرنم أن يذكر الله الإنسان ويعتني به. هذا الاهتمام مهد له بنبوات العهد القديم قبل أن يتجسد المسيح. اقرأ اليوم نبوة واحدة عن ميلاد المخلص، وافرح بتحقيقها.\",\"p\":\"يا رب، ما أعجب اسمك! ذكرتنا بنبواتك قبل أن تتجسد، فأعطني أن أراك في كل الكتب. آمين.\"},{\"t\":\"نسل المرأة يسحق رأسك\",\"ref\":\"التكوين ٣: ١٥\",\"bk\":\"التكوين\",\"v\":\"وأضع عداوة بينك وبين المرأة، وبين نسلك ونسلها. هو يسحق رأسك، وأنت تسحقين عقبه».\",\"r\":\"«هو يسحق رأسك، وأنت تسحقين عقبه». بعد السقوط مباشرة لم يترك الله الإنسان بلا رجاء، بل وعد بمخلص يولد من امرأة. وهذا الوعد تحقق في المسيح، فلا أيأس من خطيتي لأن النصرة بدأت منذ البداية.\",\"p\":\"يا رب، أشكرك لأنك وعدت منذ البداية بنسل المرأة الذي يسحق رأس الحية. اسحق الشر في حياتي بنعمتك. آمين.\"},{\"t\":\"من القديم إلى الجديد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيسوى: إني أقرأ العهد القديم وأرجع إلى العهد الجديد. فالقديم يمهد والجديد يكمل. اقرأ اليوم نصًا من العهدين متقابلين، وراقب الصلة بينهما.\",\"p\":\"يا رب، افتح ذهني لأفهم الكتب. أرني المسيح في كل صفحة منها. آمين.\",\"fq\":499}]},\"8-12\":{\"th\":\"العليقة المتقدة\",\"m\":[{\"t\":\"لا شيء يختفي من حرارتها\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"من أقصى السماء خروجها، ومنتهاها إلى أقصى السماء ولا شئ يختفي من حرارتها.\",\"r\":\"يصف المرنم الشمس التي لا يختفي شيء من حرارتها. ظهر الله لموسى في عليقة تتقد ولا تحترق. نار الله تطهر ولا تفني. اطلب اليوم أن يشعل الله فيك نار محبته دون أن يحرق ضعفك.\",\"p\":\"يا رب، أنت النار التي لا تحرق. أشعل فيّ غيرة لك ولا تحرقني بغضبك. آمين.\"},{\"t\":\"العليقة لم تكن تحترق\",\"ref\":\"الخروج ٣: ٢\",\"bk\":\"الخروج\",\"v\":\"وظهر له ملاك الرب بلهيب نار من وسط عليقة. فنظر وإذا العليقة تتوقد بالنار، والعليقة لم تكن تحترق.\",\"r\":\"«فنظر وإذا العليقة تتوقد بالنار، والعليقة لم تكن تحترق». ما أعجب هذا المنظر! النار تشتعل والعليقة لا تفنى. هكذا حضور الله يملأ ولا يحرق. وهذا ما يعلّمنا الآباء عن مريم وعن كل قلب يسكنه الله.\",\"p\":\"يا رب، كما ظهرت لموسى في العليقة، اظهر في حياتي. اجعل قلبي موضعًا لحضورك لا يحترق بل يستنير. آمين.\"},{\"t\":\"الخشب بين المواد المشتعلة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب مكاريوس إن الخشب الذي يتوسط المواد المشتعلة تلتهمه النار بسرعة، وكذلك الإنسان إذا نقّى ذهنه بمخافة الله تلتهم المخافة جسده. مخافة الله نار نقية. اطلب اليوم مخافة الله لا خوفًا من الناس.\",\"p\":\"يا رب، اسكب في قلبي مخافتك كنار مطهرة. أحرق ما فيّ من شر، وأبقني لك. آمين.\",\"fq\":237}]},\"8-13\":{\"th\":\"الباب المغلق\",\"m\":[{\"t\":\"افتحوا لي أبواب البر\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"افتحوا لي أبواب البر لكي أدخل فيها وأعترف للرب. هذا هو باب الرب والصديقون يدخلون فيه.\",\"r\":\"يدعو المرنم أن تُفتح له أبواب البر ليعترف للرب، فهذا باب الرب والصديقون يدخلون فيه. الباب المغلق في الكنيسة علامة سر العذراء. افتح قلبك اليوم لله، وأغلقه على كل ما يفسده.\",\"p\":\"يا رب، افتح لي أبواب البر. علّمني أن أغلق قلبي على الشر وأفتحه لك وحدك. آمين.\"},{\"t\":\"الباب يكون مغلقًا\",\"ref\":\"حزقيال ٤٤: ١\",\"bk\":\"حزقيال\",\"v\":\"ثم أرجعني إلى طريق باب المقدس الخارجي المتجه للمشرق، وهو مغلق.\",\"r\":\"«ثم أرجعني إلى طريق باب المقدس الخارجي المتجه للمشرق، وهو مغلق». هذا الرمز يعلمني قيمة القداسة والتكريس. فبعض الأبواب تبقى لله وحده، وفي حياتي أيضًا أحتاج أن أجعل لله بابًا لا يدخله غيره.\",\"p\":\"يا رب، أجعل في حياتي بابًا مغلقًا لك وحدك. اقبل تكريسي، واحفظ قلبي مقدسًا لحضورك. آمين.\"},{\"t\":\"اللسان والبطن\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب تيثوى: كيف يمكننا أن نحفظ قلبنا عندما يكون لساننا وبطننا مفتوحين؟ حراسة القلب تبدأ بإغلاق الأبواب. أغلق اليوم بابًا واحدًا: كلمة زائدة أو أكلة زائدة.\",\"p\":\"يا رب، ضع حارسًا على فمي، واحفظ باب قلبي. آمين.\",\"fq\":546}]},\"8-14\":{\"th\":\"عصا هارون المزهرة\",\"m\":[{\"t\":\"الكاهن على طقس ملكيصادق\",\"ref\":\"المزمور ١٠٩ (١١٠) — التاسعة\",\"v\":\"أقسم الرب ولن يندم أنك أنت هو الكاهن على طقس ملكيصادق.\",\"r\":\"أقسم الرب ولن يندم أنك أنت الكاهن على طقس ملكيصادق. كهنوت المسيح أزهر كعصا هارون، حياة من يابس. اطلب اليوم من الله أن يعيد الحياة إلى شيء يابس في حياتك.\",\"p\":\"يا رب، أنت الكاهن الأبدي. أزهِر في حياتي ما يبس، وأعد إليّ نضارة الإيمان. آمين.\"},{\"t\":\"الرجل الذي أختاره\",\"ref\":\"العدد ١٧: ٥\",\"bk\":\"العدد\",\"v\":\"فالرجل الذي أختاره تفرخ عصاه، فأسكن عني تذمرات بني إسرائيل التي يتذمرونها عليكما».\",\"r\":\"«فالرجل الذي أختاره تفرخ عصاه». اختيار الله يظهر بثمر لا بدعاية. وليست العصا اليابسة هي التي تثمر بل قوة الله. وأنا أتعلم ألا أخشى من يبسي، فإن اختارني الله أثمرت بنعمته.\",\"p\":\"يا رب، كما أفرخت عصا هارون اليابسة، أنبت الحياة في ما جف في حياتي، واجعلني أثمر لمجدك. آمين.\"},{\"t\":\"الغصن الغض\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أشعيا: كما أن الغصن الغض ينحني بسهولة، هكذا يكون المبتدئون في الطاعة. الحياة تحتاج مرونة تستجيب للمشيئة. اختر اليوم أن تنحني أمام مشيئة الله في موقف تقاومه.\",\"p\":\"يا رب، اجعلني غصنًا غضًّا في يديك. علّمني الطاعة التي تثمر، ولا تدعني أيبس. آمين.\",\"fq\":121}]},\"8-15\":{\"th\":\"نشيد العروس\",\"m\":[{\"t\":\"أبتهج بكلامك\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء الحادي والعشرون · صلاة الستار\",\"v\":\"أبتهج أنا بكلامك كمن وجد غنائم كثيرة. أبغضت الظلم ورذلته؛ أما ناموسك فأحببته.\",\"r\":\"يبتهج المرنم بكلام الله كمن وجد غنائم كثيرة، ويبغض الظلم ويحب الناموس. هذا هو غزل المحبة بين العروس والعريس. اقرأ اليوم آية من الإنجيل كأنها رسالة حب شخصية إليك.\",\"p\":\"يا رب، أبتهج بكلامك كمن وجد غنائم كثيرة. اجعل محبتي لك أعمق من كل محبة، وأبغض ما يبعدني عنك. آمين.\"},{\"t\":\"قومي يا حبيبتي\",\"ref\":\"نشيد الأنشاد ٢: ١٠\",\"bk\":\"نشيد الأنشاد\",\"v\":\"أجاب حبيبي وقال لي: «قومي يا حبيبتي، يا جميلتي وتعالي.\",\"r\":\"«أجاب حبيبي وقال لي: قومي يا حبيبتي، يا جميلتي، وتعالي». المسيح يخاطبني بحنان وليس بتوبيخ. يدعوني لأن أقوم من تراخيّ وأتجه إليه، ويسميني «جميلتي»، ثقة منه بقدرتي على الاستجابة.\",\"p\":\"يا حبيبي يسوع، أسمع دعوتك: قومي وتعالي. أقوم من فتوري وأتجه إليك بكل قلبي، فاجذبني إليك. آمين.\"},{\"t\":\"المحبة أهم من الصوم\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب كسيانوس: الصوم معي دائمًا أما أنتم فلستم معي دائمًا. الصوم اختياري أما إتمام المحبة فتطلبه شريعة الله بالضرورة. قدّم اليوم خدمة محبة قبل أي نسك.\",\"p\":\"يا رب، علّمني أن أضع المحبة قبل كل نسك. اجعل جهادي كله محبة لك ولإخوتي. آمين.\",\"fq\":208}]},\"8-16\":{\"th\":\"جبل الرب\",\"m\":[{\"t\":\"الجبال حولها\",\"ref\":\"المزمور ١٢٤ (١٢٥) — الغروب\",\"v\":\"الساكن في أورشليم. الجبال حولها، والرب حول شعبه من الآن والى الأبد.\",\"r\":\"المتوكلون على الرب مثل جبل صهيون، والجبال حول أورشليم والرب حول شعبه. الكنيسة جبل الرب الذي يلجأ إليه كل متعب. صلِّ اليوم من أجل كنيستك ورعاتها.\",\"p\":\"يا رب، كن حول شعبك من الآن وإلى الأبد. ثبّت كنيستك كجبل صهيون لا يتزعزع. آمين.\"},{\"t\":\"عظيم هو الرب\",\"ref\":\"المزامير ٤٨: ١\",\"bk\":\"المزامير\",\"v\":\"عظيم هو الرب وحميد جدا في مدينة إلهنا، جبل قدسه.\",\"r\":\"«عظيم هو الرب وحميد جدًا في مدينة إلهنا، جبل قدسه». حين أنظر إلى عظمة الله، تصغر مشاكلي وتتسع نفسي. وتسبيح الجماعة في بيت الله يذكرني بأنني جزء من شعب يعبد إلهًا عظيمًا.\",\"p\":\"يا رب، عظيم أنت وحميد جدًا. أقم في وسطنا، واجعلنا نحدث الأجيال القادمة بعظمتك وأمانتك. آمين.\"},{\"t\":\"الطريق الملوكي الخفيف\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن الآباء وجدوا أن الأفضل أن يأكل الإنسان قليلًا كل يوم، وسلموا الطريق الملوكي الخفيف. طريق الله صعود معتدل لا قفز. اختر اليوم نظامًا خفيفًا تستمر عليه شهرًا.\",\"p\":\"يا رب، علّمني الاعتدال في كل شيء. قدني في الطريق الملوكي الذي تحبه. آمين.\",\"fq\":331}]},\"8-17\":{\"th\":\"تعالوا نسجد\",\"m\":[{\"t\":\"الرب القوي في الحروب\",\"ref\":\"المزمور ٢٣ (٢٤) — الثالثة\",\"v\":\"الرب العزيز القدير، الرب القوى في الحروب.\",\"r\":\"الرب العزيز القدير القوي في الحروب هو الذي ندعوه ليدخل قلوبنا. السجود للرب يبدأ بفتح الأبواب له. افتح باب قلبك اليوم لملك المجد، وانحنِ في صلاة صامتة.\",\"p\":\"يا رب القوات، يا ملك المجد، أنت القوي في الحروب. افتح لك أبواب نفسي وأسجد لك. آمين.\"},{\"t\":\"اسجدوا في جبل قدسه\",\"ref\":\"المزامير ٩٩: ٩\",\"bk\":\"المزامير\",\"v\":\"علوا الرب إلهنا، واسجدوا في جبل قدسه، لأن الرب إلهنا قدوس.\",\"r\":\"«علوا الرب إلهنا، واسجدوا في جبل قدسه، لأن الرب إلهنا قدوس». السجود ليس حركة جسد بل اعتراف بالقداسة. وحين أسجد بقلبي، أضع نفسي في مكانها الصحيح أمام الله العظيم.\",\"p\":\"يا رب القدوس، أسجد لك في جبل قدسك. علّمني أن أعلّي اسمك وأخضع لك بقلب محب. آمين.\"},{\"t\":\"لا تغادر قلايتك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيرابيون: يا ولدي إذا ابتغيت المنفعة فلا تغادر قلايتك، انتبه لنفسك وعمل يديك، فالخروج لا يجديك نفعًا كالبكاء. السجود الداخلي أعمق من الحركة الخارجية. اجلس اليوم في مكانك بصلاة أطول.\",\"p\":\"يا رب، علّمني السجود في حضرتك. اجعل قلبي قلاية تلتقي فيها بي. آمين.\",\"fq\":521}]},\"8-18\":{\"th\":\"السحابة والمجد\",\"m\":[{\"t\":\"لبس الجلال\",\"ref\":\"المزمور ٩٢ (٩٣) — السادسة\",\"v\":\"الرب قد ملك. ولبس الجلال.\",\"r\":\"الرب قد ملك ولبس الجلال، ويظهر مجده في السحابة. تحجب السحابة ما لا نحتمل ونرى منه ما يكفينا. تأمل اليوم في عظمة الله بصمت، دون أن تطلب شيئًا.\",\"p\":\"يا رب، لقد ملكت ولبست الجلال. أنا أسجد لك في سحابة مجدك، وأتهيب حضورك. آمين.\"},{\"t\":\"جلد وجهه صار يلمع\",\"ref\":\"الخروج ٣٤: ٢٩\",\"bk\":\"الخروج\",\"v\":\"وكان لما نزل موسى من جبل سيناء ولوحا الشهادة في يد موسى، عند نزوله من الجبل، أن موسى لم يعلم أن جلد وجهه صار يلمع في كلامه معه.\",\"r\":\"«موسى لم يعلم أن جلد وجهه صار يلمع في كلامه معه». لم يقصد أن يتلألأ، لكن الصلاة تركت أثرها. فالمصلي الحقيقي لا يعرف ما يحمله من نور، لكن الناس يرونه في هدوئه ولطفه وسلامه.\",\"p\":\"يا رب، غيرني بصلاتي معك حتى يلمع وجهي بنورك دون أن أدري. وأعطني أن أحمل سلامك إلى من حولي. آمين.\"},{\"t\":\"من لا يمتدحه أحد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أور إن من يُحترم ويُمتدح أكثر مما هو عليه يهلك كثيرًا، أما من لا يمتدحه أحد فيتمجد من فوق. المجد الحقيقي يأتي من الله. افرح اليوم إن لم يلتفت إليك أحد.\",\"p\":\"يا رب، لا أطلب مجد الناس. أعطني أن أتمجد بك وحدك. آمين.\",\"fq\":561}]},\"8-19\":{\"th\":\"عيد التجلي\",\"m\":[{\"t\":\"لبس الرب القوة\",\"ref\":\"المزمور ٩٢ (٩٣) — السادسة\",\"v\":\"لبس الرب القوة. وتمنطق بها. لأنه ثبت المسكونة فلن تتزعزع.\",\"r\":\"لبس الرب القوة وتمنطق بها، وثبت المسكونة فلن تتزعزع. في التجلي ظهر مجده على الجبل لتلاميذه لتثبت قلوبهم. تأمل اليوم في مجد المسيح الذي أخفاه ليحتمل ضعفنا.\",\"p\":\"يا رب، يا من تجليت على الجبل، ثبتنا في مجدك وأنر عيوننا لنراك. آمين.\"},{\"t\":\"أضاء وجهه كالشمس\",\"ref\":\"متى ١٧: ٢\",\"bk\":\"متى\",\"v\":\"وتغيرت هيئته قدامهم، وأضاء وجهه كالشمس، وصارت ثيابه بيضاء كالنور.\",\"r\":\"«وتغيرت هيئته قدامهم، وأضاء وجهه كالشمس، وصارت ثيابه بيضاء كالنور». التلاميذ رأوا لمحة من مجد المسيح الحقيقي قبل أن يروا عاره في الصليب. وأنا أيضًا مدعو لأن أرى وراء الظروف نور المسيح.\",\"p\":\"يا رب يسوع، يا من تجليت على الجبل بمجدك، أضئ على قلبي بنورك. ثبّتني في رجاء المجد وقت الصليب. آمين.\"},{\"t\":\"مجد الناس باطل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيسوى: إذا لم يمجدنا الله فمجد الناس باطل. التجلي يعلّمنا أن المجد الحقيقي ينتظرنا مع المسيح. أطلب اليوم رضا الله قبل رضا الناس في قرار واحد.\",\"p\":\"يا رب، أنت مجدي. اجعلني أطلب وجهك لا استحسان الناس. آمين.\",\"fq\":491}]},\"8-20\":{\"th\":\"النزول من الجبل\",\"m\":[{\"t\":\"لا ينعس حافظك\",\"ref\":\"المزمور ١٢٠ (١٢١) — الغروب\",\"v\":\"لا يسلم رجلك للزلل؛ فما ينعس حافظك. هوذا لا ينعس ولا ينام حارس إسرائيل.\",\"r\":\"لا يسلم الرب رجلك للزلل لأن حارس إسرائيل لا ينعس ولا ينام. التلاميذ نزلوا من الجبل إلى الواقع بحفظه. اجعل رؤيتك الروحية اليوم تنزل إلى عملك العادي وتغيره.\",\"p\":\"يا رب، احفظ رجلي من الزلل. اجعل ما أراه من نورك يظهر في واقع حياتي. آمين.\"},{\"t\":\"لا تعلموا أحدًا\",\"ref\":\"متى ١٧: ٩\",\"bk\":\"متى\",\"v\":\"وفيما هم نازلون من الجبل أوصاهم يسوع قائلا: «لا تعلموا أحدا بما رأيتم حتى يقوم ابن الإنسان من الأموات».\",\"r\":\"«لا تعلموا أحدًا بما رأيتم حتى يقوم ابن الإنسان من الأموات». بعض الخبرات الروحية تحتاج إلى وقت لتنضج قبل أن تُحكى. وأحيانًا يكون الصمت أفضل شهادة حتى يتضح المعنى كاملًا.\",\"p\":\"يا رب، علّمني الحكمة في الصمت والكلام. احفظ في قلبي ما أعطيتني حتى يحين وقت الشهادة بنعمتك. آمين.\"},{\"t\":\"تحمل ما يأتيك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيرابيون: إذا أردت أن تكون متواضعًا فدرّب نفسك على تحمل ما يأتيك من الآخرين. النزول من الجبل يعني احتمال الناس. تحمل اليوم كلمة ثقيلة بصمت وصلِّ للمتكلم.\",\"p\":\"يا رب، علّمني أن أحتمل بتواضع. أعطني صبر النزول إلى الناس. آمين.\",\"fq\":522}]},\"8-21\":{\"th\":\"نفوس الصديقين بيد الله\",\"m\":[{\"t\":\"الرب ينقذ نفوس عبيده\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"الرب ينقذ نفوس عبيده؛ ولا يندم جميع المتكلين عليه.\",\"r\":\"الرب ينقذ نفوس عبيده، ولا يندم جميع المتكلين عليه. نفوس الصديقين بيد الله فلا يمسها عذاب. لا تخف من ساعة الرحيل، بل استعد لها بتوبة هادئة اليوم.\",\"p\":\"يا رب، نفسي بين يديك. أنقذني ساعة الرحيل، ولا تدعني أخزى أبدًا. آمين.\"},{\"t\":\"بيد الله\",\"ref\":\"الحكمة ٣: ١\",\"bk\":\"الحكمة\",\"v\":\"اما نفوس الصديقين فهي بيد الله فلا يمسها العذاب\",\"r\":\"«أما نفوس الصديقين فهي بيد الله، فلا يمسها العذاب». الموت يبدو للناس نهاية وشقاء، لكن الإيمان يراه انتقالًا إلى يد الله. وما يبدو خسارة هو في الحقيقة بداية سلام ثابت لا ينقطع.\",\"p\":\"يا رب، نفوس الصديقين بيدك. أشكرك على أحبائي الراحلين، واحفظهم في سلامك، وعزّ قلوبنا برجاء اللقاء. آمين.\"},{\"t\":\"تذكر الموت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب إفاغريوس: عندما تجلس في قلايتك اجمع فكرك وتذكر أيام الموت وافهم المصيبة، لتثبت في السكينة ولا تضعف. ذكر الموت يعلّمنا الأولويات. اسأل نفسك اليوم: ماذا يهم فعلًا لو كان هذا آخر يوم؟\",\"p\":\"يا رب، علّمني إحصاء أيامي. أعطني أن أحيا كل يوم كما لو كان الأخير. آمين.\",\"fq\":108}]},\"8-22\":{\"th\":\"نياحة السيدة العذراء\",\"m\":[{\"t\":\"أنهضي نفسي المريضة\",\"ref\":\"قطعة النوم (٣)\",\"v\":\"أيتها العذراء الطاهرة أسبلي ظلك السريع المعونة على عبدك، وأبعدي أمواج الأفكار الرديئة عني، وأنهضي نفسي المريضة للصلاة والسهر، لأنها استغرقت في سبات عميق.\",\"r\":\"نتذكر اليوم نياحة العذراء مريم الأم الطاهرة التي انتقلت إلى مجد ابنها. نطلب شفاعتها لتنهض نفوسنا من نوم الغفلة. صلِّ اليوم لأجل شخص بعيد، واطلب من العذراء أن تشفع.\",\"p\":\"يا رب، بصلوات والدة الإله القديسة مريم أنهض نفسي من الغفلة. أعطني رجاء اللقاء بك. آمين.\"},{\"t\":\"المشرفة مثل الصباح\",\"ref\":\"نشيد الأنشاد ٦: ١٠\",\"bk\":\"نشيد الأنشاد\",\"v\":\"من هي المشرفة مثل الصباح، جميلة كالقمر، طاهرة كالشمس، مرهبة كجيش بألوية؟\",\"r\":\"«من هي المشرفة مثل الصباح، جميلة كالقمر، طاهرة كالشمس؟». الكنيسة ترى في العذراء مثل الفجر الذي سبق شمس البر. ومن يحمل نور المسيح يصير هو نفسه مضيئًا لغيره، فأطلب أن أكون كذلك.\",\"p\":\"يا رب، يا شمس البر، اجعلني قمرًا يعكس نورك. وبصلوات العذراء أضئ في قلبي حتى أضيء لمن حولي. آمين.\"},{\"t\":\"الدينونة الأبدية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إفاغريوس: تذكر على الدوام ساعة خروجك ولا تنس الدينونة الأبدية، فلا توجد في نفسك خطيئة. الانتقال يذكّرنا بساعة اللقاء. اعمل اليوم عملًا واحدًا تريد أن يراه الله عند لقائه بك.\",\"p\":\"يا رب، اجعلني مستعدًا للقائك. نقِّ حياتي من كل خطيئة قبل ساعة الرحيل. آمين.\",\"fq\":111}]},\"8-23\":{\"th\":\"بيت أبي منازل كثيرة\",\"m\":[{\"t\":\"فرحت بالقائلين\",\"ref\":\"المزمور ١٢١ (١٢٢) — الغروب\",\"v\":\"هناك نصبت كراسي للقضاء كراسي بيت داود.\",\"r\":\"فرح المرنم بالقائلين إلى بيت الرب نذهب. بيت الآب فيه منازل كثيرة أعدها المسيح لنا. تأمل اليوم في الفرح بالمنزل الذي أعده لك، واعمل اليوم بما يناسب ذلك الفرح.\",\"p\":\"يا رب، أشتاق إلى بيتك الذي أعددته لنا. اجعلني أسلك اليوم كمن ينتظرك بفرح. آمين.\"},{\"t\":\"منازل كثيرة\",\"ref\":\"يوحنا ١٤: ٢\",\"bk\":\"يوحنا\",\"v\":\"في بيت أبي منازل كثيرة، وإلا فإني كنت قد قلت لكم. أنا أمضي لأعد لكم مكانا،\",\"r\":\"«في بيت أبي منازل كثيرة... أنا أمضي لأعد لكم مكانًا». يتكلم الرب عن السماء كبيت، وليس كمتاهة. يوجد مكان مُعدّ لي بيد المسيح. وهذا يرفع قلبي من الخوف إلى الشوق.\",\"p\":\"يا رب يسوع، أشكرك لأنك أعددت لي مكانًا في بيت أبيك. شوّقني إلى ذلك البيت وقدني إليه بسلام. آمين.\"},{\"t\":\"ساعة خروجك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كرونيوس إن الإنسان يجمع ذاته ويسلم نفسه للتعب الجسدي متذكرًا من كل قلبه ساعة خروجه من العالم ودينونة الله. ذكر الرحيل يخفف تعلقنا بالزائل. اكتب اليوم ما يستحق أن تحتفظ به للأبدية.\",\"p\":\"يا رب، علّمني أن أعيش للأبدية. اجعل قلبي في بيتك قبل أن يسكنه جسدي. آمين.\",\"fq\":219}]},\"8-24\":{\"th\":\"رجاء القيامة\",\"m\":[{\"t\":\"لو كان العمر ثابتًا\",\"ref\":\"قطعة النوم (٢)\",\"v\":\"لو كان العمر ثابتًا وهذا العالم مؤبدًا لكان لك يا نفسي حجة واضحة. لكن إذا انكشفت أفعالك أمام الديان العادل، فأي جواب تجيبين؟\",\"r\":\"صلاة النوم توقظ النفس لتتذكر أن الحياة قصيرة وأن القيامة حقيقة وراء الموت. الرجاء بالقيامة يحول الخوف من الموت إلى ترقب لقاء. قبل أن تنام الليلة قل: يا رب أنا أنتظر قيامتك.\",\"p\":\"يا رب، يا قيامتنا ورجاءنا، أيقظ نفسي من غفلتها. اجعلني مستعدًا للقائك ورجائي ثابت فيك. آمين.\"},{\"t\":\"ابتلع الموت إلى غلبة\",\"ref\":\"كورنثوس الأولى ١٥: ٥٤\",\"bk\":\"كورنثوس الأولى\",\"v\":\"ومتى لبس هذا الفاسد عدم فساد، ولبس هذا المائت عدم موت، فحينئذ تصير الكلمة المكتوبة: «ابتلع الموت إلى غلبة».\",\"r\":\"«ومتى لبس هذا الفاسد عدم فساد، ولبس هذا المائت عدم موت، فحينئذ تصير الكلمة المكتوبة: ابتلع الموت إلى غلبة». الموت الذي بدا قويًا ينتهي ببلع كامل. وأنا أنتظر هذا اليوم بيقين.\",\"p\":\"يا رب، أشكرك لأنك غلبت الموت. ألبسني عدم فساد، واجعل رجائي بالقيامة حيًا وقويًا كل أيام حياتي. آمين.\"},{\"t\":\"الذهن إلى الدينونة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كرونيوس: إذا التفت الذهن وطلب الله ذاكرًا الدينونة الأخيرة، سقط الهوى للحال. رجاء القيامة يُنقي القلب. اختر اليوم هوى واحدًا، وقاومه بذكر اللقاء.\",\"p\":\"يا رب، ذكّرني بلقائك كلما غلبني هوى. قوّني بنعمة القيامة. آمين.\",\"fq\":218}]},\"8-25\":{\"th\":\"سحابة الشهود\",\"m\":[{\"t\":\"يعسكر ملاك الرب\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"يعسكر ملاك الرب حول كل خائفيه وينجيهم.\",\"r\":\"يعسكر ملاك الرب حول خائفيه وينجيهم، فنحن محاطون بسحابة من الشهود. القديسون لا يزالون يصلون معنا. اختر اليوم قديسًا وصلِّ إليه، واطلب أن تتعلم منه فضيلة.\",\"p\":\"يا رب، أحط بملائكتك وقديسيك كل من يخافك. أعطني أن أتشبه بهم في الجهاد والإيمان. آمين.\"},{\"t\":\"جبل صهيون ومدينة الله الحي\",\"ref\":\"العبرانيين ١٢: ٢٢\",\"bk\":\"العبرانيين\",\"v\":\"بل قد أتيتم إلى جبل صهيون، وإلى مدينة الله الحي. أورشليم السماوية، وإلى ربوات هم محفل ملائكة،\",\"r\":\"«بل قد أتيتم إلى جبل صهيون، وإلى مدينة الله الحي، أورشليم السماوية». حين أصلي لا أقف وحدي، بل أدخل إلى مجمع عظيم من الملائكة والقديسين. وهذا يعطي صلاتي عمقًا ويطمئن قلبي.\",\"p\":\"يا رب، أشكرك لأنك أدخلتنا إلى مدينتك السماوية. اجعلني أصلي بإحساس الانتماء إلى كنيسة واحدة في الأرض والسماء. آمين.\"},{\"t\":\"اقتنوا الفضائل بأتعابهم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أرسانيوس عن المصريين: هؤلاء اقتنوا الفضائل بأتعابهم. القديسون لم يرثوا القداسة، بل جاهدوا لأجلها. التعب اليوم في محبتك للمسيح هو بذار القداسة.\",\"p\":\"يا رب، أعطني اشتياقًا إلى جهاد القديسين. لا تدعني أستسهل، بل أتعب لأجلك. آمين.\",\"fq\":26}]},\"8-26\":{\"th\":\"أمامك شبع سرور\",\"m\":[{\"t\":\"طلبت إلى الرب فاستجاب\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"طلبت إلى الرب فاستجاب لي. ومن جميع مخاوفي نجاني.\",\"r\":\"طلب المرنم إلى الرب فاستجاب له ونجاه من جميع مخاوفه. الشبع الحقيقي سرور في حضرته. اكتب اليوم ثلاث طلبات، وسلّمها له وانتظر.\",\"p\":\"يا رب، أشكرك لأنك تستجيب. نجّني من مخاوفي، وأشبع نفسي من سرور حضرتك. آمين.\"},{\"t\":\"سبيل الحياة\",\"ref\":\"المزامير ١٦: ١١\",\"bk\":\"المزامير\",\"v\":\"تعرفني سبيل الحياة. أمامك شبع سرور. في يمينك نعم إلى الأبد.\",\"r\":\"«تعرفني سبيل الحياة. أمامك شبع سرور. في يمينك نعم إلى الأبد». الله لا يعطيني معلومات عن الطريق فقط، بل هو نفسه الطريق. وفي حضرته أشبع، فلا أطلب سرورًا خارجه.\",\"p\":\"يا رب، عرّفني سبيل الحياة. أمامك شبع سرور، فاملأني بحضورك حتى لا أطلب غيرك أبدًا. آمين.\"},{\"t\":\"سرور في النفس\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي إن من يحتمل الجوع الطوعي يزرع في جسده حزنًا ويزرع في نفسه سرورًا وراحة. السرور الحقيقي ثمرة تضحية. ضحِّ اليوم بشيء صغير يرضيك، واشعر بسرور داخلي.\",\"p\":\"يا رب، علّمني أن أجد سروري فيك. اجعل تضحياتي ثمرة سلام في قلبي. آمين.\",\"fq\":534}]},\"8-27\":{\"th\":\"انتظار النفس\",\"m\":[{\"t\":\"خلاصه قريب\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"لأن خلاصه قريب من جميع خائفيه؛ ليسكن المجد في أرضنا.\",\"r\":\"أسمع ما يتكلم به الرب، لأن خلاصه قريب من خائفيه وليسكن المجد في أرضنا. انتظار النفس صمت واستماع. اجلس اليوم عشر دقائق صامتًا وانتظر الله.\",\"p\":\"يا رب، أسمع ما تقول لأن خلاصك قريب. اجعل نفسي تنتظرك بصمت وسلام. آمين.\"},{\"t\":\"لله انتظري يا نفسي\",\"ref\":\"المزامير ٦٢: ٥\",\"bk\":\"المزامير\",\"v\":\"إنما لله انتظري يا نفسي، لأن من قبله رجائي.\",\"r\":\"«إنما لله انتظري يا نفسي، لأن من قبله رجائي». أحيانًا تنتظر نفسي حلولًا من الناس أو الظروف، فأتعب. لكن داود يعلمني أن أخاطب نفسي وأوجهها: لله انتظري. فهو وحده يعطي رجاءً لا يخيب.\",\"p\":\"يا رب، لك وحدك أنتظر يا نفسي، فمنك رجائي. اسكب قلبي أمامك، واملأه ثقة بأنك صخرتي وخلاصي. آمين.\"},{\"t\":\"الصمت مع التواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيسوى: ما تطلبه هو الصمت الكثير مع التواضع، وهنيئًا للذين يثبتون فيه. الانتظار الحقيقي سكوت داخلي. صُم اليوم عن حديث غير ضروري.\",\"p\":\"يا رب، أعطني صمتًا متواضعًا. ثبّتني في انتظارك حتى يأتي خلاصك. آمين.\",\"fq\":505}]},\"8-28\":{\"th\":\"كفطيم نحو أمه\",\"m\":[{\"t\":\"مثل الفطيم على أمه\",\"ref\":\"المزمور ١٣٠ — النوم\",\"v\":\"فان كنت لم أتضع لكن رفعت صوتي مثل الفطيم من اللبن على أمه؛ كذلك المجازاة على نفسي. فليتكل إسرائيل على الرب من الآن والى الأبد هلليلويا.\",\"r\":\"يطلب المرنم الهدوء كالفطيم على أمه، فيتكل إسرائيل على الرب من الآن وإلى الأبد. الراحة في حضن الله لا في عظائم الأمور. اترك اليوم أمرًا أكبر منك، وارتح في يد الله.\",\"p\":\"يا رب، اجعل نفسي هادئة كالفطيم على أمه. أتكل عليك من الآن وإلى الأبد. آمين.\"},{\"t\":\"كفطيم\",\"ref\":\"المزامير ١٣١: ٢\",\"bk\":\"المزامير\",\"v\":\"بل هدأت وسكت نفسي كفطيم نحو أمه. نفسي نحوي كفطيم.\",\"r\":\"«بل هدأت وسكتت نفسي كفطيم نحو أمه». الفطيم ليس جائعًا يطلب اللبن، بل يستريح لأن أمه حاضرة. هكذا أريد أن تكون صلاتي أحيانًا: لا طلبات بل راحة في حضن الله.\",\"p\":\"يا رب، هدّئ نفسي كفطيم نحو أمه. أعطني أن أستريح في حضرتك بلا ضجيج ولا شكوى. آمين.\"},{\"t\":\"طريق التواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب تيثوى: إن طريق التواضع هي ضبط النفس والصلاة وأن يكون المرء دون الخليقة كلها. الراحة في الله تأتي بالتواضع. مارس اليوم ضبط النفس في أمر صغير.\",\"p\":\"يا رب، علّمني طريق التواضع. أعطني ضبط النفس والصلاة. آمين.\",\"fq\":547}]},\"8-29\":{\"th\":\"صالح هو الرب\",\"m\":[{\"t\":\"جميع طرق الرب رحمة\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"جميع طرق الرب رحمة وحق لحافظي عهده وشهاداته.\",\"r\":\"جميع طرق الرب رحمة وحق لحافظي عهده وشهاداته. صلاح الله يظهر في كل طريق يقودنا فيه. اذكر اليوم موقفًا بدا صعبًا ثم ظهر فيه صلاح الله، واشكره.\",\"p\":\"يا رب، ما أصلحك! علّمني أن أرى رحمتك في كل طريق. آمين.\"},{\"t\":\"حصن في يوم الضيق\",\"ref\":\"ناحوم ١: ٧\",\"bk\":\"ناحوم\",\"v\":\"صالح هو الرب. حصن في يوم الضيق، وهو يعرف المتوكلين عليه.\",\"r\":\"«صالح هو الرب. حصن في يوم الضيق، وهو يعرف المتوكلين عليه». في يوم الضيق، يكون الله حصنًا. ومعنى أنه «يعرف» أنه يعتني بكل واحد باسمه وبتفاصيله. فأتكل بثقة لأن اتكالي مقدّر عنده.\",\"p\":\"يا رب، أنت صالح وحصن في يوم الضيق. أشكرك لأنك تعرفني باسمي، فأتكل عليك بكل ثقة. آمين.\"},{\"t\":\"إكليل التواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أور: التواضع هو إكليل الراهب. أعظم ما يزين الإنسان هو تواضعه. تعامل اليوم مع شخص أقل منك بلطف يشبه تواضع المسيح.\",\"p\":\"يا رب، توّجني بإكليل التواضع. لا تدع المجد الباطل يسلبني إكليلي. آمين.\",\"fq\":560}]},\"8-30\":{\"th\":\"في وقته\",\"m\":[{\"t\":\"إلى متى يرتفع عدوي؟\",\"ref\":\"المزمور ١٢ (١٣) — باكر\",\"v\":\"إلى متى يرتفع عدوى علي؟\",\"r\":\"يصرخ المرنم: إلى متى؟ لكن الله يأتي في وقته لا في وقتنا. الحكمة أن ننتظر دون أن نتوقف عن الصلاة. اكتب اليوم رسالة قصيرة لله عن أمر طال انتظاره.\",\"p\":\"يا رب، أنت تعرف الوقت. علّمني أن أنتظر حسب توقيتك لا توقيتي. آمين.\"},{\"t\":\"إن توانت فانتظرها\",\"ref\":\"حبقوق ٢: ٣\",\"bk\":\"حبقوق\",\"v\":\"لأن الرؤيا بعد إلى الميعاد، وفي النهاية تتكلم ولا تكذب. إن توانت فانتظرها لأنها ستأتي إتيانا ولا تتأخر.\",\"r\":\"«إن توانت فانتظرها، لأنها ستأتي إتيانًا ولا تتأخر». أحيانًا تبدو وعود الله متأخرة، لكن الكلمة الإلهية تقول إنها لا تتأخر. فالانتظار ثقة والبار بإيمانه يحيا. وهكذا أثبت في الانتظار، وأكتب وعوده لأتذكرها وأتحرك بها.\",\"p\":\"يا رب، أنتظر وعدك الذي لا يتأخر. البار بإيمانه يحيا، فثبّت إيماني في زمن الانتظار. آمين.\"},{\"t\":\"وقت الإهانة\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح البابا ثيوفيلوس الأم ثيوذورا: افتدي وقت الإهانة بالتواضع وطول الأناة، وافتدي وقت الهوان بالصبر فتربحي. وقت الله يعلمنا الصبر. إن أهانك أحد اليوم، فالتزم الهدوء ولا ترد.\",\"p\":\"يا رب، أعطني صبرًا في ساعة الإهانة. اجعل تواضعي أقوى من كبريائي. آمين.\",\"fq\":147}]},\"8-31\":{\"th\":\"عهد سلام لا يتزعزع\",\"m\":[{\"t\":\"أنت ناصري\",\"ref\":\"المزمور الثالث — باكر\",\"v\":\"أنت يا رب أنت هو ناصري. مجدي ورافع رأسي.\",\"r\":\"أنت يا رب هو ناصري، مجدي ورافع رأسي. عهد سلام الله لا يتزعزع لأنه قائم على أمانته. اكتب اليوم عبارة أمان تكررها: الرب هو ناصري.\",\"p\":\"يا رب، أنت ناصري ورافع رأسي. ثبّت في قلبي عهد سلامك الذي لا يتزعزع. آمين.\"},{\"t\":\"إحساني لا يزول\",\"ref\":\"إشعياء ٥٤: ١٠\",\"bk\":\"إشعياء\",\"v\":\"فإن الجبال تزول، والآكام تتزعزع، أما إحساني فلا يزول عنك، وعهد سلامي لا يتزعزع، قال راحمك الرب.\",\"r\":\"«فإن الجبال تزول، والآكام تتزعزع، أما إحساني فلا يزول عنك، وعهد سلامي لا يتزعزع». قد تتغير الأحوال وتتهدم المشاريع وتبتعد وجوه، لكن إحسان الله ثابت. وهذا هو أساس سلامي.\",\"p\":\"يا رب، الجبال تزول وإحسانك لا يزول. أشكرك على عهد سلامك الثابت، واحفظني فيه في الشهر القادم وكل أيامي. آمين.\"},{\"t\":\"قلب عفيف تجاه كل واحد\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سارة: إن طلبت أن يكون الجميع مرتاحين مني، فسأكون عند باب كل واحد تائبة، لكني سأصلي ليكون قلبي عفيفًا تجاه كل واحد. السلام يبدأ بقلب نقي. صلِّ اليوم من أجل نقاء قلبك نحو شخص صعب.\",\"p\":\"يا رب، اجعل قلبي نقيًا نحو الجميع. أقِم فيّ سلامك الذي لا يتزعزع. آمين.\",\"fq\":528}]},\"9-1\":{\"th\":\"شكر ختام السنة\",\"m\":[{\"t\":\"إلى الأبد أعترف لك\",\"ref\":\"المزمور ٢٩ (٣٠) — الثالثة\",\"v\":\"أيها الرب إلهي إلى الأبد أعترف لك.\",\"r\":\"نبدأ السنة القبطية الجديدة بالشكر قبل الطلب. يعترف المرنم للرب إلى الأبد لأن رحمته لا تنقطع. اكتب اليوم ثلاث نعم صنعها الله معك في السنة الماضية، وصلِّ بها شكرًا.\",\"p\":\"يا رب إلهي، إلى الأبد أعترف لك. أشكرك على سنة مضت بنعمتك، وبارك أيامي الجديدة. آمين.\"},{\"t\":\"يكللك بالرحمة\",\"ref\":\"المزامير ١٠٣: ٤\",\"bk\":\"المزامير\",\"v\":\"الذي يفدي من الحفرة حياتك. الذي يكللك بالرحمة والرأفة.\",\"r\":\"«الذي يفدي من الحفرة حياتك. الذي يكللك بالرحمة والرأفة». الله لم ينقذني فقط من السقوط، بل وضع على رأسي إكليلًا من الرحمة. ومع اقتراب نهاية السنة القبطية أتذكر كم حملتني رحمته في كل شهر، وأشكره من قلبي.\",\"p\":\"يا رب، أشكرك لأنك فديت حياتي من الحفرة وكللتني بالرحمة والرأفة طوال هذه السنة. باركني بالمزيد من نعمتك. آمين.\"},{\"t\":\"الشكر على الصمت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بمفو: الشكر لله أنني منذ رفضت العالم لم أندم على كلمة تلفظت بها. من يختم عامه بقلب مطمئن على ما قاله وفعله فقد ربح كثيرًا. راجع اليوم كلماتك في العام الماضي، واطلب مسامحة من جرحتهم.\",\"p\":\"يا رب، أشكرك على حفظك لساني. اغفر لي كلماتي الجارحة، وضع حارسًا على فمي في العام الجديد. آمين.\",\"fq\":458}]},\"9-2\":{\"th\":\"أغني للرب في حياتي\",\"m\":[{\"t\":\"أسبح الرب في حياتي\",\"ref\":\"المزمور ١٤٥ — النوم\",\"v\":\"سبحي يا نفسي الرب، أسبح الرب في حياتي وأرتل لإلهي ما دمت موجودا.\",\"r\":\"يقرر المرنم أن يسبح الرب ما دام موجودًا، فالتسبيح عمل العمر كله لا لحظة عابرة. أغنية الحياة تبدأ بنية يومية. رتّل اليوم مزمورًا أو ترنيمة في وقت غير متوقع، في الطريق أو المطبخ.\",\"p\":\"يا رب، أسبحك في حياتي كلها وأرتل لك ما دمت موجودًا. اجعل أيامي ترنيمة شكر لك. آمين.\"},{\"t\":\"أرنم ما دمت موجودًا\",\"ref\":\"المزامير ١٠٤: ٣٣\",\"bk\":\"المزامير\",\"v\":\"أغني للرب في حياتي. أرنم لإلهي ما دمت موجودا.\",\"r\":\"«أغني للرب في حياتي. أرنم لإلهي ما دمت موجودًا». لم يقل داود: عندما أشعر أو عندما أكون بخير، بل ما دمت موجودًا. فالترنيم ليس مزاجًا بل قرار حياة. وأريد أن أقرر اليوم أن أجعل التسبيح عادتي.\",\"p\":\"يا رب، أغني لك في حياتي كلها وأرنم لإلهي ما دمت موجودًا. اجعل نشيدي لذيذًا لك، وفرّح قلبي بك. آمين.\"},{\"t\":\"أفواه طاهرة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بمفو عن الرهبان: هؤلاء يتكلمون مع الله على الدوام وأفواههم طاهرة. الفم الذي يسبح لا يليق به أن يدين. اجعل لك اليوم ساعة بلا نقد ولا شكوى، ولا يخرج منها إلا تسبيح.\",\"p\":\"يا رب، طهّر فمي لأتكلم معك على الدوام. اجعل كلماتي تسبيحًا وبركة لمن يسمعني. آمين.\",\"fq\":460}]},\"9-3\":{\"th\":\"أبواب الحمد\",\"m\":[{\"t\":\"ابتدئوا للرب بالاعتراف\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"ابتدئوا للرب بالاعتراف. رتلوا لإلهنا بالقيثارة.\",\"r\":\"يدعونا المرنم أن نبتدئ للرب بالاعتراف ونرتل له بالقيثارة. أبواب الحمد تُفتح بشكر صادق. ابدأ يومك اليوم بكلمة حمد واحدة قبل أي هاتف أو رسالة.\",\"p\":\"يا رب، افتح لي أبواب الحمد. أبتدئ يومي بالاعتراف بصلاحك، وأرتل لك بقلب شاكر. آمين.\"},{\"t\":\"إن إلى الأبد رحمته\",\"ref\":\"المزامير ١١٨: ١\",\"bk\":\"المزامير\",\"v\":\"احمدوا الرب لأنه صالح، لأن إلى الأبد رحمته.\",\"r\":\"«احمدوا الرب لأنه صالح، لأن إلى الأبد رحمته». هذه الدعوة تفتتح مزمورًا يغنيه شعب الله عند دخول بيت الرب. وأنا أدخل حياتي اليومية بنفس الروح، شاكرًا قبل أن أطلب.\",\"p\":\"يا رب، أحمدك لأنك صالح ورحمتك إلى الأبد. أدخل أبوابك بحمد، فاقبلني في حضرتك. آمين.  ثبّتنا في بيتك كل أيامنا يا رب.\"},{\"t\":\"لا كذب في الفم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أنوف: منذ أن حل عليّ اسم المسيح لم يخرج من فمي كذب. الحمد الصادق يحتاج لسانًا صادقًا. اختر اليوم ألا تقول أي مبالغة أو كذبة صغيرة، حتى المجاملة.\",\"p\":\"يا رب، اجعلني أحمل اسمك بصدق. احفظ فمي من الكذب، ليخرج منه حمد وحق. آمين.\",\"fq\":70}]},\"9-4\":{\"th\":\"أرى جود الرب\",\"m\":[{\"t\":\"رحمتك تدركني\",\"ref\":\"المزمور ٢٢ (٢٣) — الثالثة\",\"v\":\"هيأت قدامى مائدة تجاه مضايقي. مسحت بالزيت رأسي. وكأسك روتني بقوة. ورحمتك تدركني جميع أيام حياتي، ومسكني في بيت الرب إلى مدى الأيام.\",\"r\":\"يصف المرنم مائدة أعدها الله ورأسًا مسحه بالزيت وكأسًا ريانة، ثم تدركه الرحمة كل أيام حياته. جود الرب يُرى في التفاصيل اليومية. انتبه اليوم إلى ثلاثة أشياء صغيرة تعطيها لك نعمته وسط الزحام.\",\"p\":\"يا رب، أنت راعيّ فلا يعوزني شيء. أشكرك على مائدتك ورحمتك التي تدركني، واجعلني أسكن في بيتك. آمين.\"},{\"t\":\"آمنت بأن أرى جود الرب\",\"ref\":\"المزامير ٢٧: ١٣\",\"bk\":\"المزامير\",\"v\":\"لولا أنني آمنت بأن أرى جود الربفي أرض الأحياء.\",\"r\":\"«لولا أنني آمنت بأن أرى جود الرب في أرض الأحياء». نصف الجملة يتركه داود مفتوحًا: لولا الإيمان لكان الأمر أصعب. فالإيمان بأنني سأرى صلاح الله في هذه الحياة هو ما يمسكني في أصعب اللحظات.\",\"p\":\"يا رب، أؤمن بأنني سأرى جودك في أرض الأحياء. قوِّ إيماني في ساعات الانتظار، وافتح عيني لرؤية خيراتك. آمين.\"},{\"t\":\"آخذ وأعطي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب زينون: إذا قدّم لي أحد شيئًا آخذه، وإذا جاء أحد يطلب شيئًا أعطيه إياه. بساطة العطاء والقبول ترى جود الله في عطايا الناس. اقبل اليوم عطية صغيرة بشكر، وأعطِ من يسألك دون تردد.\",\"p\":\"يا رب، علّمني أن أقبل بشكر وأعطي بفرح. اجعل بيتي مفتوحًا لعطاياك ولمحتاجيك. آمين.\",\"fq\":115}]},\"9-5\":{\"th\":\"طرقك علمني\",\"m\":[{\"t\":\"على الصخرة رفعتني وأرشدتني\",\"ref\":\"المزمور ٦٠ (٦١) — السادسة\",\"v\":\"استمع يا الله طلبتي، وأصغ إلى صلاتي. من أقاصي الأرض صرخت إليك، عندما ضجر قلبي. على الصخرة رفعتني وأرشدتني.\",\"r\":\"يصرخ المرنم من أقاصي الأرض عندما يضجر قلبه، فيرفعه الله على صخرة ويرشده. الله لا يسمع صلاة من يعلم الطريق فقط، بل من يطلب الإرشاد. اسأل الله اليوم: ما هي الخطوة التالية؟ وانتظر جوابه.\",\"p\":\"يا رب، استمع طلبتي وأصغ إلى صلاتي. ارفعني على الصخرة وأرشدني في طريقي. آمين.\"},{\"t\":\"عرفني طرقك\",\"ref\":\"المزامير ٢٥: ٤\",\"bk\":\"المزامير\",\"v\":\"طرقك يا رب عرفني. سبلك علمني.\",\"r\":\"«طرقك يا رب عرفني. سبلك علمني». هذه صلاة تلميذ. لا يطلب داود أن يغير الله طريقه بل أن يعلمه طريق الله. وكل يوم أحتاج أن أبدأ بالسؤال: ما هي طرقك اليوم يا رب؟\",\"p\":\"يا رب، عرفني طرقك وعلمني سبلك. دربني في حقك فإنك أنت إله خلاصي، وإياك أنتظر اليوم كله. آمين.\"},{\"t\":\"إرادة الله حيثما ذهبت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إسحق كاهن القلالي: لن أهرب بعد الآن لأن هذه إرادة الله، فحيثما ذهبت أصل إلى ذلك بعينه. الإرشاد أن نثبت في ما وضعنا الله فيه. اقبل اليوم ظرفًا تحاول الهرب منه، واطلب فيه حضور الله.\",\"p\":\"يا رب، علّمني أن أقبل مشيئتك. أعطني ألا أهرب من ظروفي بل أجد فيها طريقك. آمين.\",\"fq\":176}]},\"9-6\":{\"th\":\"كلمتك في قلبي\",\"m\":[{\"t\":\"لساني ينطق بأقوالك\",\"ref\":\"المزمور ١١٨ — الجزء الثاني والعشرون («كُونوا مُستَعِدّينَ، لأنَّهُ في ساعَةٍ لا تَظُنّونَ يَأتي ابنُ الإنسان.») — الستار\",\"v\":\"تفيض شفتاي السبح إذا ما علمتني حقوقك. لساني ينطق بأقوالك لأن جميع وصاياك عادلة. لتكن يدك لخلاصي لأنني اشتهيت وصاياك.\",\"r\":\"يطلب المرنم أن تفيض شفتاه تسبيحًا إذا علمه الله حقوقه، وأن ينطق لسانه بأقواله. كلمة الله لا تبقى في الذاكرة بل تنتقل إلى القلب. اقرأ اليوم آية وحاول أن تحفظها بتكرارها صامتًا ثلاث مرات.\",\"p\":\"يا رب، علّمني حقوقك فتفيض شفتاي بالتسبيح. لتكن يدك لخلاصي، فقد اشتهيت وصاياك. آمين.\"},{\"t\":\"خبأت كلامك في قلبي\",\"ref\":\"المزامير ١١٩: ١١\",\"bk\":\"المزامير\",\"v\":\"خبأت كلامك في قلبي لكيلا أخطئ إليك.\",\"r\":\"«خبأت كلامك في قلبي لكيلا أخطئ إليك». الكلمة المحفوظة في القلب حاضرة لحظة التجربة، مثل سلاح مخبأ. فالقراءة السطحية لا تكفي، بل أحتاج أن أحفظ آيات وأتأمل فيها حتى تصير جزءًا مني.\",\"p\":\"يا رب، أخبئ كلامك في قلبي لكيلا أخطئ إليك. ثبّت كلمتك فيّ وذكّرني بها في ساعات التجربة. آمين.\"},{\"t\":\"ما في القلب ينطق به الفم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب بيمن: علّم فمك أن ينطق بمكنونات قلبك. حين يمتلئ القلب بكلمة الله ينطق الفم بها. اجعل اليوم كلمة الله حاضرة في محادثة واحدة، لا بوعظ بل بصدق.\",\"p\":\"يا رب، املأ قلبي بكلمتك ليتكلم فمي بها. احفظني من التناقض بين فمي وقلبي. آمين.\",\"fq\":360}]},\"9-7\":{\"th\":\"كلمة تثبت\",\"m\":[{\"t\":\"المخبر كلمته ليعقوب\",\"ref\":\"المزمور ١٤٧ — النوم\",\"v\":\"المخبر كلمته ليعقوب وفرائضه وأحكامه لإسرائيل.\",\"r\":\"الله يخبر بكلمته وفرائضه وأحكامه شعبه، والعشب يجف أما كلمته فتثبت. ما يثبت في الحياة هو ما بُني على كلمته. اختر اليوم قرارًا واحدًا تبنيه على وعد من وعود الله.\",\"p\":\"يا رب، كلمتك تثبت إلى الأبد. ثبّت قلبي على وعودك، ولا تدعني أبني على رمال الظنون. آمين.\"},{\"t\":\"كلمة إلهنا تثبت\",\"ref\":\"إشعياء ٤٠: ٨\",\"bk\":\"إشعياء\",\"v\":\"يبس العشب، ذبل الزهر. وأما كلمة إلهنا فتثبت إلى الأبد».\",\"r\":\"«يبس العشب، ذبل الزهر. وأما كلمة إلهنا فتثبت إلى الأبد». كم من الأشياء التي كنت أظنها دائمة ذبلت. لكن كلمة الله لم تتغير. وعندما أبني حياتي عليها، أبني على ما لا يزول.\",\"p\":\"يا رب، كل جسد عشب وكلمتك تثبت إلى الأبد. اجعلني أبني حياتي على كلمتك التي لا تزول. آمين.\"},{\"t\":\"حفظ وصايا الآباء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى: إذا حفظنا وصايا آبائنا أضمن لكم أن البرابرة لا يأتون إلى هنا، وإن لم نحفظها فإن المنطقة هذه ستقفر. الكلمة التي تثبت هي التي نحفظها ونسلمها. التزم اليوم بوصية واحدة تسلمتها من آبائك.\",\"p\":\"يا رب، علّمني أن أحفظ تعليم آبائي. ثبّت في قلبي كلمتك، وسلّمها لمن بعدي. آمين.\",\"fq\":257}]},\"9-8\":{\"th\":\"هلموا إلى المياه\",\"m\":[{\"t\":\"تهب ريحه فتسيل المياه\",\"ref\":\"المزمور ١٤٧ — النوم\",\"v\":\"يرسل كلمته فتذيبه، تهب ريحه فتسيل المياه.\",\"r\":\"يسبح المرنم الله الذي يرسل كلمته فتذيب الجليد وتهب ريحه فتسيل المياه. كل ما يُروى به الإنسان من عطشه من يديه. هلموا إلى المياه التي لا تُشترى. أصغ اليوم إلى عطش داخلك وسمّه، ثم قدمه لله.\",\"p\":\"يا رب، أنت ينبوع الماء الحي. أرو عطشي بكلمتك، ولا تدعني أشرب من آبار مشققة. آمين.\"},{\"t\":\"أيها العطاش هلموا\",\"ref\":\"إشعياء ٥٥: ١\",\"bk\":\"إشعياء\",\"v\":\"«أيها العطاش جميعا هلموا إلى المياه، والذي ليس له فضة تعالوا اشتروا وكلوا. هلموا اشتروا بلا فضة وبلا ثمن خمرا ولبنا.\",\"r\":\"«أيها العطاش جميعًا هلموا إلى المياه». دعوة لا تشترط استحقاقًا ولا مالًا. يكفي أن أعطش. وفي كثير من الأحيان أحاول أن أدفع ثمن النعمة بأعمالي، لكن الله يقول: تعال بلا فضة.\",\"p\":\"يا رب، أنا عطشان إليك. هلم بي إلى ينبوعك المجاني، واروِ نفسي بروحك القدوس. آمين.  واسقني من ينبوعك كل يوم يا رب.\"},{\"t\":\"ينابيع الماء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن الرهبان عندما يقيمون في البرية يلتهبون بسم الشياطين، فيأتون إلى ينابيع الماء، أعني جسد المسيح ودمه، ليتطهروا من مرارة الشرير. الشركة المقدسة ينبوع لا ينضب. حاول اليوم أن تتناول من الأسرار باستعداد.\",\"p\":\"يا رب، أنت الينبوع الحي. اغسلني بجسدك ودمك، وأرو عطشي بحضورك. آمين.\",\"fq\":330}]},\"9-9\":{\"th\":\"روح الرب علي\",\"m\":[{\"t\":\"انسكبت النعمة على شفتيك\",\"ref\":\"المزمور ٤٤ (٤٥) — الثالثة\",\"v\":\"وقد انسكبت النعمة على شفتيك. فلذلك باركك الله إلى الدهر.\",\"r\":\"انسكبت النعمة على الشفتين، فباركه الله إلى الدهر. مسحة الروح تُعطى لخدمة الكلمة والرحمة. اطلب اليوم من الله أن يمسحك لخدمة واحدة تقدمها: كلمة تشجيع أو قراءة أو تعليم.\",\"p\":\"يا رب، روحك عليّ لأبشر المساكين وأعصب منكسري القلوب. انسكب نعمتك عليّ لأخدم باسمك. آمين.\"},{\"t\":\"مسحني لأبشر\",\"ref\":\"إشعياء ٦١: ١\",\"bk\":\"إشعياء\",\"v\":\"روح السيد الرب علي، لأن الرب مسحني لأبشر المساكين، أرسلني لأعصب منكسري القلب، لأنادي للمسبيين بالعتق، وللمأسورين بالإطلاق.\",\"r\":\"«روح السيد الرب علي، لأن الرب مسحني لأبشر المساكين». هذه رسالة المسيح، وهي تصير رسالتي بقدر ما أحمل روحه. فالمسحة ليست امتيازًا بل خدمة للمنكسرين والمأسورين.  فاجعلني يا رب أحمل بشارتك للمنكسرين حولي.\",\"p\":\"يا رب، روحك عليّ فأبشر المساكين وأعصب المنكسرين. استخدمني لتحرير المأسورين وتعزية الحزانى. آمين.  املأني بروحك لأخدم المتألمين بفرح، يا رب.\"},{\"t\":\"موهبة تأخذ زمنًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب مكاريوس: لقد أمضيت اثنتي عشرة سنة في خدمة ربي كي يمنحني هذه الموهبة. المواهب الروحية تنمو بالصبر والخدمة الطويلة. لا تيأس من موهبتك البطيئة، واستمر اليوم في تنميتها.\",\"p\":\"يا رب، أعطني صبرًا في خدمتك. وعلّمني ألا أستعجل مواهب روحك، بل أطلبها بتواضع. آمين.\",\"fq\":236}]},\"9-10\":{\"th\":\"استعداد للعام الجديد\",\"m\":[{\"t\":\"انتظرت نفسي الرب\",\"ref\":\"المزمور ١٢٩ (١٣٠) — النوم\",\"v\":\"صبرت نفسي لناموسك. انتظرت نفسي الرب من محرس الصبح إلى الليل.\",\"r\":\"صبرت نفس المرنم لناموس الرب وانتظرته من محرس الصبح إلى الليل. بداية عام جديد فرصة لتجديد كل شيء. حدد اليوم مجالًا واحدًا تريد أن تتغير فيه في هذا العام، وسلّمه للرب.\",\"p\":\"يا رب، أنت تعطي حياة جديدة. صبرت نفسي لناموسك، فأعدّني لعام جديد ببركتك. آمين.\"},{\"t\":\"أعوض لكم عن السنين\",\"ref\":\"يوئيل ٢: ٢٥\",\"bk\":\"يوئيل\",\"v\":\"«وأعوض لكم عن السنين التي أكلها الجراد، الغوغاء والطيار والقمص، جيشي العظيم الذي أرسلته عليكم.\",\"r\":\"«وأعوض لكم عن السنين التي أكلها الجراد». كم من سنوات أظن أنها ضاعت بالخطية أو الإهمال أو المرض. والله يعد بالتعويض. فلا أدخل العام الجديد بحسرة على الماضي بل برجاء أن الله يستطيع أن يرد.\",\"p\":\"يا رب، اعوض لي عن السنين التي أكلها الجراد. أسلمك ماضيّ كله، فاصنع معي عجبًا واملأ فمي تسبيحًا. آمين.\"},{\"t\":\"أن أهدم لأبني\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ألونيوس: إذا لم أهدم كل شيء لا أستطيع أن أبني نفسي. التجديد يبدأ بالتخلي عما لا يصلح. تخلَّ اليوم عن عادة أو فكرة قديمة تعطل نموّك.\",\"p\":\"يا رب، اهدم فيّ ما لا يرضيك وابنني من جديد. اجعل عامي الجديد بداية أخرى معك. آمين.\",\"fq\":73}]},\"9-11\":{\"th\":\"النيروز: عيد الشهداء\",\"m\":[{\"t\":\"الصديقون صرخوا\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"الصديقون صرخوا والرب استجاب لهم، ومن جميع شدائدهم نجاهم.\",\"r\":\"الصديقون صرخوا والرب استجاب لهم ومن جميع شدائدهم نجاهم. في عيد النيروز نذكر شهداء الكنيسة الذين صرخوا إليه وسط الاضطهاد. صلِّ اليوم من أجل المضطهدين في العالم كله.\",\"p\":\"يا رب، استجب لصرخة شهدائك ومضطهدي كنيستك. أعطني شجاعة الأمانة حتى الموت. آمين.\"},{\"t\":\"كن أمينًا إلى الموت\",\"ref\":\"رؤيا يوحنا ٢: ١٠\",\"bk\":\"رؤيا يوحنا\",\"v\":\"لا تخف البتة مما أنت عتيد أن تتألم به. هوذا إبليس مزمع أن يلقي بعضا منكم في السجن لكي تجربوا، ويكون لكم ضيق عشرة أيام. كن أمينا إلى الموت فسأعطيك إكليل الحياة.\",\"r\":\"«كن أمينًا إلى الموت فسأعطيك إكليل الحياة». في أول توت تبدأ الكنيسة سنتها القبطية المسماة تقويم الشهداء، فتذكّرنا أن بدايتنا مبنية على أمانة أولادها. وأنا لست مطالبًا اليوم بالموت، لكنني مطالب بأمانة صغيرة في كلمة صادقة وعمل نزيه.\",\"p\":\"يا رب، أشكرك على شهدائك الذين ثبتوا حتى الدم. امنحني أمانة في الصغير والكبير، ولا تدعني أخاف من الحق، واجعلني شاهدًا لك بحياتي. آمين.\"},{\"t\":\"الذين معنا أكثر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس عن الملائكة: هؤلاء هم الذين يرسلهم الله لمساعدة القديسين، أما الذين في الغرب فهم الذين يحاربونهم، والذين معنا هم أكثر عددًا. الشهداء ثبتوا لأنهم رأوا هذه القوة. ثق اليوم أن من معك أكثر.\",\"p\":\"يا رب، افتح عيني لأرى ملائكتك حولي. اجعلني ثابتًا مثل شهدائك لأن معي من هو أعظم. آمين.\",\"fq\":252}]},\"9-12\":{\"th\":\"الصبر في الضيق\",\"m\":[{\"t\":\"أبث لديه ضيقي\",\"ref\":\"المزمور ١٤١ (١٤٢) — النوم\",\"v\":\"بصوتي إلى الرب تضرعت. أسكب أمامه توسلي. أبث لديه ضيقي، عند فناء روحي مني وأنت علمت سبلي.\",\"r\":\"يسكب المرنم أمام الرب توسله ويبث لديه ضيقه وهو يعلم أن الله علم سبله. الصبر في الضيق يبدأ بالكلام مع الله. اكتب اليوم ما يضايقك في رسالة قصيرة إلى الله، ثم ضعها في مكان أمين.\",\"p\":\"يا رب، بصوتي إليك تضرعت. أسكب أمامك ضيقي، وأنت تعلم سبلي، فاحفظني بصبرك. آمين.\"},{\"t\":\"الصابر إلى المنتهى\",\"ref\":\"متى ٢٤: ١٣\",\"bk\":\"متى\",\"v\":\"ولكن الذي يصبر إلى المنتهى فهذا يخلص.\",\"r\":\"«ولكن الذي يصبر إلى المنتهى فهذا يخلص». الرب لم يعدنا بطريق بلا ضيق، لكنه وعدنا بخلاص لمن يثبت. والصبر ليس سلبية، بل هو التصاقي بالرب حين يتأخر الفرج. وأنا اليوم أحتاج هذا الصبر في أمر واحد أنتظر فيه.\",\"p\":\"يا رب، امنحني نعمة الصبر حتى النهاية. لا تدعني أفتر ولا أتراجع، وقوّ إيماني حين يتأخر الجواب. آمين.\"},{\"t\":\"يضبطون أنفسهم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيسوى: إن الإخوة يضبطون أنفسهم حتى الموت دون أن يتكلموا، فمجّد الله. الصبر في الضيق ضبط للنفس بلا شكوى. تحمل اليوم متاعب صغيرة دون أن تتذمر.\",\"p\":\"يا رب، أعطني قوة الاحتمال بلا تذمر. علّمني أن أضبط نفسي وأمجدك في كل ضيق. آمين.\",\"fq\":497}]},\"9-13\":{\"th\":\"قوة الله في الضعف\",\"m\":[{\"t\":\"الآن أقوم يقول الرب\",\"ref\":\"المزمور الحادي عشر — باكر\",\"v\":\"من أجل شقاء المساكين وتنهد البائسين الآن أقوم؛ يقول الرب، أصنع الخلاص علانية.\",\"r\":\"يقول الرب إنه من أجل شقاء المساكين وتنهد البائسين الآن يقوم ويصنع الخلاص علانية. قوته تظهر حين يضعف الإنسان ولا يخفي ضعفه. اعترف اليوم بضعف تحاول إخفاءه، واطلب قوة الله فيه.\",\"p\":\"يا رب، قوتك في ضعفي تكمل. قم الآن لخلاصي، واصنع قوتك فيّ حيث أنا أضعف. آمين.\"},{\"t\":\"أنا قوي حين أنا ضعيف\",\"ref\":\"كورنثوس الثانية ١٢: ١٠\",\"bk\":\"كورنثوس الثانية\",\"v\":\"لذلك أسر بالضعفات والشتائم والضرورات والاضطهادات والضيقات لأجل المسيح. لأني حينما أنا ضعيف فحينئذ أنا قوي.\",\"r\":\"«لأني حينما أنا ضعيف فحينئذ أنا قوي». هذه ليست عبارة متناقضة، بل سر. فحين أعترف بضعفي أفتح الباب لقوة المسيح. وكثيرًا ما أخفي ضعفي خوفًا، فأحرم نفسي من قوته. فلأقدم ضعفي له اليوم بصدق.\",\"p\":\"يا رب، أعترف لك بضعفي فاسكن فيه بقوتك. لا تدعني أتكل على ذراعي، وأعطني نعمتك التي تكفيني. آمين.\"},{\"t\":\"لا أملك شيئًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب سيسوى أن نصمت ونقول: لا أملك شيئًا، لا أملك شيئًا، وأينما كنا. هذه هي الغربة. من يعترف بفقره يملأه الله. كرر اليوم هذه العبارة عند أي زهو، واستعد غنى الله.\",\"p\":\"يا رب، أنا لا أملك شيئًا إلا أنت. املأ فقري بقوتك. آمين.\",\"fq\":466}]},\"9-14\":{\"th\":\"الاتكال على الله\",\"m\":[{\"t\":\"طوبى لمن إله يعقوب معينه\",\"ref\":\"المزمور ١٤٥ — النوم\",\"v\":\"طوبى لمن إله يعقوب معينه. واتكاله على الرب إلهه. الذي صنع السماء والأرض والبحر وكل ما فيها. الحافظ العدل إلى الدهر، الصانع الحكم للمظلومين المعطي الطعام للجياع.\",\"r\":\"طوبى لمن إله يعقوب معينه واتكاله على الرب الذي صنع السماء والأرض وهو يعطي الطعام للجياع. الاتكال لا يلغي العمل لكنه يزيل القلق. سلّم اليوم همًّا ماليًّا أو أسريًّا لله بصلاة محددة.\",\"p\":\"يا رب، أنت معيني ومتكلي. أعطني طعام يومي، وعلّمني أن أترك همومي في يديك. آمين.\"},{\"t\":\"توكل من كل قلبك\",\"ref\":\"الأمثال ٣: ٥\",\"bk\":\"الأمثال\",\"v\":\"توكل على الرب بكل قلبك، وعلى فهمك لا تعتمد.\",\"r\":\"«توكل على الرب بكل قلبك، وعلى فهمك لا تعتمد». أعتمد عادة على حساباتي ثم أطلب من الله أن يباركها. أما الوصية فتقلب الترتيب: أبدأ بالله ثم أستخدم عقلي في ضوء توكلي عليه. هذا هو الأمان الحقيقي.\",\"p\":\"يا رب، أتكل عليك بكل قلبي. لا تدعني أعتمد على فهمي وحده، وقوّم طرقي كلها بحكمتك. آمين.\"},{\"t\":\"أتحزنون من أجل الخبز؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"يسأل الأب أموي: أتحزنون من أجل الخبز؟ ثم يذكر أن بعضًا غادروا بيوتهم تاركين كل شيء مفتوحة الأبواب. الاتكال على الله حرية من الخوف على الحاجات. اترك اليوم قلقًا بسبب ما ينقصك.\",\"p\":\"يا رب، أنت تعولني. حرّرني من الخوف على الغد، وعلّمني ثقة الطيور والزهور. آمين.\",\"fq\":67}]},\"9-15\":{\"th\":\"السهر والثبات\",\"m\":[{\"t\":\"فليقم الله\",\"ref\":\"قوموا يا بني النور — نصف الليل — الخدمة الأولى\",\"v\":\"فليقم الله وليتبدد جميع أعدائه. وليهرب من قدام وجهه كل مبغضي اسمه القدوس. وأما شعبك فليكن بالبركة ألوف ألو ف وربوات ربوات، يصنعون إرادتك. يا رب افتح شفتي ولينطق فمي بتسبيحك. أمين. هلليلويا.\",\"r\":\"يصلي الليل بصلاة القيام: فليقم الله وليتبدد أعداؤه، وليكن شعبه بالبركة وهو يصنع إرادته. السهر والثبات يحتاجان انتباه القلب. خصص اليوم لحظة سهر قصيرة قبل النوم أو بعد الاستيقاظ.\",\"p\":\"يا رب، افتح شفتي ولينطق فمي بتسبيحك. علّمني السهر والثبات لأصنع إرادتك. آمين.\"},{\"t\":\"اسهروا وتضرعوا\",\"ref\":\"لوقا ٢١: ٣٦\",\"bk\":\"لوقا\",\"v\":\"اسهروا إذا وتضرعوا في كل حين، لكي تحسبوا أهلا للنجاة من جميع هذا المزمع أن يكون، وتقفوا قدام ابن الإنسان».\",\"r\":\"«اسهروا إذًا وتضرعوا في كل حين». السهر هنا ليس أرقًا بل يقظة قلب. والتضرع ليس طلبات فقط بل دوام ارتباط بالله. وأنا أحتاج أن أجعل لروحي لحظات يقظة وسط انشغالات يومي.\",\"p\":\"يا رب، أيقظ قلبي وأبعد عنه ثقل الهموم. علمني أن أسهر وأصلي في كل حين لأقف أمامك بثقة. آمين.\"},{\"t\":\"كله عين\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيساريوس: ينبغي أن يكون الراهب كالشاروبيم والسارافيم، كلّه عين. السهر الحقيقي انتباه كامل للروح. راقب اليوم عينيك وأذنيك، وانتبه لما تدخله إلى قلبك.\",\"p\":\"يا رب، اجعل كياني كله يقظًا لك. احرس عيني وأذني، وثبّتني في سهرك. آمين.\",\"fq\":83}]},\"9-16\":{\"th\":\"قلب واحد ونفس واحدة\",\"m\":[{\"t\":\"لولا أن الرب كان معنا\",\"ref\":\"المزمور ١٢٣ (١٢٤) — الغروب\",\"v\":\"لولا أن الرب كان معنا ليقل إسرائيل - لولا أن الرب كان معنا عندما قام الناس علينا، لابتلعونا ونحن أحياء، عند سخط غضبهم علينا. إذا لغرقنا في الماء وعبرت نفوسنا السيل؛ بل جازت نفوسنا الماء الذي لا نهاية له. مبارك الرب الذي لم يسلمنا فريسة لأسنانهم.\",\"r\":\"لولا أن الرب كان معنا لابتلعونا أحياء، فمبارك الرب الذي لم يسلمنا فريسة. الوحدة بين المؤمنين عطية من الله الذي يحفظنا معًا. اشكره اليوم على من جمعك بهم، وصلِّ لهم بالاسم.\",\"p\":\"يا رب، مبارك أنت لأنك معنا. اجعلنا قلبًا واحدًا ونفسًا واحدة في محبتك. آمين.\"},{\"t\":\"قلب واحد\",\"ref\":\"أعمال الرسل ٤: ٣٢\",\"bk\":\"أعمال الرسل\",\"v\":\"وكان لجمهور الذين آمنوا قلب واحد ونفس واحدة، ولم يكن أحد يقول إن شيئا من أمواله له، بل كان عندهم كل شيء مشتركا.\",\"r\":\"«كان لجمهور الذين آمنوا قلب واحد ونفس واحدة». الوحدة هنا ثمرة الروح لا اتفاق آراء. وهي تظهر في عطاء مشترك لا يقول أحد فيه «هذا لي». وأنا أحتاج أن أفحص أين أتمسك بما لي وأنسى أنني جزء من جسد.\",\"p\":\"يا رب، اجعلنا قلبًا واحدًا ونفسًا واحدة. انزع الأنانية من بيننا، واملأنا بروحك لنشارك بفرح. آمين.\"},{\"t\":\"ألا يكون في قلب أحد عليّ شيء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إسحق كاهن القلالي: لم أدخل إلى قلايتي فكرًا ضد أخ أزعجني، وكان همي ألا أترك أحدًا وفي قلبه عليّ شيء. الوحدة تحتاج مصالحة. صالح اليوم أحدًا في قلبه عليك شيء.\",\"p\":\"يا رب، لا تدع في قلب أحد عليّ شيئًا. أعطني أن أبادر بالسلام والمصالحة. آمين.\",\"fq\":179}]},\"9-17\":{\"th\":\"غلبة المسيح\",\"m\":[{\"t\":\"يملك الرب إلى الدهر\",\"ref\":\"المزمور ١٤٥ — النوم\",\"v\":\"يملك الرب إلى الدهر، وإلهك يا صهيون من جيل إلى جيل هلليلويا.\",\"r\":\"يملك الرب إلى الدهر، وهو إله صهيون من جيل إلى جيل. الغلبة هبة المسيح لا إنجاز بشري. اذكر اليوم عدوًا داخليًّا تتعب منه، وقل: الغلبة للمسيح.\",\"p\":\"يا رب، أنت الملك إلى الدهر. ارحمني وأعطني غلبتك على ضعفي. آمين.\"},{\"t\":\"من يغلب\",\"ref\":\"رؤيا يوحنا ٣: ٢١\",\"bk\":\"رؤيا يوحنا\",\"v\":\"من يغلب فسأعطيه أن يجلس معي في عرشي، كما غلبت أنا أيضا وجلست مع أبي في عرشه.\",\"r\":\"«من يغلب فسأعطيه أن يجلس معي في عرشي، كما غلبت أنا أيضًا». أنا لا أغلب بمفردي بل بغلبة المسيح الذي سبقني. والمكافأة ليست جائزة صغيرة بل شركة في مجده. وهذا يعطيني دافعًا للثبات في الصراع.\",\"p\":\"يا رب، أنت غلبت العالم فأعطني أن أغلب فيك. أخرجني من الفتور، وأدخلني إلى شركة مجدك. آمين.\"},{\"t\":\"سحقت الأسد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يفسر الأب بيمن قول داود: سحقت الأسد وخنقت الدب، أي استأصلت الغضب وضيقت على الزنى بالأتعاب. المسيح يعطينا قوة نسحق بها أسودنا الداخلية. اجعل اليوم هدفًا: ألا تغضب.\",\"p\":\"يا رب، اسحق في داخلي الغضب. أعطني غلبتك على كل عادة تقيدني. آمين.\",\"fq\":393}]},\"9-18\":{\"th\":\"الوداعة\",\"m\":[{\"t\":\"الرب يرفع الودعاء\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"الرب يرفع الودعاء ويذل الخطاة إلى الأرض.\",\"r\":\"الرب يرفع الودعاء ويذل الخطاة إلى الأرض. الوداعة قوة هادئة تحمل ثقل الآخرين دون كلام. تصرف اليوم بلطف مع أول شخص يضايقك، ولاحظ كيف تنزع الوداعة الحدة.\",\"p\":\"يا رب، ارفع الودعاء وعلّمني وداعتك. اجعل قلبي لطيفًا في ردود فعلي. آمين.\"},{\"t\":\"البسوا الوداعة\",\"ref\":\"كولوسي ٣: ١٢\",\"bk\":\"كولوسي\",\"v\":\"فالبسوا كمختاري الله القديسين المحبوبين أحشاء رأفات، ولطفا، وتواضعا، ووداعة، وطول أناة،\",\"r\":\"«فالبسوا كمختاري الله أحشاء رأفات، ولطفًا، وتواضعًا، ووداعة، وطول أناة». التعبير «البسوا» يعني أن الوداعة اختيار أرتديه كل صباح. وكما أختار ثيابي أختار طبعي اليوم. فلأضع في قلبي طول الأناة عندما أتعامل مع من يزعجني.\",\"p\":\"يا رب، البسني رأفة ولطفًا ووداعة. علمني أن أطيل أناتي مع الجميع، وحوّل غضبي إلى هدوء. آمين.\"},{\"t\":\"انظر إلى تعبي وتواضعي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى الحبشي إن الصلاة بقوله: «انظر إلى تعبي وتواضعي وامح كل سيئاتي» تجعل النفس وديعة متواضعة. الوداعة ثمرة الوعي بالتعب والضعف. كرر هذه الآية اليوم.\",\"p\":\"يا رب، انظر إلى تعبي وتواضعي وامح كل سيئاتي. اجعل نفسي وديعة متواضعة. آمين.\",\"fq\":265}]},\"9-19\":{\"th\":\"التأني والانتظار\",\"m\":[{\"t\":\"فلينتظر إسرائيل الرب\",\"ref\":\"المزمور ١٢٩ (١٣٠) — النوم\",\"v\":\"من محرس الصبح فلينتظر إسرائيل الرب. لأن الرحمة من عند الرب. عظيم هو خلاصه وهو يفتدي إسرائيل من كل آثامه هلليلويا.\",\"r\":\"من محرس الصبح فلينتظر إسرائيل الرب، فالرحمة من عنده وخلاصه عظيم. التأني ثقة بتوقيت الله لا بتوقيتنا. اترك اليوم أمرًا تنتظره دون أن تضغط على الأحداث.\",\"p\":\"يا رب، أنتظرك فالرحمة من عندك. علّمني التأني، وافتد نفسي من كل إثم. آمين.\"},{\"t\":\"فتأنوا\",\"ref\":\"يعقوب ٥: ٨\",\"bk\":\"يعقوب\",\"v\":\"فتأنوا أنتم وثبتوا قلوبكم، لأن مجيء الرب قد اقترب.\",\"r\":\"«فتأنوا أنتم وثبتوا قلوبكم، لأن مجيء الرب قد اقترب». التأني ليس خمولًا بل ثبات. والرجاء في مجيء الرب يعطيني سببًا للصبر. وكثير من اضطرابي يأتي من استعجالي، فلأتعلم أن أنتظر الرب بقلب ثابت.\",\"p\":\"يا رب، ثبّت قلبي وعلمني التأني. اجعلني أنتظر مجيئك بفرح، ولا تدعني أستعجل ما لم تأذن به. آمين.\"},{\"t\":\"الراحة قبل أوانها\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ثيوذورس: كثيرون قد اختاروا الراحة هذه الأيام قبل أن يعطيهم إياها الله. التأني أن ننتظر راحة الله لا أن نصنعها بأيدينا. اصبر اليوم على التعب دون أن تهرب إلى ما يريحك سريعًا.\",\"p\":\"يا رب، علّمني أن أنتظر راحتك. لا تدعني أستعجل ما ليس بعد من عندك. آمين.\",\"fq\":138}]},\"9-20\":{\"th\":\"ثمر الروح والمحبة\",\"m\":[{\"t\":\"جعل تخومك في سلام\",\"ref\":\"المزمور ١٤٧ — النوم\",\"v\":\"لأنه قد قوى مغاليق أبوابك وبارك بنيك فيك. الذي جعل تخومك في سلام: ويملأك من شحم الحنطة.\",\"r\":\"يبارك الرب بنيه ويجعل تخومهم في سلام ويملأهم من شحم الحنطة. ثمر الروح محبة وفرح وسلام، وأول علاماته أنه يجمع ولا يفرق. اجمع اليوم بين شخصين متخاصمين بكلمة طيبة أو صلاة.\",\"p\":\"يا رب، اجعل تخومي في سلام. أثمر في حياتي ثمر روحك: المحبة والسلام والوداعة. آمين.\"},{\"t\":\"ضد هذه ليس ناموس\",\"ref\":\"غلاطية ٥: ٢٣\",\"bk\":\"غلاطية\",\"v\":\"وداعة تعفف. ضد أمثال هذه ليس ناموس.\",\"r\":\"«وداعة تعفف. ضد أمثال هذه ليس ناموس». الثمر لا يحتاج إلى أمر خارجي لأنه ينمو من الداخل. وإن عشت في الروح فسأفعل الصواب بدافع الحب لا بدافع الخوف. وهذا هو الفرق بين الواجب والحياة.\",\"p\":\"يا رب، أثمر فيّ ثمر روحك. امنحني وداعة وتعففًا، وعلمني أن أعيش بالمحبة لا بالخوف. آمين.\"},{\"t\":\"إيماءة تؤذي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أشعيا: عندما يريد الإنسان أن يقابل الشر بالشر يستطيع بإيماءة فقط أن يؤذي ضمير قريبه. ثمر الروح يحفظ حتى إشاراتنا. راقب اليوم نظراتك وحركاتك مع الآخرين.\",\"p\":\"يا رب، قدّس حتى إشاراتي. اجعل ثمر الروح ظاهرًا في لغة جسدي وكلامي. آمين.\",\"fq\":123}]},\"9-21\":{\"th\":\"محبة المصلوب\",\"m\":[{\"t\":\"سررت أن تصعد على الصليب\",\"ref\":\"قطعة السادسة (٥)\",\"v\":\"نسجد لشخصك غير الفاسد أيها الصالح، طالبين مغفرة خطايانا أيها المسيح إلهنا. لأن بمشيئتك سررت أن تصعد على الصليب لتنجي الذين خلقتهم من عبودية العدو. نصرخ إليك ونشكرك لأنك ملأت الكل فرحًا، أيها المخلص لما أتيت لتعين العالم، يا رب المجد لك.\",\"r\":\"صعد المسيح على الصليب بمشيئته ليحررنا من عبودية العدو، وهذه هي محبته للمصلوب. الصليب ليس حدثًا عابرًا بل إعلان حب. قف اليوم أمام الصليب دقيقة صمت وقل: أنت فعلت هذا لأجلي.\",\"p\":\"يا رب، لك المجد على صليبك. نسجد لك شاكرين على محبتك التي صعدت بها لأجلنا. آمين.\"},{\"t\":\"أرسل ابنه الوحيد\",\"ref\":\"يوحنا الأولى ٤: ٩\",\"bk\":\"يوحنا الأولى\",\"v\":\"بهذا أظهرت محبة الله فينا: أن الله قد أرسل ابنه الوحيد إلى العالم لكي نحيا به.\",\"r\":\"«بهذا أظهرت محبة الله فينا: أن الله قد أرسل ابنه الوحيد إلى العالم لكي نحيا به». محبة الله ليست كلامًا بل عمل تجسد وبذل. وأنا أحيا اليوم لأنه أرسل ابنه. فهل أعيش هذه الحياة بشكر أم بعادة؟\",\"p\":\"يا أبانا السماوي، أشكرك لأنك أرسلت ابنك الوحيد لنحيا به. اجعل حياتي شكرًا دائمًا لمحبتك، وقوّني لأحب كما أحببتني. آمين.\"},{\"t\":\"واقفة عند الصليب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: كان فكري عند مريم والدة الإله التي كانت واقفة عند الصليب تبكي، وكم أردت لو أبكي مثلها باستمرار. الحب يتأمل الصليب ويبكي. اقرأ اليوم مشهد الصلب بتمهل.\",\"p\":\"يا رب، أعطني أن أتأمل صليبك مع أمك. اجعل دموعي دموع محبة لا حزن بلا رجاء. آمين.\",\"fq\":420}]},\"9-22\":{\"th\":\"الذبيحة والقربان\",\"m\":[{\"t\":\"ذبيحة التهليل\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"طفت وذبحت في مظلته ذبيحة التهليل، أسبح وأرتل للرب.\",\"r\":\"يطوف المرنم ويذبح في مظلة الرب ذبيحة التهليل. الذبيحة الحقيقية قلب يفرح بتقديم ذاته. لا تنتظر ظرفًا استثنائيًّا. قدّم اليوم عملًا يكلفك راحتك وأنت تسبح.\",\"p\":\"يا رب، أقدم لك ذبيحة التهليل. اقبل من يدي ما أستطيع، ودع محبتك تكمل ما ينقصني. آمين.\"},{\"t\":\"وضع نفسه لأجلنا\",\"ref\":\"يوحنا الأولى ٣: ١٦\",\"bk\":\"يوحنا الأولى\",\"v\":\"بهذا قد عرفنا المحبة: أن ذاك وضع نفسه لأجلنا، فنحن ينبغي لنا أن نضع نفوسنا لأجل الإخوة.\",\"r\":\"«بهذا قد عرفنا المحبة: أن ذاك وضع نفسه لأجلنا، فنحن ينبغي لنا أن نضع نفوسنا لأجل الإخوة». كلمة «ينبغي» تعني أنها ليست خيارًا إضافيًا. فالمحبة التي لا تبذل لا تشبه محبة المسيح. وأنا أسأل نفسي: ما الذي أبذله اليوم؟\",\"p\":\"يا رب، علمني المحبة بالعمل والحق. افتح عيني على احتياج إخوتي، وأعطني قلبًا سخيًا يتبع بذلك مثالك على الصليب. آمين.\"},{\"t\":\"غيرة تفوق الناس\",\"ref\":\"\",\"v\":\"\",\"r\":\"تأثر الأب بمفو لأمرين: ضياع امرأة، وأنه لا يملك الحماس والغيرة الكافية لإرضاء الله كما ترضي هذه المرأة الناس. الذبيحة غيرة من أجل الله. اسأل نفسك اليوم: ما الذي أبذله لأجل الناس، ولا أبذله لأجل الله؟\",\"p\":\"يا رب، أشعل فيّ غيرة تفوق غيرتي على إرضاء الناس. علّمني أن أقدم ذاتي ذبيحة حية. آمين.\",\"fq\":457}]},\"9-23\":{\"th\":\"حمل الله\",\"m\":[{\"t\":\"الحمل والراعي\",\"ref\":\"قطعة التاسعة (٦)\",\"v\":\"عندما نظرت الوالدة الحمل والراعي مخلص العالم على الصليب معلقا قالت وهي باكية: أما العالم فيفرح لقبوله الخلاص، وأما أحشائي فتلتهب عند نظري إلى صلبوتك الذي أنت صابر عليه من أجل الكل يا ابني والهي.\",\"r\":\"تنظر الوالدة الحمل والراعي معلقًا على الصليب، فتلتهب أحشاؤها بينما يفرح العالم بالخلاص. حمل الله يرفع خطية العالم بألم الذين يحبونه. تأمل اليوم في الثمن الذي دفعه المسيح لأجلك.\",\"p\":\"أيها الحمل الذي ذُبح لأجلنا، ارحمنا. أشكرك على صليبك وخلاصك. آمين.\"},{\"t\":\"هوذا حمل الله\",\"ref\":\"يوحنا ١: ٢٩\",\"bk\":\"يوحنا\",\"v\":\"وفي الغد نظر يوحنا يسوع مقبلا إليه، فقال: «هوذا حمل الله الذي يرفع خطية العالم!\",\"r\":\"«هوذا حمل الله الذي يرفع خطية العالم». شهادة يوحنا تلخص رسالة المسيح. وهو لا يرفع خطاياي بالإهمال بل بحمل ثقلها. وعندما أنظر إليه أرى الحل لخطيتي. فلأنظر إليه اليوم أكثر مما أنظر إلى سقطاتي.\",\"p\":\"يا حمل الله الذي يرفع خطية العالم، ارحمني. احمل عني خطيتي، وطهّر قلبي بدمك، وأعطني أن أنظر إليك دائمًا. آمين.\"},{\"t\":\"بلا عيب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن الأبرار دُعوا بلا عيب لأنهم هجروا الخطيئة فصاروا أبرارًا. حمل الله بلا عيب يدعونا إلى الابتعاد عن الخطيئة. اختر اليوم خطية تكرارية، وصمم على ألا تعود إليها.\",\"p\":\"يا رب، اجعلني بلا عيب بنعمتك. علّمني أن أهجر الخطيئة محبة فيك. آمين.\",\"fq\":398}]},\"9-24\":{\"th\":\"بجراحه شفينا\",\"m\":[{\"t\":\"صرخت إليك فشفيتني\",\"ref\":\"المزمور ٢٩ (٣٠) — الثالثة\",\"v\":\"أيها الرب إلهي، صرخت إليك فشفيتني. يا رب أصعدت من الجحيم نفسي. وخلصتني من الهابطين في الجب.\",\"r\":\"صرخ المرنم إلى الرب فشفاه وأصعد من الجحيم نفسه. جراح المسيح هي مصدر شفاء جراحنا. قدّم اليوم له جرحًا قديمًا لا يزال يؤلمك، واطلب شفاءه.\",\"p\":\"يا رب، بجراحك شفيتنا. صرخت إليك فاشف انكسار قلبي واجبر كسري بمحبتك. آمين.\"},{\"t\":\"مجروح لأجل معاصينا\",\"ref\":\"إشعياء ٥٣: ٥\",\"bk\":\"إشعياء\",\"v\":\"وهو مجروح لأجل معاصينا، مسحوق لأجل آثامنا. تأديب سلامنا عليه، وبحبره شفينا.\",\"r\":\"«وهو مجروح لأجل معاصينا، مسحوق لأجل آثامنا. تأديب سلامنا عليه، وبحبره شفينا». كل جرح في المسيح يقابل جرحًا فيّ. وسلامي الحقيقي نتيجة ألمه. فلا أنسى أن راحتي اليوم ثمنها ألم لا أراه.\",\"p\":\"يا رب، بجراحك شفيتني. أشكرك على ألمك لأجلي، واشفِ جراحات نفسي، وامنحني سلامك الذي اشتريته بحبرك. آمين.\"},{\"t\":\"الناس مرضى\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أنطونيوس إن الله لا يترك الحروب تعمل في هذا الجيل كما كانت في الأجيال السالفة، لأنه يعرف أن الناس الآن مرضى ولا يحتملون. الله يرحم ضعفنا ويشفي. اشكره اليوم على أنه لا يحمّلك فوق طاقتك.\",\"p\":\"يا رب، أشكرك لأنك تعرف ضعفي. لا تحمّلني ما لا أطيق، واشفني برحمتك. آمين.\",\"fq\":12}]},\"9-25\":{\"th\":\"النبوات عن الصليب\",\"m\":[{\"t\":\"بطل الموت\",\"ref\":\"قطعة السادسة (٦)\",\"v\":\"أنت هي الممتلئة نعمة يا والدة الإله العذراء. نعظمك لأن من قبل صليب ابنك انهبط الجحيم وبطل الموت. أمواتا كنا فنهضنا، واستحققنا الحياة الأبدية، ونلنا نعيم الفردوس الأول. من أجل هذا نمجد بشكر غير المائت المسيح إلهنا.\",\"r\":\"تعظم الكنيسة العذراء لأن من قبل صليب ابنها انهبط الجحيم وبطل الموت، وقد كنا أمواتًا فنهضنا. نبوات العهد القديم عن الصليب تحققت كلها. اقرأ اليوم نبوة عن الآلام وتأمل كيف أكملها المسيح.\",\"p\":\"يا رب، لك المجد لأنك أكملت النبوات بصليبك. أمواتًا كنا فنهضنا، فاجعلنا نحيا لك. آمين.\"},{\"t\":\"ثقبوا يدي ورجلي\",\"ref\":\"المزامير ٢٢: ١٦\",\"bk\":\"المزامير\",\"v\":\"لأنه قد أحاطت بي كلاب. جماعة من الأشرار اكتنفتني. ثقبوا يدي ورجلي.\",\"r\":\"«ثقبوا يدي ورجلي». كتب داود هذه الكلمات قبل اختراع الصلب بقرون. والكنيسة ترى فيها صوت المسيح على الصليب. وهذا يؤكد لي أن الكتاب موحى به، وأن الله يعرف التاريخ من أوله إلى آخره.\",\"p\":\"يا رب، أشكرك لأن كلمتك صادقة ومتممة. علمني أن أقرأ المزامير بقلب مصلي، وأن أرى فيها صوتك وألمك لأجلي. آمين.\"},{\"t\":\"ليتم قول المسيح\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى: إن لي سنين طوالًا وأنا أنتظر هذا اليوم لكي يتم قول المسيح: «من أخذ بالسيف بالسيف يؤخذ». من ينتظر تحقق كلام الله يقبل حتى مصيره. ثق اليوم أن كلام الله يتم.\",\"p\":\"يا رب، ثبّتني على كلمتك وإن تأخرت. أعطني أن أراها تتم في وقتها. آمين.\",\"fq\":258}]},\"9-26\":{\"th\":\"الحية النحاسية\",\"m\":[{\"t\":\"داسهم بقوة صليبه\",\"ref\":\"تحليل التاسعة\",\"v\":\"اللهم أبطل عنا كل قوة المعاند وجميع جنوده الرديئة، كما داسهم ابنك الوحيد بقوة صليبه المحيي. واقبلنا إليك يا سيدي يسوع المسيح كما قبلت اللص اليمين وأنت معلق على عود الصليب.\",\"r\":\"كما رفع موسى الحية النحاسية في البرية فنظر إليها الملدوغون وحيوا، ارتفع المسيح على الصليب. النظر إلى المصلوب شفاء. انظر اليوم إلى الصليب حين تقاومك الأفكار الشريرة، وقل: يا رب أقبلني كما قبلت اللص.\",\"p\":\"يا رب، أبطل قوة المعاند بصليبك المحيي. اقبلني كما قبلت اللص اليمين. آمين.\"},{\"t\":\"نظر إلى حية النحاس يحيا\",\"ref\":\"العدد ٢١: ٩\",\"bk\":\"العدد\",\"v\":\"فصنع موسى حية من نحاس ووضعها على الراية، فكان متى لدغت حية إنسانا ونظر إلى حية النحاس يحيا.\",\"r\":\"«فكان متى لدغت حية إنسانًا ونظر إلى حية النحاس يحيا». النظر هو الشرط، والإيمان هو الباب. لم يطلب الله من الملدوغ عملًا بل نظرة. فالخلاص هبة تُقبل بالنظر إلى المرفوع.\",\"p\":\"يا رب، لدغتني الخطية فانظر إلي وأنا أنظر إليك مرفوعًا. اشفني بصليبك وأحيني بنظرة الإيمان. آمين.\"},{\"t\":\"مقيَّد لا ميت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إبراهيم: لم تقتله فالهوى ما زال حيًّا فيك، إنما قد قُيّد، فالأهواء ما تزال حية إلا أنها لُجمت عند القديسين. الصليب يقيد الهوى لا يلغي الجهاد. ابقَ يقظًا اليوم أمام هوى معروف.\",\"p\":\"يا رب، قيّد أهوائي بصليبك. علّمني الانتباه الدائم، ولا تدعني أنام على نصر قديم. آمين.\",\"fq\":71}]},\"9-27\":{\"th\":\"عيد الصليب\",\"m\":[{\"t\":\"مزق صك خطايانا\",\"ref\":\"قطعة السادسة (١)\",\"v\":\"يا من في اليوم السادس وفي الساعة السادسة سمرت على الصليب من أجل الخطية التي تجرأ عليها أبونا آدم في الفردوس، مزق صك خطايانا أيها المسيح إلهنا وخلصنا.\",\"r\":\"في عيد الصليب نذكر الصليب الذي مزق صك خطايانا ورفع الدين الذي علينا. نفتخر به لا بأنفسنا. ارسم علامة الصليب اليوم بانتباه كامل، وقلها بصلاة: أنا مصلوب مع المسيح.\",\"p\":\"يا رب، لك المجد يا من سمرت على الصليب لأجلي. مزق صك خطاياي وخلصني. آمين.\"},{\"t\":\"مع المسيح صلبت\",\"ref\":\"غلاطية ٢: ٢٠\",\"bk\":\"غلاطية\",\"v\":\"مع المسيح صلبت، فأحيا لا أنا، بل المسيح يحيا في. فما أحياه الآن في الجسد، فإنما أحياه في الإيمان، إيمان ابن الله، الذي أحبني وأسلم نفسه لأجلي.\",\"r\":\"«مع المسيح صلبت، فأحيا لا أنا بل المسيح يحيا فيّ». في عيد الصليب أسأل: من يعيش حياتي؟ إن كانت الأنا هي التي تقود، فالصليب لم يعمل فيّ بعد. والمسيح يريد أن يحيا فيّ بمحبته وطاعته.\",\"p\":\"يا رب، في عيد صليبك أسلمك حياتي كلها. أمت أنانيتي وعش أنت فيّ، وأعطني أن أحيا بإيمان ابن الله الذي أحبني. آمين.\"},{\"t\":\"ثلاثة أيام في القبر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى: إذا لم يضع الإنسان نفسه عقليًّا في القبر ثلاثة أيام لا يمكنه أن يبلغ إلى قامة هذا الكلام. من يشارك المسيح في صليبه يتعلم أن يموت عن ذاته. تذكر اليوم أنك مدفون مع المسيح بالمعمودية.\",\"p\":\"يا رب، أمتني عن ذاتي معك. علّمني حياة القيامة بعد موت الأنا. آمين.\",\"fq\":259}]},\"9-28\":{\"th\":\"موت الإنسان العتيق\",\"m\":[{\"t\":\"قتلت الخطية بالخشبة\",\"ref\":\"قطعة السادسة (٢)\",\"v\":\"يا يسوع المسيح إلهنا الذي سمرت على الصليب في الساعة السادسة، وقتلت الخطية بالخشبة، وأحييت الميت بموتك. اقتل أوجاعنا بآلامك الشافية المحيية.\",\"r\":\"المسيح قتل الخطية بالخشبة وأحيا الميت بموته، وهذا هو أساس موت إنساننا العتيق. التحرر من العتيق ليس بقوتنا بل بآلامه. اطلب اليوم من المسيح أن يقتل فيك عادة قديمة.\",\"p\":\"يا رب، اقتل أوجاعي بآلامك الشافية. أمِت إنساني العتيق وأحيِ فيّ إنسانًا جديدًا. آمين.\"},{\"t\":\"محا الصك الذي علينا\",\"ref\":\"كولوسي ٢: ١٤\",\"bk\":\"كولوسي\",\"v\":\"إذ محا الصك الذي علينا في الفرائض، الذي كان ضدا لنا، وقد رفعه من الوسط مسمرا إياه بالصليب،\",\"r\":\"«إذ محا الصك الذي علينا، وقد رفعه من الوسط مسمرًا إياه بالصليب». ديوني ممحوة بدم المسيح. والعدو يحاول أن يذكرني بصك قديم لكنه لم يعد له مفعول. أمام الاتهام أقول: ديني سدد على الصليب.\",\"p\":\"يا رب، محوت صك خطاياي بصليبك. أشكرك على النصر، ولا تدع العدو يتهمني، بل ثبتني في غفرانك. آمين.\"},{\"t\":\"الحقل والديدان\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن من يسلك مع إنسان بهوى من أهواء الإنسان القديم ويتمسك به يشبه صاحب حقل تلتهمه الديدان والحشرات. الهوى القديم يفسد الثمر. اقتلع اليوم هوى يلتهم علاقة أو عملًا.\",\"p\":\"يا رب، حرّر علاقاتي من أهوائي القديمة. اقتلع الديدان من حقل قلبي. آمين.\",\"fq\":445}]},\"9-29\":{\"th\":\"الحياة للذي مات لأجلنا\",\"m\":[{\"t\":\"اذكرنا يا رب\",\"ref\":\"قطعة التاسعة (٥)\",\"v\":\"يا من قبل إليه اعتراف اللص على الصليب، اقبلنا إليك أيها الصالح، نحن المستوجبين حكم الموت من أجل خطايانا. نقر بخطايانا معه معترفين بألوهيتك، ونصرخ معه جميعًا: اذكرنا يا رب متى جئت في ملكوتك.\",\"r\":\"اللص المصلوب عاش لحظة واحدة للحياة الجديدة، فقبله المسيح، وهكذا نحيا لمن مات لأجلنا. الحياة التي أُعطيناها ليست لنا. اطلب اليوم كلمة تقولها بصدق: اذكرني يا رب.\",\"p\":\"يا رب، تذكّرني حين تجيء في ملكوتك. اقبل اعترافي واجعلني أحيا لك الذي مات لأجلي. آمين.\"},{\"t\":\"لا لأنفسهم\",\"ref\":\"كورنثوس الثانية ٥: ١٥\",\"bk\":\"كورنثوس الثانية\",\"v\":\"وهو مات لأجل الجميع كي يعيش الأحياء فيما بعد لا لأنفسهم، بل للذي مات لأجلهم وقام.\",\"r\":\"«كي يعيش الأحياء فيما بعد لا لأنفسهم، بل للذي مات لأجلهم وقام». غاية الفداء أن أنتقل من الحياة لنفسي إلى الحياة له. وهذا يجعل لحياتي معنى. فلا أسأل «ماذا أريد؟» فقط، بل «ماذا يريد الذي مات لأجلي؟».\",\"p\":\"يا رب، مت لأجلي فاجعلني أحيا لك. خذ وقتي ومواهبي وقراراتي، واجعل محبتك تحصرني فأخدمك بفرح. آمين.\"},{\"t\":\"مات عن العالم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كسيانوس: لقد مت عن العالم قبله، فالميت لا يرث الحي. من مات عن العالم لا يحكمه العالم. اترك اليوم مجالًا واحدًا لا تدافع فيه عن حقك.\",\"p\":\"يا رب، أمتني عن العالم وأحيني لك. حرّرني من شهوة الدفاع عن نفسي. آمين.\",\"fq\":216}]},\"9-30\":{\"th\":\"دم يسوع والكهنوت\",\"m\":[{\"t\":\"هيكلك كالسماء\",\"ref\":\"قطعة مشتركة — نصف الليل — الخدمة الثانية\",\"v\":\"إذا ما وقفنا في هيكلك المقدس نحسب كالقيام في السماء. يا والدة الإله. أنت هي باب السماء، افتحي لنا باب الرحمة.\",\"r\":\"إذا وقفنا في هيكل الله حسبنا كالقيام في السماء. هناك الدم الذي نتقدس به، والكهنوت الذي يقدمه. اذكر اليوم اسم كاهنك وصلِّ لأجله وتأمل في سر الدم المقدس.\",\"p\":\"يا رب، أشكرك على هيكلك وكهنوتك ودمك. افتح لنا باب الرحمة، وقدّس خدامك. آمين.\"},{\"t\":\"ثقة بالدخول إلى الأقداس\",\"ref\":\"العبرانيين ١٠: ١٩\",\"bk\":\"العبرانيين\",\"v\":\"فإذ لنا أيها الإخوة ثقة بالدخول إلى «الأقداس» بدم يسوع،\",\"r\":\"«فإذ لنا أيها الإخوة ثقة بالدخول إلى الأقداس بدم يسوع». الستار انشق وصار لي وصول إلى الله. وأنا لا أقترب بسبب استحقاقي بل بدم المسيح. وهذا يعطيني جرأة الصلاة دون خوف أو تردد.\",\"p\":\"يا رب، فتحت لي بدمك باب الأقداس. أقترب إليك بثقة، فاقبلني وطهرني وأعطني حضورك. آمين. وثبتني في قربك كل أيام حياتي.\"},{\"t\":\"من إنسان إلى ملاك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس عن زخريا الصبي إنه لما تقدم الأحد الماضي لتناول الجسد والدم الطاهرين كان إنسانًا، أما الآن فقد أضحى ملاكًا. التناول يغير حياتنا. تقدم للتناول باستعداد أو صلِّ صلاة استعداد.\",\"p\":\"يا رب، حوّلني بجسدك ودمك. اجعلني كل يوم أقرب إلى حياة الملائكة. آمين.\",\"fq\":221}]},\"10-1\":{\"th\":\"الكنيسة جسد المسيح\",\"m\":[{\"t\":\"الله في وسطها فلن تتزعزع\",\"ref\":\"المزمور ٤٥ (٤٦) — الثالثة\",\"v\":\"مجارى الأنهار تفرح مدينة الله. لقد قدس العلي مسكنه. والله في وسطها فلن تتزعزع.\",\"r\":\"مدينة الله تفرح بمجاري الأنهار لأن العلي قدس مسكنه وهو في وسطها. الكنيسة جسد المسيح، والله في وسط الجسد لا يتزعزع. اذكر اليوم ثلاثة أعضاء من كنيستك، وصلِّ لكل منهم بالاسم.\",\"p\":\"يا رب، أنت في وسط كنيستك فلا تتزعزع. اجعلني عضوًا حيًّا في جسدك، يفرح بالشركة معك ومع إخوته. آمين.\"},{\"t\":\"رأس فوق كل شيء للكنيسة\",\"ref\":\"أفسس ١: ٢٢\",\"bk\":\"أفسس\",\"v\":\"وأخضع كل شيء تحت قدميه، وإياه جعل رأسا فوق كل شيء للكنيسة،\",\"r\":\"«وإياه جعل رأسًا فوق كل شيء للكنيسة التي هي جسده». المسيح ليس بعيدًا عن الكنيسة بل هو رأسها. وأنا عضو في هذا الجسد. فلا أخاف على الكنيسة لأن رأسها حي، ولا أتعالى فيها لأن الرأس غيري.\",\"p\":\"يا رب، أنت رأس الكنيسة وحياتها. احفظ جسدك من الانقسام، واجعلني عضوًا حيًا نافعًا ومطيعًا لرأسه. آمين.\"},{\"t\":\"كسلوك الجميع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موتيوس: حيث تقيم ليكن سلوكك كسلوك الجميع، فالتواضع أن تكون مساويًا للأتقياء الذين تثق بهم. العضو في الجسد لا يتميز بغرابة بل بأمانة. اخدم اليوم في مكانك بروح الجماعة دون أن تبحث عن الظهور.\",\"p\":\"يا رب، علّمني أن أكون جزءًا من الجسد لا فوقه. وأعطني تواضعًا يحب المساواة مع إخوتي. آمين.\",\"fq\":281}]},\"10-2\":{\"th\":\"أعضاء بعضنا لبعض\",\"m\":[{\"t\":\"أدخل بيتك\",\"ref\":\"المزمور الخامس — باكر\",\"v\":\"أما أنا فبكثرة رحمتك أدخل بيتك. وأسجد قدام هيكل قدسك بمخافتك. اهدني يا رب ببرك.\",\"r\":\"يدخل المرنم بيت الله بكثرة الرحمة لا باستحقاقه، ويسجد بمخافته ويطلب الهداية ببر الله. نحن أعضاء بعضنا لبعض نحتاج هذا التواضع معًا. قبل أن تدخل الكنيسة أو الاجتماع اليوم، اطلب غفران الله ومحبة إخوتك.\",\"p\":\"يا رب، بكثرة رحمتك أدخل بيتك وأسجد أمام قدسك. اهدني ببرك واجعلني عضوًا نافعًا لإخوتي. آمين.\"},{\"t\":\"إن تألم عضو\",\"ref\":\"كورنثوس الأولى ١٢: ٢٦\",\"bk\":\"كورنثوس الأولى\",\"v\":\"فإن كان عضو واحد يتألم، فجميع الأعضاء تتألم معه. وإن كان عضو واحد يكرم، فجميع الأعضاء تفرح معه.\",\"r\":\"«إن كان عضو واحد يتألم فجميع الأعضاء تتألم معه، وإن كان عضو واحد يكرم فجميع الأعضاء تفرح معه». هل أشارك الكنيسة في ألمها وفرحها؟ كثيرًا ما أتألم لنفسي وأفرح بنفسي، أما الجسد فيعلمني مشاركة الآخر.\",\"p\":\"يا رب، علمني أن أبكي مع الباكين وأفرح مع الفرحين. انزع الحسد من قلبي، واجعلني أشعر بإخوتي كما بجسدي. آمين.\"},{\"t\":\"الفضيلة مع الناس أولًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب لوكيوس لمن أراد أن يهرب من الناس: إذا لم تحقق الفضيلة مع الناس أولًا، لا تستطيع بمفردك وأنت في البرية أن تحققها. نحن أعضاء بعضنا لبعض، ونتدرب على المحبة بينهم. اختر اليوم موقفًا مع شخص تتعب منه، وتدرّب فيه على الصبر.\",\"p\":\"يا رب، علّمني الفضيلة بين الناس. اجعلني أحتمل أعضاء جسدك كما احتملتني أنت. آمين.\",\"fq\":232}]},\"10-3\":{\"th\":\"بيت الله\",\"m\":[{\"t\":\"لبيتك ينبغي التقديس\",\"ref\":\"المزمور ٩٢ (٩٣) — السادسة\",\"v\":\"شهاداته صادقة جدا، لبيتك ينبغي التقديس يا رب طول الأيام.\",\"r\":\"شهادات الرب صادقة جدًا، ولبيته ينبغي التقديس طول الأيام. الكنيسة بيت الله، ونحن أيضًا هيكل لله. اسكت اليوم دقيقة عند دخولك أي مكان صلاة، وتذكر أن قلبك أيضًا بيته.\",\"p\":\"يا رب، لبيتك ينبغي التقديس. قدّس كنيستك وقدّس قلبي ليكون بيتًا لك. آمين.\"},{\"t\":\"أهل بيت الله\",\"ref\":\"أفسس ٢: ١٩\",\"bk\":\"أفسس\",\"v\":\"فلستم إذا بعد غرباء ونزلا، بل رعية مع القديسين وأهل بيت الله،\",\"r\":\"«فلستم إذًا بعد غرباء ونزلاء، بل رعية مع القديسين وأهل بيت الله». كنيستي ليست مكانًا أزوره بل بيتي. فيها أنتمي وأنال المحبة. ولي مكان على مائدة العائلة الكبيرة. وهذا يمنحني إحساسًا بالأمان.\",\"p\":\"يا رب، أشكرك لأنك جعلتني من أهل بيتك. افتح قلبي للغرباء، وأعطني أن أستقبل كل أحد بمحبة العائلة. آمين.\"},{\"t\":\"صُن نفسك في القلاية وخارجها\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب بيمن أخًا: صُن نفسك في القلاية وخارجها. القداسة لا تنحصر في موضع الصلاة، بل تحملها معك. اجعل اليوم تصرفك خارج الكنيسة مطابقًا لما تقوله داخلها.\",\"p\":\"يا رب، احفظني في بيتك وخارجه. اجعل حياتي كلها قدسًا لك. آمين.\",\"fq\":414}]},\"10-4\":{\"th\":\"شعب الله والرعاية\",\"m\":[{\"t\":\"ادخلوا أبوابه بالاعتراف\",\"ref\":\"المزمور ٩٩ (١٠٠) — التاسعة\",\"v\":\"ادخلوا أبوابه بالاعتراف، ودياره بالتسابيح.\",\"r\":\"يدعونا المرنم أن ندخل أبواب الرب بالاعتراف وديارَه بالتسابيح. شعب الله له رعاة يسهرون على نفوسه، ونحن غنم رعيته. صلِّ اليوم لأجل راعيك وأطع نصيحة رعايته بفرح.\",\"p\":\"يا رب، نحن شعبك وغنم رعيتك. احفظ رعاتنا وعلّمنا أن ندخل أبوابك بالاعتراف والتسبيح. آمين.\"},{\"t\":\"جنس مختار وكهنوت ملوكي\",\"ref\":\"بطرس الأولى ٢: ٩\",\"bk\":\"بطرس الأولى\",\"v\":\"وأما أنتم فجنس مختار، وكهنوت ملوكي، أمة مقدسة، شعب اقتناء، لكي تخبروا بفضائل الذي دعاكم من الظلمة إلى نوره العجيب.\",\"r\":\"«أنتم جنس مختار وكهنوت ملوكي وأمة مقدسة وشعب اقتناء». هذه هويتي في المسيح. ومن عرف هويته لا يعيش بحسب نظرة الناس. والغاية: «لكي تخبروا بفضائل الذي دعاكم». دعوتي أن أحكي عن الله بحياتي.\",\"p\":\"يا رب، دعوتني من الظلمة إلى نورك. أعطني أن أحيا كشعب مقتنى لك، وأخبر بفضائلك بحياتي وكلامي. آمين.\"},{\"t\":\"الدجاجة والبيضة\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي لمن يعيش في شركة ألا يغير مكانه، فكما تهمل الدجاجة البيضة إن غادرتها، هكذا يفتر الإنسان وتنطفئ جذوة الإيمان فيه إن تنقل. ثبات الراعي والرعية في موضعها بركة. التزم اليوم بثبات في مكان خدمتك.\",\"p\":\"يا رب، ثبّتني في موضعي ورعايتي. لا تدع جذوة الإيمان تنطفئ بتنقلي وتقلبي. آمين.\",\"fq\":535}]},\"10-5\":{\"th\":\"الاجتماع وقطيع واحد\",\"m\":[{\"t\":\"رتلوا للرب\",\"ref\":\"المزمور ٩٧ (٩٨) — التاسعة\",\"v\":\"هللوا للرب يا كل الأرض، سبحوا وهللوا ورتلوا. رتلوا للرب بالقيثارة، بالقيثارة وصوت المزمار.\",\"r\":\"يدعو المرنم كل الأرض أن تهلل وتسبح وترتل للرب بالقيثارة. الاجتماع ليس واجبًا بل فرح قطيع واحد حول راعٍ واحد. اجعل اليوم موعدك للكنيسة ثابتًا، وإن تعذر فصلِّ مع أحد من أهلك.\",\"p\":\"يا رب، اجعلنا قطيعًا واحدًا بتسبيح واحد. هلل أمامك مع كل من يحبك. آمين.\"},{\"t\":\"غير تاركين اجتماعنا\",\"ref\":\"العبرانيين ١٠: ٢٥\",\"bk\":\"العبرانيين\",\"v\":\"غير تاركين اجتماعنا كما لقوم عادة، بل واعظين بعضنا بعضا، وبالأكثر على قدر ما ترون اليوم يقرب،\",\"r\":\"«غير تاركين اجتماعنا كما لقوم عادة». ترك الاجتماع يبدأ بتأجيل بسيط ثم يصير عادة. والمؤمن وحده معرض للفتور. أما في الجماعة فنتشجع معًا. فلأواظب على القداس والاجتماعات ولو كنت متعبًا.\",\"p\":\"يا رب، ثبتني في اجتماعات كنيستك. لا تدعني أترك الشركة تهاونًا، وأعطني رغبة في بيتك وفرحًا بإخوتي. آمين.\"},{\"t\":\"الطاعة قبل النسك\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي: عندما نكون في دير ذي حياة مشتركة يجب أن نؤثر الطاعة على النسك، لأن النسك قد يعلّم التشامخ أما الطاعة فتعلّم التواضع. الاجتماع يحتاج طاعة تحفظ الوحدة. أطع اليوم قرار الجماعة في أمر لا يحتمل مخالفة.\",\"p\":\"يا رب، علّمني الطاعة التي تحفظ وحدة قطيعك. احفظني من كبرياء النسك. آمين.\",\"fq\":542}]},\"10-6\":{\"th\":\"وحدة الروح\",\"m\":[{\"t\":\"لتعترف لك الشعوب\",\"ref\":\"المزمور السادس والستون — باكر\",\"v\":\"فلتعترف لك الشعوب يا الله فلتعترف لك الشعوب كلها. لتفرح الأمم وتبتهج، لأنك تحكم في الشعوب بالاستقامة، وتهدى الأمم في الأرض. فلتعترف لك الشعوب يا الله فلتعترف لك الشعوب جميعا.\",\"r\":\"يطلب المرنم أن تعترف الشعوب لله وتفرح الأمم، لأنه يحكم بالاستقامة ويهدي الأرض. وحدة الروح هي أن نعترف معًا بالرب الواحد. صلِّ اليوم من أجل وحدة الكنيسة في العالم.\",\"p\":\"يا رب، لتعترف لك الشعوب كلها. ثبّت وحدة الروح فيما بيننا برباط السلام. آمين.\"},{\"t\":\"المجد الذي يوحّدنا\",\"ref\":\"يوحنا ١٧: ٢٢\",\"bk\":\"يوحنا\",\"v\":\"وأنا قد أعطيتهم المجد الذي أعطيتني، ليكونوا واحدا كما أننا نحن واحد.\",\"r\":\"«وأنا قد أعطيتهم المجد الذي أعطيتني، ليكونوا واحدًا كما أننا نحن واحد». وحدتنا ليست تفاهمًا بشريًا بل مشاركة في حياة الثالوث. وأنا أحتاج أن أطلب هذه الوحدة بالصلاة، لا بالتفاوض فقط.\",\"p\":\"يا رب، أعطنا المجد الذي أعطيتنا لنكون واحدًا. انزع الانقسام من كنيستك، وقرّبنا بعضنا إلى بعض بروحك. آمين.\"},{\"t\":\"عديم الهم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن لمن أراد دير شركة: إن لم تكن عديم الهم في كل لقاء وفي كل شيء يستحيل عليك أن تعمل فيه، لأنه ليس لك سلطان على دورق الماء. وحدة الروح تحتاج أن نترك التمسك بالحقوق. تنازل اليوم عن حق صغير بفرح.\",\"p\":\"يا رب، خلّصني من التمسك بما هو لي. علّمني أن أعيش في الجماعة بلا همّ لنفسي. آمين.\",\"fq\":426}]},\"10-7\":{\"th\":\"قول واحد وخبز واحد\",\"m\":[{\"t\":\"قدام كل شعبه\",\"ref\":\"المزمور ١١٥ — التاسعة\",\"v\":\"أوفي للرب نذوري في ديار بيت الرب، قدام كل شعبه. في وسط أورشليم.\",\"r\":\"يوفي المرنم نذوره للرب في ديار بيته أمام كل شعبه في وسط أورشليم. فنحن قول واحد وخبز واحد، نقف معًا ونأخذ معًا. فكر اليوم في معنى أن تقف مع الجماعة وتشاركها المائدة.\",\"p\":\"يا رب، أوفي لك نذوري أمام كل شعبك. اجعلنا قولًا واحدًا وخبزًا واحدًا، واحفظنا في وحدة جسدك. آمين.\"},{\"t\":\"خبز واحد، جسد واحد\",\"ref\":\"كورنثوس الأولى ١٠: ١٧\",\"bk\":\"كورنثوس الأولى\",\"v\":\"فإننا نحن الكثيرين خبز واحد، جسد واحد، لأننا جميعنا نشترك في الخبز الواحد.\",\"r\":\"«فإننا نحن الكثيرين خبز واحد، جسد واحد، لأننا جميعنا نشترك في الخبز الواحد». التناول ليس لقاءً فرديًا فقط، بل هو بناء للجسد الواحد. فعندما أتناول أتحد بالمسيح، وأتحد بكل من يتناول معي.\",\"p\":\"يا رب، اجعلني أشترك في الخبز الواحد بقلب نقي. وحّدنا في جسدك، واغفر لنا ما بيننا، واجمعنا فيك. آمين.\"},{\"t\":\"الأكل مع الأخ\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ماتوى: إذا كنت لا تتضايق وتأكل مع الأخ حسنًا تفعل. المائدة المشتركة علامة وحدة تتقدم على ترتيبنا الخاص. شارك اليوم وجبة مع أحد من أسرتك أو كنيستك دون مشاغل.\",\"p\":\"يا رب، اجعل مائدتنا مكان محبة. علّمني أن أترك رغبتي الخاصة لأجل الشركة. آمين.\",\"fq\":272}]},\"10-8\":{\"th\":\"خبز الحياة\",\"m\":[{\"t\":\"فتشبع نفسي\",\"ref\":\"المزمور ٦٣ — باكر\",\"v\":\"لذلك أباركك في حياتي؛ وباسمك أرفع يدي. فتشبع نفسي كما من شحم ودسم.\",\"r\":\"يبارك المرنم الرب في حياته ويرفع يديه باسمه، فتشبع نفسه كما من شحم ودسم. المسيح هو الخبز الذي يعطي الحياة، ونتقبله بالإيمان والتسبيح. اقرأ اليوم فصلًا من يوحنا ٦، وتأمل أن المسيح هو خبزك.\",\"p\":\"يا رب يسوع، أنت خبز الحياة. أشبع نفسي منك، وأقبل رفع يدي بالتسبيح. آمين.\"},{\"t\":\"أنا هو خبز الحياة\",\"ref\":\"يوحنا ٦: ٣٥\",\"bk\":\"يوحنا\",\"v\":\"فقال لهم يسوع: «أنا هو خبز الحياة. من يقبل إلي فلا يجوع، ومن يؤمن بي فلا يعطش أبدا.\",\"r\":\"«أنا هو خبز الحياة. من يقبل إلي فلا يجوع، ومن يؤمن بي فلا يعطش أبدًا». أبحث عن الشبع في أشياء كثيرة، لكن جوعي الأعمق لا يشبعه إلا المسيح. وعندما أقبل إليه أجد ما كنت أبحث عنه.\",\"p\":\"يا رب، أنت خبز الحياة، أشبع جوع نفسي بك. لا تدعني أبحث عن الشبع في غيرك، وأعطني أن أقبل إليك كل يوم. آمين.\"},{\"t\":\"مريم تحتاج إلى مرثا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يجيب الأب سلوان أخًا قرأ طوال النهار ولم يأكل: لأنك إنسان روحي ولا تحتاج إلى هذا الطعام، أما نحن فبشر ونحتاج إليه لهذا نعمل. ثم يضيف أن مريم تحتاج إلى مرثا، لأن مريم تُمتدح بسبب مرثا. الخبز الروحي والجسدي يخدم أحدهما الآخر. اشكر اليوم من يخدمك خبزك اليومي.\",\"p\":\"يا رب، أطعمني من كلمتك وبارك خبزي اليومي. علّمني أن أقدّر من يخدمني فأتفرغ أنا لحضورك. آمين.\",\"fq\":511}]},\"10-9\":{\"th\":\"المعمودية والولادة الجديدة\",\"m\":[{\"t\":\"الذي يحفظ الأطفال هو الرب\",\"ref\":\"المزمور ١١٤ — التاسعة\",\"v\":\"الذي يحفظ الأطفال هو الرب. اتضعت فخلصني.\",\"r\":\"الرب هو الذي يحفظ الأطفال، والمرنم يقول: اتضعت فخلصني. المعمودية ولادة جديدة من الماء والروح، ولا يدخل الملكوت إلا من صار كطفل. تذكر اليوم يوم معموديتك أو اسأل أهلك عن تاريخه.\",\"p\":\"يا رب، يا حافظ الأطفال، اتضعت فخلصتني. أشكرك على ميلادي الجديد بالمعمودية، وأعطني أن أحيا كابنك. آمين.\"},{\"t\":\"يولد من الماء والروح\",\"ref\":\"يوحنا ٣: ٥\",\"bk\":\"يوحنا\",\"v\":\"أجاب يسوع: «الحق الحق أقول لك: إن كان أحد لا يولد من الماء والروح لا يقدر أن يدخل ملكوت الله.\",\"r\":\"«إن كان أحد لا يولد من الماء والروح لا يقدر أن يدخل ملكوت الله». المعمودية ولادة جديدة وليست طقسًا فقط. وأنا ولدت مرة من أبويّ ومرة من الله. وهذا يمنحني هوية جديدة كابن لله.\",\"p\":\"يا رب، أشكرك على ولادتي الثانية من الماء والروح. ثبتني في بنوتي لك، وأعطني أن أحيا كابن مولود من فوق. آمين.\"},{\"t\":\"كل شيء يخضع له\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بولس وهو يمسك الأفاعي: الإنسان إذا اقتنى الطهارة فإن كل شيء يخضع له ويطيعه، كحال آدم في الفردوس قبل أن يعصى. المعمودية أعادت لنا ذلك الأصل. اسأل الله اليوم أن يعيد فيك براءة المعمودية.\",\"p\":\"يا رب، أعد إليّ نقاء ميلادي الجديد. طهّر قلبي ليخضع لك كل ما فيّ. آمين.\",\"fq\":475}]},\"10-10\":{\"th\":\"المسحة والروح القدس\",\"m\":[{\"t\":\"مسحك الله بزيت البهجة\",\"ref\":\"المزمور ٤٤ (٤٥) — الثالثة\",\"v\":\"لأنك أحببت البر وأبغضت الإثم. من أجل هذا مسحك الله إلهك بزيت البهجة أفضل من رفقائك.\",\"r\":\"أحب الملك البر وأبغض الإثم، فمسحه الله بزيت البهجة أفضل من رفقائه. المسحة تعلن أن الروح القدس يحل علينا ويقدسنا. اطلب اليوم من الله أن يمسح خدمتك وصلاتك بروحه.\",\"p\":\"يا رب، أحببت البر فامسحني بزيت البهجة. اسكب روحك القدوس عليّ لأصلي وأخدم كما يليق. آمين.\"},{\"t\":\"الذي مسحنا هو الله\",\"ref\":\"كورنثوس الثانية ١: ٢١\",\"bk\":\"كورنثوس الثانية\",\"v\":\"ولكن الذي يثبتنا معكم في المسيح، وقد مسحنا، هو الله\",\"r\":\"«الذي يثبتنا معكم في المسيح، وقد مسحنا، هو الله». الله هو الذي يثبتني ويمسحني. فثباتي ليس مجهودي وحدي. وأنا أحتاج أن أعيش كمن عليه مسحة الله: بقداسة وطمأنينة وخدمة.\",\"p\":\"يا رب، أنت الذي ثبتني ومسحتني، فاحفظ ختمك عليّ. أعطني أن أحيا كمن عليه مسحتك، وأعمل أعمالك بقوة روحك. آمين.\"},{\"t\":\"نارًا ملتهبة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوسف للأب لوط: لا تستطيع أن تصير راهبًا إذا لم تصبح نارًا ملتهبة بالكلية. الروح القدس يعلّمنا أن نحترق بالمحبة لا بالحماس العابر. اطلب اليوم حرارة الروح لصلاة واحدة.\",\"p\":\"يا رب، أشعل فيّ نار روحك. اجعلني ملتهبًا بحبك بالكلية. آمين.\",\"fq\":184}]},\"10-11\":{\"th\":\"الاستعداد للتجربة\",\"m\":[{\"t\":\"بصوتي إلى الرب صرخت\",\"ref\":\"المزمور الثالث — باكر\",\"v\":\"بصوتي إلى الرب صرخت. فاستجاب لي من جبل قدسه.\",\"r\":\"يقول المرنم: بصوتي إلى الرب صرخت فاستجاب لي من جبل قدسه. من يستعد للتجربة يصرخ قبل أن تشتد. اكتب اليوم ما يخيفك من تجارب قادمة، وارفعها في صلاة قصيرة.\",\"p\":\"يا رب، بصوتي إليك صرخت فاستجب لي. استعدني لكل تجربة تأتي، وكن معي فيها. آمين.\"},{\"t\":\"أعدد نفسك للتجربة\",\"ref\":\"يشوع بن سيراخ ٢: ١\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"يا بني ان اقبلت لخدمة الرب الاله فاثبت على البر والتقوى واعدد نفسك للتجربة\",\"r\":\"«يا بني، إن أقبلت لخدمة الرب الإله فاثبت على البر والتقوى وأعدد نفسك للتجربة». الحكيم لا يعد بطريق سهل، بل بإعداد للنفس. وأنا حين أبدأ خدمة أو توبة أتوقع المقاومة ولا أنزعج منها، فالتجربة جزء من الطريق.\",\"p\":\"يا رب، أنا أريد خدمتك فأعدّني للتجربة. ثبتني على البر والتقوى، ولا تدعني أتفاجأ بالضيق أو أتراجع عنه. آمين.\"},{\"t\":\"أبعد التجارب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إفاغريوس كلمة قصيرة: أبعِدْ التجارب فلا يخلص أحد. فالتجارب تفتحنا على حاجتنا إلى الله، فنتعلم الصلاة والصبر. قل لنفسك اليوم: التجربة طريق لا عائق.\",\"p\":\"يا رب، لا تدخلني في تجربة فوق طاقتي. علّمني أن أنتصر بها وأقترب منك أكثر. آمين.\",\"fq\":112}]},\"10-12\":{\"th\":\"مخافة الرب\",\"m\":[{\"t\":\"يسر الرب بخائفيه\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"لا يوثر قوة الفرس ولا يسر بساقي الرجل، بل يسر الرب بخائفيه وبالراجين رحمته هلليلويا.\",\"r\":\"لا يؤثر الرب قوة الفرس ولا ساقي الرجل، بل يسر بخائفيه والراجين رحمته. مخافة الرب بداية الحكمة وهي تواضع أمام قداسته. ابدأ اليوم بصلاة قصيرة تعبر فيها عن احترامك لله.\",\"p\":\"يا رب، يسرّك الخائفون والراجون رحمتك. ضع في قلبي مخافتك فلا أخاف شيئًا آخر. آمين.\"},{\"t\":\"مخافة الرب مجد\",\"ref\":\"يشوع بن سيراخ ١: ١١\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"مخافة الرب مجد وفخر وسرور واكليل ابتهاج\",\"r\":\"«مخافة الرب مجد وفخر وسرور وإكليل ابتهاج». لا تعني المخافة الارتعاب بل الإجلال المحب. إنها أن أخاف أن أجرح قلب أبي. وهي عندي مصدر فرح، لأن من يهاب الله لا يهاب أحدًا.\",\"p\":\"يا رب، علمني مخافتك المحبة. اجعلها فخرًا وسرورًا لي، وامنعني من كل ما يجرح قلبك. آمين.\"},{\"t\":\"خوف الله والتواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب أفربيوس: فليلازمك خوف الله والتواضع والحرمان من الأطعمة وأيضًا النوح. المخافة صحبة دائمة لا زائر عابر. اختر اليوم عملًا صغيرًا تؤديه خوفًا من الله لا من الناس.\",\"p\":\"يا رب، لازم قلبي بمخافتك وتواضعك. علّمني أن أخافك محبة. آمين.\",\"fq\":106}]},\"10-13\":{\"th\":\"انتظار رحمته\",\"m\":[{\"t\":\"وإياك انتظرت النهار كله\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"لأنك أنت هو الله مخلصي. وإياك انتظرت النهار كله.\",\"r\":\"يقول المرنم: أنت هو الله مخلصي وإياك انتظرت النهار كله. انتظار رحمته لا يضيع، فهي أقرب مما نظن. اجلس اليوم دقائق وانتظر الله بلا طلبات، فقط لتتذكر أنه رحيم.\",\"p\":\"يا رب، أنت الله مخلصي، وإياك انتظرت النهار كله. لا تدعني أخزى، بل أنقذني برحمتك. آمين.\"},{\"t\":\"انتظروا رحمته\",\"ref\":\"يشوع بن سيراخ ٢: ٧\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"ايها المتقون للرب انتظروا رحمته ولا تحيدوا لئلا تسقطوا\",\"r\":\"«أيها المتقون للرب، انتظروا رحمته ولا تحيدوا لئلا تسقطوا». الانتظار يحتاج ثباتًا في الطريق. وأكثر ما يسقطني هو الاستعجال والانحراف عن الطريق عندما يتأخر الفرج. فلأبقَ على الدرب حتى تأتي رحمته.\",\"p\":\"يا رب، علمني أن أنتظر رحمتك بصبر. احفظني من الحيدان عن طريقك، ولا تدعني أسقط في تأخر الجواب. آمين.\"},{\"t\":\"ثلاثة أيام\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيسوى: أؤمن أن الإنسان إذا تاب من كل قلبه فإن الله يقبله في غضون ثلاثة أيام. الله لا يؤخر رحمته على التائب. إن كنت تؤجل توبة، فابدأ اليوم.\",\"p\":\"يا رب، أتوب إليك من كل قلبي. اقبلني سريعًا برحمتك، ولا تؤخر مغفرتك. آمين.\",\"fq\":494}]},\"10-14\":{\"th\":\"الاتضاع والوداعة\",\"m\":[{\"t\":\"يعاين المتواضعات\",\"ref\":\"المزمور ١٣٧ — النوم\",\"v\":\"لأن مجد الرب عظيم لأن الرب عال ويعاين المتواضعات والكائنات يعرفها من بعد.\",\"r\":\"مجد الرب عظيم، وهو عالٍ ويعاين المتواضعات ويعرف الكائنات من بعد. الاتضاع والوداعة أقرب الطرق إلى قلب الله. افعل اليوم شيئًا صغيرًا دون أن يعرف أحد، واترك الله وحده يعاين.\",\"p\":\"يا رب العلي الذي يعاين المتواضعات، علّمني الاتضاع. اجعل قلبي وديعًا كقلبك. آمين.\"},{\"t\":\"اقض أعمالك بالوداعة\",\"ref\":\"يشوع بن سيراخ ٣: ١٩\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"يا بني اقض اعمالك بالوداعة فيحبك الانسان الصالح\",\"r\":\"«يا بني، اقضِ أعمالك بالوداعة فيحبك الإنسان الصالح». أنجز عملي بسلام لا بصخب. فكثيرًا ما أخسر الحب لأنني أصر على أن أنجز كل شيء بسرعة وقوة. والوداعة لا تعطل العمل بل تجعله مقبولًا.\",\"p\":\"يا رب، علمني أن أنجز أعمالي بوداعة. انزع مني الصخب والقسوة، وامنحني روحًا هادئة تجذب الناس إليك. آمين.\"},{\"t\":\"ولم أبلغ بعد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كاريون عن ابنه زخريا: بذلت جهودًا كثيرة تفوق ما بذله، ولم أبلغ بعد إلى قامته في التواضع والصمت. الاتضاع أن نعرف فضل غيرنا. اعترف اليوم بفضيلة عند شخص تتعلم منه.\",\"p\":\"يا رب، علّمني أن أتعلم من الصغار. أعطني تواضعًا يعترف بفضل غيري. آمين.\",\"fq\":220}]},\"10-15\":{\"th\":\"الرحمة بالفقير\",\"m\":[{\"t\":\"هذا المسكين صرخ\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"هذا المسكين صرخ فاستمعه الرب. ومن جميع ضيقاته خلصه.\",\"r\":\"هذا المسكين صرخ فاستمعه الرب ومن جميع ضيقاته خلصه، وهكذا يريدنا أن نرحم الفقير. الرحمة بالفقير تقليد لحنان الله نفسه. أعط اليوم من مالك أو وقتك لمحتاج، واذكر أنه ينوب عن المسيح.\",\"p\":\"يا رب، يا من تسمع صراخ المسكين، أعطني قلبًا رحيمًا. علّمني أن أعطي بفرح وسخاء. آمين.\"},{\"t\":\"لا تحرم المسكين\",\"ref\":\"يشوع بن سيراخ ٤: ١\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"يا بني لا تحرم المسكين ما يعيش به ولا تماطل عيني المعوز\",\"r\":\"«يا بني، لا تحرم المسكين ما يعيش به، ولا تماطل عيني المعوز». التأجيل في العطاء قسوة خفية. فالمحتاج لا ينتظر. وأنا حين أؤجل صدقتي أطيل ألمه. فلأعطِ ما أستطيع الآن، ولو كان قليلًا.\",\"p\":\"يا رب، افتح يدي لعطاء سريع وقلبي لرحمة حقيقية. لا تدعني أماطل عيني المحتاج، واجعلني قناة لبركتك. آمين.\"},{\"t\":\"أتصدق بإثنتين\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب لوكيوس إنه يربح من عمله وصلاته ست عشرة قطعة، يتصدق بإثنتين منها ويعيش بالباقي، والذي يتصدق عليه يصلي من أجله. العطاء يربط الغني بالفقير في صلاة واحدة. خصص اليوم نسبة صغيرة من دخلك للعطاء.\",\"p\":\"يا رب، علّمني أن أجعل العطاء جزءًا ثابتًا من حياتي. وبارك من أعطيهم ليصلوا من أجلي. آمين.\",\"fq\":227}]},\"10-16\":{\"th\":\"الصديق الأمين\",\"m\":[{\"t\":\"أنت باركت الصديق\",\"ref\":\"المزمور الخامس — باكر\",\"v\":\"لأنك أنت باركت الصديق يا رب. كما بترس المسرة كللتنا.\",\"r\":\"يقول المرنم: أنت باركت الصديق يا رب، كما بترس المسرة كللتنا. الصديق الأمين عطية الله وستر وكنز. اكتب اليوم رسالة قصيرة لصديق أمين تشكره فيها.\",\"p\":\"يا رب، بارك أصدقائي الأمناء. اجعلني صديقًا أمينًا لغيري كما أنت لي. آمين.\"},{\"t\":\"الصديق الأمين معقل حصين\",\"ref\":\"يشوع بن سيراخ ٦: ١٤\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"الصديق الامين معقل حصين ومن وجده فقد وجد كنزا\",\"r\":\"«الصديق الأمين معقل حصين، ومن وجده فقد وجد كنزًا». الصديق الأمين هبة من الله. فلأشكره على أصدقائي، ولأكون أنا أيضًا صديقًا أمينًا لغيري. فالأمانة أغلى من المصلحة. فلأشكر الله على أصدقائي اليوم.\",\"p\":\"يا رب، أشكرك على الأصدقاء الأمناء. باركهم واحفظهم، واجعلني صديقًا أمينًا يقود غيره إليك. آمين. وثبّت مودتنا بسلامك.\"},{\"t\":\"صديق من يقسو على نفسه\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب بيمن أخًا: كن صديقًا لمن يقسو على نفسه. الصديق الأمين يجالس من يجاهد ولا يخفف عنه جهاده. ابحث اليوم عن صديق روحي يشجعك على الجهاد.\",\"p\":\"يا رب، اجمعني بأصدقاء يقوّونني في جهادي. وكن أنت الصديق الأمين لنفسي. آمين.\",\"fq\":436}]},\"10-17\":{\"th\":\"الغفران والتوبة\",\"m\":[{\"t\":\"ارحمني اشف نفسي\",\"ref\":\"المزمور ٤٠ (٤١) — الثالثة\",\"v\":\"أنا قلت يا رب ارحمني، اشف نفسي لأني قد أخطأت إليك.\",\"r\":\"يقول المرنم: أنا قلت يا رب ارحمني، اشف نفسي لأني قد أخطأت إليك. الغفران يبدأ بالاعتراف الصريح بالخطأ. اعترف اليوم بخطأ لشخص وأنت تطلب المسامحة.\",\"p\":\"يا رب، ارحمني واشف نفسي لأني أخطأت إليك. أعطني قلبًا يغفر كما غفرت لي. آمين.\"},{\"t\":\"اغفر لقريبك\",\"ref\":\"يشوع بن سيراخ ٢٨: ٢\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"اغفر لقريبك ظلمه لك فاذا تضرعت تمحى خطاياك\",\"r\":\"«اغفر لقريبك ظلمه لك، فإذا تضرعت تمحى خطاياك». هذا هو نفس مبدأ الصلاة الربانية: اغفر لنا كما نغفر. وإن تمسكت بمرارتي، أعطلت صلاتي. فالغفران ليس كرمًا مني بل شرط لنوال الرحمة.\",\"p\":\"يا رب، اغفر لي كما أغفر لقريبي. أعطني قلبًا يترك المرارة، ويصلي من أجل من أساء إليّ. آمين.\"},{\"t\":\"يبكي هنا أو هناك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن عن الأب أرسانيوس: من لا يبكي نفسه هنا سيبكي هناك أبدًا، فالإنسان لا بد أن يبكي إما هنا طوعًا أو هناك من العذابات. التوبة دموع تقبل الغفران. ابك اليوم أمام الله على خطية واحدة بصدق.\",\"p\":\"يا رب، أعطني دموع التوبة هنا لئلا أبكي هناك. اغسل خطاياي بنعمتك. آمين.\",\"fq\":44}]},\"10-18\":{\"th\":\"نفوس الصديقين بيد الله\",\"m\":[{\"t\":\"كريم أمام الرب موت قديسيه\",\"ref\":\"المزمور ١١٥ — التاسعة\",\"v\":\"كريم أمام الرب موت قديسيه.\",\"r\":\"كريم أمام الرب موت قديسيه، ونفوس الصديقين بيد الله فلا يمسها عذاب. ساعة الرحيل ليست ظلمة للأبرار بل لقاء. زر اليوم قبرًا أو اذكر قديسًا بصلاة، متأملًا في رجاء الرقاد.\",\"p\":\"يا رب، كريم أمامك موت قديسيك. اجعل نفسي بيدك، وأعطني رجاء الرقاد في الإيمان. آمين.\"},{\"t\":\"هم في السلام\",\"ref\":\"الحكمة ٣: ٣\",\"bk\":\"الحكمة\",\"v\":\"وذهابهم عنا عطبا اما هم ففي السلام\",\"r\":\"«وذهابهم عنا عطبًا، أما هم ففي السلام». الموت في عين الجهال نهاية، وفي عين الإيمان انتقال. ومن فقد حبيبًا يجد في هذه الكلمة عزاء حقيقيًا. أما أنا فأصلي لهم وأثق أنهم في يد الله.\",\"p\":\"يا رب، أنت إله الأحياء. أرح أنفس راقدينا في حضنك، وعزّ القلوب الحزينة، وثبت رجاءنا في القيامة. آمين.\"},{\"t\":\"تتذكر هذه الساعة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال البابا ثيوفيلوس عند رحيله للأب أرسانيوس: هنيئًا لك لأنك كنت تتذكر هذه الساعة دائمًا. من يحيا متذكرًا ساعة الرحيل يستقبلها بسلام. اقرأ اليوم قطعة عن الأبدية قبل النوم.\",\"p\":\"يا رب، علّمني أن أتذكر ساعة الرحيل دائمًا. اجعلني مستعدًا لها بالتوبة والرجاء. آمين.\",\"fq\":146}]},\"10-19\":{\"th\":\"الله يرحم الجميع\",\"m\":[{\"t\":\"أعمال يديك\",\"ref\":\"المزمور ١٣٧ — النوم\",\"v\":\"أعمال يديك يا رب لا تتركها هلليلويا.\",\"r\":\"يصلي المرنم: أعمال يديك يا رب لا تتركها. الله يرحم الجميع لأنه خالق الجميع ولا يترك عمل يديه. ارحم اليوم من أساء إليك بالصلاة له، كمن هو عمل يدي الله.\",\"p\":\"يا رب، أعمال يديك لا تتركها. ارحم الجميع، وأعطني أن أرحم الجميع كما ترحمني. آمين.\"},{\"t\":\"ترحم الجميع\",\"ref\":\"الحكمة ١١: ٢٤\",\"bk\":\"الحكمة\",\"v\":\"لكنك ترحم الجميع لانك قادر على كل شيء وتتغاضى عن خطايا الناس لكي يتوبوا\",\"r\":\"«لكنك ترحم الجميع لأنك قادر على كل شيء، وتتغاضى عن خطايا الناس لكي يتوبوا». رحمة الله ليست ضعفًا بل قوة. وهو يمهلني لأتوب لا لأتمادى. وكل يوم جديد هو فرصة رحمة.\",\"p\":\"يا رب، ترحم الجميع لأنك قادر. أشكرك على إمهالك لي، وأعطني أن أتوب سريعًا وأرحم غيري كما رحمتني. آمين.\"},{\"t\":\"يبقي على خليقته\",\"ref\":\"\",\"v\":\"\",\"r\":\"يسأل الأب ميوس جنديًا يسأل إن كان الله يقبل التوبة: إذا كنت أنت تبقي على ثوبك الممزق، ألا يبقي الله على خليقته؟ رحمة الله أوسع من حكمنا على الناس. تذكر اليوم أن أحدًا لا يُحرم من رحمته.\",\"p\":\"يا رب، أنت تبقي على خليقتك. أعطني ثقة في رحمتك للجميع، وللتائبين خاصة. آمين.\",\"fq\":285}]},\"10-20\":{\"th\":\"طلب الحكمة\",\"m\":[{\"t\":\"أبارك الرب الذي أفهمني\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"أبارك الرب الذي أفهمني. وأيضا إلى الليل تنذرني كليتاي.\",\"r\":\"يبارك المرنم الرب الذي أفهمه، وحتى في الليل تنذره كليتاه. الحكمة عطية تُطلب من الله الذي يفهمنا. اطلب اليوم حكمة لقرار صغير، وانتظر الجواب بهدوء.\",\"p\":\"يا رب، مباركٌ أنت الذي تفهمني. هبني حكمة من عندك أسلك بها اليوم. آمين.\"},{\"t\":\"تمنيت فأوتيت الفطنة\",\"ref\":\"الحكمة ٧: ٧\",\"bk\":\"الحكمة\",\"v\":\"حينئذ تمنيت فاوتيت الفطنة ودعوت فحل علي روح الحكمة\",\"r\":\"«تمنيت فأوتيت الفطنة، ودعوت فحل عليّ روح الحكمة». الحكمة تُنال بالصلاة قبل الدراسة. وأنا عندما أحتار في قرار أحتاج أن أدعو الله أولًا. وهو لا يرد طلب الحكمة، كما وعد يعقوب بذلك.\",\"p\":\"يا رب، أطلب فطنتك وروح حكمتك. أرشدني في قراراتي، وعلمني ما يرضيك، ولا تتركني لفهمي. آمين.\"},{\"t\":\"ذهن صاح ويقظ\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: لا نحتاج إلى أحد إلا إذا كان عنده ذهن صاحٍ ويقظ. الحكمة تتطلب مرشدًا يقظًا لا كثير الكلام. اختر لنفسك اليوم مرشدًا حكيمًا وأصغ إليه.\",\"p\":\"يا رب، ضع في طريقي من له ذهن صاح ويقظ. اجعلني أسمع منه باتضاع. آمين.\",\"fq\":412}]},\"10-21\":{\"th\":\"الأسرة في قصد الله\",\"m\":[{\"t\":\"أما الرب فقبلني\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"فإن أبى وأمي قد تركاني، وأما الرب فقبلني.\",\"r\":\"يقول المرنم إن أباه وأمه قد تركاه أما الرب فقبله. الله هو أصل الأسرة وهو الذي يضم من ليس له أسرة. اشكر الله اليوم على أسرتك وصلِّ لكل فرد فيها، وللذين يعيشون بلا أسرة.\",\"p\":\"يا رب، بارك أسرتي وأحفظها في محبتك. وكن أبًا لمن ليس له أب وأمًّا لمن ليس له أم. آمين.\"},{\"t\":\"ليس جيدًا أن يكون آدم وحده\",\"ref\":\"التكوين ٢: ١٨\",\"bk\":\"التكوين\",\"v\":\"وقال الرب الإله: «ليس جيدا أن يكون آدم وحده، فأصنع له معينا نظيره».\",\"r\":\"«ليس جيدًا أن يكون آدم وحده، فأصنع له معينًا نظيره». الله هو الذي رأى حاجة الإنسان إلى الشركة. فالوحدة ليست طبيعتنا، والأسرة هبة من الله لا مجرد عرف اجتماعي. وأنا أشكره اليوم على من أعطاني ليكونوا معي.\",\"p\":\"يا رب، أشكرك لأنك لم تتركني وحدي. بارك أسرتي وكنيستي، واجعلني معينًا لمن حولي كما أعنتني. آمين.\"},{\"t\":\"أرح أباك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أرسانيوس لتلميذه: أرح أباك حتى إنه عندما ينتقل إلى الرب يصلي من أجلك لكي يأتيك الخير. براءة الأسرة تظهر في راحة الآباء. أرح اليوم أبًا أو أمًّا بكلمة أو خدمة.\",\"p\":\"يا رب، علّمني أن أريح والديّ وأكرمهما. بارك صلواتهما من أجلي. آمين.\",\"fq\":40}]},\"10-22\":{\"th\":\"اثنان خير من واحد\",\"m\":[{\"t\":\"سلام عظيم\",\"ref\":\"المزمور ١١٨ — الجزء الحادي والعشرون («كُونوا مُستَعِدّينَ، لأنَّهُ في ساعَةٍ لا تَظُنّونَ يَأتي ابنُ الإنسان.») — الستار\",\"v\":\"فليكن سلام عظيم للذين يحبون اسمك.\",\"r\":\"سلام عظيم للذين يحبون اسم الرب. اثنان خير من واحد حين يجمعهما سلام ومحبة. قدّم اليوم لشريك حياتك أو لأحد المقربين كلمة سلام وشكر.\",\"p\":\"يا رب، ليكن سلام عظيم بين الذين يحبون اسمك. بارك رباط المحبة بين المتحدين. آمين.\"},{\"t\":\"اثنان خير من واحد\",\"ref\":\"الجامعة ٤: ٩\",\"bk\":\"الجامعة\",\"v\":\"اثنان خير من واحد، لأن لهما أجرة لتعبهما صالحة.\",\"r\":\"«اثنان خير من واحد، لأن لهما أجرة لتعبهما صالحة». أحمل أثقالي وحدي كثيرًا، لكن الشركة تخفف الحمل. وهذه الحكمة تنطبق على الزواج والخدمة والصداقة. فلأسمح لأحد أن يشاركني تعبي.\",\"p\":\"يا رب، علمني ألا أحمل أثقالي وحدي. اجعل لي رفيقًا أمينًا في الجهاد، وبارك كل شركة تبني ملكوتك. آمين.\"},{\"t\":\"لا تثقل الحرب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب بيمن: إذا رأيت مشاهد وسمعت أنباء مهما كانت لا تنقلها لقريبك لأن هذا من شأنه أن يثقل الحرب عليه. الاثنان معًا يحمل أحدهما حمل الآخر. احتفظ اليوم بخبر مزعج لا يفيد، ولا تنقله.\",\"p\":\"يا رب، علّمني أن أخفف عن أخي لا أثقل عليه. اجعل كلامي سلامًا. آمين.\",\"fq\":415}]},\"10-23\":{\"th\":\"المحبة والاحترام\",\"m\":[{\"t\":\"بمجد وبهاء كلّلته\",\"ref\":\"المزمور الثامن (من صلاة باكر) — الستار\",\"v\":\"نَقَصْتَهُ قَليلًا عَنِ الملائكة، وبمَجدٍ وبَهاءٍ كَلَّلتَه. وأقَمتَهُ على أعمالِ يَدَيك، وأخضَعتَ كُلَّ شَيءٍ تحتَ قَدَمَيه.\",\"r\":\"الله كلّل الإنسان بالمجد والبهاء وأقامه على أعمال يديه. هذا المجد يستحق الاحترام، ويظهر في العلاقة بين الزوجين والأسرة. أظهر اليوم احترامك لشخص قريب منك بكلمة تقدير.\",\"p\":\"يا رب، أشكرك لأنك كلّلتنا بالمجد والكرامة. علّمني أن أكرم من تعطيني إياهم من أسرتي. آمين.\"},{\"t\":\"ليحب كل واحد امرأته\",\"ref\":\"أفسس ٥: ٣٣\",\"bk\":\"أفسس\",\"v\":\"وأما أنتم الأفراد، فليحب كل واحد امرأته هكذا كنفسه، وأما المرأة فلتهب رجلها.\",\"r\":\"«ليحب كل واحد امرأته هكذا كنفسه، وأما المرأة فلتهب رجلها». المحبة والاحترام ركنان متكاملان. لا تعيش المحبة بلا احترام، ولا يستقيم الاحترام بلا محبة. وأنا أراجع كيف أعبر عن الاثنين في بيتي.\",\"p\":\"يا رب، علمنا المحبة التي بذلت نفسك لأجلها والاحترام الذي يتواضع. اجعل بيوتنا صورة لعلاقتك بكنيستك. آمين.\"},{\"t\":\"كلمة عفوًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ثيوذورس: لقد فقد الرهبان أدبهم عندما تخلوا عن كلمة «عفوًا». الاحترام يبدأ بكلمات صغيرة مثل عفوًا وشكرًا. قل اليوم هاتين الكلمتين لأقرب الناس إليك.\",\"p\":\"يا رب، علّمني أدب المحبة. اجعل لساني مهذبًا مع أسرتي أكثر من الغرباء. آمين.\",\"fq\":133}]},\"10-24\":{\"th\":\"بيت مبني بالحكمة\",\"m\":[{\"t\":\"احفظني يا رب\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"احفظني يا رب فإني عليك توكلت. قلت للرب: أنت ربي.\",\"r\":\"يقول المرنم: احفظني يا رب فإني عليك توكلت. قلت للرب أنت ربي. البيت يبنى بحكمة حين يكون الرب سيده. قرر اليوم أن تجعل الصلاة المشتركة جزءًا ثابتًا من يوم أسرتك.\",\"p\":\"يا رب، احفظ بيتي فإني عليك توكلت. أنت ربي، فابنِ بيتي بحكمتك. آمين.\"},{\"t\":\"حكمة المرأة تبني بيتها\",\"ref\":\"الأمثال ١٤: ١\",\"bk\":\"الأمثال\",\"v\":\"حكمة المرأة تبني بيتها، والحماقة تهدمه بيدها.\",\"r\":\"«حكمة المرأة تبني بيتها، والحماقة تهدمه بيدها». بناء البيت أو هدمه يحدث بقرارات صغيرة يومية: كلمة، موقف، صبر. وأنا مسؤول عن أن أكون من البنائين لا الهادمين، مهما كان دوري في الأسرة.\",\"p\":\"يا رب، اجعلني بانيًا لبيتي بحكمتك. احفظني من الكلمات والتصرفات التي تهدم، وامنحني صبرًا وحكمة. آمين.\"},{\"t\":\"مكتفٍ في كل شيء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يصف الراوي الأب أغاثون بأنه حكيم في التفكير، عديم التعب في الجسد، مكتفٍ في كل شيء، في العمل والمأكل والملبس. بيت الحكمة بيت القناعة. اكتف اليوم بقرار شراء واحد أقل مما كنت تنوي.\",\"p\":\"يا رب، اجعل بيتي بيت قناعة وشكر. علّمني الاكتفاء الذي يبني. آمين.\",\"fq\":51}]},\"10-25\":{\"th\":\"البنون ميراث من الرب\",\"m\":[{\"t\":\"مغبوط الرجل\",\"ref\":\"المزمور ١٢٦ (١٢٧) — الغروب\",\"v\":\"مغبوط هو الرجل الذي يملا جعبته منهم. حينئذ لا يخزون إذا كلموا أعداءهم في الأبواب هلليلويا.\",\"r\":\"يشبّه المرنم البنين بالسهام، ومغبوط من يملأ جعبته منها، فلا يخزى حين يكلم أعداءه. البنون عطية من الرب ومسؤولية بيد الوالدين. اقض اليوم وقتًا مع طفل بلا هاتف.\",\"p\":\"يا رب، البنون ميراث منك. بارك أبنائي وعلّمني أن أربيهم لك. آمين.\"},{\"t\":\"البنون ميراث\",\"ref\":\"المزامير ١٢٧: ٣\",\"bk\":\"المزامير\",\"v\":\"هوذا البنون ميراث من عند الرب، ثمرة البطن أجرة.\",\"r\":\"«هوذا البنون ميراث من عند الرب، ثمرة البطن أجرة». أولادي ليسوا ملكي، بل عطية أؤتمن عليها. وهذا يعطيني مسؤولية وتواضعًا معًا: أعتني بهم لله، وأصلي لهم، ولا أحمل عليهم تحقيق أحلامي.\",\"p\":\"يا رب، أشكرك على عطية الأولاد. احفظهم في إيمانك، وعلمني أن أرعاهم كأمانة منك لا كملك لي. آمين.\"},{\"t\":\"ما لم أفعله أنا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا رئيس الدير في وداعه: لم أفعل مرة مشيئتي، كما أنني لم أعلّم أحدًا ما لم أفعله أنا أولًا. التربية بالقدوة قبل الكلام. اسأل نفسك اليوم: ما الذي أطلبه من أبنائي ولا أفعله أنا؟\",\"p\":\"يا رب، اجعل حياتي معلمة قبل كلامي. علّمني أن أفعل أولًا ما أعلّمه. آمين.\",\"fq\":213}]},\"10-26\":{\"th\":\"إكرام الوالدين\",\"m\":[{\"t\":\"كلامك حق\",\"ref\":\"المزمور ١١٨ — الجزء العشرون («كُونوا مُستَعِدّينَ، لأنَّهُ في ساعَةٍ لا تَظُنّونَ يَأتي ابنُ الإنسان.») — الستار\",\"v\":\"بد، كلامك حق، وإلي الأبد كل أحكام عدلك. هلليلويا.\",\"r\":\"كلامك حق وإلى الأبد كل أحكام عدلك. إكرام الوالدين وصية بوعد، وهو أول الوصايا الاجتماعية. اتصل اليوم بأبيك أو أمك، أو قدّم لهما خدمة.\",\"p\":\"يا رب، علّمني الإكرام لوالديّ كما أوصيتني. بارك أيامهما وأعطني أن أكون لهما سندًا. آمين.\"},{\"t\":\"وصية بوعد\",\"ref\":\"الخروج ٢٠: ١٢\",\"bk\":\"الخروج\",\"v\":\"أكرم أباك وأمك لكي تطول أيامك على الأرض التي يعطيك الرب إلهك.\",\"r\":\"«أكرم أباك وأمك لكي تطول أيامك». الإكرام ليس مجرد طاعة طفل، بل احترام يستمر طوال العمر. ومهما كبرت أحتاج أن أكرمهما بالزيارة والصلاة والاهتمام. وهذه الوصية لها بركة وعد.\",\"p\":\"يا رب، علمني أن أكرم أبي وأمي بحق. احفظهما واعطهما صحة وسلامًا، وأعطني قلبًا شاكرًا لهما. آمين.\"},{\"t\":\"كآباء وكرؤساء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس: يجب على التلاميذ أن يحبوا المعلمين الحقيقيين كآباء وأن يخافوهم كرؤساء، فلا يسقطون الخوف بداعي المحبة ولا يزيلون المحبة بداعي الخوف. الإكرام يجمع الحب والهيبة. أظهر اليوم احترامًا لمن له سلطة عليك.\",\"p\":\"يا رب، علّمني الحب والهيبة معًا. أعطني أن أكرم كل من وضعتهم في حياتي أبوة لي. آمين.\",\"fq\":201}]},\"10-27\":{\"th\":\"تربية الأجيال\",\"m\":[{\"t\":\"من أفواه الأطفال\",\"ref\":\"المزمور الثامن (من صلاة باكر) — الستار\",\"v\":\"مِن أفواهِ الأطفالِ والرُّضَّعِ أسَّسْتَ حَمدًا، بِسَبَبِ أضدادِكَ، لِتُسَكِّتَ العَدُوَّ والمُنتَقِم.\",\"r\":\"من أفواه الأطفال والرضع أسس الرب حمدًا. تربية الأجيال تبدأ بأن يسمع الأطفال تسبيحنا ويقلدوه. رتّل اليوم مع طفل ترنيمة بسيطة، أو صلِّ معه صلاة قصيرة.\",\"p\":\"يا رب، من أفواه الأطفال أسست حمدًا. اجعل بيتي مدرسة تسبيح لأطفالي. آمين.\"},{\"t\":\"لئلا يفشلوا\",\"ref\":\"كولوسي ٣: ٢١\",\"bk\":\"كولوسي\",\"v\":\"أيها الآباء، لا تغيظوا أولادكم لئلا يفشلوا.\",\"r\":\"«أيها الآباء، لا تغيظوا أولادكم لئلا يفشلوا». التربية بالقسوة تنتج إحباطًا. والأولاد يحتاجون إلى توجيه بحب وصبر. وأنا أسأل نفسي: هل أبني ثقة من أخدمهم أم أحطمها بكلماتي وتوقعاتي؟\",\"p\":\"يا رب، علمني أن أربي بالمحبة والصبر. احفظني من الغضب مع الصغار، واجعل كلمتي تبني فيهم الثقة والإيمان. آمين.\"},{\"t\":\"أعمل عملي صامتًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"تعلم الأب إسحق من الأب كرونيو الصامت أن يسرع إلى الأعمال التي ينويها، وقال: هذا علمني أن أقوم بعملي صامتًا. الصمت العملي يربي أكثر من الخطب. اعمل اليوم أمام أطفالك الصلاح الذي تريدهم أن يتعلموه.\",\"p\":\"يا رب، علّمني أن أربي بالصمت العامل. اجعل أعمالي كلمة صالحة لأبنائي. آمين.\",\"fq\":177}]},\"10-28\":{\"th\":\"دعوا الأولاد يأتون\",\"m\":[{\"t\":\"أم أولاد فرحة\",\"ref\":\"المزمور ١١٢ (١١٣) — باكر\",\"v\":\"الذي يجعل العاقر ساكنة في بيت، أم أولاد فرحة.\",\"r\":\"الله يجعل العاقر ساكنة في بيت أمًّا فرحة بأولادها. الطفل في عين الله عظيم، وهو الذي قال دعوا الأولاد يأتون إلي. أنصت اليوم لطفل بانتباه كامل، دون أن تقاطعه.\",\"p\":\"يا رب، أشكرك على الأطفال وعلى تواضعهم. اجعل بيوتنا فرحة بهم، وعلّمني أن أقبلهم كما قبلتهم. آمين.\"},{\"t\":\"دعوا الأولاد يأتون إلي\",\"ref\":\"مرقس ١٠: ١٤\",\"bk\":\"مرقس\",\"v\":\"فلما رأى يسوع ذلك اغتاظ وقال لهم: «دعوا الأولاد يأتون إلي ولا تمنعوهم، لأن لمثل هؤلاء ملكوت الله.\",\"r\":\"«دعوا الأولاد يأتون إليّ ولا تمنعوهم، لأن لمثل هؤلاء ملكوت الله». المسيح يغتاظ حين يُعاق الصغار عن القرب منه. فلا أضع عوائق أمامهم من تعقيد أو ملل أو قسوة. بل أسهّل لهم الطريق إليه.\",\"p\":\"يا رب يسوع، أنت تحب الصغار. ساعدني لا أكون عائقًا لهم، بل باب محبة يقودهم إليك بسهولة وفرح. آمين.\"},{\"t\":\"كن قدوة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب بيمن لمن سأل عن الإخوة المقيمين معه: كن قدوة في كل شيء وليس مشرّعًا. الأطفال يتعلمون من سلوكنا لا من لوائحنا. اجعل اليوم تصرفك القدوة لا الأوامر.\",\"p\":\"يا رب، اجعلني قدوة صالحة لأولادي وللصغار. اكتب فيّ ما أريد أن يقرؤوه. آمين.\",\"fq\":443}]},\"10-29\":{\"th\":\"الوفاء والمسؤولية\",\"m\":[{\"t\":\"أوفي نذوري يومًا فيوم\",\"ref\":\"المزمور ٦٠ (٦١) — السادسة\",\"v\":\"هكذا أرتل لاسمك إلى دهر الدهور، لأفي نذوري يوما فيوما.\",\"r\":\"يرتل المرنم لاسم الرب إلى دهر الدهور ليفي نذوره يومًا فيوم. الوفاء الحقيقي بقاء الإنسان مع من التزم بهم كما فعلت راعوث. أوف اليوم بوعد صغير تأخرت فيه.\",\"p\":\"يا رب، أوفي لك نذوري. علّمني الوفاء في الصغير والكبير، وأعطني أن أبقى أمينًا لمن ارتبطت بهم. آمين.\"},{\"t\":\"حيثما ذهبت أذهب\",\"ref\":\"راعوث ١: ١٦\",\"bk\":\"راعوث\",\"v\":\"فقالت راعوث: «لا تلحي علي أن أتركك وأرجع عنك، لأنه حيثما ذهبت أذهب وحيثما بت أبيت. شعبك شعبي وإلهك إلهي.\",\"r\":\"«لا تلحي عليّ أن أتركك وأرجع عنك، لأنه حيثما ذهبت أذهب… شعبك شعبي وإلهك إلهي». الوفاء ليس مشاعر بل قرار. وراعوث اختارت الله والرفقة في وقت المرارة. وأنا أتعلم الوفاء لأهلي وكنيستي حتى في زمن الصعوبة.\",\"p\":\"يا رب، علمني الوفاء كما فعلت راعوث. اجعلني أمينًا لأهلي وكنيستي وشعبك، وثبتني بجوار من يحتاجني في ضيقه. آمين.\"},{\"t\":\"ثمن واحد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب بيستامون من ينزعج وهو يبيع عمل يديه: قل ثمن السلال مرة واحدة فقط، وإن رغبت في تخفيضه فهذا لك، وبهذا تجد راحة. الأمانة في المعاملة تريح القلب. كن اليوم صريحًا وصادقًا في كل تعامل مالي.\",\"p\":\"يا رب، علّمني الصدق في كل أخذ وعطاء. اجعل كلمتي واحدة وذمتي نقية. آمين.\",\"fq\":470}]},\"10-30\":{\"th\":\"البيت المبارك\",\"m\":[{\"t\":\"بظل جناحيك أبتهج\",\"ref\":\"المزمور ٦٣ — باكر\",\"v\":\"كنت أذكرك على فراشي. وفى أوقات الأسحار كنت أرتل لك. لأنك صرت لي عونا، وبظل جناحيك ابتهج.\",\"r\":\"يذكر المرنم الله على فراشه ويرتل له في الأسحار، فصار الله عونًا وبظل جناحيه يبتهج. البيت المبارك بيت يذكر الله في الصباح والمساء. ابدأ اليوم صلاة قصيرة مع أسرتك قبل النوم.\",\"p\":\"يا رب، كن عوني وبظل جناحيك أبتهج. بارك بيتنا وعلّمنا أن نذكرك مساءً وصباحًا. آمين.\"},{\"t\":\"رجل المرأة الصالحة مغبوط\",\"ref\":\"يشوع بن سيراخ ٢٦: ١\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"رجل المراة الصالحة مغبوط وعدد ايامه مضاعف\",\"r\":\"«رجل المرأة الصالحة مغبوط، وعدد أيامه مضاعف». حضور شريك صالح يضاعف الفرح والسلام. وأنا أشكر الله على من أعطاني، وأطلب أن أكون أنا أيضًا مصدر خير وسلام لمن يشاركني الحياة.\",\"p\":\"يا رب، أشكرك على نعمة الأسرة الصالحة. بارك كل بيت، واجعل أزواجنا وزوجاتنا مصدر بركة وسلام. آمين.\"},{\"t\":\"كنا نعيش بسلام\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب رومانوس عند رحيله: لا أذكر أني طلبت من أحدكم شيئًا دون التفكير به قبل طلبه، وهكذا كنا نعيش بسلام كل زمان حياتنا. السلام في البيت ثمرة التفكير قبل الطلب. فكر اليوم قبل أن تطلب من أحد أفراد أسرتك طلبًا.\",\"p\":\"يا رب، اجعل بيتنا بيت سلام. علّمنا أن نفكر قبل أن نطلب ونتكلم. آمين.\",\"fq\":483}]},\"10-31\":{\"th\":\"أمانة الأجيال\",\"m\":[{\"t\":\"أمر بعهده إلى الأبد\",\"ref\":\"المزمور ١١٠ (١١١) — التاسعة\",\"v\":\"كل وصاياه صادقة. ثابتة إلى دهر الدهور، مصنوعة بالحق والاستقامة. أرسل خلاصا لشعبه. أمر بعهده إلى الأبد.\",\"r\":\"كل وصايا الله صادقة وثابتة إلى دهر الدهور، وقد أمر بعهده إلى الأبد. أمانة الأجيال أن ننقل هذا العهد من جيل إلى جيل. اكتب اليوم اسم من علّمك الإيمان، واشكر الله عليه، وفكر فيمن تعلّمه أنت.\",\"p\":\"يا رب، وصاياك ثابتة وعهدك أبدي. اجعل أمانتنا تسلم الإيمان لمن بعدنا. آمين.\"},{\"t\":\"أخبروا بنيكم عنه\",\"ref\":\"يوئيل ١: ٣\",\"bk\":\"يوئيل\",\"v\":\"أخبروا بنيكم عنه، وبنوكم بنيهم، وبنوهم دورا آخر.\",\"r\":\"«أخبروا بنيكم عنه، وبنوكم بنيهم، وبنوهم دورًا آخر». لا أعيش إيماني لنفسي فقط. إنه أمانة أنقلها. وأتساءل: ماذا أخبر به أولادي وأحفادي عن الله؟ وهل يرون في حياتي ما يثبت كلامي؟\",\"p\":\"يا رب، اجعلني شاهدًا لك أمام أولادي وأحفادي. علمني أن أنقل لهم ما اختبرته من أمانتك، ليثبتوا فيك. آمين.\"},{\"t\":\"انظروا سلوكي\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب إسحق لآبائه عند رحيله: انظروا كيف كان سلوكي بينكم، فإذا أردتم أن تتبعوني احفظوا وصايا الله وهو يرسل نعمته. هذا ميراث الأجيال. اجعل سلوكك اليوم رسالة لمن يتبعك.\",\"p\":\"يا رب، اجعل حياتي رسالة أمانة. علّمني أن أحفظ وصاياك لتحفظ نعمتك من بعدي. آمين.\",\"fq\":181}]},\"11-1\":{\"th\":\"صرخة من الهاوية\",\"m\":[{\"t\":\"من الأعماق صرخت\",\"ref\":\"المزمور ١٢٩ (١٣٠) — النوم\",\"v\":\"من الأعماق صرخت إليك يا رب؛ يا رب استمع صوتي. لتكن أذناك مصغيتين إلى صوت تضرعي.\",\"r\":\"صرخ المرنم من الأعماق، وصرخ يونان من جوف الحوت، والله سمع في الحالتين. لا يوجد عمق يمنع الصوت من الوصول إليه. اصرخ اليوم إلى الرب من موضع الضيق الذي تعرفه، بكلمات قليلة وصادقة.\",\"p\":\"يا رب، من الأعماق صرخت إليك. لتكن أذناك مصغيتين إلى صوت تضرعي، وأخرجني من حيث أنا. آمين.\"},{\"t\":\"دعوت من ضيقي فاستجابني\",\"ref\":\"يونان ٢: ٢\",\"bk\":\"يونان\",\"v\":\"وقال: «دعوت من ضيقي الرب، فاستجابني. صرخت من جوف الهاوية، فسمعت صوتي.\",\"r\":\"«دعوت من ضيقي الرب فاستجابني. صرخت من جوف الهاوية فسمعت صوتي». لا يوجد مكان أسفل من أن يصل إليه صوتي. وحتى لو كانت ضيقتي بسبب عنادي كما كان مع يونان، فإن الرب يسمع صرخة العودة.\",\"p\":\"يا رب، أنت تسمع من الهاوية. اسمع صرختي في ضيقي، وارفعني بيدك كما رفعت يونان، وأعطني أن أشكرك قبل أن أرى الخلاص. آمين.\"},{\"t\":\"جدار مظلم\",\"ref\":\"\",\"v\":\"\",\"r\":\"زار أخ الأب أموي طالبًا كلمة، وبعد سبعة أيام من الصمت قال له: اذهب وانتبه لنفسك، أما أنا فخطاياي قد صارت جدارًا مظلمًا بيني وبين الله. من يرى جدار خطيته يصرخ إلى الله من الأعماق. سمّ اليوم الجدار الذي يفصلك، وارفعه إلى الله.\",\"p\":\"يا رب، اهدم الجدار الذي أقمته بخطاياي بيني وبينك. اسمع صراخي من الأعماق وقرّبني إليك. آمين.\",\"fq\":66}]},\"11-2\":{\"th\":\"ارجعوا إلى الرب\",\"m\":[{\"t\":\"رأفتك كثيرة جدًا يا رب\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء العشرون · صلاة الستار\",\"v\":\"رأفتك كثيرة جدا يا رب. حسب أحكامك أحيني.\",\"r\":\"يتكل المرنم على كثرة رأفة الله ويطلب الحياة حسب أحكامه. الرجوع إلى الرب ليس بقوتنا بل برأفته. ارجع اليوم إلى الرب بخطوة واحدة محددة: اعتراف أو مصالحة أو صلاة.\",\"p\":\"رأفتك كثيرة جدًا يا رب، حسب أحكامك أحيني. أرجعني إليك برحمتك، فأنت الذي ترد من يرجع. آمين.\"},{\"t\":\"خذوا معكم كلامًا\",\"ref\":\"هوشع ١٤: ٢\",\"bk\":\"هوشع\",\"v\":\"خذوا معكم كلاما وارجعوا إلى الرب. قولوا له: «ارفع كل إثم واقبل حسنا، فنقدم عجول شفاهنا.\",\"r\":\"«خذوا معكم كلامًا وارجعوا إلى الرب. قولوا له: ارفع كل إثم». لا يطلب الله ذبائح كثيرة بل كلامًا صادقًا من قلب تائب. وأنا أحتاج أن أجهز اعترافي بكلمات واضحة، وأتجنب العموميات.\",\"p\":\"يا رب، علمني كلمات التوبة. ارفع كل إثم واقبل ما هو حسن، وأعطني شجاعة الاعتراف الكامل. آمين.\"},{\"t\":\"لا يتقيد بوصية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ثيوذورس الفرمي: إن من يقيم في التوبة لا يتقيد بوصية. التوبة المقيمة حالة قلب مفتوح يقبل كل مشيئة الله. اجعل التوبة اليوم موقفًا لا فعلًا واحدًا: قل لله عند كل خطأ صغير: غفرانك.\",\"p\":\"يا رب، أقمني في التوبة كل أيام حياتي. اجعل قلبي منفتحًا لكل وصاياك. آمين.\",\"fq\":136}]},\"11-3\":{\"th\":\"زرع البر وحبل المحبة\",\"m\":[{\"t\":\"توقعت خلاصك\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء الحادي والعشرون · صلاة الستار\",\"v\":\"توقعت خلاصك يا رب ووصاياك أحببتها.\",\"r\":\"يتوقع المرنم خلاص الرب ويحب وصاياه. زرع البر يبدأ بحب الوصية ثم بالعمل بها يومًا بيوم. ازرع اليوم عملًا صغيرًا من البر دون أن تنتظر ثمرًا قريبًا.\",\"p\":\"يا رب، توقعت خلاصك وأحببت وصاياك. ازرع فيّ بذار البر، واربطني بحبال محبتك. آمين.\"},{\"t\":\"بحبال البشر، بربط المحبة\",\"ref\":\"هوشع ١١: ٤\",\"bk\":\"هوشع\",\"v\":\"كنت أجذبهم بحبال البشر، بربط المحبة، وكنت لهم كمن يرفع النير عن أعناقهم، ومددت إليه مطعما إياه.\",\"r\":\"«كنت أجذبهم بحبال البشر، بربط المحبة، وكنت لهم كمن يرفع النير عن أعناقهم». الله لا يقودني بالقسر بل بالحب. وهو يعلمني كما يعلم الأب طفلًا الخطوات الأولى. وحين أسقط، يحملني. فلا أخاف من الاقتراب إليه.\",\"p\":\"يا أبي الحنون، أمسكتني بذراعيك ولم أعرف. اجذبني بربط محبتك، وارفع عني كل نير ثقيل، واطعمني من يدك. آمين.\"},{\"t\":\"ثمار الطاعة\",\"ref\":\"\",\"v\":\"\",\"r\":\"عاد الأب يوحنا الكولوفي بعد ثلاث سنين بثمر العصا اليابسة التي غرسها له أبوه الروحي وأمره أن يسقيها، وقال للإخوة: خذوا كلوا من ثمار الطاعة. الطاعة تثمر حيث لا يُنتظر ثمر. اسق اليوم أمرًا يبدو يابسًا في حياتك بصبر أمين.\",\"p\":\"يا رب، علّمني الطاعة التي تثمر. أعطني صبرًا أسقي به ما يبدو يابسًا حتى يزهر. آمين.\",\"fq\":150}]},\"11-4\":{\"th\":\"تطرح في أعماق البحر\",\"m\":[{\"t\":\"إلى الأبد رحمته\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"ليقل بيت إسرائيل إنه صالح وإن إلى الأبد رحمته.\",\"r\":\"يدعو المرنم أن يقول بيت إسرائيل إن الرب صالح وإلى الأبد رحمته. الله يطرح خطايانا في أعماق البحر ولا يذكرها. اكتب اليوم خطية تاب عنها واعترفت بها، وقل: طرحها الله في العمق.\",\"p\":\"يا رب، أنت صالح وإلى الأبد رحمتك. اطرح خطاياي في أعماق البحر ولا تذكرها. آمين.\"},{\"t\":\"تطرح خطاياهم\",\"ref\":\"ميخا ٧: ١٩\",\"bk\":\"ميخا\",\"v\":\"يعود يرحمنا، يدوس آثامنا، وتطرح في أعماق البحر جميع خطاياهم.\",\"r\":\"«يعود يرحمنا، يدوس آثامنا، وتطرح في أعماق البحر جميع خطاياهم». ما غفره الله لا يعود يحاسبني عليه. وأنا أحيانًا أستخرج خطاياي القديمة من أعماق البحر لأوبخ نفسي. فلأتوقف وأثق في غفرانه.\",\"p\":\"يا رب، أشكرك لأنك تدوس آثامي وتطرح خطاياي في أعماق البحر. ثبّتني في غفرانك، ولا تدعني أعود إلى ما قد غفرته. آمين.\"},{\"t\":\"الكيس خلف الظهر\",\"ref\":\"\",\"v\":\"\",\"r\":\"حمل الأب بيور كيسًا مملوءًا رملًا وراء ظهره، وقال إنه خطاياه الكثيرة، تركها وراءه لئلا يتألم بها، أما خطية أخيه فهي أمامه ينشغل بها إذ يدينه، وهذا لا يليق. من طُرحت خطاياه لا ينظر إلى خطايا الآخرين. ضع اليوم خطاياك أمام عينيك لا خطايا غيرك.\",\"p\":\"يا رب، سامحني على خطاياي الكثيرة واطرحها في العمق. احفظ عيني من النظر إلى خطايا إخوتي. آمين.\",\"fq\":468}]},\"11-5\":{\"th\":\"اذكر الرحمة في الغضب\",\"m\":[{\"t\":\"وحياة في رضاه\",\"ref\":\"المزمور ٢٩ (٣٠) — الثالثة\",\"v\":\"لأن سخطا في غضبه: وحياة في رضاه.\",\"r\":\"يقول المرنم: سخط في غضبه وحياة في رضاه. حين يغضب الله لا ينسى أن يرحم، وهكذا يريدنا أن نتذكر الرحمة حين نغضب. حين يثور فيك غضب اليوم، تنفس ببطء وقل: يا رب اذكر الرحمة.\",\"p\":\"يا رب، في الغضب اذكر الرحمة. اجعلني أتذكر رحمتك حين أغضب وأغيظ، فأحيا في رضاك. آمين.\"},{\"t\":\"في الغضب اذكر الرحمة\",\"ref\":\"حبقوق ٣: ٢\",\"bk\":\"حبقوق\",\"v\":\"يا رب، قد سمعت خبرك فجزعت. يا رب، عملك في وسط السنين أحيه. في وسط السنين عرف. في الغضب اذكر الرحمة.\",\"r\":\"«يا رب، عملك في وسط السنين أحيه… في الغضب اذكر الرحمة». كثيرًا ما أرى الأزمات ولا أرى يد الله. فأطلب منه أن يحيي عمله ويظهره. وفي ضيقي أذكره بما أعرفه عنه: أنه رحيم.\",\"p\":\"يا رب، أحيِ عملك في وسط السنين. في الغضب اذكر الرحمة، وفي ضيقنا ثبت إيماننا ورجاءنا. آمين.\"},{\"t\":\"الغضوب لا يُقبل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أغاثون: لو أقام الغضوب ميتًا لن يكون مقبولًا عند الله. الغضب يهدم حتى أعظم العطايا. اترك اليوم محاولة الانتصار في جدال صغير، وقدمها لله.\",\"p\":\"يا رب، اقتلع الغضب من قلبي. اجعل رحمتي أسبق من غضبي ووداعتي أقوى من اندفاعي. آمين.\",\"fq\":54}]},\"11-6\":{\"th\":\"اجعلوا قلبكم على طرقكم\",\"m\":[{\"t\":\"وعن شهاداتك لم أجنح\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء العشرون · صلاة الستار\",\"v\":\"كثيرون هم الذين يضطهدونني ويحزنونني. وعن شهاداتك لم أجنح.\",\"r\":\"كثيرون يضطهدون المرنم ويحزنونه، لكنه لم يجنح عن شهادات الله. أن نجعل قلبنا على طرقنا يعني أن نراجع خطواتنا بصدق. اكتب اليوم ثلاث خطوات عشتها هذا الأسبوع، واسأل: أين كنت فيها قريبًا من الله؟\",\"p\":\"يا رب، لا أجنح عن شهاداتك مهما كثر المضايقون. علّمني أن أراجع طرقي وأعدلها. آمين.\"},{\"t\":\"اطلبوا الرب واطلبوا التواضع\",\"ref\":\"صفنيا ٢: ٣\",\"bk\":\"صفنيا\",\"v\":\"أطلبوا الرب، يا جميع بائسي الأرض الذين فعلوا حكمه. اطلبوا البر. اطلبوا التواضع. لعلكم تسترون في يوم سخط الرب.\",\"r\":\"«اطلبوا الرب… اطلبوا البر. اطلبوا التواضع». ثلاث طلبات متتابعة. طلب الرب أولًا ثم البر والتواضع. ولا أنال الاستتار في يوم الضيق إلا بقرب الله. فلأبدأ اليوم بالطلب، وأعلم أن التواضع يُطلب كما يُطلب البر.\",\"p\":\"يا رب، علمني أن أطلبك وأطلب البر والتواضع. استرني في يوم الضيق بسترك، واجعلني متكلًا على رحمتك. آمين.\"},{\"t\":\"كشف الخطوات\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح القديس أنطونيوس بأن يكشف الراهب للآباء كل خطواته وكل قطرات الماء التي يشربها في قلايته، ليتأكد أنه لا يخطئ. الشفافية مع مرشد أمين تحمي الطريق. اكشف اليوم أمرًا لأب اعترافك أو صديق روحي.\",\"p\":\"يا رب، علّمني الشفافية أمام مرشدي. احفظني من التكتم الذي يخفي سقوطي. آمين.\",\"fq\":22}]},\"11-7\":{\"th\":\"مجد البيت الأخير\",\"m\":[{\"t\":\"أحببت جمال بيتك\",\"ref\":\"المزمور ٢٥ (٢٦) — الثالثة\",\"v\":\"أغسل يدي بالنقاوة. وأطوف بمذبحك يا رب. لأسمع صوت تسبيحك. وأنطق بجميع عجائبك. يا رب أحببت جمال بيتك وموضع مسكن مجدك.\",\"r\":\"أغسل يدي بالنقاوة وأطوف بمذبحك، لأسمع صوت تسبيحك، فقد أحببت جمال بيتك وموضع مسكن مجدك. مجد البيت الأخير أعظم من الأول لأنه يمتلئ حضورًا. اسهم اليوم في ترتيب بيت من بيوت الله، كنيستك أو بيتك.\",\"p\":\"يا رب، أحببت جمال بيتك. اغسل يدي بالنقاوة واجعلني أطوف بمذبحك وأنطق بعجائبك. آمين.\"},{\"t\":\"وفي هذا المكان أعطي السلام\",\"ref\":\"حجي ٢: ٩\",\"bk\":\"حجي\",\"v\":\"مجد هذا البيت الأخير يكون أعظم من مجد الأول، قال رب الجنود. وفي هذا المكان أعطي السلام، يقول رب الجنود».\",\"r\":\"«مجد هذا البيت الأخير يكون أعظم من مجد الأول… وفي هذا المكان أعطي السلام». وعد بمجد أعظم وسلام. والمسيح دخل الهيكل وأعطى السلام. وهو يعطيني اليوم سلامه في بيته، فلا أترك السلام حين أخرج من الكنيسة.\",\"p\":\"يا رب، أنت أعطيت السلام في بيتك. املأ كنيستك بمجدك، واجعلني أحمل سلامك إلى أسرتي وعملي. آمين.\"},{\"t\":\"الشدة والسكينة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا الكيليكس: لنتشبه بآبائنا، كم من الشدة والسكينة أقاموا هنا. أساس البيت الروحي أن نبنيه على تضحية من سبقونا. اشكر اليوم من أسسوا كنيستك، وصلِّ لهم.\",\"p\":\"يا رب، أشكرك على من بنوا كنيستك بتعبهم. أعطني أن أحفظ ما تركوه وأبني عليه بأمانة. آمين.\",\"fq\":195}]},\"11-8\":{\"th\":\"الرسول والعشور والتذكرة\",\"m\":[{\"t\":\"يذكر جميع ذبائحك\",\"ref\":\"المزمور ١٩ (٢٠) — الثالثة\",\"v\":\"يذكر جميع ذبائحك؛ ويستسمن محرقاتك. يعطيك الرب حسب قلبك، ويتمم كل مشورتك.\",\"r\":\"يذكر الرب ذبائحنا ويعطينا حسب قلوبنا ويتمم كل مشورتنا. العشور والتقدمات اعتراف بأن كل ما لدينا من يده. أفرز اليوم جزءًا من دخلك للرب أو للفقراء، وقدمه بفرح.\",\"p\":\"يا رب، اذكر ذبائحي وأعطني حسب قلبي. علّمني أن أقدم لك أول ما أملك بشكر. آمين.\"},{\"t\":\"جربوني بهذا\",\"ref\":\"ملاخي ٣: ١٠\",\"bk\":\"ملاخي\",\"v\":\"هاتوا جميع العشور إلى الخزنة ليكون في بيتي طعام، وجربوني بهذا، قال رب الجنود، إن كنت لا أفتح لكم كوى السماوات، وأفيض عليكم بركة حتى لا توسع.\",\"r\":\"«هاتوا جميع العشور إلى الخزنة… وجربوني بهذا». الله يدعوني إلى أمانة في المال أرى فيها وفاءه. العشور ليست ثمنًا للبركة، بل تدريب على الثقة. وأنا أبدأ بالأمانة فيما أملك لأرى أمانة الله.\",\"p\":\"يا رب، كل ما لدي منك. علمني الأمانة في العطاء، وافتح لي ثقة لا تتزعزع في أنك مصدر كل بركة. آمين.\"},{\"t\":\"حب المال المخيف\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس إن حب المال المخيف الذي لا يعرف الشبع يقود النفس المستعبدة له إلى أسوأ الشرور، فلنبتعد عنه من البدء لأنه إذا ساد صار سيدًا لا يقهر. التذكرة الأولى في العشور أن المال ليس سيدًا. أعطِ اليوم قبل أن تحسب.\",\"p\":\"يا رب، حرّرني من حب المال. اجعلني خادمًا لك لا لمالي. آمين.\",\"fq\":175}]},\"11-9\":{\"th\":\"شمس البر\",\"m\":[{\"t\":\"الله الرب أضاء علينا\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"الله الرب أضاء علينا.\",\"r\":\"الله الرب أضاء علينا، فهو شمس البر وفي أجنحتها الشفاء. كل صباح لنا فرصة لنقف في ضوئه. وقف اليوم دقيقة في الشمس أو عند النافذة، وصلِّ: أضئ علينا يا رب.\",\"p\":\"يا شمس البر، أضئ علينا. اطلع في قلبي بشفاء أجنحتك، واجعلني أنعكس نورك. آمين.\"},{\"t\":\"تشرق شمس البر\",\"ref\":\"ملاخي ٤: ٢\",\"bk\":\"ملاخي\",\"v\":\"«ولكم أيها المتقون اسمي تشرق شمس البر والشفاء في أجنحتها، فتخرجون وتنشأون كعجول الصيرة.\",\"r\":\"«ولكم أيها المتقون اسمي تشرق شمس البر والشفاء في أجنحتها». المسيح هو شمس البر. وحين يشرق في قلبي تهرب الظلمة. ومن يعيش في نوره ينمو ويفرح كعجل خارج من الحظيرة.\",\"p\":\"يا شمس البر، أشرق في قلبي. اشفني من ظلمة الخطية، وأخرجني إلى نورك كعجل يفرح بحريته. آمين.\"},{\"t\":\"عن رؤية الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ثيوناس: بسبب انشغال العقل الأعلى في غير رؤية الله نسقط أسرى الأهواء الجسدية. الشمس الحقيقية تحرر من الظلام. وجّه اليوم نظرك لحظة نحو الله كلما انشغل ذهنك بما لا يليق.\",\"p\":\"يا رب، اجعل ذهني متجهًا نحوك. حرّره من انشغالاته الباطلة. آمين.\",\"fq\":144}]},\"11-10\":{\"th\":\"العهد الجديد والشفاء\",\"m\":[{\"t\":\"ورتبت مضجعه في مرضه\",\"ref\":\"المزمور ٤٠ (٤١) — الثالثة\",\"v\":\"الرب يعينه على سرير وجعه. إنك رتبت مضجعه كله في مرضه.\",\"r\":\"الرب يعين المريض على سرير وجعه ويرتب مضجعه كله في مرضه. العهد الجديد وعد بشفاء من الداخل أولًا. صلِّ اليوم من أجل مريض، وقدم له كلمة أو خدمة.\",\"p\":\"يا رب، أعن كل مريض على سرير وجعه. اشفِ جراح قلوبنا بعهدك الجديد. آمين.\"},{\"t\":\"أكتب شريعتي على قلوبهم\",\"ref\":\"إرميا ٣١: ٣٣\",\"bk\":\"إرميا\",\"v\":\"بل هذا هو العهد الذي أقطعه مع بيت إسرائيل بعد تلك الأيام، يقول الرب: أجعل شريعتي في داخلهم وأكتبها على قلوبهم، وأكون لهم إلها وهم يكونون لي شعبا.\",\"r\":\"«أجعل شريعتي في داخلهم وأكتبها على قلوبهم». الوصية لن تبقى حجرًا على لوح بل تدخل قلبي. وهذا يتم بنعمة الروح القدس. فلأطلب كل صباح أن يكتب الله وصاياه في قلبي، لا على ورقة أنساها.\",\"p\":\"يا رب، اكتب شريعتك على قلبي بروحك القدوس. اجعلني أحب وصاياك وأعمل بها، وكن إلهي وأنا من شعبك. آمين.\"},{\"t\":\"جسد وروح\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب دانيال: بمقدار ما ينتعش الجسد تضعف النفس، وبمقدار ما يضعف الجسد تنتعش النفس. المرض قد يصير مدرسة للروح. اشكر الله اليوم على ما علّمك إياه الألم.\",\"p\":\"يا رب، علّمني أن أحيا في الضعف نمو الروح. اشفِ جسدي إن شئت وقوّ نفسي بك. آمين.\",\"fq\":94}]},\"11-11\":{\"th\":\"إيمان أيوب\",\"m\":[{\"t\":\"عليك توكلت\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"انظر إلى أعدائي فإنهم قد كثروا وأبغضوني ظلما. احفظ نفسي ونجني، لا أخزى لأني عليك توكلت.\",\"r\":\"ينظر المرنم إلى كثرة مبغضيه، لكنه يطلب الحفظ لأنه عليك توكل. هذا إيمان أيوب: أعلم أن فادي حي، وفي الامتحان أخرج كالذهب. توكل اليوم في أمر واحد تخشاه، ولو قلتها صلاة قصيرة.\",\"p\":\"احفظ نفسي ونجني يا رب، لا أخزى لأني عليك توكلت. ثبّت إيماني كأيوب في الامتحان. آمين.\"},{\"t\":\"أما أنا فقد علمت أن وليي حي\",\"ref\":\"أيوب ١٩: ٢٥\",\"bk\":\"أيوب\",\"v\":\"أما أنا فقد علمت أن وليي حي، والآخر على الأرض يقوم،\",\"r\":\"«أما أنا فقد علمت أن وليي حي، والآخر على الأرض يقوم». في قمة الألم يصرخ أيوب بإيمان القيامة. وأنا أيضًا، وسط ضيقاتي، أتمسك بأن فاديّ حي، وأنني سأرى الله. وهذا الرجاء لا يسلبه مني أحد.\",\"p\":\"يا فادي، أنت وليي الحي. ثبّت إيماني بقيامتي وقيامة أحبائي، وأعطني رجاءً لا يتزعزع في أوقات الألم والليل. آمين.\"},{\"t\":\"نوح ودانيال وأيوب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: نوح صورة اللاقنية، وأيوب صورة الألم، ودانيال مثال التمييز، وإذا وجد الثلاثة معًا في إنسان فإن الله يقيم فيه. إيمان أيوب يحتاج هذه الثلاثة. اختر منها اليوم فضيلة واحدة تتدرب عليها.\",\"p\":\"يا رب، أعطني قناعة نوح وصبر أيوب وتمييز دانيال. وأقم فيّ بنعمتك. آمين.\",\"fq\":358}]},\"11-12\":{\"th\":\"الحكمة والتأديب\",\"m\":[{\"t\":\"ليؤدبني الصديق برحمة\",\"ref\":\"المزمور ١٤٠ (١٤١) — النوم\",\"v\":\"فليؤدبني الصديق برحمة ويوبخني.\",\"r\":\"يقول المرنم: فليؤدبني الصديق برحمة ويوبخني. التأديب علامة محبة، والحكمة تبدأ بقبوله. اطلب اليوم من صديق أمين ملاحظة صادقة على تصرف لك.\",\"p\":\"يا رب، أعطني قلبًا يقبل التأديب. ليؤدبني الصديق برحمة، فأتعلم ولا أعاند. آمين.\"},{\"t\":\"طوبى لرجل يؤدبه الله\",\"ref\":\"أيوب ٥: ١٧\",\"bk\":\"أيوب\",\"v\":\"« هوذا طوبى لرجل يؤدبه الله. فلا ترفض تأديب القدير.\",\"r\":\"«طوبى لرجل يؤدبه الله، فلا ترفض تأديب القدير». التأديب ليس رفضًا بل محبة. وأنا حين أتعرض لتصحيح لا أفرح به لكني أقبله، لأنه يشبه تأديب الأب لابنه. فلأعامل التأديب بشكر.\",\"p\":\"يا رب، لا أرفض تأديبك لأنه محبة. علمني من كل تصحيح، وأعطني قلبًا ينفتح للتعلم بدل أن ينغلق في الدفاع. آمين.\"},{\"t\":\"التعليم يشبه التوبيخ\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: إن تعليم القريب شبيه بتوبيخه. من يعلّم يتحمل مسؤولية المعلم، ومن يقبل التعليم يتحمل أن يُصحَّح. اقبل اليوم تصحيحًا بتواضع، ولا تدافع.\",\"p\":\"يا رب، علّمني قبول التصحيح. وإن علّمت أحدًا فاجعل كلامي رحمة. آمين.\",\"fq\":430}]},\"11-13\":{\"th\":\"لكل شيء زمان\",\"m\":[{\"t\":\"سبع مرات في النهار\",\"ref\":\"المزمور ١١٨ — الجزء الحادي والعشرون («كُونوا مُستَعِدّينَ، لأنَّهُ في ساعَةٍ لا تَظُنّونَ يَأتي ابنُ الإنسان.») — الستار\",\"v\":\"سبع مرات في النهار سبحتك على أحكام عدلك.\",\"r\":\"يسبح المرنم الله سبع مرات في النهار على أحكام عدله. لكل شيء زمان، وللتسبيح زمان في كل ساعة. اختر اليوم ثلاث ساعات تتوقف فيها دقيقة للتسبيح.\",\"p\":\"يا رب، سبع مرات في النهار أسبحك. علّمني أن أعرف أزمنتي وأقدسها بحمدك. آمين.\"},{\"t\":\"لكل شيء زمان\",\"ref\":\"الجامعة ٣: ١\",\"bk\":\"الجامعة\",\"v\":\"لكل شيء زمان، ولكل أمر تحت السماوات وقت:\",\"r\":\"«لكل شيء زمان، ولكل أمر تحت السماوات وقت». هناك وقت للبكاء ووقت للضحك، وقت للحصاد ووقت للغرس. وأنا أتعلم ألا أستعجل ما لم يحن، ولا أؤجل ما حان. فلأطلب من الله أن يعرفني زمني.\",\"p\":\"يا رب، أنت سيد الأوقات. علمني أن أعيش كل زمن بحسب مشيئتك، وأن أشكرك في الفرح، وأثق بك في الحزن. آمين.\"},{\"t\":\"الخطايا أو المسيح أو الناس\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيليا: يفكر الناس إما بالخطايا أو بالمسيح أو بالناس. أزمنة اليوم تمتلئ بإحدى هذه الثلاث. راقب اليوم أين يذهب فكرك أكثر، وأعده إلى المسيح.\",\"p\":\"يا رب، اجعل فكري فيك لا في خطاياي ولا في الناس. آمين.\",\"fq\":129}]},\"11-14\":{\"th\":\"ختام الأمر كله\",\"m\":[{\"t\":\"كل طرقي أمامك\",\"ref\":\"المزمور ١١٨ — الجزء الحادي والعشرون («كُونوا مُستَعِدّينَ، لأنَّهُ في ساعَةٍ لا تَظُنّونَ يَأتي ابنُ الإنسان.») — الستار\",\"v\":\"وكل طرقي أمامك يا راج. هلليلويا.\",\"r\":\"يقول المرنم: كل طرقي أمامك. ختام الأمر كله أن نتقي الله ونحفظ وصاياه. اختم اليوم بأن تضع أمام الله كل ما فعلته، وانتظر رحمته.\",\"p\":\"يا رب، كل طرقي أمامك. اجعل ختام أمري كله أن أخافك وأحفظ وصاياك. آمين.\"},{\"t\":\"هذا هو الإنسان كله\",\"ref\":\"الجامعة ١٢: ١٣\",\"bk\":\"الجامعة\",\"v\":\"فلنسمع ختام الأمر كله: اتق الله واحفظ وصاياه، لأن هذا هو الإنسان كله.\",\"r\":\"«ختام الأمر كله: اتق الله واحفظ وصاياه، لأن هذا هو الإنسان كله». بعد كل تجارب الحكيم، يرى أن الحياة تتلخص في أمرين: مخافة الله وحفظ وصاياه. وهذا كافٍ ليعطي حياتي معنى وتوجهًا.\",\"p\":\"يا رب، علمني أن أتقيك وأحفظ وصاياك لأن هذا هو الإنسان كله. اجمع قلبي المشتت عليك، وامنحني بساطة الحكمة الحقيقية. آمين.\"},{\"t\":\"لا تثق ببرك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي القديس أنطونيوس: لا تثق ببرك ولا تندم على أمر قد عبر، وأمسك بطنك ولسانك. الختام الصالح يكون بتواضع من لا يعتمد على نفسه. اترك اليوم الندم على ماضٍ مضى، وابدأ من جديد.\",\"p\":\"يا رب، لا أثق ببري بل برحمتك. اغفر ما مضى، وأمسك لساني وجسدي في طاعتك. آمين.\",\"fq\":4}]},\"11-15\":{\"th\":\"الرب يقاتل عنكم\",\"m\":[{\"t\":\"الرب عضدني\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"أحاطوا بي احتياطا واكتنفوني، وباسم الرب قهرتهم. أحاطوا بي مثل النحل حول الشهد، والتهبوا كنار في شوك، وباسم الرب انتقمت منهم. دفعت لأسقط والرب عضدني.\",\"r\":\"يقول المرنم: أحاطوا بي مثل النحل حول الشهد، وباسم الرب قهرتهم؛ دفعت لأسقط والرب عضدني. الرب يقاتل عنا ونحن صامتون. سلّم اليوم صراعًا لا تستطيع حله بنفسك، وقل: يا رب قاتل عني.\",\"p\":\"يا رب، عضدني حين أدفع لأسقط. باسمك أقهر، وأنت تقاتل عني. آمين.\"},{\"t\":\"الرب يقاتل عنكم\",\"ref\":\"الخروج ١٤: ١٤\",\"bk\":\"الخروج\",\"v\":\"الرب يقاتل عنكم وأنتم تصمتون».\",\"r\":\"«الرب يقاتل عنكم وأنتم تصمتون». حين يضيق الأمر ولا أرى مخرجًا، أميل إلى الجدال والاضطراب. وأحيانًا يكون المطلوب أن أصمت وأثق. فالله يقاتل في المواقف التي لا أقدر عليها.\",\"p\":\"يا رب، أنت تقاتل عني. علمني أن أصمت بثقة، وأتحرك حين تأمرني، ولا أجادل في وقت الضيق. آمين.\"},{\"t\":\"الجبّ العميق\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن الإنسان أمام حرب جسدية بمن يقف أمام جب عميق، وإذا ابتعد عن الجسديات صار بعيدًا عن الجب، وإن حاول العدو أن يجره أرسل الله له العون. الابتعاد عن مواضع السقوط نصف المعركة. ابتعد اليوم عن موضع تعثر فيه.\",\"p\":\"يا رب، أبعدني عن حافة الجب. أرسل لي عونك حين يحاول العدو أن يجرني. آمين.\",\"fq\":357}]},\"11-16\":{\"th\":\"اختر الحياة\",\"m\":[{\"t\":\"من يهوى الحياة؟\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"من هو الإنسان الذي يهوى الحياة، ويحب أن يرى أياما صالحة؟\",\"r\":\"من هو الإنسان الذي يهوى الحياة ويحب أن يرى أيامًا صالحة؟ جواب الله: اختر الحياة. اختيار الحياة قرارات صغيرة يومية. اختر اليوم بوعي ما يعطي حياة: كلمة طيبة أو قراءة أو راحة.\",\"p\":\"يا رب، أريد أن أحيا وأرى أيامًا صالحة. اهدني في اختيار الحياة، وابعدني عما يميت. آمين.\"},{\"t\":\"فاختر الحياة\",\"ref\":\"التثنية ٣٠: ١٩\",\"bk\":\"التثنية\",\"v\":\"أشهد عليكم اليوم السماء والأرض. قد جعلت قدامك الحياة والموت. البركة واللعنة. فاختر الحياة لكي تحيا أنت ونسلك،\",\"r\":\"«قد جعلت قدامك الحياة والموت، البركة واللعنة، فاختر الحياة لكي تحيا أنت ونسلك». الله يدعوني إلى الاختيار، ولا يفرض. وقراراتي اليوم لا تؤثر علي وحدي بل على من بعدي. فلأختار الحياة في الأمور الصغيرة.\",\"p\":\"يا رب، أنت الحياة. أعنّي أن أختار الحياة في قراراتي اليومية، واحفظ أولادي ونسلي في طريق البركة. آمين.\"},{\"t\":\"الخطية تميت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: إذا وصل الإنسان إلى الخطية مات، وإذا وصل إلى الصلاح حيا وعمل الصلاح. الاختيار بين طريقين يتكرر كل يوم. قل اليوم نعم لصلاح واحد ولا لخطية واحدة.\",\"p\":\"يا رب، قدني إلى الصلاح الذي يحيي. أبعد عني الخطية التي تميت. آمين.\",\"fq\":402}]},\"11-17\":{\"th\":\"عيون الإيمان\",\"m\":[{\"t\":\"بعينيك تتأمل\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"وعن يمينك ربوات، وأما أنت فلا يقتربون إليك. بل بعينيك تتأمل، ومجازاة الخطاة تبصر.\",\"r\":\"يعد المزمور أنه تسقط عن يسارك ألوف وعن يمينك ربوات وأنت لا يقتربون إليك، بل بعينيك تتأمل. عيون الإيمان تبصر ما لا تراه عيون الجسد، كما رأى خادم أليشع جبلًا مملوءًا خيلًا. اطلب اليوم من الله أن يفتح عينيك على حضوره.\",\"p\":\"يا رب، افتح عيني لأرى حضورك وحمايتك. ثبّتني بعيون الإيمان، فلا أخاف مما أراه. آمين.\"},{\"t\":\"الذين معنا أكثر\",\"ref\":\"الملوك الثاني ٦: ١٦\",\"bk\":\"الملوك الثاني\",\"v\":\"فقال: «لا تخف، لأن الذين معنا أكثر من الذين معهم».\",\"r\":\"«لا تخف، لأن الذين معنا أكثر من الذين معهم». ما يخيفني أحيانًا هو ما أراه فقط. لكن هناك حقيقة روحية أكبر لا تراها العين. فلأصلِّ مع أليشع: «يا رب افتح عيني فأبصر».\",\"p\":\"يا رب، افتح عيني لأرى جيشك المحيط بي. شدد قلبي وقت الخوف، واحفظني بملائكتك الأطهار. آمين.\"},{\"t\":\"ما في الداخل\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال أحد الشيوخ للأب يوحنا الكولوفي: إبريقك مملوء سمًّا، فأجابه: لقد قلت هذا لأنك رأيت ما في الخارج فقط، ماذا كنت ستقول لو رأيت ما في الداخل أيضًا؟ عيون الإيمان تعترف بحقيقة النفس. اعترف اليوم بأعماق ضعفك لله وحده.\",\"p\":\"يا رب، أنت ترى ما في الداخل. طهّرني من الداخل واغفر لي ما لا يراه أحد. آمين.\",\"fq\":152}]},\"11-18\":{\"th\":\"أمانة في الوقت المناسب\",\"m\":[{\"t\":\"عيناي على أمناء الأرض\",\"ref\":\"المزمور ١٠٠ (١٠١) — التاسعة\",\"v\":\"عيناي على جميع أمناء الأرض لكي أجلسهم معي. السالك في الطريق بلا عيب هذا كان يخدمني.\",\"r\":\"يقول المرنم: عيناي على جميع أمناء الأرض لكي أجلسهم معي، والسالك في الطريق بلا عيب هذا كان يخدمني. الأمانة في الوقت المناسب تُعرف بالخدمة الأمينة حين يطلبها الله. اسأل نفسك اليوم: ما الأمر الذي أصبح وقته الآن؟ وافعله.\",\"p\":\"يا رب، اجعلني أمينًا في وقتي. أعطني أن أخدمك بلا عيب فتجلسني مع أمنائك. آمين.\"},{\"t\":\"لوقت مثل هذا\",\"ref\":\"أستير ٤: ١٤\",\"bk\":\"أستير\",\"v\":\"لأنك إن سكت سكوتا في هذا الوقت يكون الفرج والنجاة لليهود من مكان آخر، وأما أنت وبيت أبيك فتبيدون. ومن يعلم إن كنت لوقت مثل هذا وصلت إلى الملك؟».\",\"r\":\"«ومن يعلم إن كنت لوقت مثل هذا وصلت إلى الملك؟». ربما وضعني الله في موقعي الحالي لسبب. وقد لا أرى الغاية الآن، لكنني أسأل: ما الذي يريده مني هنا؟ والصمت أمام الحق قد يضيع فرصة أمانة.\",\"p\":\"يا رب، ضعني حيث تريد وامنحني شجاعة أمانة في الوقت المناسب. لا تدعني أصمت حين يجب أن أتكلم، واستخدمني لخير شعبك. آمين.\"},{\"t\":\"اتّضع في السلام\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيساريوس: عندما تكون في سلام وغير محارب، اتّضع أكثر، فربما بدخول فرح غريب نفتخر فنُسلَّم للمعارك. أمانة الوقت أن نحرس السلام أيضًا. تواضع اليوم في لحظة نجاح أو راحة.\",\"p\":\"يا رب، احفظني من الافتخار في السلام. علّمني أن أتضع في الراحة كما في الضيق. آمين.\",\"fq\":81}]},\"11-19\":{\"th\":\"تواضع وصلاة ورجوع\",\"m\":[{\"t\":\"وجهك يا رب ألتمس\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"استمع يا رب صوتي الذي به دعوتك. ارحمني واستجب لي فإنه لك قال قلبي: طلبت وجهك. ووجهك يا رب ألتمس.\",\"r\":\"يصرخ المرنم بصوته إلى الله ويطلب وجهه، قائلاً قلبي طلب وجهك. شرط الاستجابة تواضع وصلاة وطلب وجه ورجوع. اجلس اليوم دقائق تقول فيها: وجهك يا رب ألتمس.\",\"p\":\"استمع يا رب صوتي الذي به دعوتك. ارحمني واستجب لي، ووجهك يا رب ألتمس. آمين.\"},{\"t\":\"إن تواضع شعبي وصلوا\",\"ref\":\"أخبار الأيام الثاني ٧: ١٤\",\"bk\":\"أخبار الأيام الثاني\",\"v\":\"فإذا تواضع شعبي الذين دعي اسمي عليهم وصلوا وطلبوا وجهي، ورجعوا عن طرقهم الردية فإنني أسمع من السماء وأغفر خطيتهم وأبرئ أرضهم.\",\"r\":\"«فإذا تواضع شعبي… وصلوا وطلبوا وجهي ورجعوا عن طرقهم الردية فإنني أسمع من السماء وأغفر». أربع خطوات: تواضع، صلاة، طلب وجه الله، ورجوع عن الشر. والنتيجة سماع وغفران وشفاء. وأنا أبدأ من نفسي.\",\"p\":\"يا رب، أتواضع أمامك وأصلي وأطلب وجهك. أرجع عن طرقي الردية، فاسمع من السماء واغفر وأبرئ أرضنا وكنيستنا. آمين.\"},{\"t\":\"افحص ضميرك\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب أور: عندما يأتيك فكر التشامخ افحص ضميرك هل حفظت كل الوصايا وأحببت كل أعدائك، واعتبر نفسك عبدًا بطّالًا وخاطئًا أكثر من جميع الناس. الرجوع إلى الله يبدأ بكسر الكبرياء. افحص اليوم ضميرك ثلاث دقائق.\",\"p\":\"يا رب، اكسر كبريائي وأرجعني إليك. أعطني أن أرى نفسي عبدًا بطّالًا محتاجًا لرحمتك. آمين.\",\"fq\":562}]},\"11-20\":{\"th\":\"الذين ردوا كثيرين إلى البر\",\"m\":[{\"t\":\"أظهر عجائبه لقديسيه\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"أظهر عجائبه لقديسيه الذين في أرضه؛ وصنع فيهم كل مشيئاته.\",\"r\":\"أظهر الرب عجائبه لقديسيه الذين في أرضه وصنع فيهم كل مشيئاته. الذين يردون كثيرين إلى البر يضيئون كالكواكب، وقد صنع الله فيهم مشيئته أولًا. ارجع اليوم إلى حياتك الخاصة قبل أن تنصح أحدًا.\",\"p\":\"يا رب، اصنع فيّ مشيئتك لأكون سببًا في رجوع كثيرين إليك. ولا تدع أحدًا يتعثر بسببي. آمين.\"},{\"t\":\"الفاهمون يضيئون\",\"ref\":\"دانيال ١٢: ٣\",\"bk\":\"دانيال\",\"v\":\"والفاهمون يضيئون كضياء الجلد، والذين ردوا كثيرين إلى البر كالكواكب إلى أبد الدهور.\",\"r\":\"«والفاهمون يضيئون كضياء الجلد، والذين ردوا كثيرين إلى البر كالكواكب إلى أبد الدهور». رد النفوس إلى الله أعظم عمل. وكل خدمة مهما كانت صغيرة، إذا قادت أحدًا إلى المسيح، لها مجد أبدي.\",\"p\":\"يا رب، اجعلني أضيء بنورك وأرد كثيرين إلى البر. استخدمني في خدمة النفوس، واقبل تعبي القليل لمجد اسمك. آمين.\"},{\"t\":\"عبثًا يكون التعب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى الحبشي: إذا لم تتفق الصلاة مع السيرة عبثًا يكون التعب، فلا نعمل ما نصلّي من أجله. من يردّ كثيرين إلى البر تتفق صلاته مع سيرته. اجعل اليوم صلاتك وسلوكك في خط واحد.\",\"p\":\"يا رب، وحّد صلاتي وسيرتي. اجعل حياتي شاهدة لما أطلبه في صلاتي. آمين.\",\"fq\":264}]},\"11-21\":{\"th\":\"عيد رئيس الملائكة ميخائيل\",\"m\":[{\"t\":\"يوصي ملائكته بك\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"لأنه يوصى ملائكته بك؛ ليحفظوك في سائر طرقك. وعلى أيديهم يحملونك، لئلا تعثر بحجر رجلك.\",\"r\":\"في عيد رئيس الملائكة ميخائيل نتذكر أن الله يوصي ملائكته بنا ليحفظونا في كل طرقنا. على أيديهم يحملوننا لئلا نعثر. ارفع اليوم صلاة قصيرة إلى الملاك الحارس وإلى القديس ميخائيل.\",\"p\":\"يا رب، أوصِ ملائكتك بي ليحفظوني في سائر طرقي. بشفاعة الملاك ميخائيل احرسني ولا تعثّرني. آمين.\"},{\"t\":\"ميخائيل الرئيس العظيم\",\"ref\":\"دانيال ١٢: ١\",\"bk\":\"دانيال\",\"v\":\"«وفي ذلك الوقت يقوم ميخائيل الرئيس العظيم القائم لبني شعبك، ويكون زمان ضيق لم يكن منذ كانت أمة إلى ذلك الوقت. وفي ذلك الوقت ينجى شعبك، كل من يوجد مكتوبا في السفر.\",\"r\":\"«وفي ذلك الوقت يقوم ميخائيل الرئيس العظيم القائم لبني شعبك… ينجى شعبك، كل من يوجد مكتوبًا في السفر». في أيام الضيق لا يترك الله شعبه. وأنا أطلب شفاعة رئيس الملائكة، وأثق أن اسمي مكتوب في سفر الحياة.\",\"p\":\"يا رب، أشكرك على رئيس الملائكة ميخائيل وكل جنودك السماويين. احفظنا بشفاعتهم، واكتب أسماءنا في سفر الحياة. آمين.\"},{\"t\":\"أصوات الملائكة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب بيمن للإخوة الذين أرادوا أن يرحلوا من مكان بسبب أديرته: وهل تغادرون المكان بسبب أصوات الملائكة؟ الملائكة حاضرون حيث نصلي. ابقَ اليوم في حضرتهم، واحتمل ضجيج الصلاة بفرح.\",\"p\":\"يا رب، افتح أذني لأسمع تسبيح ملائكتك. اجعلني أحب مكان الصلاة ولا أنفر منه. آمين.\",\"fq\":428}]},\"11-22\":{\"th\":\"ملاك الرب حال حول خائفيه\",\"m\":[{\"t\":\"اسجدوا لله يا جميع ملائكته\",\"ref\":\"المزمور ٩٦ (٩٧) — التاسعة\",\"v\":\"اسجدوا لله يا جميع ملائكته.\",\"r\":\"يدعو المزمور جميع ملائكة الله أن يسجدوا له. وملاك الرب يحل حول خائفيه وينجيهم. الملائكة خدام الله وأرواح مرسلة لخدمة العتيدين أن يرثوا الخلاص. اشكر الله اليوم على ملائكته، وصلِّ بتسبيحهم: قدوس قدوس قدوس.\",\"p\":\"يا رب، لتسجد لك ملائكتك، وأسجد أنا معهم. احفظني بملاكك الحارس، وأنجني من كل شر. آمين.\"},{\"t\":\"ملاك الرب حال حول خائفيه\",\"ref\":\"المزامير ٣٤: ٧\",\"bk\":\"المزامير\",\"v\":\"ملاك الرب حال حول خائفيه، وينجيهم.\",\"r\":\"«ملاك الرب حال حول خائفيه وينجيهم». لا أرى هذا الملاك، لكن الكلمة تؤكد أنه محيط بي. والشرط هو مخافة الرب. وعندما أنام وأسير وأعمل، يحرسني ملاك، فلأشكر الله على ذلك.\",\"p\":\"يا رب، أشكرك على ملاك حراستي. احفظني وبيتي وأحبائي بحراسته، وأعطني مخافتك فلا أخاف شيئًا غيرك. آمين.\"},{\"t\":\"إرادة واحدة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب أرسانيوس: القوات السماوية وآلاف الطغمات العلوية عندها إرادة واحدة، أما البشر فبإراداتهم كثيرة. الملائكة ينفذون مشيئة الله بوحدة كاملة. اجعل اليوم إرادتك واحدة مع مشيئة الله في قرار تتردد فيه.\",\"p\":\"يا رب، وحّد إرادتي بإرادتك كما توحد الملائكة. علّمني أن أقول: لتكن مشيئتك. آمين.\",\"fq\":33}]},\"11-23\":{\"th\":\"فرح الملائكة بالتائب\",\"m\":[{\"t\":\"صرخت في حزني فاستجبت لي\",\"ref\":\"المزمور ١١٩ (١٢٠) — الغروب\",\"v\":\"إليك يا رب صرخت في حزني فاستجبت لي.\",\"r\":\"يشهد المرنم أنه صرخ في حزنه فاستجاب الرب. وحين يعود الخاطئ إلى الله يفرح الملائكة. توبتك تفرح السماء قبل أن تفرحك. ارجع اليوم إلى الله بصلاة قصيرة وتخيل فرح الملائكة بك.\",\"p\":\"يا رب، صرخت إليك في حزني فاستجبت لي. اقبل توبتي وافرح بعودتي، وليفرح ملائكتك بي. آمين.\"},{\"t\":\"فرح قدام ملائكة الله\",\"ref\":\"لوقا ١٥: ١٠\",\"bk\":\"لوقا\",\"v\":\"هكذا، أقول لكم: يكون فرح قدام ملائكة الله بخاطئ واحد يتوب.\",\"r\":\"«يكون فرح قدام ملائكة الله بخاطئ واحد يتوب». توبتي تُحدث فرحًا في السماء. ولا أحتاج أن أنتظر لأتب بعد أن أكمل. فكل خطوة رجوع تفرح الملائكة. وهذا يرفع عني الشعور بالخجل.\",\"p\":\"يا رب، أشكرك لأن السماء تفرح بتوبتي. خذ بيدي إلى الاعتراف الصادق، واجعلني سبب فرح لملائكتك بدل الحزن. آمين.\"},{\"t\":\"النوح الدائم\",\"ref\":\"\",\"v\":\"\",\"r\":\"رأى الأب بيمن امرأة تبكي بمرارة عند قبر، فقال: لو انسكبت كل مباهج هذه الدنيا لا تقدر أن ترفع النوح عن نفس هذه المسكينة، وهكذا الراهب يجب أن يقتني النوح في قلبه على الدوام. النوح الصادق على الخطية يفرح السماء. ابك اليوم بصدق على خطية واحدة، ثم ارفع شكرك.\",\"p\":\"يا رب، أعطني نوحًا صادقًا على خطاياي لا يغادر قلبي. وحوّل نوحي إلى فرح بغفرانك. آمين.\",\"fq\":326}]},\"11-24\":{\"th\":\"قدوس قدوس قدوس\",\"m\":[{\"t\":\"قدوس هو\",\"ref\":\"المزمور ٩٨ (٩٩) — التاسعة\",\"v\":\"ارفعوا الرب إلهنا واسجدوا لموطئ قدميه فإنه قدوس هو.\",\"r\":\"يدعونا المزمور أن نرفع الرب إلهنا ونسجد لموطئ قدميه لأنه قدوس. وفي السماء يقول الملائكة: قدوس قدوس قدوس. الاقتراب من القداسة يبدأ بخضوع القلب. قف اليوم دقيقة صامتًا وانحنِ في داخلك، وقل ثلاث مرات: قدوس قدوس قدوس.\",\"p\":\"يا رب القدوس، أرفعك وأسجد لك. اجعلني أقترب منك بخشوع، وقدّسني بقداستك. آمين.\"},{\"t\":\"السرافيم واقفون فوقه\",\"ref\":\"إشعياء ٦: ٢\",\"bk\":\"إشعياء\",\"v\":\"السرافيم واقفون فوقه، لكل واحد ستة أجنحة، باثنين يغطي وجهه، وباثنين يغطي رجليه، وباثنين يطير.\",\"r\":\"«باثنين يغطي وجهه، وباثنين يغطي رجليه، وباثنين يطير». حتى السرافيم تخشع أمام الله. وأنا أدخل الصلاة أحيانًا بلا خشوع. فأتعلم منهم أن أغطي وجهي بالتواضع وأطير بالطاعة. ومن يخشع يقترب أكثر.\",\"p\":\"يا قدوس يا قدوس يا قدوس، علمني الخشوع في حضرتك. طهّر شفتيّ وقلبي، واجعلني مستعدًا أن أقول: هأنذا أرسلني. آمين.\"},{\"t\":\"دون الخليقة كلها\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل أخ الأب سيسوى: أرى أن ذكر الله يبقى في داخلي، فأجابه أن المهم حقًّا أن تعاين نفسك دون الخليقة كلها، لأن هذا يقود مع التعب الجسدي إلى سبيل التواضع. من يرى قداسة الله يرى صغر نفسه. قل اليوم: أنا لا شيء أمام قداستك.\",\"p\":\"يا رب القدوس، علّمني أن أراك عظيمًا وأرى نفسي صغيرًا. وقدّسني بتواضع حقيقي. آمين.\",\"fq\":490}]},\"11-25\":{\"th\":\"بدء صوم الميلاد\",\"m\":[{\"t\":\"فلتفرح السماوات\",\"ref\":\"المزمور ٩٥ (٩٦) — التاسعة\",\"v\":\"فلتفرح السموات ولتبتهج الأرض وليعج البحر وجميع ملئه.\",\"r\":\"تفرح السماوات وتبتهج الأرض لأن الرب آتٍ. نبدأ اليوم صوم الميلاد بفرح، فنحن نصوم لنستقبل مولودًا لا لنحزن. حدد اليوم نوع صومك لهذه الأربعين: طعام أو ترفيه أو كلام، وقدمه لله بفرح.\",\"p\":\"يا رب، لتفرح السماوات وتبتهج الأرض بمجيئك. بارك صومنا واجعله استعدادًا صادقًا لاستقبالك. آمين.\"},{\"t\":\"هوذا إلهكم يأتي\",\"ref\":\"إشعياء ٣٥: ٤\",\"bk\":\"إشعياء\",\"v\":\"قولوا لخائفي القلوب: «تشددوا لا تخافوا. هوذا إلهكم. الانتقام يأتي. جزاء الله. هو يأتي ويخلصكم».\",\"r\":\"«قولوا لخائفي القلوب: تشددوا لا تخافوا. هوذا إلهكم… هو يأتي ويخلصكم». اليوم تبدأ الكنيسة صوم الميلاد، وصوتها: لا تخافوا، الرب آت. فأبدأ هذا الصوم بالرجاء لا بالثقل. وصيامي استقبال لا حرمان.\",\"p\":\"يا رب، أبدأ صوم ميلادك بالرجاء. شددني ولا تدعني أخاف، وهيئ قلبي مذودًا نقيًا لاستقبالك في الميلاد. آمين.\"},{\"t\":\"الصوم والمحبة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب سلوان لتلميذه الذي أراد أن يشرب في الطريق بعد أن أكلا قليلًا في دير: ما أكلناه كان من المحبة، أما هنا فلنحتفظ بصيامنا يا ولدي. الصوم يحفظ ولا يتصلب أمام المحبة. اجعل صومك هذه الأيام ثمرة محبة لا قسوة.\",\"p\":\"يا رب، علّمني صومًا يجمع النسك بالمحبة. احفظ أصوامي ببساطة وتواضع. آمين.\",\"fq\":509}]},\"11-26\":{\"th\":\"الموعد منذ القديم\",\"m\":[{\"t\":\"قال الرب لربي\",\"ref\":\"المزمور ١٠٩ (١١٠) — التاسعة\",\"v\":\"قال الرب لربي: اجلس عن يميني حتى أضع أعداءك تحت موطئ قدميك. عصا قوة يرسل لك الرب من صهيون وتسود في وسط أعدائك.\",\"r\":\"يعلن المزمور عن ملك يجلس عن يمين الرب ويسود في وسط أعدائه. هذا الوعد القديم صار حقيقة في المسيح. اقرأ اليوم نبوة من سفر التكوين أو العدد وتأمل كيف تحققت في الميلاد.\",\"p\":\"يا رب، أنت الملك الجالس عن يمين الآب. أشكرك لأنك أتممت وعودك القديمة في ابنك. آمين.\"},{\"t\":\"حتى يأتي شيلون\",\"ref\":\"التكوين ٤٩: ١٠\",\"bk\":\"التكوين\",\"v\":\"لا يزول قضيب من يهوذا ومشترع من بين رجليه حتى يأتي شيلون وله يكون خضوع شعوب.\",\"r\":\"«لا يزول قضيب من يهوذا… حتى يأتي شيلون وله يكون خضوع شعوب». قبل آلاف السنين وعد الله بمجيء المسيح. ووعد الله لا يتأخر ولا يسقط. وإن بدا الانتظار طويلًا، فالله يعرف الوقت المعين.\",\"p\":\"يا رب، وعدك صادق وإن طال الانتظار. ثبت إيماني بمجيئك، وأعطني صبرًا في انتظار وعودك لحياتي وكنيستك. آمين.\"},{\"t\":\"لم تكن عليه تهمة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن لأخ سأله كيف يسلك الإنسان: نرى دانيال أنه لم تكن عليه تهمة إلا في خدمة الرب إلهه. أمانة المنتظرين للوعد تُعرف بتمسكهم بخدمة الله حتى لو اتُّهموا. اثبت اليوم في خدمتك لله ولو لم يفهمك الناس.\",\"p\":\"يا رب، ثبّتني في خدمتك كدانيال. أعطني ألا يكون لي ذنب إلا في أمانتي لك. آمين.\",\"fq\":351}]},\"11-27\":{\"th\":\"الملك والابن\",\"m\":[{\"t\":\"أنت ابني\",\"ref\":\"المزمور الثاني — باكر\",\"v\":\"أنا أقمته ملكا على صهيون جبل قدسه. لأكرز بأمر الرب. الرب قال لي: أنت ابني، وأنا اليوم ولدتك.\",\"r\":\"يعلن الرب: أنا أقمته ملكًا على صهيون جبل قدسه، وأنت ابني وأنا اليوم ولدتك. هذا هو الملك الذي ننتظره في الميلاد، ملك تواضع ليخلصنا. تأمل اليوم في المسيح الملك والابن الذي دعاك أيضًا ابنًا.\",\"p\":\"يا رب، أنت الملك وابن الله. أشكرك لأنك جعلتني ابنًا لك بنعمتك. ليكن ملكك في قلبي. آمين.\"},{\"t\":\"أنت ابني أنا اليوم ولدتك\",\"ref\":\"المزامير ٢: ٧\",\"bk\":\"المزامير\",\"v\":\"إني أخبر من جهة قضاء الرب: قال لي: «أنت ابني، أنا اليوم ولدتك.\",\"r\":\"«قال لي: أنت ابني، أنا اليوم ولدتك». سر البنوة هو سر الميلاد. والابن الأزلي سيأتي في ملء الزمان. وبهذا السر صرت أنا أيضًا ابنًا بالتبني. فلأقترب من الآب بثقة الأبناء.\",\"p\":\"يا أبانا السماوي، أشكرك لأنك ولدتنا بابنك الوحيد وجعلتنا أبناء. ثبتنا في بنوتنا، وأعطنا روح الثقة والمحبة. آمين.\"},{\"t\":\"غربة وفقر وصمت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أندراوس: الراهب تناسبه هذه الثلاثة: غربة وفقر وصمت مع صبر. الملك الذي ننتظره جاء غريبًا وفقيرًا وصامتًا في المذود. اختر اليوم أن تعيش لحظة بساطة وصمت كملكك.\",\"p\":\"يا رب، أعطني أن أحب غربتك وفقرك وصمتك. ليكن لي فيك سلام الاكتفاء. آمين.\",\"fq\":78}]},\"11-28\":{\"th\":\"الرحمة والحق التقيا\",\"m\":[{\"t\":\"أرسل الله رحمته وحقه\",\"ref\":\"المزمور ٥٦ (٥٧) — السادسة\",\"v\":\"أرسل الله رحمته وحقه.\",\"r\":\"يعلن المرنم أن الله أرسل رحمته وحقه. في الميلاد التقت الرحمة والحق، والبر والسلام تلاقيا. أرسل اليوم رحمة إلى أحد: رسالة أو زيارة أو كلمة تسامح.\",\"p\":\"يا رب، أرسلت رحمتك وحقك إلينا. اجعل في قلبي رحمة تلتقي بالحق، وسلامًا يحمل البر. آمين.\"},{\"t\":\"الرحمة والحق التقيا\",\"ref\":\"المزامير ٨٥: ١٠\",\"bk\":\"المزامير\",\"v\":\"الرحمة والحق التقيا. البر والسلام تلاثما.\",\"r\":\"«الرحمة والحق التقيا. البر والسلام تلاثما». في المسيح التقت الرحمة بالحق، فلا الله يتجاهل الخطية ولا يهلك الخاطئ. وأنا أرى في الميلاد هذا اللقاء: محبة تنزل لتتحمل العدل.\",\"p\":\"يا رب، في تجسدك التقت الرحمة بالحق والبر بالسلام. علمني أن أحيا بهذا التوازن، وأن أنشر سلامك بحق ورحمة. آمين.\"},{\"t\":\"بهدوء وسكينة\",\"ref\":\"\",\"v\":\"\",\"r\":\"سُئل الأب أمون: لماذا تصعد إلى مركب خاص وأنت تحيك الخوص؟ فقال: لكي لا أجاري أفكاري، وهذا كان مثلًا لنا لنسلك طريق الرب بهدوء وسكينة. السلام يبدأ بألا نجاري كل فكر. خذ اليوم لحظة هدوء قبل الرد على فكر يستفزك.\",\"p\":\"يا رب، علّمني أن أسلك بهدوء وسكينة. لا أجاري أفكاري بل أسلمها لسلامك. آمين.\",\"fq\":63}]},\"11-29\":{\"th\":\"قومي استنيري\",\"m\":[{\"t\":\"لتشرق فينا الحواس المضيئة\",\"ref\":\"قطعة باكر (٢)\",\"v\":\"إذا ما دخل إلينا وقت الصباح أيها المسيح إلهنا النور الحقيقي، فلتشرق فينا الحواس المضيئة والأفكار النورانية، ولا تغطينا ظلمة الآلام، لكي نسبحك عقليًا مع داود قائلين: سبقت عيناي وقت السحر لأتلو في جميع أقوالك.\",\"r\":\"تصلي الكنيسة عند الصباح أن يشرق النور الحقيقي في حواسنا وأفكارنا فلا تغطينا ظلمة الآلام. قومي استنيري لأن نورك قد جاء. ابدأ اليوم بفتح نافذة وتنفس عميق وصلاة تدخل فيها نور الله إلى كل حواسك.\",\"p\":\"يا مسيح النور الحقيقي، أشرق في حواسي وأفكاري. ولا تدع ظلمة الألم تغطيني. آمين.\"},{\"t\":\"قومي استنيري\",\"ref\":\"إشعياء ٦٠: ١\",\"bk\":\"إشعياء\",\"v\":\"«قومي استنيري لأنه قد جاء نورك، ومجد الرب أشرق عليك.\",\"r\":\"«قومي استنيري لأنه قد جاء نورك، ومجد الرب أشرق عليك». النور جاء، وعلي أن أقوم من نومي الروحي. فالاستنارة ليست جهدًا مني بل قبول لنور وصل إلي. وهذا يدعوني إلى النهوض ومواجهة الفتور.\",\"p\":\"يا نور الكنيسة، أيقظني من نومي الروحي. أشرق علي وأنرني، واجعلني أعكس نورك لكل من حولي. آمين.\"},{\"t\":\"كعشر شموع\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب لوط للأب يوسف إنه يقوم بصلاته وصومه ودرسه وتأمله فماذا بقي عليه؟ فبسط الأب يوسف يديه نحو السماء فصارت أصابعه كعشر شموع من نار، وقال: إذا كنت تريد فما عليك إلا أن تكون نارًا بالكلية. النور الكامل يطلب قلبًا كاملًا. أعطِ الله اليوم شيئًا أكثر مما تعودت.\",\"p\":\"يا رب، اجعلني نارًا بالكلية في محبتك. لا أكتفي بما فعلت، بل أطلب نورك الكامل. آمين.\",\"fq\":185}]},\"11-30\":{\"th\":\"ملء الزمان\",\"m\":[{\"t\":\"كل الخليقة تهللت بمجيئك\",\"ref\":\"قطعة باكر\",\"v\":\"أيها النور الحقيقي الذي يضيء لكل إنسان آت إلى العالم: أتيت إلى العالم بمحبتك للبشر، وكل الخليقة تهللت بمجيئك. خلصت أبانا آدم من الغواية، وأعتقت أمنا حواء من طلقات الموت، وأعطيتنا روح البنوة.\",\"r\":\"جاء المسيح في ملء الزمان ليخلص آدم وحواء ويعطينا روح البنوة. كل الخليقة تهللت بمجيئه. حيّ في هذا اليوم النهاية القادمة للصوم بفرح الترقب، وقل لنفسك: إنه آتٍ.\",\"p\":\"يا نور العالم، أنت آتٍ في ملء الزمان. أعطني روح البنوة، وأدخلني في تهليل الخليقة بك. آمين.\"},{\"t\":\"لما جاء ملء الزمان\",\"ref\":\"غلاطية ٤: ٤\",\"bk\":\"غلاطية\",\"v\":\"ولكن لما جاء ملء الزمان، أرسل الله ابنه مولودا من امرأة، مولودا تحت الناموس،\",\"r\":\"«ولكن لما جاء ملء الزمان، أرسل الله ابنه مولودًا من امرأة». الله لا يتعجل ولا يتأخر. هناك وقت معين لكل عمل. وأنا أنتظر بصبر أن يأتي ملء الزمان لكل وعد في حياتي، وأثق أن توقيته أفضل.\",\"p\":\"يا رب، أنت أرسلت ابنك في ملء الزمان. علمني أن أنتظر توقيتك في حياتي، وأثق أن كل شيء يكمل في وقته الصالح. آمين.\"},{\"t\":\"الخبرة تمتحن\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: الخبرة جميلة لأنها تجعل الإنسان ممتحنًا أكثر. وملء الزمان جاء بعد أزمنة طويلة من الانتظار والخبرة. لا تستعجل اليوم، فالله يعمل في زمنه وزماننا يمتحن.\",\"p\":\"يا رب، علّمني الصبر في الانتظار. اجعل خبرات الأيام تقربني إليك. آمين.\",\"fq\":325}]},\"12-1\":{\"th\":\"زكريا وأليصابات\",\"m\":[{\"t\":\"طوبى للخائف الرب\",\"ref\":\"المزمور ١١١ (١١٢) — التاسعة\",\"v\":\"طوبى للرجل الخائف الرب ويهوى وصاياه جدا. يقوى نسله على الأرض.\",\"r\":\"من يخاف الرب ويحب وصاياه يبارك الله نسله. هكذا كان زكريا وأليصابات، بارّين أمام الله، وانتظرا طويلًا دون أن يتركا الصلاة. اخترنا اليوم وصية واحدة نتمسك بها بفرح، ولو بدا الانتظار طويلًا.\",\"p\":\"يا رب، علّمني أن أحب وصاياك وأخافك بمحبة. بارك حياتي وبيتي كما باركت بيت زكريا وأليصابات. آمين.\"},{\"t\":\"بارين أمام الله\",\"ref\":\"لوقا ١: ٦\",\"bk\":\"لوقا\",\"v\":\"وكانا كلاهما بارين أمام الله، سالكين في جميع وصايا الرب وأحكامه بلا لوم.\",\"r\":\"«وكانا كلاهما بارين أمام الله، سالكين في جميع وصايا الرب وأحكامه بلا لوم». لم يكن الطريق سهلًا، ولم يكن لهما ولد، ومع ذلك استمرا في الأمانة. وأنا أتعلم أن البر لا يتوقف على تحقق رغباتي.\",\"p\":\"يا رب، علمني أن أسلك في وصاياك بلا لوم وأنا أنتظر. ثبتني في الأمانة حين تتأخر الاستجابة، وأعطني رجاءً كرجاء زكريا وأليصابات. آمين.\"},{\"t\":\"ضمير نقي تجاه القريب\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل كاهن من النطرون الأب بمفو: كيف يمكن للإخوة أن يسلكوا؟ فأجاب: بنسك كبير وهم يحفظون ضميرهم طاهرًا نقيًا تجاه القريب. فالبر الحقيقي يظهر أولًا في علاقتنا بالناس. اسأل نفسك اليوم: هل بيني وبين أحد ما يثقل ضميري؟ وبادر بالصلح.\",\"p\":\"يا رب، طهّر ضميري تجاه كل قريب. أعطني أن أسلك بلا لوم أمامك وأمام الناس. آمين.\",\"fq\":463}]},\"12-2\":{\"th\":\"السابق للمسيح\",\"m\":[{\"t\":\"رحيم رؤوف وبار\",\"ref\":\"المزمور ١١١ (١١٢) — التاسعة\",\"v\":\"رحيم هو الرب الإله ورؤوف وبار.\",\"r\":\"الله الذي ننتظر ميلاده رحيم ورؤوف وبار. لذلك وُلد يوحنا اسمه «الله حنّان»، ليهيئ الطريق لمن جاء بنعمته. أول ما يهيئ القلب هو أن يعرف الله على حقيقته: رحيمًا. اقرأ اليوم عن رحمة الله، واحتمل بها ضعف من حولك.\",\"p\":\"يا رب الرحيم الرؤوف، هيّئ قلبي لمجيئك، وعلّمني أن أرحم كما رحمتني. آمين.\"},{\"t\":\"يمتلئ من الروح القدس\",\"ref\":\"لوقا ١: ١٥\",\"bk\":\"لوقا\",\"v\":\"لأنه يكون عظيما أمام الرب، وخمرا ومسكرا لا يشرب، ومن بطن أمه يمتلئ من الروح القدس.\",\"r\":\"«لأنه يكون عظيمًا أمام الرب… ومن بطن أمه يمتلئ من الروح القدس». العظمة الحقيقية هي عظمة أمام الرب، لا أمام الناس. وامتلاء الروح القدس هو سر قوة يوحنا. وأنا أطلب هذا الامتلاء كل يوم.\",\"p\":\"أيها الروح القدس، املأني منذ هذا الصباح. اجعلني عظيمًا أمام الرب لا أمام الناس، وكرّس حياتي لك. آمين.\"},{\"t\":\"لا أستحق ما يُقال\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يعقوب: عندما يُمتدح إنسان ينبغي أن يتأمل في خطاياه ويفكر في أنه لا يستحق ما يُقال فيه. هذه كانت روح السابق: ينبغي أن ذلك يزيد وأني أنا أنقص. عند أول مدح تسمعه اليوم، ارفعه بصمت إلى الله وقل: لك المجد.\",\"p\":\"يا رب، احفظني من الافتخار بمدح الناس. اجعلني أنقص ليزيد اسمك فيَّ. آمين.\",\"fq\":188}]},\"12-3\":{\"th\":\"الصمت والإيمان\",\"m\":[{\"t\":\"حافظًا لفمي\",\"ref\":\"المزمور ١٤٠ (١٤١) — النوم\",\"v\":\"ضع يا رب حافظا لفمي، وبابا حصينا لشفتي. ولا تمل قلبي إلى كلام الشر، فيتعلل بعلل في الخطايا مع أناس فاعلي الإثم، ولا أتفق مع مختاريهم.\",\"r\":\"طلب المرنم من الله أن يضع حافظًا لفمه وبابًا حصينًا لشفتيه. زكريا فقد نطقه بسبب عدم إيمانه، ثم عاد يتكلم بالتسبيح. اجعل لفمك اليوم حارسًا: قبل أن تتكلم، اسأل نفسك هل هذه الكلمة تبني أم تهدم؟\",\"p\":\"يا رب، ضع حافظًا لفمي، وأبعد قلبي عن كلام الشر. وليكن كلامي اليوم تسبيحًا لك. آمين.\"},{\"t\":\"كيف أعلم هذا؟\",\"ref\":\"لوقا ١: ١٨\",\"bk\":\"لوقا\",\"v\":\"فقال زكريا للملاك: «كيف أعلم هذا، لأني أنا شيخ وامرأتي متقدمة في أيامها؟»\",\"r\":\"«كيف أعلم هذا، لأني أنا شيخ وامرأتي متقدمة في أيامها؟». الواقع يضغط على إيماني، فأقيس وعد الله بإمكاناتي. وأنا أحتاج أن أنظر إلى الوعد قبل الظروف، وأن أتذكر أن لا شيء غير ممكن لدى الله.\",\"p\":\"يا رب، أؤمن فأعن عدم إيماني. لا تدع الظروف تعمي عيني عن وعودك، وقوّ إيماني حين يضعف أمام الواقع. آمين.\"},{\"t\":\"أن نؤثر الصمت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: إذا تذكّر المرء القول المكتوب «بكلامك تتبرر وبكلامك تدان» فإنه سرعان ما يؤثر الصمت. الصمت ليس هروبًا بل استعدادًا للسماع. اقضِ اليوم عشر دقائق بلا كلام لتسمع صوت الله في الأمور الصغيرة.\",\"p\":\"يا رب، علّمني أن أؤثر الصمت حين لا يفيد الكلام. وافتح فمي لتسبيحك وحده. آمين.\",\"fq\":340}]},\"12-4\":{\"th\":\"البشارة بالتجسد\",\"m\":[{\"t\":\"كرسي ملكك\",\"ref\":\"المزمور ٤٤ (٤٥) — الثالثة\",\"v\":\"كرسيك يا الله إلى دهر الدهر، قضيب الاستقامة هو قضيب ملكك.\",\"r\":\"كرسي الله إلى دهر الدهر، وقضيب ملكه قضيب استقامة. هكذا أعلن الملاك لمريم: وسيملك على بيت يعقوب إلى الأبد. الملك الذي يأتي لا يملك بالقوة بل بالاستقامة والتواضع. افتح اليوم لهذا الملك مجالًا في قرار صغير من قراراتك.\",\"p\":\"يا رب، ليملك في قلبي قضيب استقامتك. وأعطني أن أستقبل مشيئتك كما استقبلتها العذراء. آمين.\"},{\"t\":\"إلى عذراء مخطوبة\",\"ref\":\"لوقا ١: ٢٧\",\"bk\":\"لوقا\",\"v\":\"إلى عذراء مخطوبة لرجل من بيت داود اسمه يوسف. واسم العذراء مريم.\",\"r\":\"«إلى عذراء مخطوبة لرجل من بيت داود اسمه يوسف. واسم العذراء مريم». الله اختار فتاة بسيطة من بلدة صغيرة. فلا أحتقر بساطة حياتي، فهي قد تكون مكان عمل الله. وأرحب بالتواضع كطريق للنعمة.\",\"p\":\"يا رب، أشكرك على تواضعك الذي اخترت به الصغار. اجعلني أرحب بنعمتك مهما كانت حياتي بسيطة، وبارك عذراءك الطاهرة. آمين.\"},{\"t\":\"كالنفس الذي لا ينقطع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: يحتاج الإنسان إلى التواضع ومخافة الله، تمامًا كالنفَس الذي يخرج من أنفه. العذراء مريم قالت «هوذا أنا أمة الرب» وهي في كامل الاتضاع. نفّس اليوم بتواضع: كلما شعرت بالكبرياء، تنفس وقل: أنا عبدك يا رب.\",\"p\":\"يا رب، اجعل التواضع ومخافتك لي كالنفس الذي لا ينقطع. آمين.\",\"fq\":347}]},\"12-5\":{\"th\":\"ليس شيء غير ممكن\",\"m\":[{\"t\":\"يمين الرب صنعت قوة\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"يمين الرب صنعت قوة، يمين الرب رفعتني، يمين الرب صنعت قوة.\",\"r\":\"يمين الرب رفعتني، يمين الرب صنعت قوة. وقال الملاك لمريم: ليس شيء غير ممكن لدى الله. فما تظنه مستحيلًا في حياتك اليوم، اعرضه على من لا يعجزه شيء، وانتظر تدخله.\",\"p\":\"يا رب، يمينك صنعت قوة. أؤمن أنه لا يعجزك شيء، فاعمل في ما أعجز أنا عنه. آمين.\"},{\"t\":\"لا يكون لملكه نهاية\",\"ref\":\"لوقا ١: ٣٣\",\"bk\":\"لوقا\",\"v\":\"ويملك على بيت يعقوب إلى الأبد، ولا يكون لملكه نهاية».\",\"r\":\"«ويملك على بيت يعقوب إلى الأبد، ولا يكون لملكه نهاية». كل الممالك تزول، وملكه لا يزول. وأنا إذ أنتمي إلى ملكوته أتحرر من القلق على مصير هذا العالم، فالمستقبل بيد الملك الأبدي.\",\"p\":\"يا ملك الدهور، ملكك لا نهاية له. ثبتنا في ملكوتك، ولا تدع الأحداث المتغيرة تهز إيماننا، فأنت ملك السلام. آمين.\"},{\"t\":\"الإيمان بأن الله يهتم\",\"ref\":\"\",\"v\":\"\",\"r\":\"سُئل الأب أشعيا: ما هي محبة الفضة؟ فقال إنها عدم الإيمان بأن الله يهتم بك، واليأس من وعوده، ومحبة الافتخار والعظمة. من يؤمن أن الله يهتم يستريح من الخوف على الغد. قدّم اليوم همًّا ماديًّا واحدًا لله وقل له: أنت تهتم.\",\"p\":\"يا رب، أؤمن أنك تهتم بي. اشفِ ضعف إيماني بوعودك، وحررني من محبة المال. آمين.\",\"fq\":124}]},\"12-6\":{\"th\":\"زيارة مريم لأليصابات\",\"m\":[{\"t\":\"فرحت صهيون\",\"ref\":\"المزمور ٩٦ (٩٧) — التاسعة\",\"v\":\"سمعت صهيون ففرحت. وتهللت بنات يهوذا، من أجل أحكامك يا رب.\",\"r\":\"سمعت صهيون ففرحت وتهللت بنات يهوذا. هكذا حين سمعت أليصابات سلام مريم تحرك الجنين بابتهاج. الفرح معدٍ حين نحمل المسيح. اذهب اليوم لتزور أحدًا وحيدًا أو مريضًا، وليكن حضورك بشارة صغيرة.\",\"p\":\"يا رب، املأ قلبي فرحًا بك لكي أحمل فرحك لمن أزورهم. آمين.\"},{\"t\":\"أليصابات نسيبتك حبلى\",\"ref\":\"لوقا ١: ٣٦\",\"bk\":\"لوقا\",\"v\":\"وهوذا أليصابات نسيبتك هي أيضا حبلى بابن في شيخوختها، وهذا هو الشهر السادس لتلك المدعوة عاقرا،\",\"r\":\"«وهوذا أليصابات نسيبتك هي أيضًا حبلى بابن في شيخوختها». الله يشجع بعلامة قريبة. وحين أشعر بصعوبة، قد يعطيني الله علامة في حياة أحد أحبائي ليقوي إيماني. فأتعلم أن أفرح بعمل الله في غيري.\",\"p\":\"يا رب، أشكرك على علاماتك التي تشجعنا. علمني أن أفرح بعملك في غيري، وأن أنقل الفرح لمن حولي. آمين.\"},{\"t\":\"تعال متى تشاء\",\"ref\":\"\",\"v\":\"\",\"r\":\"جاء أخ إلى الأب يوحنا الكولوفي وكان يخشى أن يزعجه. فأشعل الشيخ مصابيح كثيرة من مصباح واحد دون أن يتضرر، وقال له: يمكنك أن تأتي إليّ متى تشاء دون أن تتردد. المحبة لا تنقص بالعطاء. افتح بابك اليوم لمن يحتاج إليك دون ضجر.\",\"p\":\"يا رب، اجعلني كالمصباح الذي لا ينقص نوره بالعطاء. علّمني أن أستقبل الجميع بمحبة. آمين.\",\"fq\":156}]},\"12-7\":{\"th\":\"الفرح والرحمة والوعد\",\"m\":[{\"t\":\"الرب قد ملك\",\"ref\":\"المزمور ٩٦ (٩٧) — التاسعة\",\"v\":\"الرب قد ملك فلتتهلل الأرض، ولتفرح الجزائر الكثيرة.\",\"r\":\"الرب قد ملك فلتتهلل الأرض. ملكه ليس بالسيف بل بالرحمة، وفي هذا الأسبوع نستعد لاستقبال ملك متواضع. اجعل لهذا اليوم ملكًا واحدًا: أن يملك الله على قرار واحد صغير، وفرّح بذلك.\",\"p\":\"يا رب، أنت الملك. لتتهلل أرض قلبي بملكك، ولتملك على كل أفكاري. آمين.\"},{\"t\":\"ليذكر رحمة\",\"ref\":\"لوقا ١: ٥٥\",\"bk\":\"لوقا\",\"v\":\"كما كلم آباءنا. لإبراهيم ونسله إلى الأبد».\",\"r\":\"«عضد إسرائيل فتاه ليذكر رحمة، كما كلم آباءنا. لإبراهيم ونسله إلى الأبد». مريم ترى الميلاد تحقيقًا لوعد قديم. وأنا أتعلم أن أنظر إلى حياتي في ضوء وعود الله. فهو لا ينسى ويذكر رحمته.\",\"p\":\"يا رب، أنت تذكر رحمتك وتفي بوعودك. أشكرك على أمانتك مع آبائنا ومعنا، وأعطني أن أثق بوعودك لمستقبلي. آمين.\"},{\"t\":\"الله رحيم بالشجعان\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال أخ للأب بيمن إنه حيثما حل يجد عونًا. فقال له الشيخ إن الذين يحملون السيوف في أيديهم يجدون الله رحيمًا في الوقت الحاضر، وإذا كنا شجعانًا فإنه يرحمنا أيضًا. الشجاعة الروحية أن نجاهد الخطية، لا أن نهرب منها. جاهد اليوم في أمر واحد.\",\"p\":\"يا رب، أعطني شجاعة الجهاد، ولا تتركني أستسلم. ارحمني كما ترحم المجاهدين. آمين.\",\"fq\":381}]},\"12-8\":{\"th\":\"يوسف البار\",\"m\":[{\"t\":\"أحسن إلى المستقيمين\",\"ref\":\"المزمور ١٢٤ (١٢٥) — الغروب\",\"v\":\"أحسن يا رب إلى الصالحين والى المستقيمي القلوب.\",\"r\":\"يطلب المرنم: أحسن يا رب إلى الصالحين والمستقيمي القلوب. يوسف كان بارًا ومستقيم القلب، فلم يشهّر بمريم بل أراد تخليتها سرًّا. البر الحقيقي لا يسرع إلى الحكم. إن بلغك أمر عن أحد اليوم، أمسك لسانك وصلِّ من أجله.\",\"p\":\"يا رب، أحسن إلى المستقيمين. اجعل قلبي كقلب يوسف: بارًا رحيمًا لا يسرع إلى الحكم. آمين.\"},{\"t\":\"رجلها إذ كان بارًا\",\"ref\":\"متى ١: ١٩\",\"bk\":\"متى\",\"v\":\"فيوسف رجلها إذ كان بارا، ولم يشأ أن يشهرها، أراد تخليتها سرا.\",\"r\":\"«فيوسف رجلها إذ كان بارًا، ولم يشأ أن يشهرها، أراد تخليتها سرًا». البر ممزوج بالرحمة. فهو لا يتعجل الحكم ولا يفضح. وأنا أتعلم منه أن أحفظ كرامة الناس حتى عندما أظن أنهم أخطأوا.\",\"p\":\"يا رب، علمني من يوسف البار أن أمزج البر بالرحمة. احفظ لساني من فضح الآخرين، وأعطني لطفًا يستر ولا يعير. آمين.\"},{\"t\":\"اسمك في سفر الأحياء\",\"ref\":\"\",\"v\":\"\",\"r\":\"وقف الأب بفنوتيوس يصلي من أجل خطاياه بينما كان بعض الناس يتحدثون، فظهر له ملاك يحمل سيفًا وقال إن الذين يدينون إخوتهم يهلكون بحد هذا السيف، أما هو فقد كتب اسمه في سفر الأحياء لأنه لا يدين أحدًا بل يتضع كأنه المخطئ. اتضع اليوم ولا تدن.\",\"p\":\"يا رب، احفظني من الدينونة. علّمني أن أقف أمامك كالمخطئ، فأجد اسمي مكتوبًا في سفر الحياة. آمين.\",\"fq\":473}]},\"12-9\":{\"th\":\"عمانوئيل\",\"m\":[{\"t\":\"جعلت العلي ملجأك\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"لأنك أنت يا رب رجائي. جعلت العلي ملجأك.\",\"r\":\"لأنك أنت يا رب رجائي، جعلت العلي ملجأك. اسم عمانوئيل معناه الله معنا. ليس الله بعيدًا عنا بل ملجأ قريب في كل ضيق. عندما يضطرب قلبك اليوم، قل: الله معي، وارجع إليه كملجأ.\",\"p\":\"يا رب عمانوئيل، أنت معي. اجعل فيك ملجأي ورجائي في كل ضيق. آمين.\"},{\"t\":\"الله معنا\",\"ref\":\"متى ١: ٢٣\",\"bk\":\"متى\",\"v\":\"«هوذا العذراء تحبل وتلد ابنا، ويدعون اسمه عمانوئيل» الذي تفسيره: الله معنا.\",\"r\":\"«هوذا العذراء تحبل وتلد ابنًا، ويدعون اسمه عمانوئيل، الذي تفسيره: الله معنا». أعظم عزاء أن الله معنا في الفرح والضيق. وأنا أبدأ يومي بهذه الحقيقة: لست وحدي، لأنه معي.\",\"p\":\"يا عمانوئيل، أنت الله معنا. كن معي في كل لحظة، وأعطني وعيًا بحضورك في الفرح والضيق، فلا أخاف شيئًا. آمين.\"},{\"t\":\"ذكر الله الدائم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا الكولوفي: السجن هو أن تقيم في قلايتك وتذكر الله على الدوام، وهذا هو معنى الآية «كنت محبوسًا فأتيتم إليّ». الإقامة مع الله ليست سجنًا بل حرية. اختر اليوم ساعة تجلس فيها وتذكر الله بلا انشغال.\",\"p\":\"يا رب عمانوئيل، علّمني أن أذكرك على الدوام. اجعل قلبي قلاية تسكن فيها. آمين.\",\"fq\":161}]},\"12-10\":{\"th\":\"النور الحقيقي\",\"m\":[{\"t\":\"أخبرت السموات بعدله\",\"ref\":\"المزمور ٩٦ (٩٧) — التاسعة\",\"v\":\"أخبرت السموات بعدله؛ وعاينت جميع الشعوب مجده.\",\"r\":\"أخبرت السموات بعدله وعاينت جميع الشعوب مجده. النور الحقيقي الذي يضيء لكل إنسان يتجلى في الميلاد لكل الشعوب. لا يخص أحدًا دون غيره. تأمل اليوم في أن المسيح جاء لك أنت، ولمن تبغضه أيضًا.\",\"p\":\"يا نور العالم، أضئ لكل إنسان، وأضئ لي أنا. وليعاين الجميع مجدك. آمين.\"},{\"t\":\"كل شيء به كان\",\"ref\":\"يوحنا ١: ٣\",\"bk\":\"يوحنا\",\"v\":\"كل شيء به كان، وبغيره لم يكن شيء مما كان.\",\"r\":\"«كل شيء به كان، وبغيره لم يكن شيء مما كان». الخالق هو المخلص. وكل جمال في الكون يشهد له. وأنا أنظر اليوم إلى الخليقة بعين شكر، لأنني أرى فيها يد المسيح.\",\"p\":\"يا خالق الكون، كل شيء بك كان. أشكرك على جمال خليقتك، وعلمني أن أحفظها وأحمدك عليها، وأن أراك في كل ما صنعت. آمين.\"},{\"t\":\"شمعة في الريح\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل الإخوة الأب إسحق: لماذا تهرب من الإخوة بعد الصلاة؟ فأجاب: لو أمسك أحد شمعة مضاءة وأطال وقوفه في الريح تنطفئ، وهكذا عقلنا يظلم إذا مشينا خارج قلالينا بعد أن استنرنا من التقدمة المقدسة. احفظ نور القدسات بعد القداس بصمت وهدوء.\",\"p\":\"يا رب، احفظ نور القدسات في قلبي، ولا تدع ريح العالم تطفئه. آمين.\",\"fq\":207}]},\"12-11\":{\"th\":\"الطريق إلى بيت لحم\",\"m\":[{\"t\":\"لندخل إلى مساكنه\",\"ref\":\"المزمور ١٣١ — النوم\",\"v\":\"ها قد سمعنا به في افراته ووجدناه في موضع الغابة. فلندخل إلى مساكنه ونسجد في الموضع الذي فيه استقرت قدماه.\",\"r\":\"سمعنا به في أفراته ووجدناه في موضع الغابة، فلندخل إلى مساكنه ونسجد. أفراتة هي بيت لحم، حيث وُلد الرب. ذهب يوسف ومريم إليها بطاعة وتعب. افتح لنفسك طريقًا إلى بيت لحم اليوم بقراءة صغيرة من إنجيل لوقا.\",\"p\":\"يا رب، اجعلني أدخل إلى مساكنك وأسجد حيث استقرت قدماك. آمين.\"},{\"t\":\"قيصر يأمر والله يدبّر\",\"ref\":\"لوقا ٢: ١\",\"bk\":\"لوقا\",\"v\":\"وفي تلك الأيام صدر أمر من أوغسطس قيصر بأن يكتتب كل المسكونة.\",\"r\":\"«وفي تلك الأيام صدر أمر من أوغسطس قيصر بأن يكتتب كل المسكونة». ظن القيصر أنه يعدّ رعاياه، وكان الله يعدّ مكان ميلاد ابنه. وأنا أتضايق أحيانًا من ظروف خارجة عن إرادتي. اليوم أتعلم أن يد الله تعمل خلف الأحداث، وأن ما يزعجني قد يكون جزءًا من خطة أكبر.\",\"p\":\"يا رب، أنت ضابط الكل ومدبّر الأحداث. علمني أن أثق في تدبيرك حين تتغير خطتي، وأن أرى يدك خلف كل ظرف، وأن أسلّم لك يومي بقلب مطمئن. آمين.\"},{\"t\":\"لباس يلتقطه أحد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بمفو: يجب أن يرتدي الراهب لباسًا بحيث إذا رُمي خارج القلاية ثلاثة أيام لا يلتقطه أحد. الميلاد جاء في بساطة وفقر، في مذود وقماط. تخلَّ اليوم عن شيء كمالي في حياتك أو أعطه لمن يحتاجه.\",\"p\":\"يا رب، علّمني أن أحب بساطتك. ولا يتعلق قلبي بما يزول. آمين.\",\"fq\":459}]},\"12-12\":{\"th\":\"بشارة الرعاة\",\"m\":[{\"t\":\"هللوا لله\",\"ref\":\"المزمور ٤٦ (٤٧) — الثالثة\",\"v\":\"يا جميع الأمم صفقوا بأيديكم، هللوا لله بصوت الابتهاج.\",\"r\":\"يدعو المرنم كل الأمم أن يصفقوا ويهللوا بصوت الابتهاج. وكان أول من هلل الرعاة البسطاء، سمعوا الخبر في الحقل ففرحوا. الفرح الكامل لا يحتاج إلى مكانة. ابحث اليوم عن سبب بسيط للتهليل، وقل شكرًا لله.\",\"p\":\"يا رب، أهلل لك بصوت الابتهاج. ملأتني فرحًا كالرعاة البسطاء. آمين.\"},{\"t\":\"ظهور الملاك للرعاة\",\"ref\":\"لوقا ٢: ٨–٩\",\"bk\":\"لوقا\",\"v\":\"وكان في تلك الكورة رعاة متبدين يحرسون حراسات الليل على رعيتهم، وإذا ملاك الرب وقف بهم، ومجد الرب أضاء حولهم، فخافوا خوفا عظيما.\",\"r\":\"«وكان في تلك الكورة رعاة متبدين يحرسون حراسات الليل». أول من سمع بشارة الميلاد كانوا بسطاء يعملون بأمانة في الظلام. لا يتجاهل الله من يخدم بصمت. وربما يعلن لي حضوره وأنا في عملي العادي المتعب، فأحتاج أن أكون ساهرًا وأمينًا.\",\"p\":\"يا رب، أشكرك لأنك تعلن ذاتك للبسطاء الأمناء. اجعلني أمينًا في عملي كأنني أسهر على رعيتك، وأرني مجدك في أيامي العادية. آمين.\"},{\"t\":\"الأسد غير المنظور\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن داود لما عارك الأسد أمسك به من رقبته وقتله في الحال. ونحن إذا أمسكنا بحلقنا وبطننا نغلب بالله الأسد غير المنظور. الراعي الأمين يحرس نفسه أولًا. ضبط الشهوة يبدأ بأمر صغير، فاختر اليوم أن تضبط أمرًا واحدًا.\",\"p\":\"يا رب، علّمني أن أحرس نفسي كالراعي الأمين. واجعل نعمتك تقويني. آمين.\",\"fq\":447}]},\"12-13\":{\"th\":\"الفرح بالمولود\",\"m\":[{\"t\":\"هللوا أمام الرب الملك\",\"ref\":\"المزمور ٩٧ (٩٨) — التاسعة\",\"v\":\"هللوا أمام الرب الملك. فليعج البحر وكل ملئه: المسكونة وكل الساكنين فيها.\",\"r\":\"هللوا أمام الرب الملك، فليعج البحر وكل ما فيه. الخليقة كلها تفرح بالميلاد، فلا يليق أن يصمت الإنسان. عبّر اليوم لأحد عن فرحك بالرب بكلمة صادقة قصيرة.\",\"p\":\"يا رب، لتهلل خليقتك كلها أمامك. وليكن لساني أول المهللين. آمين.\"},{\"t\":\"وجدوا الطفل مضجعًا\",\"ref\":\"لوقا ٢: ١٦–١٧\",\"bk\":\"لوقا\",\"v\":\"فجاءوا مسرعين، ووجدوا مريم ويوسف والطفل مضجعا في المذود. فلما رأوه أخبروا بالكلام الذي قيل لهم عن هذا الصبي.\",\"r\":\"«فجاءوا مسرعين، ووجدوا مريم ويوسف والطفل مضجعًا في المذود». حين يسعى الإنسان بإخلاص يجد المسيح. لقد وجدوا الأمر كما قيل لهم، فازداد إيمانهم وصاروا يشهدون. أريد أن أكون مثلهم: أجد المسيح في الصلاة والإنجيل ثم أخبر الآخرين بفرحي.\",\"p\":\"يا رب، أشكرك لأنك تُظهر نفسك لمن يطلبك. أعطني أن أجدك كل يوم وأن أتحدث عنك بفرح وبساطة لكل من حولي. آمين.\"},{\"t\":\"الكلام عن الله والصمت لأجله\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل أخ الأب بيمن: ما الأفضل، الكلام أم الصمت؟ فقال: إن من يتحدث عن الله فحسنًا يفعل، ومن يصمت حبًّا بالله يماثله. المهم الدافع: أن يكون للمحبة. أخبر اليوم أحدًا عن الله، أو اصمت لأجله، وكن في الحالين لله.\",\"p\":\"يا رب، اجعل كلامي وصمتي لك. ولتكن المحبة دافعي. آمين.\",\"fq\":422}]},\"12-14\":{\"th\":\"المجوس يسجدون\",\"m\":[{\"t\":\"كل الأمم يسجدون\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"كل الأمم الذين خلقتهم يأتون ويسجدون أمامك يا رب، ويمجدون اسمك. لأنك أنت عظيم وصانع العجائب، أنت وحدك الإله العظيم.\",\"r\":\"كل الأمم التي خلقتها يأتون ويسجدون أمامك ويمجدون اسمك، وأنت وحدك الإله العظيم. بدأ السجود يتحقق حين جاء المجوس من بلاد بعيدة بالهدايا. اسجد اليوم في قلبك، وقدم هدية: وقتًا مع الله.\",\"p\":\"يا رب، أنت وحدك الإله العظيم. أسجد لك وأقدم لك قلبي هدية. آمين.\"},{\"t\":\"أين هو المولود؟\",\"ref\":\"متى ٢: ١–٢\",\"bk\":\"متى\",\"v\":\"ولما ولد يسوع في بيت لحم اليهودية، في أيام هيرودس الملك، إذا مجوس من المشرق قد جاءوا إلى أورشليم قائلين: «أين هو المولود ملك اليهود؟ فإننا رأينا نجمه في المشرق وأتينا لنسجد له».\",\"r\":\"«أين هو المولود ملك اليهود؟ فإننا رأينا نجمه في المشرق وأتينا لنسجد له». قطعوا مسافات طويلة بحثًا عن الحق. أما أنا فأحيانًا لا أتحرك خطوة لأقترب من الله. أطلب اليوم قلبًا يبحث عن المسيح بشوق حقيقي ولا يكتفي بما هو قريب وسهل.\",\"p\":\"يا رب، أعطني شوق المجوس لأطلبك بكل قلبي. اجتذبني إليك بكل وسيلة، واجعل رحلتي نحوك أولوية حياتي. آمين.\"},{\"t\":\"اهرب من الناس\",\"ref\":\"\",\"v\":\"\",\"r\":\"كان الأب أرسانيوس في البلاط الملكي يصلي: يا رب عرّفني كيف أخلص. فجاءه صوت: اهرب من الناس تخلص. ترك قصر الملك وسلك طريقًا لم يتوقعه أحد. كذلك رجع المجوس في طريق أخرى. اترك اليوم لحظة ضوضاء لتخلو بالله.\",\"p\":\"يا رب، عرّفني كيف أخلص. وأعطني شجاعة الاعتزال حين تدعوني. آمين.\",\"fq\":23}]},\"12-15\":{\"th\":\"حفظ الله وطاعة الابن\",\"m\":[{\"t\":\"تحت جناحيه تعتصم\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"لأنه ينجيك من فخ الصياد. ومن كلمة مقلقة. في وسط منكبيه يظللك، وتحت جناحيه تعتصم، عدله يحيط بك كالسلاح.\",\"r\":\"ينجيك الله من فخ الصياد ومن كلمة مقلقة، وتحت جناحيه تعتصم. هكذا حفظ الله الطفل يسوع في الهروب إلى مصر. نحن لا نعرف الطريق دائمًا، لكن الله يعرف. سلّم اليوم موضع قلق واحد لجناحيه.\",\"p\":\"يا رب، احفظني تحت جناحيك. وإذا اضطررت للهروب فكن أنت طريقي. آمين.\"},{\"t\":\"قم وخذ الصبي وأمه\",\"ref\":\"متى ٢: ١٣\",\"bk\":\"متى\",\"v\":\"وبعدما انصرفوا، إذا ملاك الرب قد ظهر ليوسف في حلم قائلا: «قم وخذ الصبي وأمه واهرب إلى مصر، وكن هناك حتى أقول لك. لأن هيرودس مزمع أن يطلب الصبي ليهلكه».\",\"r\":\"«قم وخذ الصبي وأمه واهرب إلى مصر». لم يناقش يوسف الأمر ولم يؤجل. هو يحمي الابن وأمه بطاعة صامتة. أنظر اليوم إلى حياتي: هل أطيع وصايا الله حتى لو لم أفهم كل التفاصيل؟ طاعة يوسف جعلته أداة لحفظ الله لابنه.\",\"p\":\"يا رب، احفظني كما حفظت عائلتك المقدسة في مصر. امنحني طاعة يوسف وإيمانه، وبارك أرضنا وشعبنا بنعمة حضورك. آمين.\"},{\"t\":\"خير لي أن أهرب\",\"ref\":\"\",\"v\":\"\",\"r\":\"لما هرب الأب نيسثروس من تنين رآه في البرية، قال له أخ: وأنت أيضًا تخاف يا أبت؟ فقال: لا أخاف، لكن خير لي أن أهرب، وإلا فلن يمكنني أن أهرب من روح المجد الفارغ. أحيانًا الحكمة في الابتعاد. ابتعد اليوم عن موقف يجرحك.\",\"p\":\"يا رب، علّمني متى أهرب ومتى أثبت. واحفظني من المجد الفارغ. آمين.\",\"fq\":297}]},\"12-16\":{\"th\":\"الاسم والانتظار\",\"m\":[{\"t\":\"وأريه خلاصي\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"ومن طول الأيام أشبعه. وأريه خلاصي.\",\"r\":\"ومن طول الأيام أشبعه وأريه خلاصي. انتظر سمعان الشيخ سنين طويلة، فرأى الخلاص بعينيه. الانتظار لله ليس ضياعًا للوقت. ماذا تنتظر من الله اليوم؟ قل له: أنا منتظر، وأريد أن أرى خلاصك.\",\"p\":\"يا رب، علّمني الصبر في الانتظار. أرني خلاصك كما أريته لسمعان. آمين.\"},{\"t\":\"سُمي يسوع\",\"ref\":\"لوقا ٢: ٢١\",\"bk\":\"لوقا\",\"v\":\"ولما تمت ثمانية أيام ليختنوا الصبي سمي يسوع، كما تسمى من الملاك قبل أن حبل به في البطن.\",\"r\":\"«ولما تمت ثمانية أيام ليختنوا الصبي سمي يسوع». اسمه يعني «يهوه يخلص». لهذا الاسم قوة وعزاء. حين أخاف أو أتعب أستطيع أن أنطق به، فهو يذكّرني بأن لي مخلصًا قريبًا. أريد أن يكون اسم يسوع على شفتي وفي قلبي اليوم.\",\"p\":\"يا يسوع، يا اسمًا حلوًا يعزي القلوب. ليكن اسمك على شفتي وفي قلبي، وخلصني من خطاياي ومخاوفي. لك المجد إلى الأبد. آمين.\"},{\"t\":\"أربع عشرة سنة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أمون: أمضيت أربع عشرة سنة في الإسقيط متضرعًا إلى الله ليل نهار أن يمنحني القوة لأتغلب على الغضب. لم يمل ولم يكل. الثبات في الطلبة يثمر. اختر اليوم عادة واحدة تتعب منها، وصلِّ من أجلها بإصرار.\",\"p\":\"يا رب، أعطني صبرًا في الصلاة. ولا أمل حتى أرى عمل نعمتك فيَّ. آمين.\",\"fq\":61}]},\"12-17\":{\"th\":\"لماذا تجسد؟\",\"m\":[{\"t\":\"قطعت قيودي\",\"ref\":\"المزمور ١١٥ — التاسعة\",\"v\":\"يا رب أنا عبدك. أنا عبدك وابن أمتك. قطعت قيودي.\",\"r\":\"يا رب أنا عبدك وابن أمتك، قطعت قيودي. جاء المسيح ليحرر من الخوف من الموت الذين كانوا طوال الحياة تحت العبودية. قد ربطتك عادة أو خوف؟ قل له اليوم باسمه: اقطع قيدي.\",\"p\":\"يا رب، أنا عبدك. اقطع قيودي، وحررني من كل عبودية. آمين.\"},{\"t\":\"ليبيد الموت\",\"ref\":\"العبرانيين ٢: ١٤–١٥\",\"bk\":\"العبرانيين\",\"v\":\"فإذ قد تشارك الأولاد في اللحم والدم اشترك هو أيضا كذلك فيهما، لكي يبيد بالموت ذاك الذي له سلطان الموت، أي إبليس، ويعتق أولئك الذين- خوفا من الموت- كانوا جميعا كل حياتهم تحت العبودية.\",\"r\":\"«فإذ قد تشارك الأولاد في اللحم والدم اشترك هو أيضًا كذلك فيهما، لكي يبيد بالموت ذاك الذي له سلطان الموت». أخاف أحيانًا من المرض والفقد والنهاية. لكن المسيح دخل الموت وكسر شوكته. فلست عبدًا للخوف، لأن لي مخلصًا غلب الموت وفتح لي باب الحياة.\",\"p\":\"يا رب، أنت الذي غلبت الموت بموتك. حرّرني من كل خوف يستعبدني، وثبّت رجائي في القيامة والحياة الأبدية معك. آمين.\"},{\"t\":\"ما قوة الخطية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يسأل الأب إيليا: ما قوة الخطيئة عندما توجد التوبة؟ كذلك ما نفع المحبة عندما يظهر الكبرياء؟ التوبة أقوى من السقوط، والكبرياء يفسد الفضيلة. لا تيأس اليوم من سقطة، وابدأ بتوبة صغيرة، ولا تتكبر بفضيلة.\",\"p\":\"يا رب، أعطني توبة تغلب خطيتي، وتواضعًا يحفظ فضائلي. آمين.\",\"fq\":128}]},\"12-18\":{\"th\":\"ظهور النعمة\",\"m\":[{\"t\":\"اعترفوا للرب\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"اعترفوا للرب لأنه صالح وأن إلى الأبد رحمته.\",\"r\":\"اعترفوا للرب لأنه صالح وأن إلى الأبد رحمته. النعمة المخلصة ظهرت للجميع، وهي عطية لا نستحقها، والجواب عليها هو الشكر. اكتب اليوم ثلاث نعم تتعامل معها كأنها حق لك، واشكر عليها.\",\"p\":\"يا رب، أعترف لك لأنك صالح. أشكرك على نعمتك التي ظهرت لنا. آمين.\"},{\"t\":\"نعمة الله المخلصة\",\"ref\":\"تيطس ٢: ١١–١٢\",\"bk\":\"تيطس\",\"v\":\"لأنه قد ظهرت نعمة الله المخلصة، لجميع الناس، معلمة إيانا أن ننكر الفجور والشهوات العالمية، ونعيش بالتعقل والبر والتقوى في العالم الحاضر،\",\"r\":\"«لأنه قد ظهرت نعمة الله المخلصة لجميع الناس». النعمة ظهرت في شخص المسيح. وهي لا تتركني كما أنا، بل تعلمني أن أنكر الشر وأعيش بتعقل وبر وتقوى. أشكر الله على نعمته، وأطلب أن تقودني لحياة جديدة هذا اليوم.\",\"p\":\"أشكرك يا رب على نعمتك المخلصة. علمني أن أنكر كل شر، وأن أعيش بتعقل وبر وتقوى في هذا العالم، منتظرًا مجيئك المبارك. آمين.\"},{\"t\":\"الفضيلة المفقودة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب بتنهد: كل الفضائل دخلت إلى هذا البيت ما عدا واحدة، بدونها بالجهد يصمد الإنسان. وسألوه: وما هي؟ فأجاب: أن يلوم الإنسان نفسه. من يلوم نفسه يقبل النعمة. اليوم، قبل أن تلوم أحدًا، تأمل ما نصيبك أنت من الخطأ.\",\"p\":\"يا رب، علّمني أن ألوم نفسي لا غيري. واملأ قلبي بنعمتك. آمين.\",\"fq\":411}]},\"12-19\":{\"th\":\"الطفل الذي ينمو\",\"m\":[{\"t\":\"مذابحك يا رب\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"لأن العصفور وجد له بيتا، واليمامة عشا لتضع فيه أفراخها. مذابحك يا رب اله القوات، ملكي وإلهي.\",\"r\":\"العصفور وجد بيتًا، واليمامة عشًّا، ومذابحك يا رب ملكي وإلهي. وجد الطفل يسوع بيته في هيكل أبيه، وقال: ينبغي أن أكون فيما لأبي. هل لك مكان مع الله تشعر فيه بالبيت؟ اجعل لك اليوم لحظة في الكنيسة أو في ركن صلاة.\",\"p\":\"يا رب، مذبحك بيتي وراحتي. اجعلني أعشق بيتك وأسكن فيه كل أيام حياتي. آمين.\"},{\"t\":\"ينمو ويتقوى بالروح\",\"ref\":\"لوقا ٢: ٤٠\",\"bk\":\"لوقا\",\"v\":\"وكان الصبي ينمو ويتقوى بالروح، ممتلئا حكمة، وكانت نعمة الله عليه.\",\"r\":\"«وكان الصبي ينمو ويتقوى بالروح، ممتلئًا حكمة، وكانت نعمة الله عليه». حتى المسيح في ناسوته مرّ بمراحل النمو. فلا أتعجل ثمرة روحية سريعة ولا أيأس من بطء تقدمي. المهم أن أنمو يومًا بعد يوم في الصلاة والحكمة والنعمة.\",\"p\":\"يا رب، كما نما الصبي يسوع في الحكمة والنعمة، نمِّني أنا أيضًا. علمني الصبر في النمو، وبارك أسرتي لتكون بيتًا تسكنه نعمتك. آمين.\"},{\"t\":\"لا تسبق أحدًا بالكلام\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل الأب أفربيوس في بداية حياته ناسكًا: قل لي كلمة، كيف أخلص؟ فأجابه: إذا أردت أن تخلص لازم عدم الكلام، ولا تسبق أحدًا إليه، ولا تتكلم قبل أن يسألوك. وهكذا كان يسوع بين المعلمين: يسمع ويسأل. اسمع اليوم أكثر مما تتكلم.\",\"p\":\"يا رب، علّمني أن أسمع قبل أن أتكلم. ولتكن كلماتي قليلة ونافعة. آمين.\",\"fq\":107}]},\"12-20\":{\"th\":\"السهر في كيهك\",\"m\":[{\"t\":\"يا رب إليك صرخت\",\"ref\":\"المزمور ١٤٠ (١٤١) — النوم\",\"v\":\"يا رب إليك صرخت فاستمع لي. أنصت إلى صوت تضرعي. إذا ما صرخت إليك.\",\"r\":\"يا رب إليك صرخت فاستمع لي، أنصت إلى صوت تضرعي إذا صرخت إليك. شهر كيهك شهر السهر والتسبيح، ننتظر فيه مجيء الرب. جرّب اليوم أن تصلي صلاة قصيرة في وقت لم تعتد الصلاة فيه.\",\"p\":\"يا رب، إليك صرخت فاستمع لي. اجعل سهري صلاة، وصلاتي سهرًا. آمين.\"},{\"t\":\"الواقفون بالليل\",\"ref\":\"المزامير ١٣٤: ١–٢\",\"bk\":\"المزامير\",\"v\":\"هوذا باركوا الرب يا جميع عبيد الرب، الواقفين في بيت الرب بالليالي. ارفعوا أيديكم نحو القدس، وباركوا الرب.\",\"r\":\"«هوذا باركوا الرب يا جميع عبيد الرب، الواقفين في بيت الرب بالليالي». تقف الكنيسة في شهر كيهك لتسبّح في الليل قبل الفجر. حتى لو لم أستطع الذهاب، أخصص دقائق في الليل للتسبيح، فأرفع يدي وقلبي وأبارك الرب.\",\"p\":\"يا رب، أبارِكك في ليالي حياتي كلها. علمني أن أسهر معك، وارفع يدي وقلبي نحوك، واقبل تسبيحي مع الكنيسة المصلية في كل مكان. آمين.\"},{\"t\":\"أتعب الفضائل\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل الإخوة القديس أغاثون: ما هي الفضيلة التي تتطلب تعبًا أكثر من سواها؟ فقال: لا يوجد تعب كتعب الصلاة إلى الله، لأن الأعداء يسعون لإيقافه، ولأن الصلاة تحتاج إلى جهاد يدوم حتى النسمة الأخيرة. لا تتوقف اليوم عن صلاتك حين تتعب.\",\"p\":\"يا رب، قوّني في جهاد الصلاة. ولا تدعني أتوقف حتى النسمة الأخيرة. آمين.\",\"fq\":50}]},\"12-21\":{\"th\":\"السهر والصلاة\",\"m\":[{\"t\":\"أمال أذنه إلي\",\"ref\":\"المزمور ١١٤ — التاسعة\",\"v\":\"أحببت أن يسمع الرب صوت تضرعي. لأنه أمال أذنه إلي فأدعوه كل أيامي.\",\"r\":\"أحببت أن يسمع الرب صوت تضرعي، لأنه أمال أذنه إلي فأدعوه كل أيامي. الله ينحني ليسمعنا. هل ننحني نحن لنسمعه؟ اقضِ اليوم خمس دقائق تتكلم فيها مع الله بكلماتك أنت، ثم اصمت لتسمع.\",\"p\":\"يا رب، لقد أملت أذنك إليّ. أدعوك كل أيامي، فلا تغب عني. آمين.\"},{\"t\":\"أقوم في منتصف الليل\",\"ref\":\"المزامير ١١٩: ٦٢\",\"bk\":\"المزامير\",\"v\":\"في منتصف الليل أقوم لأحمدك على أحكام برك.\",\"r\":\"«في منتصف الليل أقوم لأحمدك على أحكام برك». حين يصمت العالم يصير القلب أقدر على الإصغاء. لا أنتظر أن أمتلك وقتًا طويلًا للصلاة، بل أقتطع لحظات من الليل أو الفجر أقول فيها لله شكرًا وحمدًا. أطلب اليوم قلبًا يسبقه الشوق إلى لقاء الله.\",\"p\":\"يا رب، أحمدك على أحكام برك. أيقظ قلبي لتسبيحك في هدوء الليل، وامنحني شوقًا حقيقيًا للقائك قبل كل شيء آخر. آمين.\"},{\"t\":\"السهر يذيب الجسد\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب ثيوذوتس: إن حاجة الخبز تذيب جسد الراهب. وقال أب آخر: لكن السهر يذيب الجسد أكثر. السهر الروحي يهز الجسد والنفس معًا. في كيهك، اسهر قليلًا في الصلاة هذه الليلة، ولو بتسبحة واحدة.\",\"p\":\"يا رب، أعطني قوة السهر لأصلي. واجعل سهري ثمرًا بعد التعب. آمين.\",\"fq\":143}]},\"12-22\":{\"th\":\"استيقظ أيها النائم\",\"m\":[{\"t\":\"ليبتهج بك الملتمسون\",\"ref\":\"المزمور التاسع والستون — باكر\",\"v\":\"وليبتهج ويفرح بك جميع الذين يلتمسونك. وليقل في كل حين محبو خلاصك: فليتعظم الرب.\",\"r\":\"ليبتهج ويفرح بك جميع الذين يلتمسونك، وليقل في كل حين محبو خلاصك: فليتعظم الرب. التمس الرب اليوم لا في أحداث كبيرة بل في تفاصيل بسيطة. وقل في كل حين: فليتعظم الرب.\",\"p\":\"يا رب، لتفرح بك نفسي وأنا أطلبك. فليتعظم اسمك في كل حين. آمين.\"},{\"t\":\"فيضيء لك المسيح\",\"ref\":\"أفسس ٥: ١٤\",\"bk\":\"أفسس\",\"v\":\"لذلك يقول: «استيقظ أيها النائم وقم من الأموات فيضيء لك المسيح».\",\"r\":\"«استيقظ أيها النائم وقم من الأموات فيضيء لك المسيح». أحيانًا أنام روحيًا وأنا أتحرك، فأعيش بلا انتباه لمحبة الله. هذه الآية تدعوني إلى استيقاظ حقيقي: أن أقوم من عادات الموت، فيضيء لي المسيح طريقي. اليوم أطلب نعمة اليقظة.\",\"p\":\"يا نور العالم، أيقظني من كل غفلة ونوم روحي. أضئ لي طريقي، وأقمني من الموت إلى الحياة، لأعيش اليوم في نورك. آمين.\"},{\"t\":\"الصاحي ينهض للصلاة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ثيوذورس: يأتي الفكر فيزعجني ويشغلني ويعيقني عن الفضيلة. أما الرجل الصاحي فينهض للصلاة عندما يهاجمه الفكر. استيقظ من الغفلة الروحية وقم عند أول فكر مزعج وصلِّ.\",\"p\":\"يا رب، أيقظني من غفلتي. وعند كل فكر مزعج اجعلني أنهض للصلاة. آمين.\",\"fq\":142}]},\"12-23\":{\"th\":\"المشرق من العلاء\",\"m\":[{\"t\":\"أضاءت بروقه\",\"ref\":\"المزمور ٩٦ (٩٧) — التاسعة\",\"v\":\"أضاءت بروقه المسكونة.\",\"r\":\"أضاءت بروقه المسكونة. جاء الإله المتجسد كنور في الظلمة، فأضاء لجالسين في ظلال الموت. في هذه الأيام الأخيرة قبل العيد، أضئ ركنًا مظلمًا في بيتك أو قلبك بعمل محبة.\",\"p\":\"يا مشرق من العلاء، أضئ حياتي. وليضئ نورك من خلالي لمن حولي. آمين.\"},{\"t\":\"افتقدنا المشرق\",\"ref\":\"لوقا ١: ٧٨–٧٩\",\"bk\":\"لوقا\",\"v\":\"بأحشاء رحمة إلهنا التي بها افتقدنا المشرق من العلاء. ليضيء على الجالسين في الظلمة وظلال الموت، لكي يهدي أقدامنا في طريق السلام».\",\"r\":\"«بأحشاء رحمة إلهنا التي بها افتقدنا المشرق من العلاء». لم أذهب أنا إلى النور، بل جاء النور إليّ. الله افتقدني برحمته وأنا في ظلمتي. أشكره اليوم على هذه الزيارة الإلهية، وأطلب أن يهدي خطواتي إلى طريق السلام في بيتي وعملي.\",\"p\":\"يا مشرق من العلاء، أشكرك لأنك افتقدتني برحمتك. أضئ ظلمات قلبي، واهدِ أقدامي في طريق السلام، واحفظ بيتي في نورك. آمين.\"},{\"t\":\"من يسهر لا يكترث\",\"ref\":\"\",\"v\":\"\",\"r\":\"سمع الأب إسحق صوت طائر، فسأل الأب بيمن: هل يوجد مثل هذه الأصوات هنا؟ فأجابه: أمثالك يصغون إلى هذه الأصوات، لكن من يسهر لا يكترث لها. من ينشغل بالله لا تشغله الأصوات. في هذه الليالي، سلّم قلبك للصمت والترقب.\",\"p\":\"يا رب، اجعل قلبي ساهرًا فلا تشغله الأصوات. وانتظرك بقلب مستعد. آمين.\",\"fq\":390}]},\"12-24\":{\"th\":\"الرجاء المبارك\",\"m\":[{\"t\":\"لا تبطئ\",\"ref\":\"المزمور التاسع والستون — باكر\",\"v\":\"وأما أنا فمسكين وفقير اللهم أعنى. أنت معيني ومخلصي يا رب فلا تبطئ.\",\"r\":\"أنا مسكين وفقير، اللهم أعني. أنت معيني ومخلصي يا رب فلا تبطئ. هو صراخ منتظر ينتظر مجيء المسيح. الليلة تنتظر الكنيسة الميلاد. قل اليوم من قلبك: تعال يا رب يسوع.\",\"p\":\"يا رب يسوع، أنا مسكين وفقير. تعال وأعنّي ولا تبطئ. آمين.\"},{\"t\":\"منتظرين الرجاء المبارك\",\"ref\":\"تيطس ٢: ١٣\",\"bk\":\"تيطس\",\"v\":\"منتظرين الرجاء المبارك وظهور مجد الله العظيم ومخلصنا يسوع المسيح،\",\"r\":\"«منتظرين الرجاء المبارك وظهور مجد الله العظيم ومخلصنا يسوع المسيح». أعيش بين ميلاد مضى ومجيء قادم. الأول يعطيني اطمئنانًا لأن الله اقترب، والثاني يعطيني رجاءً لأن العدل قادم. أنتظر اليوم برجاء هادئ وأعمل بأمانة.\",\"p\":\"يا ربي يسوع، يا رجائي المبارك، أنتظر ظهور مجدك. ثبّتني في الإيمان والعمل الصالح، وأعطني فرحًا ورجاء في كل أيامي. آمين.\"},{\"t\":\"أخاف ثلاثة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيليا: أخاف ثلاثة: عندما توشك نفسي أن تفارق جسدي، وعندما انتصب أمام الله، وعندما يصدر الحكم بحقي. الذي يخاف من مجيء الديان يستعد لمجيء المخلص. وفي الليلة الأخيرة قبل العيد، اعترف بخطيتك واستقبل الطفل.\",\"p\":\"يا رب، علّمني مخافتك ورجائي فيك. واجعلني مستعدًا للقائك. آمين.\",\"fq\":127}]},\"12-25\":{\"th\":\"إلى هنا أعاننا الرب\",\"m\":[{\"t\":\"لأنك احتضنتني\",\"ref\":\"المزمور ٢٩ (٣٠) — الثالثة\",\"v\":\"أعظمك يا رب لأنك احتضنتني، ولم تشمت بي أعدائي.\",\"r\":\"أعظمك يا رب لأنك احتضنتني ولم تشمت بي أعدائي. اليوم احتضن الله البشرية في طفل. لم يبق بينه وبيننا بعد. كل عام وأنت بخير، وهذا هو العيد الحقيقي: أن تحتضنك يد الله. احتضن اليوم من أهملته.\",\"p\":\"يا رب، أعظمك لأنك احتضنتني بتجسدك. وأعطني أن أحتضن غيري بمحبتك. آمين.\"},{\"t\":\"حجر المعونة\",\"ref\":\"صموئيل الأول ٧: ١٢\",\"bk\":\"صموئيل الأول\",\"v\":\"فأخذ صموئيل حجرا ونصبه بين المصفاة والسن، ودعا اسمه «حجر المعونة» وقال: «إلى هنا أعاننا الرب».\",\"r\":\"«فأخذ صموئيل حجرًا ونصبه... ودعا اسمه حجر المعونة وقال: إلى هنا أعاننا الرب». في أواخر السنة أقيم في قلبي حجر معونة. أتذكر المرات التي حملني فيها الله، ولو لم أنتبه إليها وقتها. من يتذكر المعونة السابقة يثق في المعونة القادمة.\",\"p\":\"يا رب، إلى هنا أعنتني. أشكرك على كل معونة عرفتها وكل معونة لم أنتبه لها. ثبّت إيماني بك للأيام القادمة، واحفظني من الجحود. آمين.\"},{\"t\":\"لما كنت في الإسقيط\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب يوحنا الخصي للأب ثيوذورس الفرمي لما زاره: لما كنت في الإسقيط كانت أمور النفس شغلنا الأول وعمل اليد ثانيًا، أما الآن فقد صارت أمور النفس ثانوية وعمل اليد هو الأساس. في العيد، لا تجعل مشاغل العيد تسبق أمور نفسك. رتب اليوم ما هو أول.\",\"p\":\"يا رب، رتّب أولوياتي. واجعل شؤون نفسي أولًا ولو في زحمة العيد. آمين.\",\"fq\":135}]},\"12-26\":{\"th\":\"العطية التي لا يعبر عنها\",\"m\":[{\"t\":\"للرب الخلاص\",\"ref\":\"المزمور الثالث — باكر\",\"v\":\"للرب الخلاص وعلى شعبه بركته.\",\"r\":\"للرب الخلاص وعلى شعبه بركته. الخلاص عطية لا ثمن لها: هو الله نفسه بيننا. لا نقتنيه بجهدنا. تلقَّ اليوم هذه العطية بفم مفتوح، وقل شكرًا لمن لا يطلب مقابلًا.\",\"p\":\"يا رب، لك الخلاص وعلى شعبك بركتك. أشكرك على عطيتك التي لا يعبر عنها. آمين.\"},{\"t\":\"عطية لا يعبر عنها\",\"ref\":\"كورنثوس الثانية ٩: ١٥\",\"bk\":\"كورنثوس الثانية\",\"v\":\"فشكرا لله على عطيته التي لا يعبر عنها.\",\"r\":\"«فشكرًا لله على عطيته التي لا يعبر عنها». ليس بوسعي أن أصف قيمة هذه العطية، لكني أقدر أن أشكر. الله أعطاني نفسه في ابنه. وفي ذكرى الميلاد أتعلم أن أفتح يدي لأتقبل بامتنان، ثم أعطي بدوري بسخاء.\",\"p\":\"أشكرك يا أبانا السماوي على عطيتك التي لا يعبر عنها. ابنك الوحيد صار لي مخلصًا ومعينًا. اجعلني معطيًا بسخاء كما أعطيتني. آمين.\"},{\"t\":\"كن عديم الهم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيسوى: ازدر بنفسك واجعل مشيئتك وراءك وكن عديم الهمّ، فتجد راحة. الراحة التي يعطيها الله تأتي حين نتخلى عن مشيئتنا. سلّم اليوم همًّا واحدًا ولا تأخذه معك.\",\"p\":\"يا رب، علّمني أن أضع مشيئتي وراءي. وارفع عني الهموم لتعطيني راحتك. آمين.\",\"fq\":506}]},\"12-27\":{\"th\":\"عمق الغنى الإلهي\",\"m\":[{\"t\":\"عظمت رحمتك\",\"ref\":\"المزمور ٥٦ (٥٧) — السادسة\",\"v\":\"لأن رحمتك قد عظمت إلى السموات. وإلى السحاب عدلك.\",\"r\":\"عظمت رحمتك إلى السموات، وعدلك إلى السحاب. من يقيس غنى حكمة الله؟ إن كنا نحيا في ضيق، فرحمته لا تقاس. أحصِ اليوم ثلاث رحمات صغيرة في يومك، وقل: لك المجد.\",\"p\":\"يا رب، عظمت رحمتك إلى السموات. أشكرك على غنى نعمتك. آمين.\"},{\"t\":\"يا لعمق غنى الله\",\"ref\":\"رومية ١١: ٣٣\",\"bk\":\"رومية\",\"v\":\"يا لعمق غنى الله وحكمته وعلمه! ما أبعد أحكامه عن الفحص وطرقه عن الاستقصاء!\",\"r\":\"«يا لعمق غنى الله وحكمته وعلمه! ما أبعد أحكامه عن الفحص وطرقه عن الاستقصاء!». كثيرًا ما أحاول فهم كل شيء، والله أكبر من إدراكي. في هذا الاعتراف راحة: لا أحتاج أن أفهم كل التدبير لأثق في الله، فيكفيني أن أسجد وأسبح.\",\"p\":\"يا لعمق غناك وحكمتك وعلمك يا رب. أسجد لك أمام ما لا أفهمه، وأثق في تدبيرك الصالح. علّمني التسبيح عند حدود عقلي. آمين.\"},{\"t\":\"كالغنى والفقر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب مكاريوس المصري: لن تموت إذا صار عندك الهزء كالمديح والفقر كالغنى والحرمان كالقنية. من يؤمن جيدًا ويسلك بتقوى لا يسقط في خديعة الشياطين. اطلب اليوم سلامًا لا يتغير مع ما عندك أو ما ينقصك.\",\"p\":\"يا رب، أعطني قلبًا متحررًا من الغنى والفقر. وليكن كنزي فيك. آمين.\",\"fq\":240}]},\"12-28\":{\"th\":\"الإله الأزلي\",\"m\":[{\"t\":\"كرسيك ثابت منذ الأزل\",\"ref\":\"المزمور ٩٢ (٩٣) — السادسة\",\"v\":\"كرسيك ثابت منذ البدء، وأنت هو منذ الأزل.\",\"r\":\"كرسيك ثابت منذ البدء، وأنت هو منذ الأزل. في عالم متغير يمنحنا الله ثباتًا. كل ما نتعلق به يزول، وهو وحده يبقى. ضع قرارك اليوم على ما يثبت: وصية أو عادة صلاة.\",\"p\":\"يا رب، أنت هو منذ الأزل. ثبّتني على كرسيك ولا أتزعزع. آمين.\"},{\"t\":\"ملجأ في دور فدور\",\"ref\":\"المزامير ٩٠: ١–٢\",\"bk\":\"المزامير\",\"v\":\"يا رب، ملجأ كنت لنا في دور فدور. من قبل أن تولد الجبال، أو أبدأت الأرض والمسكونة، منذ الأزل إلى الأبد أنت الله.\",\"r\":\"«يا رب، ملجأ كنت لنا في دور فدور». الأجيال تمضي والله ثابت. حين أشعر بعدم الاستقرار أتذكر أن بيتي الحقيقي ليس مكانًا بل شخصًا. أنهي السنة في ملجأ لا يتغير، وأسلم له ما مضى وما سيأتي.\",\"p\":\"يا رب، أنت ملجأ لنا في دور فدور. من قبل الجبال أنت الله. ثبتني في ملجأك الأمين، واحفظ أيامي في يدك. آمين.\"},{\"t\":\"الفضائل خالدة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس: أكرم الفضائل ولا تهتم باللذات، لأن الفضائل خالدة، أما الملذات فتزول بسهولة. ما نعمله لله يبقى، وما نركض خلفه من متع يذهب. اختر اليوم فضيلة تبقى وتخلد معك.\",\"p\":\"يا رب، أعطني أن أكرم الفضائل. واجعلني أستثمر في ما يبقى للأبد. آمين.\",\"fq\":173}]},\"12-29\":{\"th\":\"الحفظ والشهادة\",\"m\":[{\"t\":\"عيناه على الصديقين\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"فإن عيني الرب على الصديقين، وأذنيه مصغيتان إلى طلبتهم.\",\"r\":\"عيني الرب على الصديقين وأذناه مصغيتان إلى طلبتهم. الله الذي يرى لا يغفل عنا. ننهي العام تحت نظره الأبوي وحفظه. تذكر اليوم موقفًا ظننت فيه أنك وحدك، وشاهد الله حاضرًا فيه.\",\"p\":\"يا رب، عيناك عليّ وأذناك مصغيتان إليّ. احفظني اليوم وفي كل أيام عمري. آمين.\"},{\"t\":\"يحفظ خروجك ودخولك\",\"ref\":\"المزامير ١٢١: ٧–٨\",\"bk\":\"المزامير\",\"v\":\"الرب يحفظك من كل شر. يحفظ نفسك. الرب يحفظ خروجك ودخولك من الآن وإلى الدهر.\",\"r\":\"«الرب يحفظ خروجك ودخولك من الآن وإلى الدهر». أخرج إلى عملي وأعود وأنا في حفظه، وأدخل السنة الجديدة وأخرج منها وهو معي. لا أعرف ما ينتظرني، لكني أعرف من يحفظني. هذا يكفي ليهدأ قلبي.\",\"p\":\"يا رب، أنت حارسي لا تنعس ولا تنام. احفظ خروجي ودخولي، وأسرتي وأحبائي، واحفظنا من كل شر في العام القادم. آمين.\"},{\"t\":\"عمل الله أولًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"سألوا الأب يوحنا الخصي: كيف استطعتم أن تعملوا إرادة الله براحة، بينما نحن بالجهد نفعل ذلك؟ فأجاب: اهتمامنا الأساسي هو عمل الله، وللحاجة الجسدية نعير انتباهًا قليلًا، أما أنتم فتعطون الحاجة الجسدية الاهتمام الأول فتتعبون. قدّم الله اليوم في قائمة أولوياتك.\",\"p\":\"يا رب، اجعل عملك أول اهتمامي. وأرحني من تعب الأولويات الخاطئة. آمين.\",\"fq\":192}]},\"12-30\":{\"th\":\"كل شيء جديدًا\",\"m\":[{\"t\":\"رفعت نفسي إليك\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"إليك يا رب رفعت نفسي.\",\"r\":\"إليك يا رب رفعت نفسي. والرب يقول: هأنذا أصنع كل شيء جديدًا. ننظر إلى العام القادم بقلب مرفوع إلى الله. ما الذي تريد أن يجدده الله فيك؟ ارفعه إليه اليوم بصلاة صريحة.\",\"p\":\"يا رب، إليك أرفع نفسي. اصنع في حياتي كل شيء جديدًا. آمين.\"},{\"t\":\"بخار يظهر قليلًا\",\"ref\":\"يعقوب ٤: ١٤–١٥\",\"bk\":\"يعقوب\",\"v\":\"أنتم الذين لا تعرفون أمر الغد! لأنه ما هي حياتكم؟ إنها بخار، يظهر قليلا ثم يضمحل. عوض أن تقولوا: «إن شاء الرب وعشنا نفعل هذا أو ذاك».\",\"r\":\"«ما هي حياتكم؟ إنها بخار يظهر قليلًا ثم يضمحل». في آخر العام أشعر بسرعة مرور الأيام. لا أقول هذا لأخاف، بل لأستيقظ. أضع خططي لسنة جديدة بتواضع، وأقول من القلب: «إن شاء الرب وعشنا»، فكل ما عندي هبة منه.\",\"p\":\"يا رب، علمني أن أحسب أيامي بحكمة. أسلم لك خططي للعام القادم، وليكن ما تشاء. اجعل عمري كله لمجدك. آمين.\"},{\"t\":\"السماء الجديدة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: إذا استطاع الإنسان أن يبني سماء جديدة وأرضًا جديدة، لا يمكنه أن يكون بدون همّ. حتى أعظم الإنجازات لا تعطي راحة كاملة، فالراحة الحقيقية في الله. كلما انشغلت بالتخطيط للعام الجديد، سلّم همّه لمن يصنع كل شيء جديدًا.\",\"p\":\"يا رب، علّمني أن أطلب راحتي فيك. واصنع فيّ سماءً جديدة وأرضًا جديدة. آمين.\",\"fq\":346}]},\"12-31\":{\"th\":\"ختام السنة وشكر\",\"m\":[{\"t\":\"اشكروا الرب\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"اشكروا الرب فإنه صالح وأن إلى الأبد رحمته هلليلويا\",\"r\":\"اشكروا الرب فإنه صالح وأن إلى الأبد رحمته. في آخر يوم من السنة نتوقف لنشكر. تذكر هذا العام: صعوباته وأفراحه. كتب الله في كل منها اسمه. اقض اليوم دقائق في الشكر على ما مضى بلا مقارنة ولا ندم.\",\"p\":\"يا رب، أشكرك على كل يوم من هذا العام. فإنك صالح وإلى الأبد رحمتك. آمين.\"},{\"t\":\"القادر أن يحفظكم\",\"ref\":\"يهوذا ١: ٢٤–٢٥\",\"bk\":\"يهوذا\",\"v\":\"والقادر أن يحفظكم غير عاثرين، ويوقفكم أمام مجده بلا عيب في الابتهاج، الإله الحكيم الوحيد مخلصنا، له المجد والعظمة والقدرة والسلطان، الآن وإلى كل الدهور. آمين.\",\"r\":\"«والقادر أن يحفظكم غير عاثرين، ويوقفكم أمام مجده بلا عيب في الابتهاج». أختم السنة بتسبحة الثقة هذه. لست قادرًا على حفظ نفسي، لكن القادر يحفظني. أسلم له الأيام القادمة، وأعبده بقلب شاكر، وأضع المجد كله له الآن وإلى كل الدهور.\",\"p\":\"للقادر أن يحفظنا غير عاثرين، الإله الحكيم الوحيد مخلصنا، له المجد والعظمة والقدرة والسلطان، الآن وإلى كل الدهور. احفظنا في السنة الجديدة بنعمتك. آمين.\"},{\"t\":\"الرب معهم\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل الأب نيسثروس الأب أنطونيوس: ما هو العمل الصالح حتى أعمله؟ فأجاب: أليست كل الأعمال متساوية؟ إبراهيم كان مضيفًا والرب معه، وإيليا أحب السكينة والرب معه، وداود كان متواضعًا والرب معه. ما تريده نفسك وفقًا لمشيئة الله اعمله. في العام الجديد، اختر ما يرضي الله واثبت فيه.\",\"p\":\"يا رب، كن معي في كل عمل. وأعطني أن أنهي هذا العام وأبدأ العام الجديد بمشيئتك. آمين.\",\"fq\":298}]}}}";